def _uri_for_log(uri: str) -> str:
    """Return a safe URI string for logging (no credentials)."""
    if not uri or not isinstance(uri, str):
        return "<default>"
    u = (uri or "").strip()
    if not u:
        return "<default>"
    # Already safe if no @; otherwise show only host part
    if "@" in u:
        try:
            after = u.split("@", 1)[1]
            return f"...@{after}" if len(after) < 80 else f"...@{after[:76]}..."
        except Exception:
            return "***"
    return u if len(u) <= 80 else u[:76] + "..."


DEFAULT_NEO4J_URI = "bolt://localhost:7687"
DEFAULT_NEO4J_USER = "neo4j"
DEFAULT_NEO4J_PASSWORD = "intellistock"


def _resolve_neo4j_runtime_config(config: dict | None = None) -> tuple[str, str, str]:
    cfg = config or {}
    uri = str(cfg.get("neo4j_uri") or "").strip() or str(os.environ.get("NEO4J_URI") or "").strip() or DEFAULT_NEO4J_URI
    user = str(cfg.get("neo4j_user") or "").strip() or str(os.environ.get("NEO4J_USER") or "").strip() or DEFAULT_NEO4J_USER
    password = str(cfg.get("neo4j_password") or "").strip() or str(os.environ.get("NEO4J_PASSWORD") or "").strip() or DEFAULT_NEO4J_PASSWORD
    return uri, user, password


def _format_stage_elapsed(seconds: float) -> str:
    if seconds < 1.0:
        return f"{seconds * 1000:.0f}ms"
    return f"{seconds:.2f}s"


def _log_stage_progress(
    label: str,
    completed: int,
    total: int,
    *,
    started: float,
    last_state: dict[str, Any] | None = None,
    every_items: int = 5,
    every_seconds: float = 5.0,
    extra: str = "",
    color: str = "cyan",
    force: bool = False,
) -> None:
    if total <= 0:
        return
    now = perf_counter()
    state = last_state if last_state is not None else {}
    last_count = int(state.get("count", 0) or 0)
    last_time = float(state.get("time", 0.0) or 0.0)
    should_log = force or completed >= total
    if not should_log and completed > 0 and completed == 1:
        should_log = True
    if not should_log and every_items > 0 and completed - last_count >= every_items:
        should_log = True
    if not should_log and last_time > 0 and every_seconds > 0 and now - last_time >= every_seconds:
        should_log = True
    if not should_log:
        return
    pct = (completed / total) * 100.0
    suffix = f" | {extra}" if extra else ""
    _log(
        f"{label}: progress {completed}/{total} ({pct:.0f}%) in {_format_stage_elapsed(now - started)}{suffix}",
        color,
    )
    state["count"] = completed
    state["time"] = now


def _log_lookback_banner(title: str, *, date_key: str = "", lookback_days: int = 0, end: bool = False) -> None:
    line = "=" * 28
    suffix = f" | date={date_key} | lookback_days={lookback_days}" if date_key or lookback_days else ""
    label = f"{title} END" if end else title
    _log(line, "cyan")
    _log(f"{label}{suffix}", "cyan")
    _log(line, "cyan")


@contextmanager
def _timed_stage(label: str, *, start_details: str = "", start_color: str = "cyan", done_color: str = "cyan"):
    detail_suffix = f" | {start_details}" if start_details else ""
    _log(f"{label}: start{detail_suffix}", start_color)
    started = perf_counter()
    try:
        yield
    except Exception as exc:
        _log(f"{label}: failed after {_format_stage_elapsed(perf_counter() - started)} | {exc}", "yellow")
        raise
    _log(f"{label}: done in {_format_stage_elapsed(perf_counter() - started)}", done_color)


