def _ensure_nexus_history_table(
    conn,
    table_name: str,
    *,
    indexes: tuple[str, ...] = (),
) -> None:
    """Ensure the table exists AND each named simple-field index is built.

    ``indexes`` lets writers declare which secondary indexes the table
    needs. The first call per (table, index) pair triggers
    ``index_create`` + ``index_wait`` — on a heavy existing table this
    can take a few minutes, but it runs at most once per process and
    every subsequent startup pays nothing. Without the index, the
    instance-scoped ``filter()`` queries the broker runs at lookback
    prep time degrade to multi-minute full-table scans
    (backtest 953929 stalled ~4 min on this exact query)."""
    if conn is None or not table_name:
        return
    needs_index_check = bool(indexes) and not all(
        f"{table_name}::{idx}" in _nexus_history_tables_ensured for idx in indexes
    )
    if table_name in _nexus_history_tables_ensured and not needs_index_check:
        return
    try:
        dbs = list(_r.db_list().run(conn))
        if DB_NAME not in dbs:
            _r.db_create(DB_NAME).run(conn)
        tables = list(_r.db(DB_NAME).table_list().run(conn))
        if table_name not in tables:
            _r.db(DB_NAME).table_create(table_name).run(conn)
        _nexus_history_tables_ensured.add(table_name)
        if indexes:
            existing = set(
                _r.db(DB_NAME).table(table_name).index_list().run(conn)
            )
            for idx in indexes:
                marker = f"{table_name}::{idx}"
                if idx in existing:
                    _nexus_history_tables_ensured.add(marker)
                    continue
                _log(
                    f"Creating index '{idx}' on {table_name} "
                    f"(one-time; may take a few minutes on first run)...",
                    "cyan",
                )
                _t0 = perf_counter()
                _r.db(DB_NAME).table(table_name).index_create(idx).run(conn)
                _r.db(DB_NAME).table(table_name).index_wait(idx).run(conn)
                _log(
                    f"Index '{idx}' on {table_name} ready in "
                    f"{perf_counter() - _t0:.1f}s",
                    "cyan",
                )
                _nexus_history_tables_ensured.add(marker)
    except Exception as exc:
        _log(f"Could not ensure table {table_name}: {exc}", "yellow")


# Sweep-3: persistent rotation eviction cooldown (survives stop+resume)
NEXUS_ROTATION_COOLDOWN_TABLE = "GraphNexusRotationCooldown"

# Sweep-3: schema validation for action_intent persistence.
# Any persisted action_intent MUST be in this set, otherwise it's coerced to "unknown".
# This catches typos at persistence time and gives a clean enumeration for downstream consumers.
_VALID_ACTION_INTENTS = frozenset({
    "hold", "buy", "sell",
    # Baseline intents emitted by _infer_action_intent (score>0/<0). These were
    # missing here, so every vanilla buy/sell candidate persisted as "unknown"
    # (870/877 rows on backtest 586767). "sell_override" is also the exact value
    # _update_indefinite_outcomes keys the sell-return sign off of.
    "initial_buy", "add_buy", "sell_override",
    "winner_add_buy", "momentum_amplifier_buy",
    "backfill_queue_buy", "backfill_rotation_buy",
    "direct_reserved_buy", "top_momentum_break_glass_buy",
    "rotation_buy", "rotation_sell",
    "trend_reversal_sell", "fast_loser_cut", "trailing_stop_sell",
    "circuit_breaker_sell", "hold_limit_sell", "deep_loser_protect",
    "forced_exit", "downtrend_protection_sell",
    "consecutive_neutral_pruning", "blocked_priority_buy",
    "panel_buy", "panel_sell",
    "etf_buy", "etf_sell",
})


def _normalize_action_intent(intent: str | None) -> str:
    """Coerce action_intent to a valid enum value. Unknown values become 'unknown'
    so persistence schema stays bounded — caller can grep for 'unknown' to find typos."""
    _norm = str(intent or "hold").strip().lower()
    if _norm in _VALID_ACTION_INTENTS:
        return _norm
    return "unknown"


_NON_EXECUTED_INTENTS = frozenset({
    # Valid context intents that describe a BLOCKED signal — no trade
    # occurred, so no directional forward-outcome row may exist (audit
    # 2026-07-18: these silently biased the hit-rate denominator).
    "blocked_priority_buy",
})


def _outcome_row_allowed(action_intent: str) -> bool:
    """Task 8 (benchmark-alpha E04): only a real directional prediction may
    create a forward-outcome row. 'unknown' is a schema error (context row
    only); 'hold' and blocked/queued states are not directional outcomes."""
    intent = str(action_intent or "").strip().lower()
    return (intent in _VALID_ACTION_INTENTS and intent != "hold"
            and intent not in _NON_EXECUTED_INTENTS)


def _load_evict_cooldown_from_db(conn, instance_id: str) -> dict:
    """Load persisted rotation eviction cooldown for this instance."""
    if conn is None or _r is None or not instance_id:
        return {}
    try:
        _ensure_nexus_history_table(conn, NEXUS_ROTATION_COOLDOWN_TABLE)
        doc = _r.db(DB_NAME).table(NEXUS_ROTATION_COOLDOWN_TABLE).get(instance_id).run(conn)
        if isinstance(doc, dict) and isinstance(doc.get("cooldown"), dict):
            return {str(k): int(v) for k, v in doc["cooldown"].items() if int(v or 0) > 0}
    except Exception:
        pass
    return {}


def _save_evict_cooldown_to_db(conn, instance_id: str, cooldown: dict) -> None:
    """Persist rotation eviction cooldown to RethinkDB (fire-and-forget)."""
    if conn is None or _r is None or not instance_id:
        return
    try:
        _ensure_nexus_history_table(conn, NEXUS_ROTATION_COOLDOWN_TABLE)
        _r.db(DB_NAME).table(NEXUS_ROTATION_COOLDOWN_TABLE).insert({
            "id": instance_id,
            "cooldown": {str(k): int(v) for k, v in (cooldown or {}).items() if int(v or 0) > 0},
        }, conflict="replace").run(conn, noreply=True)
    except Exception:
        pass


