_GN_LIVE_MODE_FLAG: bool = False  # Module-level live-mode flag set by run_once; gates wall-clock budgets in utility fns
_neo4j_market_cap_cache: dict[str, float] = {}
_active_point_in_time_graph_scope = None


def _pit_is_research(context) -> bool:
    """True for a DECLARED research context (non-live and non-strict).

    Such a context can only be built by the broker's pit_mode="research"
    branch, and run_once still requires the config to declare it, so this is a
    label check rather than a second door. Every strict consumer below treats a
    research context exactly like the legacy/live path: it reads current state.
    The context stays stamped legacy_unverified so nothing downstream can
    mistake what it saw for verified point-in-time evidence.
    """
    if context is None:
        return False
    return bool(getattr(context, "is_research", False))


def _pit_use_legacy_sources(context) -> bool:
    """True when a consumer should read current state instead of a snapshot."""
    if context is None:
        return True
    return bool(getattr(context, "uses_live_sources", False))


def _overlay_llm_key_available(config) -> bool:
    """True when the overlay role can actually reach a provider.

    Mirrors how the other LLM roles gate themselves. Without this the overlay
    dispatches work that cannot succeed and burns its full retry budget per
    candidate per cycle.
    """
    cfg = config if isinstance(config, dict) else {}
    for key in ("overlay_llm_api_key", "llm_api_key"):
        if str(cfg.get(key) or "").strip():
            return True
    for env in ("OPENROUTER_API_KEY", "OPENAI_API_KEY", "GEMINI_API_KEY",
                "ANTHROPIC_API_KEY", "AZURE_OPENAI_API_KEY", "LLM_API_KEY"):
        if str(os.environ.get(env) or "").strip():
            return True
    return False


def _llm_call_window(per_call_sec, slack: int = 30) -> float:
    """How long ONE LLM call may go without completing before the pool treats
    it as stalled. Per CALL, not per batch: a large healthy batch must never be
    cut off just for being large. The window restarts on every completion."""
    try:
        base = float(per_call_sec or 0) or 180.0
    except (TypeError, ValueError):
        base = 180.0
    return base + slack


def _llm_pool_ceiling(per_call_sec, n_items: int, slack: int = 60) -> float:
    """Absolute ceiling for a pool, for the pathological case where calls
    trickle in just fast enough to keep resetting the per-call window."""
    try:
        base = float(per_call_sec or 0) or 180.0
    except (TypeError, ValueError):
        base = 180.0
    return base * max(1, int(n_items or 1)) + slack


def _activate_point_in_time_graph_scope(
    context,
    *,
    strategy_cache: dict | None,
    config: dict | None,
) -> None:
    """Namespace graph-derived caches by immutable manifest and decision time."""
    global _active_point_in_time_graph_scope
    global _momentum_neighbor_cache
    global _neo4j_etf_cache
    global _neo4j_stock_sector_cache
    global _neo4j_market_cap_cache

    requested_scope = None
    if not _pit_use_legacy_sources(context):
        requested_scope = context.cache_key("nexus-graph")

    global_scope_changed = requested_scope != _active_point_in_time_graph_scope
    if global_scope_changed:
        _momentum_neighbor_cache = {}
        _PRIVATE_ENTITY_ALIAS_QUERY_CACHE.clear()
        _PRIVATE_ENTITY_ALIAS_QUERY_CACHE_ORDER.clear()
        _neo4j_etf_cache = None
        _neo4j_stock_sector_cache = None
        _neo4j_market_cap_cache = {}
        _active_point_in_time_graph_scope = requested_scope

    local_scope_changed = False
    if isinstance(strategy_cache, dict):
        scope_key = "_nexus_graph_pit_scope"
        local_scope_changed = strategy_cache.get(scope_key) != requested_scope
        if local_scope_changed:
            strategy_cache.pop("_neo4j_snapshot", None)
            strategy_cache.pop("_neo4j_snapshot_stats", None)
            strategy_cache.pop("_inst_co_holdings_cache", None)
            if requested_scope is None:
                strategy_cache.pop(scope_key, None)
            else:
                strategy_cache[scope_key] = requested_scope
    if (global_scope_changed or local_scope_changed) and isinstance(config, dict):
        config.pop("_inst_co_holdings_cache", None)


def _load_neo4j_market_cap_cache(driver) -> None:
    """Load yf_market_cap from Neo4j Company nodes (set by graph engine Phase 1b).

    Phase δ observability sweep (2026-05-18, BT232179 follow-up): the prior
    `if _neo4j_market_cap_cache: _log(...)` gate + `except Exception: pass`
    silent-swallow combo could hide BOTH the Neo4j-empty case AND the
    Neo4j-driver-error case. BT232179 showed mcap pre-seed running with an
    empty Neo4j cache; this function's silent failure modes are an upstream
    contributor. Always log the outcome (populated count OR error) so
    operators can correlate downstream A1 misses with the load-time state.
    """
    global _neo4j_market_cap_cache
    if _neo4j_market_cap_cache:
        # Already populated this session — nothing to do.
        return
    if driver is None:
        _log(
            "Neo4j market_cap cache: skipped — no Neo4j driver "
            "(graph engine Phase 1b may not have initialized)",
            "yellow",
        )
        return
    try:
        with driver.session() as session:
            result = session.run(
                "MATCH (c:Company) WHERE c.yf_market_cap IS NOT NULL AND c.yf_market_cap > 0 "
                "RETURN c.ticker AS ticker, c.yf_market_cap AS mc ORDER BY ticker LIMIT 15000"
            )
            for rec in result:
                t = str(rec.get("ticker") or "").strip().upper()
                mc = float(rec.get("mc") or 0)
                if t and mc > 0:
                    _neo4j_market_cap_cache[t] = mc
        _n_loaded = len(_neo4j_market_cap_cache)
        if _n_loaded > 0:
            _log(
                f"Neo4j market_cap cache loaded: {_n_loaded} companies",
                "green",
            )
        else:
            # Phase δ: SURFACE the empty-load case. Prior silent-fail
            # mode left operators chasing "A1 returns LOW for everything"
            # downstream without any audit trail of WHY the mcap cache
            # was empty.
            _log(
                "Neo4j market_cap cache: 0 companies loaded — A1 mega-cap "
                "tier resolution will fall back to raw_score for ALL "
                "symbols (BT109429/BT232179 silent-fail mode). Verify "
                "graph engine Phase 1b ingestion (yf_market_cap property "
                "on Company nodes).",
                "red",
            )
    except Exception as _mc_exc:
        # Phase δ: SURFACE the exception. Prior `pass` swallowed driver
        # connection errors, schema mismatches, etc. — leaving downstream
        # callers to debug "A1 silently LOW" with no upstream signal.
        _log(
            f"Neo4j market_cap cache: load failed ({_mc_exc!r}) — A1 mcap "
            f"path will be inert for this run. Phase 1b may not have run "
            f"yet, or the Neo4j driver is misconfigured.",
            "red",
        )


# V16: Removed duplicate _load_neo4j_market_cap_cache definition and duplicate _neo4j_market_cap_cache declaration


def _load_neo4j_etf_mappings(driver, force_refresh: bool = False) -> dict[str, list[str]]:
    """
    Query Neo4j for ETF → sector/theme mappings. Returns a dict of
    keyword (lowered sector/theme name) → list of ETF tickers, sorted
    by number of matching relationships (most connected first).
    """
    global _neo4j_etf_cache
    if _neo4j_etf_cache is not None and not force_refresh:
        return _neo4j_etf_cache
    if driver is None:
        return {}
    mapping: dict[str, list[tuple[str, int]]] = {}
    try:
        with driver.session() as session:
            # ETF_TRACKS_SECTOR: ETF → Sector
            result = session.run(
                "MATCH (e:ETF)-[r:ETF_TRACKS_SECTOR]->(s:Sector) "
                "WHERE r.edge_state = 'open' "
                "RETURN e.ticker AS ticker, toLower(s.name) AS keyword"
            )
            for rec in result:
                ticker = str(rec.get("ticker") or "").strip().upper()
                kw = str(rec.get("keyword") or "").strip().lower()
                if ticker and kw:
                    mapping.setdefault(kw, []).append(ticker)
            # ETF_TRACKS_THEME: ETF → Theme
            result = session.run(
                "MATCH (e:ETF)-[r:ETF_TRACKS_THEME]->(t:Theme) "
                "WHERE r.edge_state = 'open' "
                "RETURN e.ticker AS ticker, toLower(t.name) AS keyword"
            )
            for rec in result:
                ticker = str(rec.get("ticker") or "").strip().upper()
                kw = str(rec.get("keyword") or "").strip().lower()
                if ticker and kw:
                    mapping.setdefault(kw, []).append(ticker)
            # Also index by ETF keywords property for broader matching
            result = session.run(
                "MATCH (e:ETF) "
                "WHERE e.keywords IS NOT NULL AND size(e.keywords) > 0 "
                "RETURN e.ticker AS ticker, e.keywords AS keywords"
            )
            for rec in result:
                ticker = str(rec.get("ticker") or "").strip().upper()
                keywords = rec.get("keywords") or []
                if ticker and keywords:
                    for kw in keywords:
                        kw_lower = str(kw).strip().lower()
                        if kw_lower:
                            mapping.setdefault(kw_lower, []).append(ticker)
        # Deduplicate and sort by frequency (most-referenced ETFs first)
        from collections import Counter as _Counter
        result_map: dict[str, list[str]] = {}
        for kw, tickers in mapping.items():
            counts = _Counter(tickers)
            result_map[kw] = [t for t, _ in counts.most_common()]
        _neo4j_etf_cache = result_map
        _ALL_ETF_TICKERS.update(t for tickers in result_map.values() for t in tickers)
        _log(f"Neo4j ETF mappings loaded: {len(result_map)} keywords, {len(set(t for v in result_map.values() for t in v))} unique ETFs", "cyan")
        return result_map
    except Exception as exc:
        _log(f"Neo4j ETF mapping load failed: {exc}", "yellow")
        return {}


def _load_neo4j_stock_sector_mappings(driver, force_refresh: bool = False) -> dict[str, list[str]]:
    """
    Query Neo4j for Company → sector/industry mappings.  Returns a dict of
    keyword (lowered sector or industry name) → list of stock tickers, sorted
    by number of matching relationships (most connected first).
    """
    global _neo4j_stock_sector_cache
    if _neo4j_stock_sector_cache is not None and not force_refresh:
        return _neo4j_stock_sector_cache
    if driver is None:
        return {}
    mapping: dict[str, list[str]] = {}
    try:
        with driver.session() as session:
            # Source 1: Company → Sector via IN_SECTOR relationship
            result = session.run(
                "MATCH (c:Company)-[r:IN_SECTOR]->(s:Sector) "
                "WHERE r.edge_state = 'open' AND c.ticker IS NOT NULL "
                "RETURN c.ticker AS ticker, toLower(s.name) AS keyword"
            )
            for rec in result:
                ticker = str(rec.get("ticker") or "").strip().upper()
                kw = str(rec.get("keyword") or "").strip().lower()
                if ticker and kw:
                    mapping.setdefault(kw, []).append(ticker)
            # Source 2: Company.industry property (more granular than GICS sector)
            # e.g. "Semiconductors", "Semiconductor Equipment", "Oil & Gas E&P"
            result = session.run(
                "MATCH (c:Company) "
                "WHERE c.industry IS NOT NULL AND c.ticker IS NOT NULL "
                "RETURN c.ticker AS ticker, toLower(c.industry) AS keyword"
            )
            for rec in result:
                ticker = str(rec.get("ticker") or "").strip().upper()
                kw = str(rec.get("keyword") or "").strip().lower()
                if ticker and kw:
                    mapping.setdefault(kw, []).append(ticker)
        from collections import Counter as _Counter
        result_map: dict[str, list[str]] = {}
        for kw, tickers in mapping.items():
            counts = _Counter(tickers)
            result_map[kw] = [t for t, _ in counts.most_common()]
        _neo4j_stock_sector_cache = result_map
        _n_unique = len(set(t for v in result_map.values() for t in v))
        _log(f"Neo4j stock-sector mappings loaded: {len(result_map)} keywords, {_n_unique} unique stocks", "cyan")
        return result_map
    except Exception as exc:
        _log(f"Neo4j stock-sector mapping load failed: {exc}", "yellow")
        return {}


def _get_etfs_for_trend(trend: dict, max_etfs: int = 4) -> list[str]:
    """
    Return up to max_etfs ETF tickers matching the trend theme.
    Tries Neo4j dynamic mappings first, then falls back to hardcoded _TREND_ETF_MAP.
    """
    text = " " + " ".join(filter(None, [
        trend.get("name", ""),
        trend.get("description", ""),
        trend.get("sector", ""),
    ])).lower() + " "
    etf_scores: dict[str, int] = {}
    # Priority 1: Neo4j dynamic mappings (sector + theme + keywords)
    neo4j_map = _neo4j_etf_cache or {}
    for kw, etfs in neo4j_map.items():
        if kw in text:
            for etf in etfs:
                etf_scores[etf] = etf_scores.get(etf, 0) + 2  # higher weight for Neo4j
    # Priority 2: Hardcoded fallback (fills gaps if Neo4j has no match)
    for kw, etfs in _TREND_ETF_MAP.items():
        if kw in text:
            for etf in etfs:
                etf_scores[etf] = etf_scores.get(etf, 0) + 1
    ranked = sorted(etf_scores, key=lambda e: (-etf_scores[e], str(e)))
    return ranked[:max_etfs]


def _discover_trend_etfs(
    conn, active_trends: list[dict], instance_id: str,
    current_syms: set, config: dict, date_key: str,
) -> list[str]:
    """
    For bullish active trends above strength threshold, discover related ETFs.
    Stores them in GraphNexusDiscoveredStocks with source='trend_etf'.
    Returns list of newly added ETF tickers.
    """
    if conn is None or _r is None or not active_trends:
        return []
    _ensure_discovered_stocks_table(conn)
    min_strength = float(config.get("etf_min_trend_strength", 0.4))
    max_etfs_total = int(config.get("max_trend_etfs", 3))
    reuse_stamp = _nexus_reuse_stamp_from_config(config, instance_id)

    # Load existing active ETF discoveries to avoid duplicates
    try:
        cursor = _r.db(DB_NAME).table(DISCOVERED_TABLE).filter(
            lambda doc: (doc["instance_id"] == instance_id)
                & doc.has_fields("source")
                & (doc["source"] == "trend_etf")
                & (doc["status"] == "active")
        ).run(conn)
        existing_etf_ids = {doc["ticker"] for doc in cursor}
    except Exception:
        existing_etf_ids = set()

    # Aggregate ETFs across all qualifying bullish trends
    etf_trend_map: dict[str, list[str]] = {}
    for t in active_trends:
        if t.get("status") != "active":
            continue
        if (t.get("strength") or 0) < min_strength:
            continue
        if t.get("direction", "bullish") != "bullish":
            continue
        trend_id = t.get("id", "")
        for etf in _get_etfs_for_trend(t, max_etfs=4):
            etf_trend_map.setdefault(etf, []).append(trend_id)

    # Sort by number of supporting trends (most coverage first), then apply total cap
    sorted_etfs = sorted(etf_trend_map.items(), key=lambda x: len(x[1]), reverse=True)
    # Count existing active ETFs toward the total cap
    remaining_slots = max(0, max_etfs_total - len(existing_etf_ids))

    newly_discovered: list[str] = []
    for etf, source_ids in sorted_etfs:
        if len(newly_discovered) >= remaining_slots:
            break
        if etf in current_syms or etf in existing_etf_ids:
            continue
        doc_id = f"{instance_id}_etf_{etf}"
        doc = {
            "id": doc_id,
            "ticker": etf,
            "instance_id": instance_id,
            "discovered_date": date_key,
            "source_trend_ids": source_ids,
            "source": "trend_etf",
            "status": "active",
            "last_signal_date": date_key,
            "sell_reason": None,
        }
        doc.update(reuse_stamp)
        try:
            _r.db(DB_NAME).table(DISCOVERED_TABLE).insert(doc, conflict="replace").run(conn)
            newly_discovered.append(etf)
            _log(f"  Discovered trend ETF: {etf} (trends: {', '.join(source_ids[:3])})", "green")
        except Exception:
            pass
    return newly_discovered


def _get_all_active_trend_etfs(conn, instance_id: str) -> list[str]:
    """Return all active ETF tickers discovered from trends for this instance."""
    if conn is None or _r is None:
        return []
    _ensure_discovered_stocks_table(conn)
    try:
        cursor = _r.db(DB_NAME).table(DISCOVERED_TABLE).filter(
            lambda doc: (doc["instance_id"] == instance_id)
                & doc.has_fields("source")
                & (doc["source"] == "trend_etf")
                & (doc["status"] == "active")
        ).run(conn)
        return [doc["ticker"] for doc in cursor if doc.get("ticker")]
    except Exception:
        return []


def _get_stale_trend_etfs(conn, instance_id: str, all_trends: list[dict]) -> set[str]:
    """
    Return ETF tickers whose ALL source trends have ended or weakened (strength < 0.3).
    These ETFs should be sold.
    """
    if conn is None or _r is None:
        return set()
    _ensure_discovered_stocks_table(conn)
    try:
        cursor = _r.db(DB_NAME).table(DISCOVERED_TABLE).filter(
            lambda doc: (doc["instance_id"] == instance_id)
                & doc.has_fields("source")
                & (doc["source"] == "trend_etf")
                & (doc["status"] == "active")
        ).run(conn)
        etf_docs = list(cursor)
    except Exception:
        return set()
    if not etf_docs:
        return set()

    trend_state: dict[str, tuple[str, float]] = {
        t.get("id", ""): (t.get("status", "active"), float(t.get("strength") or 0))
        for t in all_trends if t.get("id")
    }

    stale: set[str] = set()
    for doc in etf_docs:
        source_ids = doc.get("source_trend_ids") or []
        if not source_ids:
            continue
        # Stale only when every source trend has ended or weakened past threshold
        if all(
            trend_state.get(tid, ("active", 1.0))[0] == "ended"
            or (
                trend_state.get(tid, ("active", 1.0))[0] == "weakening"
                and trend_state.get(tid, ("active", 1.0))[1] < 0.3
            )
            for tid in source_ids
        ):
            stale.add(doc["ticker"])
    return stale


def _mark_trend_etf_sold(conn, instance_id: str, etf: str, reason: str = ""):
    """Mark a trend ETF discovery as sold."""
    if conn is None or _r is None:
        return
    _ensure_discovered_stocks_table(conn)
    doc_id = f"{instance_id}_etf_{etf}"
    try:
        _r.db(DB_NAME).table(DISCOVERED_TABLE).get(doc_id).update({
            "status": "sold",
            "sell_reason": (reason or "Source trend ended")[:200],
        }).run(conn)
    except Exception:
        pass


def _ensure_ticker_history_table(conn):
    """Ensure GraphNexusTickerHistory table exists."""
    global _ticker_history_table_ensured
    if conn is None or _ticker_history_table_ensured:
        return
    try:
        tables = list(_r.db(DB_NAME).table_list().run(conn))
        if TICKER_HISTORY_TABLE not in tables:
            _r.db(DB_NAME).table_create(TICKER_HISTORY_TABLE).run(conn)
        _ticker_history_table_ensured = True
    except Exception as e:
        _log(f"Could not ensure ticker history table: {e}", "yellow")


def _update_ticker_history(conn, ticker_headlines: dict, date_key: str, max_age_days: int = 30):
    """
    Append today's headlines to per-ticker history and prune entries older than max_age_days.
    ticker_headlines: {ticker: [headline_str, ...]}
    """
    if conn is None or not ticker_headlines:
        return
    _ensure_ticker_history_table(conn)
    cutoff = (datetime.strptime(date_key, "%Y-%m-%d") - timedelta(days=max_age_days)).strftime("%Y-%m-%d")
    try:
        for ticker, headlines in ticker_headlines.items():
            if not headlines:
                continue
            new_entries = [{"d": date_key, "h": h[:200]} for h in headlines[:15]]  # cap per day
            doc = _r.db(DB_NAME).table(TICKER_HISTORY_TABLE).get(ticker).run(conn)
            if doc is None:
                _r.db(DB_NAME).table(TICKER_HISTORY_TABLE).insert({
                    "id": ticker,
                    "headlines": new_entries,
                    "last_updated": _r.now(),
                }).run(conn)
            else:
                existing = doc.get("headlines") or []
                # Deduplicate: skip if we already have entries for this date
                existing_dates = {e.get("d") for e in existing}
                if date_key not in existing_dates:
                    existing.extend(new_entries)
                # Prune old entries
                pruned = [e for e in existing if e.get("d", "") >= cutoff]
                _r.db(DB_NAME).table(TICKER_HISTORY_TABLE).get(ticker).update({
                    "headlines": pruned,
                    "last_updated": _r.now(),
                }).run(conn)
    except Exception as e:
        _log(f"Update ticker history error: {e}", "yellow")


def _get_ticker_history(conn, tickers: list, max_per_ticker: int = 10) -> dict:
    """
    Return recent headline history for requested tickers.
    Returns {ticker: [{d: "2026-02-20", h: "..."}, ...]} sorted newest first, capped.
    """
    if conn is None or not tickers:
        return {}
    _ensure_ticker_history_table(conn)
    result = {}
    try:
        for ticker in tickers[:20]:  # cap to avoid huge queries
            doc = _r.db(DB_NAME).table(TICKER_HISTORY_TABLE).get(ticker).run(conn)
            if doc and isinstance(doc.get("headlines"), list):
                headlines = sorted(doc["headlines"], key=lambda x: x.get("d", ""), reverse=True)
                result[ticker] = headlines[:max_per_ticker]
    except Exception as e:
        _log(f"Get ticker history error: {e}", "yellow")
    return result


def _extract_ticker_headlines(articles: list) -> dict:
    """
    From a list of Alpaca articles, extract per-ticker headline mapping.
    Returns {ticker: [headline_str, ...]}.
    """
    mapping: dict[str, list[str]] = {}
    for a in articles or []:
        h = (a.get("headline") or "").strip()
        if not h:
            continue
        for sym in (a.get("symbols") or []):
            if isinstance(sym, str) and len(sym) <= 10 and sym.isupper():
                mapping.setdefault(sym.strip(), []).append(h)
    return mapping


def _article_id_or_hash(article: dict) -> str:
    """Stable id for one article: id, url, or hash of title+url."""
    if not article or not isinstance(article, dict):
        return ""
    aid = article.get("id")
    if isinstance(aid, str) and aid.strip():
        return aid.strip()
    url = article.get("url")
    if isinstance(url, str) and url.strip():
        return url.strip()
    title = (article.get("title") or "").strip()
    url = (article.get("url") or "").strip()
    raw = f"{title}|{url}"
    return hashlib.sha256(raw.encode("utf-8", errors="replace")).hexdigest()[:32]


def _article_set_fingerprint(articles: list) -> str:
    """Stable hash for this exact set of articles. Same set => same fingerprint."""
    if not articles:
        return ""
    ids = sorted(_article_id_or_hash(a) for a in articles if _article_id_or_hash(a))
    if not ids:
        return ""
    payload = json.dumps(ids, sort_keys=True)
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()[:32]


def _article_available_at(article: dict):
    if not isinstance(article, dict):
        return None
    return (
        article.get("published_at")
        or article.get("created_at")
        or article.get("published_date")
    )


def _filter_articles_for_context(articles: list, context=None) -> list[dict]:
    if context is None:
        return list(articles or [])
    from point_in_time_data import filter_available

    return list(
        filter_available(
            articles or [],
            context=context,
            available_at=_article_available_at,
        )
    )


def _point_in_time_sentiment_scope_id(
    sentiment_cache_scope_id: str,
    context=None,
) -> str:
    base_scope = str(sentiment_cache_scope_id or "").strip()
    if context is None:
        return base_scope
    key = context.cache_key("nexus-news-sentiment", base_scope)
    return (
        f"{key[0]}|manifest={key[1]}|as_of={key[2]}|"
        f"scope={key[3]}"
    )


def _get_cached_articles(
    conn,
    date_key: str,
    *,
    sentiment_cache_scope_id: str = "",
    context=None,
    config: dict | None = None,
):
    """
    Return (articles, cached_sentiment) for date_key (YYYY-MM-DD).
    Sentiment is keyed by article-set fingerprint: only returned if the cached
    articles match the same set (same ids/urls). Otherwise None so LLM is called.
    articles: list or None on miss/invalid.
    cached_sentiment: dict[ticker -> {sentiment, event}] or None if not cached for this set.
    """
    from _phase_alpha_helpers import evidence_cache_read_allowed
    if not evidence_cache_read_allowed("sentiment"):
        return None, None
    if conn is None:
        return None, None
    try:
        doc = _r.db(DB_NAME).table(NEXUS_NEWS_CACHE_TABLE).get(date_key).run(conn)
        if doc and isinstance(doc.get("articles"), list):
            articles = _filter_low_signal_alpaca_articles(
                list(doc["articles"]),
                date_key=date_key,
                log_prefix="Alpaca cached article sanitize",
            )
            if len(articles) != len(doc.get("articles") or []):
                try:
                    _r.db(DB_NAME).table(NEXUS_NEWS_CACHE_TABLE).get(date_key).update({
                        "articles": articles,
                        "count": len(articles),
                    }).run(conn)
                except Exception:
                    pass
            articles = _filter_articles_for_context(articles, context)
            n = len(articles)
            _log(f"Article cache HIT for {date_key} ({n} articles)", "green")
            fp = _article_set_fingerprint(articles)
            sent = None
            scope_id = _point_in_time_sentiment_scope_id(
                sentiment_cache_scope_id,
                context,
            )
            by_scope = doc.get("sentiment_by_scope")
            if scope_id and isinstance(by_scope, dict) and fp:
                scope_bucket = by_scope.get(scope_id)
                if isinstance(scope_bucket, dict) and fp in scope_bucket:
                    entry = scope_bucket[fp]
                    if isinstance(entry, dict):
                        sent = entry.get("sentiment_data")
                    if isinstance(sent, dict) and sent:
                        _log(
                            f"Sentiment cache HIT for {date_key} (scope={scope_id[:8]}..., fp={fp[:8]}..., {len(sent)} tickers)",
                            "green",
                        )
            by_fp = doc.get("sentiment_by_fingerprint")
            if sent is None and not scope_id and isinstance(by_fp, dict) and fp and fp in by_fp:
                entry = by_fp[fp]
                if isinstance(entry, dict):
                    sent = entry.get("sentiment_data")
                if isinstance(sent, dict) and sent:
                    _log(f"Sentiment cache HIT for {date_key} (fp={fp[:8]}..., {len(sent)} tickers)", "green")
            if sent is None and isinstance(doc.get("sentiment_data"), dict) and doc["sentiment_data"]:
                if scope_id and isinstance(by_scope, dict) and by_scope:
                    _log(
                        f"Sentiment cache scope MISS for {date_key}; cached scopes do not match {scope_id[:8]}...",
                        "cyan",
                    )
                elif not isinstance(by_fp, dict) or not by_fp:
                    _log(
                        f"Legacy sentiment cache ignored for {date_key}; waiting for fingerprinted sentiment refresh",
                        "cyan",
                    )
            if not (isinstance(sent, dict) and sent):
                sent = None
            return articles, sent
    except Exception as e:
        from point_in_time_data import PointInTimeDataError

        if isinstance(e, PointInTimeDataError):
            raise
        _log(f"Article cache lookup error: {e}", "yellow")
    return None, None


def _save_cached_sentiment(
    conn,
    date_key: str,
    sentiment_data: dict,
    articles: list | None = None,
    *,
    sentiment_cache_scope_id: str = "",
    sentiment_cache_scope_doc: dict[str, Any] | None = None,
    context=None,
):
    """Save LLM sentiment_data keyed by article-set fingerprint so reuse is only for the same articles."""
    from _phase_alpha_helpers import evidence_cache_write_allowed
    if not evidence_cache_write_allowed("sentiment"):
        return
    if conn is None or not isinstance(sentiment_data, dict) or len(sentiment_data) == 0:
        return
    fp = _article_set_fingerprint(articles or []) if articles else ""
    scope_id = _point_in_time_sentiment_scope_id(
        sentiment_cache_scope_id,
        context,
    )
    scope_doc = dict(sentiment_cache_scope_doc or {})
    try:
        doc = _r.db(DB_NAME).table(NEXUS_NEWS_CACHE_TABLE).get(date_key).run(conn)
        if doc is not None:
            by_fp = dict(doc.get("sentiment_by_fingerprint") or {})
            by_scope = dict(doc.get("sentiment_by_scope") or {})
            if scope_id:
                scope_bucket = dict(by_scope.get(scope_id) or {})
                if fp:
                    scope_bucket[fp] = {
                        "sentiment_data": sentiment_data,
                        "sentiment_ticker_count": len(sentiment_data),
                        "sentiment_cache_scope_id": scope_id,
                        "sentiment_model_stamp": scope_doc,
                    }
                by_scope[scope_id] = scope_bucket
            if fp:
                by_fp[fp] = {
                    "sentiment_data": sentiment_data,
                    "sentiment_ticker_count": len(sentiment_data),
                }
            update = {
                "sentiment_by_scope": by_scope,
                "sentiment_by_fingerprint": by_fp,
                "sentiment_data": sentiment_data,
                "sentiment_cached_at": _r.now(),
                "sentiment_ticker_count": len(sentiment_data),
                "sentiment_cache_scope_id": scope_id,
                "sentiment_model_stamp": scope_doc,
            }
            _r.db(DB_NAME).table(NEXUS_NEWS_CACHE_TABLE).get(date_key).update(update).run(conn)
            scope_suffix = f", scope={scope_id[:8]}..." if scope_id else ""
            _log(f"Sentiment cache SAVE for {date_key} (fp={fp[:8] if fp else 'n/a'}..., {len(sentiment_data)} tickers{scope_suffix})", "cyan")
        else:
            by_fp = {fp: {"sentiment_data": sentiment_data, "sentiment_ticker_count": len(sentiment_data)}} if fp else {}
            by_scope = {}
            if scope_id:
                by_scope[scope_id] = (
                    {
                        fp: {
                            "sentiment_data": sentiment_data,
                            "sentiment_ticker_count": len(sentiment_data),
                            "sentiment_cache_scope_id": scope_id,
                            "sentiment_model_stamp": scope_doc,
                        }
                    }
                    if fp
                    else {}
                )
            _r.db(DB_NAME).table(NEXUS_NEWS_CACHE_TABLE).insert({
                "id": date_key,
                "articles": articles or [],
                "sentiment_data": sentiment_data,
                "sentiment_by_fingerprint": by_fp,
                "sentiment_by_scope": by_scope,
                "sentiment_cached_at": _r.now(),
                "sentiment_ticker_count": len(sentiment_data),
                "sentiment_cache_scope_id": scope_id,
                "sentiment_model_stamp": scope_doc,
                "cached_at": _r.now(),
                "count": len(articles) if articles else 0,
            }, conflict="replace").run(conn)
            scope_suffix = f", scope={scope_id[:8]}..." if scope_id else ""
            _log(f"Sentiment cache SAVE for {date_key} (fp={fp[:8] if fp else 'n/a'}..., {len(sentiment_data)} tickers{scope_suffix}, new doc)", "cyan")
    except Exception as e:
        _log(f"Sentiment cache save error: {e}", "yellow")


def _save_cached_articles(conn, date_key: str, articles: list, start_iso: str, end_iso: str):
    """Save articles to cache for date_key."""
    if conn is None:
        return
    try:
        articles = _filter_low_signal_alpaca_articles(list(articles or []), date_key=date_key, log_prefix="Alpaca article cache save sanitize")
        doc = {
            "id": date_key,
            "articles": articles,
            "start_iso": start_iso,
            "end_iso": end_iso,
            "cached_at": _r.now(),
            "count": len(articles),
        }
        _r.db(DB_NAME).table(NEXUS_NEWS_CACHE_TABLE).insert(doc, conflict="replace").run(conn)
        _log(f"Article cache SAVE for {date_key} ({len(articles)} articles)", "cyan")
    except Exception as e:
        _log(f"Article cache save error: {e}", "yellow")


def _invalidate_cached_articles(conn, date_key: str, *, sentiment_cache_scope_id: str = "") -> None:
    """Delete the cached article doc for ``date_key`` (Scope D C1).

    Used when a live first-touch ``force_fresh`` fetch returns EMPTY: the existing
    doc may be a stale backtest-written entry, and leaving it lets the next
    same-day live cycle (``force_fresh=False``) serve the backtest articles +
    aggregated LLM sentiment (skipping the live LLM). Removing it forces the next
    cycle to MISS the cache and re-fetch fresh. Best-effort."""
    if conn is None:
        return
    try:
        _r.db(DB_NAME).table(NEXUS_NEWS_CACHE_TABLE).get(date_key).delete().run(conn)
        _log(f"Article cache INVALIDATE for {date_key} (force_fresh fetch returned empty)", "cyan")
    except Exception as e:
        _log(f"Article cache invalidate error: {e}", "yellow")


def _fetch_alpaca_news_all(start_dt: datetime, end_dt: datetime, key: str, secret: str, limit: int = 50) -> list[dict]:
    """Fetch Alpaca news for all symbols without relying on the legacy news strategy module."""
    if not key or not secret:
        return []
    try:
        import requests
    except Exception:
        return []
    url = f"{ALPACA_NEWS_BASE}/news"
    headers = {
        "APCA-API-KEY-ID": key,
        "APCA-API-SECRET-KEY": secret,
        "accept": "application/json",
    }
    params = {
        "start": start_dt.strftime("%Y-%m-%dT%H:%M:%SZ"),
        "end": end_dt.strftime("%Y-%m-%dT%H:%M:%SZ"),
        "limit": max(1, min(int(limit or 50), 50)),
    }
    retry_waits = (10, 30, 60)
    last_error = None
    for attempt in range(len(retry_waits) + 1):
        try:
            resp = requests.get(url, headers=headers, params=params, timeout=30)
            resp.raise_for_status()
            payload = resp.json() or {}
            articles = payload.get("news") or []
            return articles if isinstance(articles, list) else []
        except requests.HTTPError as exc:
            last_error = exc
            status = getattr(getattr(exc, "response", None), "status_code", None)
            if status == 429 and attempt < len(retry_waits):
                wait = retry_waits[attempt]
                _log(f"Alpaca news all-symbol fetch hit 429; retrying in {wait}s.", "yellow")
                try:
                    import time as _time
                    _time.sleep(wait)
                except Exception:
                    pass
                continue
            break
        except Exception as exc:
            last_error = exc
            break
    _log(f"Alpaca news fetch failed: {last_error}", "yellow")
    return []


def _candidate_government_action_type(sym: str, macro_rows: list[dict], active_events: list[dict]) -> str:
    symbol = str(sym or "").strip().upper()
    if not symbol:
        return ""
    for ev in active_events or []:
        affected = {
            str(v or "").strip().upper()
            for v in (ev.get("affected_tickers") or [])
            if str(v or "").strip()
        }
        if symbol in affected:
            gov_action = str(ev.get("government_action_type") or "").strip().lower()
            if gov_action and gov_action != "none":
                return gov_action
    for row in macro_rows or []:
        possible = {
            str(v or "").strip().upper()
            for v in (row.get("possible_direct_companies") or [])
            if str(v or "").strip()
        }
        if symbol in possible:
            gov_action = str(row.get("government_action_type") or "").strip().lower()
            if gov_action and gov_action != "none":
                return gov_action
    return ""


def _fetch_articles_cached(
    date_key: str,
    start_dt: datetime,
    end_dt: datetime,
    alpaca_key: str,
    alpaca_secret: str,
    limit: int,
    min_articles: int,
    *,
    sentiment_cache_scope_id: str = "",
    force_fresh: bool = False,
    context=None,
    snapshot_store=None,
    config: dict | None = None,
) -> tuple[list, bool, dict | None]:
    """
    Return (articles, from_cache, cached_sentiment) for the given date range.
    Uses RethinkDB cache when available; cached_sentiment is dict or None.

    1-C (bug-sweep 2026-05-28): ``force_fresh=True`` bypasses the cache HIT so a
    live run never serves articles + aggregated LLM sentiment that a backtest may
    have written for this same date_key (date_key is the only cache key). A fresh
    Alpaca fetch is performed and re-cached, and cached_sentiment comes back None
    so the caller re-runs the LLM on the fresh articles instead of adopting the
    stale backtest sentiment (which would skip the LLM entirely).
    """
    strict_articles = _strict_news_source(
        context=context,
        snapshot_store=snapshot_store,
        source="alpaca",
    )
    if strict_articles is not None:
        from point_in_time_data import PointInTimeDataError

        if not isinstance(strict_articles, (list, tuple)):
            raise PointInTimeDataError(
                "news.alpaca snapshot must be an article list"
            )
        sanitized = _filter_low_signal_alpaca_articles(
            list(strict_articles),
            date_key=date_key,
            log_prefix="Alpaca PIT article sanitize",
        )
        return (
            _filter_articles_for_context(sanitized, context),
            True,
            None,
        )

    conn = _get_nexus_db_conn()
    if conn:
        _ensure_nexus_cache_table(conn)
        cache_kwargs = {
            "sentiment_cache_scope_id": sentiment_cache_scope_id,
            "config": config,
        }
        if context is not None:
            cache_kwargs["context"] = context
        cached_articles, cached_sentiment = _get_cached_articles(
            conn, date_key, **cache_kwargs
        )
        cached_count = len(cached_articles or [])
        cached_articles = _filter_articles_for_context(
            cached_articles or [],
            context,
        )
        if len(cached_articles) != cached_count:
            cached_sentiment = None
        if (not force_fresh) and cached_articles is not None and len(cached_articles) >= min_articles:
            return cached_articles, True, cached_sentiment
    _log(f"Article cache MISS for {date_key}; fetching from Alpaca (limit={limit})", "cyan")
    fetch_end_dt = end_dt
    if context is not None and isinstance(end_dt, datetime):
        context_end = context.as_of
        if end_dt.tzinfo is None:
            context_end = context_end.replace(tzinfo=None)
        if fetch_end_dt > context_end:
            fetch_end_dt = context_end
    fetched_articles = _fetch_alpaca_news_all(
        start_dt,
        fetch_end_dt,
        alpaca_key,
        alpaca_secret,
        limit=limit,
    )
    fetched_articles = _filter_low_signal_alpaca_articles(
        fetched_articles or [],
        date_key=date_key,
        log_prefix="Alpaca fetched article sanitize",
    )
    if conn and fetched_articles:
        start_iso = start_dt.strftime("%Y-%m-%dT%H:%M:%SZ")
        end_iso = fetch_end_dt.strftime("%Y-%m-%dT%H:%M:%SZ")
        _save_cached_articles(
            conn,
            date_key,
            fetched_articles,
            start_iso,
            end_iso,
        )
    elif conn and force_fresh:
        # Scope D C1: a live first-touch force_fresh fetch came back EMPTY. The
        # existing cached doc may be a stale backtest entry; leaving it lets the
        # next same-day cycle (force_fresh=False) serve it. Invalidate so the next
        # cycle re-fetches fresh instead of adopting backtest articles+sentiment.
        _invalidate_cached_articles(conn, date_key, sentiment_cache_scope_id=sentiment_cache_scope_id)
    return _filter_articles_for_context(fetched_articles, context), False, None


def _mentioned_tickers_from_articles(articles: list) -> set:
    """Extract ticker symbols from Alpaca article 'symbols' field."""
    tickers = set()
    for a in articles or []:
        for s in (a.get("symbols") or []):
            if isinstance(s, str) and len(s) <= 10 and s.isupper():
                tickers.add(s.strip())
    return tickers


def _news_article_text(article: dict) -> str:
    parts = [
        str(article.get("headline") or article.get("title") or "").strip(),
        str(article.get("summary") or article.get("description") or "").strip(),
        str(article.get("content_excerpt") or article.get("body_excerpt") or "").strip(),
    ]
    return "\n".join(part for part in parts if part)


def _alpaca_low_signal_article_reason(article: dict) -> str:
    headline = str(article.get("headline") or article.get("title") or "").strip()
    if not headline:
        return ""
    for reason, pattern in _LOW_SIGNAL_ALPACA_HEADLINE_PATTERNS:
        if re.search(pattern, headline):
            return reason
    return ""


def _filter_low_signal_alpaca_articles(
    articles: list[dict],
    *,
    date_key: str = "",
    log_prefix: str = "Alpaca low-signal filter",
) -> list[dict]:
    if not articles:
        return []
    filtered: list[dict] = []
    dropped: Counter[str] = Counter()
    for article in articles:
        reason = _alpaca_low_signal_article_reason(article or {})
        if reason:
            dropped[reason] += 1
            continue
        filtered.append(article)
    if dropped:
        drop_summary = ", ".join(f"{reason}={count}" for reason, count in dropped.most_common())
        date_suffix = f" | date={date_key}" if date_key else ""
        _log(
            f"{log_prefix}: dropped {sum(dropped.values())}/{len(articles)} article(s){date_suffix} | {drop_summary}",
            "yellow",
        )
    return filtered


def _trend_relevance_keywords(
    trend_name: str,
    trend_desc: str,
    trend_tickers: list[str] | None,
    trend_sectors: list[str] | None,
) -> set[str]:
    raw_parts = [str(trend_name or ""), str(trend_desc or "")]
    raw_parts.extend(str(v or "") for v in (trend_tickers or []))
    raw_parts.extend(str(v or "") for v in (trend_sectors or []))
    keywords: set[str] = set()
    for part in raw_parts:
        for token in re.findall(r"[A-Za-z0-9&.-]+", part):
            norm = str(token or "").strip().lower()
            if not norm or norm in _TREND_KEYWORD_STOPWORDS:
                continue
            if len(norm) >= 4 or norm in {"ai", "ip", "vr", "ar", "5g", "lng"}:
                keywords.add(norm)
    return keywords


def _article_trend_relevance_score(
    article: dict,
    *,
    trend_name: str,
    trend_desc: str,
    trend_tickers: list[str] | None,
    trend_sectors: list[str] | None,
) -> int:
    article = article or {}
    text = " ".join(
        [
            str(article.get("headline") or article.get("title") or "").strip(),
            str(article.get("summary") or article.get("description") or "").strip(),
        ]
    ).strip()
    if not text:
        return 0
    text_lower = text.lower()
    symbols = {
        str(v or "").strip().upper()
        for v in (article.get("symbols") or article.get("affected_tickers") or [])
        if str(v or "").strip()
    }
    tickers = {
        str(v or "").strip().upper()
        for v in (trend_tickers or [])
        if str(v or "").strip()
    }
    sectors = {
        str(v or "").strip().lower()
        for v in (trend_sectors or [])
        if str(v or "").strip()
    }
    keywords = _trend_relevance_keywords(trend_name, trend_desc, list(tickers), list(sectors))

    score = 0
    if symbols and tickers:
        score += 10 * len(symbols & tickers)
    for ticker in tickers:
        if re.search(rf"(?<![A-Za-z0-9]){re.escape(ticker.lower())}(?![A-Za-z0-9])", text_lower):
            score += 6
    for sector in sectors:
        if sector and sector in text_lower:
            score += 3
    keyword_hits = 0
    for keyword in keywords:
        if keyword and re.search(rf"(?<![A-Za-z0-9]){re.escape(keyword)}(?![A-Za-z0-9])", text_lower):
            keyword_hits += 1
    score += min(keyword_hits, 4) * 2
    return score


def _select_trend_supporting_articles(
    articles: list[dict],
    *,
    date_key: str,
    trend_name: str,
    trend_desc: str,
    trend_tickers: list[str] | None,
    trend_sectors: list[str] | None,
    max_items: int = 3,
) -> list[dict]:
    ranked: list[tuple[int, str, dict]] = []
    seen_headlines: set[str] = set()
    for article in articles or []:
        headline = str(article.get("headline") or article.get("title") or "").strip()
        if not headline:
            continue
        if _alpaca_low_signal_article_reason(article):
            continue
        score = _article_trend_relevance_score(
            article,
            trend_name=trend_name,
            trend_desc=trend_desc,
            trend_tickers=trend_tickers,
            trend_sectors=trend_sectors,
        )
        if score < 4:
            continue
        headline_key = headline.lower()
        if headline_key in seen_headlines:
            continue
        seen_headlines.add(headline_key)
        ranked.append((
            score,
            headline,
            {"date": date_key, "headline": headline[:200], "source": str(article.get("source") or "alpaca").strip() or "alpaca"},
        ))
    ranked.sort(key=lambda item: (-item[0], item[1]))
    return [item[2] for item in ranked[:max_items]]


def _sanitize_trend_supporting_articles(
    entries: list[dict],
    *,
    trend_name: str = "",
    trend_desc: str = "",
    trend_tickers: list[str] | None = None,
    trend_sectors: list[str] | None = None,
) -> list[dict]:
    sanitized: list[dict] = []
    for entry in entries or []:
        if not isinstance(entry, dict):
            continue
        headline = str(entry.get("headline") or "").strip()
        if not headline:
            continue
        if _alpaca_low_signal_article_reason({"headline": headline}):
            continue
        if _article_trend_relevance_score(
            {"headline": headline, "summary": "", "symbols": []},
            trend_name=trend_name,
            trend_desc=trend_desc,
            trend_tickers=trend_tickers,
            trend_sectors=trend_sectors,
        ) < 4:
            continue
        sanitized.append(dict(entry))
    return sanitized


def _normalize_private_entity_alias(alias: str) -> str:
    text = re.sub(r"\s+", " ", str(alias or "").strip()).lower()
    if not text:
        return ""
    text = re.sub(r"^the\s+", "", text)
    text = re.sub(r"[^a-z0-9]+", " ", text)
    return re.sub(r"\s+", " ", text).strip()


def _private_entity_alias_in_text(alias: str, article_text: str) -> bool:
    clean_alias = str(alias or "").strip()
    if not clean_alias or not article_text:
        return False
    return bool(re.search(rf"(?<![A-Za-z0-9]){re.escape(clean_alias)}(?![A-Za-z0-9])", article_text, re.I))


def _extract_private_entity_candidate_aliases_from_text(article_text: str, *, max_candidates: int = 300) -> set[str]:
    text = str(article_text or "").strip()
    if not text:
        return set()
    entity_word = r"(?:[A-Z]{2,}[A-Za-z0-9&./'-]*|[A-Z][A-Za-z0-9&./'-]*|[A-Za-z]+[A-Z][A-Za-z0-9&./'-]*)"
    connector = r"(?:of|and|the|for|to|at|in|on|by|with)"
    pattern = re.compile(
        rf"\b{entity_word}\b(?:\s+(?:{connector})\s+\b{entity_word}\b|\s+\b{entity_word}\b){{0,4}}"
    )
    candidates: set[str] = set()
    for match in pattern.finditer(text):
        phrase = str(match.group(0) or "").strip()
        if not phrase:
            continue
        norm = _normalize_private_entity_alias(phrase)
        if norm and len(norm) >= 3 and norm not in _PRIVATE_ENTITY_ALIAS_STOPWORDS:
            candidates.add(norm)
        words = [w for w in re.findall(r"[A-Za-z0-9&./'-]+", phrase) if w]
        filtered = [w for w in words if w.lower() not in _PRIVATE_ENTITY_CONNECTOR_WORDS]
        for word in filtered:
            norm_word = _normalize_private_entity_alias(word)
            if norm_word and len(norm_word) >= 3 and norm_word not in _PRIVATE_ENTITY_ALIAS_STOPWORDS:
                candidates.add(norm_word)
        max_span = min(4, len(words))
        for size in range(2, max_span + 1):
            for start in range(0, len(words) - size + 1):
                chunk_words = words[start:start + size]
                if chunk_words[0].lower() in _PRIVATE_ENTITY_CONNECTOR_WORDS or chunk_words[-1].lower() in _PRIVATE_ENTITY_CONNECTOR_WORDS:
                    continue
                phrase_norm = _normalize_private_entity_alias(" ".join(chunk_words))
                if phrase_norm and len(phrase_norm) >= 3 and phrase_norm not in _PRIVATE_ENTITY_ALIAS_STOPWORDS:
                    candidates.add(phrase_norm)
        if len(candidates) >= max_candidates:
            break
    return set(sorted(candidates)[:max_candidates])


def _build_private_entity_alias_lookup(alias_index: list[dict]) -> dict[str, list[dict[str, Any]]]:
    lookup: dict[str, list[dict[str, Any]]] = {}
    for entry in alias_index or []:
        seen_norms: set[str] = set()
        for alias in (entry.get("aliases") or []):
            alias_text = str(alias or "").strip()
            if not alias_text:
                continue
            alias_norm = _normalize_private_entity_alias(alias_text)
            if not alias_norm or alias_norm in seen_norms:
                continue
            seen_norms.add(alias_norm)
            lookup.setdefault(alias_norm, []).append({"alias": alias_text, "entry": entry})
    return lookup


def _hierarchy_llm_config() -> tuple[str, str, str]:
    provider = (os.environ.get("GRAPH_NEXUS_HIERARCHY_LLM_PROVIDER", "deepseek") or "deepseek").strip().lower()
    if provider not in _NEXUS_VALID_PROVIDERS:
        provider = "deepseek"
    model = (os.environ.get("GRAPH_NEXUS_HIERARCHY_LLM_MODEL", "") or "").strip()
    if not model:
        model = _default_model_for_provider(provider)
    api_key = (os.environ.get("GRAPH_NEXUS_HIERARCHY_LLM_API_KEY", "") or "").strip()
    if not api_key:
        api_key = _default_api_key_for_provider(provider)
    return provider, model, api_key


def _hierarchy_llm_provider_config() -> dict[str, Any]:
    provider = (os.environ.get("GRAPH_NEXUS_HIERARCHY_LLM_PROVIDER", "deepseek") or "deepseek").strip().lower()
    if provider == "bedrock":
        # Bedrock requires a region — unlike ollama (which defaults to
        # localhost), _call_bedrock returns "" with no region, so the
        # env-driven hierarchy provider must supply one.
        region = (
            os.environ.get("GRAPH_NEXUS_HIERARCHY_BEDROCK_REGION")
            or os.environ.get("BEDROCK_REGION")
            or os.environ.get("AWS_REGION")
            or ""
        ).strip()
        reasoning = (os.environ.get("GRAPH_NEXUS_HIERARCHY_BEDROCK_REASONING") or "").strip().lower()
        out: dict[str, Any] = {}
        if region:
            out["bedrock_region"] = region
        if reasoning and reasoning != "off":
            out["bedrock_reasoning"] = reasoning
        return out
    if provider != "azure":
        return {}
    return {
        "azure_endpoint": (
            os.environ.get("GRAPH_NEXUS_HIERARCHY_AZURE_OPENAI_ENDPOINT")
            or os.environ.get("GRAPH_NEXUS_AZURE_OPENAI_ENDPOINT")
            or os.environ.get("AZURE_OPENAI_ENDPOINT")
            or ""
        ).strip(),
        "api_version": (
            os.environ.get("GRAPH_NEXUS_HIERARCHY_AZURE_OPENAI_API_VERSION")
            or os.environ.get("GRAPH_NEXUS_AZURE_OPENAI_API_VERSION")
            or os.environ.get("OPENAI_API_VERSION")
            or "2024-10-21"
        ).strip(),
    }


def _structured_hierarchy_validation(
    prompt: str,
    output_type: Any,
    *,
    system_prompt: str,
    allow_search: bool,
    log_label: str,
    decision_at: str = "",
):
    provider, model, api_key = _hierarchy_llm_config()
    provider_config = _hierarchy_llm_provider_config()
    if not api_key:
        return None
    search_used = {"value": False}

    def google_search_tool(query: str) -> list[dict[str, Any]]:
        search_used["value"] = True
        return google_cse_search(
            query,
            api_key=os.environ.get("GOOGLE_SEARCH_API_KEY", "").strip(),
            search_engine_id=os.environ.get("GOOGLE_SEARCH_ENGINE_ID", "").strip(),
            num_results=5,
            fetch_result_excerpt=False,
            timeout_sec=20,
        )

    tools = [google_search_tool] if allow_search else None
    # TODO: thread `config` into this helper to attribute critical-guard
    # failures back to the originating backtest/instance.
    raw = _scl_guarded(
        provider,
        api_key,
        model,
        prompt,
        output_type,
        attribution_keys={"call_site": "structured_hierarchy_validation"},
        evidence_context=_model_evidence_context(
            prompt,
            decision_at=decision_at,
            call_site="structured_hierarchy_validation",
            role="hierarchy_validation",
            subject=log_label,
            local_sequence=0,
        ),
        system_prompt=system_prompt,
        tools=tools,
        max_output_tokens=0,
        retries=2,
        output_retries=2,
        temperature=0.0,
        provider_config=provider_config,
    )
    meta = get_last_structured_llm_call_metadata()
    _log(
        f"{log_label}: provider={meta.get('provider') or provider} model={meta.get('effective_model') or model} "
        f"fallback={bool(meta.get('fallback_used'))} search_used={search_used['value']} outcome={'validated' if raw else 'unresolved'}",
        "white" if raw else "yellow",
    )
    return raw


def _load_private_entity_alias_index(session, as_of_date: str = "", candidate_aliases: set[str] | list[str] | None = None) -> list[dict]:
    if session is None:
        return []
    started = perf_counter()
    normalized_candidates = sorted({
        _normalize_private_entity_alias(alias)
        for alias in (candidate_aliases or [])
        if _normalize_private_entity_alias(alias)
    })
    cache_key = ""
    if normalized_candidates:
        cache_key = f"{as_of_date or 'latest'}|{hashlib.sha1('|'.join(normalized_candidates).encode('utf-8')).hexdigest()[:16]}"
        cached = _PRIVATE_ENTITY_ALIAS_QUERY_CACHE.get(cache_key)
        if cached is not None:
            return [dict(row) for row in cached]
    try:
        query = (
            "MATCH (le:LegalEntity) "
            "WHERE size(coalesce(le.aliases, [])) > 0 "
        )
        if normalized_candidates:
            query += (
                "AND ANY(alias_norm IN coalesce(le.normalized_aliases, []) WHERE alias_norm IN $candidate_aliases) "
            )
        query += (
            "OPTIONAL MATCH (parent:Company)-[r:PARENT_OF_ENTITY]->(le) "
            "WHERE " + _edge_active_after_clause("r") + " "
            "WITH le, [ticker IN collect(DISTINCT parent.ticker) WHERE ticker IS NOT NULL] AS parent_tickers "
            "RETURN le.entity_key AS entity_key, "
            "       coalesce(le.display_name, le.legal_name, le.name, le.entity_key) AS display_name, "
            "       coalesce(le.aliases, []) AS aliases, "
            "       coalesce(le.normalized_aliases, []) AS normalized_aliases, "
            "       coalesce(le.alias_risk, 'low') AS alias_risk, "
            "       coalesce(le.alias_requires_parent_confirmation, false) AS requires_confirmation, "
            "       CASE WHEN size(parent_tickers) > 0 THEN parent_tickers ELSE coalesce(le.listed_ancestor_tickers, []) END AS ancestor_tickers"
        )
        rows = list(session.run(
            query,
            as_of_date=as_of_date or "",
            candidate_aliases=normalized_candidates,
        ))
    except Exception as exc:
        _log(f"Private-entity alias index load error: {exc}", "yellow")
        return []
    out = []
    alias_total = 0
    for row in rows:
        ancestors = [str(t or "").strip().upper() for t in (row.get("ancestor_tickers") or []) if str(t or "").strip()]
        if not ancestors:
            continue
        aliases = [str(alias or "").strip() for alias in (row.get("aliases") or []) if str(alias or "").strip()]
        if not aliases:
            continue
        alias_total += len(aliases)
        out.append({
            "entity_key": str(row.get("entity_key") or "").strip(),
            "display_name": str(row.get("display_name") or "").strip(),
            "aliases": aliases,
            "normalized_aliases": [str(alias or "").strip() for alias in (row.get("normalized_aliases") or []) if str(alias or "").strip()],
            "alias_risk": str(row.get("alias_risk") or "low").strip().lower(),
            "requires_confirmation": bool(row.get("requires_confirmation")),
            "ancestor_tickers": ancestors,
        })
    if cache_key:
        _PRIVATE_ENTITY_ALIAS_QUERY_CACHE[cache_key] = [dict(row) for row in out]
        _PRIVATE_ENTITY_ALIAS_QUERY_CACHE_ORDER.append(cache_key)
        while len(_PRIVATE_ENTITY_ALIAS_QUERY_CACHE_ORDER) > _PRIVATE_ENTITY_ALIAS_QUERY_CACHE_LIMIT:
            oldest = _PRIVATE_ENTITY_ALIAS_QUERY_CACHE_ORDER.pop(0)
            _PRIVATE_ENTITY_ALIAS_QUERY_CACHE.pop(oldest, None)
    return out


def _public_company_candidates_for_alias(session, alias: str) -> list[dict]:
    if session is None:
        return []
    alias_text = str(alias or "").strip()
    alias_upper = alias_text.upper()
    alias_norm = _normalize_private_entity_alias(alias_text)
    if not alias_text:
        return []
    try:
        rows = session.run(
            """
            MATCH (c:Company)
            WHERE c.ticker = $alias_upper
               OR toLower(coalesce(c.canonical_name, c.name, '')) = $alias_norm
               OR toLower(coalesce(c.name, '')) = $alias_norm
            RETURN c.ticker AS ticker, coalesce(c.canonical_name, c.name, c.ticker) AS name
            ORDER BY ticker
            LIMIT 5
            """,
            alias_upper=alias_upper,
            alias_norm=alias_norm,
        )
        return [{"ticker": str(row.get("ticker") or "").strip().upper(), "name": str(row.get("name") or "").strip()} for row in rows if row.get("ticker")]
    except Exception:
        return []


def _private_entity_context_prefers_parent(alias: str, article_text: str, ancestor_ticker: str) -> bool:
    text = (article_text or "").lower()
    alias_norm = _normalize_private_entity_alias(alias)
    ticker = str(ancestor_ticker or "").strip().upper()
    if alias_norm == "ring" and ticker == "AMZN":
        return any(cue in text for cue in ("doorbell", "security camera", "home alarm", "alexa", "amazon", "prime"))
    if alias_norm == "beats" and ticker == "AAPL":
        return any(cue in text for cue in ("headphones", "earbuds", "iphone", "apple", "music", "airpods"))
    return False


def _apply_private_entity_resolutions_to_articles(articles: list, resolutions: list[dict]) -> str:
    by_article: dict[int, list[dict]] = {}
    for resolution in resolutions or []:
        by_article.setdefault(int(resolution.get("article_index", -1)), []).append(resolution)
    context_lines: list[str] = []
    for idx, article in enumerate(articles or []):
        resolved = by_article.get(idx) or []
        if not resolved:
            continue
        symbols = list(article.get("symbols") or [])
        for match in resolved:
            ticker = str(match.get("seed_ticker") or "").strip().upper()
            if ticker and ticker not in symbols:
                symbols.append(ticker)
            article.setdefault("_private_entity_resolutions", []).append(dict(match))
            context_lines.append(
                f"Article {idx + 1}: private entity '{match.get('alias')}' resolved to {ticker} via {match.get('entity_kind')} candidate '{match.get('display_name')}'."
            )
        article["symbols"] = symbols
    return ("\n\nPRIVATE ENTITY RESOLUTIONS:\n" + "\n".join(context_lines) + "\n") if context_lines else ""


def _resolve_private_entity_news_matches(session, articles: list, as_of_date: str = "", *, use_toon: bool = True) -> list[dict]:
    started = perf_counter()
    article_candidate_aliases: set[str] = set()
    article_candidate_counts: list[int] = []
    per_article_candidates: list[set[str]] = []
    for article in articles or []:
        article_text = _news_article_text(article)
        article_candidates = _extract_private_entity_candidate_aliases_from_text(article_text)
        per_article_candidates.append(article_candidates)
        article_candidate_counts.append(len(article_candidates))
        article_candidate_aliases.update(article_candidates)
    if not article_candidate_aliases:
        _log("Private-entity matching: no candidate aliases extracted from articles; skipping", "cyan")
        return []
    alias_index = _load_private_entity_alias_index(session, as_of_date=as_of_date, candidate_aliases=article_candidate_aliases)
    if not alias_index or not articles:
        if not alias_index:
            _log("Private-entity matching: no alias index rows available; skipping", "cyan")
        return []
    total_aliases = sum(len(entry.get("aliases") or []) for entry in alias_index)
    alias_lookup = _build_private_entity_alias_lookup(alias_index)
    resolutions: list[dict] = []
    matched_articles = 0
    matched_aliases = 0
    matched_candidate_aliases = 0
    ambiguous_aliases = 0
    llm_resolution_count = 0
    deterministic_resolution_count = 0
    progress_state: dict[str, Any] = {}
    for idx, article in enumerate(articles):
        article_text = _news_article_text(article)
        if not article_text:
            continue
        article_candidates = per_article_candidates[idx] if idx < len(per_article_candidates) else set()
        lookup_candidates = [alias_norm for alias_norm in article_candidates if alias_norm in alias_lookup]
        matched: dict[str, list[dict]] = {}
        for alias_norm in lookup_candidates:
            for alias_candidate in alias_lookup.get(alias_norm, []):
                alias = str(alias_candidate.get("alias") or "").strip()
                entry = alias_candidate.get("entry") or {}
                if alias and _private_entity_alias_in_text(alias, article_text):
                    matched.setdefault(alias, []).append(entry)
        if matched:
            matched_articles += 1
            matched_aliases += len(matched)
            matched_candidate_aliases += len(lookup_candidates)
        for alias, candidates in matched.items():
            if not candidates:
                continue
            public_candidates = _public_company_candidates_for_alias(session, alias)
            deterministic = None
            if len(candidates) == 1:
                candidate = candidates[0]
                ancestors = list(candidate.get("ancestor_tickers") or [])
                if ancestors:
                    if not candidate.get("requires_confirmation"):
                        deterministic = {
                            "article_index": idx,
                            "alias": alias,
                            "entity_key": candidate.get("entity_key"),
                            "display_name": candidate.get("display_name"),
                            "seed_ticker": ancestors[0],
                            "entity_kind": "legal_entity",
                            "confidence_bucket": "high",
                            "reason": "single_open_ancestor",
                        }
                    elif _private_entity_context_prefers_parent(alias, article_text, ancestors[0]):
                        deterministic = {
                            "article_index": idx,
                            "alias": alias,
                            "entity_key": candidate.get("entity_key"),
                            "display_name": candidate.get("display_name"),
                            "seed_ticker": ancestors[0],
                            "entity_kind": "legal_entity",
                            "confidence_bucket": "high",
                            "reason": "context_prefers_parent",
                        }
            if deterministic:
                resolutions.append(deterministic)
                deterministic_resolution_count += 1
                continue
            ambiguous_aliases += 1
            prompt = (
                "Resolve an ambiguous private-entity news mention to the safest tradable public parent ticker.\n"
                "Return keep=true only when one candidate clearly fits the article context.\n"
                "If the best match is a private subsidiary, set best_entity_kind='legal_entity' and best_parent to the parent ticker.\n"
                "If the best match is a directly listed public company candidate, set best_entity_kind='company' and best_parent to that ticker.\n\n"
                f"Alias mention: {alias}\n"
                f"Article text:\n{article_text[:1600]}\n\n"
                f"Private entity candidates:\n{_to_prompt_payload([{k: v for k, v in c.items() if k != 'normalized_aliases'} for c in candidates], use_toon=use_toon)}\n\n"
                f"Public company candidates:\n{_to_prompt_payload(public_candidates, use_toon=use_toon)}\n"
            )
            verdict = _structured_hierarchy_validation(
                prompt,
                _PrivateEntityNewsResolutionResponse,
                system_prompt=(
                    "Use the search tool only when the alias is ambiguous or risky. "
                    "Return only structured fields. Prefer dropping the match over unsafe ticker assignments."
                ),
                allow_search=True,
                log_label="Private-entity validator",
                decision_at=as_of_date,
            )
            if not verdict or not verdict.keep:
                continue
            seed_ticker = str(verdict.best_parent or "").strip().upper()
            if not seed_ticker:
                continue
            chosen_entity_key = str(verdict.best_entity_key or "").strip()
            display_name = next((entry.get("display_name") for entry in candidates if entry.get("entity_key") == chosen_entity_key), alias)
            resolutions.append({
                "article_index": idx,
                "alias": alias,
                "entity_key": chosen_entity_key,
                "display_name": display_name,
                "seed_ticker": seed_ticker,
                "entity_kind": str(verdict.best_entity_kind or "legal_entity").strip().lower(),
                "confidence_bucket": str(verdict.confidence_bucket or "low").strip().lower(),
                "reason": str(verdict.reason or "").strip(),
                "evidence_urls": list(verdict.evidence_urls or []),
            })
            llm_resolution_count += 1
    _log(
        "Private-entity matching: "
        f"resolved={len(resolutions)} | deterministic={deterministic_resolution_count} | "
        f"llm={llm_resolution_count} | ambiguous={ambiguous_aliases} | candidate_hits={matched_candidate_aliases} in {_format_stage_elapsed(perf_counter() - started)}",
        "cyan",
    )
    return resolutions


# ──────────────────────────────────────────────────────────────────────────────
# Relationship-aware contagion propagation model
# ──────────────────────────────────────────────────────────────────────────────

# Propagation rules: how sentiment flows through each edge type and direction.
# Key: (relationship_type, direction) where direction is "out" or "in"
#   "out" = mentioned_ticker -[r]-> neighbor  (we're following outgoing edges)
#   "in"  = mentioned_ticker <-[r]- neighbor  (we're following incoming edges)
# Value: (base_factor, invert_sentiment)
#   base_factor: 0.0-1.0, how strongly sentiment transmits
#   invert_sentiment: True if sentiment flips sign (competitor loss = your gain)

_PROPAGATION = {
    # Corporate hierarchy — tightest coupling (parent/subsidiary fate linked)
    ("PARENT_OF", "out"):         (0.85, False),   # parent news → subsidiary heavily affected
    ("PARENT_OF", "in"):          (0.60, False),   # subsidiary news → parent moderately affected
    ("PARENT_OF_LEI", "out"):     (0.85, False),   # LEI parent → subsidiary
    ("PARENT_OF_LEI", "in"):      (0.60, False),
    ("CONTROLS", "out"):          (0.80, False),   # controller news → controlled entity
    ("CONTROLS", "in"):           (0.55, False),   # controlled entity news → controller

    # Supply chain — directional with asymmetric impact
    ("SUPPLIER_OF", "out"):       (0.65, False),   # supplier disruption → customer at supply risk
    ("SUPPLIER_OF", "in"):        (0.50, False),   # customer demand drop → supplier revenue risk
    # Contracts — contractual dependency
    ("CONTRACTS_WITH", "out"):    (0.45, False),   # contractor risk → counterparty
    ("CONTRACTS_WITH", "in"):     (0.45, False),

    # Competition — INVERTS sentiment (zero-sum dynamics)
    ("COMPETES_WITH", "out"):     (0.40, True),    # competitor loss = potential market share gain
    ("COMPETES_WITH", "in"):      (0.40, True),    # competitor gain = potential market share loss

    # Strategic alliances — shared risk
    ("STRATEGIC_PARTNER", "out"): (0.50, False),   # partner risk spills over
    ("STRATEGIC_PARTNER", "in"):  (0.50, False),
    ("PATENT_PARTNER", "out"):    (0.25, False),   # innovation partner — weaker link
    ("PATENT_PARTNER", "in"):     (0.25, False),

}

# All relationship types we know how to propagate (subset used based on what exists in DB)
_REL_TYPES_1HOP = [
    "SUPPLIER_OF", "PARENT_OF", "PARENT_OF_LEI", "CONTROLS",
    "CONTRACTS_WITH", "COMPETES_WITH", "STRATEGIC_PARTNER", "PATENT_PARTNER",
]

# Strong directional relationships for 2-hop chain traversal
_REL_TYPES_2HOP = ["SUPPLIER_OF", "PARENT_OF", "PARENT_OF_LEI", "CONTROLS", "CONTRACTS_WITH"]

# Event-type amplifiers: certain news categories strengthen specific edge propagation.
# e.g. a supply_disruption event amplifies SUPPLIER_OF by 1.5x
_EVENT_AMPLIFIERS = {
    "supply_disruption": {"SUPPLIER_OF": 1.5, "STRATEGIC_PARTNER": 1.2, "CONTRACTS_WITH": 1.2},
    "regulatory":        {"COMPETES_WITH": 1.2, "IN_SECTOR": 1.4},
    "m_and_a":           {"PARENT_OF": 1.5, "PARENT_OF_LEI": 1.5, "CONTROLS": 1.5, "STRATEGIC_PARTNER": 1.4},
    "earnings":          {"COMPETES_WITH": 1.3, "IN_SECTOR": 1.2},
    "competition":       {"COMPETES_WITH": 1.5},
    "product":           {"COMPETES_WITH": 1.3, "SUPPLIER_OF": 1.2},
    "legal":             {"PARENT_OF": 1.2, "PARENT_OF_LEI": 1.2, "CONTRACTS_WITH": 1.2},
    "general":           {},
}

# Defaults
_SECTOR_PROPAGATION_FACTOR = 0.20
_INSTITUTIONAL_PROPAGATION_FACTOR = 0.10
_INSTITUTIONAL_MIN_SHARED = 3
_INSTITUTIONAL_SCALE_DIVISOR = 10.0
_2HOP_DECAY = 0.40
_MIN_2HOP_CONFIDENCE = 0.60
_DEFAULT_BUY_THRESHOLD = 0.15
_DEFAULT_SELL_THRESHOLD = -0.30


