def _extract_sentiment_json(resp: str):
    """
    Extract a single JSON object (ticker -> {s, e} or ticker -> int) from LLM response.
    Handles deepseek-reasoner: long reasoning_content with final JSON at the end.
    Returns parsed dict or None.
    """
    import json
    if not resp or not resp.strip():
        return None
    s = resp.strip()
    # 1) Prefer ```json ... ``` block
    for marker in ("```json", "```"):
        start = s.find(marker)
        if start >= 0:
            start = s.find("{", start)
            if start >= 0:
                end = s.find("```", start)
                if end < 0:
                    end = len(s)
                chunk = s[start:end]
                brace_end = chunk.rfind("}") + 1
                if brace_end > 0:
                    try:
                        return json.loads(chunk[:brace_end])
                    except json.JSONDecodeError:
                        pass
    # 2) First { to last } (whole response)
    first_brace = s.find("{")
    last_brace = s.rfind("}")
    if first_brace >= 0 and last_brace > first_brace:
        try:
            return json.loads(s[first_brace:last_brace + 1])
        except json.JSONDecodeError:
            pass
    # 3) Last complete JSON object (for reasoner: final answer at end)
    end_idx = last_brace
    while end_idx >= first_brace >= 0:
        depth = 1  # we are inside the closing } at end_idx
        start_idx = -1
        for j in range(end_idx - 1, first_brace - 1, -1):
            if s[j] == "}":
                depth += 1
            elif s[j] == "{":
                depth -= 1
                if depth == 0:
                    start_idx = j
                    break
        if start_idx >= 0:
            try:
                return json.loads(s[start_idx:end_idx + 1])
            except json.JSONDecodeError:
                pass
        end_idx = s.rfind("}", 0, end_idx)
        if end_idx <= first_brace:
            break
    return None


def _enhanced_sentiment_from_llm(articles: list, provider: str, api_key: str, model: str, num_articles: int = 30, today_str: str = "", pending_trades: list | None = None, ticker_history: dict | None = None, active_trends: list | None = None, additional_context: str = "", provider_config: dict[str, Any] | None = None, config: dict[str, Any] | None = None, _retry_stage: int = 0) -> tuple[dict, list, list, dict]:
    """
    One LLM call: given headlines (and optionally pending future trades + active trends), return:
      - dict[ticker -> {"sentiment": int, "event": str}]
      - list of future_trade dicts [{"ticker", "date", "signal", "reason"}, ...]
      - list of cancel dicts [{"ticker", "date", "reason"}, ...] for trades to revoke
      - dict of trend_updates {"new": [...], "confirm": [...], "weaken": [...], "end": [...]}
    Event types enable relationship-specific amplification in graph propagation.
    Falls back gracefully if LLM returns old format (ticker -> int).
    """
    _empty4 = ({}, [], [], {})
    if not api_key or not articles:
        return _empty4
    sentiment_limits = _get_sentiment_prompt_limits(
        config,
        provider=provider,
        model=model,
        provider_config=provider_config,
        requested_articles=num_articles,
    )
    requested_articles = int(sentiment_limits["requested_articles"])
    if sentiment_limits["auto_reduced"]:
        _log(
            f"Daily sentiment LLM: auto-reduced prompt context for {sentiment_limits['model_ref']} | "
            f"articles={requested_articles}→{int(sentiment_limits['max_articles'])} "
            f"pending={sentiment_limits['requested_pending_trades']}→{sentiment_limits['max_pending_trades']} "
            f"history={sentiment_limits['requested_history_tickers']}x{sentiment_limits['requested_history_entries']}→"
            f"{sentiment_limits['max_history_tickers']}x{sentiment_limits['max_history_entries']} "
            f"context={sentiment_limits['requested_context_chars']}→{sentiment_limits['max_additional_context_chars']} chars",
            "yellow",
        )
    num_articles = int(sentiment_limits["max_articles"])
    _max_additional_context_chars = int(sentiment_limits["max_additional_context_chars"])
    if _max_additional_context_chars <= 0:
        additional_context = ""
    elif additional_context and len(additional_context) > _max_additional_context_chars:
        additional_context = additional_context[:_max_additional_context_chars].rstrip()
    headlines = []
    for i, a in enumerate(articles[:num_articles]):
        h = (a.get("headline") or "").strip()
        if h:
            headlines.append(f"{i+1}. {h}")
    text = "\n".join(headlines)
    if not text:
        return _empty4

    # Build trends context for LLM
    trends_context = _build_trends_context(active_trends) if active_trends else ""

    # Build pending trades context for LLM review
    pending_context = ""
    if pending_trades:
        pending_lines = []
        for t in pending_trades:
            sig = "BUY" if t.get("signal") == 1 else "SELL"
            pending_lines.append(
                f"  - {t.get('symbol')} {sig} on {t.get('target_date')} "
                f"(reason: {t.get('reason', 'N/A')[:60]}, scheduled: {t.get('source_date', '?')})"
            )
        if pending_lines:
            pending_context = (
                "\n\nPENDING SCHEDULED TRADES (review these against today's headlines):\n"
                + "\n".join(pending_lines[: int(sentiment_limits["max_pending_trades"])])
                + "\nFor each pending trade, decide if today's news invalidates the original thesis. "
                "If so, include it in the 'cancel' list.\n"
            )

    # Build recent headline history context for tickers with pending trades
    history_context = ""
    if ticker_history:
        history_lines = []
        for ticker, entries in list(ticker_history.items())[: int(sentiment_limits["max_history_tickers"])]:
            if not entries:
                continue
            dates_seen = set()
            ticker_lines = []
            for e in entries:
                d = e.get("d", "")
                h = e.get("h", "")
                if d and h and d not in dates_seen:
                    dates_seen.add(d)
                    ticker_lines.append(f"  {d}: {h[:120]}")
            if ticker_lines:
                history_lines.append(f"{ticker} (recent {len(ticker_lines)} days):")
                history_lines.extend(ticker_lines[: int(sentiment_limits["max_history_entries"])])
        if history_lines:
            history_context = (
                "\n\nRECENT HEADLINE HISTORY (for tickers with pending trades — use this to evaluate "
                "whether today's news confirms or contradicts the original trade thesis):\n"
                + "\n".join(history_lines)
                + "\n"
            )

    try:
        prompt = (
            "Analyze these financial news headlines. For each stock ticker mentioned or implied:\n"
            "1. Determine sentiment: 1 (positive), -1 (negative), 0 (neutral)\n"
            "2. Categorize the primary event type. MUST be one of:\n"
            "   supply_disruption, regulatory, m_and_a, earnings, competition, product, legal, general\n"
            "   Do NOT invent new event types — use the closest match from this list.\n\n"
            "Consider indirect effects:\n"
            "- Oil/commodity price moves affect energy and materials tickers\n"
            "- Supply chain disruptions ripple to manufacturers and their customers\n"
            "- Regulatory actions can affect entire sectors\n"
            "- M&A news affects acquirer, target, and competitors\n"
            "- Earnings beats/misses signal sector strength or weakness\n\n"
            + (f"Today's date: {today_str}\n" if today_str else "")
            + pending_context
            + history_context
            + trends_context
            + (
                ("\n\nThe following additional market data sources are provided. Factor them into your sentiment assessment:\n"
                 + ("- Analyst rating changes (upgrades/downgrades with PT changes) are meaningful signals.\n" if "ANALYST RATINGS" in additional_context else "")
                 + ("- Insider buys >$100K are bullish. Large insider sells may be bearish.\n" if "INSIDER TRANSACTIONS" in additional_context else "")
                 + ("- Recent earnings beats/misses affect near-term sentiment.\n" if "EARNINGS RESULTS" in additional_context else "")
                 + ("- Congressional stock trades may signal informed sentiment.\n" if "GOVERNMENT TRADES" in additional_context else "")
                 + ("- M&A activity can drive significant price moves for targets and acquirers.\n" if "MERGERS" in additional_context else "")
                 + ("- Upcoming IPOs/splits affect sector and individual stock dynamics.\n" if "IPOs" in additional_context or "SPLITS" in additional_context else "")
                 + "\n")
                if additional_context and any(s in additional_context for s in ("ANALYST", "INSIDER", "EARNINGS", "GOVERNMENT", "MERGERS", "IPOs", "SPLITS", "DIVIDENDS", "PREDICTION"))
                else ("" if not additional_context else "\n\nAdditional context:\n")
            )
            + additional_context
            + "Reply with a structured object with these keys:\n"
            '1. "sentiment": [{"t": "TICKER", "s": 1, "e": "category", "sp": 1.0}, ...]\n'
            '   "sp" (sell_pct): optional, only for s=-1 partial sells (0.0–1.0, default 1.0=sell all). '
            'Use 0.5 to reduce a position by half while keeping partial exposure.\n'
            '2. "future" (optional): [{"t": "TICKER", "d": "YYYY-MM-DD", "s": 1, "r": "brief reason"}, ...]\n'
            "   Include future events ONLY when a headline mentions a specific upcoming date\n"
            "   (earnings date, FDA decision date, merger vote date, product launch date, etc.).\n"
            "   Signal should be your predicted impact: 1 (positive) or -1 (negative).\n"
            '3. "cancel" (optional): [{"t": "TICKER", "d": "YYYY-MM-DD", "r": "why thesis is invalidated"}, ...]\n'
            "   Include ONLY if today's news clearly invalidates a pending trade's original thesis.\n"
            "   Do NOT cancel just because there's no new news; only cancel on contradicting evidence.\n"
            '4. "trends" (optional): Identify or update market-level trends from headlines.\n'
            '   - "new": emerging trends NOT in ACTIVE TRENDS above. Each:\n'
            '     {"id": "snake_case_slug", "name": "Human Name", "desc": "1-sentence", '
            '"dir": "bullish"|"bearish", "str": 0.0-1.0, "tickers": ["SYM",...], "sectors": ["Name",...]}\n'
            '   - "confirm": existing active trends reinforced by today\'s headlines.\n'
            '     Each: {"id": "existing_slug", "str": 0.0-1.0, "tickers_add": ["SYM",...] (optional)}\n'
            '   - "weaken": existing trends losing momentum. Each: {"id": "slug", "reason": "brief"}\n'
            '   - "end": existing trends clearly over/reversed. Each: {"id": "slug", "reason": "brief"}\n'
            "   A trend is a multi-week/month market pattern (e.g., 'RAM shortage', 'oil price surge', "
            "'AI spending boom'). Only identify trends with clear evidence in headlines.\n\n"
            "Use short ticker symbols (AAPL not Apple). Only include tickers you can confidently identify.\n"
            "IMPORTANT: Be extremely concise. Max 5 words per reason/desc. Omit empty arrays/objects. "
            "Do NOT repeat or rephrase headlines. Target under 1500 total output tokens.\n\n"
            f"Headlines:\n{text}"
        )
        _est_prompt_tokens = len(prompt.encode("utf-8")) // 4
        _max_output_tokens = int(sentiment_limits["max_output_tokens"] or 0)
        _log(
            f"Daily sentiment LLM: prompt ~{_est_prompt_tokens:,} tokens | headlines={len(headlines)} | max_output={_max_output_tokens if _max_output_tokens > 0 else 'unlimited'}",
            "cyan",
        )
        _sent_instance_id = (
            str((config or {}).get("runtime_instance_id") or "").strip()
            or str((config or {}).get("instance_id") or "").strip()
        )
        with llm_call_context(
            backtest_id=(config or {}).get("_telemetry_backtest_id"),
            instance_id=(config or {}).get("_telemetry_instance_id"),
            strategy="GraphNexusAnalysis",
            call_site="sentiment",
        ):
            raw = _scl_guarded(
                provider,
                api_key,
                model,
                prompt,
                _EnhancedSentimentResponse,
                attribution_keys={
                    "backtest_id": (config or {}).get("_telemetry_backtest_id"),
                    "instance_id": (config or {}).get("_telemetry_instance_id"),
                    "call_site": "sentiment",
                },
                evidence_context=_model_evidence_context(
                    prompt,
                    decision_at=today_str,
                    call_site="sentiment",
                    role="sentiment",
                    subject=_sent_instance_id or "graph-nexus",
                    local_sequence=_retry_stage,
                ),
                system_prompt=(
                    "Return only structured financial headline classifications as minimal JSON. "
                    "Use the short alias keys (t, s, e, sp, d, r). "
                    "Omit fields with default values, empty arrays/objects, and omit sp when it equals 1.0. "
                    "Max 5 words per reason/desc. Do NOT add explanations or commentary. "
                    "Target under 1500 total output tokens."
                ),
                max_output_tokens=_max_output_tokens,
                retries=1 if sentiment_limits["is_gpt_oss"] else 2,
                output_retries=1 if sentiment_limits["is_gpt_oss"] else 3,
                timeout_sec=180 if sentiment_limits["is_gpt_oss"] else 360,
                provider_config=provider_config,
                prefer_raw_json=bool(sentiment_limits["is_gpt_oss"]),
            )
        _build_llm_trace("enhanced_sentiment", provider, model, prompt, (
            "Return only structured financial headline classifications. "
            "Use the schema fields exactly; omit markdown and free-form wrappers."
        ), "enhanced_sentiment_v1", raw is not None)
        if raw is None:
            if bool(sentiment_limits["is_gpt_oss"]) and int(_retry_stage) < int(sentiment_limits["outer_attempts"]):
                _next_stage = int(_retry_stage) + 1
                if _next_stage == 1:
                    _next_num_articles = max(
                        int(sentiment_limits["retry_min_articles"]),
                        min(max(1, int(num_articles) - 1), int(math.ceil(int(num_articles) * 0.67))),
                    )
                    _next_pending = list(pending_trades or [])[: max(0, int(sentiment_limits["max_pending_trades"]) // 2)] or None
                    _next_history = {}
                    for _ticker, _entries in list((ticker_history or {}).items())[: max(0, int(sentiment_limits["max_history_tickers"]) // 2)]:
                        _next_history[_ticker] = list(_entries or [])[: max(0, int(sentiment_limits["max_history_entries"]) // 2)]
                    _next_active_trends = active_trends
                    _next_additional_context = (additional_context or "")[: max(0, int(_max_additional_context_chars) // 2)].rstrip()
                else:
                    _next_num_articles = max(int(sentiment_limits["retry_min_articles"]), min(8, int(num_articles)))
                    _next_pending = None
                    _next_history = None
                    _next_active_trends = None
                    _next_additional_context = ""
                _log(
                    f"Daily sentiment LLM retry {_next_stage}/{int(sentiment_limits['outer_attempts'])}: "
                    f"shrinking prompt context | articles={num_articles}→{_next_num_articles} "
                    f"| pending={len(pending_trades or [])}→{len(_next_pending or [])} "
                    f"| history={len(ticker_history or {})}→{len(_next_history or {})} "
                    f"| extra={len(additional_context or '')}→{len(_next_additional_context or '')}",
                    "yellow",
                )
                return _enhanced_sentiment_from_llm(
                    articles,
                    provider,
                    api_key,
                    model,
                    num_articles=_next_num_articles,
                    today_str=today_str,
                    pending_trades=_next_pending,
                    ticker_history=_next_history if _next_history else None,
                    active_trends=_next_active_trends,
                    additional_context=_next_additional_context,
                    provider_config=provider_config,
                    config=config,
                    _retry_stage=_next_stage,
                )
            _log("Structured LLM sentiment returned no validated payload.", "yellow")
            return _empty4

        result = {}
        for v in (raw.sentiment or []):
            ticker = str(v.ticker).upper().strip()
            if not ticker:
                continue
            sent = int(v.sentiment) if int(v.sentiment) in (1, -1, 0) else 0
            evt_raw = str(v.event or "general").strip().lower()
            try:
                sell_pct = float(v.sell_pct if v.sell_pct is not None else 1.0)
                sell_pct = max(0.01, min(1.0, sell_pct))
            except (ValueError, TypeError):
                sell_pct = 1.0
            result[ticker] = {
                "sentiment": sent,
                "event": evt_raw if evt_raw in _EVENT_AMPLIFIERS else "general",
                "sell_pct": sell_pct,
            }
        if result:
            _log(f"LLM sentiment: {len(result)} tickers classified", "green")
        else:
            _n_raw = len(raw.sentiment or [])
            _log(f"Enhanced sentiment: LLM returned {_n_raw} sentiment item(s) — all empty/invalid tickers or empty list", "yellow")

        # Parse future trades
        # Phase δ observability sweep (2026-05-18, BT232179 follow-up): the
        # prior `if future_trades: _log(...)` gate hid the empty-result case
        # — operators couldn't distinguish "LLM returned 0 future events"
        # from "LLM returned events but all failed validation" from "LLM
        # crashed before reaching this path". Always log, with raw-vs-valid
        # counts so the operator sees the filter funnel.
        future_trades = []
        _ft_raw_count = len(raw.future) if raw.future else 0
        for ft in raw.future:
            ticker = str(ft.ticker).upper().strip()
            date = str(ft.date).strip()
            signal = int(ft.signal)
            reason = str(ft.reason).strip()
            if ticker and len(date) == 10 and signal in (1, -1):
                future_trades.append({"ticker": ticker, "date": date, "signal": signal, "reason": reason})
        if future_trades or _ft_raw_count > 0:
            _ft_color = "green" if future_trades else "yellow"
            _log(
                f"LLM future events: {len(future_trades)}/{_ft_raw_count} "
                f"trades scheduled (after ticker+date+signal validation)",
                _ft_color,
            )

        # Parse cancellation recommendations
        cancel_recommendations = []
        _ct_raw_count = len(raw.cancel) if raw.cancel else 0
        for ct in raw.cancel:
            ticker = str(ct.ticker).upper().strip()
            date = str(ct.date).strip()
            reason = str(ct.reason).strip()
            if ticker and len(date) == 10:
                cancel_recommendations.append({"ticker": ticker, "date": date, "reason": reason})
        # Phase δ: always log, including the 0-cancel case. A burst of cancels
        # is operationally important and the prior gate could hide quiet
        # periods where the LLM returned `cancel:[]` (vs the schema-error
        # case where `raw.cancel` itself was malformed).
        if cancel_recommendations or _ct_raw_count > 0:
            _ct_color = "yellow" if cancel_recommendations else "cyan"
            _log(
                f"LLM cancel recommendations: {len(cancel_recommendations)}"
                f"/{_ct_raw_count} trades to review (after ticker+date validation)",
                _ct_color,
            )

        # Parse trend updates
        trend_updates = raw.trends.model_dump(by_alias=True)
        n_new = len(trend_updates.get("new") or [])
        n_confirm = len(trend_updates.get("confirm") or [])
        n_weaken = len(trend_updates.get("weaken") or [])
        n_end = len(trend_updates.get("end") or [])
        # Phase δ: always log so the all-zeros case is visible too. Trend
        # tracking is a key Phase 2 signal; zero-trend bars need an audit
        # trail to distinguish "no movement" from "LLM trend parser broke".
        _trend_color = "green" if (n_new or n_confirm or n_weaken or n_end) else "cyan"
        _log(
            f"LLM trends: {n_new} new, {n_confirm} confirmed, {n_weaken} "
            f"weakening, {n_end} ended",
            _trend_color,
        )

        return result, future_trades, cancel_recommendations, trend_updates
    except Exception as e:
        _raise_model_evidence_error(e)
        _log(f"Enhanced LLM sentiment error: {e}", "yellow")
        return _empty4


# ──────────────────────────────────────────────────────────────────────────────
# Google News: macro/geopolitical news classification + Neo4j resolution
# ──────────────────────────────────────────────────────────────────────────────

def _get_available_sectors(session) -> list[str]:
    """Fetch all sector names from Neo4j for LLM prompt context."""
    try:
        result = session.run("MATCH (s:Sector) RETURN s.name AS name ORDER BY name")
        return [r["name"] for r in result if r.get("name")]
    except Exception:
        return []


def _get_available_gov_agencies(session) -> list[str]:
    """Fetch all government agency names from Neo4j for LLM prompt context."""
    try:
        result = session.run("MATCH (g:GovAgency) RETURN g.name AS name ORDER BY name")
        return [r["name"] for r in result if r.get("name")]
    except Exception:
        return []


def _classify_macro_news_via_llm(
    articles: list[dict],
    provider: str,
    api_key: str,
    model: str,
    today_str: str,
    available_sectors: list[str],
    available_gov_agencies: list[str],
    num_articles: int = 50,
    provider_config: dict[str, Any] | None = None,
    graph_driver=None,
) -> list[dict]:
    """
    Classify Google News articles into structured macro signals via a single LLM call.
    Returns list of macro_signal dicts with affected_sectors, event_type, sentiment, etc.

    Hybrid approach: uses structured classification first; if all results are too vague,
    falls back to Gemini tool-calling with Neo4j query tools.
    """
    if not api_key or not articles:
        return []

    headlines = []
    for i, a in enumerate(articles[:num_articles]):
        h = (a.get("headline") or a.get("title") or "").strip()
        desc = (a.get("description") or "").strip()
        if h:
            line = f"{i+1}. {h}"
            if desc and len(desc) > 20:
                line += f" — {desc[:150]}"
            headlines.append(line)
    text = "\n".join(headlines)
    if not text:
        return []

    sectors_str = ", ".join(available_sectors) if available_sectors else "Technology, Healthcare, Energy, Financials, Industrials, Consumer Discretionary, Consumer Staples, Materials, Utilities, Real Estate, Communication Services"
    agencies_str = ", ".join(available_gov_agencies[:20]) if available_gov_agencies else "Department of Defense, NASA, Department of Energy, Department of Health and Human Services"

    prompt = (
        "You are analyzing general/macro news articles for stock market impact.\n"
        "For each article that could affect publicly traded US companies, classify it.\n\n"
        f"Available sectors in our database: [{sectors_str}]\n"
        f"Available government agencies: [{agencies_str}]\n\n"
        "For each impactful article, output a JSON object using SHORT keys:\n"
        '{"macro_signals":[{"hi":1,"as":["Energy","Industrials"],"et":"supply_disruption","se":-1,"st":0.8,"re":"Oil supply cut","dt":["XOM"],"nf":{"ga":"DOD","cm":"oil","rl":"CONTRACTS_WITH"}}]}\n\n'
        "Valid event_type values: supply_disruption|regulatory|m_and_a|earnings|competition|product|legal|geopolitical|macro_economic|commodity|general\n\n"
        "Rules:\n"
        "- Only include articles with CLEAR market impact (skip vague/general articles)\n"
        "- affected_sectors: MUST use exact sector names from the list above\n"
        "- direct_tickers: only if a specific company is mentioned by name\n"
        "- neo4j_filters: optional hints for which graph relationships to query\n"
        "- strength: 0.0-1.0 how impactful (0.3=minor, 0.6=moderate, 0.9=major)\n"
        "- sentiment: 1 (positive for stocks), -1 (negative), 0 (mixed/unclear)\n"
        "- Skip articles about sports, entertainment, celebrities unless they mention a public company\n\n"
        f"Today's date: {today_str}\n\n"
        f"Headlines:\n{text}"
    )

    try:
        macro_batch_sys = (
            "Return only structured macro-news impact classifications as minimal JSON. "
            "Use short alias keys: hi (headline_idx), as (affected_sectors), et (event_type), "
            "se (sentiment), st (strength), re (reason), dt (direct_tickers), nf (neo4j_filters with ga/cm/rl). "
            "Omit fields with default/empty values. Omit nf if all filters empty. "
            "Keep reason under 8 words. Max 3 sectors per signal. "
            "Minimize total output tokens. No markdown or prose."
        )
        # TODO: thread `config` into _classify_macro_news_via_llm to attribute
        # critical-guard failures back to the originating backtest/instance.
        raw = _scl_guarded(
            provider,
            api_key,
            model,
            prompt,
            _MacroSignalsResponse,
            attribution_keys={"call_site": "macro_news_classification"},
            evidence_context=_model_evidence_context(
                prompt,
                decision_at=today_str,
                call_site="macro_news_classification",
                role="macro_classification",
                local_sequence=0,
            ),
            system_prompt=macro_batch_sys,
            max_output_tokens=0,
            retries=2,
            output_retries=3,
            timeout_sec=360,
            provider_config=provider_config,
            prefer_raw_json=True,
        )
        _build_llm_trace("macro_batch", provider, model, prompt, macro_batch_sys, "macro_batch_v1", raw is not None)
        if raw is None:
            return []

        # Validate and normalize
        valid = []
        for sig in raw.macro_signals:
            sectors = list(sig.affected_sectors or [])
            # Filter to valid sectors
            sectors = [s for s in sectors if s in available_sectors] if available_sectors else sectors
            sentiment = max(-1, min(1, int(sig.sentiment)))
            strength = max(0.0, min(1.0, float(sig.strength)))
            event = str(sig.event_type or "general").strip().lower()
            direct = [t.upper().strip() for t in (sig.direct_tickers or []) if isinstance(t, str) and t.strip()]
            filters = sig.neo4j_filters.model_dump() if sig.neo4j_filters else {}

            if sectors or direct:  # must have at least a sector or direct ticker
                valid.append({
                    "affected_sectors": sectors,
                    "event_type": event,
                    "sentiment": sentiment,
                    "strength": strength,
                    "reason": str(sig.reason or "")[:200],
                    "direct_tickers": direct,
                    "neo4j_filters": filters,
                })

        # ── Hybrid fallback: if classification is too vague, use tool-calling ──
        if not valid and len(headlines) >= 3 and provider == "gemini":
            valid = _classify_macro_with_tools(
                text, api_key, model, today_str,
                available_sectors, available_gov_agencies,
                graph_driver=graph_driver,
            )

        if valid:
            _log(f"Macro classification: {len(valid)} signals from {len(headlines)} headlines", "green")
        return valid
    except Exception as e:
        _raise_model_evidence_error(e)
        _log(f"Macro classification error: {e}", "yellow")
        return []


_NEXUS_NEWS_LLM_GOOGLE_TABLE = "GraphNexusNewsLLMGoogle"
_google_macro_table_ensured = False


def _ensure_google_macro_table(conn) -> None:
    global _google_macro_table_ensured
    if conn is None or _google_macro_table_ensured:
        return
    try:
        tables = list(_r.db(DB_NAME).table_list().run(conn))
        if _NEXUS_NEWS_LLM_GOOGLE_TABLE not in tables:
            _r.db(DB_NAME).table_create(_NEXUS_NEWS_LLM_GOOGLE_TABLE).run(conn)
        _google_macro_table_ensured = True
    except Exception as _e:
        _log(f"Could not ensure Google macro cache table: {_e}", "yellow")


def _classify_macro_news_via_llm_cached(
    articles: list[dict],
    provider: str,
    api_key: str,
    model: str,
    today_str: str,
    available_sectors: list[str],
    available_gov_agencies: list[str],
    num_articles: int = 50,
    provider_config: dict[str, Any] | None = None,
    conn=None,
    instance_id: str = "",
    graph_driver=None,
) -> list[dict]:
    """Cached wrapper for _classify_macro_news_via_llm. Stores result in RethinkDB keyed by
    (date_key, instance_id, model, article fingerprint) so backtest restarts skip the 56s LLM call."""
    from _phase_alpha_helpers import evidence_cache_read_allowed
    if not evidence_cache_read_allowed("macro_classification"):
        return _classify_macro_news_via_llm(
            articles, provider, api_key, model, today_str,
            available_sectors, available_gov_agencies, num_articles, provider_config,
            graph_driver=graph_driver,
        )
    if conn is None or not _nexus_db_available:
        return _classify_macro_news_via_llm(
            articles, provider, api_key, model, today_str,
            available_sectors, available_gov_agencies, num_articles, provider_config,
            graph_driver=graph_driver,
        )
    try:
        fp_parts = "|".join(
            sorted(str(a.get("id") or a.get("url") or a.get("headline") or "")[:60] for a in articles[:num_articles])
        )
        fp_hash = hashlib.sha256(fp_parts.encode("utf-8", errors="replace")).hexdigest()[:16]
        model_ref = f"{provider}:{model}"
        _sec_hash = hashlib.sha256("|".join(sorted(available_sectors or [])).encode("utf-8", errors="replace")).hexdigest()[:8]
        cache_id = f"google_macro|{today_str}|{instance_id[:24]}|{model_ref}|{fp_hash}|{_sec_hash}"
        _ensure_google_macro_table(conn)
        cached = _r.db(DB_NAME).table(_NEXUS_NEWS_LLM_GOOGLE_TABLE).get(cache_id).run(conn)
        if cached and isinstance(cached.get("signals"), list):
            _log(f"Google macro: cache hit for {today_str} ({len(cached['signals'])} signals)", "cyan")
            return cached["signals"]
    except Exception:
        cached = None
        cache_id = ""
    result = _classify_macro_news_via_llm(
        articles, provider, api_key, model, today_str,
        available_sectors, available_gov_agencies, num_articles, provider_config,
        graph_driver=graph_driver,
    )
    if result and cache_id:
        try:
            _r.db(DB_NAME).table(_NEXUS_NEWS_LLM_GOOGLE_TABLE).insert(
                {"id": cache_id, "signals": result, "cached_at": today_str},
                conflict="replace",
            ).run(conn)
        except Exception:
            pass
    return result


def _classify_macro_with_tools(
    headlines_text: str,
    api_key: str,
    model: str,
    today_str: str,
    available_sectors: list[str],
    available_gov_agencies: list[str],
    *,
    graph_driver=None,
) -> list[dict]:
    """
    Fallback: use Gemini function-calling to let the LLM query Neo4j
    when structured classification alone is too vague. Capped at 2 rounds.
    """
    if not api_key or not model:
        return []

    # Lazy Neo4j session for tool execution
    _tool_session = [None]  # mutable container for closure
    _tool_driver = [None]

    def _get_tool_session():
        if _tool_session[0] is not None:
            return _tool_session[0]
        try:
            if graph_driver is not None:
                _tool_session[0] = graph_driver.session()
                return _tool_session[0]
            from neo4j import GraphDatabase
            uri, user, pw = _resolve_neo4j_runtime_config()
            driver = GraphDatabase.driver(uri, auth=(user, pw))
            _tool_driver[0] = driver
            _tool_session[0] = driver.session()
            return _tool_session[0]
        except Exception:
            return None

    def search_by_sector(sector: str) -> list[dict[str, Any]]:
        """Find publicly traded companies in a specific market sector.

        Args:
            sector: Exact sector name from the graph.
        """
        session = _get_tool_session()
        if session is None:
            return [{"error": "Neo4j unavailable"}]
        try:
            r = session.run(
                (
                    "MATCH (c:Company)-[r:IN_SECTOR]->(s:Sector {name: $sector}) "
                    "WHERE " + _edge_active_after_clause("r") + " "
                    "RETURN c.ticker AS ticker, c.name AS name ORDER BY ticker LIMIT 20"
                ),
                sector=sector,
                as_of_date=today_str,
            )
            return [{"ticker": rec["ticker"], "name": rec["name"]} for rec in r]
        except Exception as e:
            return [{"error": str(e)}]

    def search_by_gov_contracts(agency_keyword: str) -> list[dict[str, Any]]:
        """Find companies with government contracts from a specific agency.

        Args:
            agency_keyword: Partial agency name keyword such as Department of Defense.
        """
        session = _get_tool_session()
        if session is None:
            return [{"error": "Neo4j unavailable"}]
        try:
            r = session.run(
                (
                    "MATCH (c:Company)-[r:CONTRACTS_WITH]->(g:GovAgency) "
                    "WHERE g.name CONTAINS $agency AND " + _edge_active_after_clause("r") + " "
                    "RETURN c.ticker AS ticker, c.name AS name, r.total_obligation AS obligation "
                    "ORDER BY r.total_obligation DESC LIMIT 15"
                ),
                agency=agency_keyword,
                as_of_date=today_str,
            )
            return [
                {
                    "ticker": rec["ticker"],
                    "name": rec["name"],
                    "obligation": rec.get("obligation"),
                }
                for rec in r
            ]
        except Exception as e:
            return [{"error": str(e)}]

    def search_related_companies(ticker: str, relationship: str) -> list[dict[str, Any]]:
        """Find companies connected to a ticker by a supported graph relationship.

        Args:
            ticker: Public stock ticker symbol such as AAPL.
            relationship: One of SUPPLIER_OF, COMPETES_WITH, PARENT_OF, CONTROLS, CONTRACTS_WITH, STRATEGIC_PARTNER, PATENT_PARTNER.
        """
        session = _get_tool_session()
        if session is None:
            return [{"error": "Neo4j unavailable"}]
        rel = (relationship or "SUPPLIER_OF").strip().upper()
        allowed_rels = {
            "SUPPLIER_OF",
            "COMPETES_WITH",
            "PARENT_OF",
            "CONTROLS",
            "CONTRACTS_WITH",
            "STRATEGIC_PARTNER",
            "PATENT_PARTNER",
        }
        if rel not in allowed_rels:
            return [{"error": f"Invalid relationship: {rel}"}]
        try:
            r = session.run(
                (
                    f"MATCH (a:Company {{ticker: $ticker}})-[r:{rel}]-(b:Company) "
                    f"WHERE {_edge_active_after_clause('r')} "
                    "RETURN b.ticker AS ticker, b.name AS name ORDER BY ticker LIMIT 15"
                ),
                ticker=(ticker or "").upper().strip(),
                as_of_date=today_str,
            )
            return [{"ticker": rec["ticker"], "name": rec["name"]} for rec in r]
        except Exception as e:
            return [{"error": str(e)}]

    tool_prompt = (
        "You are analyzing news headlines for stock market impact. "
        "Use the provided tools to find which companies/tickers are affected.\n\n"
        "After querying, return the structured macro_signals response.\n\n"
        f"Today: {today_str}\n\nHeadlines:\n{headlines_text}"
    )

    try:
        # TODO: thread `config` into _classify_macro_with_tools to attribute
        # critical-guard failures back to the originating backtest/instance.
        raw = _scl_guarded(
            "gemini",
            api_key,
            model,
            tool_prompt,
            _MacroSignalsResponse,
            attribution_keys={"call_site": "macro_news_tools_fallback"},
            evidence_context=_model_evidence_context(
                tool_prompt,
                decision_at=today_str,
                call_site="macro_news_tools_fallback",
                role="macro_classification",
                local_sequence=1,
            ),
            system_prompt=(
                "Use the available Neo4j tools when needed, then return only structured macro signals. "
                "Do not include markdown or explanatory prose outside the schema."
            ),
            tools=[search_by_sector, search_by_gov_contracts, search_related_companies],
            max_output_tokens=0,
            retries=2,
            output_retries=3,
        )
        if raw is None:
            return []
        valid = []
        for sig in raw.macro_signals:
            sectors = [s for s in (sig.affected_sectors or []) if s in available_sectors] if available_sectors else list(sig.affected_sectors or [])
            direct = [t.upper().strip() for t in (sig.direct_tickers or []) if isinstance(t, str) and t.strip()]
            if not sectors and not direct:
                continue
            valid.append({
                "affected_sectors": sectors,
                "event_type": str(sig.event_type or "general").strip().lower(),
                "sentiment": max(-1, min(1, int(sig.sentiment))),
                "strength": max(0.0, min(1.0, float(sig.strength))),
                "reason": str(sig.reason or "")[:200],
                "direct_tickers": direct,
                "neo4j_filters": sig.neo4j_filters.model_dump() if sig.neo4j_filters else {},
            })
        return valid
    except Exception as e:
        _raise_model_evidence_error(e)
        _log(f"Tool-calling fallback error: {e}", "yellow")
    finally:
        # Clean up session
        if _tool_session[0] is not None:
            try:
                _tool_session[0].close()
            except Exception:
                pass
        if _tool_driver[0] is not None:
            try:
                _tool_driver[0].close()
            except Exception:
                pass
    return []


def _resolve_macro_signals_to_tickers(
    session,
    macro_signals: list[dict],
    symbols_set: set[str] | None = None,
    as_of_date: str = "",
) -> dict[str, dict]:
    """
    Convert macro LLM classifications into ticker → sentiment mappings via Neo4j queries.

    Decay factors by resolution method:
    - Direct ticker mention: sentiment × 1.0
    - Gov contract match:   sentiment × 0.7
    - Commodity exposure:   sentiment × 0.6
    - Sector match:         sentiment × 0.5

    Returns dict like {"XOM": {"sentiment": -1, "event": "supply_disruption"}, ...}
    """
    if not session or not macro_signals:
        return {}

    result: dict[str, dict] = {}

    for sig in macro_signals:
        sentiment = sig.get("sentiment", 0)
        if sentiment == 0:
            continue
        event = sig.get("event_type", "general")
        strength = sig.get("strength", 0.5)
        sectors = sig.get("affected_sectors") or []
        direct = sig.get("direct_tickers") or []
        filters = sig.get("neo4j_filters") or {}

        # 1. Direct tickers (decay = 1.0)
        for tk in direct:
            tk = tk.upper().strip()
            if symbols_set and tk not in symbols_set:
                continue
            score = sentiment * strength * 1.0
            if tk not in result or abs(score) > abs(result[tk].get("sentiment", 0)):
                result[tk] = {"sentiment": score, "event": event}

        # 2. Gov agency contract match (decay = 0.7)
        agency = filters.get("gov_agency", "")
        if agency:
            try:
                r = session.run(
                    (
                        "MATCH (c:Company)-[r:CONTRACTS_WITH]->(g:GovAgency) "
                        "WHERE g.name CONTAINS $agency AND " + _edge_active_after_clause("r") + " "
                        "RETURN c.ticker AS ticker, r.total_obligation AS obligation "
                        "ORDER BY r.total_obligation DESC LIMIT 20"
                    ),
                    agency=agency,
                    as_of_date=as_of_date or "",
                )
                for rec in r:
                    tk = rec["ticker"]
                    if symbols_set and tk not in symbols_set:
                        continue
                    score = sentiment * strength * 0.7
                    if tk not in result or abs(score) > abs(result[tk].get("sentiment", 0)):
                        result[tk] = {"sentiment": score, "event": event}
            except Exception:
                pass

        # 3. Commodity exposure (decay = 0.6)
        commodity = filters.get("commodity", "")
        if commodity:
            try:
                r = session.run(
                    (
                        "MATCH (s:Sector)-[:EXPOSED_TO]->(com:Commodity) "
                        "WHERE toLower(com.name) CONTAINS toLower($commodity) "
                        "WITH s "
                        "MATCH (c:Company)-[r:IN_SECTOR]->(s) "
                        "WHERE " + _edge_active_after_clause("r") + " "
                        "RETURN c.ticker AS ticker ORDER BY ticker LIMIT 30"
                    ),
                    commodity=commodity,
                    as_of_date=as_of_date or "",
                )
                for rec in r:
                    tk = rec["ticker"]
                    if symbols_set and tk not in symbols_set:
                        continue
                    score = sentiment * strength * 0.6
                    if tk not in result or abs(score) > abs(result[tk].get("sentiment", 0)):
                        result[tk] = {"sentiment": score, "event": event}
            except Exception:
                pass

        # 4. Sector match (decay = 0.5)
        for sector in sectors:
            try:
                r = session.run(
                    (
                        "MATCH (c:Company)-[r:IN_SECTOR]->(s:Sector {name: $sector}) "
                        "WHERE " + _edge_active_after_clause("r") + " "
                        "RETURN c.ticker AS ticker ORDER BY ticker LIMIT 50"
                    ),
                    sector=sector,
                    as_of_date=as_of_date or "",
                )
                for rec in r:
                    tk = rec["ticker"]
                    if symbols_set and tk not in symbols_set:
                        continue
                    score = sentiment * strength * 0.5
                    if tk not in result or abs(score) > abs(result[tk].get("sentiment", 0)):
                        result[tk] = {"sentiment": score, "event": event}
            except Exception:
                pass

    if result:
        _log(f"Macro → ticker resolution: {len(result)} tickers from {len(macro_signals)} signals", "green")
    return result


def _fetch_google_news_cached(
    date_key: str,
    start_dt: datetime,
    end_dt: datetime,
    config: dict,
    conn=None,
    *,
    log_context: str = "foreground",
    context=None,
    snapshot_store=None,
) -> list[dict]:
    """
    Fetch Google News articles with RethinkDB caching (same pattern as Alpaca cache).
    Returns list of article dicts or empty list if disabled/error.
    """
    if not config.get("google_news_enabled", True):
        return []

    strict_articles = _strict_news_source(
        context=context,
        snapshot_store=snapshot_store,
        source="google",
    )
    if strict_articles is not None:
        from point_in_time_data import PointInTimeDataError

        if not isinstance(strict_articles, (list, tuple)):
            raise PointInTimeDataError(
                "news.google snapshot must be an article list"
            )
        sanitized = _filter_low_signal_alpaca_articles(
            list(strict_articles),
            date_key=date_key,
            log_prefix="Google PIT article sanitize",
        )
        return _filter_articles_for_context(sanitized, context)

    try:
        from google_news import (
            fetch_google_news, fetch_google_news_by_topic,
            load_cached_articles, cache_articles, compute_keywords_hash,
            DEFAULT_KEYWORDS, DEFAULT_TOPICS,
        )
    except ImportError:
        try:
            from strategies.google_news import (
                fetch_google_news, fetch_google_news_by_topic,
                load_cached_articles, cache_articles, compute_keywords_hash,
                DEFAULT_KEYWORDS, DEFAULT_TOPICS,
            )
        except ImportError:
            _log("google_news module not found; skipping Google News.", "yellow")
            return []

    keywords = config.get("google_news_keywords") or DEFAULT_KEYWORDS
    topics = config.get("google_news_topics") or DEFAULT_TOPICS
    max_articles = config.get("google_news_max_articles", 50)
    kw_hash = compute_keywords_hash(keywords, topics)

    _is_background_log = str(log_context or "").strip().lower() == "background"

    # Check cache — use provided connection (important for background threads)
    if conn is None:
        conn = _get_nexus_db_conn()
    cached = load_cached_articles(conn, date_key, kw_hash) if conn else None
    if cached:
        sanitized_cached = _filter_low_signal_alpaca_articles(
            list(cached or []),
            date_key=date_key,
            log_prefix="Google cached article sanitize",
        )
        if conn and len(sanitized_cached) != len(cached):
            try:
                cache_articles(conn, date_key, sanitized_cached, kw_hash)
            except Exception:
                pass
        sanitized_cached = _filter_articles_for_context(
            sanitized_cached,
            context,
        )
        if _is_background_log:
            _log(f"Google News background: {len(sanitized_cached)} articles from cache for {date_key}", "cyan")
        else:
            _log(f"Google News: {len(sanitized_cached)} articles from cache for {date_key}", "cyan")
        return sanitized_cached

    # Fetch fresh
    if _is_background_log:
        _log(
            f"Google News background: fetching for {date_key} "
            f"({len(keywords)} keywords, {len(topics)} topics)...",
            "cyan",
        )
    else:
        _log(f"Google News: fetching for {date_key} ({len(keywords)} keywords, {len(topics)} topics)...", "cyan")
    articles = []
    try:
        kw_articles = fetch_google_news(
            keywords=keywords, start_date=start_dt, end_date=end_dt,
            max_results_per_keyword=5, max_total=max_articles,
        )
        articles.extend(kw_articles)
    except Exception as e:
        _log(f"Google News keyword fetch error: {e}", "yellow")

    try:
        topic_articles = fetch_google_news_by_topic(
            topics=topics, start_date=start_dt, end_date=end_dt,
            max_results_per_topic=10, max_total=max(20, max_articles - len(articles)),
        )
        # Deduplicate against keyword articles
        seen_urls = {a.get("url") for a in articles}
        for a in topic_articles:
            if a.get("url") not in seen_urls:
                articles.append(a)
                seen_urls.add(a.get("url"))
    except Exception as e:
        _log(f"Google News topic fetch error: {e}", "yellow")

    articles = _filter_low_signal_alpaca_articles(
        articles or [],
        date_key=date_key,
        log_prefix="Google fetched article sanitize",
    )
    if articles and conn:
        cache_articles(conn, date_key, articles, kw_hash)
    articles = _filter_articles_for_context(articles, context)

    if _is_background_log:
        _log(f"Google News background: {len(articles)} articles fetched for {date_key}", "green")
    else:
        _log(f"Google News: {len(articles)} articles fetched for {date_key}", "green")
    return articles


# ──────────────────────────────────────────────────────────────────────────────
# Neo4j graph traversal queries (batched for efficiency)
# ──────────────────────────────────────────────────────────────────────────────

def _query_1hop(session, tickers: set, direction: str, rels: list | None = None, as_of_date: str = "") -> list[dict]:
    """
    Batch query 1-hop neighbors of all mentioned tickers in a specific direction.
    rels: relationship types to query (only those present in DB). If empty/None, returns [].
    Returns list of edge dicts with relationship metadata.
    """
    if not tickers:
        return []
    rels = rels if rels else []
    if not rels:
        return []
    if direction == "out":
        q = """
        UNWIND $tickers AS src
        MATCH (s:Company {ticker: src})-[r]->(n:Company)
        WHERE type(r) IN $rels
          AND (__DATE_R__)
        WITH src, n.ticker AS target, type(r) AS rel,
             max(coalesce(r.confidence, 0.5)) AS conf,
             max(r.revenue_pct) AS rev_pct,
             max(r.total_obligation) AS obligation,
             max(CASE WHEN r.patent_ids IS NOT NULL THEN size(r.patent_ids) ELSE 0 END) AS patent_count
        RETURN src AS source, target, rel, conf, rev_pct, obligation, patent_count
        """
    else:
        q = """
        UNWIND $tickers AS src
        MATCH (s:Company {ticker: src})<-[r]-(n:Company)
        WHERE type(r) IN $rels
          AND (__DATE_R__)
        WITH src, n.ticker AS target, type(r) AS rel,
             max(coalesce(r.confidence, 0.5)) AS conf,
             max(r.revenue_pct) AS rev_pct,
             max(r.total_obligation) AS obligation,
             max(CASE WHEN r.patent_ids IS NOT NULL THEN size(r.patent_ids) ELSE 0 END) AS patent_count
        RETURN src AS source, target, rel, conf, rev_pct, obligation, patent_count
        """
    try:
        q = q.replace("__DATE_R__", _edge_active_after_clause("r"))
        result = session.run(q, tickers=list(tickers), rels=rels, as_of_date=as_of_date or "")
        edges = []
        for rec in result:
            target = (rec.get("target") or "").strip()
            if not target or target == rec.get("source"):
                continue
            edges.append({
                "source": rec["source"],
                "target": target,
                "rel": rec["rel"],
                "direction": direction,
                "confidence": float(rec.get("conf") or 0.5),
                "revenue_pct": float(rec["rev_pct"]) if rec.get("rev_pct") is not None else None,
                "total_obligation": float(rec["obligation"]) if rec.get("obligation") is not None else None,
                "patent_count": int(rec.get("patent_count") or 0),
            })
        return edges
    except Exception as e:
        _log(f"1-hop {direction} query error: {e}", "yellow")
        return []


def _query_sector_peers(session, tickers: set, as_of_date: str = "") -> list[dict]:
    """Batch query: find same-sector peers of all mentioned tickers via IN_SECTOR.

    Determinism: the LIMIT below truncates, so without an ORDER BY it is not
    "500 peers" but "whichever 500 Neo4j happened to emit" -- a different
    subset on every run, from a `tickers` SET whose UNWIND order also varied.
    Two runs of the same config therefore scored different peer universes.
    Sorting both the seed list and the result makes the truncation stable.
    """
    if not tickers:
        return []
    q = """
    UNWIND $tickers AS src
    MATCH (s:Company {ticker: src})-[r1:IN_SECTOR]->(sec:Sector)<-[r2:IN_SECTOR]-(peer:Company)
    WHERE peer.ticker <> src
      AND __DATE_R1__
      AND __DATE_R2__
    RETURN src AS source, peer.ticker AS target, sec.name AS sector
    ORDER BY source, target, sector
    LIMIT 500
    """
    try:
        q = q.replace("__DATE_R1__", _edge_active_after_clause("r1")).replace("__DATE_R2__", _edge_active_after_clause("r2"))
        result = session.run(q, tickers=list(tickers), as_of_date=as_of_date or "")
        edges = []
        seen = set()
        for rec in result:
            target = (rec.get("target") or "").strip()
            pair = (rec["source"], target)
            if not target or pair in seen:
                continue
            seen.add(pair)
            edges.append({
                "source": rec["source"],
                "target": target,
                "sector": rec.get("sector", ""),
            })
        return edges
    except Exception as e:
        _log(f"Sector peer query error: {e}", "yellow")
        return []


def _query_macro_sector_flow(session, tickers: set, as_of_date: str = "") -> list[dict]:
    """
    Find companies in downstream sectors that depend on the mentioned tickers' sectors
    via BEA I-O SUPPLIES_TO_SECTOR relationships. E.g. if AAPL (Technology) has news,
    propagate to companies in sectors that Technology supplies to.
    Returns list of {source, target, from_sector, to_sector, flow_value}.
    """
    if not tickers:
        return []
    q = """
    UNWIND $tickers AS src
    MATCH (s:Company {ticker: src})-[r1:IN_SECTOR]->(s1:Sector)-[f:SUPPLIES_TO_SECTOR]->(s2:Sector)<-[r2:IN_SECTOR]-(target:Company)
    WHERE target.ticker <> src AND s1 <> s2
      AND (__DATE_R1__)
      AND (__DATE_R2__)
      AND (__DATE_F__)
    RETURN src AS source, target.ticker AS target, s1.name AS from_sector,
           s2.name AS to_sector, coalesce(f.flow_value, 0) AS flow_value
    ORDER BY f.flow_value DESC, source, target
    LIMIT 500
    """
    try:
        q = (
            q.replace("__DATE_R1__", _edge_active_after_clause("r1"))
             .replace("__DATE_R2__", _edge_active_after_clause("r2"))
             .replace("__DATE_F__", _edge_active_after_clause("f"))
        )
        result = session.run(q, tickers=list(tickers), as_of_date=as_of_date or "")
        edges = []
        seen = set()
        for rec in result:
            target = (rec.get("target") or "").strip()
            pair = (rec["source"], target)
            if not target or pair in seen:
                continue
            seen.add(pair)
            edges.append({
                "source": rec["source"],
                "target": target,
                "from_sector": rec.get("from_sector", ""),
                "to_sector": rec.get("to_sector", ""),
                "flow_value": float(rec.get("flow_value") or 0),
            })
        return edges
    except Exception as e:
        _log(f"Macro sector flow query error: {e}", "yellow")
        return []


def _query_2hop_chains(session, tickers: set, direction: str, rels: list | None = None, as_of_date: str = "") -> list[dict]:
    """
    Batch query 2-hop chains through strong directional relationships.
    rels: relationship types to use (only those present in DB). If empty/None, returns [].
    """
    if not tickers:
        return []
    rels = rels if rels else []
    if not rels:
        return []
    if direction == "out":
        q = """
        UNWIND $tickers AS src
        MATCH (s:Company {ticker: src})-[r1]->(mid:Company)-[r2]->(other:Company)
        WHERE type(r1) IN $rels AND type(r2) IN $rels
          AND coalesce(r1.confidence, 0.5) >= $min_conf
          AND coalesce(r2.confidence, 0.5) >= $min_conf
          AND (__DATE_R1__)
          AND (__DATE_R2__)
          AND other.ticker <> src AND mid.ticker <> src
        WITH src, other.ticker AS target, type(r1) AS rel1, type(r2) AS rel2,
             max(coalesce(r1.confidence, 0.5)) AS conf1,
             max(coalesce(r2.confidence, 0.5)) AS conf2
        RETURN DISTINCT src AS source, target, rel1, rel2, conf1, conf2
        ORDER BY source, target, rel1, rel2
        LIMIT 500
        """
    else:
        q = """
        UNWIND $tickers AS src
        MATCH (s:Company {ticker: src})<-[r1]-(mid:Company)<-[r2]-(other:Company)
        WHERE type(r1) IN $rels AND type(r2) IN $rels
          AND coalesce(r1.confidence, 0.5) >= $min_conf
          AND coalesce(r2.confidence, 0.5) >= $min_conf
          AND (__DATE_R1__)
          AND (__DATE_R2__)
          AND other.ticker <> src AND mid.ticker <> src
        WITH src, other.ticker AS target, type(r1) AS rel1, type(r2) AS rel2,
             max(coalesce(r1.confidence, 0.5)) AS conf1,
             max(coalesce(r2.confidence, 0.5)) AS conf2
        RETURN DISTINCT src AS source, target, rel1, rel2, conf1, conf2
        LIMIT 500
        """
    try:
        q = q.replace("__DATE_R1__", _edge_active_after_clause("r1")).replace("__DATE_R2__", _edge_active_after_clause("r2"))
        result = session.run(
            q, tickers=list(tickers), rels=rels, min_conf=_MIN_2HOP_CONFIDENCE, as_of_date=as_of_date or ""
        )
        edges = []
        for rec in result:
            target = (rec.get("target") or "").strip()
            if not target:
                continue
            edges.append({
                "source": rec["source"],
                "target": target,
                "rel1": rec["rel1"],
                "rel2": rec["rel2"],
                "direction": direction,
                "combined_conf": float(rec.get("conf1", 0.5)) * float(rec.get("conf2", 0.5)),
            })
        return edges
    except Exception as e:
        _log(f"2-hop {direction} query error: {e}", "yellow")
        return []


def _get_available_relationship_types(session) -> set:
    """Return set of relationship type names present in the database. Used to query only what exists."""
    try:
        result = session.run("CALL db.relationshipTypes() YIELD relationshipType RETURN relationshipType")
        types = {str(r.get("relationshipType", "")).strip() for r in result if r.get("relationshipType")}
        return types
    except Exception:
        return set()


def _graph_has_relationship_type(session, rel_type: str) -> bool:
    """Return True if the graph has the given relationship type (avoids running queries that trigger 'not available' warnings)."""
    return (rel_type or "") in _get_available_relationship_types(session)


def _edge_active_after_clause(alias: str) -> str:
    return (
        f"(NOT (coalesce({alias}.retired_reason, '') IN "
        f"['false_positive', 'entity_correction', 'direction_conflict', 'denylist', 'invalid_listing'])) "
        f"AND ("
        f"($as_of_date = '' AND "
        f"({alias}.active_after IS NULL OR {alias}.active_after = '' OR {alias}.active_after <= toString(date())) "
        f"AND ({alias}.valid_until IS NULL OR {alias}.valid_until = '' OR toString(date()) < {alias}.valid_until)"
        f") "
        f"OR "
        f"($as_of_date <> '' AND "
        f"({alias}.active_after IS NULL OR {alias}.active_after = '' OR {alias}.active_after <= $as_of_date) "
        f"AND ({alias}.valid_until IS NULL OR {alias}.valid_until = '' OR $as_of_date < {alias}.valid_until)"
        f")"
        f")"
    )


def _query_institutional_co_holdings(session, tickers: set, as_of_date: str = "") -> list[dict]:
    """
    Find companies that share 3+ institutional holders with mentioned tickers.
    Captures institutional correlation: large funds rebalancing affects co-held stocks.
    Skips if HOLDS relationship type is not in the graph (no warning).
    """
    if not tickers:
        return []
    try:
        if not _graph_has_relationship_type(session, "HOLDS"):
            _log("  Institutional co-holdings: skipped (HOLDS relationship not in graph; load institutional data to enable)", "cyan")
            return []
    except Exception:
        return []
    q = """
    UNWIND $tickers AS src
    MATCH (c:Company {ticker: src})<-[r1:HOLDS]-(inst:Institution)-[r2:HOLDS]->(other:Company)
    WHERE other.ticker <> src
      AND (__DATE_R1__)
      AND (__DATE_R2__)
    WITH src, other.ticker AS target, count(DISTINCT inst) AS shared_count,
         sum(coalesce(r1.value_usd, 0)) + sum(coalesce(r2.value_usd, 0)) AS total_value
    WHERE shared_count >= $min_shared
    WITH src, target, shared_count, total_value
    ORDER BY shared_count DESC
    WITH src, collect({target: target, shared_count: shared_count, total_value: total_value})[..30] AS top_targets
    UNWIND top_targets AS t
    RETURN src AS source, t.target AS target, t.shared_count AS shared_count, t.total_value AS total_value
    """
    try:
        q = q.replace("__DATE_R1__", _edge_active_after_clause("r1")).replace("__DATE_R2__", _edge_active_after_clause("r2"))
        result = session.run(q, tickers=list(tickers), min_shared=_INSTITUTIONAL_MIN_SHARED, as_of_date=as_of_date or "")
        edges = []
        for rec in result:
            target = (rec.get("target") or "").strip()
            if not target:
                continue
            edges.append({
                "source": rec["source"],
                "target": target,
                "shared_count": int(rec.get("shared_count", 0)),
                "total_value": float(rec.get("total_value") or 0),
            })
        return edges
    except Exception as e:
        _log(f"Institutional co-holding query error: {e}", "yellow")
        return []


# ──────────────────────────────────────────────────────────────────────────────
# Advanced graph queries for deeper analysis
# ──────────────────────────────────────────────────────────────────────────────

def _query_supply_chain_concentration(session, tickers: set, as_of_date: str = "") -> dict:
    """
    For each ticker, count how many SUPPLIER_OF and customer relationships it has.
    High concentration (few suppliers) means more vulnerability to supply disruption.
    Returns dict[ticker -> {"supplier_count": int, "customer_count": int}].
    """
    if not tickers:
        return {}
    q = """
    UNWIND $tickers AS t
    OPTIONAL MATCH (c:Company {ticker: t})<-[r1:SUPPLIER_OF]-(sup:Company)
    WHERE __DATE_R1__
    WITH t, count(DISTINCT sup) AS supplier_count
    OPTIONAL MATCH (c2:Company {ticker: t})-[r2:SUPPLIER_OF]->(cust:Company)
    WHERE __DATE_R2__
    RETURN t AS ticker, supplier_count, count(DISTINCT cust) AS customer_count
    """
    try:
        q = q.replace("__DATE_R1__", _edge_active_after_clause("r1")).replace("__DATE_R2__", _edge_active_after_clause("r2"))
        result = session.run(q, tickers=list(tickers), as_of_date=as_of_date or "")
        out = {}
        for rec in result:
            tk = rec.get("ticker")
            if tk:
                out[tk] = {
                    "supplier_count": int(rec.get("supplier_count", 0)),
                    "customer_count": int(rec.get("customer_count", 0)),
                }
        return out
    except Exception as e:
        _log(f"Supply chain concentration query error: {e}", "yellow")
        return {}


def _query_institutional_holders_count(session, tickers: set, as_of_date: str = "") -> dict:
    """
    Count how many institutions hold each ticker. More institutional ownership
    means the stock is more sensitive to broad sentiment shifts.
    Returns dict[ticker -> int (holder count)].
    """
    if not tickers:
        return {}
    q = """
    UNWIND $tickers AS t
    MATCH (c:Company {ticker: t})<-[r:HOLDS]-(inst:Institution)
    WHERE __DATE_R__
    RETURN t AS ticker, count(DISTINCT inst) AS holder_count
    """
    try:
        q = q.replace("__DATE_R__", _edge_active_after_clause("r"))
        result = session.run(q, tickers=list(tickers), as_of_date=as_of_date or "")
        return {rec["ticker"]: int(rec.get("holder_count", 0)) for rec in result if rec.get("ticker")}
    except Exception as e:
        _log(f"Institutional holder count query error: {e}", "yellow")
        return {}


def _query_competitive_overlap(session, tickers: set, as_of_date: str = "") -> list[dict]:
    """
    Find competitors that also share suppliers. When competitor has negative news
    and you share supply chain, the beneficiary effect is stronger (you can capture
    their supply contracts and market share).
    Returns list of dicts with source, target, shared_supplier_count.
    """
    if not tickers:
        return []
    q = """
    UNWIND $tickers AS src
    MATCH (s:Company {ticker: src})-[rc:COMPETES_WITH]-(comp:Company)
    WHERE __DATE_RC__
    OPTIONAL MATCH (s)<-[r1:SUPPLIER_OF]-(shared:Company)-[r2:SUPPLIER_OF]->(comp)
    WHERE __DATE_R1__ AND __DATE_R2__
    WITH src, comp.ticker AS competitor, count(DISTINCT shared) AS shared_suppliers
    WHERE shared_suppliers > 0
    RETURN src AS source, competitor AS target, shared_suppliers
    LIMIT 200
    """
    try:
        q = (
            q.replace("__DATE_RC__", _edge_active_after_clause("rc"))
             .replace("__DATE_R1__", _edge_active_after_clause("r1"))
             .replace("__DATE_R2__", _edge_active_after_clause("r2"))
        )
        result = session.run(q, tickers=list(tickers), as_of_date=as_of_date or "")
        return [
            {"source": rec["source"], "target": rec["target"], "shared_suppliers": int(rec.get("shared_suppliers", 0))}
            for rec in result if rec.get("target")
        ]
    except Exception as e:
        _log(f"Competitive overlap query error: {e}", "yellow")
        return []


def _query_conglomerate_exposure(session, tickers: set, as_of_date: str = "") -> list[dict]:
    """
    Find tickers that are controlled or owned by the same parent (siblings).
    News affecting one subsidiary can signal parent-level issues that ripple to siblings.
    Returns list of {source, target, parent_ticker, relationship}.
    """
    if not tickers:
        return []
    q = """
    UNWIND $tickers AS src
    MATCH (s:Company {ticker: src})<-[r1:PARENT_OF|CONTROLS]-(parent:Company)-[r2:PARENT_OF|CONTROLS]->(sibling:Company)
    WHERE sibling.ticker <> src
      AND __DATE_R1__
      AND __DATE_R2__
    RETURN DISTINCT src AS source, sibling.ticker AS target, parent.ticker AS parent
    LIMIT 200
    """
    try:
        q = q.replace("__DATE_R1__", _edge_active_after_clause("r1")).replace("__DATE_R2__", _edge_active_after_clause("r2"))
        result = session.run(q, tickers=list(tickers), as_of_date=as_of_date or "")
        return [
            {"source": rec["source"], "target": rec["target"], "parent": rec.get("parent", "")}
            for rec in result if rec.get("target")
        ]
    except Exception as e:
        _log(f"Conglomerate exposure query error: {e}", "yellow")
        return []


# ──────────────────────────────────────────────────────────────────────────────
# Contagion propagation engine
# ──────────────────────────────────────────────────────────────────────────────

_NEO4J_SNAPSHOT_DEFAULT_LRU_CAP = 256


def _neo4j_cached_query(
    strategy_cache: dict | None,
    config: dict,
    query_name: str,
    seeds,
    date_key: str,
    query_fn,
):
    """Phase α.2 (2026-05-18, BT109429 follow-up): cache Neo4j query
    results to reduce cross-bar variance in paired backtest re-runs.

    The variance/robustness agent attributed 25-35% of the 4.8x same-code
    spread to graph-propagation seed sensitivity. If Neo4j is mutated
    externally (e.g., a re-index running concurrently with a backtest),
    per-bar queries drift. Snapshotting per ISO week locks the propagation
    graph against external mutation across the snapshot window.

    Snapshot granularity (``nexus_neo4j_snapshot_granularity`` config):
      * ``"weekly"`` (default): one snapshot per ISO-week of ``date_key``.
      * ``"once"``: one snapshot for the entire backtest run.
      * ``"off"``: no snapshot — pass-through to ``query_fn``.

    Live mode (``_GN_LIVE_MODE_FLAG=True``) ALWAYS bypasses the snapshot
    so production trading sees fresh graph state.

    Cache lives at ``strategy_cache["_neo4j_snapshot"]`` (an ``OrderedDict``
    with LRU eviction, default cap 256 — tunable via
    ``nexus_neo4j_snapshot_lru_cap``). Cleared per backtest restart via
    persistence blacklist + migration_reset_keys.

    **Mutation contract**: callers MUST treat the returned list/dict as
    read-only. The helper does not deep-copy — mutating the result
    pollutes the snapshot for subsequent same-key calls. All current
    consumers in ``_compute_propagated_scores`` only iterate; if a new
    caller needs to mutate, they must shallow-copy first.
    """
    if _GN_LIVE_MODE_FLAG or not isinstance(strategy_cache, dict):
        return query_fn()
    # Bare import (not `backend.`) because prod Docker layout is flat at /app/.
    from _phase_alpha_helpers import neo4j_snapshot_key as _neo4j_snapshot_key
    key_pair = _neo4j_snapshot_key(query_name, seeds, date_key, config)
    if key_pair is None:
        # granularity="off" OR broken iterable — bypass cache.
        return query_fn()
    cache_key, _granularity = key_pair
    import collections as _collections_local
    snapshot = strategy_cache.setdefault("_neo4j_snapshot", _collections_local.OrderedDict())
    # If a prior helper version stored a plain dict, migrate to OrderedDict
    # in place so LRU semantics work going forward.
    if not isinstance(snapshot, _collections_local.OrderedDict):
        snapshot = _collections_local.OrderedDict(snapshot)
        strategy_cache["_neo4j_snapshot"] = snapshot
    if cache_key in snapshot:
        # LRU hit: bump to MRU end.
        try:
            snapshot.move_to_end(cache_key, last=True)
        except KeyError:  # pragma: no cover — racy delete; treat as miss
            pass
        else:
            stats = strategy_cache.setdefault("_neo4j_snapshot_stats", {"hits": 0, "misses": 0})
            stats["hits"] = int(stats.get("hits", 0) or 0) + 1
            return snapshot[cache_key]
    result = query_fn()
    snapshot[cache_key] = result
    # LRU eviction: pop oldest if over cap. Default 256 entries is generous
    # — a 6-month backtest produces ~26 weeks * 11 query types = ~286
    # entries; 256 fits the common case without spilling, and overflow
    # weeks evict cleanly. Operators can tune via the config knob.
    try:
        cap = max(8, int(config.get(
            "nexus_neo4j_snapshot_lru_cap",
            _NEO4J_SNAPSHOT_DEFAULT_LRU_CAP,
        ) or _NEO4J_SNAPSHOT_DEFAULT_LRU_CAP))
    except (TypeError, ValueError):
        cap = _NEO4J_SNAPSHOT_DEFAULT_LRU_CAP
    while len(snapshot) > cap:
        try:
            snapshot.popitem(last=False)
        except KeyError:  # pragma: no cover
            break
    stats = strategy_cache.setdefault("_neo4j_snapshot_stats", {"hits": 0, "misses": 0})
    stats["misses"] = int(stats.get("misses", 0) or 0) + 1
    return result


def _build_sector_map_for_aug(driver, tickers: set, strategy_cache) -> dict[str, str]:
    """η.B' helper: return {ticker: sector_name} for the given tickers.

    Cached per-run in strategy_cache["_eta_sector_map"]. Sectors don't
    change mid-backtest so the cache is sound for the full run.
    Uses OPTIONAL MATCH so tickers without an IN_SECTOR edge get a
    sentinel "" entry (rather than being absent and re-queried every
    bar — the original implementation had a negative-cache trap that
    caused permanent re-querying). `_max_peer_raw_in_sector` already
    treats "" sector as "no peer" via `if not sec: return 0.0`.
    Returns empty dict if Neo4j unavailable AND nothing cached.
    Tracks failures in strategy_cache["_eta_sector_map_failed_calls"]
    so a connectivity bug after the first successful query surfaces in
    the per-bar telemetry instead of silently zeroing out η.B'.
    """
    if not tickers:
        return {}
    if isinstance(strategy_cache, dict):
        _cached = strategy_cache.get("_eta_sector_map")
        if isinstance(_cached, dict):
            _need = [t for t in tickers if t not in _cached]
            if not _need:
                return {t: _cached[t] for t in tickers if t in _cached}
        else:
            strategy_cache["_eta_sector_map"] = {}
            _need = list(tickers)
        _cache_dict = strategy_cache["_eta_sector_map"]
    else:
        _cache_dict = {}
        _need = list(tickers)
    if not driver:
        return {t: _cache_dict[t] for t in tickers if t in _cache_dict}
    try:
        with driver.session() as session:
            result = session.run(
                "MATCH (c:Company) WHERE c.ticker IN $tickers "
                "OPTIONAL MATCH (c)-[:IN_SECTOR]->(s) "
                "RETURN c.ticker AS ticker, s.name AS sector",
                tickers=list(_need),
            )
            _need_set = {str(t).strip().upper() for t in _need}
            _seen: set[str] = set()
            for row in result:
                tk = row.get("ticker")
                sec = row.get("sector")
                if not isinstance(tk, str):
                    continue
                _tk_u = tk.strip().upper()
                _seen.add(_tk_u)
                # OPTIONAL MATCH returns sec=None when no IN_SECTOR edge.
                # Cache sentinel "" so we don't re-query this ticker.
                _cache_dict[_tk_u] = sec if isinstance(sec, str) else ""
            # Tickers absent from the result entirely (no Company node).
            # Cache sentinel so they don't re-query indefinitely.
            for _missing in _need_set - _seen:
                _cache_dict[_missing] = ""
    except Exception as e:
        if isinstance(strategy_cache, dict):
            _fail_n = int(strategy_cache.get("_eta_sector_map_failed_calls", 0) or 0)
            strategy_cache["_eta_sector_map_failed_calls"] = _fail_n + 1
            if _fail_n == 0:
                _log(
                    f"[ETA.B] _build_sector_map_for_aug FAILED (fail-open, "
                    f"first occurrence — subsequent failures counted in "
                    f"strategy_cache._eta_sector_map_failed_calls): {e}",
                    "red",
                )
        else:
            _log(f"[ETA.B] _build_sector_map_for_aug failed (fail-open): {e}", "yellow")
    return {t: _cache_dict[t] for t in tickers if t in _cache_dict}


def _max_peer_raw_in_sector(ticker: str, aggregated: dict, sector_map: dict) -> float:
    """η.B' helper: return the maximum raw_score among aggregated entries
    whose ticker is in the same sector as the input ticker (excluding the
    ticker itself). Returns 0.0 if no peer or sector unknown.
    """
    sec = sector_map.get(ticker)
    if not sec:
        return 0.0
    best = 0.0
    for peer, doc in aggregated.items():
        if peer == ticker:
            continue
        if sector_map.get(peer) != sec:
            continue
        raw = float(doc.get("raw_score", 0.0) or 0.0)
        if raw > best:
            best = raw
    return best


def _cap_propagation_fanout_per_seed(edges: list[dict], config: dict) -> list[dict]:
    """Cap how many 1-hop propagation edges a single source ("seed") contributes,
    keeping the strongest-coupled neighbors (by confidence, then revenue_pct).

    Prevents one news item (e.g. a HOOD earnings hit) from injecting its entire
    COMPETES_WITH cohort (~90+ names at one score) into scoring and flooding the
    propagation/backfill queue. Disabled (returns the same list object, no-op)
    when propagation_max_per_seed <= 0.
    """
    max_per_seed = int(config.get("propagation_max_per_seed", 0) or 0)
    if max_per_seed <= 0 or not edges:
        return edges
    by_source: dict[str, list[dict]] = {}
    for e in edges:
        by_source.setdefault(str(e.get("source") or ""), []).append(e)
    keep: set[int] = set()
    for group in by_source.values():
        if len(group) <= max_per_seed:
            keep.update(id(e) for e in group)
        else:
            ranked = sorted(
                group,
                key=lambda e: (
                    float(e.get("confidence", 0.0) or 0.0),
                    float(e.get("revenue_pct", 0.0) or 0.0),
                ),
                reverse=True,
            )[:max_per_seed]
            keep.update(id(e) for e in ranked)
    return [e for e in edges if id(e) in keep]


def _institutional_cache_binding(
    context,
    base_instance_id: str,
    date_key: str,
) -> tuple[str, dict[str, str]]:
    """Return persistent cache identity bound to strict graph decision time."""

    base = str(base_instance_id or "default")[:24]
    if not _pit_use_legacy_sources(context):
        from point_in_time_data import PointInTimeContext, PointInTimeDataError

        if not isinstance(context, PointInTimeContext) or not context.strict:
            raise PointInTimeDataError(
                "historical institutional cache context must be strict"
            )
        manifest_id = context.manifest.manifest_id
        as_of = context.as_of.isoformat().replace("+00:00", "Z")
        return (
            f"inst_co_holdings|{base}|{manifest_id}|{as_of}",
            {"manifest_id": manifest_id, "as_of": as_of},
        )
    return f"inst_co_holdings|{base}|{date_key[:7]}", {}


def _institutional_cache_row_matches(row: dict, context) -> bool:
    """True when a persistent co-holdings row belongs to the exact PIT scope."""

    if not isinstance(row, dict):
        return False
    if _pit_use_legacy_sources(context):
        return True
    if not context.strict:
        return False
    expected_manifest = context.manifest.manifest_id
    expected_as_of = context.as_of.isoformat().replace("+00:00", "Z")
    return (
        str(row.get("manifest_id") or "") == expected_manifest
        and str(row.get("as_of") or "") == expected_as_of
    )


def _compute_propagated_scores(
    driver,
    sentiment_data: dict,
    symbols_list: list,
    config: dict,
    date_key: str = "",
    strategy_cache: dict | None = None,
) -> dict:
    """
    Full graph contagion engine. Takes LLM sentiment data, traverses Neo4j graph
    through multiple relationship types and hops, applies directional and event-aware
    propagation weights, and aggregates multi-path influence per ticker.

    Args:
        driver: Neo4j driver
        sentiment_data: dict[ticker -> {"sentiment": int, "event": str}]
        symbols_list: list of tickers in the trading universe
        config: strategy configuration
        date_key: ISO date for the bar being scored (drives Phase α.2
            ISO-week snapshot keying).
        strategy_cache: optional run_once-level cache. When provided in
            backtest mode, enables the Phase α.2 Neo4j snapshot
            (cleared per backtest restart). Pass-through in live mode.

    Returns:
        dict[ticker -> {"raw_score": float, "reasons": list[str]}]
    """
    if not driver or not sentiment_data:
        return {}

    mentioned = set(sentiment_data.keys())
    # ticker -> list of (score_contribution, reason_string)
    contributions: dict[str, list[tuple[float, str]]] = {}

    # Seed: directly mentioned tickers get full sentiment as their first contribution
    for ticker, data in sentiment_data.items():
        s = data["sentiment"]
        if s != 0:
            contributions.setdefault(ticker, []).append(
                (float(s), f"direct: sentiment={s:+d} event={data['event']}")
            )

    try:
        with driver.session() as session:
            session.run("RETURN 1").consume()
    except Exception as e:
        _log(
            "Neo4j unavailable (connection refused or error). Start Neo4j or set NEO4J_URI / neo4j_* in config. Graph propagation disabled for this run: " + str(e),
            "yellow",
        )
        return {}

    n_seed = sum(1 for d in sentiment_data.values() if d.get("sentiment") != 0)
    with driver.session() as session:
        # Discover which relationship types exist in the DB; use only those (avoids "not available" warnings)
        _log("Graph metadata: relationship type discovery start", "cyan")
        available = _neo4j_cached_query(
            strategy_cache, config, "available_rels", None, date_key,
            lambda: _get_available_relationship_types(session),
        )
        _log(f"Graph metadata: relationship type discovery done | count={len(available)}", "cyan")
        rels_1hop = [r for r in _REL_TYPES_1HOP if r in available]
        rels_2hop = [r for r in _REL_TYPES_2HOP if r in available]
        _log(
            f"Graph: {n_seed} seed tickers | as_of={date_key or 'latest'} | 1-hop rels: {rels_1hop or '(none)'} | 2-hop rels: {rels_2hop or '(none)'} | sector: {'yes' if 'IN_SECTOR' in available else 'no'} | macro-flow: {'yes' if 'SUPPLIES_TO_SECTOR' in available else 'no'} | institutional: {'yes' if 'HOLDS' in available else 'no'}",
            "cyan",
        )
        # ── Kick off the slow institutional co-holdings query as a bg future
        # so it overlaps with the cheap 1-hop / sector / 2-hop queries below.
        # In backtest 419346 this query was 37s of the 41s Neo4j budget; the
        # rest collectively were ~4s. Each thread needs its OWN driver.session()
        # — neo4j-python sessions are not thread-safe.
        use_inst = config.get("use_institutional_correlation", True)
        _inst_co_holdings_fut = None
        _inst_snapshot_key: str | None = None  # set when α.2 snapshot is in play
        _inst_seed_cap = int(config.get("institutional_seed_cap", 50) or 50)
        if use_inst and "HOLDS" in available and config.get("_inst_co_holdings_cache") is None:
            # Phase η bug-sweep: η.A seeds tickers with event="momentum_breakout"
            # (a technical-momentum signal with no LLM news backing); treat it
            # the same as its sibling "trend_momentum" for institutional-HOLDS
            # propagation (i.e. excluded — institutional seeding should track
            # news-derived sentiment, not engine-internal technical seeds).
            _INST_EXCLUDE_EVENTS = {"trend_momentum", "momentum_breakout"}
            _inst_seeds = {
                t for t, d in sentiment_data.items()
                if d.get("sentiment", 0) != 0
                and d.get("event", "") not in _INST_EXCLUDE_EVENTS
            }
            _inst_pre_filter = len(_inst_seeds)
            if len(_inst_seeds) > _inst_seed_cap:
                _inst_seeds = set(sorted(_inst_seeds)[:_inst_seed_cap])
            # Phase α.2 bug-sweep follow-up (2026-05-18): the institutional bg
            # query was originally uncached and contributed ~15-25% of the
            # remaining graph variance. Snapshot lookup BEFORE the bg launch:
            # cache hit → set `_inst_co_holdings_cache` (which retrieval at
            # line ~14681 already honors) and skip the thread; cache miss →
            # launch as before and store after retrieval.
            _inst_snap_pair = None
            if not _GN_LIVE_MODE_FLAG and isinstance(strategy_cache, dict):
                # Bare import (not `backend.`) because prod Docker is flat at /app/.
                from _phase_alpha_helpers import (
                    neo4j_snapshot_key as _neo4j_snapshot_key_local,
                )
                _inst_snap_pair = _neo4j_snapshot_key_local(
                    "inst_co_holdings", _inst_seeds, date_key, config,
                )
            if _inst_snap_pair is not None:
                _inst_snapshot_key, _ = _inst_snap_pair
                _inst_snap_dict = strategy_cache.get("_neo4j_snapshot") if isinstance(strategy_cache, dict) else None
                if _inst_snap_dict is not None and _inst_snapshot_key in _inst_snap_dict:
                    config["_inst_co_holdings_cache"] = _inst_snap_dict[_inst_snapshot_key]
                    _log(
                        f"  Institutional co-holdings query: snapshot cache HIT "
                        f"(seeds={len(_inst_seeds)})",
                        "cyan",
                    )
                    _inst_co_holdings_fut = None
            if config.get("_inst_co_holdings_cache") is None:
                _log(
                    f"  Institutional co-holdings query: start (bg) | "
                    f"seeds={len(_inst_seeds)} (filtered={_inst_pre_filter} of {len(mentioned)} mentioned"
                    f"{', capped' if _inst_pre_filter > _inst_seed_cap else ''})",
                    "cyan",
                )
                def _inst_co_holdings_worker(_seeds=_inst_seeds, _dk=date_key):
                    # New session per thread — neo4j-python sessions are not thread-safe.
                    with driver.session() as _bg_inst_session:
                        return _query_institutional_co_holdings(_bg_inst_session, _seeds, as_of_date=_dk)
                from concurrent.futures import ThreadPoolExecutor as _InstTPE
                _inst_executor = _InstTPE(max_workers=1)
                _inst_co_holdings_fut = _inst_executor.submit(_inst_co_holdings_worker)
                _inst_executor.shutdown(wait=False)

        # ── 1-hop: relationship-aware directional propagation ──────────────
        _log(f"  1-hop query out: start | seeds={len(mentioned)} | rels={len(rels_1hop)}", "cyan")
        out_edges = _neo4j_cached_query(
            strategy_cache, config, "1hop_out", mentioned, date_key,
            lambda: _query_1hop(session, mentioned, "out", rels_1hop, as_of_date=date_key),
        )
        _log(f"  1-hop query out: done | edges={len(out_edges)}", "cyan")
        _log(f"  1-hop query in: start | seeds={len(mentioned)} | rels={len(rels_1hop)}", "cyan")
        in_edges = _neo4j_cached_query(
            strategy_cache, config, "1hop_in", mentioned, date_key,
            lambda: _query_1hop(session, mentioned, "in", rels_1hop, as_of_date=date_key),
        )
        _log(f"  1-hop query in: done | edges={len(in_edges)}", "cyan")
        all_1hop = out_edges + in_edges
        # B (2026-05-26): cap per-seed fan-out so one news item (e.g. a HOOD
        # earnings hit) can't inject its whole COMPETES_WITH cohort. No-op when
        # propagation_max_per_seed <= 0.
        all_1hop = _cap_propagation_fanout_per_seed(all_1hop, config)

        for edge in all_1hop:
            src_data = sentiment_data.get(edge["source"])
            if not src_data or src_data["sentiment"] == 0:
                continue

            s = src_data["sentiment"]
            event = src_data["event"]
            rel = edge["rel"]
            direction = edge["direction"]
            conf = edge["confidence"]
            rev_pct = edge["revenue_pct"]

            key = (rel, direction)
            if key not in _PROPAGATION:
                continue
            base_factor, invert = _PROPAGATION[key]

            # Event amplification: supply_disruption boosts SUPPLIER_OF 1.5x, etc.
            amp = _EVENT_AMPLIFIERS.get(event, {}).get(rel, 1.0)
            factor = base_factor * amp

            # Revenue concentration bonus: higher % = tighter coupling
            # 10% → 1.0x, 20% → 1.12x, 50% → 1.50x, capped at 1.50x
            if rev_pct is not None and rev_pct > 10.0:
                rev_bonus = 1.0 + min(0.50, (rev_pct - 10.0) / 80.0)
                factor *= rev_bonus

            # Government contract obligation bonus (CONTRACTS_WITH)
            obligation = edge.get("total_obligation")
            if rel == "CONTRACTS_WITH" and obligation is not None and obligation > 0:
                # >$100M = 1.2x, >$1B = 1.4x
                if obligation >= 1_000_000_000:
                    factor *= 1.4
                elif obligation >= 100_000_000:
                    factor *= 1.2

            # Patent partnership depth bonus (PATENT_PARTNER)
            patent_count = edge.get("patent_count", 0)
            if rel == "PATENT_PARTNER" and patent_count > 0:
                # 1 patent = 1.05x, 10 = 1.5x, 20+ = 1.5x cap
                patent_bonus = 1.0 + min(0.50, patent_count / 20.0)
                factor *= patent_bonus

            # Apply: propagated = sentiment * factor * edge_confidence
            propagated = float(s) * factor * conf
            if invert:
                propagated = -propagated

            arrow = "\u2192" if direction == "out" else "\u2190"
            reason = f"1-hop {rel}({arrow}{edge['source']}): s={s:+d} f={factor:.2f} c={conf:.2f}"
            if invert:
                reason += " [inv]"
            if rev_pct and rev_pct > 10:
                reason += f" [rev={rev_pct:.0f}%]"
            if obligation and obligation >= 100_000_000:
                reason += f" [obl=${obligation/1e6:.0f}M]"
            if patent_count > 0:
                reason += f" [pat={patent_count}]"

            contributions.setdefault(edge["target"], []).append((propagated, reason))

        _log(f"  1-hop: {len(out_edges)} out, {len(in_edges)} in (total {len(all_1hop)} edges)", "cyan")

        # ── Sector peer propagation (only if IN_SECTOR exists) ─────────────
        sector_edges = []
        if "IN_SECTOR" in available:
            _log(f"  Sector peer query: start | seeds={len(mentioned)}", "cyan")
            sector_edges = _neo4j_cached_query(
                strategy_cache, config, "sector_peers", mentioned, date_key,
                lambda: _query_sector_peers(session, mentioned, as_of_date=date_key),
            )
            _log(f"  Sector peer query: done | edges={len(sector_edges)}", "cyan")
        else:
            _log("  Sector peers: skipped (IN_SECTOR not in graph)", "cyan")
        sector_wt = float(config.get("sector_propagation_weight", _SECTOR_PROPAGATION_FACTOR))

        for edge in sector_edges:
            src_data = sentiment_data.get(edge["source"])
            if not src_data or src_data["sentiment"] == 0:
                continue
            s = src_data["sentiment"]
            event = src_data["event"]
            amp = _EVENT_AMPLIFIERS.get(event, {}).get("IN_SECTOR", 1.0)
            propagated = float(s) * sector_wt * amp

            sector = edge.get("sector", "?")
            reason = f"sector({sector}\u2190{edge['source']}): s={s:+d} wt={sector_wt * amp:.2f}"
            contributions.setdefault(edge["target"], []).append((propagated, reason))

        _log(f"  Sector peers: {len(sector_edges)} edges", "cyan")

        # ── Macro sector-to-sector supply flow (BEA I-O) ─────────────────
        # Propagate through inter-sector supply dependencies for macro-relevant events
        macro_edges = []
        if "SUPPLIES_TO_SECTOR" in available and "IN_SECTOR" in available:
            _log(f"  Macro sector flow query: start | seeds={len(mentioned)}", "cyan")
            macro_edges = _neo4j_cached_query(
                strategy_cache, config, "macro_sector_flow", mentioned, date_key,
                lambda: _query_macro_sector_flow(session, mentioned, as_of_date=date_key),
            )
            _log(f"  Macro sector flow query: done | edges={len(macro_edges)}", "cyan")
            # Normalize flow_value: find max to scale relative importance
            max_flow = max((e["flow_value"] for e in macro_edges), default=1.0) or 1.0
            _MACRO_BASE_FACTOR = 0.15
            _MACRO_EVENTS = {"supply_disruption", "regulatory", "earnings"}

            for edge in macro_edges:
                src_data = sentiment_data.get(edge["source"])
                if not src_data or src_data["sentiment"] == 0:
                    continue
                event = src_data["event"]
                if event not in _MACRO_EVENTS:
                    continue
                s = src_data["sentiment"]
                # Scale by relative flow importance (0.5x to 1.5x of base)
                flow_scale = 0.5 + (edge["flow_value"] / max_flow)
                macro_factor = _MACRO_BASE_FACTOR * flow_scale
                propagated_val = float(s) * macro_factor

                reason = f"macro-flow({edge['from_sector']}\u2192{edge['to_sector']}\u2190{edge['source']}): s={s:+d} f={macro_factor:.3f}"
                contributions.setdefault(edge["target"], []).append((propagated_val, reason))

            _log(f"  Macro sector flow: {len(macro_edges)} edges", "cyan")
        elif "SUPPLIES_TO_SECTOR" not in available:
            _log("  Macro sector flow: skipped (SUPPLIES_TO_SECTOR not in graph)", "cyan")

        # ── 2-hop: strong directional chain propagation ───────────────────
        max_hops = int(config.get("max_hops", 2))
        if max_hops >= 2 and rels_2hop:
            _log(f"  2-hop query out: start | seeds={len(mentioned)} | rels={len(rels_2hop)}", "cyan")
            hop2_out = _neo4j_cached_query(
                strategy_cache, config, "2hop_out", mentioned, date_key,
                lambda: _query_2hop_chains(session, mentioned, "out", rels_2hop, as_of_date=date_key),
            )
            _log(f"  2-hop query out: done | edges={len(hop2_out)}", "cyan")
            _log(f"  2-hop query in: start | seeds={len(mentioned)} | rels={len(rels_2hop)}", "cyan")
            hop2_in = _neo4j_cached_query(
                strategy_cache, config, "2hop_in", mentioned, date_key,
                lambda: _query_2hop_chains(session, mentioned, "in", rels_2hop, as_of_date=date_key),
            )
            _log(f"  2-hop query in: done | edges={len(hop2_in)}", "cyan")
            all_2hop = hop2_out + hop2_in

            for edge in all_2hop:
                src_data = sentiment_data.get(edge["source"])
                if not src_data or src_data["sentiment"] == 0:
                    continue

                s = src_data["sentiment"]
                direction = edge["direction"]
                # Chain propagation: factor(r1) * factor(r2) * decay
                key1 = (edge["rel1"], direction)
                key2 = (edge["rel2"], direction)
                f1, inv1 = _PROPAGATION.get(key1, (0.3, False))
                f2, inv2 = _PROPAGATION.get(key2, (0.3, False))
                chained = f1 * f2 * _2HOP_DECAY
                combined_conf = edge["combined_conf"]

                propagated = float(s) * chained * combined_conf
                # Invert if odd number of inversions in the chain
                if inv1 != inv2:
                    propagated = -propagated

                chain = f"{edge['rel1']}\u2192{edge['rel2']}"
                reason = f"2-hop {chain}(via {edge['source']}): s={s:+d} f={chained:.3f} c={combined_conf:.2f}"
                contributions.setdefault(edge["target"], []).append((propagated, reason))

            _log(f"  2-hop: {len(hop2_out)} out, {len(hop2_in)} in (total {len(all_2hop)} edges)", "cyan")
        elif max_hops >= 2 and not rels_2hop:
            _log("  2-hop: skipped (no 2-hop relationship types in graph)", "cyan")

        # ── Institutional co-holding (only if HOLDS exists) ──────────────────
        # `use_inst` was computed above (alongside the bg future kickoff).
        if use_inst and "HOLDS" in available:
            _inst_cache = config.get("_inst_co_holdings_cache")
            if _inst_cache is not None:
                inst_edges = _inst_cache
                _log(f"  Institutional co-holdings: reused cache | edges={len(inst_edges)}", "cyan")
            elif _inst_co_holdings_fut is not None:
                # Future was kicked off above — just collect the result. Most
                # of the time it's already done because the 1-hop / sector /
                # 2-hop queries take ~4s and the institutional query is ~37s.
                try:
                    inst_edges = _inst_co_holdings_fut.result(timeout=120)
                except Exception as _inst_exc:
                    _log(f"  Institutional co-holdings query failed: {_inst_exc}", "yellow")
                    inst_edges = []
                _log(f"  Institutional co-holdings query: done | edges={len(inst_edges)}", "cyan")
                # Phase α.2 bug-sweep follow-up: store the bg result in the
                # snapshot so subsequent same-week bars hit cache (the bg
                # query was the largest single uncached variance source).
                if (
                    _inst_snapshot_key
                    and not _GN_LIVE_MODE_FLAG
                    and isinstance(strategy_cache, dict)
                ):
                    _inst_snap_store = strategy_cache.setdefault("_neo4j_snapshot", None)
                    if _inst_snap_store is None:
                        import collections as _collections_inst
                        _inst_snap_store = _collections_inst.OrderedDict()
                        strategy_cache["_neo4j_snapshot"] = _inst_snap_store
                    _inst_snap_store[_inst_snapshot_key] = inst_edges
            else:
                # Defensive fallback — sentiment_data became empty between the
                # bg-kickoff branch and here, or HOLDS lookup changed. Inline.
                # Phase η bug-sweep: include "momentum_breakout" alongside
                # "trend_momentum" — both are engine-internal technical
                # seeds without LLM news backing.
                _INST_EXCLUDE_EVENTS = {"trend_momentum", "momentum_breakout"}
                inst_seeds = {
                    t for t, d in sentiment_data.items()
                    if d.get("sentiment", 0) != 0
                    and d.get("event", "") not in _INST_EXCLUDE_EVENTS
                }
                _fallback_pre = len(inst_seeds)
                if len(inst_seeds) > _inst_seed_cap:
                    inst_seeds = set(sorted(inst_seeds)[:_inst_seed_cap])
                _log(
                    f"  Institutional co-holdings query: start (inline fallback) | "
                    f"seeds={len(inst_seeds)} (filtered={_fallback_pre} of {len(mentioned)} mentioned"
                    f"{', capped' if _fallback_pre > _inst_seed_cap else ''})",
                    "cyan",
                )
                # Phase α.2 bug-sweep: wrap the inline-fallback branch too.
                inst_edges = _neo4j_cached_query(
                    strategy_cache, config, "inst_co_holdings",
                    inst_seeds, date_key,
                    lambda: _query_institutional_co_holdings(session, inst_seeds, as_of_date=date_key),
                )
                _log(f"  Institutional co-holdings query: done | edges={len(inst_edges)}", "cyan")

            for edge in inst_edges:
                src_data = sentiment_data.get(edge["source"])
                if not src_data or src_data["sentiment"] == 0:
                    continue
                s = src_data["sentiment"]
                shared = edge["shared_count"]
                total_val = edge.get("total_value", 0)
                # Scale: 3 shared → 0.03, 5 → 0.05, 10+ → 0.10 (base)
                inst_factor = _INSTITUTIONAL_PROPAGATION_FACTOR * min(
                    1.0, shared / _INSTITUTIONAL_SCALE_DIVISOR
                )
                # High-overlap bonus: 10+ shared holders continue scaling up to 2.0x
                # at 40+ shared (e.g., 36 shared → 1.87x, 48 shared → 2.0x cap)
                if shared > _INSTITUTIONAL_SCALE_DIVISOR:
                    _ihod = config.get("institutional_high_overlap_divisor")
                    _inst_high_overlap_divisor = float(_ihod) if _ihod is not None else 30.0
                    _high_overlap_bonus = min(1.0, (shared - _INSTITUTIONAL_SCALE_DIVISOR) / _inst_high_overlap_divisor)
                    inst_factor *= (1.0 + _high_overlap_bonus)
                    # Hard cap: institutional factor alone must not exceed buy threshold
                    _inst_cap = float(config.get("institutional_factor_cap", 0.15) or 0.15)
                    inst_factor = min(inst_factor, _inst_cap)
                # Position-size bonus: log10(total_value) scaled
                # $1M=1.0x, $100M=1.33x, $1B=1.5x, $10B=1.67x, capped at 2.0x
                if total_val > 1_000_000:
                    val_mult = min(2.0, 1.0 + math.log10(total_val / 1_000_000) / 6.0)
                    inst_factor *= val_mult
                propagated_val = float(s) * inst_factor

                reason = f"institutional({shared} shared\u2190{edge['source']}): s={s:+d} f={inst_factor:.3f}"
                if total_val > 1_000_000:
                    reason += f" [val=${total_val/1e6:.0f}M]"
                contributions.setdefault(edge["target"], []).append((propagated_val, reason))

            _log(f"  Institutional co-holdings: {len(inst_edges)} edges", "cyan")

        # ── Supply chain concentration risk ──────────────────────────────
        # Companies with few suppliers are more vulnerable to supply disruption news
        if "SUPPLIER_OF" in available:
            all_affected = mentioned | {e["target"] for e in all_1hop}
            _log(f"  Supply chain concentration query: start | tickers={len(all_affected)}", "cyan")
            sc_conc = _neo4j_cached_query(
                strategy_cache, config, "supply_chain_conc", all_affected, date_key,
                lambda: _query_supply_chain_concentration(session, all_affected, as_of_date=date_key),
            )
            _log(f"  Supply chain concentration query: done | tickers={len(sc_conc)}", "cyan")
            for ticker, counts in sc_conc.items():
                if ticker not in contributions:
                    continue
                sup_count = counts["supplier_count"]
                # Amplify negative supply-chain signals for companies with few suppliers (concentration risk)
                if sup_count > 0 and sup_count <= 3:
                    for i, (score, reason) in enumerate(contributions[ticker]):
                        if score < 0 and ("SUPPLIER_OF" in reason or "supply" in reason.lower()):
                            # Concentrate: 1 supplier = 1.5x, 2 = 1.3x, 3 = 1.15x
                            conc_mult = 1.0 + 0.5 / sup_count
                            contributions[ticker][i] = (score * conc_mult, reason + f" [conc={sup_count}sup]")
            _log(f"  Supply chain concentration: analyzed {len(sc_conc)} tickers", "cyan")

        # ── Competitive overlap: shared supply chains ────────────────────
        # Competitors who share suppliers: negative news on one benefits the other more strongly
        if "COMPETES_WITH" in available and "SUPPLIER_OF" in available:
            _log(f"  Competitive overlap query: start | seeds={len(mentioned)}", "cyan")
            comp_overlap = _neo4j_cached_query(
                strategy_cache, config, "competitive_overlap", mentioned, date_key,
                lambda: _query_competitive_overlap(session, mentioned, as_of_date=date_key),
            )
            _log(f"  Competitive overlap query: done | edges={len(comp_overlap)}", "cyan")
            for edge in comp_overlap:
                src_data = sentiment_data.get(edge["source"])
                if not src_data or src_data["sentiment"] == 0:
                    continue
                s = src_data["sentiment"]
                shared = edge["shared_suppliers"]
                # Negative news on competitor with shared suppliers = stronger buy signal for target
                # (you can capture their supply contracts and market share)
                overlap_factor = 0.15 * min(1.0, shared / 5.0)
                propagated = float(-s) * overlap_factor  # inverted: competitor's loss is your gain
                reason = f"comp-overlap({edge['source']},{shared}shared-sup): s={s:+d} f={overlap_factor:.2f} [inv]"
                contributions.setdefault(edge["target"], []).append((propagated, reason))
            _log(f"  Competitive supply overlap: {len(comp_overlap)} edges", "cyan")

        # ── Conglomerate sibling exposure ────────────────────────────────
        # Subsidiaries of the same parent: news at one sibling signals parent-level issues
        if "PARENT_OF" in available or "CONTROLS" in available:
            _log(f"  Conglomerate sibling query: start | seeds={len(mentioned)}", "cyan")
            sibling_edges = _neo4j_cached_query(
                strategy_cache, config, "conglomerate", mentioned, date_key,
                lambda: _query_conglomerate_exposure(session, mentioned, as_of_date=date_key),
            )
            _log(f"  Conglomerate sibling query: done | edges={len(sibling_edges)}", "cyan")
            for edge in sibling_edges:
                src_data = sentiment_data.get(edge["source"])
                if not src_data or src_data["sentiment"] == 0:
                    continue
                s = src_data["sentiment"]
                # Siblings share parent risk: moderate propagation
                sibling_factor = 0.35
                propagated = float(s) * sibling_factor
                reason = f"sibling(via parent {edge['parent']},{edge['source']}): s={s:+d} f={sibling_factor:.2f}"
                contributions.setdefault(edge["target"], []).append((propagated, reason))
            _log(f"  Conglomerate siblings: {len(sibling_edges)} edges", "cyan")

        # ── Institutional momentum amplifier ─────────────────────────────
        # Heavily-held stocks (many institutional holders) get amplified signals:
        # institutional herding means the stock moves more on sentiment shifts
        if use_inst and "HOLDS" in available:
            _log(f"  Institutional momentum query: start | seeds={len(mentioned)}", "cyan")
            holder_counts = _neo4j_cached_query(
                strategy_cache, config, "inst_holders_count", mentioned, date_key,
                lambda: _query_institutional_holders_count(session, mentioned, as_of_date=date_key),
            )
            _log(f"  Institutional momentum query: done | tickers={len(holder_counts)}", "cyan")
            for ticker, count in holder_counts.items():
                if ticker not in contributions or count < 10:
                    continue
                # Scale: 10 holders = 1.05x, 50 = 1.15x, 100+ = 1.20x (subtle amplification)
                inst_amp = 1.0 + min(0.20, count / 500.0)
                for i, (score, reason) in enumerate(contributions[ticker]):
                    if "direct:" in reason:
                        contributions[ticker][i] = (score * inst_amp, reason + f" [inst-mom={count}]")
            _log(f"  Institutional momentum: {len(holder_counts)} tickers analyzed", "cyan")

    # ── Aggregate multi-path contributions per ticker ─────────────────────
    # Sort by magnitude (strongest signal first), then apply diminishing returns:
    # total = c[0] + c[1]*0.5 + c[2]*0.25 + ... (prevents edge-count blowup)
    aggregated = {}
    for ticker, contribs in contributions.items():
        if not contribs:
            continue
        # Tiebreak on the contributor id. The decay below is POSITION-weighted
        # (0.5**i), so two tied contributions of opposite sign swapping places
        # flips the aggregate's sign -- +0.175 becomes -0.175, a buy becomes a
        # sell -- purely on dict/set ordering.
        contribs.sort(key=lambda x: (-abs(x[0]), str(x[1])))
        total = contribs[0][0]
        for i, (score, _) in enumerate(contribs[1:], 1):
            total += score * (0.5 ** i)
        total = max(-1.0, min(1.0, total))
        reasons = [r for _, r in contribs[:5]]
        aggregated[ticker] = {"raw_score": total, "reasons": reasons, "n_paths": len(contribs)}

    # η.B' — Phase η (2026-05-20): post-aggregation sector-peer
    # augmentation for momentum_watchlist tickers whose geometric-sum
    # raw_score landed below threshold. Defensive belt-and-suspenders
    # on top of existing IN_SECTOR / COMPETES_WITH propagation. Tagged
    # with distinct "eta_b_aug" reason to make telemetry grep-able.
    if config.get("eta_sector_augmentation_enabled", True):
        _eta_b_thr = float(config.get("eta_augment_below_raw", 0.5) or 0.5)
        _eta_b_fac = float(config.get("eta_augment_peer_factor", 0.3) or 0.3)
        _eta_b_top_n = int(config.get("eta_augment_top_n", 5) or 5)
        # Production schema fix (bug-sweep): scores live in
        # _momentum_ranked_cache (list[(ticker, score)] sorted desc), not
        # in _momentum_watchlist values. Intersect ranked-cache with
        # current watchlist membership to get the top-N momentum tickers.
        _eta_b_mw_ranked = (
            strategy_cache.get("_momentum_ranked_cache", []) or []
            if isinstance(strategy_cache, dict) else []
        )
        _eta_b_mw_members = (
            set((strategy_cache.get("_momentum_watchlist") or {}).keys())
            if isinstance(strategy_cache, dict) else set()
        )
        if _eta_b_mw_ranked and _eta_b_mw_members:
            _eta_b_mw: set[str] = set()
            for _eta_b_entry in _eta_b_mw_ranked:
                if len(_eta_b_mw) >= _eta_b_top_n:
                    break
                try:
                    _eta_b_cand = str(_eta_b_entry[0] or "").strip().upper()
                except (IndexError, TypeError):
                    continue
                if _eta_b_cand and _eta_b_cand in _eta_b_mw_members:
                    _eta_b_mw.add(_eta_b_cand)
            _eta_b_sector_map = _build_sector_map_for_aug(
                driver, _eta_b_mw, strategy_cache,
            )
            _eta_b_aug = 0
            for _eta_b_tk in _eta_b_mw:
                _eta_b_existing = aggregated.get(
                    _eta_b_tk,
                    {"raw_score": 0.0, "reasons": [], "n_paths": 0},
                )
                if float(_eta_b_existing.get("raw_score", 0.0)) >= _eta_b_thr:
                    continue
                _eta_b_peer = _max_peer_raw_in_sector(
                    _eta_b_tk, aggregated, _eta_b_sector_map,
                )
                if _eta_b_peer < _eta_b_thr:
                    continue
                _eta_b_new_raw = (
                    float(_eta_b_existing.get("raw_score", 0.0))
                    + _eta_b_peer * _eta_b_fac
                )
                # Prepend the eta_b_aug tag so it never gets truncated by
                # the 5-reason cap (bug-sweep: appending then slicing[:5]
                # would silently drop the tag when existing reasons==5).
                aggregated[_eta_b_tk] = {
                    "raw_score": max(-1.0, min(1.0, _eta_b_new_raw)),
                    "reasons": (
                        [f"eta_b_aug(peer={_eta_b_peer:.2f}*{_eta_b_fac})"]
                        + list(_eta_b_existing.get("reasons", []))[:4]
                    ),
                    "n_paths": int(_eta_b_existing.get("n_paths", 0)) + 1,
                }
                _eta_b_aug += 1
            if _eta_b_aug:
                _log(
                    f"[ETA.B] augmented {_eta_b_aug} momentum tickers "
                    f"(threshold={_eta_b_thr}, factor={_eta_b_fac})",
                    "cyan",
                )

    # Bug-sweep 2026-05-18: ALWAYS log aggregation outcome. The prior
    # `if aggregated:` gate hid the zero-tickers case (same antipattern as
    # the α.4 mcap-preseed silent-fail). Zero-aggregated could mean "no
    # seeds had nonzero sentiment", "all edges filtered out", or "no
    # relationship types in graph" — operators need to distinguish.
    if aggregated:
        top = sorted(aggregated.items(), key=lambda x: abs(x[1]["raw_score"]), reverse=True)[:5]
        parts = [f"{t}={v['raw_score']:+.3f}({v['n_paths']}p)" for t, v in top]
        _log(f"Aggregated: {len(aggregated)} tickers with paths | top raw: {', '.join(parts)}", "cyan")
    else:
        _log(
            f"Aggregated: 0 tickers with paths "
            f"(n_seed={n_seed}, mentioned={len(mentioned)}, "
            f"1hop_edges={len(all_1hop)}, contributions_dict={len(contributions)})",
            "red",
        )
    # Phase α.2 bug-sweep follow-up: emit snapshot stats once per bar so
    # operators can audit cache hit-rate without per-call log spam (11
    # queries × ~125 bars would be ~1400 lines/backtest otherwise).
    if isinstance(strategy_cache, dict):
        _snap_stats = strategy_cache.get("_neo4j_snapshot_stats")
        _snap_dict = strategy_cache.get("_neo4j_snapshot")
        if _snap_stats:
            _h = int(_snap_stats.get("hits", 0) or 0)
            _m = int(_snap_stats.get("misses", 0) or 0)
            _total = _h + _m
            _hit_rate = (_h / _total) if _total else 0.0
            _size = len(_snap_dict) if isinstance(_snap_dict, dict) else 0
            _log(
                f"neo4j snapshot: {_h}/{_total} hits ({_hit_rate:.0%}), "
                f"{_size} entries cached",
                "cyan",
            )
    # η — Phase η (2026-05-20): per-bar telemetry summary. η.B' is the
    # only Phase η component that fires inside _compute_propagated_scores
    # (η.A is in run_once, η.D in the V28.9 block, η.G in the V31 cap).
    # The per-event [ETA.X] lines remain the primary grep target; this
    # summary collects the propagation-stage components only when at
    # least one of them fires so logs stay quiet on bars where η is inert.
    _eta_b_aug_summary = locals().get("_eta_b_aug", 0) or 0
    if _eta_b_aug_summary:
        _log(
            f"[ETA] propagation summary: augmented={_eta_b_aug_summary}",
            "cyan",
        )
    return aggregated


# ──────────────────────────────────────────────────────────────────────────────
# Held-position risk evaluation (extracted from _finalize_scores for reuse
# by the dual-cadence monitor cycle). Behavior MUST be byte-equivalent to the
# previous inline block — see backend/tests/test_nexus_evaluate_position_risk.py.
# ──────────────────────────────────────────────────────────────────────────────

def _alert_risk_pipeline_skip(instance_id: str, sym: str) -> None:
    """Page operators when a held position's risk pipeline is silently bypassed.

    When a held position's current or entry price cannot be resolved, P&L is
    uncomputable and EVERY risk-exit gate (circuit-breaker, fast-loser,
    trailing-stop, ...) is skipped for that bar. That silent skip is exactly
    how a position can bleed past every loss floor uncut, so it must never
    fail quietly again.

    Reuses live_alerts' notify/_channel utility layer and the same lazy-import,
    try/except-wrapped, live-only (``_instance_id``) pattern as
    ``_apply_portfolio_drawdown_halt`` — a Discord outage never blocks the
    strategy.
    """
    try:
        from live_alerts import notify, _channel
        _body = (
            f"RISK PIPELINE SKIP [{instance_id}] {sym}: current/entry price "
            f"unresolved — P&L uncomputable, ALL risk-exit checks bypassed "
            f"this bar"
        )
        notify(
            category="risk_skip",
            instance_id=str(instance_id),
            title="Risk pipeline SKIP",
            body=_body,
            discord_channel=_channel("notifications"),
            discord_embed={
                "title": "Risk pipeline SKIP",
                "color": 0xE74C3C,
                "description": _body[:1500],
                "fields": [
                    {"name": "symbol", "value": str(sym), "inline": True},
                    {"name": "effect",
                     "value": "All risk-exit gates bypassed (no P&L this bar)",
                     "inline": False},
                ],
            },
            push_body=f"{sym}: risk pipeline skipped (price unresolved)",
        )
    except Exception:
        # Alerts must never block strategy execution.
        pass


# Reason-string tags that mark a PROTECTIVE risk exit (as opposed to a
# signal-driven sell). V31 grace must NEVER suppress these — grace gates
# signal sells only (its purpose is protecting fresh positions from churn).
# Matched as substrings against fresh_reason; they correspond to the exit
# reasons emitted inside _evaluate_position_risk:
#   "Fast loser cut: …"   "Circuit breaker: …"
#   "Trailing stop: …"    "Hold-limit exit: …"
# Forensic audit of backtest 586767: ZERO risk exits fired all run because
# grace vetoed fast-loser/circuit-breaker cuts for the whole ~10d median hold.
_RISK_EXIT_TAGS = ("Fast loser", "Circuit breaker", "Trailing stop", "Hold-limit",
                   "Profit take", "Catastrophic stop")

# The subset of risk-exit tags that also set `_forced_exit` on the score doc.
# `_forced_exit` is what the sweep near the end of run_once reads to add a
# symbol to `nexus_sell_enforcement` — without it the broker can silently drop
# the order for any held name that has aged out of the discovery universe.
#
# This tuple was previously a literal `["Fast loser", "Trailing stop",
# "Hold-limit", "Circuit breaker"]` copy-pasted at THREE sites (the two
# `_finalize_scores` emit branches and the monitor cycle). Three copies is how
# a new protective exit ends up forced at one site and not the others, which
# reads as "the stop fired but nothing sold". One definition now.
#
# NB: "Profit take" is deliberately absent — a profit-take is a PARTIAL trim
# carrying a sell_fraction, and forcing it into sell enforcement would make the
# broker liquidate the whole position (see the monitor-cycle deferral below).
_FORCED_EXIT_TAGS = ("Fast loser", "Trailing stop", "Hold-limit",
                     "Circuit breaker", "Catastrophic stop")


def _profit_take_next_tier(config, unrealized_pct, entry_key, prior_marker):
    """Next un-fired profit-take tier crossed at unrealized_pct, or None.
    Fires the LOWEST un-fired crossed tier (one per bar -> progressive
    scale-out). prior_marker may be the dict form {"entry","fired"}, a legacy
    entry-key string (treated as lowest tier already taken), or None."""
    tiers_raw = config.get("profit_take_tiers") or []
    if not tiers_raw:
        return None
    tiers = []
    for t in tiers_raw:
        try:
            g = float(t[0]); f = float(t[1])
        except (TypeError, ValueError, IndexError, KeyError):
            continue
        if g > 0 and 0.0 < f < 1.0:
            tiers.append((g, f))
    if not tiers:
        return None
    tiers.sort(key=lambda x: x[0])
    if isinstance(prior_marker, dict):
        fired = (set(float(x) for x in (prior_marker.get("fired") or []))
                 if prior_marker.get("entry") == entry_key else set())
    elif isinstance(prior_marker, str) and prior_marker == entry_key:
        # legacy single-fire fired at profit_take_gain_pct -> every tier at/below
        # that level is already taken (not just the lowest).
        try:
            _legacy_gain = float(config.get("profit_take_gain_pct", 40.0) or 40.0)
        except (TypeError, ValueError):
            _legacy_gain = 40.0
        fired = {g for (g, _f) in tiers if g <= _legacy_gain}
    else:
        fired = set()
    try:
        upct = float(unrealized_pct)
    except (TypeError, ValueError):
        return None
    for g, f in tiers:  # ascending -> lowest first
        if g not in fired and upct >= g:
            return {"gain": g, "fraction": f,
                    "new_marker": {"entry": entry_key, "fired": sorted(fired | {g})}}
    return None


def _evaluate_position_risk(
    sym: str,
    *,
    fresh_score: int,
    fresh_reason: str,
    config: dict,
    portfolio_emulator,
    strategy_cache: dict,
    prices: dict | None,
    price_history: dict | None,
    date_key: str,
    propagated: dict,
    entry_buy_ts,
    held_days: int,
    max_hold_days: int,
    bypass_winner_protection: bool = False,
    side_effect_mode: str = "full",
) -> tuple[int, str, dict]:
    """Run held-position risk-exit checks (hold-limit, circuit-breaker,
    winner protection, peak protection, fast-loser, trailing-stop, mega-winner,
    profit-take, V31 grace).

    Returns (new_score, new_reason, extras_dict). extras_dict may contain
    optional keys like ``sell_fraction``.

    bypass_winner_protection=True skips the winner-protection gates wholesale
    (used by the monitor cycle which has empty propagated/sentiment context).

    side_effect_mode="full" — all writes (peak HWM, FLC blacklist, profit-state).
    side_effect_mode="monitor" — peak HWM still writes, but FLC blacklist
    creation is suppressed (the post-_finalize_scores blacklist-decrement loop
    only runs in full cycles, so creating new entries in monitor mode would
    leak — both modes RESPECT existing entries).
    """
    extras: dict = {}
    _profit_take_fired_fraction = None  # set by the tiered profit-take branch below
    if portfolio_emulator is None:
        return fresh_score, fresh_reason, extras

    _hold_limit_forced = False
    _unrealized_pct: float | None = None  # defined only when _ep>0 and _cp>0

    # Hold-limit exit: if position held > max_hold_days with no fresh buy signal, force sell
    if fresh_score <= 0 and max_hold_days > 0:
        days = held_days
        pos = (portfolio_emulator._positions or {}).get(sym, 0.0)
        if pos > 0 and days > max_hold_days:
            _hl_cp = _resolve_symbol_price(sym, prices, price_history, portfolio_emulator=portfolio_emulator)
            _hl_ep = 0.0
            for _ht in reversed(portfolio_emulator._trades or []):
                if _ht.get("ticker") == sym and _ht.get("action") == "buy":
                    _hl_ep = float(_ht.get("price", 0) or 0)
                    break
            _hl_gain = ((_hl_cp - _hl_ep) / _hl_ep * 100.0) if (_hl_ep > 0 and _hl_cp > 0) else 0.0
            _hl_ts_activation = float(config.get("trailing_stop_activation_pct", 10.0))
            if _hl_gain >= _hl_ts_activation:
                _log(f"Hold-limit deferred: {sym} held {days}d > {max_hold_days}d but gain={_hl_gain:+.1f}% >= trailing_stop_activation={_hl_ts_activation:.0f}% — trailing stop manages", "cyan")
            else:
                fresh_score = -1
                fresh_reason = f"Hold-limit exit: held {days}d > {max_hold_days}d max with no fresh buy signal"
                _hold_limit_forced = True
                _log(f"Hold-limit EXIT: {sym} held {days}d > {max_hold_days}d, gain={_hl_gain:+.1f}%, ep=${_hl_ep:.2f}, cp=${_hl_cp:.2f}", "red")
            if _hl_cp <= 0 or _hl_ep <= 0:
                _log(f"Hold-limit WARN: {sym} price resolution issue — cp=${_hl_cp:.2f} ep=${_hl_ep:.2f} (gain calc unreliable)", "yellow")

    _pos_qty_check = float((portfolio_emulator._positions or {}).get(sym, 0))
    if fresh_score != 0 or _pos_qty_check > 0:
        _pos_qty = float((portfolio_emulator._positions or {}).get(sym, 0))
        if _pos_qty > 0:
            _cp = _resolve_symbol_price(sym, prices, price_history, portfolio_emulator=portfolio_emulator)
            _ep = 0.0
            for _th in reversed(portfolio_emulator._trades or []):
                if _th.get("ticker") == sym and _th.get("action") == "buy":
                    _ep = float(_th.get("price", 0) or 0)
                    break
            if _cp <= 0 or _ep <= 0:
                _log(f"Risk pipeline SKIP: {sym} qty={_pos_qty:.1f} but cp=${_cp:.2f} ep=${_ep:.2f} — cannot compute P&L, all risk checks bypassed", "red")
                # A silent skip here is exactly how a position bleeds past every
                # loss floor uncut (CRWV 2026-07). Page operators once per
                # (sym, PT-date) so a silent bypass can never happen again.
                # Dedup + Discord are live-only (PortfolioEmulator has no
                # _instance_id); backtests/tests stay quiet.
                _rs_instance_id = getattr(portfolio_emulator, "_instance_id", None)
                if _rs_instance_id and isinstance(strategy_cache, dict):
                    try:
                        from datetime import datetime as _rs_dt, timezone as _rs_tz
                        from zoneinfo import ZoneInfo as _rs_ZI
                        _rs_pt_date = _rs_dt.now(_rs_tz.utc).astimezone(
                            _rs_ZI("America/Los_Angeles")
                        ).strftime("%Y-%m-%d")
                    except Exception:
                        _rs_pt_date = str(date_key)
                    _rs_sent = strategy_cache.setdefault("_risk_skip_alerted", {})
                    _rs_key = f"{sym}|{_rs_pt_date}"
                    if not _rs_sent.get(_rs_key):
                        _rs_sent[_rs_key] = True
                        _alert_risk_pipeline_skip(str(_rs_instance_id), sym)
            if _ep > 0 and _cp > 0:
                _unrealized_pct = ((_cp - _ep) / _ep) * 100.0
                _prop_raw = float((propagated or {}).get(sym, {}).get("raw_score", 0.0))
                _held_days_wp = float(held_days)
                _time_decay = max(0.0, (_held_days_wp - 45) * 0.005) if _held_days_wp > 45 else 0.0

                if not bypass_winner_protection and fresh_score == -1 and not _hold_limit_forced:
                    if _unrealized_pct >= 50 and _prop_raw > (-0.55 + _time_decay):
                        fresh_score = 0
                        fresh_reason = f"Winner protection: +{_unrealized_pct:.1f}% gain, raw={_prop_raw:.3f} insufficient to sell"
                    elif _unrealized_pct >= 20 and _prop_raw > (-0.35 + _time_decay):
                        fresh_score = 0
                        fresh_reason = f"Winner protection: +{_unrealized_pct:.1f}% gain, raw={_prop_raw:.3f} insufficient to sell"
                    elif _unrealized_pct >= 10 and _prop_raw > (-0.15 + _time_decay):
                        fresh_score = 0
                        fresh_reason = f"Winner protection: +{_unrealized_pct:.1f}% gain, raw={_prop_raw:.3f} insufficient to sell"
                # Tier-3 A1 (2026-05-17): conviction-aware floor matrix.
                # Pre-Tier-3 was a constant -15% with vol-scaling that ineffectively
                # tightened low-vol names (SNDK 5-7% vol → vol-scaled -10% > -15%
                # absolute, so absolute dominated; cut at -18% missed +487% rally).
                # New scheme: resolve HIGH/MID/LOW tier from mcap + raw_score,
                # then pick floor per tier. HIGH disables vol scaling entirely.
                # Phase 2b A2 layers regime adjustment (bull widens, bear tightens,
                # crash forces emergency exit).
                _cb_regime = (
                    str((strategy_cache or {}).get("_market_regime") or "")
                    if isinstance(strategy_cache, dict)
                    else ""
                )
                _cb_regime_gated = bool(
                    config.get("circuit_breaker_regime_gating_enabled", True)
                )
                _cb_tier = _resolve_conviction_tier_at_exit(
                    sym, config, strategy_cache, propagated
                )
                # Tier-3 Phase 3 (A5): record per-evaluation conviction telemetry
                # for offline analysis. Disabled by default once 30 days of data
                # is collected; the score will then be considered for binding to
                # the floor matrix as a continuous knob.
                if bool(config.get("conviction_telemetry_enabled", True)):
                    try:
                        _conv_score = _compute_conviction_score(
                            sym, config, strategy_cache, propagated
                        )
                        if isinstance(strategy_cache, dict):
                            _conv_log = strategy_cache.setdefault(
                                "_nexus_conviction_telemetry", []
                            )
                            if isinstance(_conv_log, list):
                                if len(_conv_log) < 2000:
                                    _conv_log.append({
                                        "sym": sym,
                                        "date": date_key,
                                        "tier": _cb_tier,
                                        "score": _conv_score,
                                        "unrealized_pct": round(_unrealized_pct, 2),
                                    })
                                elif not strategy_cache.get("_nexus_conviction_telemetry_capped_logged"):
                                    # Log once when the cap is hit so operators
                                    # see why the buffer stopped growing.
                                    _log(
                                        "Conviction telemetry buffer capped at 2000 entries — "
                                        "older entries will not be overwritten; clear "
                                        "_nexus_conviction_telemetry from strategy_cache to reset.",
                                        "yellow",
                                    )
                                    strategy_cache["_nexus_conviction_telemetry_capped_logged"] = True
                    except Exception:
                        pass
                # A4 (2026-07-28): one resolver owns tier floor -> regime
                # adjustment -> operator override -> vol scaling -> firing, so
                # the tested floor is the floor that actually fires. The vol
                # lookup stays lazy — it only runs when scaling can bind.
                _z31_floor_effective, _cb_fires, _cb_floor_telemetry = (
                    _resolve_effective_open_loss_floor(
                        _cb_tier,
                        config,
                        regime=(_cb_regime if _cb_regime_gated else None),
                        realized_vol=lambda: _realized_vol_20d(
                            _recent_closes_for_symbol(
                                sym, price_history, portfolio_emulator)),
                        unrealized_pct=_unrealized_pct,
                    )
                )
                _cb_floor_pct = _cb_floor_telemetry["base_pct"]
                _cb_crash_emergency = _cb_floor_telemetry["crash_emergency"]
                if _cb_fires:
                    fresh_score = -1
                    if _cb_crash_emergency:
                        fresh_reason = (
                            f"Circuit breaker: crash regime emergency exit "
                            f"({_unrealized_pct:.1f}% unrealized)"
                        )
                        _log(
                            f"[sell-gate] {sym} | gate=circuit_breaker | regime=crash | "
                            f"unrealized={_unrealized_pct:.1f}% | result=emergency_exit",
                            "red",
                        )
                    else:
                        fresh_reason = (
                            f"Circuit breaker: {_unrealized_pct:.1f}% loss hit floor "
                            f"{_z31_floor_effective:.1f}% (tier={_cb_tier} "
                            f"base={_cb_floor_pct:.0f}% regime={_cb_regime or 'n/a'})"
                        )
                        _log(
                            f"[sell-gate] {sym} | gate=circuit_breaker | tier={_cb_tier} | "
                            f"regime={_cb_regime or 'n/a'} | unrealized={_unrealized_pct:.1f}% | "
                            f"floor={_z31_floor_effective:.1f}% (base={_cb_floor_pct:.0f}%) | result=fired",
                            "red",
                        )
                    # 2026-07-24 (bt#869125 CAR -$185): monitor-mode CB exits
                    # EXECUTE (c88101c) but never set _momentum_sell_cooldown
                    # (that writes only in full-cycle bookkeeping), so the
                    # momentum swap lane re-bought CAR 21h after stopping it out.
                    # Write a re-entry blacklist HERE (fires in BOTH side_effect
                    # modes) reusing _fast_loser_blacklist — every buy lane already
                    # consults it. Config default 0 = OFF -> byte-identical (no
                    # write, no read-side change). Don't buy a name you just
                    # circuit-breaker-stopped out of.
                    _cb_bl_bars = int(config.get("circuit_breaker_reentry_blacklist_bars", 0) or 0)
                    if _cb_bl_bars > 0 and strategy_cache is not None:
                        _cb_bl = _normalize_cache_mapping(strategy_cache, "_fast_loser_blacklist")
                        if sym not in _cb_bl:
                            _cb_bl[sym] = {"date": date_key, "bars_remaining": _cb_bl_bars,
                                           "_created_this_bar": True}
                            _log(f"CB re-entry BLACKLIST: {sym} blocked for {_cb_bl_bars} bars", "red")

                _peak_protected = False
                _peak_pnl_pct_for_log = 0.0
                _drawdown_from_peak_pct_for_log = 0.0
                if bool(config.get("peak_protection_enabled", True)):
                    _sc_pp = strategy_cache if strategy_cache is not None else {}
                    _pp_key, _pp_peak = _resolve_position_peak_state(
                        _sc_pp, sym, entry_buy_ts, _cp
                    )
                    if _cp > _pp_peak:
                        _pp_peak = _cp
                        _sc_pp[_pp_key] = _pp_peak
                    if _ep > 0 and _pp_peak > 0:
                        _peak_pnl_pct_for_log = ((_pp_peak - _ep) / _ep) * 100.0
                        _drawdown_from_peak_pct_for_log = (
                            ((_pp_peak - _cp) / _pp_peak) * 100.0 if _pp_peak > 0 else 0.0
                        )
                        _pp_min_peak = float(
                            config.get("peak_protection_min_peak_pnl_pct", 30.0) or 30.0
                        )
                        _pp_max_dd = float(
                            config.get("peak_protection_max_drawdown_from_peak_pct", 60.0) or 60.0
                        )
                        if (
                            _peak_pnl_pct_for_log >= _pp_min_peak
                            and _drawdown_from_peak_pct_for_log <= _pp_max_dd
                        ):
                            _peak_protected = True

                _fast_cut_pct = float(config.get("fast_loser_cut_pct", -10.0))
                # 2026-07-19 regime-safety Phase 4: hard/kill drawdown-circuit
                # tiers tighten the cut floor (e.g. -10% -> -7%).
                _dd_floor_override = (strategy_cache or {}).get("_dd_cut_floor_override")
                if _dd_floor_override is not None:
                    try:
                        _fast_cut_pct = max(_fast_cut_pct, float(_dd_floor_override))
                    except (TypeError, ValueError):
                        pass
                if fresh_score >= 0 and _unrealized_pct <= _fast_cut_pct and _peak_protected:
                    _log(
                        f"Peak protection BYPASS fast-loser-cut: {sym} "
                        f"peak_pnl=+{_peak_pnl_pct_for_log:.1f}% (>={float(config.get('peak_protection_min_peak_pnl_pct', 30.0) or 30.0):.0f}%), "
                        f"drawdown_from_peak={_drawdown_from_peak_pct_for_log:.1f}% "
                        f"(<={float(config.get('peak_protection_max_drawdown_from_peak_pct', 60.0) or 60.0):.0f}%), "
                        f"current_pnl={_unrealized_pct:+.1f}% — deferring to trailing stop",
                        "magenta",
                    )
                elif (fresh_score >= 0 and _unrealized_pct <= _fast_cut_pct
                      and bool(config.get("fast_loser_cut_enabled", True))):
                    # `fast_loser_cut_enabled` (2026-08-06, default True =
                    # unchanged behaviour). This cut had NO off switch: every
                    # other exit in this function has one, so an operator
                    # building a let-winners-run profile could disable the
                    # trailing stop, profit take, hold limit and drawdown
                    # circuit and still be cut at -10%.
                    #
                    # That matters because a -10% floor is not a small filter on
                    # the names this strategy is trying to hold. Measured over
                    # the nine 2025-26 semiconductor moonshots, not one of which
                    # drew down less than 22% on its way up, a -10% cut reaches
                    # 5 of 9 and the -3% downtrend rule reaches 6 of 9 — while
                    # -40% reaches none. Losing the tail is the cost, and it is
                    # not visible in aggregate P&L until a 10-bagger is in the
                    # book.
                    # P&L sweep 2026-07-19 (config-gated, default 0=off):
                    # day-one whipsaw guard. NEUTRAL lost $415 to 49 fast cuts
                    # (three same-day cuts were the entire window loss) while
                    # BEAR had 0 fires — a cut this early is noise, not
                    # information. A position younger than min-hold is spared;
                    # the trailing stop and drawdown halt still protect it.
                    # BEAR_F lesson (-7.77%): suppression is BULL/CHOP-only —
                    # in a bear/crash regime the cut must fire immediately
                    # (the baseline bear had 0 fires unsuppressed, so this is
                    # strictly behavior-preserving there).
                    _flc_regime = (
                        str((strategy_cache or {}).get("_market_regime") or "")
                        if isinstance(strategy_cache, dict) else ""
                    ).strip().lower()
                    _flc_suppression_allowed = _flc_regime not in ("bear", "crash")
                    _flc_min_hold_days = int(config.get("fast_loser_cut_min_hold_days", 0) or 0)
                    if not _flc_suppression_allowed:
                        _flc_min_hold_days = 0
                    _flc_min_hold_ok = True
                    if _flc_min_hold_days > 0:
                        try:
                            _flc_entry = entry_buy_ts
                            if _flc_entry is not None and date_key:
                                if hasattr(_flc_entry, "date"):
                                    _flc_entry_date = _flc_entry.date()
                                else:
                                    _flc_entry_date = _dt.date.fromisoformat(str(_flc_entry)[:10])
                                _flc_held = (_dt.date.fromisoformat(date_key[:10])
                                             - _flc_entry_date).days
                                if 0 <= _flc_held < _flc_min_hold_days:
                                    _flc_min_hold_ok = False
                                    _log(
                                        f"FLC min-hold guard: {sym} held {_flc_held}d < "
                                        f"{_flc_min_hold_days}d — not cutting day-one noise",
                                        "yellow",
                                    )
                        except Exception:
                            _flc_min_hold_ok = True
                    _flc_runup_block_pct = float(config.get("fast_loser_cut_recent_runup_block_pct", 0.0) or 0.0)
                    if not _flc_suppression_allowed:
                        _flc_runup_block_pct = 0.0  # bear/crash: never spare a -10% loss
                    _flc_runup_lookback = int(config.get("fast_loser_cut_recent_runup_lookback_bars", 20) or 20)
                    _flc_block_runup, _flc_runup_pct = _recent_runup_protect(
                        sym, price_history, _flc_runup_block_pct, _flc_runup_lookback,
                    )
                    if _flc_block_runup:
                        _log(
                            f"V28.7 FLC recent-runup block: {sym} recent "
                            f"{_flc_runup_lookback}-bar range ran +{_flc_runup_pct:.1f}% > "
                            f"{_flc_runup_block_pct:.0f}% threshold — not cutting "
                            f"(volatility on hot entry)",
                            "yellow",
                        )
                    if _flc_block_runup or not _flc_min_hold_ok:
                        pass  # fall through, no cut
                    else:
                        fresh_score = -1
                        fresh_reason = f"Fast loser cut: {_unrealized_pct:.1f}% loss exceeds {_fast_cut_pct:.0f}% threshold"
                        # Monitor mode skips blacklist creation — the daily decrement loop runs in full cycles only.
                        if side_effect_mode == "full":
                            _fl_blacklist = _normalize_cache_mapping(strategy_cache, "_fast_loser_blacklist")
                            if sym not in _fl_blacklist:
                                _fl_blacklist[sym] = {"date": date_key, "bars_remaining": int(config.get("fast_loser_blacklist_days", 20)), "_created_this_bar": True}
                                _log(f"Fast loser BLACKLIST: {sym} blocked for {_fl_blacklist[sym]['bars_remaining']} bars", "red")

                # ── Catastrophic position stop (default OFF) ──────────────
                # The single unconditional loss floor that survives when an
                # operator turns the trailing stop off (`trailing_stop_disabled`).
                #
                # Kaminski & Lo: under a random walk the "stopping premium" is
                # ALWAYS negative — a stop only adds return when price
                # autocorrelation at the evaluation frequency is at least as
                # large as the Sharpe ratio at that frequency, which daily US
                # equities do not deliver. Han/Zhou/Zhu's pro-stop result
                # decomposes to +3 bps/month on the LONG leg (insignificant)
                # while adding ~40% turnover; the whole effect lives in the
                # short leg, which this long-only book does not have. So this
                # is deliberately NOT an alpha claim — it is ruin control, and
                # it is priced as such: one wide floor, one evaluation per day.
                #
                # Why it is not just another circuit-breaker tier: the tier
                # floor matrix (_resolve_effective_open_loss_floor) is
                # conviction- and regime-conditioned and an operator can widen
                # every tier out of the way. This floor is unconditional — no
                # tier, no regime gate, and explicitly NOT bypassable by peak
                # protection (which defers losers to "the trailing stop", the
                # very mechanism this replaces). If both fire, whichever is
                # tighter wins simply by evaluating first.
                #
                # side_effect_mode=="full" is the daily/full cycle, so the
                # comparison is against a settled daily mark rather than an
                # intraday tick. That matters: a stop evaluated on intraday
                # marks fires on noise and re-prices the whole rationale above.
                # Same reason the profit-take block below defers to the daily
                # cycle.
                _cat_stop_enabled = bool(config.get("catastrophic_stop_enabled", False))
                _cat_stop_pct = float(config.get("catastrophic_stop_pct", -20.0) or -20.0)
                if (
                    _cat_stop_enabled
                    and side_effect_mode == "full"
                    and fresh_score >= 0
                    and _cat_stop_pct < 0
                    and _unrealized_pct <= _cat_stop_pct
                ):
                    fresh_score = -1
                    fresh_reason = (
                        f"Catastrophic stop: {_unrealized_pct:.1f}% loss hit the "
                        f"unconditional {_cat_stop_pct:.0f}% floor"
                    )
                    _log(
                        f"[sell-gate] {sym} | gate=catastrophic_stop | "
                        f"unrealized={_unrealized_pct:.1f}% | floor={_cat_stop_pct:.0f}% | "
                        f"result=fired",
                        "red",
                    )

                # Z3.2 (2026-05-15): default activation lowered from 10% to 5%
                # AND vol-scaled per-symbol with an upper cap so high-vol
                # names don't need an unreasonable gain before trail kicks in.
                # Spec: activation = clamp(max(5%, 0.75*vol), 5%, 15%).
                # The 15% ceiling is critical — AMD ~40% vol would otherwise
                # need +30% gain before trail engaged, defeating the
                # purpose of the early-activation fix.
                _ts_activation = float(config.get("trailing_stop_activation_pct", 5.0))
                _z32_vol_mult = float(config.get("trailing_stop_activation_vol_multiplier", 0.75) or 0.0)
                _z32_vol_cap = float(config.get("trailing_stop_activation_vol_cap_pct", 15.0) or 15.0)
                if _z32_vol_mult > 0:
                    _z32_closes = _recent_closes_for_symbol(sym, price_history, portfolio_emulator)
                    _z32_vol = _realized_vol_20d(_z32_closes)
                    if _z32_vol > 0:
                        _z32_target = _z32_vol_mult * _z32_vol * 100.0
                        # Pick the larger of default and vol-scaled, capped
                        # at the vol_cap_pct ceiling.
                        _ts_activation = min(_z32_vol_cap, max(_ts_activation, _z32_target))
                _default_trailing_pct = float(config.get("trailing_stop_pct", 8.0))
                if sym in _COMMODITY_ETF_TICKERS:
                    _ts_drop = float(config.get("trailing_stop_commodity_etf_pct", 12.0))
                elif sym in _SECTOR_ETF_TICKERS:
                    _ts_drop = float(config.get("trailing_stop_sector_etf_pct", 10.0))
                else:
                    _ts_drop = _default_trailing_pct
                _has_amplifier_adds = bool(
                    (strategy_cache or {}).get("_momentum_amplifier_fired", {}).get(sym)
                ) if strategy_cache else False
                _orig_entry_hoist = _get_open_position_entry_trade(portfolio_emulator, sym)
                _orig_ep_hoist = float((_orig_entry_hoist or {}).get("price", _ep) or _ep)
                if _orig_ep_hoist <= 0:
                    _orig_ep_hoist = _ep
                _sc_hoist = strategy_cache if strategy_cache is not None else {}
                _peak_key_hoist, _stored_peak_hoist = _resolve_position_peak_state(
                    _sc_hoist, sym, entry_buy_ts, _cp
                )
                _peak_price_for_scale = max(
                    float(_stored_peak_hoist or 0.0), float(_cp or 0.0)
                )
                if _orig_ep_hoist > 0 and _peak_price_for_scale > _orig_ep_hoist:
                    _peak_gain_pct = ((_peak_price_for_scale - _orig_ep_hoist) / _orig_ep_hoist) * 100.0
                else:
                    _peak_gain_pct = float(_unrealized_pct or 0.0)
                # 2026-07-31: the scaling below WIDENS the trail as a winner
                # grows (up to trailing_stop_scale_max_multiplier), which is
                # backwards for a parabolic blow-off — the wider the band, the
                # further a vertical name falls before the stop fires. CAR
                # peaked at +141.9%, took the full 2x, and its threshold went
                # 12% -> 24%; it therefore held at a 17.8% drawdown and exited a
                # day later 59% off the peak. This cap disables the widening
                # once peak gain exceeds N% (0.0 = OFF = today's behaviour).
                _ts_scale_off_above = float(
                    config.get("trailing_stop_pnl_scaling_disable_above_pct", 0.0) or 0.0)
                if (bool(config.get("trailing_stop_pnl_scaling_enabled", True))
                        and not _has_amplifier_adds
                        and not (_ts_scale_off_above > 0.0
                                 and _peak_gain_pct >= _ts_scale_off_above)):
                    _orig_gain_pct = _peak_gain_pct
                    if _orig_gain_pct >= 25.0:
                        _ts_scale_floor = float(config.get("trailing_stop_scale_floor_pnl", 25.0))
                        _ts_scale_ceiling = float(config.get("trailing_stop_scale_ceiling_pnl", 60.0))
                        _ts_scale_max = float(config.get("trailing_stop_scale_max_multiplier", 2.0))
                        _pnl_ratio = min(1.0, (_orig_gain_pct - _ts_scale_floor) / max(1.0, _ts_scale_ceiling - _ts_scale_floor))
                        _ts_multiplier = 1.0 + _pnl_ratio * (_ts_scale_max - 1.0)
                        _ts_drop = _ts_drop * _ts_multiplier
                if (bool(config.get("mega_winner_protect_enabled", True))
                        and not _has_amplifier_adds):
                    try:
                        _mwp_min_pnl = float(config.get("mega_winner_min_pnl_pct", 50.0) or 50.0)
                    except Exception:
                        _mwp_min_pnl = 50.0
                    try:
                        _mwp_min_days = int(config.get("mega_winner_min_held_days", 60) or 60)
                    except Exception:
                        _mwp_min_days = 60
                    try:
                        _mwp_fast_min_days = int(config.get("mega_winner_fast_min_held_days", 20) or 20)
                    except Exception:
                        _mwp_fast_min_days = 20
                    try:
                        _mwp_trail = float(config.get("mega_winner_trail_pct", 30.0) or 30.0)
                    except Exception:
                        _mwp_trail = 30.0
                    try:
                        _mwp_held = int(held_days or 0)
                    except Exception:
                        _mwp_held = 0
                    _mwp_effective_min_days = min(_mwp_min_days, _mwp_fast_min_days)
                    if _mwp_fast_min_days >= _mwp_min_days:
                        _mwp_warn_key = "_mwp_fast_config_warned"
                        if strategy_cache is not None and not strategy_cache.get(_mwp_warn_key):
                            _log(
                                f"CONFIG WARNING: mega_winner_fast_min_held_days ({_mwp_fast_min_days}d) >= "
                                f"mega_winner_min_held_days ({_mwp_min_days}d) — fast branch is a no-op. "
                                f"Set fast<std (e.g., fast=20, std=60) to enable fast-mover protection.",
                                "yellow",
                            )
                            strategy_cache[_mwp_warn_key] = True
                    if (
                        _peak_gain_pct is not None
                        and _peak_gain_pct >= _mwp_min_pnl
                        and _mwp_held >= _mwp_effective_min_days
                    ):
                        _mwp_new_ts = max(float(_ts_drop), _mwp_trail)
                        _mwp_branch = "FAST" if _mwp_held < _mwp_min_days else "STD"
                        if _mwp_new_ts > float(_ts_drop) + 1e-6:
                            _log(
                                f"V32 MEGA-WINNER ({_mwp_branch}): {sym} peak_gain={_peak_gain_pct:+.1f}% "
                                f"held={_mwp_held}d trail {_ts_drop:.1f}% -> {_mwp_new_ts:.1f}%",
                                "magenta",
                            )
                            _ts_drop = _mwp_new_ts
                # `trailing_stop_disabled` (default False) suppresses the SELL
                # only — every line of peak bookkeeping below still runs.
                # The high-water mark this block maintains is not private to the
                # trailing stop: peak protection, winner-add's
                # drawdown-from-peak gate and the mega-winner widener all read
                # the same `_peak_key`. Skipping the block wholesale would
                # silently freeze those three at whatever HWM they last saw,
                # which is a different (and much worse) change than "no trailing
                # stop" — a stale HWM makes drawdown-from-peak read 0% forever.
                _ts_disabled = bool(config.get("trailing_stop_disabled", False))
                _sc = strategy_cache if strategy_cache is not None else {}
                _peak_key, _stored_peak = _resolve_position_peak_state(_sc, sym, entry_buy_ts, _cp)
                if _trailing_stop_armed(_sc, _peak_key, _unrealized_pct, _ts_activation, _peak_protected) and fresh_score >= 0:
                    _peak = max(_stored_peak, _cp)
                    _sc[_peak_key] = _peak
                    _drop_from_peak = ((_peak - _cp) / _peak) * 100.0 if _peak > 0 else 0
                    if _ts_disabled:
                        if _drop_from_peak >= _ts_drop:
                            _log(
                                f"Trailing stop SUPPRESSED (trailing_stop_disabled): {sym} "
                                f"drop={_drop_from_peak:.1f}% >= {_ts_drop:.0f}% — held; "
                                f"catastrophic stop is the floor",
                                "yellow",
                            )
                    elif _drop_from_peak >= _ts_drop:
                        fresh_score = -1
                        fresh_reason = f"Trailing stop: dropped {_drop_from_peak:.1f}% from peak ${_peak:.2f}"
                        _log(f"Trailing stop SELL: {sym} peak=${_peak:.2f} cp=${_cp:.2f} drop={_drop_from_peak:.1f}% >= {_ts_drop:.0f}% threshold (peak_protected={_peak_protected})", "red")
                    else:
                        if _drop_from_peak > 3.0:
                            _log(f"Trailing stop tracking: {sym} peak=${_peak:.2f} drop={_drop_from_peak:.1f}% (need {_ts_drop:.0f}%)", "cyan")
                elif _unrealized_pct < _ts_activation:
                    _sc[_peak_key] = max(_stored_peak, _cp)

                # `profit_take_disabled` (default False) is a KILL SWITCH that
                # outranks `profit_take_enabled` and `profit_take_tiers`. It
                # exists as a separate key because the live config sets those
                # two — flipping them there is a hand-edit of a real-money
                # document, whereas this is one boolean an A/B can carry.
                #
                # Odean (JF 1998): the winners investors sold subsequently
                # OUTPERFORMED the losers they kept. Frazzini (JF 2006): the
                # post-news drift is LARGER when the news and the unrealised
                # gain point the same way — worth over 200 bps/month. A
                # profit-take tier fires precisely on a held winner with news
                # agreement, i.e. it sells the exact position where the drift
                # is strongest, and pays ~23 bps one-way for the privilege.
                # Tiers are also a leading source of short holds here: each tier
                # crossing is its own round trip on the same name.
                _profit_take_enabled = (
                    bool(config.get("profit_take_enabled", False))
                    and not bool(config.get("profit_take_disabled", False))
                )
                _profit_take_gain_pct = float(config.get("profit_take_gain_pct", 40.0) or 40.0)
                _profit_take_sell_fraction = float(config.get("profit_take_sell_fraction", 0.50) or 0.50)
                _profit_take_tiers_cfg = config.get("profit_take_tiers") or []
                _profit_take_fired_fraction = None
                # A configured tiers list with no structurally-valid [gain, fraction]
                # entry falls back to single-fire (and warns) rather than silently
                # disabling all profit-taking.
                _pt_valid_tiers = False
                for _pt_t in _profit_take_tiers_cfg:
                    try:
                        if float(_pt_t[0]) > 0 and 0.0 < float(_pt_t[1]) < 1.0:
                            _pt_valid_tiers = True
                            break
                    except (TypeError, ValueError, IndexError, KeyError):
                        continue
                if _profit_take_tiers_cfg and not _pt_valid_tiers:
                    _log("Profit take: profit_take_tiers has no valid [gain,fraction] entries — using single-fire", "yellow")
                # Profit-take runs ONLY on the daily/full cycle: the intraday
                # monitor has no per-symbol sell-size channel (would default to a
                # 100% sell) and shares the persistent profit-state cache, so a
                # monitor fire would burn the tier marker without trimming. A
                # +20% trim is not time-critical — defer it to the daily cycle.
                if _profit_take_enabled and side_effect_mode == "full" and fresh_score >= 0 and (
                    _pt_valid_tiers
                    or (_profit_take_gain_pct > 0 and 0.0 < _profit_take_sell_fraction < 1.0)
                ):
                    _profit_state = _normalize_cache_mapping(strategy_cache, "_nexus_profit_take_state")
                    _entry_marker = entry_buy_ts
                    if isinstance(_entry_marker, str):
                        _entry_key = _entry_marker[:32]
                    elif hasattr(_entry_marker, "isoformat"):
                        try:
                            _entry_key = str(_entry_marker.isoformat())[:32]
                        except Exception:
                            _entry_key = str(_entry_marker)[:32]
                    else:
                        _entry_key = str(_entry_marker or "")
                    _profit_marker = _profit_state.get(sym)
                    _pt_already_taken = (
                        _profit_marker == _entry_key
                        or (isinstance(_profit_marker, dict) and _profit_marker.get("entry") == _entry_key)
                    )
                    if _pt_valid_tiers and _entry_key:
                        _pt_tier = _profit_take_next_tier(config, _unrealized_pct, _entry_key, _profit_marker)
                        if _pt_tier is not None:
                            fresh_score = -1
                            fresh_reason = (
                                f"Profit take tier: +{_unrealized_pct:.1f}% gain crossed "
                                f"+{_pt_tier['gain']:.0f}% tier"
                            )
                            _profit_state[sym] = _pt_tier["new_marker"]
                            _profit_take_fired_fraction = _pt_tier["fraction"]
                            _log(f"Profit take tier TRIGGER: {sym} gain={_unrealized_pct:+.1f}% >= +{_pt_tier['gain']:.0f}% tier, sell_fraction={_pt_tier['fraction']:.0%}", "magenta")
                    elif _unrealized_pct >= _profit_take_gain_pct and _entry_key and not _pt_already_taken:
                        fresh_score = -1
                        fresh_reason = (
                            f"Profit take: +{_unrealized_pct:.1f}% gain exceeds "
                            f"{_profit_take_gain_pct:.0f}% threshold"
                        )
                        _profit_state[sym] = _entry_key
                        _log(f"Profit take TRIGGER: {sym} gain={_unrealized_pct:+.1f}% >= {_profit_take_gain_pct:.0f}% threshold, sell_fraction={_profit_take_sell_fraction:.0%}", "magenta")
                    elif _unrealized_pct >= _profit_take_gain_pct and _entry_key and _pt_already_taken:
                        _log(f"Profit take SKIP (already taken): {sym} gain={_unrealized_pct:+.1f}% but already trimmed for entry={str(_entry_key)[:16]}", "cyan")

            # V31 grace gates SIGNAL-driven sells only. Protective risk exits
            # (Fast loser / Circuit breaker / Trailing stop / Hold-limit) must
            # survive grace untouched — see _RISK_EXIT_TAGS. (_hold_limit_forced
            # is already covered by the "Hold-limit" tag but kept explicit.)
            _is_risk_exit_sell = bool(
                fresh_reason and any(tag in fresh_reason for tag in _RISK_EXIT_TAGS)
            )
            if fresh_score == -1 and not _hold_limit_forced and not _is_risk_exit_sell:
                _grace_days = held_days
                _grace_regime = str((strategy_cache or {}).get("_market_regime") or "chop")
                # Mirror the inlined original: grace fires only when _ep>0 and _cp>0 (which
                # is when _unrealized_pct was defined). Otherwise pnl unknown — skip grace.
                if _unrealized_pct is None:
                    _g_in_grace = False
                    _g_escape = False
                    _g_reason = ""
                    _grace_pnl = 0.0
                else:
                    _grace_pnl = _unrealized_pct
                    # Phase ε.C.0' (2026-05-19): tier-aware grace escape_A.
                    _grace_tier_sell = _resolve_conviction_tier_at_exit(
                        sym, config, strategy_cache, propagated
                    )
                    _g_in_grace, _g_escape, _g_reason = _in_initial_grace_period(
                        _grace_days, _grace_pnl, config, _grace_regime,
                        conviction_tier=_grace_tier_sell,
                    )
                # Run-185254 leak #2: a high-conviction signal sell on a losing
                # position may bypass grace (same lever as the min-hold gate).
                # NOTE: this site gates on the pre-overlay graph raw_score and
                # original-entry pnl; the min-hold gate uses the overlay-adjusted
                # raw_net and latest-add pnl. The two sites guard different sell
                # paths, so the shared thresholds apply to slightly different
                # scales — acceptable, but keep in mind when tuning. —
                # otherwise the min-hold bypass is neutered for the first
                # grace_bars days and losers still ride to the -10% hard cut.
                _grace_conv_raw = float((propagated.get(sym) or {}).get("raw_score", 0.0) or 0.0)
                if (
                    _g_in_grace
                    and not _g_escape
                    and _llm_sell_conviction_bypass(config, _grace_conv_raw, _grace_pnl if _unrealized_pct is not None else None)
                ):
                    _g_in_grace = False
                    _log(
                        f"V31 grace BYPASS (conviction): {sym} day {_grace_days} "
                        f"pnl={_grace_pnl:+.1f}% raw={_grace_conv_raw:+.2f} — sell allowed",
                        "red",
                    )
                if _g_in_grace and not _g_escape:
                    _log(
                        f"V31 grace SUPPRESS: {sym} day {_grace_days} pnl={_grace_pnl:+.1f}% "
                        f"would-have-sold reason='{fresh_reason[:60]}' — held",
                        "yellow",
                    )
                    fresh_score = 0
                    fresh_reason = (
                        f"V31 grace period (day {_grace_days}/{int(config.get('initial_grace_bars', 14) or 14)}): "
                        f"suppressed [{fresh_reason[:80]}]"
                    )
                elif _g_in_grace and _g_escape:
                    _log(
                        f"V31 grace ESCAPE: {sym} day {_grace_days} pnl={_grace_pnl:+.1f}% "
                        f"trigger={_g_reason} — sell allowed",
                        "red",
                    )

    if fresh_score == -1 and "Profit take" in (fresh_reason or ""):
        extras["sell_fraction"] = (
            _profit_take_fired_fraction if _profit_take_fired_fraction is not None
            else float(config.get("profit_take_sell_fraction", 0.50) or 0.50)
        )
    return fresh_score, fresh_reason, extras


# ──────────────────────────────────────────────────────────────────────────────
# Final score mapping
# ──────────────────────────────────────────────────────────────────────────────

def _finalize_scores(symbols_list: list, sentiment_data: dict, propagated: dict, config: dict, pending_by_symbol: dict | None = None, portfolio_emulator=None, date_key: str = "", prices: dict | None = None, strategy_cache: dict | None = None, price_history: dict | None = None) -> dict:
    """
    Map continuous raw_scores to discrete {-1, 0, 1} with detailed reasoning.
    Direct LLM sentiment takes priority; graph-propagated scores use configurable thresholds.
    Pending future trades are combined with the fresh analysis as additional votes.
    portfolio_emulator: optional PortfolioEmulator — used for hold-limit exit logic.

    Z2.2 (2026-05-15): union currently-held positions into symbols_list so every
    held name produces a decision record each bar. Backtest 299903 had AORT
    in only 2 of 9 decision records (buy + final sell) — the strategy never
    re-evaluated it during the -33% drawdown. With this change, held names
    not in the active discovery universe still get scored, enabling the
    stop-loss / drawdown logic to fire on every bar.
    """
    import datetime as _dt
    if strategy_cache is None:
        strategy_cache = {}
    buy_thresh = float(config.get("buy_threshold", _DEFAULT_BUY_THRESHOLD))
    sell_thresh = float(config.get("sell_threshold", _DEFAULT_SELL_THRESHOLD))
    max_hold_days = int(config.get("max_hold_days", 90) or 90)
    pending_by_symbol = pending_by_symbol or {}

    # Z2.2: union held positions into the scored universe so every held
    # name produces a decision record each bar (enables stop-loss / drawdown
    # logic to fire continuously). Use the public get_positions() accessor
    # for thread-safety when running in live mode; fall back to the private
    # attribute when get_positions() isn't available (older tests/mocks).
    if portfolio_emulator is not None:
        try:
            if hasattr(portfolio_emulator, "get_positions"):
                _held_positions = portfolio_emulator.get_positions() or {}
            else:
                _held_positions = getattr(portfolio_emulator, "_positions", None) or {}
            _existing_set = set(symbols_list or [])
            _held_added: list[str] = []
            # 2026-07-19: sleeve legs are broker-managed cash parking — they
            # must NOT enter the scoring universe or the monitor's stop-loss
            # machinery would sell the hedge on routine bounces (adversarial
            # review HIGH: FLC at -7% fires on a ~2.3% QQQ bounce vs SQQQ,
            # then the sleeve rebuys same bar — serial loss crystallization).
            _z22_sleeve_syms = _sleeve_symbols(config)
            for _sym, _qty in _held_positions.items():
                if _sym in _z22_sleeve_syms:
                    continue
                if _qty and _qty > 0 and _sym and _sym not in _existing_set:
                    _existing_set.add(_sym)
                    _held_added.append(_sym)
            # Build the new list once outside the loop (was O(n^2) per spawn).
            if _held_added:
                symbols_list = list(symbols_list) + _held_added
                # Z2.2 telemetry: log only when verbose mode is set so we
                # don't drown BacktestResults.logs (500-line truncation).
                if bool(config.get("nexus_held_reeval_verbose", False)):
                    _log(
                        f"Held-position re-eval (Z2.2): added {len(_held_added)} held name(s) to scoring "
                        f"universe: {', '.join(_held_added[:10])}{'...' if len(_held_added) > 10 else ''}",
                        "cyan",
                    )
        except Exception as _z22_err:
            _log(f"Z2.2 held-position union skipped: {_z22_err}", "yellow")

    # Build per-ticker entry date of the CURRENT open position from portfolio emulator trade history.
    # "Entry date" = earliest buy AFTER the most recent sell (or earliest buy ever if never sold).
    # This prevents premature sell-after-rebuy: if AAPL was bought day 1, sold day 20, rebought
    # day 60, the entry date is day 60, not day 1.
    _entry_buy: dict[str, Any] = {}
    if portfolio_emulator is not None and max_hold_days > 0:
        history = portfolio_emulator.get_trade_history() or []
        if bool(config.get("entry_survives_partial_sell_enabled", False)):
            # 2026-07-23 FIX (tiered profit-take): entry = the buy that opened the
            # CURRENT continuous holding run (running net qty). The legacy two-pass
            # below treats a PARTIAL profit-take trim as if it closed+reopened the
            # position — after tier 1 sells, the original buy is "before the last
            # sell" -> no entry for a still-held name -> entry_key="" -> the tiered
            # profit-take STOPS after tier 1 and held_days resets. See helper.
            _entry_buy = _open_run_entry_map(history)
        else:
            # Legacy two-pass: find the most recent sell timestamp per ticker,
            # then the earliest buy AFTER it. (Buggy on partial sells — see above.)
            _last_sell: dict[str, Any] = {}
            for trade in history:
                if trade.get("action") == "sell":
                    t = trade.get("ticker", "")
                    ts = trade.get("timestamp")
                    if t and ts is not None:
                        existing = _last_sell.get(t)
                        if existing is None or ts > existing:
                            _last_sell[t] = ts
            for trade in history:
                if trade.get("action") == "buy":
                    t = trade.get("ticker", "")
                    ts = trade.get("timestamp")
                    if t and ts is not None:
                        last_sell = _last_sell.get(t)
                        if last_sell is not None and ts <= last_sell:
                            continue  # This buy was before or at last sell — not the current entry
                        existing = _entry_buy.get(t)
                        if existing is None or ts < existing:
                            _entry_buy[t] = ts
        # Remove tickers with no current open position
        positions = portfolio_emulator._positions or {}
        for t in list(_entry_buy.keys()):
            if positions.get(t, 0.0) <= 0:
                del _entry_buy[t]

    def _hold_days(sym: str) -> int:
        """Return calendar days since entry into the current open position, or 0 if not held."""
        buy_ts = _entry_buy.get(sym)
        if buy_ts is None or not date_key:
            return 0
        try:
            today = _dt.date.fromisoformat(date_key[:10])
            if hasattr(buy_ts, "date"):
                buy_date = buy_ts.date()
            elif isinstance(buy_ts, str):
                buy_date = _dt.date.fromisoformat(str(buy_ts)[:10])
            else:
                return 0
            return max(0, (today - buy_date).days)
        except Exception:
            return 0

    out = {}
    for sym in symbols_list:
        fresh_score = 0
        fresh_reason = "No graph signal"

        # Priority 1: direct LLM sentiment (the ticker was explicitly mentioned in news)
        if sym in sentiment_data and sentiment_data[sym]["sentiment"] != 0:
            s = sentiment_data[sym]["sentiment"]
            evt = sentiment_data[sym]["event"]
            raw = propagated.get(sym, {}).get("raw_score", float(s))
            n_paths = propagated.get(sym, {}).get("n_paths", 1)
            fresh_score = s
            fresh_reason = f"Direct {evt} sentiment={s:+d} (raw={raw:+.3f}, {n_paths} paths)"

        # Priority 2: graph-propagated score above threshold
        elif sym in propagated:
            raw = propagated[sym]["raw_score"]
            reasons = propagated[sym]["reasons"]
            n_paths = propagated[sym]["n_paths"]
            if raw >= buy_thresh:
                fresh_score = 1
            elif raw <= sell_thresh:
                fresh_score = -1
            top_reason = reasons[0] if reasons else "graph propagation"
            fresh_reason = f"Graph({n_paths} paths, raw={raw:+.3f}): {top_reason}"

        # V31 Section 4.1: per-stock breakout score boost. Adds to raw_score
        # for any stock printing 52w/5w highs, volume surge, or gap-up. Can
        # PROMOTE a previously-neutral stock to score=1 even without LLM news.
        if bool(config.get("breakout_score_boost_enabled", True)):
            _bk_boost, _bk_reason = _compute_breakout_score_boost(sym, price_history, config)
            if _bk_boost > 0:
                _existing_raw = float(propagated.get(sym, {}).get("raw_score", 0.0) or 0.0)
                _new_raw = _existing_raw + _bk_boost
                if fresh_score <= 0 and _new_raw >= buy_thresh:
                    fresh_score = 1
                fresh_reason = f"{fresh_reason} | breakout({_bk_reason}=+{_bk_boost:.2f})"

        # Held-position risk evaluation (extracted to _evaluate_position_risk
        # for reuse by the dual-cadence monitor cycle). Behavior MUST be
        # byte-equivalent to the previous inline block — see
        # backend/tests/test_nexus_evaluate_position_risk.py.
        _epr_extras: dict = {}  # bound below only when the emulator exists; keep safe for the sell_fraction sites
        if portfolio_emulator is not None:
            _epr_score, _epr_reason, _epr_extras = _evaluate_position_risk(
                sym,
                fresh_score=fresh_score,
                fresh_reason=fresh_reason,
                config=config,
                portfolio_emulator=portfolio_emulator,
                strategy_cache=strategy_cache,
                prices=prices,
                price_history=price_history,
                date_key=date_key,
                propagated=propagated,
                entry_buy_ts=_entry_buy.get(sym),
                held_days=_hold_days(sym),
                max_hold_days=max_hold_days,
                bypass_winner_protection=False,
                side_effect_mode="full",
            )
            fresh_score = _epr_score
            fresh_reason = _epr_reason

        # Combine with pending scheduled trades using confidence-weighted voting
        if sym in pending_by_symbol:
            pending = pending_by_symbol[sym]
            ft_reasons = "; ".join(t["reason"][:40] for t in pending)

            # Weighted voting: fresh analysis gets weight 1.0, scheduled trades use their confidence
            weight_buy = 1.0 if fresh_score == 1 else 0.0
            weight_sell = 1.0 if fresh_score == -1 else 0.0
            for t in pending:
                conf = float(t.get("confidence", 0.5))
                if t["signal"] == 1:
                    weight_buy += conf
                elif t["signal"] == -1:
                    weight_sell += conf

            if weight_buy > weight_sell:
                final_score = 1
            elif weight_sell > weight_buy:
                final_score = -1
            else:
                # Tie: defer to fresh analysis (more current)
                final_score = fresh_score

            out[sym] = {
                "score": final_score,
                "reason": f"{fresh_reason} | scheduled: {ft_reasons}",
                "_forced_exit": (final_score == -1 and fresh_reason and any(x in fresh_reason for x in _FORCED_EXIT_TAGS)),
            }
            if "Profit take" in fresh_reason and final_score == -1:
                out[sym]["sell_fraction"] = _epr_extras.get(
                    "sell_fraction", float(config.get("profit_take_sell_fraction", 0.50) or 0.50)
                )
        else:
            out[sym] = {
                "score": fresh_score,
                "reason": fresh_reason,
                "_forced_exit": (fresh_score == -1 and fresh_reason and any(x in fresh_reason for x in _FORCED_EXIT_TAGS)),
            }
            if "Profit take" in fresh_reason and fresh_score == -1:
                out[sym]["sell_fraction"] = _epr_extras.get(
                    "sell_fraction", float(config.get("profit_take_sell_fraction", 0.50) or 0.50)
                )

    return out


