# Strategy class
# ──────────────────────────────────────────────────────────────────────────────

def _infer_action_intent(score: int, symbol: str, portfolio_emulator=None) -> str:
    if score > 0:
        return "add_buy" if _current_position_size(portfolio_emulator, symbol) > 0 else "initial_buy"
    if score < 0:
        return "sell_override"
    return "hold"


_overlay_bars_table_ensured = False


def _ensure_overlay_bars_table(conn):
    """Ensure GraphNexusOverlayBarsCache table exists."""
    global _overlay_bars_table_ensured
    if conn is None or _overlay_bars_table_ensured:
        return
    try:
        tables = list(_r.db(DB_NAME).table_list().run(conn))
        if NEXUS_OVERLAY_BARS_TABLE not in tables:
            _r.db(DB_NAME).table_create(NEXUS_OVERLAY_BARS_TABLE).run(conn)
        _overlay_bars_table_ensured = True
    except Exception:
        pass


def _overlay_bars_adjustment() -> str:
    """Bar adjustment this process expects cached rows to be in."""
    return str(os.environ.get("ALPACA_BARS_ADJUSTMENT", "split") or "split").lower()


def _overlay_bars_cache_get(conn, symbol: str) -> dict | None:
    """Load the cached bars DOC for a symbol from RethinkDB.

    Returns the whole row (bars + fetch_start/fetch_end coverage) so the
    caller can validate coverage. Rows with empty bars are treated as
    missing — the 2026-07-19 regime forensics found empty rows persisting
    forever and silently blinding the V31 regime detector.
    """
    if conn is None:
        return None
    try:
        _ensure_overlay_bars_table(conn)
        doc = _r.db(DB_NAME).table(NEXUS_OVERLAY_BARS_TABLE).get(symbol).run(conn)
        if not doc or not doc.get("bars"):
            return None
        # The row is keyed by symbol ALONE, so a row written before bars moved
        # to adjustment="split" holds RAW closes and would be served as if it
        # were split-adjusted — silently reintroducing the unadjusted-split
        # corruption (VGT 8-for-1 read as an -87% crash) that the fetch-side
        # change exists to remove. Treat a mismatched or missing adjustment as
        # a MISS so the row is refetched and overwritten. No purge needed.
        if str(doc.get("adjustment") or "") != _overlay_bars_adjustment():
            return None
        return doc
    except Exception:
        return None


def _overlay_bars_cache_set(conn, symbol: str, bars: list[dict],
                            fetch_start: str | None = None,
                            fetch_end: str | None = None) -> None:
    """Store bars for a symbol in RethinkDB.

    Empty results are never persisted (a failed fetch must retry next run,
    not poison every later run). Coverage metadata lets readers detect rows
    that do not extend far enough back for their window.
    """
    if conn is None or not bars:
        return
    try:
        _ensure_overlay_bars_table(conn)
        doc = {"id": symbol, "bars": bars,
               "adjustment": _overlay_bars_adjustment(),
               "cached_at": datetime.utcnow().isoformat()}
        if fetch_start:
            doc["fetch_start"] = fetch_start
        if fetch_end:
            doc["fetch_end"] = fetch_end
        _r.db(DB_NAME).table(NEXUS_OVERLAY_BARS_TABLE).insert(
            doc, conflict="replace",
        ).run(conn)
    except Exception:
        pass


def _overlay_bars_compute_range(config: dict, date_key: str) -> tuple[str, str]:
    """Compute the full date range for bar pre-fetching.

    Goes back far enough for the overlay lookback and forward to cover the
    entire backtest range (reuses Benzinga's range logic).
    """
    overlay_lookback = int(config.get("overlay_price_lookback_days", 30) or 30)
    learning_days = int(config.get("lookback_learning_days", config.get("learning_stage_days", 30)) or 30)
    lookahead = int(config.get("benzinga_lookahead_days", 0) or 0)
    try:
        base = datetime.strptime(date_key[:10], "%Y-%m-%d")
    except (ValueError, AttributeError):
        base = datetime.utcnow()
    # Start: enough history for the overlay lookback from the earliest possible day
    start = base - timedelta(days=overlay_lookback + int(overlay_lookback * 0.6) + 30)
    # 2026-07-24 (default OFF): the momentum watchlist scores over up to
    # momentum_watchlist_history_bars TRADING bars, but the prefetch above only
    # reaches ~55 trading bars back — so most names are unscoreable early and ALL
    # 60-day returns come back 0.0, causing adverse selection (weak names pass while
    # strong ones trip a parabolic ceiling on a false 0.0) and cache-luck
    # nondeterminism. When overlay_bars_min_history_bars is set, extend the start to
    # cover that many trading bars (~*1.5 calendar days + buffer).
    _min_hist_bars = int(config.get("overlay_bars_min_history_bars", 0) or 0)
    if _min_hist_bars > 0:
        _hist_start = base - timedelta(days=int(_min_hist_bars * 1.5) + 30)
        if _hist_start < start:
            start = _hist_start
    # End: cover the full backtest range (same logic as Benzinga bulk),
    # but cap at today to avoid fetching future dates (which always return 0 bars
    # and cause Alpaca to split into unnecessary chunks).
    end = base + timedelta(days=int(learning_days * 2.5) + lookahead + 60)
    today = datetime.utcnow()
    if end > today:
        end = today
    return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")


def _breadth_scan_movers(
    config,
    strategy_cache,
    date_key,
    alpaca_key,
    alpaca_secret,
    *,
    context=None,
    snapshot_store=None,
    session_close_resolver=None,
):
    """2026-07-24 market-wide BREADTH momentum scanner (default OFF).

    The stock finder only ever looked at ~100-250 symbols (trend ETFs + graph
    neighbours of holdings), so a genuine market mover unconnected to the book
    was invisible until news propagation surfaced it late (CAR: seen at +166%,
    bought the top). This rotates through a liquidity-floored full-market
    universe, prices each name AS-OF date_key (no look-ahead — bars are read
    `<= date_key`), and admits FRESH momentum movers to an evaluation set fed to
    the momentum watchlist. Safeguards vs today's two failure modes:
      - GLITCH filter: skip split-unadjusted/poisoned bars (adjacent close ratio
        outside [0.4, 2.5]) so a +2119% ghost can't be admitted.
      - PARABOLIC cap: skip already-blown-off names (r20 > cap / r60 > cap) so we
        catch movers EARLY, not at the top.
    EVALUATION ONLY — admitted names still face every buy gate (extension, V32
    ATH/mcap, circuit-breaker, fast-loser blacklist, cap, bear RS). The pool is
    built only in the configured regimes (default bull/chop); the bear reserved-
    buy lane is separately blocked from breadth names (they persist across flips).
    Returns the cumulative admitted symbol list. Never raises."""
    if not isinstance(strategy_cache, dict):
        return []
    _admitted = strategy_cache.setdefault("_breadth_scan_admitted", {})

    def _rollback():
        # Remove breadth-admitted names from the (never-evicting) momentum
        # watchlist and clear the pool. Merged watchlist membership — NOT just the
        # admitted set — is what feeds the reserved-buy lane AND momentum_breakout_add
        # (both bypass the bear RS gate; the latter uses the GLOBAL cap). So a plain
        # pool-clear leaves breadth names buyable in bear. Evicting them is what
        # actually makes the bear-block / disable real. A name that also has a
        # legitimate source re-enters via that source on the next eligible bar.
        _wl = strategy_cache.get("_momentum_watchlist")
        if isinstance(_wl, dict):
            for _s in list(_admitted.keys()):
                _wl.pop(_s, None)
        _admitted.clear()

    try:
        if not bool(config.get("breadth_scan_enabled", False)):
            # Disable = real rollback (evict + clear), so toggling OFF stops it.
            if _admitted:
                _rollback()
            return []
        _regs = [str(x).lower() for x in (config.get("breadth_scan_regimes") or ["bull", "chop"])]
        _reg = str(strategy_cache.get("_market_regime") or "").lower()
        if _reg not in _regs:
            # In bear/crash, EVICT breadth names from the watchlist (not just clear
            # the pool) so neither the reserved-buy lane nor momentum_breakout_add can
            # knife-catch them into a downtrend. Rebuilds when the regime recovers.
            if _reg in ("bear", "crash") and bool(config.get("breadth_scan_bear_reserved_lane_block", True)):
                _rollback()
            return list(_admitted.keys())   # off-regime: don't grow the pool
        from ticker_universe import get_breadth_universe
        _universe_kwargs = {}
        if context is not None:
            _universe_kwargs = {
                "context": context,
                "snapshot_store": snapshot_store,
            }
        _uni = get_breadth_universe(
            min_mcap=float(config.get("breadth_scan_min_mcap", 2e9) or 2e9),
            min_dollar_volume=float(config.get("breadth_scan_min_dollar_volume", 5e6) or 5e6),
            price_floor=float(config.get("buy_price_floor", 5.0) or 5.0),
            top_n=int(config.get("breadth_scan_universe_size", 500) or 500),
            **_universe_kwargs,
        )
        if not _uni:
            return list(_admitted.keys())
        _batch_n = max(1, int(config.get("breadth_scan_batch_per_bar", 50) or 50))
        _cur = int(strategy_cache.get("_breadth_cursor", 0) or 0) % len(_uni)
        _batch = _uni[_cur:_cur + _batch_n]
        if len(_batch) < _batch_n:
            _batch += _uni[:_batch_n - len(_batch)]
        strategy_cache["_breadth_cursor"] = (_cur + _batch_n) % len(_uni)
        _ensure_overlay_bars_cached(_batch, alpaca_key, alpaca_secret, strategy_cache, config, date_key)
        _bars_all = strategy_cache.get("_overlay_bars_raw") or {}
        _ds = str(date_key or "")[:10]
        _r5_min = float(config.get("breadth_scan_r5_min_pct", 7.0) or 7.0)
        _r20_min = float(config.get("breadth_scan_r20_min_pct", 12.0) or 12.0)
        _r20_cap = float(config.get("breadth_scan_r20_parabolic_cap_pct", 60.0) or 60.0)
        _r60_cap = float(config.get("breadth_scan_r60_parabolic_cap_pct", 150.0) or 150.0)
        _admit_per_bar = max(1, int(config.get("breadth_scan_admit_per_bar", 3) or 3))
        _admit_max = int(config.get("breadth_scan_admit_max", 150) or 150)
        _cands = []
        _pit_close_kwargs = {}
        if context is not None and not context.is_live:
            _pit_close_kwargs = {
                "context": context,
                "session_close_resolver": session_close_resolver,
            }
        for _sym in _batch:
            if _sym in _admitted:
                continue
            _c = _point_in_time_closes(
                _bars_all.get(_sym),
                _ds,
                **_pit_close_kwargs,
            )
            if len(_c) < 21 or _c[-1] <= 0:
                continue
            # Scan the FULL r60 window (not just r20) for split-signature jumps:
            # an unadjusted split in bars -60..-22 would leave r20 clean but make
            # r60 spuriously negative, defeating the r60 parabolic cap.
            _glitch = False
            for _i in range(max(1, len(_c) - 60), len(_c)):
                if _c[_i - 1] > 0 and not (0.4 <= _c[_i] / _c[_i - 1] <= 2.5):
                    _glitch = True
                    break
            if _glitch:
                continue
            _cur_px = _c[-1]
            _r5 = (_cur_px - _c[-6]) / _c[-6] * 100 if _c[-6] > 0 else 0.0
            _r20 = (_cur_px - _c[-21]) / _c[-21] * 100 if _c[-21] > 0 else 0.0
            _r60 = ((_cur_px - _c[-61]) / _c[-61] * 100) if (len(_c) >= 61 and _c[-61] > 0) else _r20
            if _r20 > _r20_cap or _r60 > _r60_cap:
                continue
            if _r5 >= _r5_min or _r20 >= _r20_min:
                _cands.append((_r5, _sym))
        _cands.sort(reverse=True)
        for _r5v, _sym in _cands[:_admit_per_bar]:
            if len(_admitted) >= _admit_max:
                break
            _admitted[_sym] = _ds
    except Exception as _e:
        from point_in_time_data import PointInTimeDataError

        if isinstance(_e, PointInTimeDataError):
            raise
        try:
            _log(f"breadth scan tolerated error: {_e}", "yellow")
        except Exception:
            pass
    return list(_admitted.keys())


def _split_adjust_bars(bars):
    """Return a split-CONTINUOUS copy of a daily bar list (oldest-first).

    2026-08-02. The Alpaca bars request omits the `adjustment` parameter, so
    Alpaca's RAW default applies and every series spanning a corporate action
    carries a step discontinuity. VGT 8-for-1: $808.88 -> $101.57 between two
    bars. Left raw, a 20-day return over that step reads about -87%, which sets
    the regime detector to bear, deletes the name from breadth discovery, and
    poisons every moving average and volatility estimate built on the series.

    This is the single write-path into `_overlay_bars_raw`, so adjusting here
    covers the regime detector, breadth scanner, momentum discovery and
    rediscovery, the falling-knife filter, sector context and price-trend
    detection at once. OHLC are scaled together so intrabar relationships hold.
    """
    # DEFAULT OFF. Bars are now requested with adjustment="split" (broker.py),
    # so the server already restates them and inference on top is redundant.
    # It is also actively dangerous: measured against 345 real discontinuities
    # in these caches, only 96 were splits — 176 were GENUINE crashes (MLTX
    # -90% on a trial failure, ATYR -83%), a 65% false-positive rate. Silently
    # rewriting those would erase real losses from the regime detector and the
    # falling-knife filter. Enable only to repair a cache known to predate the
    # adjustment change, and prefer purging that cache instead.
    if os.environ.get("NEXUS_INFER_BAR_SPLITS", "0").strip() not in ("1", "true", "True"):
        return bars
    if not isinstance(bars, list) or len(bars) < 2:
        return bars
    try:
        from split_detect import adjust_closes_for_splits
        closes = []
        for b in bars:
            if not isinstance(b, dict):
                return bars
            c = b.get("c", b.get("close"))
            closes.append(float(c) if c is not None else 0.0)
        if any(c <= 0 for c in closes):
            return bars
        _adj, found = adjust_closes_for_splits(closes)
        if not found:
            return bars
        # Cumulative factor to apply to every bar BEFORE each split index.
        factors = [1.0] * len(bars)
        for idx, ratio in found:
            for j in range(idx):
                factors[j] /= ratio
        out = []
        for b, f in zip(bars, factors):
            if f == 1.0:
                out.append(b)
                continue
            nb = dict(b)
            for k in ("o", "h", "l", "c", "open", "high", "low", "close"):
                if nb.get(k) is not None:
                    try:
                        nb[k] = float(nb[k]) * f
                    except (TypeError, ValueError):
                        pass
            for k in ("v", "volume"):
                if nb.get(k) is not None:
                    try:
                        nb[k] = float(nb[k]) / f
                    except (TypeError, ValueError):
                        pass
            out.append(nb)
        _log(f"Split-adjusted bar series: {len(found)} split(s) "
             f"{[(i, round(r, 2)) for i, r in found]}", "cyan")
        return out
    except Exception:
        return bars


def _ensure_overlay_bars_cached(
    symbols: list[str],
    alpaca_key: str,
    alpaca_secret: str,
    strategy_cache: dict,
    config: dict,
    date_key: str,
) -> None:
    """Ensure bars for the given symbols are in strategy_cache.

    On first call, bulk-fetches bars for all symbols over the full backtest
    date range and stores in strategy_cache + RethinkDB.  Subsequent calls
    only fetch symbols not already cached.
    """
    from broker import fetch_alpaca_historical_bars

    if not symbols or not alpaca_key:
        return

    bars_cache: dict[str, list[dict]] = _normalize_cache_mapping(strategy_cache, "_overlay_bars_raw")
    # Track which symbols have been checked against RethinkDB this session
    rdb_checked: set[str] = _normalize_cache_string_set(strategy_cache, "_overlay_bars_rdb_checked")

    # Compute / reuse the full fetch range
    if "_overlay_bars_range" not in strategy_cache:
        strategy_cache["_overlay_bars_range"] = _overlay_bars_compute_range(config, date_key)
    fetch_start, fetch_end = strategy_cache["_overlay_bars_range"]

    conn = _get_nexus_db_conn()

    # Identify symbols not yet in memory cache
    missing_mem = [s for s in symbols if s not in bars_cache]

    # For those missing from memory, try RethinkDB first
    still_missing = []
    for sym in missing_mem:
        if sym in rdb_checked:
            still_missing.append(sym)
            continue
        rdb_checked.add(sym)
        rdb_doc = _overlay_bars_cache_get(conn, sym)
        if rdb_doc is not None:
            rdb_bars = rdb_doc.get("bars") or []
            # Coverage check (2026-07-19 regime forensics): the row must
            # cover the requested range on BOTH ends. The old code only
            # checked the end, so rows fetched by a recent-window run
            # silently blinded every earlier-window backtest (regime
            # detector saw <21 point-in-time closes → permanent "bull").
            _last_bar_date = str(rdb_bars[-1].get("t", rdb_bars[-1].get("date", "")))[:10]
            _doc_start = str(rdb_doc.get("fetch_start") or "")[:10]
            if not _doc_start:
                # Legacy rows carry no coverage metadata — use the first bar.
                _doc_start = str(rdb_bars[0].get("t", rdb_bars[0].get("date", "")))[:10]
            try:
                from datetime import datetime as _dt_check
                _end_gap = (_dt_check.strptime(fetch_end, "%Y-%m-%d")
                            - _dt_check.strptime(_last_bar_date, "%Y-%m-%d")).days if _last_bar_date else 999
                _start_gap = (_dt_check.strptime(_doc_start, "%Y-%m-%d")
                              - _dt_check.strptime(fetch_start, "%Y-%m-%d")).days if _doc_start else 999
            except (ValueError, AttributeError):
                _end_gap = _start_gap = 0
            if _end_gap > 7 or _start_gap > 7:
                still_missing.append(sym)
                continue
            bars_cache[sym] = _split_adjust_bars(rdb_bars)
        else:
            still_missing.append(sym)

    if not still_missing:
        return

    # Fetch from Alpaca in batches of 50 symbols
    _log(f"Overlay bars: fetching {len(still_missing)} symbol(s) ({fetch_start} to {fetch_end})", "cyan")
    batch_size = 50
    for i in range(0, len(still_missing), batch_size):
        batch = still_missing[i:i + batch_size]
        try:
            fetched = fetch_alpaca_historical_bars(
                batch, fetch_start, fetch_end,
                key=alpaca_key, secret=alpaca_secret, timeframe="1Day",
            )
        except Exception as e:
            _log(f"Overlay bars fetch error: {e}", "yellow")
            fetched = {}

        for sym in batch:
            sym_bars = fetched.get(sym) or []
            sym_bars = _split_adjust_bars(sym_bars)
            bars_cache[sym] = sym_bars
            _overlay_bars_cache_set(conn, sym, sym_bars,
                                    fetch_start=fetch_start,
                                    fetch_end=fetch_end)

    loaded = sum(1 for s in still_missing if bars_cache.get(s))
    # Track symbols with 0 bars so discovery pruning can remove them next day
    _no_data: set[str] = _normalize_cache_string_set(strategy_cache, "_overlay_no_data_tickers")
    for s in still_missing:
        if not bars_cache.get(s):
            _no_data.add(s)
    _log(f"Overlay bars: cached {loaded}/{len(still_missing)} symbol(s) ({fetch_start} to {fetch_end})", "cyan")


def _fetch_price_history_for_overlay(
    symbols: list[str],
    as_of_date: str,
    lookback_days: int,
    alpaca_key: str,
    alpaca_secret: str,
    strategy_cache: dict | None = None,
    config: dict | None = None,
) -> dict[str, dict]:
    """Compute compact price metrics for overlay candidates from cached bars.

    Uses strategy_cache + RethinkDB bar cache (populated by
    _ensure_overlay_bars_cached).  Only calls Alpaca for symbols not yet
    cached.

    Returns {symbol: {"recent_closes": [...], "ret_5d": float, ...}}.
    """
    if not symbols or not alpaca_key:
        return {}

    _cache = strategy_cache if isinstance(strategy_cache, dict) else {}

    # Make sure bars are cached for these symbols
    if _cache and config:
        _ensure_overlay_bars_cached(
            symbols, alpaca_key, alpaca_secret, _cache, config, as_of_date,
        )

    bars_cache: dict[str, list[dict]] = _cache.get("_overlay_bars_raw", {})

    result: dict[str, dict] = {}
    for sym in symbols:
        all_bars = bars_cache.get(sym) or []
        if not all_bars:
            continue
        # Filter to bars on or before the last CLOSED session, sort ascending,
        # take last N. This list is rendered straight into the overlay LLM
        # prompt, so a same-session close here is future price action quoted to
        # the model as history — see _overlay_daily_cutoff.
        bars = _visible_overlay_bars(all_bars, _cache, as_of_date, config)
        bars = sorted(bars, key=lambda b: str(b.get("t", "")))[-lookback_days:]
        closes = []
        for b in bars:
            try:
                _c = float(b.get("c") or 0)
                if _c > 0:
                    closes.append(_c)
            except (TypeError, ValueError):
                continue
        if len(closes) < 3:
            continue
        current = closes[-1]
        high_20d = max(closes)
        low_20d = min(closes)
        volumes = [int(b.get("v", 0)) for b in bars]
        avg_vol = int(sum(volumes) / len(volumes)) if volumes else 0

        def _ret(n: int, _closes=closes) -> float | None:
            if len(_closes) > n and _closes[-(n + 1)] > 0:
                return round((_closes[-1] / _closes[-(n + 1)] - 1) * 100, 2)
            return None

        recent_closes = [round(c, 2) for c in closes[-5:]]

        result[sym] = {
            "recent_closes": recent_closes,
            "ret_5d": _ret(5),
            "ret_10d": _ret(10),
            "ret_20d": _ret(20),
            "current": round(current, 2),
            "high_20d": round(high_20d, 2),
            "low_20d": round(low_20d, 2),
            "pct_from_20d_high": round((current / high_20d - 1) * 100, 2) if high_20d > 0 else 0,
            "pct_from_20d_low": round((current / low_20d - 1) * 100, 2) if low_20d > 0 else 0,
            "avg_vol_20d": avg_vol,
        }
    return result


# ════════════════════════════════════════════════════════════════════════
# Persistent Momentum Watchlist — additive feature (V31 core untouched)
# ════════════════════════════════════════════════════════════════════════

def _build_momentum_watchlist(
    strategy_cache: dict,
    all_discovered: list[str],
    prices: dict[str, float] | None = None,
    price_history: dict[str, list[dict]] | None = None,
    config: dict | None = None,
    extra_sources: dict[str, list[str]] | None = None,
) -> dict[str, dict]:
    """Accumulate discovered tickers into a persistent momentum watchlist.

    Universal mode: when ``momentum_watchlist_universal_mode`` is True, merges
    ``all_discovered`` with every extra source in ``extra_sources`` (propagation
    expansion, BFQ pending, trend-tracked, held positions, sell-enforcement
    tickers, tickers with any non-zero score). No eviction — tickers are
    monitored for the rest of the backtest.
    """
    watchlist: dict[str, dict] = strategy_cache.setdefault("_momentum_watchlist", {})
    cfg = config or {}
    max_size = int(cfg.get("momentum_watchlist_max_size", 2000) or 2000)
    universal = bool(cfg.get("momentum_watchlist_universal_mode", False))
    bar_index = int(strategy_cache.get("_deployment_bar_index", 1) or 1)

    # Merge all sources into a single candidate set
    candidates: list[str] = list(all_discovered or [])
    source_counts: dict[str, int] = {"all_discovered": len(candidates)}
    if universal and extra_sources:
        for src_name, src_tickers in extra_sources.items():
            if not src_tickers:
                source_counts[src_name] = 0
                continue
            clean = [str(t).strip().upper() for t in src_tickers if t]
            source_counts[src_name] = len(clean)
            candidates.extend(clean)

    added = 0
    seen_this_call: set[str] = set()
    for ticker in candidates:
        sym = str(ticker).strip().upper()
        if not sym or sym in watchlist or sym in seen_this_call:
            continue
        # Fix (2026-05-26): keep leveraged/inverse/commodity ETFs out of the momentum
        # watchlist too — otherwise they re-enter the buy funnel via the rank/rotation
        # paths, bypassing the discovery-side exclusion (backtest 404780).
        if _is_excluded_momentum_etf(sym, cfg):
            continue
        seen_this_call.add(sym)
        if len(watchlist) >= max_size:
            break
        first_price = 0.0
        if prices and sym in prices:
            try:
                first_price = float(prices[sym])
            except (TypeError, ValueError):
                pass
        if first_price <= 0 and price_history:
            first_price = _latest_price_from_history(price_history, sym)
        watchlist[sym] = {
            "first_seen_bar": bar_index,
            "first_seen_price": first_price,
        }
        added += 1

    if added > 0:
        if universal and extra_sources:
            _src_summary = ", ".join(f"{k}={v}" for k, v in source_counts.items() if v)
            _log(
                f"Momentum watchlist: added {added} ticker(s), total={len(watchlist)} "
                f"(sources: {_src_summary})",
                "cyan",
            )
        else:
            _log(f"Momentum watchlist: added {added} ticker(s), total={len(watchlist)}", "cyan")
    return watchlist


def _load_watchlist_bars(
    watchlist: dict[str, dict],
    strategy_cache: dict,
    alpaca_key: str,
    alpaca_secret: str,
    config: dict,
    date_key: str,
) -> None:
    """Load bars for newly-added watchlist tickers.

    Fetches 252 bars (1yr) before backtest start through backtest end date
    in a single call.  Already-cached tickers are skipped (zero I/O).
    """
    if not watchlist or not alpaca_key:
        return
    bars_cache: dict[str, list[dict]] = strategy_cache.get("_overlay_bars_raw") or {}
    new_tickers = [sym for sym in watchlist if sym not in bars_cache]
    if not new_tickers:
        return
    _log(f"Momentum watchlist: loading bars for {len(new_tickers)} new ticker(s)", "cyan")
    _ensure_overlay_bars_cached(
        new_tickers, alpaca_key, alpaca_secret,
        strategy_cache, config, date_key,
    )


def _score_momentum_rank(
    watchlist: dict[str, dict],
    strategy_cache: dict,
    date_key: str,
    config: dict,
) -> list[tuple[str, float]]:
    """Score and rank all watchlist tickers by multi-timeframe momentum.

    Returns [(ticker, score)] sorted descending.  Only includes tickers
    with sufficient history and positive weighted score.
    """
    if not watchlist:
        return []
    # 2026-05-08 granularity-scaling fix: `momentum_min_history_bars`
    # and the `momentum_weights` lookback keys are TIME-SCALED bar
    # counts tuned at the 3600s baseline. At finer granularity (e.g.
    # 1200s) the un-scaled defaults read 1/3 of the wall-clock window
    # they intend — short intraday rips dominate over multi-week
    # trends, and high-conviction names like SNDK don't even meet the
    # min-history floor. Apply `_scale_bars` at every site so 63 bars
    # always ≈ 9 trading days regardless of cadence.
    min_history = _scale_bars(int(config.get("momentum_min_history_bars", 63) or 63), config)
    min_watchlist = int(config.get("momentum_min_watchlist_size", 20) or 20)
    max_runup = float(config.get("momentum_max_runup_multiple", 3.0) or 3.0)
    weights_raw = config.get("momentum_weights") or {}
    if not isinstance(weights_raw, dict) or not weights_raw:
        weights_raw = {"10": 0.05, "20": 0.20, "21": 0.25, "42": 0.25, "63": 0.25}
    weights: dict[int, float] = {}
    for k, v in weights_raw.items():
        try:
            scaled_lb = _scale_bars(int(k), config)
            if scaled_lb <= 0:
                continue
            # Sum weights if multiple raw keys map to the same scaled
            # lookback (e.g. 20 and 21 collapse to the same scaled bar
            # count at coarse cadences); preserves total weight mass.
            weights[scaled_lb] = weights.get(scaled_lb, 0.0) + float(v)
        except (ValueError, TypeError):
            pass
    if not weights:
        # Defaults are pre-scaled by _scale_bars on application above;
        # this fallback is for the truly-pathological case where every
        # config key was unparseable.
        weights = {
            _scale_bars(10, config): 0.05,
            _scale_bars(20, config): 0.20,
            _scale_bars(21, config): 0.25,
            _scale_bars(42, config): 0.25,
            _scale_bars(63, config): 0.25,
        }

    if len(watchlist) < min_watchlist:
        return []

    bars_cache: dict[str, list[dict]] = strategy_cache.get("_overlay_bars_raw") or {}
    buy_price_floor = float(config.get("buy_price_floor", 5.0) or 5.0)
    scored: list[tuple[str, float]] = []

    for sym, info in watchlist.items():
        all_bars = bars_cache.get(sym) or []
        filtered = _visible_overlay_bars(all_bars, strategy_cache, date_key, config)
        closes = [float(b.get("c", 0)) for b in filtered if float(b.get("c", 0) or 0) > 0]
        if len(closes) < min_history:
            continue
        # Skip tickers below buy_price_floor — the broker would reject them anyway
        if closes[-1] < buy_price_floor:
            continue
        first_price = float(info.get("first_seen_price", 0) or 0)
        if first_price <= 0:
            # Scope D A2: re-establish the runup baseline from the current live
            # bar when it is missing (e.g. stripped on a backtest->live boot, or
            # an entry the builder created without a price). Scope C popped
            # first_seen_price but nothing re-seeded it, permanently disabling
            # the runup ceiling for every hydrated watchlist ticker. Persisting
            # closes[-1] re-baselines from live bars (the strip's stated intent)
            # without changing this cycle's score (closes[-1] > closes[-1]*runup
            # is always False).
            first_price = closes[-1]
            info["first_seen_price"] = first_price
        if first_price > 0 and closes[-1] > first_price * max_runup:
            continue
        score = 0.0
        for lookback, weight in weights.items():
            if len(closes) <= lookback:
                continue
            prior = closes[-1 - lookback]
            if prior <= 0:
                continue
            ret = (closes[-1] - prior) / prior
            score += ret * weight
        if score > 0:
            scored.append((sym, round(score, 6)))

    scored.sort(key=lambda x: -x[1])
    # V31.4 Fix 19: filter falling-knives.
    # EXEMPT: held momentum positions + post-sell breakout candidates. Fix 19 is
    # a NEW-BUY gate, not a sell signal. Applying to held positions would set
    # their current_score=0 via _mw_scores_lookup, making them eligible for
    # eviction by Fix 2's score-delta gate (reviewer-flagged CRITICAL).
    _fk_exempt: set[str] = set()
    try:
        _fk_held = strategy_cache.get("_momentum_held") or {}
        if isinstance(_fk_held, dict):
            _fk_exempt.update(str(k).strip().upper() for k in _fk_held.keys())
        _fk_ps_hist = strategy_cache.get("_post_sell_breakout_history") or {}
        if isinstance(_fk_ps_hist, dict):
            _fk_exempt.update(str(k).strip().upper() for k in _fk_ps_hist.keys())
    except Exception:
        _fk_exempt = set()
    scored = _apply_falling_knife_filter(
        scored, bars_cache, config, date_key,
        exempt_set=_fk_exempt, strategy_cache=strategy_cache,
    )
    return scored


def _apply_falling_knife_filter(
    ranked: list[tuple[str, float]],
    bars_cache: dict[str, list[dict]],
    config: dict,
    date_key: str,
    exempt_set: set[str] | None = None,
    strategy_cache: dict | None = None,
) -> list[tuple[str, float]]:
    """V31.4 Fix 19: filter crashing stocks with short-term bounce.

    TLRY -58.6% 6mo scored 5.1+ because 63d max lookback misses long-term
    crash. This filter rejects tickers that fail ALL 3 gates:
      Gate 1: current < 52w_high * (1 - max_drawdown_pct/100)
      Gate 2: 6mo return < min_6mo_return_pct (negative)
      Gate 3: NOT in V-shape recovery (bounce >= v_bounce_pct off 6mo low
              AND current > SMA100, with SMA50 fallback for shorter history)

    Config:
      falling_knife_filter_enabled: True
      falling_knife_max_drawdown_from_52w_high_pct: 50
      falling_knife_min_6mo_return_pct: -25
      falling_knife_v_shape_bounce_pct: 30
      falling_knife_v_shape_above_ma: True
      falling_knife_exempt_tickers: ["SPY", "QQQ", "IWM", "DIA"]
    """
    if not config.get("falling_knife_filter_enabled", True):
        return ranked
    if not ranked:
        return ranked

    max_dd_pct = float(config.get("falling_knife_max_drawdown_from_52w_high_pct", 50.0) or 50.0)
    min_6mo_ret = float(config.get("falling_knife_min_6mo_return_pct", -25.0) or -25.0)
    v_bounce_pct = float(config.get("falling_knife_v_shape_bounce_pct", 30.0) or 30.0)
    check_above_ma = bool(config.get("falling_knife_v_shape_above_ma", True))
    # V31.4 config bounds clamp (reviewer-flagged): user sets 0.50 instead of
    # 50 would make threshold 99.5%, filtering nearly everything. Clamp ranges.
    max_dd_pct = max(10.0, min(99.0, max_dd_pct))
    min_6mo_ret = max(-99.0, min(0.0, min_6mo_ret))
    v_bounce_pct = max(5.0, min(100.0, v_bounce_pct))
    exempt_raw = config.get("falling_knife_exempt_tickers") or ["SPY", "QQQ", "IWM", "DIA"]
    exempt_tickers = {str(t).strip().upper() for t in exempt_raw if str(t).strip()}
    if exempt_set:
        exempt_tickers.update(exempt_set)

    _dd_threshold = 1.0 - (max_dd_pct / 100.0)
    filtered: list[tuple[str, float]] = []
    for sym, score in ranked:
        sym_u = str(sym).strip().upper()
        if sym_u in exempt_tickers:
            filtered.append((sym, score))
            continue
        all_bars = bars_cache.get(sym) or []
        f_bars = _visible_overlay_bars(all_bars, strategy_cache, date_key, config)
        closes = [float(b.get("c", 0) or 0) for b in f_bars if float(b.get("c", 0) or 0) > 0]
        # Insufficient history: don't filter (fail-safe)
        if len(closes) < 50:
            filtered.append((sym, score))
            continue
        cur = closes[-1]
        # Gate 1: 52w peak drawdown (use up to 252 bars)
        _52w_window = closes[-252:] if len(closes) >= 252 else closes
        high_52w = max(_52w_window)
        gate1 = cur < high_52w * _dd_threshold
        if not gate1:
            filtered.append((sym, score))
            continue
        # Gate 2: 6-month return (need full 126 bars — fail-safe pass if short
        # history, to avoid wrongly rejecting stocks with <6mo of data)
        if len(closes) < 126:
            filtered.append((sym, score))
            continue
        ret_6mo = (cur - closes[-126]) / closes[-126] * 100.0 if closes[-126] > 0 else 0.0
        gate2 = ret_6mo < min_6mo_ret
        if not gate2:
            filtered.append((sym, score))
            continue
        # Gate 3: V-shape recovery exemption
        low_window = closes[-126:] if len(closes) >= 126 else closes
        low_6mo = min(low_window)
        bounce_pct = ((cur - low_6mo) / low_6mo) * 100.0 if low_6mo > 0 else 0.0
        # MA check: SMA100 if available, SMA50 fallback
        ma_ok = True
        if check_above_ma:
            if len(closes) >= 100:
                sma = sum(closes[-100:]) / 100.0
            else:
                sma = sum(closes[-50:]) / 50.0
            ma_ok = cur > sma
        if bounce_pct >= v_bounce_pct and ma_ok:
            # V-shape recovery: exempt
            filtered.append((sym, score))
            continue
        # All 3 gates fired — filter out
        _log(
            f"V31.4 falling-knife filter: {sym} score={score:.2f} | "
            f"52w_dd={(1 - cur/high_52w)*100:.0f}% 6mo_ret={ret_6mo:+.0f}% "
            f"v_bounce={bounce_pct:.0f}% ma_ok={ma_ok}",
            "yellow",
        )
    return filtered


def _reserve_momentum_slots(
    ranked: list[tuple[str, float]],
    config: dict,
    held_momentum: set[str],
    open_positions: set[str],
    recent_sell_cooldown: set[str] | None = None,
    force_promote: set[str] | None = None,
) -> list[dict]:
    """Select top momentum candidates for reserved slot allocation.

    Returns candidate dicts ready for the allocation pipeline.
    Skips already-held tickers and tickers on the momentum re-buy cooldown.

    Phase ε.C.6 (BT294837 follow-up, 2026-05-19): the optional
    ``force_promote`` set marks tickers whose V31.4 cooldown-lift fired
    THIS bar (post-sell breakout / recovery_shortcut). Pre-ε.C.6 the
    lifted ticker still had to compete for momentum_watchlist slots and
    often lost to higher-ranking watchlist candidates (the operator's
    SNDK rebuy audit found this happened at BT294837 L7499 — SNDK was
    lifted but the slot went to LITE/TYRA which scored higher). Now
    force-promote takes priority over ranking so the lift translates
    to an executable buy intent. NO TICKER HARDCODING — works for any
    ticker whose V31.4 lift fired this bar.
    """
    n_reserved = int(config.get("momentum_reserved_slots", 2) or 2)
    n_open_momentum = len(held_momentum & open_positions)
    n_needed = max(0, n_reserved - n_open_momentum)
    if n_needed == 0 or not ranked:
        return []

    _cooldown = recent_sell_cooldown or set()
    _force = {str(s or "").strip().upper() for s in (force_promote or set()) if str(s or "").strip()}
    picks: list[dict] = []
    # Phase ε.C.6: prioritize force-promoted tickers (V31.4 lifted) first
    # so they actually translate to executable buy intents instead of
    # losing the slot to higher-scoring momentum candidates.
    ranked_normalized = list(ranked or [])
    if _force:
        ranked_map = {str(s or "").strip().upper(): sc for s, sc in ranked_normalized}
        forced_first: list[tuple[str, float]] = []
        rest: list[tuple[str, float]] = []
        for sym, score in ranked_normalized:
            sym_u = str(sym or "").strip().upper()
            if sym_u in _force and sym_u not in open_positions and sym_u not in _cooldown:
                forced_first.append((sym, score))
            else:
                rest.append((sym, score))
        # Append force-promote tickers NOT already in ranked (so a lifted
        # ticker that fell out of momentum watchlist still gets a slot).
        _ranked_keys = {str(s or "").strip().upper() for s, _ in ranked_normalized}
        for sym_u in _force:
            if sym_u in _ranked_keys or sym_u in open_positions or sym_u in _cooldown:
                continue
            # Synthesize a watchlist score floor — give force-promote tickers
            # the watchlist priority min raw_score so they don't get rejected
            # downstream for low score.
            _fp_score = float(config.get("watchlist_priority_min_raw_score", 0.35) or 0.35)
            forced_first.append((sym_u, _fp_score))
        ranked_normalized = forced_first + rest
    for sym, score in ranked_normalized:
        if sym in open_positions:
            continue
        if sym in _cooldown:
            continue
        if len(picks) >= n_needed:
            break
        # η.E — Phase η (2026-05-20): floor + natural-signal differentiator.
        # Preserves natural-signal info inside the floored value so downstream
        # tie-breaks (η.G swap eligibility) and telemetry can see the
        # underlying technical-momentum strength.
        _eta_e_floored = max(score, 1.50)
        if config.get("eta_floor_differentiator_enabled", True):
            _eta_e_diff = min(0.20, max(0.0, float(score)) * 0.5)
            _eta_e_raw_net = _eta_e_floored + _eta_e_diff
        else:
            _eta_e_raw_net = _eta_e_floored
        picks.append({
            "ticker": sym,
            "raw_net_score": _eta_e_raw_net,
            "raw_net_natural": float(score),
            "signal_source": "momentum_watchlist",
            "is_watchlist_member": True,
            "is_watchlist_priority": True,
            "is_propagation_expansion": False,
            "grace_eligible": True,
            "momentum_watchlist_score": score,
            "is_force_promote": str(sym or "").strip().upper() in _force,
        })
    return picks


def _rotate_momentum_slots(
    ranked: list[tuple[str, float]],
    held_momentum: dict[str, dict],
    config: dict,
    bar_index: int,
    open_positions: set[str],
    recent_sell_cooldown: set[str] | None = None,
) -> tuple[str | None, str | None, float]:
    """Check if a held momentum position should be swapped for a stronger one.

    Returns (sell_ticker, buy_ticker, buy_score) or (None, None, 0.0).
    Skips tickers on the momentum re-buy cooldown to prevent churn.
    """
    min_delta = float(config.get("momentum_swap_min_delta", 0.30) or 0.30)
    # 2026-05-07 granularity-scaling: min wall-clock hold before a momentum
    # swap is allowed; preserve baseline duration across cadences.
    min_hold = _scale_bars(int(config.get("momentum_swap_min_hold_bars", 10) or 10), config)
    if not ranked or not held_momentum:
        return None, None, 0.0

    _cooldown = recent_sell_cooldown or set()
    weakest_ticker = None
    weakest_score = float("inf")
    for sym, info in held_momentum.items():
        if sym not in open_positions:
            continue
        bars_held = bar_index - int(info.get("bar_entered", bar_index))
        if bars_held < min_hold:
            continue
        current_score = float(info.get("current_score", 0) or 0)
        if current_score < weakest_score:
            weakest_score = current_score
            weakest_ticker = sym

    if weakest_ticker is None:
        return None, None, 0.0

    for sym, score in ranked:
        if sym in open_positions:
            continue
        if sym in _cooldown:
            continue
        if score - weakest_score > min_delta:
            return weakest_ticker, sym, score
        break
    return None, None, 0.0


def _rotate_momentum_vs_portfolio_weakest(
    ranked: list[tuple[str, float]],
    portfolio_pnl: dict[str, dict],
    config: dict,
    open_positions: set[str],
    recent_sell_cooldown: set[str] | None = None,
) -> tuple[str | None, str | None, float, float]:
    """V31.2 Fix 2 (reframed): portfolio-wide momentum swap via score delta.

    Uses momentum-score delta (incoming - held) as the eligibility gate,
    not P&L% (which penalizes market-beta holders unfairly). A position
    with low momentum score but positive P&L can still be swapped for a
    stronger momentum candidate. Winner_lock still applies as independent
    guard to protect genuine compounders.

    portfolio_pnl: dict[ticker -> {"unrealized_pct": float, "held_days": int,
                                    "winner_locked": bool, "held_score": float}]

    Returns (sell_ticker, buy_ticker, buy_score, sell_pnl_pct) or (None, None, 0.0, 0.0).
    """
    if not config.get("momentum_swap_vs_portfolio_enabled", True):
        return None, None, 0.0, 0.0
    min_hold = int(config.get("momentum_swap_vs_portfolio_min_hold_days", 10) or 10)
    # V31.2: score-delta gate replaces max_held_pnl_pct gate
    score_delta_min = float(config.get("momentum_swap_score_delta_min", 0.50) or 0.50)
    if not ranked or not portfolio_pnl:
        return None, None, 0.0, 0.0

    _cooldown = recent_sell_cooldown or set()
    # V31.4 Fix 14: block swap on profitable seasoned holds.
    # Fix A was net -180bps in V31.3 backtest because it churned winners
    # for marginal momentum upgrades (LITE +14% → HYMC, +0.5% → TLRY -11%).
    # Skip any held position that's profitable AND seasoned; let it ride.
    _swap_block_pnl = float(config.get("momentum_swap_min_pnl_to_block", 0.05) or 0.05) * 100.0
    _swap_block_days = int(config.get("momentum_swap_min_held_days_to_block", 10) or 10)
    # Find weakest held by momentum SCORE (not P&L)
    weakest_ticker: str | None = None
    weakest_score = float("inf")
    weakest_pnl = 0.0
    for sym, info in portfolio_pnl.items():
        if sym not in open_positions:
            continue
        if bool(info.get("winner_locked", False)):
            continue
        held_days = int(info.get("held_days") or 0)
        if held_days < min_hold:
            continue
        # V31.4 Fix 14: block seasoned profitable holds from eviction
        held_pnl_val = float(info.get("unrealized_pct") or 0.0)
        if held_days >= _swap_block_days and held_pnl_val >= _swap_block_pnl:
            continue
        held_score = float(info.get("held_score", 0.0) or 0.0)
        if held_score < weakest_score:
            weakest_score = held_score
            weakest_ticker = sym
            weakest_pnl = held_pnl_val

    if weakest_ticker is None:
        return None, None, 0.0, 0.0

    for sym, score in ranked:
        if sym in open_positions:
            continue
        if sym in _cooldown:
            continue
        if sym == weakest_ticker:
            continue
        # V31.2: swap fires when incoming score beats held score by min_delta
        if (score - weakest_score) >= score_delta_min:
            return weakest_ticker, sym, score, weakest_pnl
        break
    return None, None, 0.0, 0.0


def _format_benzinga_for_symbol(bz_data: dict[str, list], symbol: str, use_toon: bool = True) -> str:
    """Build a compact per-symbol Benzinga context string for the trade overlay."""
    if not bz_data:
        return ""
    sym_upper = symbol.upper()
    sections: list[str] = []
    # Ratings
    sym_ratings = [r for r in bz_data.get("ratings", []) if (r.get("ticker") or "").upper() == sym_upper]
    if sym_ratings:
        lines = [f"  {r.get('date','')} {r.get('action','')} → {r.get('rating','')} by {r.get('analyst','')} PT={r.get('pt','')}" for r in sym_ratings[:5]]
        sections.append("Analyst ratings:\n" + "\n".join(lines))
    # Insider trades
    sym_insider = [r for r in bz_data.get("insider_trades", []) if (r.get("ticker") or "").upper() == sym_upper]
    if sym_insider:
        lines = [f"  {r.get('date','')} {r.get('insider','')} ({r.get('title','')}) {r.get('direction','')} {r.get('shares','')} shares @{r.get('price','')}" for r in sym_insider[:5]]
        sections.append("Insider trades:\n" + "\n".join(lines))
    # Earnings
    sym_earn = [r for r in bz_data.get("earnings", []) if (r.get("ticker") or "").upper() == sym_upper]
    if sym_earn:
        lines = []
        for r in sym_earn[:3]:
            eps_str = f"EPS est={r.get('eps_est','')} act={r.get('eps_actual','')}" if r.get("eps_actual") else f"EPS est={r.get('eps_est','')}"
            lines.append(f"  {r.get('date','')} {r.get('period','')} {eps_str}")
        sections.append("Earnings:\n" + "\n".join(lines))
    # Gov trades
    sym_gov = [r for r in bz_data.get("gov_trades", []) if (r.get("ticker") or "").upper() == sym_upper]
    if sym_gov:
        lines = [f"  {r.get('date','')} {r.get('politician','')} ({r.get('chamber','')}) {r.get('direction','')} ~${r.get('value_usd','')}" for r in sym_gov[:3]]
        sections.append("Gov trades:\n" + "\n".join(lines))
    # M&A
    sym_ma = [r for r in bz_data.get("ma", []) if (r.get("ticker") or "").upper() == sym_upper]
    if sym_ma:
        lines = [f"  {r.get('date','')} {r.get('deal_type','')} by {r.get('acquirer','')} status={r.get('deal_status','')}" for r in sym_ma[:3]]
        sections.append("M&A:\n" + "\n".join(lines))
    if not sections:
        return ""
    return "Benzinga data for " + sym_upper + ":\n" + "\n".join(sections) + "\n"


# ── Overlay prompt canonicalization ───────────────────────────────────────
#
# `_canonicalize_prompt_value` kills the encoding-noise half of the cache-miss
# problem (float repr, key order). The other half is semantic: fields that
# genuinely differ between two runs of the same window while saying nothing new
# about the trade. They are handled here, per-payload, because deciding what is
# safe to drop needs to know what the field means — a blanket strip at the
# `_to_prompt_payload` chokepoint would also delete `supporting_article_hashes`
# from the event-maintenance prompt, which the model is asked to cite back.

_OVERLAY_STRIP_KEYS = frozenset({
    # Scope/provenance stamps the strategy attaches to its own history rows.
    "supporting_article_hashes", "article_hash", "history_scope_id",
    "base_instance_id", "history_model_stamp", "strategy_config_hash",
    "feature_version", "cache_scope_id", "instance_id",
    # 2026-08-02: the set above was only ever applied to `active_events`.
    # `feature_row` and `base_score_doc` went into the prompt untouched, so
    # anything run-scoped riding along in them reached the hash. Nothing below
    # is decision-bearing — they are row identity, PIT bookkeeping, telemetry
    # correlation ids, and wall-clock stamps.
    "id", "backtest_id", "run_id",
    "pit_manifest_id", "pit_provenance", "pit_as_of",
    "trained_at", "cached_at", "computed_at", "generated_at",
    "created_at", "updated_at",
    "_telemetry_backtest_id", "_telemetry_instance_id",
})


def _strip_run_scoped(value: Any, _depth: int = 0) -> Any:
    """Recursively drop `_OVERLAY_STRIP_KEYS` from a prompt payload."""
    if _depth >= _PROMPT_CANON_MAX_DEPTH:
        return value
    if isinstance(value, dict):
        return {
            key: _strip_run_scoped(item, _depth + 1)
            for key, item in value.items()
            if key not in _OVERLAY_STRIP_KEYS
        }
    if isinstance(value, (list, tuple)):
        return [_strip_run_scoped(item, _depth + 1) for item in value]
    return value


def _training_row_band(rows: Any) -> int:
    """Collapse the ML training-row count to a 1-2-5 magnitude band.

    `ml_training_rows` is `NexusModelBundle.row_count`: how many
    context-by-outcome rows this instance had accumulated when the bar's model
    was fitted. It grows every bar, and two runs of the same window never agree
    on it — run 2 starts against a table that already holds run 1's rows, and
    because the two runs trade different symbols they write different ones.
    Embedded raw it changed the overlay prompt on literally every call, which on
    its own pins the cache hit rate at zero.

    It is not decoration: the prompt warns the model when the ML head was fitted
    on very little data. But only the order of magnitude carries that warning,
    so a 1-2-5 ladder keeps "trained on ~2000 rows" while making 2,431 and 2,687
    the same prompt.
    """
    try:
        n = int(rows or 0)
    except (TypeError, ValueError):
        return 0
    if n <= 0:
        return 0
    band = 1
    while band * 10 <= n:
        band *= 10
    for step in (5, 2, 1):
        if n >= band * step:
            return band * step
    return band


def _canonicalize_overlay_base_doc(base_score_doc: Any) -> dict:
    """Strip run-scoped keys and band `ml_training_rows` in the base-score doc."""
    doc = _strip_run_scoped(base_score_doc if isinstance(base_score_doc, dict) else {})
    ml = doc.get("ml")
    if isinstance(ml, dict) and "ml_training_rows" in ml:
        ml = dict(ml)
        ml["ml_training_rows"] = _training_row_band(ml.get("ml_training_rows"))
        doc["ml"] = ml
    return doc


def _canonical_active_event_order(events: Any) -> list[dict]:
    """Re-apply `_sorted_active_event_records`' ordering, without renormalizing.

    Every production path already hands the overlay a sorted list, so this is a
    no-op there. It exists because the overlay TRUNCATES the list
    (`overlay_max_events_per_symbol`, default 12): if a future caller ever
    forwards events straight off an unordered RethinkDB scan, an unstable order
    would silently change WHICH events the model sees, not just the order it
    sees them in. Ordering only — no field is rewritten.
    """
    return sorted(
        (ev for ev in (events or []) if isinstance(ev, dict)),
        key=lambda ev: (
            str(ev.get("event_cluster_key") or ""),
            str(ev.get("event_name") or ""),
            str(ev.get("event_type") or ""),
        ),
    )


def _canonical_historical_analogs(analogs: Any) -> list[dict]:
    """Impose a total order on the analog list before it reaches the prompt.

    `_retrieve_historical_analogs` reads `GraphNexusTradeOutcomes` ordered only
    by `latest_observation_date` — a field `_update_indefinite_outcomes`
    rewrites to the current bar on hundreds of rows every bar, so most of the
    80-row window is one giant tie that RethinkDB breaks by index-scan order.
    The result is a bag of comparable past trades, not a ranking, so a total
    order costs nothing and stops the prompt reshuffling between runs.
    Most-recent-first is kept; the symbol/event tiebreak is what makes it total.
    """
    rows = [dict(row) for row in (analogs or []) if isinstance(row, dict)]
    rows.sort(key=lambda row: (
        str(row.get("symbol") or ""),
        str(row.get("dominant_event_type") or ""),
        str(row.get("government_action_type") or ""),
    ))
    rows.sort(key=lambda row: str(row.get("entry_date") or ""), reverse=True)
    return rows


# ── Overlay result cache (fast mode only) ─────────────────────────────────

def _overlay_result_cache_key(
    symbol: str, date_key: str, raw_net_score: float,
    active_events: list[dict], model: str,
) -> str:
    """Coarse cache key: symbol + date + score bucket + event types + model."""
    score_bucket = round(raw_net_score, 1)
    event_types = sorted({str(e.get("event_type", "")).lower() for e in active_events if e})
    raw = f"{symbol}|{date_key}|{score_bucket}|{','.join(event_types)}|{model}"
    return hashlib.md5(raw.encode()).hexdigest()[:32]


def _check_overlay_result_cache(
    conn, symbol: str, date_key: str, raw_net_score: float,
    active_events: list[dict], config: dict,
) -> dict | None:
    """Check overlay result cache. Returns cached overlay dict or None."""
    from _phase_alpha_helpers import evidence_cache_read_allowed
    if not evidence_cache_read_allowed("overlay_result"):
        return None
    if conn is None or _r is None or not config.get("overlay_result_cache_enabled", False):
        return None
    _ensure_nexus_history_table(conn, NEXUS_OVERLAY_RESULT_CACHE_TABLE)
    model = str(config.get("overlay_llm_model", "") or "").strip().lower()
    key = _overlay_result_cache_key(symbol, date_key, raw_net_score, active_events, model)
    try:
        doc = _r.db(DB_NAME).table(NEXUS_OVERLAY_RESULT_CACHE_TABLE).get(key).run(conn)
        if doc and doc.get("result"):
            _log(f"Overlay CACHE HIT [fast]: {symbol} (key={key[:12]}…)", "cyan")
            return dict(doc["result"])
    except Exception:
        pass
    return None


def _store_overlay_result_cache(
    conn, symbol: str, date_key: str, raw_net_score: float,
    active_events: list[dict], config: dict, result: dict,
) -> None:
    """Store overlay result in cache."""
    from _phase_alpha_helpers import evidence_cache_write_allowed
    if not evidence_cache_write_allowed("overlay_result"):
        return
    if conn is None or _r is None or not config.get("overlay_result_cache_enabled", False):
        return
    if not result:
        return
    model = str(config.get("overlay_llm_model", "") or "").strip().lower()
    key = _overlay_result_cache_key(symbol, date_key, raw_net_score, active_events, model)
    try:
        _r.db(DB_NAME).table(NEXUS_OVERLAY_RESULT_CACHE_TABLE).insert({
            "id": key, "symbol": symbol, "date_key": date_key,
            "model": model, "result": result,
            "raw_net_score": round(raw_net_score, 4),
        }, conflict="replace").run(conn, noreply=True)
    except Exception:
        pass


def _overlay_max_output_tokens(config: dict) -> int:
    """Wire ``max_tokens`` for the trade-overlay LLM call.

    The overlay response is a tiny bounded JSON, but a reasoning model (e.g.
    Nemotron) will otherwise spiral into tens of thousands of thinking tokens:
    passing 0 makes the OpenRouter path inject a 32,768-token reasoning-safe
    default, and a ``requests`` between-bytes read timeout can't stop a steadily
    streaming generation — so one runaway symbol stalls the whole bar. Cap it to
    a value that fits normal reasoning yet cuts runaways short (a truncated call
    falls back to the base score for that symbol). Coerce 0/invalid to the
    default so the overlay can never be uncapped again. Tunable via
    ``overlay_llm_max_output_tokens`` (default 2500).
    """
    try:
        n = int((config or {}).get("overlay_llm_max_output_tokens", 2500) or 2500)
    except (TypeError, ValueError):
        n = 2500
    return n if n > 0 else 2500


def _apply_trade_overlay(
    symbol: str,
    base_score_doc: dict,
    *,
    feature_row: dict,
    active_events: list[dict],
    historical_analogs: list[dict],
    config: dict,
    price_history: dict | None = None,
    benzinga_context: str = "",
    date_key: str = "",
) -> tuple[dict, dict]:
    provider, api_key, model, prompt_version = _resolve_role_llm_config(config, "overlay")
    provider_config = _resolve_role_llm_provider_config(config, "overlay")
    if not api_key or not config.get("llm_overlay_enabled", True):
        return {}, {}
    use_toon = bool(config.get("use_toon_format", True))
    system_prompt = (
        "Return only a bounded structured trade overlay as minimal JSON. "
        "Use all supplied context (graph, news, ML, price history, analyst/insider data if present, "
        "active events) to adjust or block the trade candidate. "
        "When graph relationships show strong multi-path signals (raw >= 0.30), favor 'buy' bias "
        "unless there is clear negative evidence (bad earnings, downtrend, sell-side downgrades). "
        "Use short alias keys: ds (delta_score), cd (confidence_delta), db (decision_bias), "
        "bb (buy_block), sb (sell_block), rc (reason_codes), fb (feature_boosts), fp (feature_penalties), ra (rationale). "
        "Omit fields with default/empty values. Keep rationale under 15 words. "
        "Keep reason_codes/feature_boosts/feature_penalties to max 3 items each, max 5 words per item. "
        "Minimize total output tokens."
    )
    # Canonicalize the two payloads that were previously handed to the prompt
    # exactly as built: `base_score_doc` carries `ml.ml_training_rows`, which
    # differs on every bar and between runs, and `feature_row` was never
    # stripped at all. See `_canonicalize_overlay_base_doc`.
    base_score_doc = _canonicalize_overlay_base_doc(base_score_doc)
    feature_row_ctx = _strip_run_scoped(feature_row if isinstance(feature_row, dict) else {})
    # `feature_row` never carried a `date_key` (it is the ML feature vector),
    # so every `feature_row.get("date_key")` below silently resolved to "" —
    # collapsing every date into one overlay-result-cache bucket and leaving
    # `decision_at` blank on the evidence record. Take it from the caller.
    date_key = str(date_key or feature_row_ctx.get("date_key") or "")
    # ── Fast mode: check overlay result cache before building prompt ──
    _fast_mode_overlay = bool(config.get("nexus_fast_mode", False))
    if _fast_mode_overlay:
        _raw_score = float(base_score_doc.get("graph_raw_score", 0.0) or 0.0)
        _cache_conn = _get_nexus_db_conn(reuse=False)
        _cached = _check_overlay_result_cache(_cache_conn, symbol, date_key, _raw_score, active_events, config)
        if _cache_conn:
            try:
                _cache_conn.close()
            except Exception:
                pass
        if _cached is not None:
            return _cached, {}
    # ── Fast mode: trim events to symbol-relevant only ──
    active_events = _canonical_active_event_order(active_events)
    _max_events = int(config.get("overlay_max_events_per_symbol", 12) or 12)
    if _fast_mode_overlay:
        _max_events = min(_max_events, int(config.get("overlay_max_events_per_symbol", 5) or 5))
        # Filter to events affecting this symbol's sector or tickers
        _sym_upper = symbol.upper()
        _relevant = [ev for ev in active_events if _sym_upper in str(ev.get("affected_tickers", []))]
        if not _relevant:
            _relevant = active_events  # fallback to all if none match
        active_events = _relevant
    stripped_events = _strip_run_scoped(list(active_events[:_max_events]))
    # ── Fast mode: trim price history ──
    _price_bar_limit = int(config.get("overlay_price_history_bars", 0) or 0)
    if _fast_mode_overlay and _price_bar_limit > 0 and price_history:
        if isinstance(price_history, dict) and "bars" in price_history:
            price_history = dict(price_history)
            price_history["bars"] = price_history["bars"][-_price_bar_limit:]
        elif isinstance(price_history, list):
            price_history = price_history[-_price_bar_limit:]
    price_ctx = ""
    if price_history:
        price_ctx = (
            f"Price history (recent daily): {_to_prompt_payload(price_history, use_toon=use_toon)}\n"
            "Consider: Is the stock in an uptrend or downtrend? Is it near highs (momentum) or near lows (potential reversal or value trap)? "
            "Does recent price action support or contradict the news-based signal?\n"
        )
    bz_ctx = ""
    if benzinga_context:
        _bz_hints: list[str] = []
        if "Analyst ratings" in benzinga_context:
            _bz_hints.append("analyst upgrades/downgrades with PT changes are meaningful signals")
        if "Insider trades" in benzinga_context:
            _bz_hints.append("insider buys >$100K are bullish, large insider sells may be bearish")
        if "Earnings" in benzinga_context:
            _bz_hints.append("recent earnings beats/misses affect near-term momentum")
        if "Gov trades" in benzinga_context:
            _bz_hints.append("congressional trades may signal informed sentiment")
        if "M&A" in benzinga_context:
            _bz_hints.append("M&A activity can drive significant price moves")
        _bz_guidance = ". ".join(_bz_hints) + ".\n" if _bz_hints else ""
        bz_ctx = benzinga_context + _bz_guidance
    # ML quality warning for low-confidence models
    ml_quality_ctx = ""
    _ml_doc = base_score_doc.get("ml") or {} if isinstance(base_score_doc, dict) else {}
    _ml_data_conf = float(_ml_doc.get("ml_data_confidence", 1.0) or 1.0)
    _ml_train_rows = int(_ml_doc.get("ml_training_rows", 0) or 0)
    if _ml_data_conf < 0.5 and _ml_train_rows > 0:
        # "~" because the count is banded — see `_training_row_band`.
        ml_quality_ctx = (
            f"IMPORTANT: ML model trained on only ~{_ml_train_rows} rows (confidence: {_ml_data_conf*100:.0f}%). "
            "ML predictions are UNRELIABLE. Weight graph relationships, news sentiment, and price action "
            "MORE heavily than ML signals.\n"
        )
    graph_ctx = ""
    _graph_rels = base_score_doc.get("graph_relationships") or [] if isinstance(base_score_doc, dict) else []
    if _graph_rels:
        graph_ctx = (
            f"Graph signal context (propagation raw={base_score_doc.get('graph_raw_score', 0):.3f}, "
            f"{base_score_doc.get('graph_n_paths', 0)} paths):\n"
            + "\n".join(f"  - {r}" for r in _graph_rels) + "\n"
            "These relationships represent real supply-chain, institutional, or competitive connections "
            "discovered via Neo4j graph analysis. Strong multi-path graph signals indicate structural "
            "tailwinds — weight them accordingly even if news sentiment is neutral.\n"
        )
    prompt = (
        f"Candidate ticker: {symbol}\n"
        + ml_quality_ctx
        + graph_ctx
        + f"Base score context: {_to_prompt_payload(base_score_doc, use_toon=use_toon)}\n"
        f"Feature row: {_to_prompt_payload(feature_row_ctx, use_toon=use_toon)}\n"
        + price_ctx
        + bz_ctx
        + f"Active events as of evaluation date: {_to_prompt_payload(stripped_events, use_toon=use_toon)}\n"
        f"Historical analogs: {_to_prompt_payload(_canonical_historical_analogs(historical_analogs)[:5], use_toon=use_toon)}\n"
        'Output example: {"ds":0.1,"cd":0.05,"db":"buy","rc":["strong_earnings"],"ra":"Q3 beat estimates"}\n'
        "Return only the bounded overlay decision."
    )
    _overlay_timeout = int(config.get("overlay_llm_timeout_sec", 60) or 60)
    # Enter the telemetry context INSIDE the worker (this body runs in a
    # ThreadPoolExecutor thread with no ambient context) so usage rows
    # attribute call_site="overlay" instead of "(unset)". The attribution_keys
    # below still enrich the LLMCriticalFailure exception path — both needed.
    with llm_call_context(
        backtest_id=(config or {}).get("_telemetry_backtest_id"),
        instance_id=(config or {}).get("_telemetry_instance_id"),
        strategy="GraphNexusAnalysis",
        call_site="overlay",
    ):
        raw = _scl_guarded(
            provider,
            api_key,
            model,
            prompt,
            _TradeOverlayResponse,
            attribution_keys={
                "backtest_id": (config or {}).get("_telemetry_backtest_id"),
                "instance_id": (config or {}).get("_telemetry_instance_id"),
                "call_site": "overlay",
            },
            evidence_context=_model_evidence_context(
                prompt,
                decision_at=date_key,
                call_site="overlay",
                role="trade_overlay",
                subject=symbol,
                local_sequence=0,
            ),
            system_prompt=system_prompt,
            max_output_tokens=_overlay_max_output_tokens(config),
            timeout_sec=_overlay_timeout,
            retries=1,
            output_retries=2,
            provider_config=provider_config,
            prefer_raw_json=True,
        )
    trace = _build_llm_trace("overlay", provider, model, prompt, system_prompt, prompt_version, raw is not None)
    if raw is None:
        return {}, trace
    base_max_delta = abs(float(config.get("llm_overlay_max_delta", 0.2) or 0.2))
    if _ml_data_conf < 0.3:
        max_delta = base_max_delta * 2.0  # 0.4 override room when ML is unreliable
    elif _ml_data_conf < 0.6:
        max_delta = base_max_delta * 1.5  # 0.3
    else:
        max_delta = base_max_delta         # 0.2
    max_conf = abs(float(config.get("llm_overlay_max_confidence_delta", 0.2) or 0.2))
    _result_dict = {
        "delta_score": max(-max_delta, min(max_delta, float(raw.delta_score or 0.0))),
        "confidence_delta": max(-max_conf, min(max_conf, float(raw.confidence_delta or 0.0))),
        "decision_bias": str(raw.decision_bias or "hold").strip().lower(),
        "buy_block": bool(raw.buy_block),
        "sell_block": bool(raw.sell_block),
        "reason_codes": list(raw.reason_codes or []),
        "feature_boosts": list(raw.feature_boosts or []),
        "feature_penalties": list(raw.feature_penalties or []),
        "rationale": str(raw.rationale or "").strip()[:500],
    }
    # ── Fast mode: store result in overlay cache ──
    if _fast_mode_overlay:
        _store_conn = _get_nexus_db_conn(reuse=False)
        _store_overlay_result_cache(
            _store_conn, symbol, date_key,
            float(base_score_doc.get("graph_raw_score", 0.0) or 0.0),
            active_events, config, _result_dict,
        )
        if _store_conn:
            try:
                _store_conn.close()
            except Exception:
                pass
    return _result_dict, trace


def _build_etf_trend_context(symbol: str, active_trends: list, config: dict) -> str:
    """Build trend context string for ETF overlay prompt."""
    matching_trends = []
    for trend in (active_trends or []):
        etfs = _get_etfs_for_trend(trend, max_etfs=10)
        if symbol in etfs:
            matching_trends.append({
                "name": trend.get("name", "unknown"),
                "strength": trend.get("strength", 0),
                "age_days": trend.get("age_days", 0),
                "status": trend.get("status", "active"),
                "last_confirmed": trend.get("last_confirmed_date", ""),
                "description": (trend.get("description", "") or "")[:100],
            })
    if not matching_trends:
        return "No specific trend context available"
    # `active_trends` arrives in RethinkDB scan order, which is not a ranking
    # and is not stable across runs. Order the block so the ETF overlay prompt
    # hashes the same for the same set of trends.
    matching_trends.sort(key=lambda t: (str(t.get("name") or ""), str(t.get("last_confirmed") or "")))
    use_toon = bool(config.get("use_toon_format", True))
    return _to_prompt_payload(matching_trends, use_toon=use_toon)


def _apply_etf_trade_overlay(
    symbol: str,
    base_score_doc: dict,
    *,
    feature_row: dict,
    active_events: list[dict],
    active_trends: list,
    config: dict,
    price_history: dict | None = None,
    date_key: str = "",
) -> tuple[dict, dict]:
    """Trade overlay for ETFs — uses trend context instead of company context."""
    provider, api_key, model, prompt_version = _resolve_role_llm_config(config, "overlay")
    provider_config = _resolve_role_llm_provider_config(config, "overlay")
    if not api_key or not config.get("llm_overlay_enabled", True):
        return {}, {}
    use_toon = bool(config.get("use_toon_format", True))
    system_prompt = (
        "Return only a bounded structured trade overlay as minimal JSON. "
        "You are evaluating an ETF (exchange-traded fund), NOT an individual stock. "
        "Focus on: the underlying trend/theme driving this ETF, macro conditions, "
        "sector momentum, and whether the trend is strengthening or weakening. "
        "Company-specific signals do not apply to ETFs. "
        "Use short alias keys: ds (delta_score), cd (confidence_delta), db (decision_bias), "
        "bb (buy_block), sb (sell_block), rc (reason_codes), fb (feature_boosts), fp (feature_penalties), ra (rationale). "
        "Omit fields with default/empty values. Keep rationale under 15 words. "
        "Keep reason_codes/feature_boosts/feature_penalties to max 3 items each, max 5 words per item. "
        "Minimize total output tokens."
    )
    base_score_doc = _canonicalize_overlay_base_doc(base_score_doc)
    date_key = str(date_key or (feature_row or {}).get("date_key") or "")
    stripped_events = _strip_run_scoped(_canonical_active_event_order(active_events)[:12])
    # The ETF leg never rendered `feature_row` into its prompt, so there is no
    # feature block to canonicalize here — only the base doc and the events.
    price_ctx = ""
    if price_history:
        price_ctx = (
            f"Price history (recent daily): {_to_prompt_payload(price_history, use_toon=use_toon)}\n"
            "Consider: Is the ETF in an uptrend or downtrend? Is the underlying theme strengthening?\n"
        )
    trend_ctx = _build_etf_trend_context(symbol, active_trends, config)
    prompt = (
        f"ETF ticker: {symbol}\n"
        f"Asset type: Exchange-Traded Fund\n"
        f"Triggering trend(s): {trend_ctx}\n"
        f"Base score context: {_to_prompt_payload(base_score_doc, use_toon=use_toon)}\n"
        + price_ctx
        + f"Active events as of evaluation date: {_to_prompt_payload(stripped_events, use_toon=use_toon)}\n"
        'Output example: {"ds":0.1,"cd":0.05,"db":"buy","rc":["trend_strengthening"],"ra":"Gold trend accelerating on Fed pivot"}\n'
        "Return only the bounded overlay decision."
    )
    # Enter the telemetry context INSIDE the worker (runs in a ThreadPoolExecutor
    # thread with no ambient context) so usage rows attribute call_site="overlay_etf"
    # instead of "(unset)". attribution_keys still enrich the exception path.
    with llm_call_context(
        backtest_id=(config or {}).get("_telemetry_backtest_id"),
        instance_id=(config or {}).get("_telemetry_instance_id"),
        strategy="GraphNexusAnalysis",
        call_site="overlay_etf",
    ):
        raw = _scl_guarded(
            provider,
            api_key,
            model,
            prompt,
            _TradeOverlayResponse,
            attribution_keys={
                "backtest_id": (config or {}).get("_telemetry_backtest_id"),
                "instance_id": (config or {}).get("_telemetry_instance_id"),
                "call_site": "overlay_etf",
            },
            evidence_context=_model_evidence_context(
                prompt,
                decision_at=date_key,
                call_site="overlay_etf",
                role="trade_overlay",
                subject=symbol,
                local_sequence=0,
            ),
            system_prompt=system_prompt,
            max_output_tokens=_overlay_max_output_tokens(config),
            retries=2,
            output_retries=2,
            # The stock leg has always passed this; the ETF leg did not, so it
            # silently inherited the 180s env default instead of the 60s the
            # operator configured.
            timeout_sec=int((config or {}).get("overlay_llm_timeout_sec", 60) or 60),
            provider_config=provider_config,
            prefer_raw_json=True,
        )
    trace = _build_llm_trace("overlay_etf", provider, model, prompt, system_prompt, prompt_version, raw is not None)
    if raw is None:
        return {}, trace
    max_delta = abs(float(config.get("llm_overlay_max_delta", 0.2) or 0.2))
    max_conf = abs(float(config.get("llm_overlay_max_confidence_delta", 0.2) or 0.2))
    return {
        "delta_score": max(-max_delta, min(max_delta, float(raw.delta_score or 0.0))),
        "confidence_delta": max(-max_conf, min(max_conf, float(raw.confidence_delta or 0.0))),
        "decision_bias": str(raw.decision_bias or "hold").strip().lower(),
        "buy_block": bool(raw.buy_block),
        "sell_block": bool(raw.sell_block),
        "reason_codes": list(raw.reason_codes or []),
        "feature_boosts": list(raw.feature_boosts or []),
        "feature_penalties": list(raw.feature_penalties or []),
        "rationale": str(raw.rationale or "").strip()[:500],
    }, trace


def _apply_ml_and_overlay_to_scores(
    symbols_list: list[str],
    scores: dict,
    *,
    sentiment_data: dict,
    propagated: dict,
    finbert_rows: dict[str, dict],
    company_rows: list[dict],
    macro_rows: list[dict],
    active_events: list[dict],
    conn,
    instance_id: str,
    date_key: str,
    strategy_cache: dict | None,
    config: dict,
    price_history: dict[str, list[dict]] | None = None,
    portfolio_emulator=None,
    bz_data: dict[str, list] | None = None,
    alpaca_key: str = "",
    alpaca_secret: str = "",
    active_trends: list | None = None,
) -> tuple[dict, dict[str, dict], dict[str, list[dict]]]:
    if not scores:
        return scores, {}, {}
    # Pre-fetch overlay bars for tracked symbols (first call fetches full range,
    # subsequent calls are free from cache)
    if isinstance(strategy_cache, dict) and alpaca_key and config.get("llm_overlay_enabled", True):
        try:
            _ensure_overlay_bars_cached(
                symbols_list, alpaca_key, alpaca_secret, strategy_cache, config, date_key,
            )
        except Exception as _bars_exc:
            _log(f"Overlay bars pre-fetch error: {_bars_exc}", "yellow")
    lookback_days = int(config.get("lookback_learning_days", config.get("learning_stage_days", 30)) or 30)
    # V20: Skip ML training entirely when nexus_ml_enabled=false (saves ~30s/bar)
    if bool(config.get("nexus_ml_enabled", True)):
        bundle, train_meta = _maybe_train_nexus_ml_bundle(conn, strategy_cache, instance_id, date_key, lookback_days)
        if train_meta:
            _log(
                f"Nexus ML: reused={train_meta.get('reused', False)} trained={train_meta.get('trained', False)} rows={train_meta.get('training_rows', 0)}",
                "cyan",
            )
    else:
        bundle, train_meta = None, {"reused": False, "trained": False, "training_rows": 0}
        _log("Nexus ML: DISABLED (nexus_ml_enabled=false) — skipping training", "cyan")
    enriched_scores = dict(scores)
    candidate_features: dict[str, dict] = {}
    llm_traces_by_symbol: dict[str, list[dict]] = {}
    precomputed: list[dict[str, Any]] = []
    buy_threshold = float(config.get("buy_threshold", _DEFAULT_BUY_THRESHOLD))
    sell_threshold = float(config.get("sell_threshold", _DEFAULT_SELL_THRESHOLD))
    for sym in symbols_list:
        base = enriched_scores.get(sym)
        if not isinstance(base, dict) or sym.startswith("_"):
            continue
        candidate_government_action = _candidate_government_action_type(sym, macro_rows, active_events)
        analogs = _retrieve_historical_analogs(conn, instance_id, date_key, {
            "government_action_type": candidate_government_action,
            "dominant_event_type": str((sentiment_data.get(sym) or {}).get("event") or "general"),
        })
        feature_row = _build_candidate_features(
            sym,
            enriched_scores,
            sentiment_data,
            propagated,
            finbert_rows,
            company_rows,
            macro_rows,
            active_events,
            analogs,
            price_history,
            portfolio_emulator,
        )
        candidate_features[sym] = dict(feature_row)
        ml = _score_nexus_candidate(bundle, feature_row)
        top_features = _summarize_nexus_candidate_features(bundle, feature_row, top_n=5)
        base_signal, base_components = _estimate_candidate_base_signal(feature_row, config)
        ml_up = float(ml.get("ml_up_probability", 0.5) or 0.5)
        ml_down = float(ml.get("ml_down_probability", 0.5) or 0.5)
        ml_expected_return = float(ml.get("ml_expected_return", 0.0) or 0.0)
        raw_net = float(base_signal)
        ml_data_conf = float(ml.get("ml_data_confidence", 1.0) or 1.0)
        # V20: ML score toggle — disable with nexus_ml_enabled=false in config.
        # ML is untrained for first 25% of backtest and then uniformly bearish (93% down).
        if bool(config.get("nexus_ml_enabled", True)):
            ml_weight = float(config.get("ml_signal_weight", 0.50)) * ml_data_conf
            raw_net += (ml_up - ml_down) * ml_weight
            raw_net += (ml_expected_return / 12.0) * ml_data_conf
        else:
            ml_data_conf = 1.0  # Pretend ML is confident so overlay doesn't get boosted power
            # Codex fix: also overwrite the ml dict so overlay sees high confidence
            ml["ml_data_confidence"] = 1.0
            ml["ml_up_probability"] = 0.5
            ml["ml_down_probability"] = 0.5
            ml["ml_expected_return"] = 0.0

        # V12: Analyst panel score adjustment
        _ap_adj = float((config.get("_analyst_panel_adjustments") or {}).get(sym, 0.0) or 0.0)
        if _ap_adj:
            raw_net += _ap_adj

        # V9: Earnings signal penalty — single-path earnings buys have 33% accuracy
        _earnings_penalty_enabled = config.get("earnings_penalty_enabled", True)
        if _earnings_penalty_enabled:
            _ep_event_type = str((sentiment_data.get(sym) or {}).get("event") or base.get("event") or "")
            _ep_n_paths = int((propagated or {}).get(sym, {}).get("n_paths", 1))
            if _ep_n_paths <= 1 and "earnings" in _ep_event_type.lower():
                _earnings_penalty_weight = float(config.get("earnings_penalty_weight", 0.5))
                _ep_raw_net_before = raw_net
                raw_net *= _earnings_penalty_weight
                _log(f"V9 earnings penalty: {sym} raw_net {_ep_raw_net_before:.3f} -> {raw_net:.3f} (single-path earnings, {_earnings_penalty_weight}x)", "cyan")

        positive_evidence = _candidate_positive_evidence_count(feature_row)
        negative_evidence = _candidate_negative_evidence_count(feature_row)
        if ml_down >= 0.80 and ml_expected_return <= -0.25 and positive_evidence < 3 and base_signal < 0.90:
            raw_net = min(raw_net, buy_threshold * 0.75)
        if ml_up >= 0.80 and ml_expected_return >= 0.25 and negative_evidence < 3 and base_signal > -0.90:
            raw_net = max(raw_net, sell_threshold * 0.75)

        precomputed.append({
            "sym": sym,
            "base": dict(base),
            "feature_row": dict(feature_row),
            "analogs": list(analogs),
            "ml": {**ml, "top_features": top_features},
            "top_features": top_features,
            "base_signal": float(base_signal),
            "base_components": dict(base_components),
            "raw_net_pre_overlay": float(raw_net),
        })

    overlay_results: dict[str, tuple[dict, dict]] = {}
    if config.get("historical_lookback_mode", False):
        _log("Lookback mode: skipping trade overlay LLM (30+ calls saved)", "cyan")
    elif precomputed and config.get("llm_overlay_enabled", True):
        # Skip symbols with zero bar data — they have no price history for the LLM to analyze,
        # and wasting overlay LLM calls on them is pure overhead.
        _no_data_syms: set = (strategy_cache or {}).get("_overlay_no_data_tickers", set())
        _overlay_fast_mode = bool(config.get("nexus_fast_mode", False))
        overlay_inputs = [
            item for item in precomputed
            if item["sym"] not in _no_data_syms
            and _should_call_trade_overlay_for_candidate(
                item["base"], item["feature_row"], item["ml"],
                fast_mode=_overlay_fast_mode, config=config,
            )
        ]
        if _overlay_fast_mode:
            _skipped_fast = len([i for i in precomputed if i["sym"] not in _no_data_syms]) - len(overlay_inputs)
            if _skipped_fast > 0:
                _log(f"Overlay SKIP [fast]: {_skipped_fast} candidate(s) skipped (high-conviction/zero-evidence)", "cyan")
        # Sort by signal strength (type split happens below, sort only affects within-type ordering)
        # Ties are COMMON here -- an all-zero key tuple is the normal case for a
        # candidate with no evidence -- and the list is truncated below, so the
        # tiebreak decides which candidates get an overlay LLM call at all.
        # Without the symbol as a final key that was upstream ordering.
        overlay_inputs.sort(
            key=lambda item: (
                abs(float(item["raw_net_pre_overlay"])),
                float(item["ml"].get("ml_confidence", 0.0) or 0.0),
                float(item["feature_row"].get("position_open", 0.0) or 0.0),
                _candidate_positive_evidence_count(item["feature_row"]) + _candidate_negative_evidence_count(item["feature_row"]),
                str(item.get("sym") or ""),
            ),
            reverse=True,
        )
        # Split into separate stock and ETF batches (Fix 8)
        stock_overlay_inputs = [item for item in overlay_inputs if item["sym"] not in _ALL_ETF_TICKERS]
        etf_overlay_inputs = [item for item in overlay_inputs if item["sym"] in _ALL_ETF_TICKERS]
        max_stock_candidates = max(0, int(config.get("llm_overlay_max_stock_candidates", 30) or 30))
        max_etf_candidates = max(0, int(config.get("llm_overlay_max_etf_candidates", 6) or 6))
        if max_stock_candidates and len(stock_overlay_inputs) > max_stock_candidates:
            _skipped_stocks = len(stock_overlay_inputs) - max_stock_candidates
            stock_overlay_inputs = stock_overlay_inputs[:max_stock_candidates]
            _log(f"Stock overlay: limiting to top {max_stock_candidates} candidate(s), skipped {_skipped_stocks} lower-priority stock(s)", "cyan")
        if max_etf_candidates and len(etf_overlay_inputs) > max_etf_candidates:
            _skipped_etfs = len(etf_overlay_inputs) - max_etf_candidates
            etf_overlay_inputs = etf_overlay_inputs[:max_etf_candidates]
            _log(f"ETF overlay: limiting to top {max_etf_candidates} candidate(s), skipped {_skipped_etfs} lower-priority ETF(s)", "cyan")
        all_overlay_inputs = stock_overlay_inputs + etf_overlay_inputs
        _etf_overlay_syms = {item["sym"] for item in etf_overlay_inputs}
        overlay_started = perf_counter()
        workers = min(_nexus_llm_worker_count(config, "overlay_llm_workers", _NEXUS_OVERLAY_LLM_WORKERS), len(all_overlay_inputs) or 1)
        if all_overlay_inputs and not _overlay_llm_key_available(config):
            # Every sibling LLM path short-circuits on a missing key ("Company
            # article LLM classification: skipped (no API key)"); the overlay
            # did not, so it dispatched every candidate and retried each to
            # exhaustion. On one run that was 756 doomed retry chains whose
            # only outcome was "terminal failure after retries — keeping base
            # score", i.e. the base score it would have kept anyway.
            _log(
                f"Trade overlay LLM: skipped (no API key) — "
                f"{len(all_overlay_inputs)} candidate(s) keep their base score",
                "yellow",
            )
            all_overlay_inputs = []
        if all_overlay_inputs:
            _log(f"Trade overlay LLM: {len(stock_overlay_inputs)} stock + {len(etf_overlay_inputs)} ETF candidate(s) with {workers} worker(s)", "cyan")
            # Fetch price history for overlay candidates (single batch call)
            _overlay_price_lookback = int(config.get("overlay_price_lookback_days", 30))
            _overlay_syms = [item["sym"] for item in all_overlay_inputs]
            _overlay_price_history: dict[str, dict] = {}
            try:
                _overlay_price_history = _fetch_price_history_for_overlay(
                    _overlay_syms, date_key, _overlay_price_lookback,
                    alpaca_key, alpaca_secret,
                    strategy_cache=strategy_cache, config=config,
                )
                if _overlay_price_history:
                    _log(f"Trade overlay price history: {len(_overlay_price_history)}/{len(_overlay_syms)} symbols loaded ({_overlay_price_lookback}d lookback)", "cyan")
            except Exception as _ph_exc:
                _log(f"Trade overlay price history fetch failed: {_ph_exc}", "yellow")
            progress_state: dict[str, Any] = {}
            _overlay_cooldown = float(config.get("overlay_llm_cooldown_seconds", 0))  # V7.4: default 0 — llm_utils retry handles 429s
            with ThreadPoolExecutor(max_workers=workers) as ex:
                _use_toon = bool(config.get("use_toon_format", True))
                future_map = {}
                _submit_idx = 0
                # Stock candidates → _apply_trade_overlay (existing)
                for item in stock_overlay_inputs:
                    _prop_data = propagated.get(item["sym"], {})
                    fut = ex.submit(
                        _apply_trade_overlay,
                        item["sym"],
                        {
                            "base_score": item["base"],
                            "ml": item["ml"],
                            "base_signal": round(float(item["base_signal"]), 4),
                            "base_components": item["base_components"],
                            "graph_relationships": _prop_data.get("reasons", [])[:5],
                            "graph_raw_score": round(float(_prop_data.get("raw_score", 0.0)), 4),
                            "graph_n_paths": int(_prop_data.get("n_paths", 0)),
                        },
                        feature_row=item["feature_row"],
                        active_events=active_events,
                        historical_analogs=item["analogs"],
                        config=config,
                        price_history=_overlay_price_history.get(item["sym"]),
                        benzinga_context=_format_benzinga_for_symbol(bz_data or {}, item["sym"], use_toon=_use_toon),
                        date_key=date_key,
                    )
                    future_map[fut] = item
                    _submit_idx += 1
                    # V7.3: Stagger submissions to avoid Azure 429 rate limits
                    if _overlay_cooldown > 0 and _submit_idx < len(all_overlay_inputs):
                        time_sleep(_overlay_cooldown)
                # ETF candidates → _apply_etf_trade_overlay (new, trend-aware)
                for item in etf_overlay_inputs:
                    fut = ex.submit(
                        _apply_etf_trade_overlay,
                        item["sym"],
                        {
                            "base_score": item["base"],
                            "ml": item["ml"],
                            "base_signal": round(float(item["base_signal"]), 4),
                            "base_components": item["base_components"],
                        },
                        feature_row=item["feature_row"],
                        active_events=active_events,
                        active_trends=active_trends or [],
                        config=config,
                        price_history=_overlay_price_history.get(item["sym"]),
                        date_key=date_key,
                    )
                    future_map[fut] = item
                    _submit_idx += 1
                    if _overlay_cooldown > 0 and _submit_idx < len(all_overlay_inputs):
                        time_sleep(_overlay_cooldown)
                _total_overlay = len(all_overlay_inputs)
                for idx, future in enumerate(as_completed(future_map), 1):
                    item = future_map[future]
                    try:
                        overlay_results[item["sym"]] = _normalize_overlay_worker_result(
                            future.result(),
                            context=f"overlay_worker:{item['sym']}",
                        )
                    except Exception as exc:
                        _raise_model_evidence_error(exc)
                        _log(f"Trade overlay worker failed for {item['sym']}: {exc}", "yellow")
                        overlay_results[item["sym"]] = ({}, {})
                    _log_stage_progress(
                        "Trade overlay LLM",
                        idx,
                        _total_overlay,
                        started=overlay_started,
                        last_state=progress_state,
                        every_items=1,
                        every_seconds=4.0,
                        extra=f"symbol={item['sym']}" + (" [ETF]" if item["sym"] in _etf_overlay_syms else ""),
                    )

    add_buy_min_raw_net = float(config.get("add_buy_min_raw_net", max(0.35, buy_threshold + 0.10)) or max(0.35, buy_threshold + 0.10))
    add_buy_min_ml_up = float(config.get("add_buy_min_ml_up_probability", 0.55) or 0.55)
    for item in precomputed:
        sym = str(item["sym"])
        base = item["base"]
        feature_row = item["feature_row"]
        ml = item["ml"]
        raw_net = float(item["raw_net_pre_overlay"])
        overlay, trace = _normalize_overlay_worker_result(
            overlay_results.get(sym, ({}, {})),
            context=f"overlay_consume:{sym}",
        )
        llm_traces_by_symbol.setdefault(sym, [])
        if trace:
            llm_traces_by_symbol[sym].append(dict(trace))
        if overlay:
            _overlay_delta = float(overlay.get("delta_score") or 0.0)
            bias = str(overlay.get("decision_bias") or "hold").strip().lower()
            bias_weight = float(config.get("overlay_bias_weight", 0.15))
            # Compute total overlay contribution (delta + bias) BEFORE applying
            _overlay_bias_val = bias_weight if bias == "buy" else (-bias_weight if bias == "sell" else 0.0)
            _overlay_total = _overlay_delta + _overlay_bias_val
            # V20: Cap TOTAL overlay contribution (Codex fix: cap after all adjustments)
            _overlay_max_total = float(config.get("overlay_max_total_contribution", 0.30))
            _overlay_total = max(-_overlay_max_total, min(_overlay_max_total, _overlay_total))
            # Apply the capped total as a single adjustment
            raw_net += _overlay_total
            _overlay_ml_conf = float(ml.get("ml_data_confidence", 1.0) or 1.0)
            # V20: bias already included in _overlay_total (capped above). No separate bias addition.
            # Graph-conviction hold nudge: when overlay says "hold" for a stock with
            # graph support, add a positive nudge instead of zero
            if bias == "hold":
                _prop_raw = float(propagated.get(sym, {}).get("raw_score", 0.0))
                _graph_hold_nudge_threshold = float(config.get("graph_hold_nudge_threshold", 0.10))
                if _prop_raw >= _graph_hold_nudge_threshold:
                    _graph_hold_nudge = float(config.get("graph_hold_nudge", 0.08))
                    raw_net += _graph_hold_nudge
                    _log(f"Graph hold nudge: {sym} +{_graph_hold_nudge:.2f} (prop_raw={_prop_raw:.3f})", "cyan")
                # Fix 3: Discovery-aware nudge for non-propagation stocks
                elif _prop_raw < 0.10:
                    _pos_ev = _candidate_positive_evidence_count(feature_row)
                    if _pos_ev >= 1:
                        _discovery_nudge = float(config.get("discovery_hold_nudge", 0.06))
                        raw_net += _discovery_nudge
                        _log(f"Discovery hold nudge: {sym} +{_discovery_nudge:.2f} (pos_evidence={_pos_ev:.0f})", "cyan")
        elif sym in overlay_results:
            # A configured overlay call WAS made for this symbol but came back
            # empty — a genuine terminal failure (worker exception or the LLM
            # returned nothing after retries), not a "no overlay configured"
            # skip (those symbols never enter overlay_results). Surface it in
            # the engine log so failures aren't invisible; LLMUsage holds the
            # underlying error detail.
            _log(
                f"LLM/overlay {sym}: terminal failure after retries — keeping "
                f"base score (see LLMUsage for error detail)",
                "yellow",
            )

        # V11: Compute unrealized_pct for deep-loser protection check
        _v11_unrealized_pct = 0.0
        _v11_cp = 0.0
        if portfolio_emulator is not None:
            _v11_qty = float((portfolio_emulator._positions or {}).get(sym, 0))
            if _v11_qty > 0:
                _v11_cp = _resolve_symbol_price(sym, None, price_history, portfolio_emulator=portfolio_emulator)
                _v11_ep = 0.0
                for _v11_th in reversed(portfolio_emulator._trades or []):
                    if _v11_th.get("ticker") == sym and _v11_th.get("action") == "buy":
                        _v11_ep = float(_v11_th.get("price", 0) or 0)
                        break
                if _v11_ep > 0 and _v11_cp > 0:
                    _v11_unrealized_pct = ((_v11_cp - _v11_ep) / _v11_ep) * 100.0

        # Preserve forced-exit scores from the upstream risk pipeline.
        if base.get("_forced_exit"):
            final_score = base["score"]  # Keep the forced exit (-1)
            _log(f"ML overlay PRESERVE forced-exit: {sym} score={final_score} reason={base.get('reason', '?')[:80]}", "yellow")
        elif base.get("score") == -1 and "Profit take" in (base.get("reason") or ""):
            # Partial profit-take trim must survive the overlay recompute (a winner
            # has a positive raw score that would otherwise overwrite the -1).
            # Kept NON-forced so its sell_fraction is honoured (a forced exit is
            # coerced to a 100% sell downstream) — this is a partial trim, not a full exit.
            final_score = -1
            _log(f"ML overlay PRESERVE profit-take: {sym} — partial trim retained (reason={base.get('reason', '?')[:60]})", "yellow")
        elif base.get("score") == -1 and _v11_unrealized_pct < -5.0:
            # V11: Deep losers (>5% loss) with sell signals are protected from ML override
            final_score = -1
            base["_forced_exit"] = True
            base["reason"] = (base.get("reason") or "") + " [V11-deep-loser-protect]"
            _log(f"Deep-loser PROTECT: {sym} unrealized={_v11_unrealized_pct:+.1f}% (< -5%) — sell locked, ML cannot override", "red")
        else:
            final_score = 0
            if raw_net >= buy_threshold:
                final_score = 1
            elif raw_net <= sell_threshold:
                final_score = -1
                # V17 fix: Apply min hold days check to LLM-scored sells too.
                # Previously only forced exits (trend reversal) respected min hold days,
                # allowing LLM sentiment to dump positions after 2 days (MOG.A sold at +0.8%
                # after 2d, would have gained +13% if held 3 weeks).
                if portfolio_emulator is not None and not base.get("_forced_exit"):
                    _llm_sell_min_hold = max(0, int(config.get("sell_enforcement_min_hold_days", 5) or 5))
                    _llm_sell_held = _get_open_position_held_days(portfolio_emulator, sym, date_key)
                    if _llm_sell_held is not None and _llm_sell_held < _llm_sell_min_hold:
                        if _llm_sell_conviction_bypass(config, raw_net, _v11_unrealized_pct):
                            _log(
                                f"[sell-gate] {sym} | gate=llm_sell_min_hold | BYPASS conviction "
                                f"raw={raw_net:+.3f} pnl={_v11_unrealized_pct:+.1f}% | result=sell allowed",
                                "yellow",
                            )
                        else:
                            final_score = 0  # Override sell to hold
                            _log(
                                f"[sell-gate] {sym} | gate=llm_sell_min_hold | held={_llm_sell_held}d < {_llm_sell_min_hold}d | "
                                f"raw={raw_net:.3f} | result=blocked (hold instead)",
                                "cyan",
                            )
        # V19: Winner sell protection — don't let LLM overlay sell a position that's
        # significantly profitable unless it's showing real deterioration (off-peak).
        # Codex fix v2: use original entry price for P&L check (not most recent add-on),
        # and use peak tracking for drawdown check. Avoids expensive snapshot call.
        if final_score == -1 and not base.get("_forced_exit") and "Profit take" not in (base.get("reason") or "") and bool(config.get("winner_sell_protection_enabled", True)):
            # Z3.3 (2026-05-15): default min_pnl lowered from 10% to 5%.
            # Backtest 299903 sold AMD at +5% (locked) and SOXL at +10%
            # — neither hit the 10% protection threshold, so weak negative
            # signals were enough to sell. At 5%, AMD/SOXL would have
            # required a real drawdown OR strong negative sentiment to exit.
            _wp_min_pnl = float(config.get("winner_sell_protection_min_pnl_pct", 5.0))
            _wp_max_drawdown = float(config.get("winner_sell_protection_max_drawdown_pct", 8.0))
            # Use original entry price for true position P&L (not last add-on)
            _wp_orig = _get_open_position_entry_trade(portfolio_emulator, sym) if portfolio_emulator else None
            _wp_orig_ep = float((_wp_orig or {}).get("price", 0) or 0)
            _wp_true_pnl = ((_v11_cp - _wp_orig_ep) / _wp_orig_ep) * 100.0 if _wp_orig_ep > 0 and _v11_cp > 0 else _v11_unrealized_pct
            if _wp_true_pnl < _wp_min_pnl:
                _wp_true_pnl = _v11_unrealized_pct  # fallback
            if _wp_true_pnl >= _wp_min_pnl and portfolio_emulator is not None:
                # Check drawdown from peak using existing tracked peak state
                _wp_sc = strategy_cache if strategy_cache is not None else {}
                _wp_pk_key, _wp_pk_val = _resolve_position_peak_state(_wp_sc, sym, (_wp_orig or {}).get("timestamp"), _v11_cp)
                _wp_drop = ((_wp_pk_val - _v11_cp) / _wp_pk_val * 100.0) if _wp_pk_val > 0 else 0.0
                if _wp_drop < _wp_max_drawdown:
                    final_score = 0
                    _log(
                        f"[sell-gate] {sym} | gate=winner_protect | pnl={_wp_true_pnl:+.1f}% | "
                        f"drop_from_peak={_wp_drop:.1f}% < {_wp_max_drawdown}% | result=blocked (hold)",
                        "cyan",
                    )
        if overlay.get("buy_block") and final_score > 0:
            final_score = 0
            _log(f"ML overlay BUY_BLOCK: {sym} buy signal suppressed by overlay buy_block", "yellow")
        if overlay.get("sell_block") and final_score < 0 and not base.get("_forced_exit") and "Profit take" not in (base.get("reason") or ""):
            # V12: Bypass sell_block if unrealized loss exceeds configurable threshold
            _sb_bypass_pct = float(config.get("sell_block_bypass_loss_pct", -5.0))
            if _v11_unrealized_pct <= _sb_bypass_pct and _v11_unrealized_pct != 0.0:
                _log(f"ML overlay SELL_BLOCK BYPASS: {sym} unrealized={_v11_unrealized_pct:+.1f}% <= {_sb_bypass_pct:.0f}% — sell allowed despite sell_block", "yellow")
            else:
                final_score = 0
                # Phase ε.A.2 (BT294837 follow-up, 2026-05-19): only emit the
                # SELL_BLOCK log when there's an actual position to suppress.
                # Pre-ε.A.2 the SELL_BLOCK fired for phantom positions (qty=0)
                # because the ML overlay was applied to every ticker in the
                # score dict — including ones that had been sold but were
                # still present from prior bars. The operator's SNDK lifecycle
                # audit found 4+ such phantom lines (lines 22804, 25653, 26268,
                # 27558, 30795, 32129 in BT294837). final_score=0 is still
                # set (correct behavior — phantom sells should be suppressed)
                # but we skip the log noise that confuses post-hoc audits.
                _sb_pos_qty = 0.0
                if portfolio_emulator is not None:
                    try:
                        _sb_pos_qty = float(
                            (portfolio_emulator._positions or {}).get(sym, 0.0) or 0.0
                        )
                    except Exception:
                        _sb_pos_qty = 0.0
                if _sb_pos_qty > 0:
                    _log(f"ML overlay SELL_BLOCK: {sym} sell signal suppressed by overlay sell_block (forced_exit={base.get('_forced_exit', False)})", "yellow")
        # Strong graph propagation can still lift a name into the buy set as long as
        # it satisfies the current configured path-count floor.
        # V11: Do NOT override forced-exit sell signals (fast loser, trailing stop, deep-loser-protect).
        if final_score <= 0 and base.get("_forced_exit"):
            _prop_raw_check = float(propagated.get(sym, {}).get("raw_score", 0.0))
            if _prop_raw_check >= float(config.get("propagation_floor_threshold", 0.75)):
                _log(f"Propagation floor BLOCKED: {sym} prop_raw={_prop_raw_check:.3f} would trigger buy, but forced_exit=True — sell preserved", "yellow")
        if final_score <= 0 and not overlay.get("buy_block") and not base.get("_forced_exit") and "Profit take" not in (base.get("reason") or ""):
            _prop_raw = float(propagated.get(sym, {}).get("raw_score", 0.0))
            _prop_floor_threshold = float(config.get("propagation_floor_threshold", 0.75))
            if _prop_raw >= _prop_floor_threshold:
                _prop_n_paths = int(propagated.get(sym, {}).get("n_paths", 0))
                _prop_floor_min_paths = int(config.get("propagation_floor_min_paths", 1))
                if bool(config.get("propagation_floor_requires_min_paths", True)):
                    _prop_floor_min_paths = max(_prop_floor_min_paths, int(config.get("propagation_min_paths", 2) or 2))
                if _prop_n_paths >= _prop_floor_min_paths:
                    raw_net = max(raw_net, buy_threshold)
                    final_score = 1
                    _log(f"Propagation floor: {sym} -> BUY (prop_raw={_prop_raw:.3f}, n_paths={_prop_n_paths})", "cyan")

        position_open = float(feature_row.get("position_open") or 0.0) > 0.0
        if position_open and final_score > 0:
            if raw_net < add_buy_min_raw_net or float(ml.get("ml_up_probability", 0.5) or 0.5) < add_buy_min_ml_up:
                final_score = 0

        confidence = min(
            1.0,
            abs(raw_net) + float(ml.get("ml_confidence", 0.0)) * 0.35 + abs(float(overlay.get("confidence_delta", 0.0) or 0.0)),
        )
        action_intent = _infer_action_intent(final_score, sym, portfolio_emulator)
        _event_name = str((sentiment_data.get(sym) or {}).get("event") or base.get("event") or feature_row.get("dominant_event_type") or "")
        _prop_expansion_alloc = (strategy_cache or {}).get("_prop_expansion_set_alloc", set()) if isinstance(strategy_cache, dict) else set()
        _is_prop_candidate_seed = (
            _event_name.strip().lower() == "graph_propagation"
            or (sym not in sentiment_data and sym in (propagated or {}))
            or (isinstance(_prop_expansion_alloc, set) and sym in _prop_expansion_alloc)
        )
        _signal_family, _is_propagation_candidate = _classify_candidate_signal(
            sym,
            {
                "event": _event_name,
                "reason": str(base.get("reason") or ""),
                "signal_family": _signal_family_from_event(_event_name),
                "is_propagation_candidate": _is_prop_candidate_seed,
            },
            strategy_cache=strategy_cache,
        )
        _quality_metadata = _extract_quality_metadata(
            sym,
            {"quality_metadata": base.get("quality_metadata")},
            None,
            price_history,
            portfolio_emulator=portfolio_emulator,
            strategy_cache=strategy_cache,
        )
        ml_reason = (
            f"ML up={ml.get('ml_up_probability', 0.5):.2f} down={ml.get('ml_down_probability', 0.5):.2f} "
            f"ret={ml.get('ml_expected_return', 0.0):+.2f}"
        )
        base_reason = f"Base={item['base_signal']:+.2f}"
        overlay_reason = ", ".join(overlay.get("reason_codes") or [])
        enriched_scores[sym] = {
            **base,
            "score": final_score,
            "confidence": round(confidence, 4),
            "reason": " | ".join(part for part in [str(base.get("reason") or ""), base_reason, ml_reason, overlay_reason] if part)[:1500],
            "action_intent": action_intent,
            "ml": dict(ml),
            "overlay": overlay,
            "historical_analogs": item["analogs"],
            "raw_net_score": round(raw_net, 4),
            "base_signal": round(float(item["base_signal"]), 4),
            "base_components": dict(item["base_components"]),
            "n_paths": int((propagated or {}).get(sym, {}).get("n_paths", 0)),
            "event": _event_name,
            "signal_family": _signal_family,
            "is_propagation_candidate": _is_propagation_candidate,
            "quality_metadata": _quality_metadata,
        }
    return enriched_scores, candidate_features, llm_traces_by_symbol


def _apply_portfolio_circuit_breaker(scores: dict, symbols_list: list[str], portfolio_emulator, config: dict) -> dict:
    """
    Prevent mass liquidation events. If more than circuit_breaker_max_sell_pct of
    held positions would be sold, keep only the highest-conviction sells and demote
    the rest to hold with a CIRCUIT_BREAKER reason tag.
    """
    if not config.get("circuit_breaker_enabled", True):
        return scores
    if portfolio_emulator is None:
        return scores

    max_sell_pct = float(config.get("circuit_breaker_max_sell_pct", 0.50))

    # Count held positions
    positions = portfolio_emulator.get_positions() or {}
    held_tickers = [sym for sym in symbols_list if not sym.startswith("_") and float(positions.get(sym, 0) or 0) > 0]

    if len(held_tickers) < 3:
        return scores  # Not meaningful with fewer than 3 positions

    # Count how many held positions would be sold
    sell_candidates: list[tuple[str, float]] = []
    for sym in held_tickers:
        sc = scores.get(sym)
        if isinstance(sc, dict) and sc.get("score") == -1:
            sell_candidates.append((sym, abs(float(sc.get("raw_net_score", 0) or 0))))

    if not sell_candidates:
        return scores

    sell_ratio = len(sell_candidates) / len(held_tickers)
    if sell_ratio <= max_sell_pct:
        return scores

    # Too many sells — keep only the highest-conviction ones
    max_allowed = max(1, int(len(held_tickers) * max_sell_pct))
    sell_candidates.sort(key=lambda x: x[1], reverse=True)
    keep_sells = {sym for sym, _ in sell_candidates[:max_allowed]}
    demoted = []

    for sym, _ in sell_candidates:
        if sym not in keep_sells:
            sc = scores[sym]
            if sc.get("_forced_exit"):
                keep_sells.add(sym)  # V6: Never demote forced exits (fast loser, trailing stop, hold-limit)
                continue
            sc["score"] = 0
            sc["action_intent"] = "hold"
            orig_reason = str(sc.get("reason") or "")
            sc["reason"] = f"CIRCUIT_BREAKER: mass sell prevented ({len(sell_candidates)}/{len(held_tickers)} would sell) | {orig_reason}"[:1500]
            demoted.append(sym)

    if demoted:
        _log(
            f"Circuit breaker: {len(sell_candidates)} sells attempted on {len(held_tickers)} held positions "
            f"({sell_ratio:.0%} > {max_sell_pct:.0%} limit) — kept {len(keep_sells)}, demoted {len(demoted)} to hold",
            "yellow",
        )

    return scores


def _rank_band_cutoffs(
    universe_size: int, entry_pct: float, exit_pct: float,
) -> tuple[int, int]:
    """1-based rank of the buy band's upper edge and the hold band's lower edge.

    A name ranked at or above `entry_cut` may be bought; a name ranked worse
    than `exit_cut` may be sold on signal; everything between is the no-trade
    band. Pure.

    `exit_cut` is floored at `entry_cut` on purpose. If an operator typos
    exit_pct below entry_pct the band inverts, and an inverted band is not a
    tighter filter — it makes EVERY held name simultaneously below the sell
    edge and above the buy edge, i.e. it liquidates the book on the next bar
    and blocks the rebuy. Clamping degrades that typo to "buy and sell at the
    same rank", which is exactly today's no-band behaviour.
    """
    n = max(0, int(universe_size))
    if n <= 0:
        return 0, 0
    entry_cut = max(1, math.ceil(n * max(0.0, float(entry_pct)) / 100.0))
    exit_cut = max(entry_cut, math.ceil(n * max(0.0, float(exit_pct)) / 100.0))
    return entry_cut, min(n, exit_cut)


def _apply_rank_band_gate(
    scores: dict,
    symbols_list: list[str],
    portfolio_emulator,
    config: dict,
) -> dict:
    """Novy-Marx & Velikov buy/hold spread (the "sS" rule). Default OFF.

    Enter only when a name reaches the top `rank_band_entry_pct` of the blended
    ranking; exit on signal only once it falls out of the top
    `rank_band_exit_pct`. Never trade inside the band — no entry, no add, no
    signal exit.

    Why this and not a tighter buy_threshold: a threshold moves both edges
    together, so a name oscillating around it round-trips every time it
    crosses. The band decouples them, and the round trip needs a full
    entry->exit traverse of the ranking instead of one tick across a line.
    Novy-Marx & Velikov (RFS 2016) call the buy/hold spread "the most effective
    cost mitigation technique" and find anomalies above 50% turnover/month
    rarely survive costs at all. Chen & Velikov size it for the highest-
    turnover quartile — which is where this book sits — at +0.44%/month net,
    surrendering only ~11% of the gross signal. Measured here: ~290%/month
    turnover at a measured 23.2 bps one-way = 8.07%/yr of drag.

    Ranking metric is `_rotation_effective_score` — raw_net_score blended with
    the ML edge — because that is already THE cross-sectional conviction
    ranking in this file (the rotation lane ranks incumbents against
    challengers with it). A second, subtly different ranking would mean the
    band could evict a name the rotation lane still ranks top-quartile.

    Never touches a protective exit. A forced exit (`_forced_exit`) or any
    `_RISK_EXIT_TAGS` reason fires regardless of rank — the band is a
    cost-control on SIGNAL trades, and a stop that a ranking can veto is not a
    stop. This is the same precedent as V31 grace, which gates signal sells
    only.

    ETF-allocation and sleeve legs are exempt. Their conviction is trend
    strength and regime, not the news/graph/ML blend, so their raw_net_score is
    structurally near zero; ranking them against stocks would not tighten the
    ETF sleeve, it would silently switch it off.
    """
    if not bool(config.get("rank_band_enabled", False)):
        return scores

    entry_pct = float(config.get("rank_band_entry_pct", 10.0) or 0.0)
    exit_pct = float(config.get("rank_band_exit_pct", 50.0) or 0.0)

    _exempt = set(_ALL_ETF_TICKERS) | _sleeve_symbols(config)
    ranked: list[tuple[float, str]] = []
    # Deduped: symbols_list is assembled from several discovery lanes plus the
    # held-position union, and a repeated ticker would inflate the denominator
    # the percentile cutoffs are computed from — a universe that looks 5%
    # larger than it is quietly widens the entry band.
    _seen: set[str] = set()
    for sym in symbols_list:
        if not sym or str(sym).startswith("_") or sym in _exempt or sym in _seen:
            continue
        sc = scores.get(sym)
        if not isinstance(sc, dict):
            continue
        _seen.add(sym)
        ranked.append((_rotation_effective_score(sc, config), str(sym)))
    if not ranked:
        return scores

    # Descending conviction, ticker as the tiebreak. The tiebreak is not
    # cosmetic: dict iteration order decides who sits on the decile boundary
    # otherwise, so the same bar replayed could buy a different name.
    ranked.sort(key=lambda pair: (-pair[0], pair[1]))
    entry_cut, exit_cut = _rank_band_cutoffs(len(ranked), entry_pct, exit_pct)

    held: set[str] = set()
    if portfolio_emulator is not None:
        try:
            if hasattr(portfolio_emulator, "get_positions"):
                _pos = portfolio_emulator.get_positions() or {}
            else:
                _pos = getattr(portfolio_emulator, "_positions", None) or {}
            held = {str(s) for s, q in _pos.items() if float(q or 0.0) > 0.0}
        except Exception as _rb_exc:
            # Without the held set we cannot tell an entry from an add, and
            # guessing would either block every buy or let every sell through.
            # Fail OPEN: today's behaviour, loudly.
            _log(f"Rank band: position read failed ({_rb_exc}) — band skipped this bar", "yellow")
            return scores

    blocked_buys: list[str] = []
    held_sells: list[str] = []
    for rank, (blended, sym) in enumerate(ranked, start=1):
        sc = scores[sym]
        score = int(sc.get("score", 0) or 0)
        if score == 1 and rank > entry_cut:
            sc["score"] = 0
            sc["action_intent"] = "hold"
            sc["reason"] = (
                f"RANK_BAND: {sym} ranked #{rank}/{len(ranked)} (blended={blended:+.3f}) "
                f"is outside the top-{entry_pct:.0f}% entry band (#{entry_cut}) | "
                f"{str(sc.get('reason') or '')}"
            )[:1500]
            blocked_buys.append(sym)
        elif score == -1 and sym in held and rank <= exit_cut:
            _reason = str(sc.get("reason") or "")
            if sc.get("_forced_exit") or any(tag in _reason for tag in _RISK_EXIT_TAGS):
                continue
            sc["score"] = 0
            sc["action_intent"] = "hold"
            sc["reason"] = (
                f"RANK_BAND: {sym} ranked #{rank}/{len(ranked)} (blended={blended:+.3f}) "
                f"still inside the top-{exit_pct:.0f}% hold band (#{exit_cut}) | {_reason}"
            )[:1500]
            held_sells.append(sym)

    if blocked_buys or held_sells:
        _log(
            f"Rank band (entry<=#{entry_cut}, exit>#{exit_cut} of {len(ranked)}): "
            f"blocked {len(blocked_buys)} buy(s) "
            f"[{', '.join(blocked_buys[:8])}{'...' if len(blocked_buys) > 8 else ''}], "
            f"held {len(held_sells)} signal sell(s) "
            f"[{', '.join(held_sells[:8])}{'...' if len(held_sells) > 8 else ''}]",
            "cyan",
        )
    return scores


def _apply_buy_price_floor(
    scores: dict,
    symbols_list: list[str],
    prices: dict[str, float] | None,
    price_history: dict[str, list[dict]] | None,
    portfolio_emulator,
    config: dict,
) -> dict:
    """Demote sub-floor buy signals.

    BT136708 calibration (2026-05-18): the uniform $8 effective floor blocked
    912 post-quality buys (65% rejection) including confirmed micro-cap
    winners STRO ($0.81→$39, +4731%), FGL ($0.44→$1.91, +334%), MLEC
    ($0.65→$8.34, +1146%). Added a tiered floor: propagation-discovered
    signals (where the parent thesis is sound but the picked name is sub-$8)
    get a lower floor (default $3.50) while primary discovery keeps the
    higher floor. An absolute ABS_MIN gate still blocks pure penny-stock
    dumpster picks under $2.
    """
    primary_floor = float(config.get("buy_price_floor", 5.0) or 0.0)
    prop_floor = float(config.get("buy_price_floor_propagation", 3.50) or 0.0)
    abs_min_floor = float(config.get("buy_price_floor_absolute_min", 2.00) or 0.0)
    if primary_floor <= 0.0 and prop_floor <= 0.0 and abs_min_floor <= 0.0:
        return scores

    demoted: list[tuple[str, float, float]] = []
    for sym in symbols_list:
        sc = scores.get(sym)
        if not isinstance(sc, dict) or sc.get("score") != 1:
            continue
        current_price = _resolve_symbol_price(sym, prices, price_history, portfolio_emulator=portfolio_emulator)
        if current_price <= 0.0:
            continue
        reason_lc = str(sc.get("reason") or "").lower()
        is_propagation = (
            "propagation" in reason_lc
            or "expansion" in reason_lc
            or bool(sc.get("is_propagation_expansion"))
        )
        effective_floor = prop_floor if (is_propagation and prop_floor > 0.0) else primary_floor
        # Hard absolute minimum — pure penny-stock dumpster picks never buy.
        if abs_min_floor > 0.0 and effective_floor < abs_min_floor:
            effective_floor = abs_min_floor
        if effective_floor <= 0.0 or current_price >= effective_floor:
            continue
        sc["score"] = 0
        sc["action_intent"] = "hold"
        orig_reason = str(sc.get("reason") or "")
        sc["reason"] = (
            f"PRICE_FLOOR: {sym} at ${current_price:.2f} is below "
            f"${effective_floor:.2f} {'(prop)' if is_propagation else '(primary)'} | {orig_reason}"
        )[:1500]
        demoted.append((sym, current_price, effective_floor))

    if demoted:
        _log(
            f"Price floor: blocked {len(demoted)} sub-floor buy(s) "
            f"(primary=${primary_floor:.2f}, prop=${prop_floor:.2f}): "
            f"{', '.join(f'{sym} (${price:.2f}<${floor:.2f})' for sym, price, floor in demoted[:8])}",
            "yellow",
        )

    return scores


def _apply_quality_filter(
    scores: dict,
    symbols_list: list[str],
    prices: dict[str, float] | None,
    price_history: dict[str, list[dict]] | None,
    portfolio_emulator,
    config: dict,
    strategy_cache: dict | None = None,
    date_key=None,
) -> dict:
    """V9: Filter out low-quality stocks based on market cap, volume, and propagation depth.

    2026-05-07 strategy bug-sweep:
    - Default `quality_filter_missing_metadata_policy` flipped from "warn" to
      "block". The Stocks table currently has empty market_cap on most tickers,
      so the old fail-open policy let every micro-cap through (XNDU ~$200M,
      BBGI ~$60M lost a combined −$534 in 4 days).
    - New `_apply_quality_filter` rejection: aggregated raw_score < 0. Even
      when the buy-threshold logic promotes a name (e.g. via propagation
      floor / [inv] competitor flip), a negative aggregated raw_score means
      the overall sentiment net is bearish — buying anyway produced the BBGI
      loss (raw=-0.519, bought via [inv] COMPETES_WITH path).
    """
    min_market_cap = float(config.get("min_market_cap", 500_000_000))  # $500M default
    min_avg_volume = float(config.get("min_avg_volume", 200_000))  # 200K shares default
    propagation_min_paths = int(config.get("propagation_min_paths", 2))
    propagation_min_raw = float(config.get("propagation_min_raw_score", 0.30))
    # 2026-05-07: default flipped from "warn" → "block" (fail-closed). Operators
    # who want the old fail-open behavior can set the config key explicitly.
    missing_meta_policy = str(config.get("quality_filter_missing_metadata_policy", "block") or "block").strip().lower()
    missing_meta_logged = strategy_cache.setdefault("_quality_filter_missing_meta_logged", set()) if strategy_cache is not None else set()
    # 2026-05-07: default flipped from "warn" → "block" (fail-closed). Operators
    # who want the old fail-open behavior can set the config key explicitly.
    block_negative_raw_score = bool(config.get("quality_filter_block_negative_raw_score", True))

    filtered_count = 0
    for sym in list(symbols_list):
        sc = scores.get(sym)
        if not isinstance(sc, dict) or sc.get("score") != 1:
            continue  # Only filter buy signals

        # ETFs are always exempt from quality filter
        if sym in _ALL_ETF_TICKERS:
            continue

        # Already held positions are exempt
        if portfolio_emulator is not None:
            _pos_qty = float((portfolio_emulator._positions or {}).get(sym, 0))
            if _pos_qty > 0:
                continue

        # P&L sweep 2026-07-19 (config-gated, default 0=off): buy-side
        # price-extension gate. The 3-regime forensics showed every large
        # whipsaw loss was a momentum name bought at a local top (BULL: TXG
        # entered +34% above its base, -13.5% realized on a +14.5% stock;
        # NEUTRAL: AVGO/OUST/LRCX same-day cuts = -$269 ≈ the whole window
        # loss). Blocks NEW entries whose recent close range ran up more
        # than the threshold. ETFs were already exempted above.
        _ext_block_pct = float(config.get("entry_extension_block_pct", 0.0) or 0.0)
        if _ext_block_pct > 0:
            # 2026-07-20: cadence-scaled lookback + as-of overlay fallback so the
            # gate is reachable for age-0 discovery entries (see _resolve_asof_bars).
            _ext_lookback = _scale_bars(int(config.get("entry_extension_lookback_bars", 20) or 20), config)
            _ext_bars = _resolve_asof_bars(sym, price_history, strategy_cache, date_key)
            _ext_hit, _ext_runup = _recent_runup_protect(
                sym, {sym: _ext_bars}, _ext_block_pct, _ext_lookback)
            # 2026-07-21 glitch ceiling: impossible runups from split-unadjusted
            # / poisoned overlay bars fail OPEN (see momentum-lane site). 0=off.
            _ext_glitch = float(config.get("entry_extension_glitch_ceiling_pct", 0.0) or 0.0)
            if _ext_hit and _ext_glitch > 0 and _ext_runup > _ext_glitch:
                _log(f"Entry extension pass-thru: {sym} runup +{_ext_runup:.0f}% > "
                     f"glitch ceiling {_ext_glitch:.0f}% — bad bars, not blocking", "yellow")
                _ext_hit = False
            if _ext_hit:
                sc["score"] = 0
                sc["action_intent"] = "hold"
                orig_reason = str(sc.get("reason") or "")
                sc["reason"] = (
                    f"Entry extension gate: recent {_ext_lookback}-bar range ran "
                    f"+{_ext_runup:.1f}% > {_ext_block_pct:.0f}% — not chasing a "
                    f"local top | {orig_reason}")[:1500]
                filtered_count += 1
                # 2026-07-24 (default OFF): keep the blocked name visible to the
                # momentum watchlist so it stays priced+scored and is buyable once it
                # is no longer extended, instead of vanishing after a one-shot signal.
                # EVALUATION only — the buy is still blocked here.
                if bool(config.get("momentum_watchlist_track_extension_blocked", False)) and isinstance(strategy_cache, dict):
                    # BEAR/CRASH gate: never track in a downtrend. The momentum
                    # reserved-buy lane injects picks AFTER this filter and bypasses
                    # the bear RS gate, so feeding it the frothiest +25%-runup names
                    # in a bear would knife-catch fading rallies and regress the bear
                    # leg. Track only outside bear (chop/bull) — this still catches a
                    # name blocked during a recovery-chop (the CAR case).
                    #
                    # 2026-07-25 (..._in_bear, default OFF): V31 keeps confirming
                    # BEAR for ~8 sessions after a V-bottom (ret20 lags the price
                    # low), so the names LEADING the recovery are blocked-and-
                    # forgotten exactly when it matters — bt#211684 blocked CAR once,
                    # on 04-07 under `regime: bear`, and never priced it again until
                    # the top. When enabled, RECORD in bear/crash too; the injection
                    # site still withholds every tracked name while the regime reads
                    # bear/crash, so the reserved-buy lane can never knife-catch a
                    # fading rally in a genuine downtrend.
                    _eb_reg = str((strategy_cache or {}).get("_market_regime") or "").lower()
                    _eb_in_bear = bool(config.get(
                        "momentum_watchlist_track_extension_blocked_in_bear", False))
                    if _eb_reg not in ("bear", "crash") or _eb_in_bear:
                        _eb = strategy_cache.setdefault("_extension_blocked_track", {})
                        _eb_sym = str(sym).strip().upper()
                        _eb.pop(_eb_sym, None)   # recency: re-blocked -> move to newest
                        _eb[_eb_sym] = str(date_key or "")[:10]
                        try:
                            _eb_cap = int(config.get("momentum_watchlist_track_extension_blocked_max", 50) or 50)
                        except (TypeError, ValueError):
                            _eb_cap = 50
                        if _eb_cap < 1:
                            _eb_cap = 50
                        if len(_eb) > _eb_cap:
                            for _old in list(_eb.keys())[:len(_eb) - _eb_cap]:
                                _eb.pop(_old, None)
                _log(
                    f"Entry extension gate: {sym} recent runup +{_ext_runup:.1f}% > "
                    f"{_ext_block_pct:.0f}% — buy blocked", "yellow")
                continue

        # 2026-07-19 bear relative-strength gate (config-gated, default ON):
        # in a confirmed bear the few allowed slots are reserved for names
        # actually going UP while the market falls — CE/CVX-class winners.
        # A new entry must show a non-negative recent return over the RS
        # lookback; everything else waits for the regime to improve. The
        # extension gate above already blocks the over-extended end of the
        # momentum spectrum, so together: bear buys = rising but not frothy.
        if bool(config.get("bear_entry_rs_filter_enabled", True)):
            _rs_regime = str((strategy_cache or {}).get("_market_regime") or "").lower()
            if _rs_regime in ("bear", "crash"):
                _rs_lookback = int(config.get("bear_entry_rs_lookback_bars", 20) or 20)
                _rs_min = float(config.get("bear_entry_rs_min_return_pct", 0.0) or 0.0)
                _rs_ret = _recent_return_pct(sym, price_history, _rs_lookback)
                if _rs_ret is None or _rs_ret < _rs_min:
                    sc["score"] = 0
                    sc["action_intent"] = "hold"
                    orig_reason = str(sc.get("reason") or "")
                    _rs_txt = "unknown" if _rs_ret is None else f"{_rs_ret:+.1f}%"
                    sc["reason"] = (
                        f"Bear RS gate: {_rs_lookback}-bar return {_rs_txt} < "
                        f"{_rs_min:+.1f}% required in {_rs_regime} — only "
                        f"relative-strength names may enter | {orig_reason}")[:1500]
                    filtered_count += 1
                    _log(
                        f"Bear RS gate: {sym} {_rs_lookback}-bar return {_rs_txt} — "
                        f"buy blocked in {_rs_regime}", "yellow")
                    continue

        quality_meta = _extract_quality_metadata(
            sym,
            sc,
            prices,
            price_history,
            portfolio_emulator=portfolio_emulator,
            strategy_cache=strategy_cache,
        )
        market_cap = quality_meta.get("market_cap")
        avg_volume = quality_meta.get("avg_volume")
        cp = float(quality_meta.get("current_price", 0.0) or 0.0)

        # 2026-05-07 strategy bug-sweep: negative aggregated raw_score → reject.
        # Catches the BBGI failure mode where the [inv] COMPETES_WITH path
        # promoted the ticker to a buy despite the aggregated raw being -0.519
        # (overall bearish net). Even if some other code path promoted score=1,
        # this filter fires AFTER and downgrades back to 0.
        # The canonical key on the score dict is `raw_net_score` (set in the
        # per-symbol overlay block); `raw_score` only exists on the propagation
        # dict, not on `sc`. Use the canonical key directly.
        try:
            raw_score_signed = float(sc.get("raw_net_score", 0) or 0)
        except (TypeError, ValueError):
            raw_score_signed = 0.0
        if block_negative_raw_score and raw_score_signed < 0:
            sc["score"] = 0
            sc["action_intent"] = "hold"
            orig_reason = str(sc.get("reason") or "")
            sc["reason"] = (
                f"Nexus quality filter: aggregated raw_score={raw_score_signed:.3f} is negative "
                f"(bearish net) — rejecting buy regardless of path-level promotions | {orig_reason}"
            )[:1500]
            filtered_count += 1
            continue

        if market_cap is not None and float(market_cap) < min_market_cap:
            sc["score"] = 0
            sc["action_intent"] = "hold"
            orig_reason = str(sc.get("reason") or "")
            sc["reason"] = f"Nexus quality filter: market_cap ${float(market_cap)/1e6:.0f}M < ${min_market_cap/1e6:.0f}M min | {orig_reason}"[:1500]
            filtered_count += 1
            continue

        if avg_volume is not None and float(avg_volume) < min_avg_volume:
            sc["score"] = 0
            sc["action_intent"] = "hold"
            orig_reason = str(sc.get("reason") or "")
            sc["reason"] = f"Nexus quality filter: avg_volume {float(avg_volume):.0f} < {min_avg_volume:.0f} min | {orig_reason}"[:1500]
            filtered_count += 1
            continue

        if market_cap is None and missing_meta_policy in {"block", "fail", "strict"}:
            # A missing market cap means one of three things — a genuine
            # micro-cap, or a metadata lookup that failed, or a ticker the
            # Stocks table never had. Only the first is a reason to refuse, and
            # this branch used to treat all three the same. That is not a
            # theoretical complaint: 0 of 7,052 Stocks rows carry a market_cap,
            # so resolution falls to Neo4j or a live yfinance call whose except
            # handler caches 0 permanently — one rate-limit window and the
            # whole stock lane goes dark, ETFs exempt, while the operator sees
            # only "blocked N low-quality buy(s)" with no names.
            #
            # Dollar volume settles it independently. The names this filter was
            # built for (XNDU ~$200M, BBGI ~$60M, together −$534 in 4 days) do
            # not trade tens of millions of dollars a day; a mega-cap does. So
            # when the cap is unknown but the tape shows real size, admit the
            # name and say so. When neither is available, refuse — and name the
            # ticker, because a silent refusal is what made this expensive to
            # find.
            _dollar_volume = None
            try:
                if avg_volume is not None and cp > 0:
                    _dollar_volume = float(avg_volume) * float(cp)
            except (TypeError, ValueError):
                _dollar_volume = None
            _mcap_dv_floor = float(
                config.get("quality_filter_missing_mcap_min_dollar_volume", 20_000_000)
                or 20_000_000
            )
            if _dollar_volume is not None and _dollar_volume >= _mcap_dv_floor:
                if isinstance(missing_meta_logged, set) and sym not in missing_meta_logged:
                    missing_meta_logged.add(sym)
                    _log(
                        f"Nexus quality filter: {sym} has no market_cap, but "
                        f"${_dollar_volume/1e6:.0f}M/day dollar volume clears the "
                        f"${_mcap_dv_floor/1e6:.0f}M size floor — allowing",
                        "yellow",
                    )
            else:
                sc["score"] = 0
                sc["action_intent"] = "hold"
                orig_reason = str(sc.get("reason") or "")
                sc["reason"] = f"Nexus quality filter: missing market_cap metadata for new non-ETF buy | {orig_reason}"[:1500]
                if isinstance(missing_meta_logged, set) and sym not in missing_meta_logged:
                    missing_meta_logged.add(sym)
                    _dv_txt = (f"${_dollar_volume/1e6:.1f}M/day"
                               if _dollar_volume is not None else "unknown")
                    _log(
                        f"Nexus quality filter BLOCKED {sym}: no market_cap and "
                        f"dollar volume {_dv_txt} < ${_mcap_dv_floor/1e6:.0f}M floor",
                        "red",
                    )
                filtered_count += 1
                continue
        if market_cap is None and missing_meta_policy == "warn" and isinstance(missing_meta_logged, set) and sym not in missing_meta_logged:
            missing_meta_logged.add(sym)
            _log(f"Nexus quality filter: {sym} missing market_cap metadata - allowing due to warn policy", "yellow")

        # Check stock price (secondary filter - supplement buy_price_floor)
        if cp > 0 and cp < 2.0:  # Ultra-penny stocks
            sc["score"] = 0
            sc["action_intent"] = "hold"
            orig_reason = str(sc.get("reason") or "")
            sc["reason"] = f"Nexus quality filter: price ${cp:.2f} < $2.00 (ultra-penny) | {orig_reason}"[:1500]
            filtered_count += 1
            continue

        signal_family, is_propagation = _classify_candidate_signal(sym, sc, strategy_cache=strategy_cache)
        n_paths = int(sc.get("n_paths", 0) or 0)
        raw_score = abs(float(sc.get("raw_score", 0) or sc.get("raw_net_score", 0) or 0))

        if is_propagation and n_paths < propagation_min_paths:
            sc["score"] = 0
            sc["action_intent"] = "hold"
            orig_reason = str(sc.get("reason") or "")
            sc["reason"] = (
                f"Nexus quality filter: {signal_family} {n_paths} paths < {propagation_min_paths} min, "
                f"raw={raw_score:.3f} blocked regardless of propagation floor | {orig_reason}"
            )[:1500]
            filtered_count += 1
            continue

    if filtered_count > 0:
        # Name the tickers. A bare count reads as routine hygiene whether it
        # blocked two penny stocks or the entire stock lane, and that ambiguity
        # is exactly what let a metadata outage look like a quiet market.
        _blocked_names = sorted(
            str(s) for s, _sc in (scores or {}).items()
            if str((_sc or {}).get("reason") or "").startswith("Nexus quality filter:")
        )
        _shown = ", ".join(_blocked_names[:12]) or "?"
        _more = f" (+{len(_blocked_names)-12} more)" if len(_blocked_names) > 12 else ""
        _log(
            f"Nexus quality filter: blocked {filtered_count} low-quality buy(s): "
            f"{_shown}{_more}",
            "yellow",
        )

    return scores


def _apply_portfolio_drawdown_halt(
    scores: dict,
    symbols_list: list[str],
    portfolio_emulator,
    config: dict,
    strategy_cache: dict | None,
    prices: dict[str, float] | None,
    price_history: dict[str, list[dict]] | None,
    date_key: str,
) -> dict:
    if not bool(config.get("portfolio_drawdown_halt_enabled", True)):
        return scores
    if portfolio_emulator is None or strategy_cache is None:
        return scores

    current_value = _portfolio_value_with_fallback(portfolio_emulator, prices, price_history)
    if current_value <= 0.0:
        return scores

    # V9: Relaxed drawdown halt — threshold raised from 10% to 15%, resume from 3 to 2 up-days
    halt_pct = float(config.get("portfolio_drawdown_halt_pct", 15.0) or 15.0)
    resume_up_days = max(1, int(config.get("portfolio_drawdown_resume_up_days", 2) or 2))
    state = _normalize_cache_mapping(strategy_cache, "_portfolio_drawdown_state")
    initial_value = float(getattr(portfolio_emulator, "_initial_value", current_value) or current_value)
    peak_value = max(float(state.get("peak_value", 0.0) or 0.0), current_value, initial_value)
    last_value = float(state.get("last_value", 0.0) or 0.0)
    halt_active = bool(state.get("halt_active", False))
    up_days = int(state.get("up_days", 0) or 0)
    drawdown_pct = ((peak_value - current_value) / peak_value) * 100.0 if peak_value > 0 else 0.0
    triggered_now = False

    # 2026-07-22 profit-ratchet (default OFF): once the portfolio has PEAKED above
    # arm_pct gain, tighten the halt so a sharp reversal banks near the top
    # (bt 855815: a +29.6% peak round-tripped to +8.45%). It is INACTIVE during
    # the climb (peak_gain < arm_pct), so it never whipsaws the way a globally-
    # tight halt did (v3: 11 kills). Only bites at a real cliff after a big run.
    if bool(config.get("portfolio_profit_ratchet_enabled", False)) and initial_value > 0:
        _pr_arm = float(config.get("portfolio_profit_ratchet_arm_pct", 15.0) or 15.0)
        _pr_peak_gain = (peak_value - initial_value) / initial_value * 100.0
        if _pr_peak_gain >= _pr_arm:
            _pr_dd = float(config.get("portfolio_profit_ratchet_drawdown_pct", 10.0) or 10.0)
            if 0.0 < _pr_dd < halt_pct:
                halt_pct = _pr_dd
                if not state.get("ratchet_armed"):
                    state["ratchet_armed"] = True
                    _log(f"Profit-ratchet ARMED: peak +{_pr_peak_gain:.1f}% >= +{_pr_arm:.0f}% "
                         f"— halt tightened to -{_pr_dd:.0f}% from peak to bank gains", "green")

    resumed_now = False

    if not halt_active and drawdown_pct >= halt_pct:
        halt_active = True
        up_days = 0
        triggered_now = True
        state["halt_trigger_date"] = date_key
        _log(
            f"Portfolio drawdown halt: activated at -{drawdown_pct:.1f}% from peak "
            f"(${peak_value:.0f} -> ${current_value:.0f})",
            "yellow",
        )

    if halt_active and not triggered_now and last_value > 0.0:
        # `>=`, not `>`. The kill tier liquidates to 100% cash, and a
        # 100%-cash portfolio has an EXACTLY flat NAV — so a strict `>` can
        # never book an up-day, up_days resets every bar, and the halt becomes
        # an absorbing state the instance can never leave. Flat is not a
        # drawdown; it satisfies "stopped going down", which is what the
        # resume condition is actually asking.
        if current_value >= last_value:
            up_days += 1
        else:
            up_days = 0
        if up_days >= resume_up_days:
            halt_active = False
            up_days = 0
            peak_value = current_value
            resumed_now = True
            _log(
                f"Portfolio drawdown halt: resumed after {resume_up_days} up-day(s) "
                f"(value=${current_value:.0f})",
                "green",
            )

    # 2026-05-28: Discord paging on drawdown halt activation + resume. Prior
    # code only emitted a yellow log line; the operator had no notification
    # channel when buys auto-paused. Live-only (live adapters expose
    # ``_instance_id``; PortfolioEmulator does not). Lazy import + try/except
    # keep this non-fatal — strategy never aborts on a Discord failure.
    _live_instance_id = getattr(portfolio_emulator, "_instance_id", None)
    if _live_instance_id and (triggered_now or resumed_now):
        try:
            from live_alerts import alert_drawdown_halt, alert_strategy_start
            if triggered_now:
                alert_drawdown_halt(
                    instance_id=str(_live_instance_id),
                    drawdown_pct=drawdown_pct,
                    peak_value=peak_value,
                    current_value=current_value,
                )
            elif resumed_now:
                # Reuse alert_strategy_start's "buys resumed" flavor by
                # routing a halt-cleared message via alert_halt's sibling
                # API — but we want a distinct title. Use live_alerts'
                # generic enqueue with our own embed by reaching for the
                # private _safe_enqueue helper, falling back to a plain
                # halt alert if the private symbol is gone.
                try:
                    from live_alerts import _safe_enqueue, _channel
                    content = (
                        f"DRAWDOWN RESUMED [{_live_instance_id}] "
                        f"value=${current_value:,.0f} (new peak baseline)"
                    )
                    _safe_enqueue(_channel("trades"), content, embed={
                        "title": "Drawdown halt resumed",
                        "color": 0x2ECC71,
                        "fields": [
                            {"name": "current_value",
                             "value": f"${current_value:,.0f}",
                             "inline": True},
                            {"name": "effect",
                             "value": "Buys re-enabled; new peak = current",
                             "inline": False},
                        ],
                    })
                except Exception:
                    pass
        except Exception:
            # Alerts must never block strategy execution.
            pass

    if not halt_active and current_value > peak_value:
        peak_value = current_value

    state["peak_value"] = peak_value
    state["last_value"] = current_value
    state["up_days"] = up_days
    state["halt_active"] = halt_active
    state["drawdown_pct"] = round(drawdown_pct, 4)

    # V9: Allow backfill queue to continue during halt at graduated budget
    if halt_active and strategy_cache is not None:
        strategy_cache["_bfq_halt_budget_pct"] = _compute_drawdown_halt_backfill_budget_pct(drawdown_pct, config)
    elif strategy_cache is not None:
        strategy_cache["_bfq_halt_budget_pct"] = 1.0

    # ── 2026-07-19 regime-safety Phase 4: tiered drawdown circuit ──
    # Classifier-independent safety net (the V31 detector has one proven
    # blind-failure mode; this layer only needs the portfolio's own NAV).
    #  soft (5%): halt new buys, but only when SPY's 20d return corroborates
    #             a falling market — a healthy-bull pullback keeps buying.
    #             Blind SPY counts as corroborated (fail-safe).
    #  hard (9%): halt regardless of corroboration + tighten the fast-loser
    #             cut floor (default -7%) so losers exit sooner.
    #  kill (12%): protective liquidation of every held position + halt.
    # A legacy up-days resume re-bases the peak to the current value, so the
    # circuit measures from the operator-accepted new baseline (dd = 0).
    if resumed_now:
        drawdown_pct = 0.0
    circuit_tier = None
    if bool(config.get("drawdown_circuit_enabled", True)):
        _soft_pct = float(config.get("portfolio_dd_soft_pct", 5.0) or 5.0)
        _hard_pct = float(config.get("portfolio_dd_hard_pct", 9.0) or 9.0)
        _kill_pct = float(config.get("portfolio_dd_kill_pct", 12.0) or 12.0)
        if drawdown_pct >= _kill_pct:
            circuit_tier = "kill"
        elif drawdown_pct >= _hard_pct:
            circuit_tier = "hard"
        elif drawdown_pct >= _soft_pct:
            _spy20 = _spy_20d_return(strategy_cache, date_key)
            if _spy20 is None or _spy20 < 0:
                circuit_tier = "soft"
        if circuit_tier and state.get("circuit_tier") != circuit_tier:
            _log(
                f"Drawdown circuit {circuit_tier.upper()}: -{drawdown_pct:.1f}% from peak "
                f"(${peak_value:.0f} -> ${current_value:.0f})",
                "red",
            )
    state["circuit_tier"] = circuit_tier or ""
    if circuit_tier in ("hard", "kill"):
        strategy_cache["_dd_cut_floor_override"] = float(
            config.get("portfolio_dd_hard_cut_floor_pct", -7.0) or -7.0)
    else:
        strategy_cache.pop("_dd_cut_floor_override", None)

    if circuit_tier == "kill":
        _held_syms = []
        try:
            if hasattr(portfolio_emulator, "get_positions"):
                _held_syms = list((portfolio_emulator.get_positions() or {}).keys())
        except Exception:
            _held_syms = []
        # Account loss containment is portfolio-wide.  Sleeve deployment is
        # already disabled during hard/kill tiers, so exempting a leveraged
        # inverse leg here can only retain risk; it cannot prevent redeploy
        # churn.  Liquidate every broker-owned holding, including SQQQ.
        _killed = []
        for sym in _held_syms:
            sc = scores.get(sym) if isinstance(scores.get(sym), dict) else {}
            sc["score"] = -1
            sc["action_intent"] = "sell_override"
            # "Circuit breaker" tag keeps this a risk exit that survives the
            # grace gates (_RISK_EXIT_TAGS).
            sc["reason"] = (
                f"Circuit breaker: drawdown circuit KILL at -{drawdown_pct:.1f}% "
                f"from peak — protective liquidation")
            # 2026-07-25 BUGFIX: _forced_exit was never set here. _finalize_scores
            # computes it from the reason at :18484 — but that runs BEFORE this
            # halt overwrites the reason, so a killed position kept
            # _forced_exit=False. The sweep at :27338 only adds forced exits to
            # nexus_sell_enforcement, so a held name outside the broker's
            # allowed_syms (broker.py:3790) had its KILL order silently dropped,
            # and a momentum-protected name would be stripped at :28541.
            sc["_forced_exit"] = True
            scores[sym] = sc
            _killed.append(sym)
        if _killed:
            _log(
                f"Drawdown circuit KILL: liquidating {len(_killed)} position(s): "
                f"{', '.join(sorted(_killed))}",
                "red",
            )

    if not halt_active and circuit_tier is None:
        return scores

    _halt_why = (f"circuit {circuit_tier}" if circuit_tier else
                 f"halt -{drawdown_pct:.1f}%")
    demoted = []
    for sym in symbols_list:
        sc = scores.get(sym)
        if not isinstance(sc, dict) or sc.get("score") != 1:
            continue
        sc["score"] = 0
        sc["action_intent"] = "hold"
        orig_reason = str(sc.get("reason") or "")
        sc["reason"] = (
            f"DRAWDOWN_HALT ({_halt_why}): buys paused after -{drawdown_pct:.1f}% drawdown "
            f"(resume after {resume_up_days} up days) | {orig_reason}"
        )[:1500]
        demoted.append(sym)

    if demoted:
        _log(f"Portfolio drawdown halt ({_halt_why}): demoted {len(demoted)} buy(s) to hold", "yellow")

    return scores


def _apply_sector_concentration_limit(
    scores: dict,
    symbols_list: list[str],
    config: dict,
    strategy_cache: dict | None = None,
) -> dict:
    """
    Cap any single sector's buy signals at a maximum percentage of total buys.
    Prevents over-concentration when a macro event or sector fill creates many
    simultaneous buy signals in one sector.  Uses the pre-loaded
    _neo4j_stock_sector_cache to determine each ticker's sector.
    """
    if not config.get("sector_concentration_limit_enabled", True):
        return scores
    max_sector_pct = float(config.get("max_sector_buy_pct", 0.25))
    cache = _neo4j_stock_sector_cache
    if not cache:
        return scores

    # Build reverse map: ticker → primary sector (first matching cache key)
    ticker_sector: dict[str, str] = {}
    for sector_kw, tickers in cache.items():
        for t in tickers:
            if t not in ticker_sector:
                ticker_sector[t] = sector_kw

    active_watchlist_priority_tickers = _normalize_cache_string_set(strategy_cache, "_active_watchlist_priority_tickers")
    watchlist_sector_protected_slots = max(0, int(config.get("watchlist_sector_protected_slots", 0) or 0))

    # Group buy signals by sector
    buys_by_sector: dict[str, list[tuple[str, float]]] = {}
    buys_with_meta_by_sector: dict[str, list[dict[str, Any]]] = {}
    all_buys: list[str] = []
    for sym in symbols_list:
        sc = scores.get(sym)
        if isinstance(sc, dict) and sc.get("score") == 1:
            all_buys.append(sym)
            sector = ticker_sector.get(sym, "unknown")
            raw_net = abs(float(sc.get("raw_net_score", 0) or 0))
            buys_by_sector.setdefault(sector, []).append((sym, raw_net))
            candidate_meta = _build_nexus_candidate_meta(
                sym,
                sc,
                config,
                strategy_cache=strategy_cache,
                is_propagation_expansion=bool(sc.get("is_propagation_expansion")),
                is_watchlist_member=bool(sc.get("is_watchlist_member")),
                is_watchlist_priority=bool(sc.get("is_watchlist_priority")) or str(sym).strip().upper() in active_watchlist_priority_tickers,
                signal_source=str(sc.get("signal_source") or "").strip().lower() or None,
                grace_eligible=bool(sc.get("grace_eligible")),
            )
            buys_with_meta_by_sector.setdefault(sector, []).append({
                "ticker": sym,
                "raw_net_score": raw_net,
                "n_paths": int(sc.get("n_paths", 0) or 0),
                "meta": candidate_meta,
            })

    if len(all_buys) < 3:
        return scores

    max_per_sector = max(1, int(len(all_buys) * max_sector_pct))
    demoted: list[tuple[str, str]] = []
    protected_logs: list[str] = []
    for sector, sector_buys in buys_with_meta_by_sector.items():
        if len(sector_buys) <= max_per_sector:
            continue
        ranked = sorted(
            sector_buys,
            key=lambda item: (
                0 if item["meta"].get("is_watchlist_priority") else 1,
                0 if item["meta"].get("is_propagation_expansion") else 1,
                -float(item.get("raw_net_score", 0.0) or 0.0),
                -int(item.get("n_paths", 0) or 0),
                str(item.get("ticker") or ""),
            ),
        )
        protected = ranked[:watchlist_sector_protected_slots]
        protected_set = {str(item.get("ticker") or "").strip().upper() for item in protected if item["meta"].get("is_watchlist_priority") or item["meta"].get("is_propagation_expansion")}
        remaining = [item for item in ranked if str(item.get("ticker") or "").strip().upper() not in protected_set]
        remaining.sort(key=lambda item: (-float(item.get("raw_net_score", 0.0) or 0.0), -int(item.get("n_paths", 0) or 0), str(item.get("ticker") or "")))
        survivors = []
        for item in protected:
            ticker = str(item.get("ticker") or "").strip().upper()
            if ticker in protected_set and ticker not in {str(x.get("ticker") or "").strip().upper() for x in survivors}:
                survivors.append(item)
        for item in remaining:
            if len(survivors) >= max_per_sector:
                break
            survivors.append(item)
        survivor_set = {str(item.get("ticker") or "").strip().upper() for item in survivors}
        # Z4.2 (2026-05-15): soft sector cap with priority override. Allow
        # high-conviction buys (raw_net_score >= cap AND n_paths >= path floor)
        # to bypass the sector cap. Backtest 299903 had ALAB/CRWD/NET stuck
        # in queue despite Base=+1.0 / 22 paths because the hard sector cap
        # blocked them outright. Configurable so operators can tighten.
        _z42_raw_cap = float(config.get("sector_cap_override_raw_net_score", 0.8) or 0.8)
        _z42_path_min = int(config.get("sector_cap_override_min_paths", 5) or 5)
        demoted_names: list[str] = []
        bypassed_names: list[str] = []
        for item in ranked:
            sym = str(item.get("ticker") or "").strip().upper()
            if sym in survivor_set:
                continue
            _item_raw = float(item.get("raw_net_score", 0.0) or 0.0)
            _item_paths = int(item.get("n_paths", 0) or 0)
            if _item_raw >= _z42_raw_cap and _item_paths >= _z42_path_min:
                bypassed_names.append(f"{sym}(raw={_item_raw:.2f},p={_item_paths})")
                continue
            sc = scores.get(sym) or {}
            sc["score"] = 0
            sc["action_intent"] = "hold"
            orig_reason = str(sc.get("reason") or "")
            sc["reason"] = (
                f"SECTOR_CAP: {sector} exceeded {max_sector_pct:.0%} limit "
                f"({len(ranked)} buys, max {max_per_sector}) | {orig_reason}"
            )[:1500]
            demoted.append((sym, sector))
            demoted_names.append(sym)
        if bypassed_names:
            _log(
                f"Sector concentration override (Z4.2): {sector} allowed "
                f"{len(bypassed_names)} high-conviction buy(s): "
                f"{', '.join(bypassed_names[:8])}",
                "cyan",
            )
        if demoted_names:
            protected_names = [str(item.get("ticker") or "").strip().upper() for item in survivors if str(item.get("ticker") or "").strip()]
            protected_logs.append(f"{sector}: kept {', '.join(protected_names[:max_per_sector])} | demoted {', '.join(demoted_names[:max_per_sector])}")
    if demoted:
        _sectors_hit = len({s for _, s in demoted})
        _log(
            f"Sector concentration: demoted {len(demoted)} buy(s) to hold "
            f"across {_sectors_hit} sector(s)",
            "yellow",
        )
        for _detail in protected_logs[:6]:
            _log(f"Sector concentration detail: {_detail}", "yellow")
        return scores

    return scores


class GraphNexusAnalysis:
    """
    Run-once strategy: today's news + relationship-aware Neo4j contagion propagation.

    Leverages 10+ relationship types (SUPPLIER_OF, PARENT_OF, CONTROLS, COMPETES_WITH,
    STRATEGIC_PARTNER, PATENT_PARTNER, IN_SECTOR, SUPPLIES_TO_SECTOR,
    HOLDS, plus 2-hop chains) with directional weights, edge confidence/revenue/obligation
    metadata, patent depth scoring, position-size-weighted institutional correlation,
    macro sector flow, event-type amplification, and multi-path aggregation.
    """

    def run(
        self,
        symbol,
        price,
        current_time,
        config: dict,
        conditions: dict,
        data=None,
        portfolio_emulator=None,
        strategy_cache=None,
        time_increment=None,
        *,
        point_in_time_context=None,
        point_in_time_store=None,
        point_in_time_fundamentals=None,
        session_close_resolver=None,
    ):
        """
        Per-symbol entry point. Delegates to run_once([symbol], ...) and returns
        score (and optional reason) for this symbol. Use execution_scope "run_once"
        in the strategy spec so the broker calls run_once once per loop instead.
        """
        if point_in_time_context is None and data is None:
            from datetime import timezone as _timezone
            from point_in_time_data import DatasetManifest, PointInTimeContext

            live_as_of = current_time
            if not isinstance(live_as_of, datetime):
                live_as_of = datetime.now(_timezone.utc)
            elif live_as_of.tzinfo is None:
                live_as_of = live_as_of.replace(tzinfo=_timezone.utc)
            else:
                live_as_of = live_as_of.astimezone(_timezone.utc)
            point_in_time_context = PointInTimeContext.for_live(
                as_of=live_as_of,
                manifest=DatasetManifest(
                    manifest_id="graph-nexus-live-current",
                    source_hashes={"live": "current-state"},
                    created_at=live_as_of,
                ),
            )
        prices = {symbol: price} if price is not None else {}
        raw = self.run_once(
            [symbol],
            prices,
            current_time,
            config,
            conditions,
            data=data,
            portfolio_emulator=portfolio_emulator,
            strategy_cache=strategy_cache,
            time_increment=time_increment,
            point_in_time_context=point_in_time_context,
            point_in_time_store=point_in_time_store,
            point_in_time_fundamentals=point_in_time_fundamentals,
            session_close_resolver=session_close_resolver,
        )
        if not raw or symbol not in raw:
            return (0, None, None, "No clear signal")
        val = raw[symbol]
        if isinstance(val, dict):
            score = val.get("score", val.get("signal", 0))
            reason = val.get("reason")
            if reason is not None:
                return (score, None, None, str(reason)[:500] if reason else None)
            return (score, None, None, f"Calculated score: {score}")
        return (int(val) if val is not None else 0, None, None, None)

    # ── Dual-cadence helpers ──────────────────────────────────────────────
    def _hold_days_ny(self, emulator, sym: str, current_time_utc) -> int | None:
        """Days since this symbol's most recent un-sold buy, in NY-local days.

        Returns None if entry trade is unknown (treat as 'unknown — block exit'
        in monitor cycles to avoid same-day-trading risk for manual buys).
        """
        if emulator is None:
            return None
        entry_ts = _get_open_position_entry_timestamp(emulator, sym)
        if entry_ts is None:
            return None
        try:
            from datetime import timezone as _tz
            from zoneinfo import ZoneInfo as _ZI
            if hasattr(entry_ts, "tzinfo"):
                if entry_ts.tzinfo is None:
                    entry_ts = entry_ts.replace(tzinfo=_tz.utc)
                entry_ny = entry_ts.astimezone(_ZI("America/New_York")).date()
            else:
                # String timestamp — best effort parse.
                from datetime import datetime as _dt
                _e = _dt.fromisoformat(str(entry_ts).replace("Z", "+00:00"))
                if _e.tzinfo is None:
                    _e = _e.replace(tzinfo=_tz.utc)
                entry_ny = _e.astimezone(_ZI("America/New_York")).date()
            if current_time_utc.tzinfo is None:
                current_time_utc = current_time_utc.replace(tzinfo=_tz.utc)
            now_ny = current_time_utc.astimezone(_ZI("America/New_York")).date()
            return max(0, (now_ny - entry_ny).days)
        except Exception:
            return None

    def _run_monitor_cycle(
        self,
        symbols_list,
        prices,
        price_history,
        config,
        portfolio_emulator,
        strategy_cache,
        date_key,
        current_time,
    ) -> dict:
        """Lightweight risk-only cadence for the dual-cadence live mode.

        Iterates currently held positions only; for each one runs
        _evaluate_position_risk with bypass_winner_protection=True and
        side_effect_mode="monitor". Day-trading guard: positions opened today
        (NY-local) are NEVER sold by monitor; their HWM is still updated.
        Returns a dict mirroring run_once output (sells/holds + the same
        _nexus_* metadata keys the broker reads).
        """
        from time import perf_counter as _pc
        _t0 = _pc()
        out: dict = {}
        sells = 0
        holds = 0
        if portfolio_emulator is None:
            positions = {}
        else:
            try:
                positions = portfolio_emulator.get_positions() or {}
            except Exception:
                positions = {}
        held = [s for s, q in positions.items() if float(q or 0) > 0]
        block_same_day = bool(
            (config or {}).get(
                "nexus_dual_cadence_monitor_block_same_day_exit", True
            )
        )
        # 2026-05-06: pre-market sell deferral. Monitor can run at 5:00-6:30
        # AM PT (pre-market window) but RH rejects market+day+ext_hours=False
        # orders during pre-market with HTTP 400 — sell signal would fire
        # every tick, get rejected, fire again next tick. Default: convert
        # sell signals to HOLD during pre-market; first post-open monitor
        # tick (or the FULL cycle at market open) will re-evaluate and
        # execute. Operator can opt-in to pre-market execution by setting
        # this flag True (requires extended_hours flag handling in adapter).
        _execute_pre_open = bool(
            (config or {}).get(
                "nexus_dual_cadence_monitor_execute_pre_open", False
            )
        )
        # Detect pre-market window for current_time: now_pt < full_anchor_pt
        # but >= open_pt. Strategy is already in pre-market if it called
        # this method via the new gate branch, but compute defensively here
        # for any direct callers.
        _is_pre_market_now = False
        try:
            from datetime import timezone as _tz_pre
            from zoneinfo import ZoneInfo as _ZI_pre
            _ct_utc = current_time
            if hasattr(_ct_utc, "tzinfo") and _ct_utc.tzinfo is None:
                _ct_utc = _ct_utc.replace(tzinfo=_tz_pre.utc)
            _ct_pt = _ct_utc.astimezone(_ZI_pre("America/Los_Angeles"))
            _full_min_pt = int((config or {}).get("nexus_dual_cadence_full_cycle_minute_of_day_pt", 390))
            _open_hour_pt = int((config or {}).get("nexus_dual_cadence_open_hour_pt", 5))
            _now_min_pt = _ct_pt.hour * 60 + _ct_pt.minute
            _is_pre_market_now = (_open_hour_pt * 60 <= _now_min_pt < _full_min_pt)
        except Exception:
            _is_pre_market_now = False
        if not isinstance(strategy_cache, dict):
            strategy_cache = {}
        # 2026-05-07 backtest perf: stamp the cycle mode so the broker
        # outer loop can skip per-bar EPPI + snapshot work on MONITOR
        # bars in dual-cadence backtest harness mode (where the strategy
        # decides FULL/MONITOR itself but the broker doesn't see the
        # mode it picked).
        try:
            strategy_cache["_nexus_last_tick_mode"] = "MONITOR"
        except Exception:
            pass
        _unknown_logged = strategy_cache.setdefault(
            "_nexus_unknown_entry_logged", set()
        )
        if not isinstance(_unknown_logged, set):
            try:
                _unknown_logged = set(_unknown_logged)
            except Exception:
                _unknown_logged = set()
            strategy_cache["_nexus_unknown_entry_logged"] = _unknown_logged
        # Use config-driven instance_id (stable across container restarts) so
        # the unknown-entry de-dup set survives reboots. id(self) was rejected
        # because it changes every process — would re-log every restart.
        _inst_id = str((config or {}).get("runtime_instance_id") or "default")
        for sym in held:
            held_days_ny = self._hold_days_ny(
                portfolio_emulator, sym, current_time
            )
            if held_days_ny is None:
                # Unknown entry — never auto-sell. Log YELLOW once per
                # (instance, sym, date) per day. Use joined-string key so
                # the set round-trips cleanly through RethinkDB JSON
                # serialization (tuples serialize as lists, breaking 'in' check).
                _key = f"{_inst_id}|{sym}|{date_key}"
                if _key not in _unknown_logged:
                    _log(
                        f"Monitor SKIP (unknown entry): {sym} — manual buy or "
                        f"missing trade history; skipping risk evaluation",
                        "yellow",
                    )
                    _unknown_logged.add(_key)
                out[sym] = {
                    "score": 0,
                    "reason": "monitor: unknown-entry skip",
                    "_forced_exit": False,
                }
                holds += 1
                continue

            if held_days_ny == 0 and block_same_day:
                # Same-day-entry guard: never sell, but keep the HWM advancing.
                try:
                    _entry_ts = _get_open_position_entry_timestamp(
                        portfolio_emulator, sym
                    )
                    _cp = _resolve_symbol_price(
                        sym, prices, price_history,
                        portfolio_emulator=portfolio_emulator,
                    )
                    if _cp and _cp > 0:
                        _peak_key, _stored_peak = _resolve_position_peak_state(
                            strategy_cache, sym, _entry_ts, _cp
                        )
                        if _cp > float(_stored_peak or 0.0):
                            strategy_cache[_peak_key] = _cp
                except Exception:
                    pass
                out[sym] = {
                    "score": 0,
                    "reason": "monitor: same-day-entry block",
                    "_forced_exit": False,
                }
                holds += 1
                continue

            # Risk evaluation via the shared helper. Empty propagated dict and
            # bypass_winner_protection=True — monitor has no fresh sentiment
            # context, so the winner-protection ladder (which gates against
            # _prop_raw) cannot apply.
            try:
                _entry_ts = _get_open_position_entry_timestamp(
                    portfolio_emulator, sym
                )
                _max_hold_days = int(config.get("max_hold_days", 90) or 90)
                _epr_score, _epr_reason, _epr_extras = _evaluate_position_risk(
                    sym,
                    fresh_score=0,
                    fresh_reason="monitor: hold",
                    config=config,
                    portfolio_emulator=portfolio_emulator,
                    strategy_cache=strategy_cache,
                    prices=prices,
                    price_history=price_history,
                    date_key=date_key,
                    propagated={},
                    entry_buy_ts=_entry_ts,
                    held_days=int(held_days_ny),
                    max_hold_days=_max_hold_days,
                    bypass_winner_protection=True,
                    side_effect_mode="monitor",
                )
            except Exception as _epr_exc:
                _log(
                    f"Monitor risk-eval ERROR: {sym} — {type(_epr_exc).__name__}: "
                    f"{str(_epr_exc)[:200]}",
                    "red",
                )
                out[sym] = {
                    "score": 0,
                    "reason": f"monitor: risk-eval error ({type(_epr_exc).__name__})",
                    "_forced_exit": False,
                }
                holds += 1
                continue

            _entry: dict = {
                "score": int(_epr_score) if _epr_score in (-1, 0, 1) else 0,
                "reason": str(_epr_reason or "monitor: hold"),
                "_forced_exit": (
                    _epr_score == -1
                    and _epr_reason
                    and any(
                        x in _epr_reason
                        for x in _FORCED_EXIT_TAGS
                    )
                ),
            }
            if isinstance(_epr_extras, dict) and "sell_fraction" in _epr_extras:
                _entry["sell_fraction"] = float(_epr_extras["sell_fraction"])
            # Partial profit-take trims run only on the daily cycle, where the
            # tier sell_fraction is plumbed to the broker via _nexus_position_sizes.
            # The monitor tick has no per-symbol size channel, so a "Profit take"
            # sell here would default to a 100% liquidation — defer it to daily.
            if _entry["score"] == -1 and "Profit take" in (_epr_reason or ""):
                _entry["score"] = 0
                _entry["reason"] = "monitor: profit-take deferred to daily cycle"
                _entry.pop("sell_fraction", None)
            # Monitor never emits buys.
            if _entry["score"] == 1:
                _entry["score"] = 0
                _entry["reason"] = "monitor: buy suppressed"
            # Pre-market sell-execution defer: log the would-be sell but
            # convert to HOLD so broker doesn't submit a market+day order
            # that RH rejects with HTTP 400 during pre-market hours.
            if (
                _entry["score"] == -1
                and _is_pre_market_now
                and not _execute_pre_open
                # 2026-07-23: in a backtest every hourly bar is fillable, so the
                # live pre-market defer (RH rejects market+day pre-open) is wrong
                # here — it would push an intraday risk exit into the next bar's
                # gap-down. Skip the defer for backtest ticks when monitor
                # risk-exit execution is enabled. Live behavior is unchanged.
                and not (
                    (
                        bool(config.get("nexus_monitor_risk_exit_execution_enabled", False))
                        # Same regime-independent flag as the execution gate
                        # below: without it the pre-open bars re-defer the exit
                        # and it is dropped anyway (observed in bt#148462 on
                        # 2026-04-23 12:00/13:00, "Pre-market sell DEFERRED").
                        or bool(config.get("nexus_monitor_risk_exit_always_enabled", False))
                    )
                    and bool(config.get("nexus_dual_cadence_backtest_simulation", False))
                )
            ):
                _orig_reason = _entry.get("reason") or ""
                _entry["score"] = 0
                _entry["reason"] = (
                    f"monitor: pre-market sell deferred to post-open "
                    f"[{_orig_reason[:80]}]"
                )
                _entry["_forced_exit"] = False
                _log(
                    f"Pre-market sell DEFERRED: {sym} would-have-sold "
                    f"(reason='{_orig_reason[:60]}') — execution deferred "
                    f"until 6:30 AM PT (post-open)",
                    "yellow",
                )
            out[sym] = _entry
            if _entry["score"] == -1:
                sells += 1
            else:
                holds += 1

            # Per-position decision log so the operator can see EVERY position's
            # outcome from the hourly cycle, not just an aggregate count.
            # Entry price lives in the trade history (via _get_open_position_entry_trade),
            # NOT in portfolio_emulator.get_positions() which returns {sym: qty}.
            try:
                _pos_dec_pnl: float | None = None
                _pos_dec_entry = 0.0
                _pos_dec_cp = 0.0
                _entry_trade = _get_open_position_entry_trade(portfolio_emulator, sym)
                try:
                    _pos_dec_entry = float((_entry_trade or {}).get("price", 0.0) or 0.0)
                except Exception:
                    _pos_dec_entry = 0.0
                _pos_dec_cp_raw = _resolve_symbol_price(
                    sym, prices, price_history,
                    portfolio_emulator=portfolio_emulator,
                )
                try:
                    _pos_dec_cp = float(_pos_dec_cp_raw or 0.0)
                except Exception:
                    _pos_dec_cp = 0.0
                if _pos_dec_entry > 0 and _pos_dec_cp > 0:
                    _pos_dec_pnl = ((_pos_dec_cp / _pos_dec_entry) - 1.0) * 100.0
                _pos_dec_action = "SELL" if _entry["score"] == -1 else "HOLD"
                _pos_dec_color = "red" if _entry["score"] == -1 else "white"
                _pnl_str = (
                    f"{_pos_dec_pnl:+.1f}%"
                    if _pos_dec_pnl is not None
                    else "n/a"
                )
                _reason_short = str(_entry.get("reason") or "")[:120]
                _log(
                    f"Monitor decision: {sym} day {int(held_days_ny)} "
                    f"pnl={_pnl_str} cp=${_pos_dec_cp:.2f} entry=${_pos_dec_entry:.2f} "
                    f"→ {_pos_dec_action} ({_reason_short})",
                    _pos_dec_color,
                )
            except Exception as _dec_log_e:
                # Logging never blocks the cycle; just note the failure.
                try:
                    _log(
                        f"Monitor decision-log failed for {sym}: "
                        f"{type(_dec_log_e).__name__}: {_dec_log_e}",
                        "yellow",
                    )
                except Exception:
                    pass

        # Always update last-monitor-tick timestamp (diagnostic).
        try:
            from datetime import timezone as _tz
            _now = current_time
            if hasattr(_now, "tzinfo") and _now.tzinfo is None:
                _now = _now.replace(tzinfo=_tz.utc)
            strategy_cache["_nexus_last_monitor_tick_utc"] = _now.isoformat()
        except Exception:
            pass

        # Populate the broker-expected _nexus_* metadata keys with empty
        # values so downstream allocator code doesn't see prior-tick state.
        out["_nexus_discovered"] = []
        out["_nexus_position_sizes"] = {
            "_cash_reserve_floor_pct": float(
                config.get("cash_reserve_floor_pct", 0.10)
            ),
            "_cash_reserve_floor_hard": bool(
                config.get("cash_reserve_floor_hard", True)
            ),
            "_cash_reserve_hard_min_positions": int(
                config.get("cash_reserve_hard_min_positions", 5)
            ),
            "_cash_reserve_release_after_min_positions": bool(
                config.get("cash_reserve_release_after_min_positions", True)
            ),
            "_buy_price_floor": float(config.get("buy_price_floor", 5.0) or 0.0),
        }
        out["_nexus_executable_buys"] = []
        out["_nexus_action_intents"] = {}
        # Pass-through any existing sell-enforcement set from the day's full
        # cycle so the broker's sell-enforcement gate still applies.
        _existing_se = (strategy_cache or {}).get("_nexus_sell_enforcement_last")
        _se_out = list(_existing_se) if isinstance(_existing_se, (list, set, tuple)) else []
        # 2026-07-23 PEAK-DEFENSE: route the monitor's OWN freshly-triggered
        # forced-exit sells (Trailing stop / Circuit breaker / Fast loser /
        # Hold-limit) into enforcement so they EXECUTE this intraday tick. Without
        # this, the monitor computes and logs the risk exit but returns only the
        # prior FULL cycle's enforcement + empty per-symbol sizes, so the sell is
        # silently dropped and a rolling-over winner rides its parabola all the
        # way down (bt701112/#288005: CAR peaks +142% $752 -> exits $253 -18%).
        # The broker executes enforcement sells via V7.5 injection + the
        # decision override, independent of the (empty) discovery universe.
        # Default OFF; live behavior byte-identical until enabled.
        # 2026-07-31 REGIME-INDEPENDENT RISK EXIT. In the doc-179 production
        # config the flag above lives ONLY in regime_profiles.bull/.recovery
        # (base is false), so intraday risk exits execute only once the regime
        # has confirmed bull — and are silently dropped in bear, chop and crash,
        # i.e. exactly when protection matters most. Verified on the 2026-04-22
        # CAR cascade: the monitor computed SELL on six consecutive bars
        # ("Trailing stop SELL: ... drop=28.8% >= 24%") and every one was
        # discarded at this gate; the position finally sold 22h later, $619 ->
        # $253. This second flag is stripped from every overlay by
        # _REGIME_PROFILE_BASE_ONLY_KEYS, so its BASE value always wins and a
        # regime profile cannot switch risk exits back off.
        # Default OFF; behavior byte-identical until enabled.
        if (
            bool(config.get("nexus_monitor_risk_exit_execution_enabled", False))
            or bool(config.get("nexus_monitor_risk_exit_always_enabled", False))
        ):
            for _msym, _mentry in out.items():
                if (
                    isinstance(_mentry, dict)
                    and _mentry.get("score") == -1
                    and _mentry.get("_forced_exit")
                    and _msym not in _se_out
                ):
                    _se_out.append(_msym)
        out["_nexus_sell_enforcement"] = _se_out
        out["_nexus_active_events"] = []
        out["_nexus_expansion_buys"] = []

        _elapsed_ms = int(max(0, (_pc() - _t0) * 1000.0))
        _log(
            f"Monitor cycle complete | date={date_key} | symbols={len(held)} | "
            f"sells={sells} | holds={holds} | elapsed={_elapsed_ms}ms",
            "green",
        )
        return out

    def run_historical(
        self,
        symbols: list,
        prices: dict,
        current_time,
        config: dict,
        conditions: dict,
        data=None,
        portfolio_emulator=None,
        strategy_cache=None,
        time_increment=None,
        *,
        context=None,
        point_in_time_store=None,
        session_close_resolver=None,
        mode=None,
    ) -> dict:
        """Run Graph Nexus against immutable, dated research inputs.

        Historical execution deliberately has a separate entry point so a
        caller cannot accidentally enter the legacy current-state path.  All
        required snapshots are resolved before any strategy work begins.
        """
        from point_in_time_data import (
            ImmutableSnapshotStore,
            PointInTimeContext,
            PointInTimeDataError,
            load_snapshot_payload,
        )
        from ticker_universe import load_universe_snapshot

        if not isinstance(context, PointInTimeContext) or context.is_live:
            raise PointInTimeDataError(
                "historical Graph Nexus requires a non-live PointInTimeContext"
            )
        if not context.strict:
            raise PointInTimeDataError(
                "historical Graph Nexus requires a strict PointInTimeContext"
            )
        if not callable(session_close_resolver):
            raise PointInTimeDataError(
                "historical Graph Nexus requires a session close resolver"
            )
        point_in_time_store = ImmutableSnapshotStore.coerce(
            point_in_time_store
        )

        # Fail closed before the large strategy pipeline can mutate caches or
        # contact a present-day source.
        graph_driver = load_graph_snapshot(
            context=context,
            store=point_in_time_store,
        )
        fundamentals = load_fundamentals_snapshot(
            context=context,
            store=point_in_time_store,
        )
        load_universe_snapshot(context=context, store=point_in_time_store)
        load_snapshot_payload(
            point_in_time_store,
            dataset="news",
            context=context,
        )

        result = self.run_once(
            symbols,
            prices,
            current_time,
            config,
            conditions,
            data=data,
            portfolio_emulator=portfolio_emulator,
            strategy_cache=strategy_cache,
            time_increment=time_increment,
            mode=mode,
            point_in_time_context=context,
            point_in_time_store=point_in_time_store,
            point_in_time_graph=graph_driver,
            point_in_time_fundamentals=fundamentals,
            session_close_resolver=session_close_resolver,
        )
        audit_replay = getattr(graph_driver, "assert_replay_complete", None)
        if callable(audit_replay):
            audit_replay()
        return result

    def run_once(
        self,
        symbols: list,
        prices: dict,
        current_time,
        config: dict,
        conditions: dict,
        data=None,
        portfolio_emulator=None,
        strategy_cache=None,
        time_increment=None,
        *,
        mode=None,  # 2026-05-07 scheduler refactor commit 2: explicit mode
                    # ("FULL" | "MONITOR" | "IDLE") supplied by the broker's
                    # get_next_wake. mode=None preserves legacy behavior for
                    # backtests + the per-symbol shim — the dual-cadence gate
                    # below decides FULL/MONITOR/IDLE itself when mode is None.
                    # See docs/superpowers/specs/2026-05-07-live-broker-scheduler-design.md.
        point_in_time_context=None,
        point_in_time_store=None,
        point_in_time_graph=None,
        point_in_time_fundamentals=None,
        session_close_resolver=None,
    ) -> dict:
        """
        Run once per trading loop. Fetch news, classify via LLM, propagate through
        Neo4j graph with relationship-aware contagion, return dict[symbol -> score_data].
        """
        from _phase_alpha_helpers import validate_model_evidence_preflight
        validate_model_evidence_preflight(config)
        # A run may DECLARE that it is opting out of strict point-in-time
        # replay. That is only ever legitimate when no frozen snapshots exist
        # for the window, it must be asked for by name, and the resulting run
        # is stamped legacy_unverified and can never be promotion-eligible.
        _pit_research = (
            str((config or {}).get("pit_mode") or "strict").strip().lower()
            == "research"
        )
        if point_in_time_context is None and data is not None:
            from point_in_time_data import PointInTimeDataError

            raise PointInTimeDataError(
                "historical Graph Nexus requires a point-in-time context"
            )
        if point_in_time_context is not None:
            from point_in_time_data import (
                PointInTimeContext,
                PointInTimeDataError,
            )

            if not isinstance(point_in_time_context, PointInTimeContext):
                raise PointInTimeDataError(
                    "point_in_time_context must be a PointInTimeContext"
                )
            if (
                not point_in_time_context.is_live
                and not point_in_time_context.strict
                and not _pit_research
            ):
                raise PointInTimeDataError(
                    "historical Graph Nexus requires a strict "
                    "PointInTimeContext"
                )
            if (
                not point_in_time_context.is_live
                and not callable(session_close_resolver)
            ):
                raise PointInTimeDataError(
                    "historical Graph Nexus requires a session close resolver"
                )
        _pit_capture_requested = _pit_capture_enabled(
            config,
            point_in_time_context,
            mode,
        )
        if isinstance(strategy_cache, dict):
            strategy_cache["_point_in_time_context"] = point_in_time_context
            # The resolver is a run_once PARAMETER, but the overlay-bar consumers
            # that need it are module-level helpers nested 3-4 calls deep and
            # threading it through ~10 signatures would touch far more surface
            # than the boundary it enforces. Stash it beside the context so
            # _overlay_daily_cutoff can ask "had this session closed yet?".
            if callable(session_close_resolver):
                strategy_cache["_point_in_time_session_close_resolver"] = (
                    session_close_resolver
                )
            else:
                strategy_cache.pop(
                    "_point_in_time_session_close_resolver", None
                )
            strategy_cache.pop("_overlay_daily_cutoff_memo", None)
            if point_in_time_fundamentals is not None:
                strategy_cache["_point_in_time_fundamentals"] = (
                    point_in_time_fundamentals
                )
            else:
                strategy_cache.pop("_point_in_time_fundamentals", None)
        _activate_point_in_time_graph_scope(
            point_in_time_context,
            strategy_cache=strategy_cache,
            config=config,
        )
        symbols_list = list(symbols or [])
        # Discovery can populate the initial symbol universe even when no symbols
        # are passed into the strategy.

        # 2026-05-07 granularity-scaling: stash the resolved time_increment in
        # config so deeply-nested helpers can call _scale_bars(default, config)
        # without us threading it through 30+ function signatures. See
        # docstring at module top for full rationale. time_increment is None
        # for live mode (defaults to 3600 baseline) — the live broker drives
        # the schedule via backend.scheduler so live cadence is independent.
        try:
            _ti_resolved = int(time_increment) if time_increment else 0
        except Exception:
            _ti_resolved = 0
        if _ti_resolved <= 0:
            _ti_resolved = 3600  # live mode / unset → assume baseline
        config["_resolved_time_increment_sec"] = _ti_resolved
        # Mirror onto the cache for _overlay_daily_cutoff: _resolve_asof_bars and
        # _spy_20d_return take no config, and the daily-vs-intraday distinction
        # decides whether the current session's daily bar is observable yet.
        if isinstance(strategy_cache, dict):
            strategy_cache["_resolved_time_increment_sec"] = _ti_resolved
            strategy_cache["_overlay_allow_same_session_daily_bar"] = bool(
                config.get("overlay_allow_same_session_daily_bar", False)
            )
            strategy_cache["_pit_scale_market_cap"] = bool(
                config.get("pit_scale_market_cap_to_as_of", True)
            )

        # 2026-05-07 backtest perf: clear the prior tick's stamp so a
        # mid-strategy crash leaves None (broker falls through to snapshot)
        # rather than a stale value (broker might skip a snapshot on a
        # bar where fills actually happened). The IDLE/MONITOR/FULL
        # branches below each re-stamp the correct value.
        if isinstance(strategy_cache, dict):
            try:
                strategy_cache["_nexus_last_tick_mode"] = None
            except Exception:
                pass

        # ── Resolve configuration ─────────────────────────────────────────
        alpaca_key = (config.get("alpaca_key") or conditions.get("alpaca_key") or "").strip() or os.environ.get("APCA_API_KEY_ID", "") or os.environ.get("KEY", "")
        alpaca_secret = (config.get("alpaca_secret") or conditions.get("alpaca_secret") or "").strip() or os.environ.get("APCA_API_SECRET_KEY", "") or os.environ.get("SECRET", "")
        min_articles = int(config.get("min_articles") or conditions.get("min_articles") or 20)
        max_daily_alpaca_articles = int(config.get("max_daily_alpaca_articles") or config.get("num_articles") or conditions.get("num_articles") or 50)
        max_daily_google_news_articles = int(config.get("max_daily_google_news_articles") or config.get("google_news_max_articles") or 50)
        num_articles = max_daily_alpaca_articles
        num_articles_for_llm = int(config.get("num_articles_for_llm") or max_daily_alpaca_articles or 30)
        use_llm = config.get("use_llm_sentiment", True)
        # Phase α.1 (2026-05-18, BT109429 follow-up): force-enable sentiment
        # cache in any non-live context for paired re-run determinism. The
        # variance/robustness agent attributed 40-60% of the 4.8x same-code
        # spread (BT901920 +247.6% / BT136708 +171.3% / BT109429 +51.9%) to
        # LLM non-determinism (gpt-5.4-mini omits temperature -> OpenAI
        # default 1.0). With the cache mandatory in backtest, the LLM only
        # fires on (date, ticker, articles_hash) cache miss; subsequent
        # paired runs hit the cache and emit identical sentiment. Live mode
        # (live=True AND lookback=False) honors operator config. The
        # (live=True AND lookback=True) "live with lookback pre-pass" path
        # still hits the cache — pre-pass is deterministic-prep regardless.
        # Logic extracted to _phase_alpha_helpers.resolve_use_sentiment_cache.
        # Bare import (not `backend.`) because prod Docker layout is flat at /app/.
        from _phase_alpha_helpers import (
            resolve_use_sentiment_cache as _resolve_use_sentiment_cache,
        )
        use_sentiment_cache, _alpha1_forced = _resolve_use_sentiment_cache(config)
        if _alpha1_forced:
            _log(
                "Phase alpha.1: forcing use_sentiment_cache=True in backtest mode "
                "(operator config had False; set "
                "`nexus_sentiment_cache_force_in_backtest=False` to opt out)",
                "yellow",
            )
        llm_provider, llm_key, llm_model, _ = _resolve_role_llm_config(config, "")
        llm_provider_config = _resolve_role_llm_provider_config(config, "")
        llm_model_ref = _llm_model_ref(llm_model, llm_provider_config)
        neo4j_uri, neo4j_user, neo4j_password = _resolve_neo4j_runtime_config(config)

        # ── New feature config reads ─────────────────────────────────────
        use_toon = config.get("use_toon_format", True)
        outcome_tracking = config.get("outcome_tracking_enabled", True)
        learning_stage_enabled = config.get("learning_stage_enabled", True)
        learning_stage_days = int(config.get("learning_stage_days", 14))
        learning_refresh_hours = float(config.get("learning_refresh_hours", 12))
        lookback_learning_days = int(config.get("lookback_learning_days", learning_stage_days or 30) or 30)
        # Live-readiness (2026-04-29): set module-level live-mode flag so
        # utility functions like _yf_batch_prices can apply wall-clock budgets
        # without breaking backtest determinism. config["_nexus_is_live_mode"]
        # is set by broker.py at line 2064.
        global _GN_LIVE_MODE_FLAG
        _GN_LIVE_MODE_FLAG = bool(config.get("_nexus_is_live_mode", False))

        # instance_id needed early (outcome tracking, learning)
        # Live-readiness HIGH #11 (2026-04-29): fail-loud when instance_id falls
        # back to literal "default". In live mode this would key all outcomes/
        # snapshots/cleanup-markers/learning caches to "default", colliding with
        # any other "default" instance and silently corrupting state.
        instance_id = (
            str(config.get("runtime_instance_id") or "").strip()
            or str(config.get("instance_id") or "").strip()
            or os.environ.get("INSTANCE_ID", "").strip()
        )
        if not instance_id:
            instance_id = "default"
            _is_live = bool(config.get("_nexus_is_live_mode")) or (data is None)
            if _is_live:
                _log(
                    "FATAL: instance_id is empty in LIVE mode — falling back to 'default' "
                    "would collide state across instances. Set INSTANCE_ID env or pass "
                    "config.runtime_instance_id explicitly. Continuing with 'default' but "
                    "outcomes/snapshots may be corrupted.",
                    "red",
                )
            else:
                _log("instance_id empty — using 'default' for backtest", "yellow")
        base_instance_id = str(config.get("base_instance_id") or "").strip() or instance_id
        history_scope_id = str(config.get("history_scope_id") or "").strip()
        history_model_stamp = dict(config.get("history_model_stamp") or {})
        sentiment_cache_scope_id = _enhanced_sentiment_cache_scope_id(config, instance_id)
        sentiment_cache_scope_doc = _enhanced_sentiment_cache_scope_doc(config, instance_id)
        active_event_history_scope_id = _active_event_history_scope_id(config)
        historical_lookback_mode = bool(config.get("historical_lookback_mode", False))
        # Phase δ observability sweep (2026-05-18, BT232179 follow-up):
        # surface the resolved sentiment_cache_scope_id at run_once entry
        # so operators can verify paired re-runs of the same backtest share
        # the same cache scope. Per the salt audit, the scope_id is derived
        # from operator-configured static fields (history_scope_id,
        # provider, model, prompt_version, use_toon_format,
        # num_articles_for_llm, sentiment_cache_scope_salt). It does NOT
        # auto-rotate per backtest run. If two paired runs of the same
        # backtest_id log DIFFERENT scope_ids, the operator has changed
        # one of those fields between runs (deliberately or via config
        # drift) — α.1's cache will miss on both, neutering variance
        # compression. Compare paired-run logs to confirm continuity.
        # Emit ONCE per run (gated via strategy_cache flag) — the scope_id
        # is invariant across bars by design, so per-bar emission would
        # just inflate the log without adding info (per bug-sweep agent
        # log-volume recommendation #2).
        if (
            not historical_lookback_mode
            and isinstance(strategy_cache, dict)
            and not strategy_cache.get("_sentiment_cache_scope_audit_emitted")
        ):
            _log(
                f"sentiment cache scope: id={sentiment_cache_scope_id} "
                f"provider={sentiment_cache_scope_doc.get('provider')} "
                f"model={sentiment_cache_scope_doc.get('model')} "
                f"prompt_v={sentiment_cache_scope_doc.get('prompt_version')} "
                f"salt='{sentiment_cache_scope_doc.get('sentiment_cache_scope_salt')}' "
                f"(stable across paired re-runs unless config changed)",
                "cyan",
            )
            strategy_cache["_sentiment_cache_scope_audit_emitted"] = True
        # BT136708 calibration (2026-05-18, P1.1): pre-seed _yf_market_cap_cache
        # so the Tier-3 conviction-tier resolver can return HIGH for mega-caps
        # in backtest. Without this, the cache is empty against a static
        # universe (no fresh discovery runs), and SNDK-class mega-caps default
        # to LOW conviction. Skip during the historical_lookback_mode pre-pass
        # — only seed for actual runs.
        # Phase γ.1 (2026-05-18, BT232179 follow-up): also pass
        # `portfolio_emulator` so the pre-seed pulls currently-held tickers
        # AND top-N BFQ candidates into the universe. Without this, pure-
        # discovery mode (empty symbols_list) silently no-op'd the whole
        # pre-seed and A1 ran the run with an empty mcap cache (BT232179
        # mcap pre-seed: 0/0 populated for 49/49 bars). Idempotency is now
        # a per-ticker set rather than a whole-call bool so newly-held or
        # newly-BFQ'd tickers in subsequent bars get seeded too.
        if isinstance(strategy_cache, dict) and not historical_lookback_mode:
            try:
                _pit_preseed_kwargs = {}
                if point_in_time_context is not None:
                    _pit_preseed_kwargs = {
                        "context": point_in_time_context,
                        "fundamentals_store": point_in_time_store,
                    }
                _preseed_mcap_cache_from_universe(
                    symbols_list,
                    strategy_cache,
                    config,
                    portfolio_emulator=portfolio_emulator,
                    **_pit_preseed_kwargs,
                )
            except Exception as _ps_exc:
                from point_in_time_data import PointInTimeDataError

                if isinstance(_ps_exc, PointInTimeDataError):
                    raise
                _log(f"mcap pre-seed error (non-fatal): {_ps_exc}", "yellow")
        # Position sizing: fraction of portfolio assigned to nexus stock buys / ETF buys
        nexus_portfolio_pct = float(config.get("nexus_portfolio_pct", 0.90))
        etf_portfolio_pct = float(config.get("etf_portfolio_pct", 0.10))
        # Backfill queue config
        _bfq_enabled = bool(config.get("backfill_queue_enabled", True))
        # Tier-3 B5: queue size 30 → 50 so propagation + momentum candidates
        # can both wait without flushing each other.
        _bfq_max_size = int(config.get("backfill_queue_max_size", 50))
        # 2026-05-07 granularity-scaling: BFQ TTL is the headline regression
        # site for the 1200s-vs-3600s divergence. At 3600s a 10-bar TTL
        # gives a queued buy ~10 trading hours to find a slot; at 1200s the
        # same 10 bars is only ~3.3 hours, well below V28 leader-lock
        # rotation latency. Scale the configured value (and the literal
        # priority floor of 15) to preserve wall-clock semantics.
        # Z4.3: backstop TTL minimums so dual-cadence collapse doesn't kill
        # the queue. At 1200s granularity _scale_bars(10) was returning ~2
        # bars in backtest 299903, expiring 20 queued names per bar. Floor
        # the regular TTL at 5 bars and the priority TTL at 10 bars so
        # high-conviction items get a real chance to fill before aging out.
        _bfq_max_bars = max(5, _scale_bars(int(config.get("backfill_queue_max_bars", 10)), config))
        _bfq_reserved_priority_slots = int(config.get("backfill_queue_reserved_priority_slots", 10) or 10)
        _bfq_min_displace_delta = float(config.get("backfill_queue_min_displacement_delta", 0.3))
        _bfq_recurrence_bonus = float(config.get("backfill_queue_recurrence_bonus", 0.1))
        # BT136708 calibration (2026-05-18): MU expired from BFQ at bar 11 of
        # 10 (priority TTL floor was 10 daily bars). Raised the floor to 15
        # via backfill_queue_priority_max_bars_floor so MU-class mega-caps get
        # a real chance to fill before aging out of the queue.
        _bfq_priority_max_bars_floor = int(config.get("backfill_queue_priority_max_bars_floor", 15) or 15)
        _bfq_priority_max_bars = max(_bfq_max_bars, max(_bfq_priority_max_bars_floor, _scale_bars(15, config)))
        _bfq_min_score = float(config.get("backfill_queue_min_score", 0.20))
        _bfq_staleness_pct = float(config.get("backfill_queue_staleness_pct", 20.0))

        # ── 1) Fetch news for the date ────────────────────────────────────
        try:
            if current_time is None:
                today = datetime.utcnow().date()
            elif isinstance(current_time, datetime):
                today = current_time.date()
            elif hasattr(current_time, "year") and hasattr(current_time, "month") and hasattr(current_time, "strftime"):
                today = current_time
            else:
                today = datetime.utcnow().date()
        except Exception:
            today = datetime.utcnow().date()
        date_key = today.strftime("%Y-%m-%d")
        _run_once_started = perf_counter()
        start_dt = datetime(today.year, today.month, today.day, 0, 0, 0)
        # Bound end by current_time to prevent forward-looking data leakage in intraday backtests.
        # For daily bars (time_increment >= 86400), the bar represents end-of-day, so all articles
        # published that day are available — use full-day window plus prior evening (after-hours news).
        _is_daily = time_increment is not None and int(time_increment) >= 86400
        if isinstance(current_time, datetime) and not _is_daily:
            end_dt = current_time
        else:
            end_dt = start_dt + timedelta(days=1)
        if _is_daily:
            # Extend fetch window back 12h to capture prior evening/overnight articles
            start_dt = start_dt - timedelta(hours=12)
        try:
            from pathlib import Path as _NexusVersionPath
            _NEXUS_VERSION = (
                (_NexusVersionPath(__file__).parent / "_nexus_version.txt")
                .read_text(encoding="utf-8")
                .strip()
                or "V28.9-LOSING-TRIM-CONVERT"
            )
        except Exception:
            _NEXUS_VERSION = "V28.9-LOSING-TRIM-CONVERT"
        _log(
            f"Run once | {_NEXUS_VERSION} | date={date_key} | symbols={len(symbols_list)} | lookback={'YES' if historical_lookback_mode else 'NO'} | min_articles={min_articles} | use_llm={use_llm}",
            "cyan",
        )

        # ── EXPLICIT MODE DISPATCH (commit 2 of scheduler refactor) ──────
        # When broker calls run_once with mode={FULL,MONITOR,IDLE}, bypass
        # the legacy dual-cadence gate below. The broker computes mode via
        # backend.scheduler.get_next_wake. mode=None preserves legacy
        # behavior — the gate below decides FULL/MONITOR/IDLE itself.
        # The legacy gate will be deleted in commit 5 once the broker is
        # the only caller. Backtests and the per-symbol shim never pass
        # mode → they continue running the FULL pipeline as before.
        if mode == "IDLE":
            # Strategy is idle (broker between slots, post-session, weekend, etc).
            # Throttle the log: emit once every ~60 IDLE ticks per session.
            if isinstance(strategy_cache, dict):
                # 2026-05-07 backtest perf: stamp tick mode so broker can
                # skip post-tick work on idle ticks (no equity change).
                strategy_cache["_nexus_last_tick_mode"] = "IDLE"
                _idle_n = int(strategy_cache.get("_nexus_idle_tick_count", 0)) + 1
                strategy_cache["_nexus_idle_tick_count"] = _idle_n
                if _idle_n == 1 or _idle_n % 60 == 0:
                    _log(f"Idle tick (broker mode=IDLE) | n={_idle_n} | date={date_key}", "cyan")
            return {}
        if mode == "MONITOR":
            # Stash instance_id on config so monitor's dedup key uses the
            # stable runtime ID (same pattern as the legacy gate at 16292).
            if isinstance(config, dict) and not config.get("runtime_instance_id"):
                try:
                    config["runtime_instance_id"] = str(instance_id)
                except Exception:
                    pass
            return self._run_monitor_cycle(
                symbols_list=symbols_list,
                prices=prices,
                price_history=data,
                config=config,
                portfolio_emulator=portfolio_emulator,
                strategy_cache=strategy_cache,
                date_key=date_key,
                current_time=current_time,
            )
        # mode in (None, "FULL"): fall through to the FULL pipeline. The
        # legacy gate below only runs when mode is None (backtest / shim
        # path). When mode == "FULL", we skip the gate entirely so the
        # broker has authoritative scheduling control.

        # ── DUAL-CADENCE GATE (legacy — runs only when mode is None) ─────
        # Live-mode-only optimization: run the heavy LLM/Neo4j pipeline once
        # at-or-after 9:30 ET, then hourly risk-only monitor cycles for the
        # rest of the trading day. Backtest path is byte-identical when
        # _GN_LIVE_MODE_FLAG=False or historical_lookback_mode=True. See
        # docs/superpowers/specs/2026-05-01-nexus-dual-cadence-design.md.
        # The optional `nexus_dual_cadence_backtest_simulation` flag opts a
        # backtest into the same gate (BEHAVIOR validation harness only — NOT
        # a P&L A/B vs the daily-cadence baseline). See
        # docs/superpowers/specs/2026-05-02-nexus-dual-cadence-backtest-harness-design.md.
        if config.get("nexus_dual_cadence_backtest_simulation") and not config.get("nexus_dual_cadence_enabled", True):
            raise ValueError(
                "nexus_dual_cadence_backtest_simulation=True requires nexus_dual_cadence_enabled=True. "
                "Without it, the full pipeline would fire on every hourly tick (7x LLM cost, "
                "corrupted outcomes table, meaningless harness run)."
            )
        _dual_cadence_active = (
            mode is None  # broker-driven mode bypasses the gate entirely
            and (_GN_LIVE_MODE_FLAG or bool(config.get("nexus_dual_cadence_backtest_simulation", False)))
            and not historical_lookback_mode
            and bool(config.get("nexus_dual_cadence_enabled", True))
        )
        _past_open_today = False
        _today_ny = ""
        # 2026-05-06: removed hard sub-hourly guard. Dual-cadence is
        # gated by `_nexus_full_cycle_completed_date` (once per PT-date),
        # so any tick frequency is safe — full cycle still fires only
        # once per day even with 60-second ticks. Monitor cycles are
        # ~1ms each so RethinkDB peak-HWM writes are tiny. Keep a sanity
        # floor at 30s only to prevent pathological 1-second ticks from
        # piling persistence work.
        try:
            _ti_seconds = int(time_increment or 0)
        except (TypeError, ValueError):
            _ti_seconds = 0
        if _dual_cadence_active and _ti_seconds and _ti_seconds < 30:
            if isinstance(strategy_cache, dict) and not strategy_cache.get(
                "_nexus_dual_cadence_warned_subhour"
            ):
                _log(
                    f"Dual-cadence requires time_increment>=30s (got "
                    f"{_ti_seconds}); running full cycle every tick instead.",
                    "yellow",
                )
                strategy_cache["_nexus_dual_cadence_warned_subhour"] = True
            _dual_cadence_active = False
        # Daily (or coarser) granularity already runs once per bar — the
        # whole point of the dual-cadence gate (prevent multiple FULL
        # cycles per day at sub-hourly ticks) doesn't apply. At 86400s,
        # ``current_time`` typically lands at exactly close_pt (e.g.
        # 17:00 PT), which trips the post-session ``>=`` check on every
        # bar and silently skips every day of the backtest. Bypass the
        # gate so the strategy actually runs.
        if _dual_cadence_active and _ti_seconds and _ti_seconds > 3600:
            if isinstance(strategy_cache, dict) and not strategy_cache.get(
                "_nexus_dual_cadence_warned_daily"
            ):
                _log(
                    f"Dual-cadence gate disabled at granularity {_ti_seconds}s "
                    f"(> 3600s) — runs once per bar already; session windowing "
                    f"would skip every bar that lands at/after close_pt.",
                    "yellow",
                )
                strategy_cache["_nexus_dual_cadence_warned_daily"] = True
            _dual_cadence_active = False

        if _dual_cadence_active:
            try:
                from datetime import timezone as _tz_dc
                from zoneinfo import ZoneInfo as _ZI_dc
                _now_utc_dc = current_time
                if not hasattr(_now_utc_dc, "astimezone"):
                    # Naive fallback — treat current as utcnow.
                    _now_utc_dc = datetime.now(_tz_dc.utc)
                if _now_utc_dc.tzinfo is None:
                    _now_utc_dc = _now_utc_dc.replace(tzinfo=_tz_dc.utc)
                # 2026-05-05: dual-cadence session anchored to Pacific time
                # (5am-5pm PT) so it covers pre-market (5am PT = 8am ET) AND
                # after-hours (through 5pm PT = 8pm ET). Date marker also
                # uses PT so cycle completion rolls over at midnight PT, not
                # midnight ET — matches operator timezone. Hours configurable
                # via nexus_dual_cadence_open_hour_pt / _close_hour_pt; tz
                # configurable via nexus_dual_cadence_session_tz (defaults
                # America/Los_Angeles which handles PDT/PST automatically).
                _dc_tz_name = str(
                    config.get("nexus_dual_cadence_session_tz")
                    or "America/Los_Angeles"
                )
                _dc_open_hour = int(config.get("nexus_dual_cadence_open_hour_pt", 5))
                _dc_close_hour = int(config.get("nexus_dual_cadence_close_hour_pt", 17))
                # 2026-05-06: full-cycle anchor in MINUTES of day (PT) so
                # market-open at 6:30 AM PT (= 390 mins) is supported.
                # Pre-market 5:00-6:29 AM PT runs MONITOR; 6:30 AM PT is
                # the FULL cycle (once per day per _full_done_date marker).
                _dc_full_min = int(config.get("nexus_dual_cadence_full_cycle_minute_of_day_pt", 390))
                _dc_zone = _ZI_dc(_dc_tz_name)
                _now_et = _now_utc_dc.astimezone(_dc_zone)
                _today_ny = _now_et.strftime("%Y-%m-%d")
                _session_open = _now_et.replace(
                    hour=_dc_open_hour, minute=0, second=0, microsecond=0
                )
                _session_close = _now_et.replace(
                    hour=_dc_close_hour, minute=0, second=0, microsecond=0
                )
                # Config validation: full_min must lie within [open*60, close*60).
                # Operator misconfiguration would silently collapse the
                # pre-market window or skip FULL entirely. Clamp + warn.
                _open_min = _dc_open_hour * 60
                _close_min = _dc_close_hour * 60
                if _dc_full_min < _open_min or _dc_full_min >= _close_min:
                    if isinstance(strategy_cache, dict) and not strategy_cache.get(
                        "_nexus_dual_cadence_warned_invalid_full_min"
                    ):
                        _log(
                            f"Dual-cadence config warning: full_cycle_minute_of_day_pt="
                            f"{_dc_full_min} outside [open*60={_open_min}, "
                            f"close*60={_close_min}); clamping to {max(_open_min, min(_close_min - 1, _dc_full_min))}",
                            "yellow",
                        )
                        strategy_cache["_nexus_dual_cadence_warned_invalid_full_min"] = True
                    _dc_full_min = max(_open_min, min(_close_min - 1, _dc_full_min))
                _full_anchor = _now_et.replace(
                    hour=(_dc_full_min // 60),
                    minute=(_dc_full_min % 60),
                    second=0, microsecond=0,
                )
                _past_open_today = _now_et >= _session_open
                _past_full_anchor = _now_et >= _full_anchor
                _within_session_today = _past_open_today and _now_et < _session_close
                _full_done_date = (
                    (strategy_cache or {}).get("_nexus_full_cycle_completed_date")
                )

                # Prune yesterday's pre/post-session log markers to bound
                # memory across multi-day strategy lifetimes.
                if isinstance(strategy_cache, dict):
                    try:
                        _stale_prefixes = (
                            "_nexus_pre_session_logged_",
                            "_nexus_post_session_logged_",
                        )
                        _to_prune = [
                            k for k in list(strategy_cache.keys())
                            if isinstance(k, str)
                            and any(k.startswith(p) for p in _stale_prefixes)
                            and not k.endswith(_today_ny)
                        ]
                        for _k in _to_prune:
                            strategy_cache.pop(_k, None)
                    except Exception:
                        pass

                if not _past_open_today:
                    # Pre-session: log ONCE per PT date so operators see
                    # which mode the gate took. Heartbeats live in the
                    # broker (snapshot worker), not here — the strategy
                    # only emits a single status line per state transition.
                    _pre_log_key = f"_nexus_pre_session_logged_{_today_ny}"
                    if not (strategy_cache or {}).get(_pre_log_key):
                        _mins_until = max(0, int((_session_open - _now_et).total_seconds() // 60))
                        _log(
                            f"Dual-cadence pre-session: now_pt={_now_et.strftime('%H:%M %Z')} "
                            f"< open_pt={_session_open.strftime('%H:%M %Z')} "
                            f"({_mins_until}m until open) — strategy idle until session open",
                            "cyan",
                        )
                        if isinstance(strategy_cache, dict):
                            strategy_cache[_pre_log_key] = True
                    return {}

                if _now_et >= _session_close:
                    # Post-session: log ONCE per PT date. Heartbeat lives
                    # in broker snapshot worker. Don't fire monitor OR
                    # full cycle late in the day even if today's full
                    # cycle never ran — operator can re-run manually
                    # tomorrow. Avoids heavy LLM work at e.g. 8pm PT.
                    _post_log_key = f"_nexus_post_session_logged_{_today_ny}"
                    if not (strategy_cache or {}).get(_post_log_key):
                        _log(
                            f"Dual-cadence post-session: now_pt={_now_et.strftime('%H:%M %Z')} "
                            f">= close_pt={_session_close.strftime('%H:%M %Z')} "
                            f"— strategy idle until next session open",
                            "cyan",
                        )
                        if isinstance(strategy_cache, dict):
                            strategy_cache[_post_log_key] = True
                    return {}

                # 2026-05-06: pre-market window (open <= now < full_anchor)
                # always runs MONITOR — gives risk evaluation on held
                # positions before market open without paying for the
                # heavy FULL pipeline. FULL only runs at/after market open
                # (6:30 AM PT default) when today's full hasn't completed.
                if _past_open_today and not _past_full_anchor:
                    if isinstance(config, dict) and not config.get("runtime_instance_id"):
                        try:
                            config["runtime_instance_id"] = str(instance_id)
                        except Exception:
                            pass
                    return self._run_monitor_cycle(
                        symbols_list=symbols_list,
                        prices=prices,
                        price_history=data,
                        config=config,
                        portfolio_emulator=portfolio_emulator,
                        strategy_cache=strategy_cache,
                        date_key=date_key,
                        current_time=current_time,
                    )

                if _full_done_date == _today_ny:
                    # MONITOR mode — skip the alert block (alert already fired
                    # on today's full-cycle tick).
                    # Stash instance_id on config so monitor's dedup key
                    # uses the stable runtime ID (not the unstable id(self)).
                    if isinstance(config, dict) and not config.get("runtime_instance_id"):
                        try:
                            config["runtime_instance_id"] = str(instance_id)
                        except Exception:
                            pass
                    return self._run_monitor_cycle(
                        symbols_list=symbols_list,
                        prices=prices,
                        price_history=data,
                        config=config,
                        portfolio_emulator=portfolio_emulator,
                        strategy_cache=strategy_cache,
                        date_key=date_key,
                        current_time=current_time,
                    )
                # Else: FULL mode — fall through to existing pipeline.
            except Exception as _dc_exc:
                _log(
                    f"Dual-cadence gate ERROR (falling through to full cycle): "
                    f"{type(_dc_exc).__name__}: {str(_dc_exc)[:200]}",
                    "yellow",
                )

        # 2026-05-07 backtest perf: stamp FULL once we've committed to the
        # heavy pipeline (after both the broker-driven mode=="FULL" branch
        # and the legacy dual-cadence gate's fall-through path).
        if isinstance(strategy_cache, dict):
            try:
                strategy_cache["_nexus_last_tick_mode"] = "FULL"
            except Exception:
                pass

        # 2026-04-30 v2 Task H: Discord alert on strategy start, deduped
        # per (instance, strategy, NY-date). Without dedup, a 1-min
        # tick instance fires ~390 alerts/day.
        # 2026-05-01: variable renamed from _today_ny to _alert_today_ny
        # to avoid clobbering the dual-cadence gate's _today_ny (set above
        # at line ~16035), which feeds the cycle-completed marker write.
        if _GN_LIVE_MODE_FLAG:
            try:
                _alert_today_ny = None
                try:
                    from datetime import timezone as _tz
                    from zoneinfo import ZoneInfo
                    _alert_today_ny = datetime.now(_tz.utc).astimezone(
                        ZoneInfo("America/New_York")
                    ).strftime("%Y-%m-%d")
                except Exception:
                    _alert_today_ny = str(date_key)
                _last_alerted = (strategy_cache or {}).get("_strategy_start_alert_date")
                if _last_alerted != _alert_today_ny:
                    from live_alerts import alert_strategy_start as _ass
                    _held_count = 0
                    if portfolio_emulator is not None:
                        try:
                            _held_count = sum(
                                1 for v in (portfolio_emulator.get_positions() or {}).values()
                                if float(v or 0) > 0
                            )
                        except Exception:
                            _held_count = 0
                    _eq = 0.0
                    try:
                        if portfolio_emulator is not None:
                            _eq = float(portfolio_emulator.get_portfolio_value(prices) or 0.0)
                    except Exception:
                        _eq = 0.0
                    _ass(
                        instance_id=str(instance_id),
                        strategy_name=str(self.__class__.__name__),
                        date_key=str(_alert_today_ny),
                        symbols_count=len(symbols or []),
                        held_count=_held_count,
                        equity=_eq,
                    )
                    if isinstance(strategy_cache, dict):
                        strategy_cache["_strategy_start_alert_date"] = _alert_today_ny
            except Exception as _ass_exc:
                _log(f"alert_strategy_start failed: {_ass_exc}", "yellow")

        # ── V27 (Approach D): Discovery Snapshot Bridge — bootstrap ──────────
        # On the first bar of a fresh scope, if our DISCOVERED_TABLE is empty,
        # try to import the most recent prior scope's discoveries (filtered
        # by per-bucket fingerprint match). This bridges scope changes that
        # only touched LLM/trading config without invalidating the underlying
        # data discoveries (Benzinga, momentum, graph). Fires at most ONCE per
        # run via a strategy_cache flag.
        _bootstrap_attempted_flag = "_nexus_discovery_bootstrap_attempted"
        if (
            bool(config.get("nexus_discovery_bootstrap_enabled", True))
            and strategy_cache is not None
            and not strategy_cache.get(_bootstrap_attempted_flag)
            and base_instance_id
            and instance_id
        ):
            _bootstrap_conn = _get_nexus_db_conn()
            if _bootstrap_conn is not None:
                try:
                    _current_fps = _compute_discovery_fingerprints(config)
                    _max_age = int(
                        config.get("nexus_discovery_snapshot_max_age_days", 90) or 90
                    )
                    _min_keep = float(
                        config.get("nexus_discovery_bootstrap_min_keep_pct", 0.30) or 0.30
                    )
                    # V27.1: merge_mode lets bootstrap fill in missing tickers
                    # when the current scope is non-empty (e.g., a prior run
                    # of the same scope built a stale list missing the names
                    # we want). Off by default for safety; enable when you
                    # want existing scopes to also benefit from snapshot data.
                    _merge_mode = bool(
                        config.get("nexus_discovery_bootstrap_merge_mode", False)
                    )
                    _bootstrap_result = _bootstrap_discoveries_from_snapshot(
                        _bootstrap_conn,
                        current_instance_id=instance_id,
                        base_instance_id=base_instance_id,
                        current_scope_id=history_scope_id,
                        current_fingerprints=_current_fps,
                        run_start_date_key=date_key,
                        max_age_days=_max_age,
                        min_keep_pct=_min_keep,
                        merge_mode=_merge_mode,
                    )
                    strategy_cache[_bootstrap_attempted_flag] = True
                    strategy_cache["_nexus_discovery_bootstrap_imported"] = (
                        max(0, int(_bootstrap_result)) if _bootstrap_result is not None else 0
                    )
                except Exception as _bs_exc:
                    _log(f"Discovery bootstrap WARN: {type(_bs_exc).__name__}: {str(_bs_exc)[:200]}", "yellow")
                    strategy_cache[_bootstrap_attempted_flag] = True
                finally:
                    try:
                        _bootstrap_conn.close()
                    except Exception:
                        pass

        # 2026-05-07 strategy bug-sweep: prune stale propagation discoveries
        # (default 30d TTL). Production audit found 49 of 60 active discoveries
        # dated Nov-2025 — the graph kept re-recommending 6-month-old picks
        # (XNDU, SNDK, BCE, ROKU, BBGI). Without TTL the discovery list never
        # refreshes.
        #
        # Gated by a per-day cache marker (`_nexus_propagation_pruned_for`) so
        # the prune fires once per PT-date, not just on the bootstrap path
        # (which is gated by `_bootstrap_attempted_flag` — fires only once per
        # process lifetime). On day 31 of an uninterrupted process the
        # newly-stale rows must still be pruned.
        #
        # Live mode + dual-cadence backtest harness both prune; pure historical
        # backtests skip (must keep stable seed data for reproducibility).
        _prop_ttl_active = (
            _GN_LIVE_MODE_FLAG
            or bool(config.get("nexus_dual_cadence_backtest_simulation", False))
        )
        _prop_pruned_marker = "_nexus_propagation_pruned_for"
        if (
            _prop_ttl_active
            and isinstance(strategy_cache, dict)
            and strategy_cache.get(_prop_pruned_marker) != date_key
            and base_instance_id
            and instance_id
        ):
            _prune_conn = _get_nexus_db_conn()
            if _prune_conn is not None:
                try:
                    try:
                        _prop_max_age = int(config.get(
                            "propagation_discovery_max_age_days", 30
                        ))
                    except (TypeError, ValueError):
                        _prop_max_age = 30
                    _pruned_n = _prune_stale_propagation_discoveries(
                        _prune_conn, instance_id, date_key,
                        max_age_days=_prop_max_age,
                    )
                    strategy_cache[_prop_pruned_marker] = date_key
                    strategy_cache["_nexus_propagation_pruned_count"] = int(_pruned_n)
                except Exception as _prune_exc:
                    _log(
                        f"Propagation TTL prune WARN: "
                        f"{type(_prune_exc).__name__}: {_prune_exc}",
                        "yellow",
                    )
                finally:
                    try:
                        _prune_conn.close()
                    except Exception:
                        pass
        _effective_cfg = _get_effective_nexus_config(config)
        _log(
            "Effective config | "
            f"ts={_effective_cfg['trailing_stop_pct']:.1f}/{_effective_cfg['trailing_stop_commodity_etf_pct']:.1f}/{_effective_cfg['trailing_stop_sector_etf_pct']:.1f} "
            f"| pools={_effective_cfg['pool_a_base']}/{_effective_cfg['pool_b_base']} mins={_effective_cfg['pool_a_min']}/{_effective_cfg['pool_b_min']} "
            f"| max_buys={_effective_cfg['max_stock_buys_per_day']} max_disc={_effective_cfg['max_discovered_stocks']} "
            f"| quality=avgvol>={_effective_cfg['min_avg_volume']:.0f} "
            f"mcap>=${_effective_cfg['min_market_cap']/1e6:.0f}M({ _effective_cfg['quality_market_cap_mode'] }) "
            f"| prop={_effective_cfg['propagation_min_paths']}p/{_effective_cfg['propagation_min_raw_score']:.2f} "
            f"| sell={_effective_cfg['sell_enforcement_min_hold_days']}d/{_effective_cfg['sell_enforcement_hysteresis_threshold']:.2f}/{_effective_cfg['sell_enforcement_consecutive_neutral_days']}d "
            f"| bfq={_effective_cfg['backfill_budget_reserve_pct']:.0%}/{_effective_cfg['backfill_queue_grace_bars']}g/{_effective_cfg['backfill_queue_priority_grace_bars']}pg "
            f"q={_effective_cfg['backfill_queue_max_size']}/{_effective_cfg['backfill_queue_reserved_priority_slots']} "
            f"displace={_effective_cfg.get('backfill_queue_min_displacement_delta', 0.3):.1f}/rec={_effective_cfg.get('backfill_queue_recurrence_bonus', 0.1):.1f} "
            f"halt={_effective_cfg['portfolio_drawdown_halt_pct']:.1f}%/{_effective_cfg['portfolio_drawdown_resume_up_days']}d "
            f"| rot={_effective_cfg['rotation_min_hold_days']}d/{_effective_cfg['rotation_profitable_full_exit_min_hold_days']}d/"
            f"{_effective_cfg['rotation_profitable_min_incoming_raw_score']:.2f}/{_effective_cfg['rotation_profitable_min_delta']:.2f} "
            f"| lock={str(_effective_cfg['rotation_winner_lock_enabled']).lower()}/"
            f"{_effective_cfg['rotation_winner_lock_min_hold_days']}d/{_effective_cfg['rotation_winner_lock_min_pnl_pct']:.1f}%/"
            f"{_effective_cfg['rotation_winner_lock_min_raw_score']:.2f}/{_effective_cfg['rotation_winner_lock_max_peak_drawdown_pct']:.1f}% "
            f"| break={_effective_cfg['rotation_break_glass_raw_score']:.2f}/{_effective_cfg['rotation_break_glass_delta']:.2f}/"
            f"{_effective_cfg['rotation_break_glass_sell_fraction']:.0%} "
            f"| discover=watch:{_effective_cfg['sector_watchlist_reserved_slots']}/{_effective_cfg['sector_watchlist_max_per_sector']} "
            f"peers:{_effective_cfg['max_sector_peer_discoveries_per_day']} comp:{_effective_cfg['max_competitor_discoveries_per_day']} "
            f"mom:{_effective_cfg['momentum_discovery_max_per_day']} fill:{_effective_cfg['sector_fill_max_per_sector']} prop_slots:{_effective_cfg['max_propagated_scoring_slots']} seedcap:{_effective_cfg['propagation_max_per_seed']} "
            f"| prio=watch:{_effective_cfg['watchlist_priority_slots']}@{_effective_cfg['watchlist_priority_min_raw_score']:.2f} "
            f"prop:{_effective_cfg['propagation_expansion_reserved_slots']}@{_effective_cfg['propagation_expansion_min_raw_score']:.2f} "
            f"prot={_effective_cfg['watchlist_sector_protected_slots']} min=${_effective_cfg['priority_min_position_size']:.0f}/{str(_effective_cfg['priority_budget_can_bypass_regular_min']).lower()} "
            f"| alloc={_effective_cfg['allocation_profile']}/{_effective_cfg['allocation_max_new_stock_buys']}@"
            f"{_effective_cfg['allocation_execute_min_raw_score']:.2f}/{_effective_cfg['allocation_top2_min_raw_score']:.2f} "
            f"| winner_add={str(_effective_cfg['winner_add_enabled']).lower()}/"
            f"{_effective_cfg['winner_add_min_hold_days']}d/{_effective_cfg['winner_add_min_pnl_pct']:.1f}%/"
            f"{_effective_cfg['winner_add_min_raw_score']:.2f}/{_effective_cfg['winner_add_max_drawdown_from_peak_pct']:.1f}%/"
            f"{_effective_cfg['winner_add_fraction_of_initial']:.0%}x{_effective_cfg['winner_add_max_count']} "
            f"| sent={_effective_cfg['sentiment_llm_requested_articles']}"
            f"{('→' + str(_effective_cfg['sentiment_llm_max_articles'])) if _effective_cfg['sentiment_llm_max_articles'] != _effective_cfg['sentiment_llm_requested_articles'] else ''}"
            f"{'*' if _effective_cfg['sentiment_prompt_auto_reduced'] else ''} "
            f"| events={_effective_cfg['max_events_in_prompt']}/{_effective_cfg['event_maintenance_candidate_batch_size']}"
            f"{'*' if _effective_cfg['event_maintenance_prompt_auto_reduced'] else ''} "
            f"| bz_lookahead={_effective_cfg['benzinga_lookahead_days']} "
            f"| watchlist={','.join(_effective_cfg['sector_watchlist_keys']) if _effective_cfg['sector_watchlist_keys'] else 'none'}",
            "cyan",
        )
        if history_scope_id:
            _log(
                f"History scope: base_instance_id={base_instance_id} | scoped_instance_id={instance_id} | scope={history_scope_id[:12]}...",
                "cyan",
            )

        # ── Backtest session cleanup: clear instance-scoped data on first run ──
        # Prevents bleed-over from previous backtests on the same instance.
        # Shared caches (articles, sentiment, LLM classifications, overlay bars) are preserved.
        # Uses module-level _NEXUS_BACKTEST_CLEANED_INSTANCES to prevent double-fire:
        # broker.py uses temp_strategy_caches for lookback and _strategy_cache for main run,
        # so a strategy_cache-based flag gets lost between the two phases.
        if strategy_cache is not None and instance_id not in _NEXUS_BACKTEST_CLEANED_INSTANCES:
            # V17b fix: Check DB marker before running cleanup (survives container restarts).
            # The module-level set _NEXUS_BACKTEST_CLEANED_INSTANCES resets when the process
            # restarts, causing lookback data (11,423 rows built over ~2 hours) to be wiped.
            # This DB-backed check prevents that while still re-cleaning on config changes.
            _cleanup_needed = True
            # V18c: Compute a trading-config hash separate from the LLM scope hash.
            # The LLM scope hash (history_scope_id) controls lookback data identity.
            # The trading hash controls whether post-lookback live data is stale.
            # This way: changing LLM models → full rebuild; changing thresholds → selective cleanup only.
            _trading_config_keys = [
                ("buy_threshold", config.get("buy_threshold", 0.15)),
                ("fast_loser_cut_pct", config.get("fast_loser_cut_pct", -10.0)),
                ("max_positions", config.get("max_positions", 50)),
                ("allocation_profile", str(config.get("allocation_profile", "balanced")).strip().lower()),
                ("sell_enforcement_min_hold_days", config.get("sell_enforcement_min_hold_days", 5)),
                ("trailing_stop_pct", config.get("trailing_stop_pct", 8.0)),
                ("momentum_rediscovery_enabled", config.get("momentum_rediscovery_enabled", True)),
                ("momentum_amplifier_enabled", config.get("momentum_amplifier_enabled", True)),
            ]
            _trading_hash = hashlib.sha256(json.dumps(_trading_config_keys, sort_keys=True).encode()).hexdigest()[:16]
            _cleanup_conn = _get_nexus_db_conn()
            if _cleanup_conn and _r:
                try:
                    _ensure_nexus_history_table(_cleanup_conn, LEARNING_CACHE_TABLE)
                    _marker_key = f"cleanup_done|{instance_id}"
                    _marker = _r.db(DB_NAME).table(LEARNING_CACHE_TABLE).get(_marker_key).run(_cleanup_conn)
                    if _marker is not None:
                        _current_hash = str(config.get("history_scope_id") or config.get("strategy_config_hash") or "")
                        _stored_hash = str(_marker.get("config_hash") or "")
                        if not _current_hash or not _stored_hash or _current_hash == _stored_hash:
                            _cleanup_needed = False
                            # Check if trading rules changed (triggers selective cleanup, not full wipe)
                            _stored_trading_hash = str(_marker.get("trading_config_hash") or "")
                            if _stored_trading_hash and _stored_trading_hash != _trading_hash:
                                _log(f"Backtest cleanup: trading rules changed ({_stored_trading_hash[:8]}→{_trading_hash[:8]}), selective post-lookback cleanup will run", "yellow")
                            else:
                                _log("Backtest cleanup: skipped (already cleaned, config unchanged — lookback data preserved)", "cyan")
                            # V18b: On restart with lookback reuse, clear post-lookback data
                            # so live trading starts from the same clean state as a fresh lookback.
                            # Without this, stale trends (27 vs 7), empty event caches (0 vs 23),
                            # and inflated buy signals (67 vs 5) cause wildly different results.
                            if not historical_lookback_mode and date_key:
                                _RESTART_SCOPED_TABLES = [
                                    TRENDS_TABLE,
                                    NEXUS_ACTIVE_EVENTS_TABLE,
                                    NEXUS_ACTIVE_EVENT_HISTORY_TABLE,
                                    NEXUS_ACTIVE_EVENT_MAINTENANCE_TABLE,
                                    OUTCOMES_TABLE,
                                    NEXUS_TRADE_CONTEXTS_TABLE,
                                    NEXUS_TRADE_OUTCOMES_TABLE,
                                    NEXUS_OUTCOME_SERIES_TABLE,
                                ]
                                try:
                                    _restart_tables = list(_r.db(DB_NAME).table_list().run(_cleanup_conn))
                                except Exception:
                                    _restart_tables = []
                                _post_lb_cleared = 0
                                # Codex fix: use table-specific date fields instead of generic date_key.
                                # Trends use start_date, events use start_date/effective_date,
                                # outcomes use observation_date. The generic filter missed all of these.
                                _restart_date_fields = {
                                    TRENDS_TABLE: "start_date",
                                    NEXUS_ACTIVE_EVENTS_TABLE: "start_date",
                                    NEXUS_ACTIVE_EVENT_HISTORY_TABLE: "effective_date",
                                    NEXUS_ACTIVE_EVENT_MAINTENANCE_TABLE: "date_key",
                                    OUTCOMES_TABLE: "date_key",
                                    NEXUS_TRADE_CONTEXTS_TABLE: "date_key",
                                    NEXUS_TRADE_OUTCOMES_TABLE: "date_key",
                                    NEXUS_OUTCOME_SERIES_TABLE: "observation_date",
                                }
                                for _tbl in _RESTART_SCOPED_TABLES:
                                    if _tbl not in _restart_tables:
                                        continue
                                    _date_field = _restart_date_fields.get(_tbl, "date_key")
                                    try:
                                        _del_result = (
                                            _r.db(DB_NAME).table(_tbl)
                                            .filter(lambda doc, _df=_date_field:
                                                (doc["instance_id"] == instance_id)
                                                & (doc.has_fields(_df))
                                                & (doc[_df] >= date_key)
                                            )
                                            .delete()
                                            .run(_cleanup_conn)
                                        )
                                        _post_lb_cleared += int(_del_result.get("deleted", 0))
                                    except Exception:
                                        pass
                                # Codex fix: also delete active discoveries created during prior live trading.
                                # Without this, live-only discoveries (momentum, propagation) contaminate restart.
                                if DISCOVERED_TABLE in _restart_tables:
                                    try:
                                        # Delete discoveries created during live trading (not during lookback)
                                        _del_disc = (
                                            _r.db(DB_NAME).table(DISCOVERED_TABLE)
                                            .filter(lambda doc:
                                                (doc["instance_id"] == instance_id)
                                                & (doc.has_fields("discovered_date"))
                                                & (doc["discovered_date"] >= date_key)
                                            )
                                            .delete()
                                            .run(_cleanup_conn)
                                        )
                                        _post_lb_cleared += int(_del_disc.get("deleted", 0))
                                    except Exception:
                                        pass
                                    try:
                                        # Reset lookback-era stocks that were sold during prior live trading
                                        _r.db(DB_NAME).table(DISCOVERED_TABLE).filter(
                                            lambda doc: (doc["instance_id"] == instance_id)
                                            & ((doc["status"] == "sold") | (doc["status"] == "rediscovery_pending"))
                                            & (doc.has_fields("sold_date"))
                                            & (doc["sold_date"] >= date_key)
                                        ).update({
                                            "status": "active",
                                            "sell_reason": None,
                                            "sold_date": None,
                                            "consecutive_sell_days": 0,
                                        }).run(_cleanup_conn)
                                        # Reset orphaned rediscovery_pending (no sold_date)
                                        _r.db(DB_NAME).table(DISCOVERED_TABLE).filter(
                                            lambda doc: (doc["instance_id"] == instance_id)
                                            & (doc["status"] == "rediscovery_pending")
                                        ).update({"status": "sold"}).run(_cleanup_conn)
                                    except Exception:
                                        pass
                                # Clear learning cache to force fresh learning on first live bar
                                # CRITICAL: exclude the cleanup_done marker (shares same table)
                                # Without this, a second restart would find no marker and wipe all lookback data
                                if LEARNING_CACHE_TABLE in _restart_tables:
                                    try:
                                        _marker_prefix = f"cleanup_done|"
                                        _r.db(DB_NAME).table(LEARNING_CACHE_TABLE).filter(
                                            lambda doc: (doc["instance_id"] == instance_id)
                                            & (~doc["id"].match("^cleanup_done\\\\|"))
                                        ).delete().run(_cleanup_conn)
                                    except Exception:
                                        pass
                                if _post_lb_cleared:
                                    _log(
                                        f"Backtest restart: cleared {_post_lb_cleared} post-lookback rows "
                                        f"(kept < {date_key}, cleared >= {date_key}). Live trading starts fresh.",
                                        "yellow",
                                    )
                                else:
                                    _log("Backtest restart: no post-lookback data to clear — clean start.", "cyan")
                                # Re-write the cleanup_done marker (may have been deleted by learning cache clear)
                                try:
                                    _r.db(DB_NAME).table(LEARNING_CACHE_TABLE).insert({
                                        "id": f"cleanup_done|{instance_id}",
                                        "instance_id": instance_id,
                                        "config_hash": str(config.get("history_scope_id") or config.get("strategy_config_hash") or ""),
                                        "trading_config_hash": _trading_hash,
                                        "cleaned_at": datetime.utcnow().isoformat() + "Z",
                                    }, conflict="replace").run(_cleanup_conn)
                                except Exception:
                                    pass
                        else:
                            _log(f"Backtest cleanup: config hash changed ({_stored_hash[:12]}→{_current_hash[:12]}), re-cleaning", "yellow")
                except Exception:
                    pass  # Table may not exist yet — proceed with cleanup
            if _cleanup_needed and _cleanup_conn and _r:
                # V32 REPRODUCIBILITY FIX: exclude trade-context / outcomes / outcome-series
                # tables from the blanket wipe. They hold the pre-lookback date_keys the
                # broker's `_historic_lookback_resume_dates()` probes to decide whether to
                # reuse the cached 85-day lookback. Wiping them here forces every
                # subsequent backtest to rebuild the lookback from scratch — cascading
                # non-reproducibility (different day-1 events/trends -> different momentum
                # watchlist -> missing winners like SNDK). The date-scoped cleanup at
                # L15759-15805 (restart branch) already handles these tables correctly on
                # warm-start. First-run cold-process still does a safe subset wipe below.
                _INSTANCE_SCOPED_TABLES = [
                    DISCOVERED_TABLE,
                    TRENDS_TABLE,
                    NEXUS_ACTIVE_EVENTS_TABLE,
                    NEXUS_ACTIVE_EVENT_HISTORY_TABLE,
                    NEXUS_ACTIVE_EVENT_MAINTENANCE_TABLE,
                    OUTCOMES_TABLE,
                    LEARNING_CACHE_TABLE,
                    # NEXUS_TRADE_CONTEXTS_TABLE — excluded (lookback resume source)
                    # NEXUS_TRADE_OUTCOMES_TABLE — excluded (outcome history source)
                    # NEXUS_OUTCOME_SERIES_TABLE — excluded (outcome history source)
                ]
                _existing_tables = []
                try:
                    _existing_tables = list(_r.db(DB_NAME).table_list().run(_cleanup_conn))
                except Exception as _tbl_list_exc:
                    _log(f"Backtest cleanup WARN: failed to list tables before cleanup: {_tbl_list_exc}", "yellow")
                _total_cleared = 0
                for _tbl in _INSTANCE_SCOPED_TABLES:
                    if _tbl not in _existing_tables:
                        continue
                    try:
                        result = (
                            _r.db(DB_NAME).table(_tbl)
                            .filter(lambda doc: doc["instance_id"] == instance_id)
                            .delete()
                            .run(_cleanup_conn)
                        )
                        _n = result.get("deleted", 0)
                        if _n:
                            _total_cleared += _n
                    except Exception as _cle:
                        _log(f"Backtest cleanup: error clearing {_tbl}: {_cle}", "yellow")
                if _total_cleared:
                    _log(
                        f"Backtest cleanup: cleared {_total_cleared} rows from instance-scoped tables "
                        f"(instance_id={instance_id}). Shared caches preserved.",
                        "cyan",
                    )
                else:
                    _log("Backtest cleanup: no stale instance data found — clean start.", "cyan")
                # V17b: Store cleanup marker in DB so it survives container restarts
                try:
                    _r.db(DB_NAME).table(LEARNING_CACHE_TABLE).insert({
                        "id": f"cleanup_done|{instance_id}",
                        "instance_id": instance_id,
                        "config_hash": str(config.get("history_scope_id") or config.get("strategy_config_hash") or ""),
                        "trading_config_hash": _trading_hash,
                        "cleaned_at": datetime.utcnow().isoformat() + "Z",
                    }, conflict="replace").run(_cleanup_conn)
                except Exception:
                    pass
            # Mark this instance as cleaned at the module level (survives cache swaps)
            _NEXUS_BACKTEST_CLEANED_INSTANCES.add(instance_id)
            # Also set strategy_cache flag for learning stage resets (only on first clean)
            if not strategy_cache.get("_nexus_backtest_cleaned"):
                strategy_cache["_nexus_backtest_cleaned"] = True
                # Reset learning context so it rebuilds from scratch (cache was just cleared)
                strategy_cache.pop("_nexus_learning_context_built", None)
                strategy_cache.pop("_nexus_learning_context", None)
                strategy_cache.pop("_nexus_learning_last_attempt_date", None)
                strategy_cache.pop("_nexus_learning_context_scope", None)
                strategy_cache.pop("_portfolio_drawdown_state", None)
                strategy_cache.pop("_deployment_last_bar_key", None)
                strategy_cache.pop("_deployment_bar_index", None)
                strategy_cache.pop("_backfill_queue", None)
                strategy_cache.pop("_broker_skipped_buys", None)
                strategy_cache.pop("_nexus_profit_take_state", None)
        elif strategy_cache is not None:
            # Not first run: data from lookback persists (trends, discoveries, outcomes, events)
            if not strategy_cache.get("_nexus_persistence_logged"):
                strategy_cache["_nexus_persistence_logged"] = True
                _persist_conn = _get_nexus_db_conn()
                if _persist_conn and _r:
                    _persist_counts = {}
                    for _tbl_name, _tbl_const in [("trends", TRENDS_TABLE), ("discovered", DISCOVERED_TABLE), ("outcomes", OUTCOMES_TABLE)]:
                        try:
                            _n = _r.db(DB_NAME).table(_tbl_const).filter(
                                lambda doc: doc["instance_id"] == instance_id
                            ).count().run(_persist_conn)
                            _persist_counts[_tbl_name] = _n
                        except Exception as _persist_exc:
                            _log(f"Data persistence WARN: failed to count {_tbl_name} rows: {_persist_exc}", "yellow")
                    if any(_persist_counts.values()):
                        _log(
                            f"Data persistence: {_persist_counts.get('trends', 0)} trends, "
                            f"{_persist_counts.get('discovered', 0)} discovered stocks, "
                            f"{_persist_counts.get('outcomes', 0)} outcomes carried from lookback",
                            "green",
                        )

        # ── Outcome tracking: fill previous run's outcome prices ──────────
        # Uses current prices to measure actual price changes from yesterday's predictions
        if outcome_tracking:
            with _timed_stage("Outcome tracking refresh", start_details=f"prices={len(prices)} | instance_id={instance_id}"):
                _conn_out = _get_nexus_db_conn()
                if _conn_out and (prices or strategy_cache):
                    _ob = strategy_cache.get("_overlay_bars_raw") if strategy_cache else None
                    _fill_outcome_prices(_conn_out, instance_id, date_key, prices, overlay_bars=_ob)
                    _update_indefinite_outcomes(_conn_out, instance_id, date_key, prices, overlay_bars=_ob)

        # 1-C (bug-sweep 2026-05-28): the FIRST time a live run touches a given
        # trading date, bypass any pre-existing article/sentiment cache for that
        # date — it may have been written by a backtest that ended on this date
        # (stale, LLM-skipped). Recompute once; the fresh result is re-cached so
        # later same-day live cycles reuse it (preserving the cost-saving design).
        # Excludes the historical_lookback prepass (it legitimately rebuilds days).
        _live_first_touch = False
        try:
            if (globals().get("_GN_LIVE_MODE_FLAG", False)
                    and not historical_lookback_mode
                    and isinstance(strategy_cache, dict)):
                _refreshed = strategy_cache.setdefault("_live_news_refreshed_dates", [])
                if isinstance(_refreshed, list) and date_key not in _refreshed:
                    _live_first_touch = True
                    _refreshed.append(date_key)
                    if len(_refreshed) > 10:
                        del _refreshed[:-10]
        except Exception:
            _live_first_touch = False
        try:
            _pit_news_kwargs = {}
            if (
                point_in_time_context is not None
                and not point_in_time_context.is_live
            ):
                _pit_news_kwargs["context"] = point_in_time_context
                _pit_news_kwargs["snapshot_store"] = point_in_time_store
            articles, from_cache, cached_sentiment = _fetch_articles_cached(
                date_key, start_dt, end_dt, alpaca_key, alpaca_secret,
                limit=num_articles, min_articles=min_articles,
                sentiment_cache_scope_id=sentiment_cache_scope_id,
                force_fresh=_live_first_touch,
                config=config,
                **_pit_news_kwargs,
            )
        except Exception as e:
            from point_in_time_data import PointInTimeDataError

            if isinstance(e, PointInTimeDataError):
                raise
            _log(f"News fetch error: {e}", "red")
            return {s: 0 for s in symbols_list}
        # Backtest safety: filter out articles published after current_time (catches stale cached full-day fetches).
        # Skip for daily bars — the daily bar represents the full trading day, so all articles are available.
        if isinstance(current_time, datetime) and articles and not _is_daily:
            ct_iso = current_time.strftime("%Y-%m-%dT%H:%M:%SZ")
            pre_filter = len(articles)
            articles = [
                a for a in articles
                if (a.get("created_at") or a.get("published_date") or "") <= ct_iso
            ]
            if len(articles) < pre_filter:
                _log(f"Backtest time filter: removed {pre_filter - len(articles)} articles published after {ct_iso}", "cyan")
        alpaca_article_floor_met = len(articles) >= min_articles
        if not alpaca_article_floor_met:
            _log(
                f"Only {len(articles)} Alpaca articles (min {min_articles}); "
                f"continuing with limited company-news input and Google macro pipeline.",
                "yellow",
            )
        _log(f"News: {len(articles)} articles ({'cached' if from_cache else 'fetched from Alpaca'})", "green")

        # ── Benzinga data sources ─────────────────────────────────────────
        # Set Benzinga backtest mode: data is non-None only in backtest mode
        # (broker passes price_history for backtest, None for live).
        # This bypasses the daily budget counter which otherwise exhausts during backtests.
        try:
            from benzinga_client import set_benzinga_backtest_mode as _bz_set_bt_main
            _bz_set_bt_main(data is not None)
        except ImportError:
            _log("Benzinga WARN: set_benzinga_backtest_mode unavailable; continuing without explicit backtest-mode toggle", "yellow")
        bz_key = (config.get("benzinga_api_key") or "").strip() or os.environ.get("BENZINGA_API_KEY", "").strip()
        bz_data: dict = {}
        _strict_news_history = bool(
            point_in_time_context is not None
            and not _pit_use_legacy_sources(point_in_time_context)
        )
        if bz_key or _strict_news_history:
            bz_data = _fetch_all_benzinga(
                config,
                date_key,
                symbols_list,
                strategy_cache=strategy_cache,
                context=point_in_time_context if _strict_news_history else None,
                snapshot_store=point_in_time_store if _strict_news_history else None,
            )
        else:
            _log("Benzinga: no API key configured (set benzinga_api_key in config or BENZINGA_API_KEY env)", "cyan")

        # Save per-ticker headline history to RethinkDB for LLM context
        conn_hist = _get_nexus_db_conn()
        if conn_hist and articles:
            with _timed_stage("Ticker headline history update", start_details=f"articles={len(articles)}"):
                ticker_headlines = _extract_ticker_headlines(articles)
                if ticker_headlines:
                    _update_ticker_history(conn_hist, ticker_headlines, date_key)

        # When articles were freshly fetched (not from cache), LLM is required
        llm_required = not from_cache
        if llm_required and not llm_key:
            _log("Articles not from cache; LLM sentiment is required but no API key. Skipping.", "red")
            return {s: 0 for s in symbols_list}

        # ── Future trades: clean expired ──────────────────────────────────
        try:
            from future_trades_util import (
                pop_pending_trades, expire_old_trades, schedule_trade,
                get_all_future_trades, cancel_trades,
            )
        except ImportError:
            _log("future_trades_util not available — future trades disabled", "yellow")
            pop_pending_trades = expire_old_trades = schedule_trade = None
            get_all_future_trades = cancel_trades = None
        if strategy_cache and expire_old_trades:
            expire_old_trades(strategy_cache, current_time)

        # ── 1b) Load active market trends from RethinkDB ──────────────────────
        trend_tracking = config.get("trend_tracking_enabled", True)
        stock_finder = config.get("stock_finder_enabled", True)
        etf_allocation = config.get("etf_allocation_enabled", True)
        active_trends = []
        conn_trends = _get_nexus_db_conn()

        # ── Enable prompt-hash caching ──
        # Two toggles:
        #  - nexus_fast_mode: caches across ALL bars (historic + live)
        #  - nexus_lookback_cache_enabled (default True): caches ONLY during
        #    historic lookback bars (the 85-bar warmup) to accelerate backtests
        #    without affecting live-bar behavior.
        _fast_mode = bool(config.get("nexus_fast_mode", False))
        _lookback_cache_enabled = bool(config.get("nexus_lookback_cache_enabled", True))
        # 2026-07-23 backtest determinism: in deterministic backtest mode cache
        # across ALL bars (historic + main) AND route structured calls (learning
        # summary, overlay) through the content-hash cache so paired re-runs are
        # reproducible. Gated: never engages in live (`_GN_LIVE_MODE_FLAG`).
        _det = bool(config.get("nexus_backtest_deterministic", False)) and not _GN_LIVE_MODE_FLAG
        _cache_should_enable = _fast_mode or (_lookback_cache_enabled and historical_lookback_mode) or _det
        if conn_trends is not None:
            configure_llm_prompt_cache(enabled=_cache_should_enable, structured=_det)
            if _cache_should_enable:
                _mode_label = ("deterministic" if _det else
                               "fast_mode" if _fast_mode else "lookback_only")
                _log(f"LLM prompt cache ENABLED ({_mode_label})", "cyan")

        if trend_tracking and conn_trends:
            with _timed_stage("Trend load", start_details=f"instance_id={instance_id}"):
                max_age = int(config.get("trend_max_age_days", 21))
                active_trends = _load_active_trends(
                    conn_trends,
                    instance_id,
                    max_age_days=max_age,
                    date_key=date_key,
                    config=config,
                )
                if active_trends:
                    _log(f"Market trends: {len(active_trends)} active trends loaded", "cyan")

        # ── Build additional LLM context: Benzinga + outcomes + learning ──
        additional_context = ""
        # Benzinga market data context
        if bz_data:
            additional_context += _format_benzinga_context(bz_data, date_key, use_toon=use_toon)
        # Historical outcome patterns for pattern recognition
        if outcome_tracking:
            _conn_out2 = _get_nexus_db_conn()
            if _conn_out2:
                additional_context += _load_outcome_context(
                    _conn_out2, instance_id, limit_days=30, date_key=date_key, use_toon=use_toon,
                )
        # Learning stage: analyze past outcomes into pattern summary (retries daily until enough data)
        if learning_stage_enabled and llm_key:
            from _phase_alpha_helpers import (
                evidence_cache_read_allowed,
                evidence_cache_write_allowed,
            )
            _learning_cache_read_allowed = evidence_cache_read_allowed("learning")
            _learning_cache_write_allowed = evidence_cache_write_allowed("learning")
            learning_ctx = ""
            learning_context_scope = {
                "instance_id": instance_id,
                "base_instance_id": base_instance_id,
                "history_scope_id": history_scope_id,
                "llm_provider": llm_provider,
                "llm_model": llm_model_ref,
                "learning_stage_days": learning_stage_days,
                "learning_refresh_hours": learning_refresh_hours,
            }
            if (
                _learning_cache_read_allowed
                and _learning_cache_write_allowed
                and strategy_cache is not None
                and strategy_cache.get("_nexus_learning_context_scope") != learning_context_scope
            ):
                strategy_cache["_nexus_learning_context_built"] = False
                strategy_cache["_nexus_learning_context"] = ""
                strategy_cache.pop("_nexus_learning_last_attempt_date", None)
            _learning_should_run = not _learning_cache_read_allowed
            if _learning_cache_read_allowed and strategy_cache is not None:
                if strategy_cache.get("_nexus_learning_context_built"):
                    _learning_should_run = False  # already have real content
                elif strategy_cache.get("_nexus_learning_last_attempt_date") == date_key:
                    _learning_should_run = False  # already tried today, skip remaining bars
                else:
                    _learning_should_run = True
            if _learning_should_run:
                try:
                    with _timed_stage(
                        "Learning context build",
                        start_details=f"days={learning_stage_days} | refresh_hours={learning_refresh_hours}",
                    ):
                        _conn_lrn = _get_nexus_db_conn()
                        learning_ctx = _build_learning_context(
                            _conn_lrn, instance_id, date_key,
                            learning_stage_days, learning_refresh_hours,
                            llm_provider, llm_key, llm_model, use_toon=use_toon, provider_config=llm_provider_config,
                            config=config,
                        )
                        if _learning_cache_write_allowed and strategy_cache is not None:
                            strategy_cache["_nexus_learning_context"] = learning_ctx
                            strategy_cache["_nexus_learning_last_attempt_date"] = date_key
                        if learning_ctx:
                            if _learning_cache_write_allowed and strategy_cache is not None:
                                strategy_cache["_nexus_learning_context_built"] = True
                            _log("Learning stage: context built successfully, will use for all subsequent bars", "green")
                        else:
                            _log(f"Learning stage: no usable context yet on {date_key}, will retry next day", "cyan")
                        if _learning_cache_write_allowed and strategy_cache is not None:
                            strategy_cache["_nexus_learning_context_scope"] = learning_context_scope
                except Exception as _learn_err:
                    _raise_model_evidence_error(_learn_err)
                    if _learning_cache_write_allowed and strategy_cache is not None:
                        strategy_cache["_nexus_learning_last_attempt_date"] = date_key
                    _log(f"Learning stage error (will retry next day): {_learn_err}", "yellow")
            if _learning_cache_read_allowed and strategy_cache is not None:
                additional_context += strategy_cache.get("_nexus_learning_context", "")
            else:
                additional_context += learning_ctx

        # ── Phase 2.5: Adversarial Analyst Panel ──────────────────────────────
        analyst_panel_adjustments: dict[str, float] = {}
        _ap_skip_lookback = config.get("analyst_panel_skip_lookback", True)
        if config.get("analyst_panel_enabled", False) and not (config.get("historical_lookback_mode", False) and _ap_skip_lookback):
            _load_analyst_panel()  # Lazy import on first use — avoids circular import at module load time
        if (
            _ANALYST_PANEL_AVAILABLE
            and config.get("analyst_panel_enabled", False)
            and run_analyst_panel is not None
            and not (config.get("historical_lookback_mode", False) and _ap_skip_lookback)
        ):
            try:
                if fill_analyst_panel_outcomes is not None:
                    _ap_conn = _get_nexus_db_conn()
                    if _ap_conn:
                        fill_analyst_panel_outcomes(_ap_conn, instance_id, date_key, prices)
                # Build compact news summary from articles for panel
                _ap_news = "; ".join(
                    f"{a.get('headline', '')[:80]} [{a.get('source', '')}]"
                    for a in (articles or [])[:30]
                    if a.get("headline")
                )[:4000] or "No articles available"
                # V20 fix: Use current-bar sentiment if available, otherwise cached.
                # Codex fix: sentiment_data may not be assigned yet at this point in the
                # pipeline, so check with locals() first.
                _ap_sent = {}
                if "sentiment_data" in locals() and isinstance(sentiment_data, dict) and sentiment_data:
                    _ap_sent = sentiment_data
                else:
                    from _phase_alpha_helpers import evidence_cache_read_allowed
                    _ap_cached_sent = (
                        strategy_cache.get("_last_sentiment_data")
                        if strategy_cache
                        and evidence_cache_read_allowed("sentiment")
                        else None
                    )
                    _ap_sent = _ap_cached_sent if isinstance(_ap_cached_sent, dict) else {}
                _ap_max = int(config.get("analyst_panel_max_stocks", 10))
                _ap_stocks = [
                    {"ticker": t, "score": float((_ap_sent.get(t, {}).get("sentiment") or 0) if isinstance(_ap_sent.get(t), dict) else 0)}
                    for t in (symbols_list or [])[:_ap_max]
                ]
                _ap_result = run_analyst_panel(
                    config=config,
                    news_summary=_ap_news,
                    stock_candidates=_ap_stocks,
                    strategy_cache=strategy_cache,
                    instance_id=instance_id,
                    date_key=date_key,
                    prices=prices,
                )
                if _ap_result and isinstance(_ap_result, tuple) and len(_ap_result) == 2:
                    panel_context, analyst_panel_adjustments = _ap_result
                    if panel_context:
                        additional_context += panel_context
                        _log(f"Analyst Panel: consensus added ({len(panel_context)} chars, {len(analyst_panel_adjustments)} stock adjustments)", "green")
            except Exception as _ap_err:
                _raise_model_evidence_error(_ap_err)
                _log(f"Analyst Panel error (skipped): {type(_ap_err).__name__}: {str(_ap_err)[:200]}", "yellow")
        if analyst_panel_adjustments:
            config["_analyst_panel_adjustments"] = analyst_panel_adjustments
        # Refresh main RethinkDB connection after panel (panel uses its own conn, but
        # the cached _nexus_db_conn may have gone stale during the panel's execution time)
        _get_nexus_db_conn(reuse=False)

        # ── Create shared Neo4j driver (reused across private-entity bridge, Google macro, propagation) ──
        global _shared_neo4j_driver
        _shared_neo4j_driver = None
        try:
            _historical_graph = bool(
                point_in_time_context is not None
                and not point_in_time_context.is_live
            )
            if _historical_graph and point_in_time_graph is not None:
                _shared_neo4j_driver = point_in_time_graph
            else:
                _shared_neo4j_driver = _create_nexus_graph_driver(
                    context=point_in_time_context,
                    snapshot_store=point_in_time_store,
                    neo4j_uri=neo4j_uri,
                    neo4j_user=neo4j_user,
                    neo4j_password=neo4j_password,
                    capture_enabled=_pit_capture_requested,
                )
            if _historical_graph:
                _log(
                    "Neo4j: using point-in-time graph snapshot "
                    f"(manifest={point_in_time_context.manifest.manifest_id}, "
                    f"as_of={point_in_time_context.as_of.isoformat()})",
                    "cyan",
                )
            else:
                _capture_suffix = " | PIT recording=ON" if _pit_capture_requested else ""
                _log(
                    f"Neo4j: shared driver connected to {_uri_for_log(neo4j_uri)}"
                    f"{_capture_suffix}",
                    "cyan",
                )
            # Pre-load dynamic ETF-sector/theme mappings from Neo4j (refreshed per session)
            if config.get("etf_allocation_enabled", True):
                _load_neo4j_etf_mappings(_shared_neo4j_driver, force_refresh=True)
                _load_neo4j_stock_sector_mappings(_shared_neo4j_driver, force_refresh=True)
                _load_neo4j_market_cap_cache(_shared_neo4j_driver)
        except Exception as _drv_exc:
            from point_in_time_data import PointInTimeDataError

            if isinstance(_drv_exc, PointInTimeDataError):
                raise
            _log(f"Neo4j: failed to create shared driver: {_drv_exc}", "yellow")

        # ── 2) LLM sentiment + event classification (or use cached sentiment) ──────────────────────
        use_llm_now = use_llm or llm_required
        private_entity_context = ""
        if articles:
            _peb_zero_streak = int(strategy_cache.get("_peb_zero_streak", 0) if strategy_cache else 0)
            _peb_skip_threshold = 10
            # Live-mode escape valve: defaults True so backtest path is unchanged
            # (key absent → True → original code runs). Broker flips False in live.
            if not config.get("private_entity_bridge_enabled", True):
                _log("Private-entity bridge: skipped (disabled via config)", "cyan")
                private_entity_resolutions = []
            elif _peb_zero_streak >= _peb_skip_threshold:
                _log(f"Private-entity bridge: skipped ({_peb_zero_streak} consecutive zero-resolution days)", "cyan")
                private_entity_resolutions = []
            elif _shared_neo4j_driver is None:
                _log("Private-entity bridge: skipped (no Neo4j driver)", "yellow")
                private_entity_resolutions = []
            else:
                with _timed_stage("Private-entity bridge", start_details=f"articles={len(articles)} | neo4j={_uri_for_log(neo4j_uri)}"):
                    try:
                        with _shared_neo4j_driver.session() as alias_session:
                            private_entity_resolutions = _resolve_private_entity_news_matches(
                                alias_session,
                                articles,
                                as_of_date=date_key,
                                use_toon=use_toon,
                            )
                        if private_entity_resolutions:
                            private_entity_context = _apply_private_entity_resolutions_to_articles(articles, private_entity_resolutions)
                            _log(f"Private-entity bridge: {len(private_entity_resolutions)} article resolution(s) seeded into public tickers", "green")
                            if strategy_cache is not None:
                                strategy_cache["_peb_zero_streak"] = 0
                        else:
                            _log("Private-entity bridge: no private-entity resolutions found", "cyan")
                            if strategy_cache is not None:
                                strategy_cache["_peb_zero_streak"] = _peb_zero_streak + 1
                    except Exception as exc:
                        _raise_model_evidence_error(exc)
                        _log(f"Private-entity bridge skipped: {exc}", "yellow")
                        private_entity_resolutions = []
        additional_context += private_entity_context
        # Inject sector/commodity price action so the LLM can detect trends
        # from price moves that may not appear in news headlines (gold, oil, etc.)
        if config.get("sector_price_context_enabled", True) and strategy_cache is not None:
            additional_context += _build_sector_price_context(
                strategy_cache, config, date_key, alpaca_key, alpaca_secret,
            )
        mentioned = _mentioned_tickers_from_articles(articles)
        sentiment_data: dict[str, dict] = {}
        conn = _get_nexus_db_conn()
        llm_traces_global: list[dict] = []
        company_article_rows: list[dict] = []
        macro_rows: list[dict] = []
        finbert_rows: dict[str, dict] = {}
        active_events: list[dict] = []

        # ── Google News: fetch+normalize in background (no LLM), macro LLM runs on main thread later ──
        _gn_fetch_future = None
        _gn_enabled = bool(config.get("google_news_enabled", True)) and bool(llm_key)

        def _launch_google_news_fetch_bg():
            """Launch Google News fetch+normalize in background (NO LLM calls — avoids endpoint contention)."""
            nonlocal _gn_fetch_future
            if not _gn_enabled or _gn_fetch_future is not None:
                return
            def _google_news_fetch():
                try:
                    _bg_conn = _r.connect(host=RETHINKDB_HOST, port=RETHINKDB_PORT, timeout=10) if _r else None
                except Exception as _bg_conn_exc:
                    _log(f"Google News background WARN: RethinkDB connection unavailable: {_bg_conn_exc}", "yellow")
                    _bg_conn = None
                _bg_result = {"google_articles": [], "normalized": []}
                try:
                    _pit_google_kwargs = {}
                    if point_in_time_context is not None:
                        _pit_google_kwargs["context"] = point_in_time_context
                    if (
                        point_in_time_context is not None
                        and not point_in_time_context.is_live
                    ):
                        _pit_google_kwargs["snapshot_store"] = (
                            point_in_time_store
                        )
                    _bg_articles = _fetch_google_news_cached(
                        date_key,
                        start_dt,
                        end_dt,
                        config,
                        conn=_bg_conn,
                        log_context="background",
                        **_pit_google_kwargs,
                    )
                    if not _bg_articles:
                        _log("Google News background: no articles fetched (disabled or no results)", "cyan")
                        return _bg_result
                    _bg_articles = list(_bg_articles[:max_daily_google_news_articles])
                    _log(f"Google News background: payload ready ({len(_bg_articles)} articles)", "cyan")
                    with _timed_stage("Google article normalization", start_details=f"articles={len(_bg_articles)}"):
                        _bg_normalized = _store_nexus_news_raw(_bg_conn, date_key, "google_news", _bg_articles, instance_id=instance_id, config=config)
                    _bg_result["google_articles"] = _bg_articles
                    _bg_result["normalized"] = _bg_normalized
                except Exception as _bg_exc:
                    from point_in_time_data import PointInTimeDataError

                    if isinstance(_bg_exc, PointInTimeDataError):
                        raise
                    _log(f"Google News fetch error: {_bg_exc}", "yellow")
                return _bg_result

            from concurrent.futures import ThreadPoolExecutor as _TPE
            _gn_executor = _TPE(max_workers=1)
            _gn_fetch_future = _gn_executor.submit(_google_news_fetch)
            _gn_executor.shutdown(wait=False)

        # Launch Google News fetch IMMEDIATELY so the macro pipeline can start
        # alongside company classification (the two phases used to serialise:
        # 125s of company → 178s of macro). The later _launch_google_news_fetch_bg()
        # calls (alpaca / zero-alpaca paths) are now no-ops because the closure
        # short-circuits on _gn_fetch_future being set.
        _launch_google_news_fetch_bg()

        # Background pipeline that resolves the GN fetch, applies the backtest
        # time-filter, and runs macro classification — all in parallel with the
        # foreground company classification. Combined CC concurrency is 4 (company)
        # + 4 (macro) = 8, well under CLAUDE_CLI_MAX_CONCURRENT=10.
        _macro_pipeline_fut = None
        if _gn_fetch_future is not None:
            def _macro_pipeline_worker():
                try:
                    _gn_to = max(60, int(config.get("google_news_fetch_timeout", 120)))
                    _bg_gn_result = _gn_fetch_future.result(timeout=_gn_to)
                except TimeoutError:
                    _log(f"Macro pipeline: Google News fetch timed out after {_gn_to}s — skipping", "yellow")
                    return [], [], [], []
                except Exception as _bg_gn_exc:
                    from point_in_time_data import PointInTimeDataError

                    if isinstance(_bg_gn_exc, PointInTimeDataError):
                        raise
                    _log(f"Macro pipeline: Google News fetch failed: {_bg_gn_exc}", "yellow")
                    return [], [], [], []
                _bg_google_articles = _bg_gn_result.get("google_articles", []) if isinstance(_bg_gn_result, dict) else []
                _bg_gn_normalized = _bg_gn_result.get("normalized", []) if isinstance(_bg_gn_result, dict) else []
                if not isinstance(_bg_google_articles, list):
                    _bg_google_articles = []
                if not isinstance(_bg_gn_normalized, list):
                    _bg_gn_normalized = []
                # Backtest safety: same time-filter as the original foreground block.
                if isinstance(current_time, datetime) and _bg_google_articles and not _is_daily:
                    _bg_ct_iso = current_time.strftime("%Y-%m-%dT%H:%M:%SZ")
                    _bg_pre = len(_bg_google_articles)
                    _bg_kept_idx = set()
                    for _bg_gi, _bg_ga in enumerate(_bg_google_articles):
                        _bg_pub = _bg_ga.get("published_date") or _bg_ga.get("created_at") or ""
                        if hasattr(_bg_pub, "strftime"):
                            _bg_pub = _bg_pub.strftime("%Y-%m-%dT%H:%M:%SZ")
                        if str(_bg_pub) <= _bg_ct_iso:
                            _bg_kept_idx.add(_bg_gi)
                    if len(_bg_kept_idx) < _bg_pre:
                        _bg_google_articles = [_bg_google_articles[i] for i in sorted(_bg_kept_idx)]
                        _bg_gn_normalized = [_bg_gn_normalized[i] for i in sorted(_bg_kept_idx) if i < len(_bg_gn_normalized)]
                        _log(f"Backtest time filter: removed {_bg_pre - len(_bg_google_articles)} Google articles published after {_bg_ct_iso}", "cyan")
                if not _bg_gn_normalized:
                    return [], [], _bg_google_articles, _bg_gn_normalized
                # Macro classification owns its own RethinkDB connection — _classify_*
                # uses conn for response-cache hits, and the main `conn` belongs to
                # the foreground thread.
                _bg_macro_conn = None
                try:
                    _bg_macro_conn = _r.connect(host=RETHINKDB_HOST, port=RETHINKDB_PORT, timeout=10) if (_nexus_db_available and _r is not None) else None
                except Exception as _bg_conn_exc:
                    _log(f"Macro pipeline: RethinkDB connection unavailable, classifying without cache: {_bg_conn_exc}", "yellow")
                    _bg_macro_conn = None
                try:
                    with _timed_stage("Macro article classification", start_details=f"articles={len(_bg_gn_normalized)}"):
                        _bg_macro_rows, _bg_macro_traces = _classify_macro_article_records(
                            _bg_gn_normalized, config, date_key=date_key, conn=_bg_macro_conn, instance_id=instance_id,
                        )
                    if not isinstance(_bg_macro_rows, list):
                        _bg_macro_rows = []
                    if not isinstance(_bg_macro_traces, list):
                        _bg_macro_traces = []
                    return _bg_macro_rows, _bg_macro_traces, _bg_google_articles, _bg_gn_normalized
                finally:
                    if _bg_macro_conn is not None:
                        try:
                            _bg_macro_conn.close()
                        except Exception as _bg_close_exc:
                            _log(f"Macro pipeline WARN: failed to close DB connection: {_bg_close_exc}", "yellow")
            from concurrent.futures import ThreadPoolExecutor as _MacroPipelineTPE
            _macro_pipeline_executor = _MacroPipelineTPE(max_workers=1)
            _macro_pipeline_fut = _macro_pipeline_executor.submit(_macro_pipeline_worker)
            _macro_pipeline_executor.shutdown(wait=False)

        with _timed_stage("Alpaca article normalization", start_details=f"articles={len(articles)}"):
            normalized_alpaca_articles = _store_nexus_news_raw(conn, date_key, "alpaca", articles, instance_id=instance_id, config=config)
        if not isinstance(normalized_alpaca_articles, list):
            normalized_alpaca_articles = []
        for raw_article, normalized_article in zip(articles, normalized_alpaca_articles):
            excerpt = str(normalized_article.get("content_excerpt") or "").strip()
            if excerpt:
                raw_article["content_excerpt"] = excerpt
        if normalized_alpaca_articles:
            with _timed_stage("FinBERT article scoring", start_details=f"articles={len(normalized_alpaca_articles)}"):
                finbert_rows = _score_finbert_for_articles(conn, normalized_alpaca_articles, strategy_cache)
                if not isinstance(finbert_rows, dict):
                    finbert_rows = {}
            with _timed_stage("Company article classification", start_details=f"articles={len(normalized_alpaca_articles)}"):
                try:
                    company_article_rows, company_traces = _classify_company_article_records(
                        normalized_alpaca_articles,
                        config,
                        date_key=date_key,
                        conn=conn,
                        instance_id=instance_id,
                    )
                except LLMCriticalFailure as _company_crit:
                    # Task 4: article-enrichment-role critical LLM failure
                    # degrades to an empty signal; decision-role (fail-safe)
                    # still propagates to broker.py for the halt.
                    # R2 Task 2: role-INDEPENDENT fatal classes (insufficient_credits
                    # / HTTP 402) OVERRIDE the degrade — nothing runs without credits,
                    # so re-raise even for an article role. Checked BEFORE the role.
                    if failure_is_role_independent(_company_crit) or \
                            role_is_halt_worthy(getattr(_company_crit, "role", None)):
                        raise
                    _alert_article_critical_degrade(_company_crit, instance_id=instance_id, stage="Company article")
                    company_article_rows, company_traces = [], []
                if not isinstance(company_article_rows, list):
                    company_article_rows = []
                if not isinstance(company_traces, list):
                    company_traces = []
                llm_traces_global.extend(company_traces)
            _launch_google_news_fetch_bg()  # fetch+normalize in background while sentiment LLM runs (no LLM contention)
            with _timed_stage("Daily feature aggregation", start_details=f"company_rows={len(company_article_rows)} | finbert_rows={len(finbert_rows)}"):
                _aggregate_nexus_day_features(
                    conn,
                    date_key=date_key,
                    instance_id=instance_id,
                    company_rows=company_article_rows,
                    finbert_rows=finbert_rows,
                )
        # Google macro/news flow must still run on zero-Alpaca bars.
        _launch_google_news_fetch_bg()
        llm_future_trades: list[dict] = []
        llm_cancellations: list[dict] = []
        llm_trend_updates: dict = {}

        # When use_sentiment_cache is False, ignore cache so the LLM is called every day (e.g. for backtests).
        if not use_sentiment_cache and cached_sentiment:
            _log(f"Sentiment cache skipped for {date_key} (use_sentiment_cache=false); will call LLM", "cyan")
            cached_sentiment = None

        if cached_sentiment and isinstance(cached_sentiment, dict):
            sentiment_data = dict(cached_sentiment)
            mentioned |= set(sentiment_data.keys())
            _log(f"Sentiment: using cache for {date_key} ({len(sentiment_data)} tickers) — LLM skipped, price-based trends will still run", "cyan")
            # Save event snapshots even from cached sentiment for outcome tracking
            if outcome_tracking:
                _conn_snap = _get_nexus_db_conn()
                if _conn_snap:
                    # Supplement broker prices with overlay bars cache (broker only has watchlist prices)
                    _snap_prices = dict(prices) if prices else {}
                    _overlay_raw = strategy_cache.get("_overlay_bars_raw") if strategy_cache else None
                    if _overlay_raw:
                        for _sym, _bars in _overlay_raw.items():
                            if _sym not in _snap_prices and _bars:
                                for _bar in reversed(_bars):
                                    _bd = str(_bar.get("t", _bar.get("date", "")))[:10]
                                    if _bd <= date_key:
                                        _val = float(_bar.get("c", 0) or 0)
                                        if _val > 0:
                                            _snap_prices[_sym] = _val
                                        break
                    _save_event_snapshots(_conn_snap, date_key, instance_id, sentiment_data, _snap_prices, bz_data, config=config)
        elif use_llm_now and llm_key:
            _sent_provider, _sent_key, _sent_model, _ = _resolve_role_llm_config(config, "sentiment")
            _sent_provider_config = _resolve_role_llm_provider_config(config, "sentiment")
            _sent_model_ref = _llm_model_ref(_sent_model, _sent_provider_config)
            _sent_limits = _get_sentiment_prompt_limits(
                config,
                provider=_sent_provider,
                model=_sent_model,
                provider_config=_sent_provider_config,
                requested_articles=num_articles_for_llm,
            )
            with _timed_stage(
                "Daily sentiment LLM",
                start_details=(
                    f"provider={_sent_provider} | model={_sent_model_ref} | "
                    f"articles={min(len(articles), int(_sent_limits['max_articles']))}"
                    + (
                        f" (requested={int(_sent_limits['requested_articles'])})"
                        if int(_sent_limits["requested_articles"]) != int(_sent_limits["max_articles"])
                        else ""
                    )
                ),
            ):
                # Gather pending trades to include in LLM context for review
                llm_pending = get_all_future_trades(strategy_cache) if (strategy_cache and get_all_future_trades) else []
                # Only include future trades (not today's or past)
                llm_pending = [t for t in llm_pending if t.get("target_date", "") > date_key]
                # Load recent headline history for tickers with pending trades
                ticker_history = {}
                if llm_pending and conn_hist:
                    pending_tickers = list({t.get("symbol", "") for t in llm_pending if t.get("symbol")})
                    ticker_history = _get_ticker_history(conn_hist, pending_tickers, max_per_ticker=10)
                    if ticker_history:
                        _log(f"  Loaded headline history for {len(ticker_history)} tickers with pending trades", "cyan")
                _log(f"LLM: calling {_sent_provider}/{_sent_model_ref} for up to {int(_sent_limits['max_articles'])} articles" +
                     (f" (requested {int(_sent_limits['requested_articles'])}, auto-reduced)" if int(_sent_limits["requested_articles"]) != int(_sent_limits["max_articles"]) else "") +
                     (f" (reviewing {len(llm_pending)} pending trades)" if llm_pending else ""), "cyan")
                sentiment_data, llm_future_trades, llm_cancellations, llm_trend_updates = _enhanced_sentiment_from_llm(
                    articles, _sent_provider, _sent_key, _sent_model,
                    num_articles=num_articles_for_llm,
                    today_str=date_key,
                    pending_trades=llm_pending if llm_pending else None,
                    ticker_history=ticker_history if ticker_history else None,
                    active_trends=active_trends if (trend_tracking and active_trends) else None,
                    additional_context=additional_context,
                    provider_config=_sent_provider_config,
                    config=config,
                )
            # Apply LLM-recommended cancellations
            if strategy_cache and llm_cancellations and cancel_trades:
                for ct in llm_cancellations:
                    removed = cancel_trades(strategy_cache, ct["ticker"], target_date=ct["date"])
                    if removed:
                        _log(f"  LLM cancelled: {ct['ticker']} on {ct['date']} ({ct.get('reason', '')[:60]})", "yellow")
            # Schedule any future trades the LLM identified
            if strategy_cache and llm_future_trades and schedule_trade:
                for ft in llm_future_trades:
                    schedule_trade(
                        strategy_cache, symbol=ft["ticker"],
                        target_date=ft["date"], signal=ft["signal"],
                        reason=ft.get("reason", "LLM-identified event"),
                        source_date=date_key, confidence=0.6,
                    )
                    _log(f"  Scheduled: {ft['ticker']} on {ft['date']} signal={ft['signal']} ({ft.get('reason', '')[:50]})", "cyan")
            if sentiment_data and len(sentiment_data) > 0:
                mentioned |= set(sentiment_data.keys())
                # Only cache on successful LLM return (non-empty parsed result)
                if conn:
                    _pit_sentiment_kwargs = {}
                    if point_in_time_context is not None:
                        _pit_sentiment_kwargs["context"] = point_in_time_context
                    _save_cached_sentiment(
                        conn,
                        date_key,
                        sentiment_data,
                        articles,
                        sentiment_cache_scope_id=sentiment_cache_scope_id,
                        sentiment_cache_scope_doc=sentiment_cache_scope_doc,
                        **_pit_sentiment_kwargs,
                    )
                # Save event snapshots for outcome tracking (measure actual moves next run)
                if outcome_tracking:
                    _conn_snap = _get_nexus_db_conn()
                    if _conn_snap:
                        _save_event_snapshots(_conn_snap, date_key, instance_id, sentiment_data, prices, bz_data, config=config)
            else:
                _log(
                    "LLM returned no sentiment (timeout or API error; see NewsStrategy/API logs). Falling back to company article classifications.",
                    "yellow",
                )
                # Fallback: derive seed sentiments from company article LLM classifications
                if company_article_rows:
                    _fb_scores: dict[str, list[float]] = {}
                    for _crow in company_article_rows:
                        for _ci in (_crow.get("classifications") or []):
                            _ct = str(_ci.get("ticker") or "").strip().upper()
                            _cdir = str(_ci.get("impact_direction") or "neutral").lower()
                            _cstr = float(_ci.get("impact_strength") or 0.0)
                            _crel = float(_ci.get("relevance_score") or 0.0)
                            if not _ct or _cstr < 0.3 or _crel < 0.4 or _cdir == "neutral":
                                continue
                            _fb_scores.setdefault(_ct, []).append(_cstr if _cdir == "bullish" else -_cstr)
                    for _ct, _scores in _fb_scores.items():
                        _avg = sum(_scores) / len(_scores)
                        if _avg > 0.15:
                            sentiment_data[_ct] = {"sentiment": 1, "event": "general", "sell_pct": 1.0}
                        elif _avg < -0.15:
                            sentiment_data[_ct] = {"sentiment": -1, "event": "general", "sell_pct": 1.0}
                    if sentiment_data:
                        _log(f"Company article fallback: {len(sentiment_data)} seed tickers derived from LLM article classifications", "yellow")
        else:
            reason = "cached + use_llm=False" if from_cache and not use_llm else "no API key"
            _log(f"LLM: skipped ({reason}); using neutral sentiment for mentioned tickers", "cyan")

        # ── Benzinga direct signals: fill tickers with ratings but no headlines ──
        if bz_data:
            bz_signals = _extract_benzinga_direct_signals(bz_data, set(symbols_list), date_key)
            bz_filled = 0
            for ticker, sig in bz_signals.items():
                if ticker not in sentiment_data:  # Don't override LLM
                    sentiment_data[ticker] = sig
                    mentioned.add(ticker)
                    bz_filled += 1
            if bz_filled:
                _log(f"Benzinga direct signals: {bz_filled} tickers filled (no Alpaca headline)", "green")

        # ── Recently-sold cooldown: prevent immediate re-discovery of pruned stocks ──
        _sold_cooldown_days = int(config.get("discovery_sold_cooldown_days", 7))
        _sold_cooldown: set[str] = _get_recently_sold_discovered_tickers(
            conn_trends, instance_id, date_key, cooldown_days=_sold_cooldown_days,
        )
        # Also track stocks pruned during THIS bar so later discovery stages can't re-add them
        _pruned_this_bar: set[str] = set()
        if _sold_cooldown:
            _log(f"Discovery cooldown: {len(_sold_cooldown)} recently-sold ticker(s) excluded from re-discovery", "cyan")

        # ── Benzinga discovery: find new tickers from broad data ──────────
        all_discovered: list[str] = []  # initialized early so Benzinga discovery can append to it
        if bz_data and stock_finder and conn_trends is not None and config.get("benzinga_discovery_enabled", True):
            bz_discovery = _extract_benzinga_discovery_candidates(bz_data, set(symbols_list), date_key)
            if bz_discovery:
                max_discovered = int(config.get("max_discovered_stocks", 90))
                _existing_active_disc = _get_all_discovered_stocks(conn_trends, instance_id)
                current_discovered_count = len(_existing_active_disc)
                reuse_stamp = _nexus_reuse_stamp_from_config(config, instance_id)
                hard_limit = max_discovered
                _bz_no_data = strategy_cache.get("_overlay_no_data_tickers", set()) if strategy_cache else set()
                _bz_excl = set(symbols_list) | _sold_cooldown | set(_existing_active_disc) | _bz_no_data
                _bz_newly_discovered = []
                # Benzinga candidates carry no per-ticker magnitude (sentiment is
                # a constant flag), so order deterministically by ticker.
                for ticker, sig in _ordered_discovery_candidates(bz_discovery.items()):
                    if current_discovered_count >= hard_limit:
                        break
                    if ticker in _bz_excl:
                        continue
                    doc_id = f"{instance_id}_{ticker}"
                    doc = {
                        "id": doc_id,
                        "ticker": ticker,
                        "instance_id": instance_id,
                        "discovered_date": date_key,
                        "source_trend_ids": [],
                        "source": "benzinga",
                        "benzinga_event": sig.get("event", ""),
                        "status": "active",
                        "last_signal_date": date_key,
                        "consecutive_sell_days": 0,
                        "sell_reason": None,
                    }
                    doc.update(reuse_stamp)
                    try:
                        _r.db(DB_NAME).table(DISCOVERED_TABLE).insert(doc, conflict="replace").run(conn_trends)
                        _bz_newly_discovered.append(ticker)
                        current_discovered_count += 1
                        symbols_list.append(ticker)
                        if ticker not in all_discovered:
                            all_discovered.append(ticker)
                        # Seed sentiment from discovery signal
                        if ticker not in sentiment_data:
                            sentiment_data[ticker] = sig
                            mentioned.add(ticker)
                    except Exception as _bz_disc_exc:
                        _log(f"Benzinga discovery WARN: failed to register {ticker}: {_bz_disc_exc}", "yellow")
                if _bz_newly_discovered:
                    _log(f"Benzinga discovery: {len(_bz_newly_discovered)} new ticker(s) added to symbols → {', '.join(_bz_newly_discovered)}", "green")

        # ── Cross-validate LLM sentiment with per-article classifications ──
        if company_article_rows and sentiment_data:
            _cv_dampened = 0
            for ticker in list(sentiment_data.keys()):
                llm_sent = sentiment_data[ticker].get("sentiment", 0)
                if llm_sent == 0:
                    continue
                articles_for_ticker = [
                    ci for row in company_article_rows
                    for ci in (row.get("classifications") or [])
                    if str(ci.get("ticker") or "").upper() == ticker
                    and float(ci.get("relevance_score") or 0) >= 0.5
                ]
                if len(articles_for_ticker) < 2:
                    continue
                article_direction = sum(
                    1 if ci.get("impact_direction") == "bullish" else -1
                    for ci in articles_for_ticker
                    if ci.get("impact_direction") in ("bullish", "bearish")
                )
                if article_direction != 0 and (article_direction > 0) != (llm_sent > 0):
                    sentiment_data[ticker]["sentiment"] = 0
                    sentiment_data[ticker]["event"] = sentiment_data[ticker].get("event", "") + "|article_conflict"
                    _cv_dampened += 1
            if _cv_dampened:
                _log(f"Article cross-validation: {_cv_dampened} tickers dampened (LLM vs article disagreement)", "yellow")

        # Tickers mentioned in articles but not scored by LLM: assign neutral
        for ticker in mentioned:
            if ticker not in sentiment_data:
                sentiment_data[ticker] = {"sentiment": 0, "event": "general"}

        n_pos = sum(1 for d in sentiment_data.values() if d.get("sentiment") == 1)
        n_neg = sum(1 for d in sentiment_data.values() if d.get("sentiment") == -1)
        n_neutral = len(sentiment_data) - n_pos - n_neg
        _log(
            f"Sentiment (Alpaca): {len(mentioned)} tickers mentioned | {n_pos} positive, {n_neg} negative, {n_neutral} neutral",
            "cyan",
        )

        # Cache sentiment_data for the analyst panel on the NEXT bar (Phase 2.5 runs before sentiment)
        from _phase_alpha_helpers import evidence_cache_write_allowed
        if (
            strategy_cache is not None
            and evidence_cache_write_allowed("sentiment")
        ):
            strategy_cache["_last_sentiment_data"] = dict(sentiment_data)

        # ── 2a-pre) Market Trends: apply updates, generate signals, discover stocks ──
        _log("Post-sentiment: processing trends + Google News...", "cyan")
        nexus_discovered_tickers: list[str] = []
        nexus_sell_enforcement: set[str] = set()
        # all_discovered initialized earlier (before Benzinga discovery)
        all_etf_discovered: list[str] = []

        # Price-based trend detection (independent of LLM sentiment)
        _price_trend_count = 0
        if trend_tracking and conn_trends and strategy_cache is not None:
            _price_trend_count = _detect_price_based_trends(
                conn_trends, strategy_cache, config, date_key,
                alpaca_key, alpaca_secret, instance_id,
            )
            if _price_trend_count:
                _log(f"Price-based trends: {_price_trend_count} created/updated", "green")

        # V31 Section 4.5: bull/bear/chop regime detector. Result is consumed
        # by the grace-period escape hatch C (in _in_initial_grace_period).
        # Falls back to "bull" if no proxy bars are available.
        if strategy_cache is not None and bool(config.get("regime_detector_enabled", True)):
            _pit_regime_kwargs = {}
            if point_in_time_context is not None:
                _pit_regime_kwargs = {
                    "context": point_in_time_context,
                    "session_close_resolver": session_close_resolver,
                }
            _v31_raw = _detect_market_regime(
                strategy_cache,
                config,
                date_key,
                data=data,
                **_pit_regime_kwargs,
            )
            _v31_regime = _apply_regime_hysteresis(strategy_cache, _v31_raw, config)
            strategy_cache["_market_regime"] = _v31_regime
            # 2026-07-24 recovery-regime flag (v2) — see _next_recovery_flag.
            _v31_diag_raw = str(((strategy_cache.get("_market_regime_diag") or {}).get("raw")) or "")
            strategy_cache["_market_regime_recovery"] = _next_recovery_flag(
                strategy_cache.get("_market_regime_recovery"), _v31_regime, _v31_diag_raw)
            # 2026-07-23 shared bear-conviction primitive: consecutive confirmed
            # bear/crash TRADING DAYS (increments once per new date_key while
            # confirmed bear/crash; ANY upgrade to chop/bull resets it). Single
            # source of truth read by BOTH the conviction-scaled SQQQ hedge and
            # the deep-bear long de-risk (broker-side, via the strategy_cache
            # global) — so the hedge scale-up and the long cut arm together on a
            # sustained downtrend, not a 1-day flip. Inert unless those features
            # are enabled; the count itself is harmless.
            if _v31_regime in ("bear", "crash"):
                if strategy_cache.get("_bear_dwell_last_date") != date_key:
                    strategy_cache["_bear_dwell_bars"] = int(strategy_cache.get("_bear_dwell_bars", 0) or 0) + 1
                    strategy_cache["_bear_dwell_last_date"] = date_key
            else:
                strategy_cache["_bear_dwell_bars"] = 0
                strategy_cache["_bear_dwell_last_date"] = None
            _v31_diag = strategy_cache.get("_market_regime_diag") or {}
            # 2026-07-25 bear-capacity latch (default OFF): the dwell counter
            # above RESETS on any chop bar, which is correct for the trim but
            # wrong for capacity — a single chop bar restores full chop capacity
            # and the book refills mid-downtrend. The latch persists the bear cap
            # across those interludes and releases only on a real turn.
            strategy_cache["_bear_capacity_latch"] = _next_bear_capacity_latch(
                strategy_cache.get("_bear_capacity_latch"), _v31_regime,
                strategy_cache.get("_market_regime_recovery"), config)
            _log(
                f"V31 market regime: {_v31_regime} "
                f"(raw={_v31_raw}, proxy={_v31_diag.get('proxy')}, "
                f"closes={_v31_diag.get('closes')}, ret20={_v31_diag.get('ret20')})",
                "cyan",
            )
        else:
            if strategy_cache is not None:
                strategy_cache["_market_regime"] = "bull"

        # V11.2: Initialize propagated early — used by _evaluate_trend_sell_enforcement
        # below (line ~13533) BEFORE the Neo4j propagation step computes the real values.
        propagated = {}

        # Reload active trends to include newly created price-based trends
        _active_watchlist_state = None  # V23: pre-init to avoid NameError if trend_tracking is off
        if trend_tracking and conn_trends:
            _trend_max_age = int(config.get("trend_max_age_days", 21))
            active_trends = _load_active_trends(
                conn_trends, instance_id, max_age_days=_trend_max_age, date_key=date_key, config=config,
            )

        if trend_tracking and conn_trends:
            # Apply trend updates from LLM response
            if use_llm_now and llm_key and llm_trend_updates:
                active_trends = _apply_trend_updates(
                    conn_trends, llm_trend_updates, date_key, articles, instance_id, config=config,
                )
            # Also load any recently-ended trends for sell signals
            all_instance_trends = []
            try:
                cursor = _r.db(DB_NAME).table(TRENDS_TABLE).filter(
                    lambda doc: doc["instance_id"] == instance_id
                ).run(conn_trends)
                all_instance_trends = list(cursor)
            except Exception:
                all_instance_trends = active_trends

            # Generate buy signals from active trends
            trend_buy_signals = _get_trend_buy_signals(active_trends, config)
            if trend_buy_signals:
                _log(f"Trend buy signals: {len(trend_buy_signals)} tickers from active trends", "green")

            # Generate sell signals from ended/weakening trends
            _sell_expiry = int(config.get("sell_enforcement_expiry_days", 7))
            trend_sell_signals = _get_trend_sell_signals(all_instance_trends, date_key=date_key, expiry_days=_sell_expiry)
            if trend_sell_signals:
                _log(f"Trend sell signals: {len(trend_sell_signals)} tickers from ended/weakening trends", "yellow")

            _active_watchlist_state = _get_active_watchlist_state(active_trends, config)
            if strategy_cache is not None:
                strategy_cache["_active_watchlist_priority_tickers"] = set(_active_watchlist_state.get("priority_tickers") or set())
                strategy_cache["_active_watchlist_sector_keys"] = list(_active_watchlist_state.get("matched_keys") or [])
            if _active_watchlist_state.get("matched_keys"):
                _log(
                    f"Active watchlist sectors: {', '.join(_active_watchlist_state.get('matched_keys') or [])}",
                    "cyan",
                )

            # Discover new stocks from trend buy signals
            if stock_finder and trend_buy_signals:
                current_syms = set(symbols_list) | _sold_cooldown
                nexus_discovered_tickers = _discover_stocks(
                    conn_trends, trend_buy_signals, instance_id,
                    current_syms, config, date_key,
                )

            # Discover ETFs from active trends + detect stale ETFs to sell
            stale_etfs: set[str] = set()
            if etf_allocation:
                if active_trends:
                    _discover_trend_etfs(
                        conn_trends, active_trends, instance_id,
                        set(symbols_list), config, date_key,
                    )
                stale_etfs = _get_stale_trend_etfs(conn_trends, instance_id, all_instance_trends)
                if stale_etfs:
                    _log(f"Trend ETFs to sell (stale trends): {', '.join(sorted(stale_etfs))}", "yellow")

            # Load all active discovered stocks + ETFs (including previously discovered)
            all_discovered = _get_all_discovered_stocks(conn_trends, instance_id)
            all_etf_discovered = _get_all_active_trend_etfs(conn_trends, instance_id) if etf_allocation else []

            # Prune discovered stocks whose source trends have ALL ended/weakened away
            if all_discovered and all_instance_trends:
                _active_trend_ids = {t["id"] for t in all_instance_trends if t.get("status") not in ("ended",)}
                _pruned = []
                for d_ticker in list(all_discovered):
                    d_doc_id = f"{instance_id}_{d_ticker}"
                    try:
                        d_doc = _r.db(DB_NAME).table(DISCOVERED_TABLE).get(d_doc_id).run(conn_trends)
                    except Exception as _disc_doc_exc:
                        _log(f"Discovered stock WARN: failed to load source-trend doc for {d_ticker}: {_disc_doc_exc}", "yellow")
                        d_doc = None
                    if d_doc and d_doc.get("source_trend_ids"):
                        # Check if ANY source trend is still active
                        if not any(tid in _active_trend_ids for tid in d_doc["source_trend_ids"]):
                            _mark_discovered_stock_sold(conn_trends, instance_id, d_ticker, "All source trends ended", date_key=date_key)
                            all_discovered.remove(d_ticker)
                            _pruned.append(d_ticker)
                if _pruned:
                    _pruned_this_bar.update(_pruned)
                    _log(f"Pruned {len(_pruned)} discovered stock(s) (source trends ended): {', '.join(_pruned)}", "yellow")

            # Prune discovered stocks that have no Alpaca bar data (OTC/delisted/IEX-unavailable)
            if all_discovered and strategy_cache is not None:
                _no_data_tickers: set[str] = _normalize_cache_string_set(strategy_cache, "_overlay_no_data_tickers")
                if _no_data_tickers:
                    _no_data_pruned = []
                    for d_ticker in list(all_discovered):
                        if d_ticker in _no_data_tickers:
                            _mark_discovered_stock_sold(conn_trends, instance_id, d_ticker, "No bar data available (IEX)", date_key=date_key)
                            all_discovered.remove(d_ticker)
                            _no_data_pruned.append(d_ticker)
                    if _no_data_pruned:
                        _pruned_this_bar.update(_no_data_pruned)
                        _log(f"Pruned {len(_no_data_pruned)} discovered stock(s) (no bar data): {', '.join(_no_data_pruned)}", "yellow")

            if all_discovered:
                _log(f"Discovered stocks ({len(all_discovered)} active): {', '.join(all_discovered[:10])}", "cyan")
            if all_etf_discovered:
                _log(f"Trend ETFs ({len(all_etf_discovered)} active): {', '.join(all_etf_discovered[:10])}", "cyan")

            # Merge trend buy signals into sentiment_data (LLM direct sentiment takes priority)
            # Use "trend_momentum" event so the generic_direct_penalty (-0.35) does NOT fire.
            for ticker, data in trend_buy_signals.items():
                if ticker not in sentiment_data:
                    sentiment_data[ticker] = {"sentiment": data["score"], "event": "trend_momentum"}
                    mentioned.add(ticker)

            # ETF buy signals: active trend ETFs get a buy score
            for etf in all_etf_discovered:
                if etf not in sentiment_data:
                    sentiment_data[etf] = {"sentiment": 1, "event": "trend_momentum"}
                    mentioned.add(etf)

            # η.A — Phase η (2026-05-20): bridge momentum_watchlist into
            # sentiment_data so technical-momentum picks participate in
            # propagation. The existing trend_buy_signals seeding above
            # covers LLM-news-derived trends; this covers technical
            # momentum_watchlist picks that lack news coverage (BT277953
            # MU/LITE/PRAX case).
            if config.get("eta_momentum_seeding_enabled", True):
                _eta_mw_top_n = int(config.get("eta_momentum_seed_top_n", 5) or 5)
                _eta_mw_min = float(config.get("eta_momentum_seed_min_score", 0.05) or 0.05)
                # Production schema fix (bug-sweep): _momentum_watchlist values
                # are {"first_seen_bar": ..., "first_seen_price": ...} — NO
                # "score" field. Scores live in _momentum_ranked_cache (a
                # list[(ticker, score)] populated by _score_momentum_rank
                # later in this same bar). On bar N, η.A reads bar (N-1)'s
                # ranked cache, intersected with the current watchlist
                # membership. Bar 1 is a cold-start no-op (ranked_cache empty),
                # which is the desired behavior — no scored picks to seed.
                _eta_mw_ranked = (
                    strategy_cache.get("_momentum_ranked_cache", []) or []
                    if isinstance(strategy_cache, dict) else []
                )
                _eta_mw_members = (
                    set((strategy_cache.get("_momentum_watchlist") or {}).keys())
                    if isinstance(strategy_cache, dict) else set()
                )
                _eta_seeded = 0
                _eta_considered = 0
                if _eta_mw_ranked and _eta_mw_members:
                    # ranked_cache is sorted desc by score; filter to active
                    # watchlist members, take top-N.
                    _eta_sorted: list[tuple[str, float]] = []
                    for _eta_entry in _eta_mw_ranked:
                        if len(_eta_sorted) >= _eta_mw_top_n:
                            break
                        try:
                            _eta_t = str(_eta_entry[0] or "").strip().upper()
                            _eta_s_raw = _eta_entry[1]
                        except (IndexError, TypeError):
                            continue
                        if not _eta_t or _eta_t not in _eta_mw_members:
                            continue
                        _eta_sorted.append((_eta_t, float(_eta_s_raw or 0.0)))
                    for _eta_t, _eta_s in _eta_sorted:
                        _eta_considered += 1
                        _eta_existing = sentiment_data.get(_eta_t)
                        if _eta_existing and int(_eta_existing.get("sentiment", 0) or 0) != 0:
                            continue
                        if _eta_s < _eta_mw_min:
                            continue
                        sentiment_data[_eta_t] = {
                            "sentiment": 1,
                            "event": "momentum_breakout",
                        }
                        mentioned.add(_eta_t)
                        _eta_seeded += 1
                # Always-log per bug-sweep (Φ.η.0 validation needs to
                # distinguish "feature ran, 0 qualified" from "feature
                # gated off" from "ranked_cache empty").
                _log(
                    f"[ETA.A] seeded={_eta_seeded} considered={_eta_considered} "
                    f"watchlist_members={len(_eta_mw_members)} "
                    f"ranked_cache={len(_eta_mw_ranked)} "
                    f"(top_n={_eta_mw_top_n}, min_score={_eta_mw_min})",
                    "cyan",
                )

            # Merge trend sell signals + build sell enforcement set
            # V9: Sell enforcement tuning — min hold period, confirmed downtrend,
            # signal hysteresis, and profitable hold protection.
            # IMPORTANT: fast_loser_cut and trailing_stop ALWAYS fire regardless of
            # min-hold period. Only the trend-reversal enforcement gets these gates.
            # Fast loser / trailing stop are handled in _finalize_scores and added
            # to nexus_sell_enforcement via _forced_exit at the end of scoring.
            sell_enforcement_enabled = config.get("sell_enforcement_enabled", True)
            for ticker, sell_data in trend_sell_signals.items():
                if sell_data.get("force") and sell_enforcement_enabled:
                    _trend_sell_eval = _evaluate_trend_sell_enforcement(
                        ticker,
                        portfolio_emulator=portfolio_emulator,
                        prices=prices,
                        price_history=data if isinstance(data, dict) else None,
                        propagated=propagated,
                        config=config,
                        strategy_cache=strategy_cache,
                        date_key=date_key,
                    )
                    if _trend_sell_eval.get("allow_force_sell", True):
                        nexus_sell_enforcement.add(ticker)
                        # Override sentiment to sell regardless of other signals
                        sentiment_data[ticker] = {"sentiment": sell_data["score"], "event": "general"}
                        mentioned.add(ticker)
                        # Mark discovered stock as pending sell
                        if ticker in all_discovered:
                            _mark_discovered_stock_sold(conn_trends, instance_id, ticker, sell_data.get("reason", ""), date_key=date_key)
                            _pruned_this_bar.add(ticker)
                    else:
                        _skip_reason = str(_trend_sell_eval.get("skip_reason") or "")
                        if _skip_reason:
                            _log(_skip_reason, "cyan")
                        # Still set sentiment but don't force-sell
                        # Phase ε.C.5 (BT294837 follow-up, 2026-05-19): when
                        # the trend-reversal sell was suppressed (e.g. by
                        # ε.A.3's pos=0 guard), do NOT seed propagation with
                        # negative sentiment for non-held tickers — this is
                        # the "stale Neo4j sentiment" issue per ε.B.5 audit.
                        # Pre-ε.C.5 the SELL signal flowed into
                        # sentiment_data → propagation aggregator →
                        # `SNDK=-1.000(12p)` anchor that resurfaces SNDK in
                        # propagation_expansion SELL rows every bar even
                        # though SNDK isn't held. Gate the seed on position
                        # existence so non-held negative sentiment decays
                        # naturally (no new seed each bar).
                        _ec5_pos_qty = 0.0
                        if portfolio_emulator is not None:
                            try:
                                _ec5_pos_qty = float(
                                    (portfolio_emulator._positions or {}).get(ticker, 0.0) or 0.0
                                )
                            except Exception:
                                _ec5_pos_qty = 0.0
                        if ticker not in sentiment_data and _ec5_pos_qty > 0:
                            sentiment_data[ticker] = {"sentiment": sell_data["score"], "event": "general"}
                            mentioned.add(ticker)
                elif ticker not in sentiment_data:
                    # Phase ε.C.5: same gate for the no-sell-enforcement-eval
                    # path (sell_enforcement_enabled=False OR force=False).
                    _ec5_pos_qty2 = 0.0
                    if portfolio_emulator is not None:
                        try:
                            _ec5_pos_qty2 = float(
                                (portfolio_emulator._positions or {}).get(ticker, 0.0) or 0.0
                            )
                        except Exception:
                            _ec5_pos_qty2 = 0.0
                    if _ec5_pos_qty2 > 0:
                        sentiment_data[ticker] = {"sentiment": sell_data["score"], "event": "general"}
                        mentioned.add(ticker)

            # Enforce sells on stale trend ETFs
            if stale_etfs and sell_enforcement_enabled:
                for etf in stale_etfs:
                    nexus_sell_enforcement.add(etf)
                    sentiment_data[etf] = {"sentiment": -1, "event": "general"}
                    mentioned.add(etf)
                    _mark_trend_etf_sold(conn_trends, instance_id, etf, "Source trend ended")

            # Expand symbols_list with discovered stocks so they get scored
            existing_syms = set(symbols_list)
            for d_ticker in all_discovered:
                if d_ticker not in existing_syms:
                    symbols_list.append(d_ticker)
                    existing_syms.add(d_ticker)
            # Also expand with discovered ETFs so they get scored and can appear in buy_syms
            for e_ticker in all_etf_discovered:
                if e_ticker not in existing_syms:
                    symbols_list.append(e_ticker)
                    existing_syms.add(e_ticker)
            # Trend-related individual stocks via Neo4j sector/industry mappings
            _NEO4J_STOCK_CAP_PER_KEYWORD = 10
            if active_trends and _neo4j_stock_sector_cache and config.get("trend_stock_discovery_enabled", True):
                _trend_stocks_added = []
                for trend in active_trends:
                    if trend.get("status") != "active":
                        continue
                    _tname = (trend.get("name") or "").lower()
                    for keyword, stocks in _neo4j_stock_sector_cache.items():
                        if keyword in _tname:
                            for s in stocks[:_NEO4J_STOCK_CAP_PER_KEYWORD]:
                                if s not in existing_syms:
                                    symbols_list.append(s)
                                    existing_syms.add(s)
                                    _trend_stocks_added.append(s)
                                if s not in sentiment_data:
                                    sentiment_data[s] = {"sentiment": 1, "event": "trend_momentum"}
                                    mentioned.add(s)
                if _trend_stocks_added:
                    _log(f"Trend stocks ({len(_trend_stocks_added)}): {', '.join(_trend_stocks_added[:10])}", "cyan")
            if len(symbols_list) > len(symbols or []):
                _log(f"Symbols expanded: {len(symbols or [])} → {len(symbols_list)} (includes {len(symbols_list) - len(symbols or [])} discovered)", "cyan")

        # ── 2a) Google News + macro classification: results from the bg pipeline
        # that started alongside company classification. Joining here costs only
        # the tail (max(macro, company) - company), not the full macro time.
        google_articles: list[dict] = []
        _gn_normalized: list[dict] = []
        if _macro_pipeline_fut is not None:
            try:
                with _timed_stage("Macro pipeline (join)", start_details="waiting for background macro classification"):
                    macro_rows, _gn_macro_traces, google_articles, _gn_normalized = _macro_pipeline_fut.result(timeout=600)
                if not isinstance(macro_rows, list):
                    macro_rows = []
                if not isinstance(_gn_macro_traces, list):
                    _gn_macro_traces = []
                if not isinstance(google_articles, list):
                    google_articles = []
                if not isinstance(_gn_normalized, list):
                    _gn_normalized = []
                llm_traces_global.extend(_gn_macro_traces)
            except LLMCriticalFailure as _macro_crit:
                # Task 4: an article-enrichment-role critical LLM failure
                # (e.g. codex-cli quota) must DEGRADE, not halt. A decision-role
                # critical (fail-safe: None/unknown too) still propagates to
                # broker.py's outer loop for the halt.
                # R2 Task 2: role-INDEPENDENT fatal classes (insufficient_credits
                # / HTTP 402) OVERRIDE the degrade — nothing runs without credits,
                # so re-raise even for an article role. Checked BEFORE the role.
                if failure_is_role_independent(_macro_crit) or \
                        role_is_halt_worthy(getattr(_macro_crit, "role", None)):
                    raise
                _alert_article_critical_degrade(_macro_crit, instance_id=instance_id, stage="Macro article")
                macro_rows = []
                _gn_macro_traces = []
                google_articles = []
                _gn_normalized = []
            except Exception as _macro_join_exc:
                _raise_model_evidence_error(_macro_join_exc)
                from point_in_time_data import PointInTimeDataError

                if isinstance(_macro_join_exc, PointInTimeDataError):
                    raise
                _log(f"Macro pipeline error (non-fatal): {_macro_join_exc}", "yellow")
                macro_rows = []
                _gn_macro_traces = []
                google_articles = []
                _gn_normalized = []
        # Run event maintenance + Google macro resolution in parallel.
        # _maintain_active_events only writes to RethinkDB (no Neo4j) — safe to run concurrently
        # with the Google macro Neo4j + LLM call.
        if _gn_normalized:
            # Submit event maintenance to a background thread.
            # RethinkDB connections are not thread-safe — the worker creates its own connection.
            def _maint_worker(_cfg=config, _iid=instance_id, _dk=date_key, _rows=macro_rows):
                try:
                    if not _nexus_db_available or _r is None:
                        # No DB available — run with None conn (same fallback as original code path)
                        return _maintain_active_events(
                            None, _cfg,
                            instance_id=_iid, date_key=_dk, macro_rows=_rows,
                        )
                    _bg_conn = _r.connect(host=RETHINKDB_HOST, port=RETHINKDB_PORT, timeout=10)
                    try:
                        return _maintain_active_events(
                            _bg_conn, _cfg,
                            instance_id=_iid, date_key=_dk, macro_rows=_rows,
                        )
                    finally:
                        try:
                            _bg_conn.close()
                        except Exception as _bg_close_exc:
                            _log(f"Active-event maintenance WARN: failed to close background DB connection: {_bg_close_exc}", "yellow")
                except Exception as _bg_exc:
                    _raise_model_evidence_error(_bg_exc)
                    raise RuntimeError(f"Event maintenance background worker failed: {_bg_exc}") from _bg_exc
            from concurrent.futures import ThreadPoolExecutor as _MaintTPE
            _maint_executor = _MaintTPE(max_workers=1)
            _maint_fut = _maint_executor.submit(_maint_worker)
            _maint_executor.shutdown(wait=False)
            if google_articles:
                try:
                    with _timed_stage("Google macro resolution", start_details=f"articles={len(google_articles)} | neo4j={_uri_for_log(neo4j_uri)}"):
                        if _shared_neo4j_driver is None:
                            raise RuntimeError("No shared Neo4j driver available")
                        with _shared_neo4j_driver.session() as gn_session:
                            avail_sectors = _get_available_sectors(gn_session)
                            avail_agencies = _get_available_gov_agencies(gn_session)
                            _macro_provider, _macro_key, _macro_model, _ = _resolve_role_llm_config(config, "macro_article")
                            _macro_provider_config = _resolve_role_llm_provider_config(config, "macro_article")
                            macro_signals = _classify_macro_news_via_llm_cached(
                                google_articles, _macro_provider, _macro_key, _macro_model,
                                today_str=date_key,
                                available_sectors=avail_sectors,
                                available_gov_agencies=avail_agencies,
                                num_articles=min(len(google_articles), max_daily_google_news_articles),
                                provider_config=_macro_provider_config,
                                conn=conn,
                                instance_id=instance_id,
                                graph_driver=_shared_neo4j_driver,
                            )
                            if macro_signals:
                                symbols_set = set(symbols_list)
                                macro_sentiment = _resolve_macro_signals_to_tickers(
                                    gn_session, macro_signals, symbols_set=symbols_set, as_of_date=date_key,
                                )
                                macro_added = 0
                                macro_dampened = 0
                                for ticker, data in macro_sentiment.items():
                                    raw_s = data.get("sentiment", 0)
                                    discrete_s = 1 if raw_s > 0.2 else (-1 if raw_s < -0.2 else 0)
                                    if discrete_s == 0:
                                        continue
                                    if ticker not in sentiment_data:
                                        sentiment_data[ticker] = {"sentiment": discrete_s, "event": data.get("event", "general")}
                                        mentioned.add(ticker)
                                        macro_added += 1
                                    else:
                                        existing_s = sentiment_data[ticker].get("sentiment", 0)
                                        if existing_s != 0 and existing_s != discrete_s:
                                            sentiment_data[ticker]["sentiment"] = 0
                                            sentiment_data[ticker]["event"] = f"conflicting:{sentiment_data[ticker].get('event', '')}+macro:{data.get('event', '')}"
                                            macro_dampened += 1
                                if macro_added or macro_dampened:
                                    _log(f"Google News → {macro_added} new tickers added, {macro_dampened} dampened (conflicting macro)", "green")
                except Exception as e:
                    _raise_model_evidence_error(e)
                    _log(f"Google News integration error: {e}", "yellow")
            # Wait for event maintenance background thread to complete
            try:
                with _timed_stage("Active-event maintenance (join)", start_details="waiting for background thread"):
                    active_events, _gn_event_traces = _maint_fut.result(timeout=900)
                llm_traces_global.extend(_gn_event_traces)
            except Exception as _maint_exc:
                _raise_model_evidence_error(_maint_exc)
                _exc_desc = repr(_maint_exc) if str(_maint_exc) == "" else str(_maint_exc)
                _log(f"Active-event maintenance error (non-fatal): {_exc_desc}", "yellow")
                active_events = []
                _gn_event_traces = []
        elif _gn_enabled and not llm_key:
            _log("Google News: skipped (no LLM API key for classification)", "cyan")
        if not mentioned:
            _log("No tickers extracted from Alpaca or Google News; returning hold for all.", "yellow")
            _finalize_pit_capture_safely(
                enabled=_pit_capture_requested,
                config=config,
                as_of=point_in_time_context.as_of
                if point_in_time_context is not None
                else current_time,
                recording_driver=_shared_neo4j_driver,
                strategy_cache=strategy_cache,
                alpaca_articles=articles,
                google_articles=google_articles,
                benzinga_data=bz_data,
            )
            if _shared_neo4j_driver is not None:
                try:
                    _shared_neo4j_driver.close()
                except Exception as _drv_close_exc:
                    _log(f"Neo4j WARN: failed to close shared driver on early-return path: {_drv_close_exc}", "yellow")
            return {s: 0 for s in symbols_list}
        if not active_events:
            # sorted: these records are sliced [:12] into every symbol's overlay
            # prompt, so an unsorted cursor changed what the LLM was shown.
            active_events = _sorted_active_event_records(
                _load_active_events_as_of(
                    conn,
                    instance_id,
                    date_key,
                    history_scope_id=active_event_history_scope_id,
                )
            )

        # ── 2b) Review pending future trades against fresh sentiment ──────
        # If a pending buy/sell is contradicted by today's strong sentiment, cancel it.
        # This prevents stale trades from executing when the thesis has been invalidated.
        pending_by_symbol: dict[str, list] = {}
        if strategy_cache and get_all_future_trades:
            all_future = get_all_future_trades(strategy_cache)
            if all_future:
                n_before = len(all_future)
                cancelled_count = 0
                for trade in list(all_future):
                    sym = trade.get("symbol", "")
                    sig = trade.get("signal", 0)
                    target_date = trade.get("target_date", "")
                    if not sym or not sig or target_date <= date_key:
                        continue  # Skip today's or past trades (those are handled below)
                    fresh = sentiment_data.get(sym)
                    if not fresh:
                        continue
                    fresh_sent = fresh.get("sentiment", 0)
                    # Cancel if fresh sentiment strongly contradicts the pending trade:
                    # - Pending buy (+1) but fresh sentiment is negative (-1)
                    # - Pending sell (-1) but fresh sentiment is positive (+1)
                    if fresh_sent != 0 and fresh_sent == -sig and cancel_trades:
                        reason = trade.get("reason", "")[:60]
                        # Tier-3 A3 (2026-05-17): macro-event whitelist supersedes
                        # sentiment veto. SNDK's 2025-11-28 "S&P 500 entry" scheduled
                        # buy was cancelled by negative LLM sentiment in BT901920 and
                        # the strategy missed +487% upside. Macro reasons are objectively
                        # verifiable; LLM can warn but cannot veto. Operator can disable
                        # this override with macro_supersedes_sentiment_enabled=False.
                        if (
                            bool(config.get("macro_supersedes_sentiment_enabled", True))
                            and sig == 1  # only protect BUYS — sell cancels stay sentiment-driven
                            and _macro_event_supersedes_sentiment(reason)
                        ):
                            _log(
                                f"  Macro supersedes sentiment: keeping pending buy for {sym} on "
                                f"{target_date} (reason='{reason}' — objectively verifiable; LLM "
                                f"contra-sentiment={fresh_sent} ignored)",
                                "green",
                            )
                            continue
                        removed = cancel_trades(strategy_cache, sym, target_date=target_date)
                        if removed:
                            cancelled_count += len(removed)
                            signal_word = "buy" if sig == 1 else "sell"
                            contra_word = "negative" if fresh_sent == -1 else "positive"
                            _log(
                                f"  Cancelled pending {signal_word} for {sym} on {target_date} "
                                f"(fresh {contra_word} sentiment contradicts: {reason})",
                                "yellow",
                            )
                if cancelled_count > 0:
                    _log(f"Future trade review: cancelled {cancelled_count}/{n_before} trades due to contradicting news", "yellow")
                elif n_before > 0:
                    _log(f"Future trade review: {n_before} pending trades reviewed, all still valid", "cyan")

            # Collect today's pending trades for the voting step
            for sym in symbols_list if (pop_pending_trades and strategy_cache is not None) else []:
                pend = pop_pending_trades(strategy_cache, sym, current_time)
                if pend:
                    pending_by_symbol[sym] = pend
            if pending_by_symbol:
                total_pend = sum(len(v) for v in pending_by_symbol.values())
                _log(f"Future trades: {total_pend} scheduled trade(s) firing today for {len(pending_by_symbol)} symbols", "green")

        # ── 3) Neo4j graph contagion propagation ─────────────────────────
        # (propagated already initialized above, before trend sell enforcement)
        # Pass cached institutional co-holdings through config for lookback reuse.
        # Check in-memory cache first, then fall back to RethinkDB persistent cache.
        _inst_rdb_key, _inst_scope_metadata = _institutional_cache_binding(
            point_in_time_context,
            base_instance_id or instance_id,
            date_key,
        )
        _strict_inst_scope = bool(
            point_in_time_context is not None
            and not point_in_time_context.is_live
            and point_in_time_context.strict
        )
        if (
            (historical_lookback_mode or _strict_inst_scope)
            and strategy_cache is not None
        ):
            _cached_inst = strategy_cache.get("_inst_co_holdings_cache")
            _cached_inst_scope = strategy_cache.get(
                "_inst_co_holdings_cache_scope"
            )
            if (
                _cached_inst is not None
                and (
                    not _strict_inst_scope
                    or _cached_inst_scope == _inst_scope_metadata
                )
            ):
                config["_inst_co_holdings_cache"] = _cached_inst
        if config.get("_inst_co_holdings_cache") is None and conn is not None and _nexus_db_available:
            try:
                _ensure_learning_cache_table(conn)
                _inst_rdb_cached = _r.db(DB_NAME).table(LEARNING_CACHE_TABLE).get(_inst_rdb_key).run(conn)
                if (
                    _inst_rdb_cached
                    and isinstance(_inst_rdb_cached.get("edges"), list)
                    and _institutional_cache_row_matches(
                        _inst_rdb_cached,
                        point_in_time_context,
                    )
                ):
                    config["_inst_co_holdings_cache"] = _inst_rdb_cached["edges"]
                    _log(f"  Institutional co-holdings: loaded from RethinkDB cache ({len(_inst_rdb_cached['edges'])} edges)", "cyan")
            except Exception as _inst_cache_exc:
                _log(f"Institutional cache WARN: failed to load cached co-holdings: {_inst_cache_exc}", "yellow")
        try:
            with _timed_stage("Neo4j propagation", start_details=f"seed_tickers={len(sentiment_data)} | symbols={len(symbols_list)}"):
                if _shared_neo4j_driver is None:
                    raise RuntimeError("No shared Neo4j driver available")
                # V11.2: Verify driver connectivity before expensive queries — stale bolt
                # connections cause indefinite hangs (BoltStreamingWriteException).
                try:
                    _shared_neo4j_driver.verify_connectivity()
                except Exception as _conn_check_exc:
                    if not _pit_use_legacy_sources(point_in_time_context):
                        from point_in_time_data import PointInTimeDataError

                        raise PointInTimeDataError(
                            "historical graph snapshot connectivity failed"
                        ) from _conn_check_exc
                    _log(f"Neo4j WARN: stale connection detected ({_conn_check_exc}), recreating driver", "yellow")
                    try:
                        _shared_neo4j_driver.close()
                    except Exception:
                        pass
                    if _pit_capture_requested:
                        _log(
                            "PIT capture skipped for this cycle after graph "
                            "driver reconnect",
                            "yellow",
                        )
                        _pit_capture_requested = False
                    _shared_neo4j_driver = _create_nexus_graph_driver(
                        context=point_in_time_context,
                        snapshot_store=point_in_time_store,
                        neo4j_uri=neo4j_uri,
                        neo4j_user=neo4j_user,
                        neo4j_password=neo4j_password,
                        capture_enabled=False,
                    )
                    _log("Neo4j: driver reconnected successfully", "green")
                propagated = _compute_propagated_scores(
                    _shared_neo4j_driver,
                    sentiment_data,
                    symbols_list,
                    config,
                    date_key=date_key,
                    strategy_cache=strategy_cache,
                )
        except Exception as e:
            from point_in_time_data import PointInTimeDataError

            if isinstance(e, PointInTimeDataError):
                raise
            _log(f"Neo4j error: {e}", "yellow")
        # Persist institutional cache to in-memory strategy_cache and RethinkDB for cross-session reuse
        _new_inst = config.get("_inst_co_holdings_cache")
        if _new_inst is not None:
            if (
                (historical_lookback_mode or _strict_inst_scope)
                and strategy_cache is not None
            ):
                strategy_cache["_inst_co_holdings_cache"] = _new_inst
                strategy_cache["_inst_co_holdings_cache_scope"] = dict(
                    _inst_scope_metadata
                )
            if conn is not None and _nexus_db_available:
                try:
                    _inst_cache_row = {
                        "id": _inst_rdb_key,
                        "edges": _new_inst,
                        "cached_at": date_key,
                        **_inst_scope_metadata,
                    }
                    _r.db(DB_NAME).table(LEARNING_CACHE_TABLE).insert(
                        _inst_cache_row,
                        conflict="replace",
                    ).run(conn)
                except Exception as _inst_cache_write_exc:
                    _log(f"Institutional cache WARN: failed to persist co-holdings cache: {_inst_cache_write_exc}", "yellow")

        # ── 3b) Discover stocks from strong propagation signals ─────────
        n_propagated = sum(1 for v in propagated.values() if abs(v.get("raw_score", 0)) >= 0.01)
        _log(f"Propagation complete: {n_propagated} tickers with non-zero raw signal", "green")

        if stock_finder and conn_trends is not None and propagated:
            _prop_discovered = _discover_stocks_from_propagation(
                conn_trends, propagated, instance_id,
                set(symbols_list) | _sold_cooldown | _pruned_this_bar, config, date_key,
            )
            if _prop_discovered:
                _existing_syms = set(symbols_list)
                _existing_disc = set(all_discovered)
                for _pd_ticker in _prop_discovered:
                    if _pd_ticker not in _existing_syms:
                        symbols_list.append(_pd_ticker)
                        _existing_syms.add(_pd_ticker)
                    if _pd_ticker not in _existing_disc:
                        all_discovered.append(_pd_ticker)
                        _existing_disc.add(_pd_ticker)
                    # Add a buy sentiment seed for propagation-discovered tickers
                    if _pd_ticker not in sentiment_data:
                        _pd_raw = propagated.get(_pd_ticker, {}).get("raw_score", 0)
                        sentiment_data[_pd_ticker] = {"sentiment": 1 if _pd_raw > 0 else -1, "event": "graph_propagation"}
                        mentioned.add(_pd_ticker)
                _log(f"Propagation discovery: {len(_prop_discovered)} new ticker(s) added → symbols now {len(symbols_list)}", "green")

        # ── 3c) Sector-peer and competitor-chain discovery ─────────────
        if stock_finder and conn_trends is not None and _shared_neo4j_driver is not None:
            # Identify strong-buy tickers (raw_net >= 1.5x buy_threshold)
            _disc_buy_thresh = float(config.get("buy_threshold", _DEFAULT_BUY_THRESHOLD))
            _strong_thresh = _disc_buy_thresh * 1.5
            _strong_buys: set[str] = set()
            for _sym, _pdata in propagated.items():
                if _pdata.get("raw_score", 0) >= _strong_thresh:
                    _strong_buys.add(_sym)
            # Also include any current symbol with strong sentiment
            for _sym in symbols_list:
                _sd = sentiment_data.get(_sym) or {}
                if _sd.get("sentiment", 0) == 1:
                    _strong_buys.add(_sym)
            if _strong_buys:
                try:
                    with _shared_neo4j_driver.session() as _disc_session:
                        _existing_syms = set(symbols_list) | _sold_cooldown | _pruned_this_bar
                        _sector_disc = _discover_stocks_from_sector_peers(
                            _disc_session, conn_trends, _strong_buys, instance_id,
                            _existing_syms, config, date_key,
                        )
                        _existing_syms.update(_sector_disc)
                        _comp_disc = _discover_stocks_from_competitors(
                            _disc_session, conn_trends, _strong_buys, instance_id,
                            _existing_syms, config, date_key,
                        )
                        _existing_syms.update(_comp_disc)
                        _etf_disc = _discover_stocks_from_etf_co_holdings(
                            _disc_session, conn_trends, _strong_buys, instance_id,
                            _existing_syms, config, date_key,
                        )
                    for _d_ticker in _sector_disc + _comp_disc + _etf_disc:
                        if _d_ticker not in set(symbols_list):
                            symbols_list.append(_d_ticker)
                        if _d_ticker not in set(all_discovered):
                            all_discovered.append(_d_ticker)
                        if _d_ticker not in sentiment_data:
                            sentiment_data[_d_ticker] = {"sentiment": 1, "event": "general"}
                            mentioned.add(_d_ticker)
                    if _sector_disc or _comp_disc or _etf_disc:
                        _log(
                            f"Graph discovery: {len(_sector_disc)} sector peers + {len(_comp_disc)} competitors "
                            f"+ {len(_etf_disc)} ETF co-holdings → symbols now {len(symbols_list)}",
                            "green",
                        )
                except Exception as _disc_exc:
                    _log(f"Graph discovery error: {_disc_exc}", "yellow")

        # ── 3c-bis) Momentum-based discovery ──────────────────────────────
        # Catches sustained price runners (e.g. MU +650%) that aren't in news/events.
        if config.get("momentum_discovery_enabled", True) and conn_trends and (data or strategy_cache):
            try:
                _momentum_disc = _discover_stocks_from_momentum(
                    conn_trends, data, instance_id,
                    set(symbols_list) | _sold_cooldown | _pruned_this_bar,
                    config, date_key,
                    strategy_cache=strategy_cache,
                    alpaca_key=alpaca_key, alpaca_secret=alpaca_secret,
                    active_trends=active_trends,
                )
                for _d_ticker in _momentum_disc:
                    if _d_ticker not in set(symbols_list):
                        symbols_list.append(_d_ticker)
                    if _d_ticker not in set(all_discovered):
                        all_discovered.append(_d_ticker)
                    if _d_ticker not in sentiment_data:
                        sentiment_data[_d_ticker] = {"sentiment": 1, "event": "general"}
                    mentioned.add(_d_ticker)
                if _momentum_disc:
                    _log(
                        f"Momentum discovery: {len(_momentum_disc)} new ticker(s) → symbols now {len(symbols_list)}",
                        "green",
                    )
            except Exception as _mom_exc:
                _log(f"Momentum discovery error: {_mom_exc}", "yellow")

        # ── 3c-ter) Persistent Momentum Watchlist: accumulate + load bars ──
        if config.get("momentum_watchlist_enabled", False) and strategy_cache is not None:
            try:
                # Universal mode: collect every ticker the strategy has awareness of
                _mw_extra_sources: dict[str, list[str]] = {}
                if config.get("momentum_watchlist_universal_mode", False):
                    # Propagation expansion names (where LITE lives)
                    try:
                        _prop_ex = strategy_cache.get("_prop_expansion_set_alloc") or set()
                        if isinstance(_prop_ex, (set, list, tuple)):
                            _mw_extra_sources["prop_expansion"] = list(_prop_ex)
                    except Exception:
                        pass
                    # BFQ pending tickers
                    try:
                        _bfq_tickers = [
                            str((_qe or {}).get("ticker") or "").strip().upper()
                            for _qe in (strategy_cache.get("_backfill_queue") or [])
                            if _qe and str((_qe or {}).get("ticker") or "").strip()
                        ]
                        _mw_extra_sources["bfq_pending"] = _bfq_tickers
                    except Exception:
                        pass
                    # Trend-tracked tickers (source of V31 sell enforcement, includes SNDK)
                    try:
                        _trend_tickers: list[str] = []
                        # 2026-07-24: trends store their list under "affected_tickers";
                        # the old "tickers" key was always absent, so this discovery
                        # source was silently empty every bar. GATED (default off) so
                        # reference runs — which had it empty — stay byte-identical
                        # unless momentum_watchlist_trend_source_enabled is set; when on,
                        # read the correct field. (Feeds the same lane as the reserved
                        # momentum-buy path, so it's a deliberate behavioral change.)
                        _trend_field = ("affected_tickers"
                                        if bool(config.get("momentum_watchlist_trend_source_enabled", False))
                                        else "tickers")
                        for _tr in (active_trends or []):
                            if isinstance(_tr, dict):
                                for _tkr in (_tr.get(_trend_field) or []):
                                    _s = str(_tkr).strip().upper()
                                    if _s:
                                        _trend_tickers.append(_s)
                        _mw_extra_sources["trend_tracked"] = _trend_tickers
                    except Exception:
                        pass
                    # Held positions
                    try:
                        _held_syms = [
                            str(_s).strip().upper()
                            for _s, _q in ((portfolio_emulator._positions or {}).items() if portfolio_emulator is not None else [])
                            if float(_q or 0.0) > 0.0
                        ]
                        _mw_extra_sources["held"] = _held_syms
                    except Exception:
                        pass
                    # Note: has_score source removed — scores dict is finalized at line ~16948,
                    # which is AFTER this block. Scored tickers will be captured by the
                    # _prop_expansion_set_alloc source on bar N+1 due to watchlist persistence.
                    # 2026-07-24 extension-blocked tracking (default OFF): a NEW entry the
                    # extension gate blocked (over-extended runup) is otherwise dropped from
                    # discovery entirely — if its signal was one-shot it vanishes, so a real
                    # mover that first appears already-extended (e.g. a name that ran before
                    # we saw it) is never priced/scored and can't be bought once it pulls
                    # back into range. Feed those blocked names into the watchlist so they
                    # stay priced+scored (EVALUATION ONLY — the buy stays blocked by the gate
                    # until the name is no longer extended). Pruned to a recent lookback.
                    try:
                        if bool(config.get("momentum_watchlist_track_extension_blocked", False)):
                            # Containment (2026-07-25): tracked names are NEVER fed to
                            # the watchlist while the regime reads bear/crash — the
                            # reserved momentum-buy lane bypasses the bear RS gate, so
                            # injecting the frothiest recent runups into a real
                            # downtrend would knife-catch fading rallies. They are
                            # released the first non-bear bar (bt#211684: blocked
                            # 04-07 bear -> released 04-08 chop -> rankable by 04-13
                            # bull). This guard also bounds ..._in_bear recording.
                            _eb_reg_now = str((strategy_cache or {}).get("_market_regime") or "").lower()
                            if _eb_reg_now not in ("bear", "crash"):
                                _eb_track = (strategy_cache or {}).get("_extension_blocked_track") or {}
                                _eb_keep = int(config.get("momentum_watchlist_track_extension_blocked_max", 50) or 50)
                                _mw_extra_sources["extension_blocked"] = [
                                    str(_s).strip().upper() for _s in list(_eb_track.keys())[-_eb_keep:] if _s
                                ]
                    except Exception:
                        pass
                    # Sell enforcement tickers (where SNDK lives)
                    try:
                        _mw_extra_sources["sell_enforce"] = [
                            str(_s).strip().upper()
                            for _s in (nexus_sell_enforcement or set())
                            if _s
                        ]
                    except Exception:
                        pass
                    # 2026-07-24 breadth scan (default OFF): market-wide momentum
                    # movers -> evaluation only. Regime-gated pool + glitch/parabolic
                    # filtered inside _breadth_scan_movers; every buy stays gated. The
                    # bear reserved-buy lane is separately blocked from these names.
                    try:
                        _pit_breadth_kwargs = {}
                        if point_in_time_context is not None:
                            _pit_breadth_kwargs = {
                                "context": point_in_time_context,
                                "snapshot_store": point_in_time_store,
                                "session_close_resolver": session_close_resolver,
                            }
                        _bsm = _breadth_scan_movers(
                            config,
                            strategy_cache,
                            date_key,
                            alpaca_key,
                            alpaca_secret,
                            **_pit_breadth_kwargs,
                        )
                        if _bsm:
                            _mw_extra_sources["breadth_scan"] = _bsm
                    except Exception as _bsm_exc:
                        from point_in_time_data import PointInTimeDataError

                        if isinstance(_bsm_exc, PointInTimeDataError):
                            raise

                _mw = _build_momentum_watchlist(
                    strategy_cache, all_discovered,
                    prices=prices, price_history=data, config=config,
                    extra_sources=_mw_extra_sources or None,
                )
                if _mw:
                    _load_watchlist_bars(
                        _mw, strategy_cache,
                        alpaca_key, alpaca_secret, config, date_key,
                    )
            except Exception as _mw_exc:
                from point_in_time_data import PointInTimeDataError

                if isinstance(_mw_exc, PointInTimeDataError):
                    raise
                _log(f"Momentum watchlist build/load error: {_mw_exc}", "yellow")

        # ── 3c-bis) Momentum rediscovery for previously sold stocks ──────
        _rediscovery_pending_tickers: list[str] = []
        if config.get("momentum_rediscovery_enabled", True) and conn_trends:
            try:
                _rediscovery_results = _rediscover_momentum_comebacks(
                    conn_trends, instance_id,
                    set(symbols_list) | _pruned_this_bar,  # Do NOT exclude _sold_cooldown
                    config, date_key,
                    strategy_cache=strategy_cache,
                    alpaca_key=alpaca_key, alpaca_secret=alpaca_secret,
                )
                for _rd in _rediscovery_results:
                    _rd_ticker = _rd["ticker"]
                    _rediscovery_pending_tickers.append(_rd_ticker)
                    if _rd_ticker not in set(symbols_list):
                        symbols_list.append(_rd_ticker)
                    if _rd_ticker not in set(all_discovered):
                        all_discovered.append(_rd_ticker)
                    if _rd_ticker not in sentiment_data:
                        sentiment_data[_rd_ticker] = {"sentiment": 1, "event": "general"}
                    mentioned.add(_rd_ticker)
                    # Bypass sold cooldown for rediscovered tickers
                    _sold_cooldown.discard(_rd_ticker)
                if _rediscovery_results:
                    _rd_summary = ", ".join(
                        f"{r['ticker']}(20d={r['ret_20d']:+.1f}%)" for r in _rediscovery_results
                    )
                    _log(
                        f"Momentum rediscovery: {len(_rediscovery_results)} comeback ticker(s): {_rd_summary}",
                        "green",
                    )
            except Exception as _rd_exc:
                _log(f"Momentum rediscovery error: {_rd_exc}", "yellow")

        # ── 3c-ter) Sector fill discovery ────────────────────────────────
        # When a sector (e.g. Semiconductors) is flagged bullish, inject
        # top individual stocks from that sector even without news mentions.
        if config.get("sector_fill_discovery_enabled", True) and conn_trends is not None:
            try:
                _sector_fill_disc = _discover_stocks_from_sector_fill(
                    conn_trends, active_trends, instance_id,
                    set(symbols_list) | _sold_cooldown | _pruned_this_bar,
                    config, date_key,
                    portfolio_emulator=portfolio_emulator,
                    active_watchlist_state=_active_watchlist_state,
                )
                for _d_ticker in _sector_fill_disc:
                    if _d_ticker not in set(symbols_list):
                        symbols_list.append(_d_ticker)
                    if _d_ticker not in set(all_discovered):
                        all_discovered.append(_d_ticker)
                    if _d_ticker not in sentiment_data:
                        sentiment_data[_d_ticker] = {"sentiment": 0, "event": "sector_fill"}
                    mentioned.add(_d_ticker)
                if _sector_fill_disc:
                    _log(
                        f"Sector fill discovery: {len(_sector_fill_disc)} new ticker(s) → symbols now {len(symbols_list)}",
                        "green",
                    )
                if conn_trends is not None:
                    all_discovered = _get_all_discovered_stocks(conn_trends, instance_id)
            except Exception as _sf_exc:
                _log(f"Sector fill discovery error: {_sf_exc}", "yellow")

        # ── 3d) Global discovered stock cap enforcement ──────────────────
        # All discovery sources (trend, Benzinga, propagation, sector, competitor) have independent
        # caps, but they can collectively exceed the intended hard limit. Enforce a global ceiling.
        if conn_trends is not None:
            _global_max = int(config.get("max_discovered_stocks", 90) or 90)
            _protected_disc = _normalize_cache_string_set(strategy_cache, "_active_watchlist_priority_tickers")
            if portfolio_emulator is not None:
                _protected_disc.update(
                    str(ticker).strip().upper()
                    for ticker, qty in ((portfolio_emulator._positions or {}).items())
                    if str(ticker).strip() and float(qty or 0.0) > 0.0
                )
            _trimmed_disc = _trim_discovered_stock_cap(
                conn_trends,
                instance_id,
                _global_max,
                date_key=date_key,
                protected_tickers=_protected_disc,
                protect_days=int(config.get("momentum_discovery_protect_days", 10) or 0),
            )
            if _trimmed_disc:
                for _ot in _trimmed_disc:
                    if _ot in all_discovered:
                        all_discovered.remove(_ot)
                    if _ot in symbols_list:
                        symbols_list.remove(_ot)
                _log(f"Global discovery cap: pruned {len(_trimmed_disc)} excess discovered stock(s) (cap={_global_max})", "yellow")
            _log(f"Discovery source usage: {_format_discovery_source_usage(conn_trends, instance_id)}", "cyan")

        # ── 3e) Propagation scoring expansion ────────────────────────────
        # Strongly-propagated tickers that didn't fit into discovery (hard_limit
        # full) are added to symbols_list for scoring THIS bar only — NOT registered
        # in RethinkDB discovery, so they don't count against the discovery cap.
        # Fix 15: _prop_added initialized here so it's accessible after scoring
        # to promote BUY signals to the broker via _nexus_expansion_buys.
        _prop_added: list[str] = []
        _prop_scoring_min = float(config.get("propagation_scoring_min_score",
                                              config.get("buy_threshold", _DEFAULT_BUY_THRESHOLD)))
        _max_prop_slots = int(config.get("max_propagated_scoring_slots", 15))
        if propagated and _max_prop_slots > 0:
            _existing_for_prop = set(symbols_list) | _sold_cooldown | _pruned_this_bar
            _prop_cands = [
                (t, pdata.get("raw_score", 0.0))
                for t, pdata in propagated.items()
                if t not in _existing_for_prop and abs(pdata.get("raw_score", 0.0)) >= _prop_scoring_min
            ]
            _prop_cands.sort(key=lambda x: abs(x[1]), reverse=True)
            _prop_added = [t for t, _ in _prop_cands[:_max_prop_slots]]
            for _pt in _prop_added:
                symbols_list.append(_pt)
            if _prop_added:
                _log(f"Propagation scoring expansion: {len(_prop_added)} ticker(s) added: "
                     f"{', '.join(_prop_added[:10])}", "green")

        # ── 3e-bis) Backfill queue scoring net ───────────────────────────
        # Tickers sitting in the backfill queue need to be in symbols_list
        # so _finalize_scores produces a fresh raw_net_score for them.
        # Without this, broker-skipped propagation stocks (not in discovered
        # table, no open position) silently fall out of the scoring universe
        # and the dequeue check at line ~11876 rejects them with score 0.
        _raw_bfq_pending = (strategy_cache or {}).get("_backfill_queue", [])
        _bfq_pending = _normalize_cached_ticker_entries(_raw_bfq_pending)
        if strategy_cache is not None and _bfq_pending != list(_raw_bfq_pending or []):
            strategy_cache["_backfill_queue"] = list(_bfq_pending)
        if _bfq_pending:
            _bfq_syms_set = set(symbols_list)
            _bfq_scoring_added = []
            for _bfq_entry in _bfq_pending:
                _bfq_t = _bfq_entry.get("ticker", "")
                if _bfq_t and _bfq_t not in _bfq_syms_set:
                    symbols_list.append(_bfq_t)
                    _bfq_syms_set.add(_bfq_t)
                    _bfq_scoring_added.append(_bfq_t)
            if _bfq_scoring_added:
                _log(f"Backfill queue scoring net: {len(_bfq_scoring_added)} ticker(s) added: "
                     f"{', '.join(_bfq_scoring_added)}", "cyan")

        # V7.3: Also ensure broker-skipped tickers get scored for this bar
        _raw_bsk_pending = (strategy_cache or {}).get("_broker_skipped_buys", [])
        _bsk_pending = _normalize_cached_ticker_entries(_raw_bsk_pending)
        if strategy_cache is not None and _bsk_pending != list(_raw_bsk_pending or []):
            strategy_cache["_broker_skipped_buys"] = list(_bsk_pending)
        if _bsk_pending:
            _bsk_syms_set = set(symbols_list)
            _bsk_scoring_added = []
            for _bsk_entry in _bsk_pending:
                _bsk_t = _bsk_entry.get("ticker", "")
                if _bsk_t and _bsk_t not in _bsk_syms_set:
                    symbols_list.append(_bsk_t)
                    _bsk_syms_set.add(_bsk_t)
                    _bsk_scoring_added.append(_bsk_t)
            if _bsk_scoring_added:
                _log(f"Broker-skipped scoring net: {len(_bsk_scoring_added)} ticker(s) added: "
                     f"{', '.join(_bsk_scoring_added)}", "cyan")

        # ── 3f) Open position safety net ─────────────────────────────────
        # Ensure every ticker with an open position is in symbols_list so it can
        # receive sell signals. Catches propagation-expanded buys (Fix 9) and
        # trend-stock buys (Fix 13) that aren't registered in discovery.
        if portfolio_emulator is not None:
            _open_pos = portfolio_emulator._positions or {}
            _safety_syms = set(symbols_list)
            # 2026-07-19: sleeve legs stay out of the universe here too —
            # this net was re-adding SQQQ past the Z2.2 exclusion, feeding
            # it to the monitor/LLM/rotation machinery (BULL_F7d forensics).
            _safety_sleeve = _sleeve_symbols(config)
            _safety_added = [t for t, qty in _open_pos.items()
                             if float(qty or 0) > 0 and t not in _safety_syms
                             and t not in _safety_sleeve]
            for _st in _safety_added:
                symbols_list.append(_st)
            if _safety_added:
                _log(f"Position safety net: {len(_safety_added)} ticker(s) added: "
                     f"{', '.join(_safety_added)}", "yellow")

        # ── 4) Final score mapping ────────────────────────────────────────
        with _timed_stage("Final scoring + ML overlay", start_details=f"symbols={len(symbols_list)} | lookback_days={lookback_learning_days}"):
            scores = _finalize_scores(symbols_list, sentiment_data, propagated, config, pending_by_symbol=pending_by_symbol, portfolio_emulator=portfolio_emulator, date_key=date_key, prices=prices, strategy_cache=strategy_cache, price_history=data)
            scores, candidate_features, overlay_traces = _apply_ml_and_overlay_to_scores(
                symbols_list,
                scores,
                sentiment_data=sentiment_data,
                propagated=propagated,
                finbert_rows=finbert_rows,
                company_rows=company_article_rows,
                macro_rows=macro_rows,
                active_events=active_events,
                conn=conn,
                instance_id=instance_id,
                date_key=date_key,
                strategy_cache=strategy_cache,
                config=config,
                price_history=data,
                portfolio_emulator=portfolio_emulator,
                bz_data=bz_data,
                alpaca_key=alpaca_key,
                alpaca_secret=alpaca_secret,
                active_trends=active_trends,
            )
        # Buy/hold spread. Placed FIRST in the filter chain, before the circuit
        # breaker, because it is the only filter that is part of "what does the
        # ranking say" rather than a portfolio-level risk veto — and because
        # the circuit breaker's mass-liquidation cap should count the sells that
        # will actually be submitted, not the ones the band is about to retract.
        scores = _apply_rank_band_gate(scores, symbols_list, portfolio_emulator, config)
        scores = _apply_portfolio_circuit_breaker(scores, symbols_list, portfolio_emulator, config)
        scores = _apply_buy_price_floor(scores, symbols_list, prices, data, portfolio_emulator, config)
        scores = _apply_quality_filter(scores, symbols_list, prices, data, portfolio_emulator, config, strategy_cache=strategy_cache, date_key=date_key)
        scores = _apply_sector_concentration_limit(scores, symbols_list, config, strategy_cache=strategy_cache)
        _queue_buy_candidates = [s for s in symbols_list if (scores.get(s) or {}).get("score") == 1]
        scores = _apply_portfolio_drawdown_halt(
            scores,
            symbols_list,
            portfolio_emulator,
            config,
            strategy_cache,
            prices,
            data,
            date_key,
        )
        _drawdown_halt_active = bool((((strategy_cache or {}).get("_portfolio_drawdown_state")) or {}).get("halt_active", False))

        # ── 2026-07-25 bear-book trim (default OFF) ──────────────────────────
        # `max_positions_bear` is only an ENTRY gate: a book opened during chop
        # is never trimmed when the regime downgrades, so the portfolio carries
        # decaying longs ALONGSIDE the inverse sleeve — long and short the same
        # market, paying both. Injected HERE, after the ML overlay (:24416) and
        # the drawdown halt (:24442), so it bypasses grace / winner-protect /
        # sell_block exactly the way the kill tier does.
        #
        # `_forced_exit=True` is the load-bearing flag: the forced-exit sweep
        # (search `_forced_exit` + `nexus_sell_enforcement.add`) is what puts the
        # symbol into nexus_sell_enforcement with sell_fraction=1.0. Enforcement
        # is then what actually moves it — the broker's V7.5 injector adds held
        # enforcement names to expanded_symbols and the decision override forces
        # decision=-1 (search `nexus_sell_enforcement` in broker.py). Without the
        # flag the sweep skips the symbol and the sell can be dropped for any
        # held name that has aged out of the discovery universe.
        # The "Circuit breaker" reason is kept for consistency with the kill tier
        # and for log greppability, but note it is NOT load-bearing here:
        # _finalize_scores computes _forced_exit from the reason EARLIER in the
        # cycle than this injection, so we must set the flag explicitly.
        # KNOWN LIMITATION (measured, not theoretical): `sell_syms` is rebuilt
        # downstream from score==-1 and feeds _compute_available_buy_budget, so
        # trim proceeds DO raise the same bar's buy budget. The regime position
        # caps (Z4.1 + the backfill headroom gate) are what stop that budget
        # being spent in a bear; this block does not prevent it on its own.
        # KNOWN LIMITATION 2: the V31.3 max-positions breach auto-heal runs later
        # in the cycle over the same book with the same worst-first ordering and
        # is NOT bounded by bear_book_trim_max_per_bar, so on a bar with buy
        # candidates the combined sell count can exceed the per-bar ceiling.
        if bool(config.get("bear_book_trim_enabled", False)) and portfolio_emulator is not None:
            try:
                _bbt_regime = str((strategy_cache or {}).get("_market_regime") or "")
                # Read the EXISTING per-day counter (:23411), not a per-bar one:
                # it is the single source of truth shared with the conviction
                # SQQQ scale-up (broker.py:2904/3073), so the hedge scale-up and
                # the long cut arm on the same bar.
                _bbt_dwell = int((strategy_cache or {}).get("_bear_dwell_bars", 0) or 0)
                _bbt_sleeve = _sleeve_symbols(config)
                _bbt_pnl = {}
                _bbt_book = 0
                for _bbt_sym, _bbt_qty in (portfolio_emulator.get_positions() or {}).items():
                    if float(_bbt_qty or 0.0) <= 0.0 or _bbt_sym in _bbt_sleeve:
                        continue
                    _bbt_book += 1   # TRUE book size, even if we cannot price it
                    _bbt_ent = _get_open_position_entry_trade(portfolio_emulator, _bbt_sym)
                    _bbt_ep = float((_bbt_ent or {}).get("price", 0.0) or 0.0)
                    _bbt_cp = _resolve_symbol_price(
                        _bbt_sym, prices, data, portfolio_emulator=portfolio_emulator)
                    if _bbt_ep > 0 and _bbt_cp > 0:
                        _bbt_pnl[_bbt_sym] = ((_bbt_cp / _bbt_ep) - 1.0) * 100.0
                _bbt_targets = _bear_book_trim_targets(
                    config, _bbt_regime, _bbt_dwell, _bbt_pnl,
                    recovery_flag=(strategy_cache or {}).get("_market_regime_recovery"),
                    book_size=_bbt_book,
                )
                _bbt_done = []
                for _bbt_sym in _bbt_targets:
                    _sc = scores.get(_bbt_sym) if isinstance(scores.get(_bbt_sym), dict) else {}
                    if _sc.get("score") == -1:
                        continue  # kill tier / risk pipeline is already exiting it
                    _sc["score"] = -1
                    _sc["action_intent"] = "sell_override"
                    _sc["reason"] = (
                        f"Circuit breaker: bear book trim — {_bbt_dwell} consecutive "
                        f"bear day(s), book {_bbt_book} > cap "
                        f"{_regime_position_cap(config, _bbt_regime)} "
                        f"(pnl {_bbt_pnl.get(_bbt_sym, 0.0):+.1f}%)")[:1500]
                    _sc["_forced_exit"] = True
                    scores[_bbt_sym] = _sc
                    _bbt_done.append(_bbt_sym)
                if _bbt_done:
                    _log(f"Bear book trim: selling {len(_bbt_done)} long(s) "
                         f"(dwell={_bbt_dwell}d, regime={_bbt_regime}): "
                         f"{', '.join(_bbt_done)}", "red")
            except Exception as _bbt_exc:
                _log(f"Bear book trim skipped (non-fatal): "
                     f"{type(_bbt_exc).__name__}: {_bbt_exc}", "yellow")

        # ── A4 post_sell_watch re-entry phase (BT136708 P1.7, 2026-05-18) ────
        # The Tier-3 spec defined the data plumbing for forced-exit re-entry
        # but never wired the daily eligibility scan into the buy slate. As a
        # result, SNDK's Nov-21 forced-exit had no auto-re-entry path; the
        # eventual re-buy came 47 days late via momentum rotation and missed
        # the +619% recovery to $1407. This phase reads post_sell_watch rows
        # (DB in live, in-memory in backtest), checks recovery eligibility
        # (current_price >= exit×1.05 OR 10d resistance break) AND fresh
        # raw_score >= 0.40, and injects eligible candidates into the buy
        # scoring dict so the existing slate planner picks them up.
        # Feature-flagged OFF by default — operator enables with
        # post_sell_watch_reentry_execution_enabled=True for A/B validation.
        if (
            bool(config.get("post_sell_watch_reentry_execution_enabled", False))
            and not bool(config.get("historical_lookback_mode", False))
        ):
            try:
                _a4_window_days = int(config.get("post_sell_watch_window_days", 60) or 60)
                _a4_held_set = {
                    str(_sym).strip().upper()
                    for _sym, _qty in ((portfolio_emulator._positions or {}).items()
                                       if portfolio_emulator is not None else [])
                    if float(_qty or 0.0) > 0.0
                }
                _a4_candidates = _get_post_sell_watch_candidates_combined(
                    conn_trends, strategy_cache, instance_id, date_key,
                    window_days=_a4_window_days,
                )
                _a4_reentries: list[str] = []
                _a4_skipped_held = 0
                _a4_skipped_eligibility = 0
                for _a4 in _a4_candidates:
                    _a4_sym = str(_a4.get("ticker") or "").strip().upper()
                    if not _a4_sym:
                        continue
                    if _a4_sym in _a4_held_set:
                        _a4_skipped_held += 1
                        continue
                    _a4_existing = scores.get(_a4_sym)
                    if isinstance(_a4_existing, dict) and int(_a4_existing.get("score", 0) or 0) != 0:
                        # Already has a buy or sell signal from regular pipeline — skip.
                        continue
                    _a4_cur_price = _resolve_symbol_price(
                        _a4_sym, prices, data, portfolio_emulator=portfolio_emulator,
                    )
                    try:
                        _a4_cur_price_f = float(_a4_cur_price or 0.0)
                    except (TypeError, ValueError):
                        _a4_cur_price_f = 0.0
                    if _a4_cur_price_f <= 0:
                        continue
                    _a4_fresh_raw = 0.0
                    _a4_prop = (propagated or {}).get(_a4_sym) or {}
                    if isinstance(_a4_prop, dict):
                        try:
                            _a4_fresh_raw = float(_a4_prop.get("raw_score", 0.0) or 0.0)
                        except (TypeError, ValueError):
                            _a4_fresh_raw = 0.0
                    _a4_ok, _a4_reason_text = _is_post_sell_reentry_eligible(
                        current_price=_a4_cur_price_f,
                        exit_price=float(_a4.get("exit_price") or 0.0),
                        fresh_raw_score=_a4_fresh_raw,
                        config=config,
                        recent_high_after_exit=None,
                    )
                    if not _a4_ok:
                        _a4_skipped_eligibility += 1
                        continue
                    scores[_a4_sym] = {
                        "score": 1,
                        "reason": f"A4 re-entry: {_a4_reason_text} (exited={_a4.get('exit_date', '?')})"[:1500],
                        "raw_net_score": _a4_fresh_raw,
                        "n_paths": int((_a4_existing or {}).get("n_paths", 0) or 0) if isinstance(_a4_existing, dict) else 0,
                        "action_intent": "buy",
                        "_is_post_sell_reentry": True,
                        "_reentry_exit_price": float(_a4.get("exit_price") or 0.0),
                        "_reentry_size_fraction": float(
                            config.get("post_sell_reentry_size_fraction", 0.50) or 0.50
                        ),
                    }
                    if _a4_sym not in symbols_list:
                        symbols_list.append(_a4_sym)
                    _a4_reentries.append(_a4_sym)
                if _a4_reentries:
                    _log(
                        f"A4 re-entry phase: added {len(_a4_reentries)} candidate(s) to buy "
                        f"slate: {', '.join(_a4_reentries[:8])} "
                        f"(skipped_held={_a4_skipped_held}, skipped_eligibility={_a4_skipped_eligibility})",
                        "magenta",
                    )
                # TTL sweep on in-memory storage so old rows don't linger past
                # the watch window. DB sweep happens elsewhere (live cooldown).
                if not _GN_LIVE_MODE_FLAG:
                    _post_sell_watch_inmem_forget_expired(
                        strategy_cache, date_key, window_days=_a4_window_days,
                    )
            except Exception as _a4_exc:
                _log(f"A4 re-entry phase error (non-fatal): {_a4_exc}", "yellow")

        buys = sum(1 for v in scores.values() if (v.get("score") if isinstance(v, dict) else v) == 1)
        sells = sum(1 for v in scores.values() if (v.get("score") if isinstance(v, dict) else v) == -1)
        holds = len(symbols_list) - buys - sells
        _log(f"Pre-sizing signals: {buys} buy, {sells} sell, {holds} hold", "green")
        buy_syms = [s for s in symbols_list if (scores.get(s) or {}).get("score") == 1]
        sell_syms = [s for s in symbols_list if (scores.get(s) or {}).get("score") == -1]
        # 2026-04-30 v2 Task G: filter sell_syms by held set ONLY in live
        # mode AND when adapter positions snapshot is fresh. Backtest
        # path unchanged for determinism. Stale-aware to avoid silently
        # dropping real sells when adapter cache went stale during a
        # REST outage.
        if _GN_LIVE_MODE_FLAG and portfolio_emulator is not None:
            try:
                _stale = getattr(portfolio_emulator, "_positions_stale_since", None)
                if _stale is None:
                    _held_syms = {
                        str(k).strip().upper()
                        for k, v in (portfolio_emulator.get_positions() or {}).items()
                        if float(v or 0) > 0
                    }
                    _phantom = [s for s in sell_syms if str(s).strip().upper() not in _held_syms]
                    if _phantom:
                        _log(
                            f"Phantom sells suppressed (not held): "
                            f"{', '.join(_phantom[:8])}{'...' if len(_phantom) > 8 else ''}",
                            "yellow",
                        )
                        sell_syms = [s for s in sell_syms if str(s).strip().upper() in _held_syms]
                        for _ph in _phantom:
                            sd = scores.get(_ph)
                            if isinstance(sd, dict):
                                sd["score"] = 0
                                sd["reason"] = (sd.get("reason") or "") + " [phantom-sell-suppressed]"
                else:
                    _log(
                        f"Phantom-sell filter SKIPPED: positions cache stale "
                        f"(since={_stale}); preserving all sell signals",
                        "yellow",
                    )
            except Exception as _ph_exc:
                _log(f"Phantom-sell filter error: {_ph_exc}", "yellow")

        # Fix 15: Identify propagation-expansion tickers that got BUY signals.
        # These were added to symbols_list for scoring but NOT to all_discovered,
        # so the broker would otherwise filter them out. Promote them via a
        # separate metadata key so they bypass the discovery cap.
        _prop_expansion_set = set(_prop_added) if _prop_added else set()
        _prop_expansion_buys = [s for s in buy_syms if s in _prop_expansion_set]
        # V7.3: Filter blacklisted tickers from expansion buys
        _fl_blacklist = _normalize_cache_mapping(strategy_cache, "_fast_loser_blacklist")
        _prop_expansion_buys = [s for s in _prop_expansion_buys if s not in _fl_blacklist]
        _watchlist_member_tickers = _get_sector_watchlist_tickers(config)
        _watchlist_priority_tickers = _normalize_cache_string_set(strategy_cache, "_active_watchlist_priority_tickers")
        if strategy_cache is not None:
            strategy_cache["_prop_expansion_set_alloc"] = set(_prop_expansion_buys) if _prop_expansion_buys else set()
        for _sym_key, _score_doc in list(scores.items()):
            if not isinstance(_score_doc, dict) or str(_sym_key).startswith("_"):
                continue
            _candidate_meta = _build_nexus_candidate_meta(
                _sym_key,
                _score_doc,
                config,
                strategy_cache=strategy_cache,
                is_propagation_expansion=_sym_key in _prop_expansion_set,
                is_watchlist_member=_sym_key in _watchlist_member_tickers,
                is_watchlist_priority=_sym_key in _watchlist_priority_tickers,
            )
            _score_doc.setdefault("signal_source", _candidate_meta["signal_source"])
            _score_doc["is_watchlist_member"] = bool(_candidate_meta["is_watchlist_member"])
            _score_doc["is_watchlist_priority"] = bool(_candidate_meta["is_watchlist_priority"])
            _score_doc["is_propagation_expansion"] = bool(_candidate_meta["is_propagation_expansion"])
            _score_doc["grace_eligible"] = bool(_candidate_meta["grace_eligible"])
        if _prop_expansion_buys:
            _log(f"Propagation expansion buys (promoted): {', '.join(_prop_expansion_buys)}", "green")

        if buy_syms:
            reasons = [(s, (scores.get(s) or {}).get("reason", "")[:60]) for s in buy_syms[:5]]
            _log("  Buy: " + ", ".join(f"{s} ({r})" for s, r in reasons), "green")
        if sell_syms:
            reasons = [(s, (scores.get(s) or {}).get("reason", "")[:60]) for s in sell_syms[:5]]
            _log("  Sell: " + ", ".join(f"{s} ({r})" for s, r in reasons), "red")

        # ── 4b) Prune discovered stocks with consecutive sell signals ─────
        if conn_trends is not None and all_discovered:
            _consec_sell_limit = int(config.get("consecutive_sell_days_to_prune", 10))
            _sell_pruned = []
            for d_ticker in list(all_discovered):
                got_sell = d_ticker in sell_syms
                new_count = _update_discovered_stock_sell_streak(
                    conn_trends, instance_id, d_ticker, date_key, got_sell,
                )
                if got_sell and new_count >= _consec_sell_limit:
                    # Propagation gate: don't prune if graph still supports this ticker
                    _prop_score = propagated.get(d_ticker, {}).get("raw_score", 0.0) if propagated else 0.0
                    _prune_buy_thresh = float(config.get("buy_threshold", _DEFAULT_BUY_THRESHOLD))
                    if _prop_score >= _prune_buy_thresh:
                        _log(f"Sell enforcement: {d_ticker} has {new_count} consecutive sells but propagation score {_prop_score:.3f} >= {_prune_buy_thresh:.3f} — keeping", "cyan")
                        continue
                    _mark_discovered_stock_sold(
                        conn_trends, instance_id, d_ticker,
                        f"Consecutive sell signals ({new_count} days)",
                        date_key=date_key,
                    )
                    all_discovered.remove(d_ticker)
                    _sell_pruned.append(d_ticker)
                    # Also enforce sell in position sizing
                    nexus_sell_enforcement.add(d_ticker)
            if _sell_pruned:
                _log(f"Pruned {len(_sell_pruned)} discovered stock(s) (consecutive sells >= {_consec_sell_limit}d): {', '.join(_sell_pruned)}", "yellow")

        # ── 5) Compute position sizes ─────────────────────────────────────
        # Determine portfolio total with last-price / history fallback so risk gates
        # still work when a held ticker is missing from the current prices dict.
        portfolio_total = _portfolio_value_with_fallback(portfolio_emulator, prices, data) if portfolio_emulator is not None else 0.0

        # Separate buy signals: regular stocks vs trend ETFs
        etf_set = set(all_etf_discovered) if etf_allocation else set()
        stock_buys = [s for s in buy_syms if s not in etf_set]
        etf_buys = [s for s in buy_syms if s in etf_set]
        # V31 Section 1.2: build the recent-sell blacklist once per bar.
        # Used by both BFQ collection and the main slate planner.
        _v31_blocked_set = _build_recent_sell_block_set(
            portfolio_emulator, prices, data, date_key, config
        )
        # Change 3: Exempt momentum watchlist tickers from re-entry blacklist.
        # Momentum philosophy is "keep monitoring — buy back on renewed strength."
        # SNDK/LITE/MU-class names should never be locked out post-sell if they
        # remain in the persistent momentum watchlist.
        if _v31_blocked_set and config.get("momentum_watchlist_enabled", False) and strategy_cache is not None:
            _mw_all = set((strategy_cache.get("_momentum_watchlist") or {}).keys())
            # 2026-07-24: a name in the watchlist ONLY because the extension gate
            # blocked it (Fix A tracking) must NOT gain re-entry-blacklist exemption —
            # a just-stopped-out name should stay locked out, not become re-buyable via
            # the tracking path. Exclude the tracked set from the exemption (inert when
            # Fix A is off: the tracked set is empty).
            _mw_all = _mw_all - set((strategy_cache.get("_extension_blocked_track") or {}).keys())
            if _mw_all:
                _exempt = _v31_blocked_set & _mw_all
                if _exempt:
                    _v31_blocked_set = _v31_blocked_set - _mw_all
                    _log(
                        f"V31 blacklist exempt (momentum watchlist): {len(_exempt)} ticker(s) "
                        f"({', '.join(sorted(_exempt)[:8])}{'...' if len(_exempt) > 8 else ''})",
                        "magenta",
                    )
        if _v31_blocked_set:
            _log(
                f"V31 re-entry blacklist active: {len(_v31_blocked_set)} ticker(s) "
                f"({', '.join(sorted(_v31_blocked_set)[:8])}{'...' if len(_v31_blocked_set) > 8 else ''})",
                "yellow",
            )
        _queue_stock_buys = _collect_backfill_queue_candidates(
            _queue_buy_candidates,
            stock_buys,
            etf_set,
            scores,
            _prop_expansion_buys,
            blocked_tickers=_v31_blocked_set,
        )
        _queue_recovered = [s for s in _queue_stock_buys if s not in set(stock_buys)]
        if _queue_recovered:
            _log(
                f"Backfill queue candidate recovery: {len(_queue_recovered)} extra final buy(s) kept for queue "
                f"({', '.join(_queue_recovered[:8])}{'...' if len(_queue_recovered) > 8 else ''})",
                "cyan",
            )

        # Fix 6: ETF buy cap per day — keep top N ETFs by signal strength
        max_etf_buys_per_day = int(config.get("max_etf_buys_per_day", 3))
        etf_buys_scored = sorted(
            etf_buys,
            key=lambda sym: (
                -abs(float((scores.get(sym) or {}).get("raw_net_score", 0.0) or 0.0)),
                str(sym),
            ),
        )

        # V6 Fix E: ETF sector deduplication — max 1 ETF per sector/theme
        _etf_sector_map = [
            ("semiconductor", ["smh", "soxx", "soxq", "psi", "ftxl"]),
            ("silver", ["slv", "pslv", "sivr"]),
            ("gold", ["gld", "gldm", "iau", "sgol"]),
            ("oil", ["uso", "uco", "bno", "oih", "xle", "xop"]),
            ("natgas", ["ung", "boil", "kold", "dgaz"]),
            ("biotech", ["xbi", "ibb", "labu"]),
            ("tech", ["qqq", "vgt", "xlk"]),
            ("broad", ["spy", "voo", "iwm", "dia"]),
        ]
        _etf_seen_sectors = set()
        _etf_deduped = []
        # Also check held ETF positions
        _held_etf_sectors = set()
        if portfolio_emulator is not None:
            for _et in (portfolio_emulator._positions or {}):
                if float((portfolio_emulator._positions or {}).get(_et, 0)) > 0:
                    _et_lower = _et.lower()
                    for _sector, _tickers in _etf_sector_map:
                        if _et_lower in _tickers:
                            _held_etf_sectors.add(_sector)
                            break

        for _etf in etf_buys_scored:
            _etf_lower = _etf.lower()
            _etf_sector = "other"
            for _sector, _tickers in _etf_sector_map:
                if _etf_lower in _tickers:
                    _etf_sector = _sector
                    break
            if _etf_sector not in _etf_seen_sectors and _etf_sector not in _held_etf_sectors:
                _etf_deduped.append(_etf)
                _etf_seen_sectors.add(_etf_sector)
            elif _etf_sector == "other":
                _etf_deduped.append(_etf)  # Unknown sector, allow

        etf_buys_scored = _etf_deduped  # Replace with deduped list before cap

        if len(etf_buys_scored) > max_etf_buys_per_day:
            dropped = etf_buys_scored[max_etf_buys_per_day:]
            etf_buys = etf_buys_scored[:max_etf_buys_per_day]
            _log(f"ETF buy cap: kept top {max_etf_buys_per_day}, dropped {', '.join(dropped)}", "cyan")
        else:
            etf_buys = etf_buys_scored

        # Tiered position sizing for stocks (V3 allocation)
        nexus_position_sizes: dict[str, dict] = {}
        _deferred_stock_slate_candidates: set[str] = set()

        # V7.3: Filter out fast-loser blacklisted tickers (unconditional — must decay every bar)
        _fl_blacklist = (strategy_cache or {}).get("_fast_loser_blacklist", {})
        # Decrement bars_remaining and remove expired entries
        _fl_expired = [k for k, v in _fl_blacklist.items() if v.get("bars_remaining", 0) <= 0]
        for _fle in _fl_expired:
            del _fl_blacklist[_fle]
        if _fl_expired:
            _log(f"Blacklist expired: {', '.join(_fl_expired)} ({len(_fl_blacklist)} remaining)", "cyan")
        for _flk in _fl_blacklist:
            if not _fl_blacklist[_flk].get("_created_this_bar"):
                _fl_blacklist[_flk]["bars_remaining"] = _fl_blacklist[_flk].get("bars_remaining", 0) - 1
            else:
                _fl_blacklist[_flk].pop("_created_this_bar", None)

        # P3 SNDK-fix (2026-04-29): align default with priority_min_position_size
        # (100) and _min_pos_final (100). Was 50 — when config was missing the key,
        # _plan_executable_stock_buy_slate's feasibility check used $50 here while
        # the post-rescale undersized-drop used $100, allowing $50–$99 sub-floor
        # buys to slip through.
        _min_position_size = float(config.get("min_position_size", 100.0) or 100.0)
        _rotation_sell_size_overrides: dict[str, dict[str, float]] = {}
        _prelim_sell_sizes: dict[str, dict[str, float]] = {}
        for _sell_sym in sell_syms:
            _sell_fraction = float(
                ((scores.get(_sell_sym) or {}).get(
                    "sell_fraction",
                    (sentiment_data.get(_sell_sym) or {}).get("sell_pct", 1.0),
                ) or 1.0)
            )
            _sell_fraction = max(0.01, min(1.0, _sell_fraction))
            _prelim_sell_sizes[_sell_sym] = {"sell_fraction": _sell_fraction}
        for _sell_sym in nexus_sell_enforcement:
            _prelim_sell_sizes[_sell_sym] = {"sell_fraction": 1.0}
        _available_buy_budget, _buy_budget_meta = _compute_available_buy_budget(
            portfolio_emulator,
            prices,
            data,
            sell_syms,
            _prelim_sell_sizes,
            config,
            strategy_cache,
            current_time,
            date_key,
        )
        if (stock_buys or etf_buys) and portfolio_emulator is not None:
            _log(
                f"Buy budget: spendable=${_available_buy_budget:.0f} "
                f"(cash=${_buy_budget_meta.get('cash_now', 0):.0f}, sells=${_buy_budget_meta.get('sell_proceeds', 0):.0f}, "
                f"floor=${_buy_budget_meta.get('cash_floor', 0):.0f}, ramp={_buy_budget_meta.get('ramp_cap_pct', 1.0):.0%})",
                "cyan",
            )
        _reserve_release_budget = _compute_releasable_cash_reserve(
            _buy_budget_meta,
            stock_buys,
            scores,
            portfolio_emulator,
            config,
        )
        if _reserve_release_budget > 0:
            _available_buy_budget += _reserve_release_budget
            _log(
                f"Cash reserve release: +${_reserve_release_budget:.0f} enabled for high-conviction buys "
                f"(open_positions={_count_open_positions(portfolio_emulator)}, min_positions={int(config.get('cash_reserve_hard_min_positions', 5) or 5)})",
                "yellow",
            )
        _spy_20d = _spy_20d_return(strategy_cache, date_key)
        _macro_risk_scale, _macro_risk_meta = _compute_macro_risk_scale(
            macro_rows, active_events, config, spy_20d_return=_spy_20d
        )
        if _available_buy_budget > 0 and _macro_risk_scale < 0.999:
            _scaled_buy_budget = _available_buy_budget * _macro_risk_scale
            _log(
                f"Macro risk scaling: bearish={_macro_risk_meta.get('bearish_score', 0.0):.2f} "
                f"bullish={_macro_risk_meta.get('bullish_score', 0.0):.2f} "
                f"net={_macro_risk_meta.get('net_score', 0.0):+.2f} "
                f"spy_20d={_spy_20d if _spy_20d is None else f'{_spy_20d*100:+.2f}%'} "
                f"-> buy budget ${_available_buy_budget:.0f} -> ${_scaled_buy_budget:.0f}",
                "yellow",
            )
            _available_buy_budget = _scaled_buy_budget
        elif (
            _available_buy_budget > 0
            and _spy_20d is not None
            and _spy_20d >= 0
            and float(_macro_risk_meta.get("net_score", 0.0) or 0.0) < 0
        ):
            # Only log SUPPRESSED when macro WOULD have wanted to haircut
            # (net_score < 0) but SPY 20d disagreed. Avoids per-bar spam
            # on healthy bull tapes with bullish macro.
            _log(
                f"Macro risk scaling: SUPPRESSED (SPY 20d={_spy_20d*100:+.2f}% >= 0, "
                f"price action contradicts macro net={_macro_risk_meta.get('net_score', 0.0):+.2f})",
                "cyan",
            )

        # ── Buy budget floor: never let budget fall below X% of portfolio ──
        _buy_floor_pct = float(config.get("buy_budget_floor_pct", 0) or 0)
        if _buy_floor_pct > 0 and portfolio_total > 0:
            _buy_floor = portfolio_total * _buy_floor_pct
            if _available_buy_budget < _buy_floor:
                _log(f"Buy budget floor: ${_available_buy_budget:.0f} -> ${_buy_floor:.0f} (floor={_buy_floor_pct:.0%} of ${portfolio_total:.0f})", "yellow")
                _available_buy_budget = _buy_floor

        # ── Market downtrend protection: liquidate underperformers during broad selloffs ──
        _downtrend_active = False
        if config.get("downtrend_protection_enabled", False) and portfolio_emulator is not None:
            _dt_bearish_threshold = float(config.get("downtrend_protection_bearish_threshold", -30))
            _dt_consec_bars = int(config.get("downtrend_protection_consecutive_bars", 3))
            _dt_net = float(_macro_risk_meta.get("net_score", 0.0))
            # Track consecutive bearish bars in strategy_cache
            _dt_tracker = strategy_cache.get("_downtrend_consecutive_bars", 0) if strategy_cache else 0
            if _dt_net <= _dt_bearish_threshold:
                _dt_tracker += 1
            else:
                _dt_tracker = 0
            if strategy_cache is not None:
                strategy_cache["_downtrend_consecutive_bars"] = _dt_tracker
            if _dt_tracker >= _dt_consec_bars:
                _downtrend_active = True
                _dt_sell_threshold = float(config.get("downtrend_protection_sell_underperformers_pct", -3.0))
                _dt_max_buys = int(config.get("downtrend_protection_max_buys_override", 2))
                _dt_sold_count = 0
                # Force-sell positions below the underperformer threshold
                _positions = getattr(portfolio_emulator, "_positions", {}) or {}
                for _dt_sym, _dt_qty in list(_positions.items()):
                    if float(_dt_qty or 0) <= 0:
                        continue
                    _dt_snap = _build_position_health_snapshot(
                        _dt_sym, portfolio_emulator=portfolio_emulator,
                        prices=prices, price_history=data,
                        strategy_cache=strategy_cache, date_key=date_key,
                    )
                    _dt_pnl = float(_dt_snap.get("unrealized_pct", 0.0))
                    if _dt_pnl <= _dt_sell_threshold:
                        # Add to sell enforcement
                        nexus_sell_enforcement.add(_dt_sym)
                        if _dt_sym not in sentiment_data:
                            sentiment_data[_dt_sym] = {"sentiment": -1, "event": "general"}
                        else:
                            sentiment_data[_dt_sym]["sentiment"] = -1
                        _dt_sold_count += 1
                _log(
                    f"Downtrend protection ACTIVE: net={_dt_net:+.1f} for {_dt_tracker} bars "
                    f"(threshold={_dt_bearish_threshold}), sold {_dt_sold_count} underperformer(s) "
                    f"below {_dt_sell_threshold}%, max_buys capped to {_dt_max_buys}",
                    "red",
                )

        _backfill_queue_already_pending = bool(_bfq_pending)
        _backfill_reserve_requested = _should_reserve_backfill_budget(
            _backfill_queue_already_pending,
            _queue_stock_buys if "_queue_stock_buys" in locals() else stock_buys,
            _bsk_pending,
        )
        # V26 Fix C: detect any pending backfill / broker-skipped item with a
        # high-conviction raw_net_score so the partition function bumps the
        # reserve from 0.20 -> 0.35. The threshold is config-driven for parity
        # with the high_conviction flag used by Fix A1.
        _hc_threshold_partition = float(
            config.get("nexus_high_conviction_threshold", 1.5) or 1.5
        )
        def _has_hc_item(items: list | None) -> bool:
            for _it in items or []:
                if not isinstance(_it, dict):
                    continue
                if float(_it.get("raw_net_score", 0.0) or 0.0) >= _hc_threshold_partition:
                    return True
            return False
        _has_hc_in_queue = _has_hc_item(_bfq_pending) or _has_hc_item(_bsk_pending)
        _primary_buy_budget, _reserved_backfill_budget = _compute_backfill_budget_partition(
            _available_buy_budget,
            _backfill_reserve_requested,
            config,
            has_high_conviction_in_queue=_has_hc_in_queue,
        )
        if _reserved_backfill_budget > 0:
            _effective_reserve_pct = (
                float(
                    config.get("backfill_budget_reserve_pct_high_conviction", 0.25)
                    or 0.25
                )
                if _has_hc_in_queue
                else float(config.get("backfill_budget_reserve_pct", 0.10) or 0.10)
            )
            _log(
                f"Backfill budget reserve: holding ${_reserved_backfill_budget:.0f} "
                f"({_effective_reserve_pct:.0%}) for queued and cash-constrained names"
                f"{' [HIGH-CONVICTION ACTIVE]' if _has_hc_in_queue else ''}",
                "cyan",
            )

        _stock_budget_after_adds = 0.0  # V23: pre-init to avoid UnboundLocalError in backfill queue
        _etf_budget_available = 0.0
        if portfolio_total > 0 and _primary_buy_budget > 0:
            _target_mix_total = 0.0
            if stock_buys:
                _target_mix_total += max(0.0, nexus_portfolio_pct)
            if etf_buys:
                _target_mix_total += max(0.0, etf_portfolio_pct)
            if _target_mix_total <= 0.0:
                _target_mix_total = 1.0
            _stock_budget_available = _primary_buy_budget * (max(0.0, nexus_portfolio_pct) / _target_mix_total) if stock_buys else 0.0
            _etf_budget_available = _primary_buy_budget * (max(0.0, etf_portfolio_pct) / _target_mix_total) if etf_buys else 0.0
            _log(
                f"Budget split: portfolio_total=${portfolio_total:.0f}, primary_buy=${_primary_buy_budget:.0f}, "
                f"stock_budget=${_stock_budget_available:.0f} ({len(stock_buys)} buys), "
                f"etf_budget=${_etf_budget_available:.0f} ({len(etf_buys)} ETF buys), "
                f"mix_total={_target_mix_total:.2f} (stock_pct={nexus_portfolio_pct:.2f}, etf_pct={etf_portfolio_pct:.2f})",
                "cyan",
            )
            # V28 Fix 6: also enter the rotation/queue-promotion block when the
            # backfill queue has pending items (even if stock_buys is empty this
            # bar). Without this, V28 Queue->Rotation promotion never fires on
            # bars where there are no fresh buy signals — and queue items just
            # sit until they expire. The internal logic handles empty stock_buys
            # correctly (sorted([])=[], pools become empty, etc.).
            if stock_buys or _bfq_pending:
                # Sort by raw_net_score for tiered allocation
                stock_buys_scored = sorted(
                    stock_buys or [],
                    key=lambda sym: (
                        -abs(float((scores.get(sym) or {}).get("raw_net_score", 0.0) or 0.0)),
                        str(sym),
                    ),
                )

                # --- V5: Split into pools FIRST, then apply caps per-pool ---
                # This ensures propagation stocks (SNDK, MU) get pool slots
                # before the buy cap truncates by raw_net_score
                _prop_expansion_set_alloc = set(_prop_expansion_buys) if _prop_expansion_buys else set()
                if strategy_cache is not None:
                    strategy_cache["_prop_expansion_set_alloc"] = _prop_expansion_set_alloc
                if config.get("propagation_priority", False):
                    _prop_priority_min_raw = float(config.get("propagation_priority_min_raw", 0.50))
                    _pool_a_candidates = [s for s in stock_buys_scored
                                          if _classify_candidate_signal(s, scores.get(s), strategy_cache=strategy_cache)[1]
                                          and float((propagated or {}).get(s, {}).get("raw_score", 0.0)) >= _prop_priority_min_raw]
                    _pool_b_candidates = [s for s in stock_buys_scored
                                          if s not in set(_pool_a_candidates)]
                else:
                    _pool_a_candidates = [s for s in stock_buys_scored
                                          if not _classify_candidate_signal(s, scores.get(s), strategy_cache=strategy_cache)[1]]
                    _pool_b_candidates = [s for s in stock_buys_scored
                                          if _classify_candidate_signal(s, scores.get(s), strategy_cache=strategy_cache)[1]]

                # V7.3: Filter out fast-loser blacklisted tickers (decay already done above)
                # Filter pools
                _pool_a_candidates = [s for s in _pool_a_candidates if s not in _fl_blacklist]
                _pool_b_candidates = [s for s in _pool_b_candidates if s not in _fl_blacklist]

                # Symmetric overflow
                _pool_a_base = int(config.get("pool_a_base", 10))
                _pool_b_base = int(config.get("pool_b_base", 4))
                _pool_a_min = int(config.get("pool_a_min", 3))
                _pool_b_min = int(config.get("pool_b_min", 2))
                if len(_pool_a_candidates) < _pool_a_min:
                    _pool_b_limit = min(len(_pool_b_candidates), _pool_b_base + (_pool_a_base - len(_pool_a_candidates)))
                    _pool_a_limit = len(_pool_a_candidates)
                elif len(_pool_b_candidates) < _pool_b_min:
                    _pool_a_limit = min(len(_pool_a_candidates), _pool_a_base + (_pool_b_base - len(_pool_b_candidates)))
                    _pool_b_limit = len(_pool_b_candidates)
                else:
                    _pool_a_limit = min(len(_pool_a_candidates), _pool_a_base)
                    _pool_b_limit = min(len(_pool_b_candidates), _pool_b_base)

                # Sequential selection: Pool A first, then Pool B from remainder
                _pool_a_final = _pool_a_candidates[:_pool_a_limit]
                _pool_a_set = set(_pool_a_final)
                _pool_b_final = [s for s in _pool_b_candidates if s not in _pool_a_set][:_pool_b_limit]

                # V5: Interleave pools so truncation cuts proportionally from both
                # [A1,B1,A2,B2,A3,B3] ensures both pools get slots under any cap/headroom
                _interleaved = []
                for _il in range(max(len(_pool_a_final), len(_pool_b_final))):
                    if _il < len(_pool_a_final):
                        _interleaved.append(_pool_a_final[_il])
                    if _il < len(_pool_b_final):
                        _interleaved.append(_pool_b_final[_il])
                stock_buys_scored = _interleaved

                _watchlist_priority_slots = max(0, int(config.get("watchlist_priority_slots", 0) or 0))
                _watchlist_priority_min_raw = float(config.get("watchlist_priority_min_raw_score", 0.35) or 0.35)
                _prop_reserved_slots = max(0, int(config.get("propagation_expansion_reserved_slots", 4) or 4))
                _prop_reserved_min_raw = float(config.get("propagation_expansion_min_raw_score", 0.50) or 0.50)
                _watchlist_priority_requires_active_sector = bool(config.get("watchlist_priority_requires_active_sector", False))
                _priority_front: list[str] = []
                _watchlist_priority: list[str] = []
                _prop_reserved: list[str] = []

                for _sym in stock_buys_scored:
                    _raw_ns = float((scores.get(_sym) or {}).get("raw_net_score", 0.0) or 0.0)
                    _is_watchlist_priority = bool((scores.get(_sym) or {}).get("is_watchlist_priority"))
                    if _watchlist_priority_requires_active_sector and not _is_watchlist_priority:
                        continue
                    if _is_watchlist_priority and _raw_ns >= _watchlist_priority_min_raw and len(_watchlist_priority) < _watchlist_priority_slots:
                        _watchlist_priority.append(_sym)
                for _sym in stock_buys_scored:
                    _raw_ns = float((scores.get(_sym) or {}).get("raw_net_score", 0.0) or 0.0)
                    if _sym in _prop_expansion_set_alloc and _raw_ns >= _prop_reserved_min_raw and _sym not in set(_watchlist_priority) and len(_prop_reserved) < _prop_reserved_slots:
                        _prop_reserved.append(_sym)
                for _sym in _watchlist_priority + _prop_reserved:
                    if _sym not in _priority_front:
                        _priority_front.append(_sym)
                if _priority_front:
                    _priority_front_set = set(_priority_front)
                    stock_buys_scored = _priority_front + [s for s in stock_buys_scored if s not in _priority_front_set]
                    _log(
                        f"Priority sizing order: watchlist={', '.join(_watchlist_priority) if _watchlist_priority else 'none'} | "
                        f"prop_exp={', '.join(_prop_reserved) if _prop_reserved else 'none'}",
                        "cyan",
                    )

                # --- V10: Split held positive-score names from new entries.
                _open_positions_set = {
                    str(_sym).strip().upper()
                    for _sym, _qty in ((portfolio_emulator._positions or {}).items() if portfolio_emulator is not None else [])
                    if float(_qty or 0.0) > 0.0
                }
                _held_add_candidates = [s for s in stock_buys_scored if s in _open_positions_set]
                _new_stock_candidates = [s for s in stock_buys_scored if s not in _open_positions_set]

                # --- Apply new-buy cap + headroom only to new entries ---
                _sell_count = len(sell_syms) if sell_syms else 0
                _base_buy_cap = int(config.get("max_stock_buys_per_day", 8))
                # Downtrend protection: cap buys during sustained bearish conditions
                if _downtrend_active:
                    _dt_cap = int(config.get("downtrend_protection_max_buys_override", 2))
                    _base_buy_cap = min(_base_buy_cap, _dt_cap)
                _effective_buy_cap = min(len(_new_stock_candidates), _base_buy_cap + max(0, _sell_count - _base_buy_cap))
                _new_stock_candidates = _new_stock_candidates[:_effective_buy_cap]

                # ── Momentum Watchlist: score + reserve slots ──────────────────
                _momentum_new_buys: list[dict] = []
                _momentum_held_set: set[str] = set()
                _momentum_held_data: dict[str, dict] = {}
                if config.get("momentum_watchlist_enabled", False) and strategy_cache is not None:
                    try:
                        _mw_ranked = _score_momentum_rank(
                            strategy_cache.get("_momentum_watchlist", {}),
                            strategy_cache, date_key, config,
                        )
                        # Cache scored result for reuse by rotation swap later
                        strategy_cache["_momentum_ranked_cache"] = _mw_ranked
                        # Telemetry for the app's "Nexus momentum" view: a small,
                        # PERSISTED snapshot of the top ranked names (the full
                        # ranked cache above is blacklisted from persistence).
                        # Purely additive — never affects the trade decision.
                        try:
                            strategy_cache["_momentum_ranked_top"] = [
                                [str(_t[0]), float(_t[1])]
                                for _t in list(_mw_ranked)[:25]
                                if isinstance(_t, (list, tuple)) and len(_t) >= 2
                            ]
                        except Exception:
                            pass
                        _momentum_held_data = strategy_cache.get("_momentum_held", {})
                        if not isinstance(_momentum_held_data, dict):
                            _momentum_held_data = {}
                        strategy_cache["_momentum_held"] = _momentum_held_data
                        _momentum_held_set = set(_momentum_held_data.keys())
                        # Update current scores for held momentum positions
                        _mw_scores_lookup = dict(_mw_ranked)
                        for _mh_sym in list(_momentum_held_data.keys()):
                            _momentum_held_data[_mh_sym]["current_score"] = _mw_scores_lookup.get(_mh_sym, 0.0)
                        # Get picks for empty reserved slots.
                        # Codex-required: momentum-sell cooldown to prevent churn
                        # after Change 3 exempted watchlist tickers from the V31
                        # blacklist. Decrements each bar and stores in strategy_cache.
                        _mw_bar_local = int(strategy_cache.get("_deployment_bar_index", 1) or 1)
                        _mw_cooldown_map = strategy_cache.setdefault("_momentum_sell_cooldown", {})
                        # Decrement + expire (once per bar)
                        if strategy_cache.get("_mw_cooldown_decremented_bar") != _mw_bar_local:
                            for _ct in list(_mw_cooldown_map.keys()):
                                _mw_cooldown_map[_ct] = max(0, int(_mw_cooldown_map[_ct]) - 1)
                                if _mw_cooldown_map[_ct] <= 0:
                                    del _mw_cooldown_map[_ct]
                            strategy_cache["_mw_cooldown_decremented_bar"] = _mw_bar_local
                        _mw_cooldown_set = set(_mw_cooldown_map.keys())
                        # ── V31.4 Fix 17: Post-sell breakout re-entry ─────────
                        # If a previously-held ticker breaks above its 20d high
                        # with volume confirmation, lift its cooldown/blacklist
                        # so it can compete on merit. Max 1 re-trigger per bar,
                        # 30-day per-ticker cooldown after Fix 17 rebuy.
                        # ────────────────────────────────────────────────────
                        _ps_enabled = bool(config.get("post_sell_breakout_enabled", True))
                        _ps_blocked_lift: set[str] = set()
                        if _ps_enabled:
                            try:
                                _ps_lookback = int(config.get("post_sell_breakout_lookback_days", 90) or 90)
                                _ps_runup_pct = float(config.get("post_sell_breakout_min_runup_pct", 5.0) or 5.0)
                                _ps_vol_mult = float(config.get("post_sell_breakout_min_volume_mult", 2.0) or 2.0)
                                _ps_reentry_cd_days = int(config.get("post_sell_breakout_reentry_cooldown_days", 30) or 30)
                                _ps_max_per_bar = int(config.get("post_sell_breakout_max_per_bar", 1) or 1)
                                _ps_history = strategy_cache.setdefault("_post_sell_breakout_history", {})
                                _ps_reentry_cd = strategy_cache.setdefault("_post_sell_breakout_reentry_cooldown", {})
                                # Prune history older than lookback; decrement reentry cooldowns.
                                _ps_cur_bar_key = str(date_key or "")
                                _ps_hist_dirty = False
                                for _ps_tk in list(_ps_history.keys()):
                                    _ps_info = _ps_history[_ps_tk]
                                    if not isinstance(_ps_info, dict):
                                        del _ps_history[_ps_tk]
                                        _ps_hist_dirty = True
                                        continue
                                    _ps_sell_bar_int = int(_ps_info.get("sell_bar", 0) or 0)
                                    _ps_age = _mw_bar_local - _ps_sell_bar_int
                                    if _ps_age > _ps_lookback:
                                        del _ps_history[_ps_tk]
                                        _ps_hist_dirty = True
                                # Decrement reentry cooldown once per bar
                                if strategy_cache.get("_ps_reentry_cd_decremented_bar") != _mw_bar_local:
                                    for _ct in list(_ps_reentry_cd.keys()):
                                        _ps_reentry_cd[_ct] = max(0, int(_ps_reentry_cd[_ct]) - 1)
                                        if _ps_reentry_cd[_ct] <= 0:
                                            del _ps_reentry_cd[_ct]
                                    strategy_cache["_ps_reentry_cd_decremented_bar"] = _mw_bar_local
                                # Scan for breakouts
                                _ps_bars_cache = strategy_cache.get("_overlay_bars_raw") or {}
                                _ps_fires = 0
                                for _ps_tk, _ps_info in _ps_history.items():
                                    if _ps_fires >= _ps_max_per_bar:
                                        break
                                    if _ps_tk in _open_positions_set:
                                        continue
                                    if _ps_tk in _ps_reentry_cd:
                                        continue
                                    _ps_bars = _ps_bars_cache.get(_ps_tk) or []
                                    _ps_f = _visible_overlay_bars(
                                        _ps_bars, strategy_cache, date_key, config,
                                    )
                                    _ps_closes = [float(b.get("c", 0) or 0) for b in _ps_f if float(b.get("c", 0) or 0) > 0]
                                    _ps_vols = [float(b.get("v", 0) or 0) for b in _ps_f]
                                    if len(_ps_closes) < 21 or len(_ps_vols) < 21:
                                        continue
                                    _ps_cur = _ps_closes[-1]
                                    _ps_prior_closes = _ps_closes[-21:-1]
                                    _ps_prior_vols = _ps_vols[-21:-1]
                                    if not _ps_prior_closes:
                                        continue
                                    _ps_20d_high = max(_ps_prior_closes)
                                    _ps_vol_avg = sum(_ps_prior_vols) / len(_ps_prior_vols) if _ps_prior_vols else 0.0
                                    _ps_cur_vol = _ps_vols[-1] if _ps_vols else 0.0
                                    _ps_breakout = _ps_cur > _ps_20d_high * (1.0 + _ps_runup_pct / 100.0)
                                    # V31.4 fix: volume gate fail-safe = BLOCK.
                                    # Prior fail-safe=PASS allowed false breakouts when
                                    # volume data was missing (reviewer-flagged).
                                    _ps_vol_ok = (_ps_vol_avg > 0) and (_ps_cur_vol >= _ps_vol_avg * _ps_vol_mult)
                                    # Tier-3 A5 (2026-05-17): add a sell-price-recovery
                                    # shortcut. SNDK exited at $195.77 → V31.4 only
                                    # lifted when price > 20d_high × 1.05 (~$275),
                                    # missing 80% of the recovery. The recovery
                                    # shortcut fires when cur >= sell_price × (1 +
                                    # post_sell_cooldown_lift_threshold_pct) (default
                                    # 10%) so the cooldown lifts as soon as the dip
                                    # measurably reverses, letting Tier-3 A4's
                                    # re-entry pipeline take over earlier.
                                    _ps_sell_price = float(_ps_info.get("sell_price", 0) or 0.0)
                                    _ps_lift_thresh = float(
                                        config.get("post_sell_cooldown_lift_threshold_pct", 0.10)
                                        or 0.10
                                    )
                                    _ps_recovery_shortcut = bool(
                                        _ps_sell_price > 0
                                        and _ps_cur >= _ps_sell_price * (1.0 + _ps_lift_thresh)
                                    )
                                    if (_ps_breakout and _ps_vol_ok) or _ps_recovery_shortcut:
                                        _ps_blocked_lift.add(_ps_tk)
                                        _ps_reentry_cd[_ps_tk] = _ps_reentry_cd_days
                                        _ps_fires += 1
                                        _ps_trigger = (
                                            "recovery_shortcut" if _ps_recovery_shortcut and not (_ps_breakout and _ps_vol_ok)
                                            else "20d_high_breakout"
                                        )
                                        _log(
                                            f"V31.4 post-sell breakout ({_ps_trigger}): lift cooldown for {_ps_tk} "
                                            f"(20d_high={_ps_20d_high:.2f}, cur={_ps_cur:.2f}, "
                                            f"sold={_ps_sell_price:.2f})",
                                            "magenta",
                                        )
                                # Lift cooldown for identified breakout tickers.
                                # V31.4 fix: also delete from underlying cooldown
                                # map so subsequent bars don't re-cooldown the ticker
                                # if the current-bar buy is rejected downstream.
                                if _ps_blocked_lift:
                                    _mw_cooldown_set = _mw_cooldown_set - _ps_blocked_lift
                                    for _ps_lift_sym in _ps_blocked_lift:
                                        if _ps_lift_sym in _mw_cooldown_map:
                                            del _mw_cooldown_map[_ps_lift_sym]
                            except Exception as _ps_exc:
                                _log(f"V31.4 post-sell breakout error: {_ps_exc}", "yellow")
                        # Phase ε.C.6 (BT294837 follow-up, 2026-05-19):
                        # V31.4 lift force-promotion. When the post-sell
                        # breakout / recovery_shortcut lifts a cooldown
                        # this bar, ensure the lifted ticker actually
                        # takes a watchlist slot (don't lose it to higher-
                        # scoring tickers — see ε.B.5 SNDK lifecycle audit).
                        _momentum_new_buys = _reserve_momentum_slots(
                            _mw_ranked, config, _momentum_held_set, _open_positions_set,
                            recent_sell_cooldown=_mw_cooldown_set,
                            force_promote=_ps_blocked_lift if bool(config.get("post_sell_breakout_force_promote_enabled", True)) else None,
                        )
                        # Inject momentum picks into scores + prepend to candidates
                        _existing_candidates_set = set(_new_stock_candidates)
                        for _mp in _momentum_new_buys:
                            _mp_ticker = _mp["ticker"]
                            # V32 Phase 3 B-1: consult fast_loser_blacklist before
                            # admitting via the momentum_watchlist_buy lane. The
                            # blacklist is SET at L13268-13271 but was only READ by
                            # initial_buy / BFQ / prop_expansion lanes. RJET was
                            # blacklisted 2026-01-26 then re-bought via momentum
                            # swap next bar because this lane bypassed the check.
                            _fl_bl_mwb = _normalize_cache_mapping(strategy_cache, "_fast_loser_blacklist") if strategy_cache else {}
                            if _mp_ticker in _fl_bl_mwb:
                                _bl_rem = (_fl_bl_mwb.get(_mp_ticker) or {}).get("bars_remaining", 0)
                                _log(f"V32 P3 B-1 mw_buy blacklist-block: {_mp_ticker} ({_bl_rem} bars remaining)", "yellow")
                                continue
                            # V32 T1-c + T2-a: momentum_watchlist_buy lane gate.
                            # Bug fix: run_once exposes price history as `data`, not `price_history`.
                            try:
                                _mp_buy_price = _resolve_symbol_price(
                                    _mp_ticker, prices, data,
                                    portfolio_emulator=portfolio_emulator,
                                )
                            except Exception:
                                _mp_buy_price = 0.0
                            _mp_raw = float(_mp.get("raw_net_score") or 0.0)
                            _v32_blocked, _v32_reason = _v32_momentum_ath_or_mcap_block(
                                _mp_ticker, _mp_buy_price, data, strategy_cache,
                                config, _mp_raw, log_fn=_log, lane="mw_buy",
                                date_key=date_key,
                            )
                            if _v32_blocked:
                                continue
                            if _mp_ticker not in scores:
                                scores[_mp_ticker] = {}
                            scores[_mp_ticker]["raw_net_score"] = _mp["raw_net_score"]
                            # Phase η bug-sweep: propagate raw_net_natural
                            # (added by η.E) from picks → scores so
                            # downstream consumers (η.G, telemetry) see
                            # the natural-signal value, not just the
                            # floored+differentiated raw_net_score.
                            scores[_mp_ticker]["raw_net_natural"] = _mp.get(
                                "raw_net_natural", _mp["raw_net_score"]
                            )
                            scores[_mp_ticker]["score"] = 1
                            scores[_mp_ticker]["action_intent"] = "momentum_watchlist_buy"
                            scores[_mp_ticker]["momentum_watchlist_score"] = _mp.get("momentum_watchlist_score", 0.0)
                            if _mp_ticker not in _existing_candidates_set:
                                _new_stock_candidates.insert(0, _mp_ticker)
                                _existing_candidates_set.add(_mp_ticker)
                            # Codex fix: register in _active_watchlist_priority_tickers
                            # so _build_nexus_candidate_meta preserves signal_source
                            # and is_watchlist_priority through the allocation pipeline.
                            _normalize_cache_string_set(strategy_cache, "_active_watchlist_priority_tickers").add(_mp_ticker)
                            # Sell protection: remove momentum picks from sell_syms
                            # (sell_syms was built at line ~16894 before momentum override).
                            # Without this, the LLM's -1 score would add sell_fraction
                            # to the same nexus_position_sizes entry, canceling the buy.
                            if _mp_ticker in sell_syms:
                                sell_syms.remove(_mp_ticker)
                            if _mp_ticker in nexus_sell_enforcement:
                                nexus_sell_enforcement.discard(_mp_ticker)
                        if _mw_ranked or _momentum_new_buys:
                            _log(
                                f"Momentum watchlist: watchlist={len(strategy_cache.get('_momentum_watchlist', {}))}, "
                                f"scored={len(_mw_ranked)}, top3={[(t, round(s, 3)) for t, s in _mw_ranked[:3]]}, "
                                f"held_momentum={len(_momentum_held_set & _open_positions_set)}, "
                                f"new_buys={[m['ticker'] for m in _momentum_new_buys]}",
                                "magenta",
                            )
                    except Exception as _mw_score_exc:
                        _log(f"Momentum watchlist score/reserve error: {_mw_score_exc}", "yellow")

                # --- V10: Position rotation with leader lock / break-glass trims ---
                _max_rotations = int(config.get("max_rotations_per_day", 2))
                # V28 Fix 2: separate high-conviction rotation budget that's
                # ADDITIVE to the standard cap. Without this, a single low
                # max_rotations_per_day (1-2) starves the queue when many
                # high-conviction items arrive each bar. With hc=4, the total
                # cap becomes max_rotations + 4 = up to 6 rotations/bar when
                # high-conviction inflows exist.
                _max_rotations_hc = int(config.get("max_rotations_per_day_high_conviction", 4) or 4)
                _rotation_min_delta = float(config.get("rotation_min_delta", 0.15))
                _rotation_min_score = float(config.get("rotation_min_score", 0.40))
                _rotation_min_hold_days = int(config.get("rotation_min_hold_days", 10) or 10)
                _rotation_pairs = []

                # ADDED BY CODEX (Fix 2C): rotation eviction re-buy cooldown.
                # After a ticker is rotation-evicted (full exit), prevent it from being
                # re-bought for `rotation_evict_cooldown_bars` bars to stop flip-flop.
                # Sweep-3 fix: persisted across restarts via RethinkDB so a stop+resume
                # doesn't reset cooldowns mid-backtest.
                _evict_cooldown = _load_evict_cooldown_from_db(conn_trends, instance_id) if conn_trends is not None else {}
                if strategy_cache is not None:
                    # Merge in-memory cache (latest state) over DB-loaded baseline
                    _cache_cd = strategy_cache.get("_rotation_evict_cooldown") or {}
                    for _k, _v in _cache_cd.items():
                        _evict_cooldown[_k] = _v
                    strategy_cache["_rotation_evict_cooldown"] = _evict_cooldown
                # 2026-05-07 granularity-scaling: cooldown is decremented per
                # bar, so a 5-bar default at 3600s = 5 hrs but only 1.7 hrs at
                # 1200s. Scale to keep the flip-flop guard meaningful.
                _evict_cooldown_bars = _scale_bars(int(config.get("rotation_evict_cooldown_bars", 5) or 5), config)
                # Decrement at start of bar; drop expired entries.
                for _t in list(_evict_cooldown.keys()):
                    _evict_cooldown[_t] = max(0, int(_evict_cooldown[_t]) - 1)
                    if _evict_cooldown[_t] <= 0:
                        del _evict_cooldown[_t]
                # Sweep-2 fix: ALSO filter _new_stock_candidates (not just _blocked_buys).
                # The previous sweep only filtered the rotation overflow queue, but a ticker
                # rotated out at bar N could still be re-bought as a regular new entry at
                # bar N+1 if the portfolio had headroom — defeating the cooldown.
                if _evict_cooldown and _new_stock_candidates:
                    _nc_pre_cd = len(_new_stock_candidates)
                    _new_stock_candidates = [s for s in _new_stock_candidates if s not in _evict_cooldown]
                    if len(_new_stock_candidates) < _nc_pre_cd:
                        _log(
                            f"Rotation cooldown: filtered {_nc_pre_cd - len(_new_stock_candidates)} new candidates "
                            f"(cooldown active for {len(_evict_cooldown)} ticker(s))",
                            "yellow",
                        )

                # V28.7: tightened default from 50 -> 15 and added breach diagnostic.
                # Backtest nexus-41 observed 18-25 open positions even with live DB
                # max_positions=15 because rotation/winner_add/BFQ paths bypassed this
                # gate. When breach is detected, block ALL new-ticker entries (including
                # rotation-driven and BFQ-driven swaps) for the bar until count recovers.
                # Held adds and rotation TRIMS (sell side) still flow so the portfolio
                # can naturally shrink toward the cap.
                _max_positions = int(config.get("max_positions", 15) or 15)
                # Z4.1 + Section 5 (2026-05-15): apply regime-based caps so
                # capacity contracts in adverse markets without operator
                # intervention. Defaults preserve current behavior in bull;
                # chop halves the cap, bear quarters, crash halts new buys.
                # Set nexus_regime_capacity_gating_enabled=false to disable.
                if bool(config.get("nexus_regime_capacity_gating_enabled", True)):
                    _z41_spy_20d = _spy_20d_return(strategy_cache, date_key)
                    _z41_v31 = str((strategy_cache or {}).get("_market_regime") or "chop")
                    _z41_vix = (strategy_cache or {}).get("_vix_latest") if isinstance(strategy_cache, dict) else None
                    _z41_regime = _nexus_regime_classify(_z41_spy_20d, _z41_v31, _z41_vix)
                    _z41_latch_on = bool((strategy_cache or {}).get("_bear_capacity_latch"))
                    # BT136708 calibration (2026-05-18): chop default 8 caused
                    # 9-10/8 V28.8.1 breach for ~95% of the run (BFQ stuck at
                    # 48-60 for 175 days, avg 1.98 buys/day vs 6+ capacity).
                    # Raised chop default 8→12 and bear default 4→8 so the
                    # backfill queue can drain.
                    _z41_caps = {
                        "bull":  int(config.get("max_positions_bull",  _max_positions) or _max_positions),
                        "chop":  int(config.get("max_positions_chop",  min(_max_positions, 12)) or 12),
                        "bear":  int(config.get("max_positions_bear",  min(_max_positions, 8)) or 8),
                        "crash": int(config.get("max_positions_crash", 0) or 0),
                    }
                    _z41_capped = _z41_caps.get(_z41_regime, _max_positions)
                    # 2026-07-24 recovery capacity (v2) — see _apply_recovery_cap.
                    _z41_pre_rec = _z41_capped
                    _z41_capped = _apply_recovery_cap(
                        _z41_capped, (strategy_cache or {}).get("_market_regime_recovery"), config)
                    if _z41_capped != _z41_pre_rec:
                        _log(
                            f"Recovery capacity (v2): regime={_z41_regime} recovery-flag ON, "
                            f"cap {_z41_pre_rec}->{_z41_capped}",
                            "cyan",
                        )
                    # 2026-07-30 rally-onset capacity release (default OFF). See
                    # _rally_onset in the detector: on 2026-04-01/04-02 the tape
                    # had reclaimed its 10-day MA and was +2.9%/+3.7% off a 20-day
                    # low set 1-2 sessions earlier, but ret5 (-0.43/-0.24) and
                    # off_low (0.346/0.472) still carried the 03-26..03-30 crash
                    # leg, so the recovery override could not fire and the book
                    # stayed pinned at max_positions_bear=2 (~85% cash) through
                    # the sharpest leg of the rally. Release the CAP only, to the
                    # CHOP cap, and only from "bear" (never crash). The regime
                    # LABEL is unchanged, so the bear RS gate, the extension gate,
                    # the bear-book trim and the sleeve keep their bear behavior.
                    # Only ever raises.
                    if _z41_regime == "bear" and bool(
                            ((strategy_cache or {}).get("_market_regime_diag") or {}).get("rally_onset")):
                        _z41_ro = _z41_caps["chop"]
                        if _z41_ro > _z41_capped:
                            _log(
                                f"Rally-onset capacity: regime={_z41_regime} (label unchanged) "
                                f"cap {_z41_capped}->{_z41_ro}",
                                "cyan",
                            )
                            _z41_capped = _z41_ro
                    # 2026-07-26 bear capacity latch (default OFF). Hold the BEAR
                    # cap through a plain-chop interlude so the bear-book trim's
                    # freed slots are not immediately refilled.
                    #
                    # FLOORED AT THE CURRENT BOOK, deliberately. `_max_positions`
                    # is not only the entry cap -- it is also the breach trigger
                    # below (`_current_positions > _max_positions`), and the
                    # breach auto-heal has NO per-bar ceiling. An unfloored latch
                    # took a book of 8 to cap 2 and force-liquidated 6 names in a
                    # single bar, then the unlatched lanes refilled it: strictly
                    # worse churn than the bug this fixes. Flooring means the
                    # latch can only ever set headroom to 0 (block NEW entries);
                    # reducing the book stays the trim's job, which does it
                    # gradually and worst-first.
                    if _z41_latch_on and str(_z41_regime or "").strip().lower() == "chop":
                        _z41_held_now = 0
                        try:
                            if portfolio_emulator is not None and hasattr(portfolio_emulator, "get_positions"):
                                _z41_held_now = len(portfolio_emulator.get_positions() or {})
                        except Exception:
                            _z41_held_now = 0
                        _z41_latched = max(_regime_position_cap(config, "bear"), _z41_held_now)
                        if _z41_latched < _z41_capped:
                            _log(f"Bear capacity latch: chop bar held at cap "
                                 f"{_z41_capped}->{_z41_latched} (book={_z41_held_now}, "
                                 f"downtrend not released) — blocks new entries only",
                                 "yellow")
                            _z41_capped = _z41_latched
                    if _z41_capped != _max_positions:
                        _log(
                            f"Regime capacity gate (Z4.1): regime={_z41_regime} "
                            f"max_positions {_max_positions}->{_z41_capped} "
                            f"(spy_20d={_z41_spy_20d if _z41_spy_20d is None else f'{_z41_spy_20d*100:+.2f}%'}, "
                            f"v31={_z41_v31})",
                            "cyan",
                        )
                        _max_positions = _z41_capped
                _current_positions = len(portfolio_emulator.get_positions()) if portfolio_emulator and hasattr(portfolio_emulator, 'get_positions') else 0
                _blocked_buys = []
                # V28.8.1 (Codex-corrected): breach detection + strategy_cache flag
                # propagation. The breach flag is READ by:
                # - BFQ direct-reserved (blocked — new ticker path)
                # - BFQ dequeue loop (blocked — new ticker path)
                # - Main rotation (partial-trim rotations blocked when breach active)
                # NOT read by:
                # - BFQ rotation (always allowed — inherent 1-for-1 swap)
                # - Queue→rotation promotion (feeds main rotation which handles gating)
                # - Winner adds (held adds, not new tickers)
                # Per Codex 2B: the real overfill source is rotation-generated partial
                # trims at line ~16749 that create new tickers without headroom checks.
                _position_breach_active = False
                if _current_positions > _max_positions:
                    # V31.3 Fix 11: breach auto-heal. Before blocking new buys,
                    # force-rotate out the weakest P&L unlocked position to free
                    # a slot. Restores MU-class re-entries that were blocked for
                    # 3 months because portfolio was at 9/8 breach.
                    _breach_auto_heal = bool(config.get("max_positions_breach_auto_rotate", True))
                    _breach_slots_to_free = max(1, _current_positions - _max_positions)
                    # 2026-07-27 LIVE SAFETY: bound the per-bar liquidation.
                    # This is unbounded by construction, and the regime caps make
                    # the gap large: on the FIRST confirmed bear bar with a full
                    # book, max_positions_bear=2 gives 14-2 = 12 slots to free, so
                    # a single bar emits TWELVE simultaneous market sells into a
                    # falling tape. The bear-book trim already bleeds out under
                    # `bear_book_trim_max_per_bar` for exactly this reason; this
                    # path had no equivalent. 0 = unbounded (previous behaviour).
                    try:
                        _breach_max_per_bar = int(
                            config.get("max_positions_breach_max_per_bar", 0) or 0)
                    except (TypeError, ValueError):
                        _breach_max_per_bar = 0
                    if _breach_max_per_bar > 0 and _breach_slots_to_free > _breach_max_per_bar:
                        _log(f"Breach auto-heal: capping liquidation at "
                             f"{_breach_max_per_bar}/bar (wanted {_breach_slots_to_free}; "
                             f"held={_current_positions} cap={_max_positions}) — "
                             f"remainder bleeds out on subsequent bars", "yellow")
                        _breach_slots_to_free = _breach_max_per_bar
                    _breach_min_hold_days = int(config.get("max_positions_breach_heal_min_hold_days", 3) or 3)
                    # Phase γ.3 (2026-05-18, BT232179 follow-up): adversarial review
                    # of BT232179 found the breach-heal loop was firing on 78% of
                    # bars but `auto-heal freed 0` on 79% of those — every candidate
                    # was filtered out by the winner_lock skip. Root cause: the
                    # winner_lock predicate fires for held positions at +2%/+3 days
                    # (CSCO at +8.8%/9d in BT232179), which is far short of the
                    # "true winner" intent. Relax the skip so positions that are
                    # winner_lock'd BUT only marginally profitable (pnl < 15%) are
                    # still eligible for breach-heal eviction. True winners (>=15%
                    # pnl) remain protected. Bounded: heal loop still caps at
                    # _breach_slots_to_free closes per breach (not aggressive
                    # sell-down). Knob is operator-tunable for Phase β follow-up.
                    try:
                        _breach_wlock_max_pnl = float(
                            config.get("breach_heal_winner_lock_bypass_max_pnl_pct", 15.0)
                            or 15.0
                        )
                    except (TypeError, ValueError):
                        _breach_wlock_max_pnl = 15.0
                    _breach_healed = 0
                    _breach_wlock_bypassed = 0
                    if _breach_auto_heal and portfolio_emulator is not None:
                        _breach_regime = str((strategy_cache or {}).get("_market_regime") or "chop")
                        _breach_candidates: list[tuple[str, float, int]] = []
                        for _bh_sym, _bh_q in (getattr(portfolio_emulator, "_positions", {}) or {}).items():
                            if float(_bh_q or 0) <= 0:
                                continue
                            _bh_sym_u = str(_bh_sym).strip().upper()
                            # Skip tickers already slated for sell
                            if _bh_sym_u in (nexus_sell_enforcement or set()):
                                continue
                            try:
                                _bh_snap = _build_position_health_snapshot(
                                    _bh_sym_u,
                                    portfolio_emulator=portfolio_emulator,
                                    prices=prices,
                                    price_history=data,
                                    strategy_cache=strategy_cache,
                                    date_key=date_key,
                                    raw_score=float((scores.get(_bh_sym_u) or {}).get("raw_net_score", 0.0) or 0.0),
                                )
                                _bh_pnl = float(_bh_snap.get("unrealized_pct", 0.0) or 0.0)
                                _bh_held_days = _bh_snap.get("held_days") or 0
                                _bh_raw = float(_bh_snap.get("current_raw_score", 0.0) or 0.0)
                                # V31.3 fix: skip fresh positions (held < 3d).
                                # A new high-conviction buy shouldn't be evicted
                                # just because breach math picks its P&L as weakest.
                                if int(_bh_held_days or 0) < _breach_min_hold_days:
                                    continue
                                # V31.3 fix: respect V31 initial grace period.
                                # Don't force-sell positions that would be grace-
                                # protected from trend_reversal — breach-heal
                                # shouldn't bypass risk controls for young names.
                                # Phase ε.C.0' (2026-05-19): tier-aware grace escape.
                                _bh_tier = _resolve_conviction_tier_at_exit(
                                    _bh_sym_u, config, strategy_cache, propagated
                                )
                                _bh_grace_in, _bh_grace_esc, _ = _in_initial_grace_period(
                                    _bh_held_days, _bh_pnl, config, _breach_regime,
                                    conviction_tier=_bh_tier,
                                )
                                if _bh_grace_in and not _bh_grace_esc:
                                    continue
                                # Respect winner_lock — don't heal by evicting a TRUE
                                # winner. Phase γ.3: only short-circuit when the
                                # held position is BOTH winner_lock'd AND truly
                                # profitable (pnl >= breach_heal_winner_lock_bypass_max_pnl_pct,
                                # default 15%). Modest +2%-to-15% "winners" remain
                                # eligible so the heal loop can free a slot for
                                # raw=1.8 incoming candidates.
                                _bh_wlock, _ = _rotation_winner_lock_active(
                                    held_pnl_pct=_bh_pnl,
                                    held_days=_bh_held_days,
                                    held_raw_score=_bh_raw,
                                    drop_from_peak_pct=_bh_snap.get("drop_from_peak_pct"),
                                    is_equity=bool(_bh_snap.get("is_equity", True)),
                                    config=config,
                                )
                                if _bh_wlock and float(_bh_pnl or 0.0) >= _breach_wlock_max_pnl:
                                    continue
                                if _bh_wlock:
                                    # Audit: this candidate would have been
                                    # blocked pre-γ.3. Counter incremented so
                                    # the operator can see the relaxation working.
                                    _breach_wlock_bypassed += 1
                                _breach_candidates.append((_bh_sym_u, _bh_pnl, int(_bh_held_days)))
                            except Exception as _bh_exc:
                                _log(f"V31.3 breach heal candidate skip {_bh_sym_u}: {_bh_exc}", "yellow")
                                continue
                        # Sort by weakest P&L ascending (most negative first)
                        _breach_candidates.sort(key=lambda t: t[1])
                        for _bh_sym_u, _bh_pnl, _bh_held_days in _breach_candidates[:_breach_slots_to_free]:
                            nexus_sell_enforcement.add(_bh_sym_u)
                            # V31.3 critical fix: set scores[sym]["score"] = -1
                            # so downstream sell_syms filter at line ~17124 and
                            # rotation loop at ~18034 don't re-select this ticker
                            # as a rotation candidate (double-count proceeds bug).
                            if _bh_sym_u in scores and isinstance(scores.get(_bh_sym_u), dict):
                                scores[_bh_sym_u]["score"] = -1
                            else:
                                scores[_bh_sym_u] = {"score": -1}
                            sentiment_data[_bh_sym_u] = {"sentiment": -1, "event": "general"}
                            # V31.3: record evict cooldown to prevent same-day rebuy
                            if '_evict_cooldown' in dir() and isinstance(_evict_cooldown, dict):
                                try:
                                    _evict_cooldown[_bh_sym_u] = int(_evict_cooldown_bars)
                                    _evict_cooldown_dirty = True
                                except Exception:
                                    pass
                            _breach_healed += 1
                            _log(
                                f"V31.3 breach auto-heal: rotating out {_bh_sym_u} "
                                f"(pnl={_bh_pnl:+.1f}%, held={_bh_held_days}d) "
                                f"to free slot {_breach_healed}/{_breach_slots_to_free}",
                                "magenta",
                            )
                        _current_positions -= _breach_healed
                        # Phase γ.3: emit per-bar audit on the winner_lock relaxation
                        # so operators can confirm the heal loop is actually doing
                        # work that pre-γ.3 was silently no-op'd.
                        if _breach_wlock_bypassed > 0:
                            _log(
                                f"V31.3 breach auto-heal γ.3: "
                                f"{_breach_wlock_bypassed} winner_lock'd candidate(s) "
                                f"admitted (pnl < {_breach_wlock_max_pnl:.1f}% bypass "
                                f"threshold).",
                                "magenta",
                            )
                    # Re-evaluate breach state after heal attempt
                    if _current_positions > _max_positions:
                        _position_breach_active = True
                        _log(
                            f"[V28.8.1 max_positions BREACH] current={_current_positions} > "
                            f"max={_max_positions} (auto-heal freed {_breach_healed}). "
                            f"Blocking direct/dequeue new-ticker buys.",
                            "red",
                        )
                        _blocked_buys = list(_new_stock_candidates)
                        _new_stock_candidates = []
                        _position_headroom = 0
                    else:
                        _position_headroom = max(0, _max_positions - _current_positions)
                        _log(
                            f"V31.3 breach auto-heal: freed {_breach_healed} slot(s), "
                            f"headroom now {_position_headroom}",
                            "cyan",
                        )
                        if _position_headroom < len(_new_stock_candidates):
                            _blocked_buys = _new_stock_candidates[_position_headroom:]
                            _new_stock_candidates = _new_stock_candidates[:_position_headroom]
                else:
                    _position_headroom = max(0, _max_positions - _current_positions)
                    if _position_headroom < len(_new_stock_candidates):
                        _blocked_buys = _new_stock_candidates[_position_headroom:]
                        _new_stock_candidates = _new_stock_candidates[:_position_headroom]
                # V28.8.1: propagate breach flag to strategy_cache so BFQ direct-reserved
                # and BFQ dequeue paths can READ it. These paths are new-ticker additions
                # and MUST be blocked during breach. Main rotation reads this flag too
                # (new check added below at line ~16749).
                if isinstance(strategy_cache, dict):
                    strategy_cache["_v28_7_position_breach_active"] = _position_breach_active
                stock_buys_scored = _held_add_candidates + _new_stock_candidates

                # Sweep-3: defense-in-depth _blocked_buys cooldown filter removed —
                # _new_stock_candidates is already filtered above before the headroom split,
                # so _blocked_buys is derived from already-cooldown-clean candidates.

                # ADDED BY CODEX (Fix 2C): identify top momentum tickers and prioritize
                # them at the front of the rotation candidate queue.
                _top_momentum_tickers = _identify_top_momentum_guaranteed_buys(
                    scores, data, portfolio_emulator, config, max_count=3
                )
                _top_mom_set = set(_top_momentum_tickers)
                # V26 Fix A1: expand top-momentum membership to ALL blocked buys whose
                # raw_net_score >= nexus_high_conviction_threshold (default 1.5). This
                # makes the existing top_momentum_break_glass path at
                # _rotation_candidate_allowed:5013 fire for SNDK/MU/LITE-style names
                # without changing any downstream logic. The break_glass gate still
                # requires raw>=1.5 and delta>=0.75 so we cannot accidentally rotate
                # weak candidates against winners.
                _high_conv_threshold = float(config.get("nexus_high_conviction_threshold", 1.5) or 1.5)
                def _bb_raw(s: str) -> float:
                    return float((scores.get(s) or {}).get("raw_net_score", 0.0) or 0.0)
                def _is_high_conviction_bb(s: str) -> bool:
                    return _bb_raw(s) >= _high_conv_threshold
                # V28 Fix 1: build a queue-age lookup so aged queued items can be
                # promoted to blocked_buys (and get age-boosted in the sort).
                # Without this, queued items NEVER get a chance at rotation —
                # they only ever drain via the BFQ direct path which is broken
                # when portfolio is at max_positions cap (headroom=0).
                _bfq_age_lookup: dict[str, int] = {}
                _bfq_score_lookup: dict[str, float] = {}
                for _qe in (_bfq_pending or []):
                    _qt = str((_qe or {}).get("ticker") or "").strip().upper()
                    if not _qt:
                        continue
                    _bfq_age_lookup[_qt] = int((_qe or {}).get("bars_in_queue", 0) or 0)
                    _bfq_score_lookup[_qt] = float((_qe or {}).get("raw_net_score", 0.0) or 0.0)
                def _bb_age(s: str) -> int:
                    return int(_bfq_age_lookup.get(s, 0))
                def _bb_age_boost(s: str) -> float:
                    _per_bar = float(config.get("blocked_buys_age_boost_per_bar", 0.05) or 0.05)
                    _cap = float(config.get("blocked_buys_age_boost_cap", 0.40) or 0.40)
                    return min(_cap, _bb_age(s) * _per_bar)
                # V28 Fix 1: promote aged queue items into _blocked_buys (toggleable).
                # Promote items with bars_in_queue >= min_bars AND score >= threshold
                # AND not already in blocked_buys/_open_positions/_held_add_candidates.
                # V28.8: breach-mode skip REMOVED. Queue→rotation promotion feeds
                # the rotation path, which is net-zero swap. Previously V28.7's
                # breach-skip caused aged high-conviction items (SNDK, MU, etc.)
                # to never get promoted, leaving them trapped in the BFQ.
                _aged_queue_promotions: list[tuple[str, float, int]] = []
                if (
                    bool(config.get("queue_rotation_promotion_enabled", True))
                    and _bfq_pending
                ):
                    # 2026-05-07 granularity-scaling: bar-count threshold on
                    # queue age; scale to keep wall-clock promotion gate stable.
                    _qrp_min_bars = _scale_bars(int(config.get("queue_rotation_promotion_min_bars", 1) or 1), config)
                    _qrp_max_items = int(config.get("queue_rotation_promotion_max_items", 20) or 20)
                    _existing_bb_set = set(_blocked_buys or [])
                    _open_now = set()
                    if portfolio_emulator is not None and hasattr(portfolio_emulator, "_positions"):
                        _open_now = {
                            str(s).strip().upper()
                            for s, q in (portfolio_emulator._positions or {}).items()
                            if float(q or 0) > 0
                        }
                    # Sort queue by age desc then score desc; take top N
                    _queue_for_promotion = sorted(
                        list(_bfq_pending or []),
                        key=lambda e: (
                            -int((e or {}).get("bars_in_queue", 0) or 0),
                            -float((e or {}).get("raw_net_score", 0.0) or 0.0),
                        ),
                    )[: max(0, _qrp_max_items)]
                    for _qe in _queue_for_promotion:
                        _qt = str((_qe or {}).get("ticker") or "").strip().upper()
                        _qbars = int((_qe or {}).get("bars_in_queue", 0) or 0)
                        if not _qt or _qt in _existing_bb_set or _qt in _open_now:
                            continue
                        if _qbars < _qrp_min_bars:
                            continue
                        # Use the LIVE re-scored value (not the stored queue score),
                        # so promotion only happens for items whose latest score is
                        # still high-conviction.
                        _qscore_live = _bb_raw(_qt)
                        if _qscore_live < _high_conv_threshold:
                            continue
                        _blocked_buys.append(_qt)
                        _existing_bb_set.add(_qt)
                        _aged_queue_promotions.append((_qt, _qscore_live, _qbars))
                if _aged_queue_promotions:
                    _promo_str = ", ".join(
                        f"{t}(score={s:.3f},age={b}d)" for t, s, b in _aged_queue_promotions
                    )
                    _log(
                        f"V28 Queue->Rotation promotion: {len(_aged_queue_promotions)} aged "
                        f"queue item(s) promoted to blocked_buys: {_promo_str}",
                        "magenta",
                    )
                if _blocked_buys:
                    # V28 Fix 1: sort by (priority_tier, -(raw_score + age_boost), ticker)
                    # so aged queued items get a head start over fresh new items.
                    # The ticker tie-breaker makes the sort stable across runs.
                    _blocked_buys = sorted(
                        _blocked_buys,
                        key=lambda s: (
                            0 if (s in _top_mom_set or _is_high_conviction_bb(s)) else 1,
                            -(_bb_raw(s) + _bb_age_boost(s)),
                            str(s),
                        ),
                    )
                if _top_momentum_tickers:
                    _log(
                        f"Top momentum candidates: {', '.join(_top_momentum_tickers)} "
                        f"(60d>={float(config.get('top_momentum_60d_threshold', 40.0) or 40.0):.0f}%, "
                        f"20d>={float(config.get('top_momentum_20d_threshold', 15.0) or 15.0):.0f}%)",
                        "magenta",
                    )

                # V28: track if any high-conviction blocked_buy exists so we
                # can use the expanded rotation cap. Computed BEFORE the loop
                # so we don't recompute every iteration.
                _hc_in_blocked = any(
                    _bb_raw(_s) >= _high_conv_threshold for _s in (_blocked_buys or [])
                ) if _blocked_buys else False
                _effective_max_rotations = _max_rotations + (_max_rotations_hc if _hc_in_blocked else 0)
                if (not _new_stock_candidates or _position_headroom == 0) and portfolio_emulator is not None and _effective_max_rotations > 0:
                    if _blocked_buys:
                        # V28 Fix 4: comprehensive un-truncated logging at the
                        # start of the rotation loop so we can see exactly what
                        # went into the eval and what came out.
                        _bb_summary = ", ".join(
                            f"{_s}(raw={_bb_raw(_s):.3f},age={_bb_age(_s)}d,boost={_bb_age_boost(_s):.3f})"
                            for _s in _blocked_buys[:15]
                        )
                        _log(
                            f"V28 ROTATION START: blocked_buys={len(_blocked_buys)} "
                            f"effective_cap={_effective_max_rotations} "
                            f"(standard={_max_rotations}, hc_bonus={_max_rotations_hc if _hc_in_blocked else 0}, "
                            f"hc_in_blocked={_hc_in_blocked}) "
                            f"top15={_bb_summary}",
                            "cyan",
                        )
                        _held = {}
                        for _ht, _hq in (portfolio_emulator._positions or {}).items():
                            if float(_hq) > 0 and _ht not in set(sell_syms or []) and _ht not in _momentum_held_set:
                                _held_ctx = _build_position_health_snapshot(
                                    _ht,
                                    portfolio_emulator=portfolio_emulator,
                                    prices=prices,
                                    price_history=data,
                                    strategy_cache=strategy_cache,
                                    date_key=date_key,
                                    raw_score=float((scores.get(_ht) or {}).get("raw_net_score", 0.0) or 0.0),
                                )
                                if _held_ctx["entry_price"] > 0.0 and _held_ctx["current_price"] > 0.0:
                                    _held_ctx["score"] = float((scores.get(_ht) or {}).get("raw_net_score", 0.0) or 0.0)
                                    _held_ctx["rotation_score"] = _rotation_effective_score(scores.get(_ht), config)
                                    _held[_ht] = _held_ctx

                        if _held:
                            _held_sorted = sorted(_held.items(), key=lambda x: x[1].get("unrealized_pct", 0.0))  # Weakest first
                            # V28 Fix 5: per-held trim cooldown to prevent cascade
                            # erosion. A held position partial-trimmed on bar N
                            # should not be trimmed again until bar N+cooldown.
                            # Without this, the same winner could be trimmed
                            # bar after bar to fund every new high-conviction
                            # arrival, eroding its size to zero over time.
                            _v28_trim_cd = _normalize_cache_mapping(strategy_cache, "_v28_hold_trim_cooldown") if strategy_cache is not None else {}
                            # 2026-05-07 granularity-scaling: per-held trim
                            # cooldown decrements per bar; scale to preserve
                            # the wall-clock window that prevents cascade
                            # erosion of a winner.
                            _v28_trim_cd_bars = _scale_bars(int(config.get("v28_hold_trim_cooldown_bars", 3) or 3), config)
                            # Decrement existing cooldowns at start of each bar
                            for _cdk in list(_v28_trim_cd.keys()):
                                _v28_trim_cd[_cdk] = max(0, int(_v28_trim_cd[_cdk]) - 1)
                                if _v28_trim_cd[_cdk] <= 0:
                                    _v28_trim_cd.pop(_cdk, None)
                            for _bb in _blocked_buys:
                                if len(_rotation_pairs) >= _effective_max_rotations:
                                    _log(
                                        f"V28 ROTATION CAP REACHED: {len(_rotation_pairs)}/{_effective_max_rotations} "
                                        f"— skipping remaining {len(_blocked_buys) - _blocked_buys.index(_bb)} blocked_buys: "
                                        f"{', '.join(_blocked_buys[_blocked_buys.index(_bb):])[:300]}",
                                        "yellow",
                                    )
                                    break
                                _bb_score = float((scores.get(_bb) or {}).get("raw_net_score", 0.0) or 0.0)
                                _bb_rotation_score = _rotation_effective_score(scores.get(_bb), config)
                                if _bb_score < _rotation_min_score:
                                    _log(
                                        f"V28 ROTATION SKIP: {_bb} raw={_bb_score:.3f} < min_score={_rotation_min_score:.3f}",
                                        "yellow",
                                    )
                                    continue
                                for _wt, _wd in _held_sorted:
                                    if _wt in [p["sell"] for p in _rotation_pairs]:
                                        continue
                                    # V28 Fix 5: skip holds that were trimmed recently
                                    if _v28_trim_cd.get(_wt, 0) > 0:
                                        continue
                                    _held_days_value = _wd.get("held_days")
                                    # ADDED BY CODEX (Fix 2C): build incoming_meta with
                                    # is_top_momentum flag so _rotation_candidate_allowed
                                    # can apply the lowered break_glass thresholds.
                                    # V26 Fix A1: also flag any blocked-buy whose raw score
                                    # crosses nexus_high_conviction_threshold so it can use
                                    # the existing top_momentum_break_glass bypass.
                                    _bb_is_high_conv = _bb_score >= _high_conv_threshold
                                    _incoming_meta = {
                                        "is_top_momentum": (_bb in _top_mom_set) or _bb_is_high_conv,
                                        "is_high_conviction": _bb_is_high_conv,
                                        "from_top_mom_set": _bb in _top_mom_set,
                                    }
                                    _rotation_allowed, _rotation_delta, _rotation_mode = _rotation_candidate_allowed(
                                        held_pnl_pct=float(_wd.get("unrealized_pct", 0.0) or 0.0),
                                        held_rotation_score=float(_wd.get("rotation_score", _wd.get("score", 0.0)) or 0.0),
                                        held_days=int(_held_days_value) if _held_days_value is not None else None,
                                        held_raw_score=float(_wd.get("score", 0.0) or 0.0),
                                        drop_from_peak_pct=_wd.get("drop_from_peak_pct"),
                                        is_equity=bool(_wd.get("is_equity", True)),
                                        incoming_raw_score=_bb_score,
                                        incoming_rotation_score=_bb_rotation_score,
                                        config=config,
                                        incoming_meta=_incoming_meta,
                                        # Phase ε.C.2: regime-aware time-floor decay
                                        market_regime=str((strategy_cache or {}).get("_market_regime") or "chop"),
                                        # Task 12: symbol for the ROTATION_GRAPH_GATE log line.
                                        held_sym=_wt,
                                    )
                                    # V28 Fix 4: log every rotation eval result so failed
                                    # rotations are visible (previously most failures
                                    # were silent — only winner_lock had a log line).
                                    _log(
                                        f"V28 ROT EVAL: {_bb}(raw={_bb_score:.3f},age={_bb_age(_bb)}d,is_hc={_bb_is_high_conv}) "
                                        f"vs held={_wt}(pnl={_wd.get('unrealized_pct',0.0):.1f}%,days={_held_days_value},rot={_wd.get('rotation_score',0):.3f},peak_drop={_wd.get('drop_from_peak_pct',0) or 0:.1f}%) "
                                        f"-> mode={_rotation_mode} allowed={_rotation_allowed} delta={_rotation_delta:.3f}",
                                        "green" if _rotation_allowed else "yellow",
                                    )
                                    if not _rotation_allowed:
                                        if _rotation_mode in {"min_hold", "profitable_min_hold"} and _held_days_value is not None and int(_held_days_value) < _rotation_min_hold_days:
                                            continue
                                        if _rotation_mode == "winner_lock":
                                            _log(
                                                f"Rotation blocked: {_wt} leader_lock active "
                                                f"(P&L={_wd.get('unrealized_pct', 0.0):.1f}%, held={int(_held_days_value) if _held_days_value is not None else '?'}d, "
                                                f"raw={float(_wd.get('score', 0.0) or 0.0):.3f}, drop={float(_wd.get('drop_from_peak_pct', 0.0) or 0.0):.1f}%) "
                                                f"vs {_bb} (raw={_bb_score:.3f}, rot={_bb_rotation_score:.3f}, delta={_rotation_delta:.3f})",
                                                "cyan",
                                            )
                                        continue
                                    if _rotation_delta > _rotation_min_delta:
                                        _held_days_label = f"{int(_held_days_value)}d" if _held_days_value is not None else "n/a"
                                        # Sweep-3 fix: top_momentum_break_glass also punches through
                                        # winner_lock and should be a partial trim like break_glass_trim
                                        # (otherwise top-momentum candidates would fully evict the
                                        # held winner, defeating the partial-trim safety design).
                                        # V28.3: V28.2 modes are now FULL EXITS (not partial trims)
                                        # to prevent cascade churn. Cascade was: bar N trims SPLP 50%,
                                        # bar N+3 trims SPLP again 50%, bar N+6 again — within 9 bars
                                        # SPLP is at 12.5% of original. Same for many holds. Win rate
                                        # was 0% because new buys got partial-trimmed before they
                                        # could appreciate. Full exits make rotation atomic: 1 hold
                                        # leaves entirely, 1 new hold takes its slot.
                                        # top_momentum_break_glass and break_glass_trim KEEP the
                                        # partial-trim behavior because they're for genuine winners
                                        # (winner_lock active = profitable AND not too far from peak).
                                        _is_partial_trim_mode = _rotation_mode in {
                                            "break_glass_trim",
                                            "top_momentum_break_glass",
                                            "v28_hc_losing_break_glass",  # V28.6: revert V28.3 for losing variant only
                                        }
                                        _is_break_glass_mode = _is_partial_trim_mode or _rotation_mode in {
                                            "v28_hc_profitable_break_glass",
                                            # Full-exit (not partial-trim) but must still consult the
                                            # eta.D HIGH-tier grace guard below so a fresh high-tier
                                            # holding in its grace window is not evicted.
                                            "profitable_min_hold_conviction_override",
                                        }
                                        # η.D — Phase η (2026-05-20): refuse V28.9/break-glass
                                        # eviction of a HIGH-tier holding that is still inside
                                        # its grace window. Closes the ε.B gap — ε.B added
                                        # tier-aware grace floors at _in_initial_grace_period
                                        # but the break-glass rotation path (this block) did
                                        # not consult them. BT277953 day 5: SNDK was evicted
                                        # via this code path while in grace.
                                        if (
                                            _is_break_glass_mode
                                            and config.get("eta_v289_protect_high_grace_enabled", True)
                                        ):
                                            _eta_d_tier = _resolve_conviction_tier_at_exit(
                                                _wt, config, strategy_cache, propagated
                                            )
                                            _eta_d_grace_in, _eta_d_grace_esc, _ = _in_initial_grace_period(
                                                int(_held_days_value or 0),
                                                float(_wd.get("unrealized_pct", 0.0) or 0.0),
                                                config,
                                                str((strategy_cache or {}).get("_market_regime") or "chop"),
                                                conviction_tier=_eta_d_tier,
                                            )
                                            if (
                                                _eta_d_tier == "HIGH"
                                                and _eta_d_grace_in
                                                and not _eta_d_grace_esc
                                            ):
                                                _log(
                                                    f"[ETA.D] V28.9 refused pair: loser={_wt} "
                                                    f"HIGH-tier in grace (held={_held_days_label}, "
                                                    f"pnl={float(_wd.get('unrealized_pct', 0.0) or 0.0):+.1f}%, "
                                                    f"mode={_rotation_mode}); trying next pair",
                                                    "yellow",
                                                )
                                                continue
                                        # Track C (run-163943): recent-runup momentum-protect. A losing
                                        # position that recently ran up (volatile hot entry that dipped) is
                                        # not evicted at a local bottom via the losing break-glass (UAL was
                                        # cut here before a +27% move). Default-off; winner-lock partial-trim
                                        # modes are unaffected (they already protect genuine winners).
                                        if _rotation_mode == "v28_hc_losing_break_glass":
                                            _bg_runup_pct_cfg = float(
                                                config.get("rotation_break_glass_recent_runup_block_pct", 0.0) or 0.0
                                            )
                                            _bg_runup_lookback = int(
                                                config.get("rotation_break_glass_recent_runup_lookback_bars", 20) or 20
                                            )
                                            _bg_protected, _bg_runup_pct = _recent_runup_protect(
                                                _wt, data, _bg_runup_pct_cfg, _bg_runup_lookback,
                                            )
                                            if _bg_protected:
                                                _log(
                                                    f"break-glass recent-runup block: {_wt} recent "
                                                    f"{_bg_runup_lookback}-bar range ran +{_bg_runup_pct:.1f}% > "
                                                    f"{_bg_runup_pct_cfg:.0f}% — refusing losing break-glass "
                                                    f"eviction (momentum on hot entry); trying next pair",
                                                    "yellow",
                                                )
                                                continue
                                        # V28.6: v28_hc_profitable_break_glass remains FULL EXIT (V28.4 floor
                                        # protects winners >2% pnl); v28_hc_losing_break_glass reverts to
                                        # partial trim to soften V28.5's expanded eviction so displaced names
                                        # are not fully evicted in one shot.
                                        if _is_partial_trim_mode:
                                            _sell_fraction = float(
                                                config.get("rotation_break_glass_sell_fraction", 0.50) or 0.50
                                            )
                                        elif _rotation_mode == "v28_hc_profitable_break_glass":
                                            _sell_fraction = 1.0  # FULL EXIT (V28.4 floor protects winners >2% pnl)
                                        else:
                                            _sell_fraction = 1.0  # losing_hold path = full exit
                                        # V28.8.1 (Codex-corrected): when at cap (breach OR headroom==0),
                                        # partial-trim rotations create a NEW ticker without freeing a slot.
                                        # That's the root cause of the V28.7 overfill (bar 6 reached 15
                                        # positions via partial trims). Only allow full-exit (sell_fraction
                                        # >= 0.999) rotations when at cap. Full exits are truly net-zero
                                        # (the trimmed ticker fully leaves, the new ticker takes its slot).
                                        # V28.9: SNDK was starved by the V28.8.1 gate at bar 2025-11-25
                                        # because all its rotation partners were partial-trim mode. HM
                                        # investigation of nexus-43.txt (257 SKIPPED events) shows 155
                                        # of them were `v28_hc_losing_break_glass` targeting held positions
                                        # at -2% to -9% P&L. Those holds are already slated for eviction
                                        # under the losing branch of break_glass logic (code line 5157,
                                        # which is OUTSIDE `if winner_lock_active:` — held_pnl <= -1.5
                                        # by definition). Converting the 50% partial trim to 100% full
                                        # exit is net-zero-swap-equivalent to v28_hc_profitable_break_glass
                                        # (which uses 100% full exit and works fine). The other modes
                                        # (top_momentum_break_glass, break_glass_trim) ARE inside
                                        # the winner_lock branch and must NOT be converted — winners
                                        # at +6% to +24% P&L stay protected.
                                        _v288_at_cap = (_position_breach_active or _position_headroom <= 0)
                                        if _v288_at_cap and _sell_fraction < 0.999:
                                            _v289_held_pnl_pct = float(_wd.get("unrealized_pct", 0.0) or 0.0)
                                            # V32 S1-d2: configurable CONVERT loss threshold. Default -2.0
                                            # preserves V31.7 behaviour; paired with shield=False the threshold
                                            # can be widened to -4.0 (or similar) so CONVERT fires later.
                                            # 2026-07-21 bull-alpha: bull-only widen via
                                            # v32_convert_min_loss_pct_bull (funds starved winners, e.g. INTC;
                                            # bear/chop keep the base — see _convert_min_loss_threshold).
                                            _v288_regime = str((strategy_cache or {}).get("_market_regime") or "chop").lower()
                                            _v32_convert_min_loss = _convert_min_loss_threshold(config, _v288_regime)
                                            _v289_can_convert_loser = (
                                                _rotation_mode == "v28_hc_losing_break_glass"
                                                and _v289_held_pnl_pct <= _v32_convert_min_loss
                                            )
                                            # V31.7 Fix C: shield fresh positions from full-exit conversion.
                                            # MU (day 7, -3.6%), LMT (day 7, -2.8%), META (day 5, -4.2%) were
                                            # cut via this path in backtest #308030. Shield: if held_days is
                                            # below threshold AND loss is small, block the conversion and
                                            # skip the rotation pair (position continues).
                                            if _v289_can_convert_loser and bool(config.get("break_glass_fresh_shield_enabled", False)):
                                                _v317_fresh_days_cfg = int(config.get("break_glass_fresh_min_held_days", 8) or 8)
                                                _v317_fresh_max_loss_cfg = float(config.get("break_glass_fresh_max_loss_pct", -4.0) or -4.0)
                                                _v317_held_days_val = int(_wd.get("held_days", 999) or 999)
                                                if (
                                                    _v317_held_days_val < _v317_fresh_days_cfg
                                                    and _v289_held_pnl_pct > _v317_fresh_max_loss_cfg
                                                ):
                                                    _log(
                                                        f"V31.7 break_glass fresh shield: {_wt} "
                                                        f"(pnl={_v289_held_pnl_pct:+.1f}%, held={_v317_held_days_val}d) "
                                                        f"— conversion BLOCKED (shield: <{_v317_fresh_days_cfg}d "
                                                        f"AND > {_v317_fresh_max_loss_cfg:.1f}%)",
                                                        "magenta",
                                                    )
                                                    continue
                                            # V32 T1-d: CONVERT same-ticker cooldown. Block 3rd CONVERT on a
                                            # ticker within N bars to stop NVDA/META-class death-spiral churn.
                                            # Window defaults to 30 bars; counter resets on profitable close
                                            # (see sell-settlement hook).
                                            if _v289_can_convert_loser and bool(
                                                config.get("v32_convert_same_ticker_cooldown_enabled", True)
                                            ):
                                                _cv_cache = (
                                                    strategy_cache.setdefault("_v32_convert_losses", {})
                                                    if strategy_cache is not None
                                                    else {}
                                                )
                                                try:
                                                    _cv_max = int(
                                                        config.get("v32_convert_cooldown_max_losses", 2) or 2
                                                    )
                                                except Exception:
                                                    _cv_max = 2
                                                try:
                                                    # 2026-05-07 granularity-scaling: convert-loser
                                                    # cooldown window is bar-decremented; preserve
                                                    # wall-clock semantics across cadences.
                                                    _cv_window = _scale_bars(
                                                        int(config.get("v32_convert_cooldown_window_bars", 30) or 30),
                                                        config,
                                                    )
                                                except Exception:
                                                    _cv_window = 30
                                                # Bug fix: run_once does not expose `bar_index`;
                                                # use strategy_cache's deployment_bar_index (same
                                                # pattern used throughout run_once).
                                                _cv_cur_bar = 0
                                                try:
                                                    _cv_cur_bar = int(
                                                        (strategy_cache or {}).get(
                                                            "_deployment_bar_index", 1
                                                        ) or 1
                                                    )
                                                except Exception:
                                                    _cv_cur_bar = 0
                                                _cv_hist_raw = list(_cv_cache.get(_wt, []))
                                                _cv_hist = []
                                                for _cv_b in _cv_hist_raw:
                                                    try:
                                                        _cv_bi = int(_cv_b)
                                                    except Exception:
                                                        continue
                                                    if (_cv_cur_bar - _cv_bi) < _cv_window:
                                                        _cv_hist.append(_cv_bi)
                                                if len(_cv_hist) >= _cv_max:
                                                    _log(
                                                        f"V32 CONVERT cooldown BLOCK: {_wt} "
                                                        f"({len(_cv_hist)} converts in last {_cv_window} bars)",
                                                        "yellow",
                                                    )
                                                    # Persist pruned history so stale entries decay.
                                                    if strategy_cache is not None:
                                                        _cv_cache[_wt] = _cv_hist
                                                    continue
                                                # Keep pruned history; we'll append current fire after CONVERT log.
                                                if strategy_cache is not None:
                                                    _cv_cache[_wt] = _cv_hist
                                            if _v289_can_convert_loser:
                                                _log(
                                                    f"V28.9 rotation pair CONVERTED (losing_break_glass at cap): "
                                                    f"{_wt}(pnl={_v289_held_pnl_pct:+.1f}%, 50%\u2192100%)\u2192{_bb} "
                                                    f"raw={_bb_score:.3f} rot={_bb_rotation_score:.3f}",
                                                    "cyan",
                                                )
                                                _sell_fraction = 1.0
                                                _rotation_mode = "v28_hc_losing_break_glass_v289_full_exit_at_cap"
                                                # V32 T1-d: record this CONVERT fire for same-ticker cooldown.
                                                if bool(
                                                    config.get("v32_convert_same_ticker_cooldown_enabled", True)
                                                ) and strategy_cache is not None:
                                                    _cv_cache_w = strategy_cache.setdefault(
                                                        "_v32_convert_losses", {}
                                                    )
                                                    _cv_hist_w = list(_cv_cache_w.get(_wt, []))
                                                    try:
                                                        _cv_bar_w = int(
                                                            (strategy_cache or {}).get(
                                                                "_deployment_bar_index", 1
                                                            ) or 1
                                                        )
                                                        _cv_hist_w.append(_cv_bar_w)
                                                    except Exception:
                                                        pass
                                                    _cv_cache_w[_wt] = _cv_hist_w
                                                # Fall through to append as full-exit pair (net-zero swap).
                                            else:
                                                _log(
                                                    f"V28.8.1 rotation pair SKIPPED (at cap, partial trim, winner/marginal): "
                                                    f"{_wt}(pnl={_v289_held_pnl_pct:+.1f}%, {_sell_fraction:.0%})\u2192{_bb} "
                                                    f"mode={_rotation_mode}",
                                                    "yellow",
                                                )
                                                continue
                                        _rotation_pairs.append(
                                            {
                                                "sell": _wt,
                                                "buy": _bb,
                                                "sell_pnl": _wd.get("unrealized_pct", 0.0),
                                                "sell_fraction": _sell_fraction,
                                                "mode": _rotation_mode,
                                            }
                                        )
                                        _rotation_sell_size_overrides[_wt] = {"sell_fraction": _sell_fraction}
                                        if _bb not in stock_buys_scored:
                                            stock_buys_scored.append(_bb)
                                        if _wt not in sell_syms:
                                            sell_syms.append(_wt)
                                        if _is_break_glass_mode:
                                            # V28 Fix 5: set per-hold trim cooldown so this
                                            # position is not trimmed again immediately.
                                            try:
                                                _v28_trim_cd[_wt] = int(_v28_trim_cd_bars)
                                            except Exception:
                                                pass
                                            _log(
                                                f"Rotation partial trim ({_rotation_mode}): sell {_sell_fraction:.0%} {_wt} "
                                                f"(P&L={_wd.get('unrealized_pct', 0.0):.1f}%, held={_held_days_label}, rot={_wd.get('rotation_score', _wd['score']):.3f}) "
                                                f"\u2192 fund {_bb} (raw={_bb_score:.3f}, rot={_bb_rotation_score:.3f}, delta={_rotation_delta:.3f}) "
                                                f"[trim_cooldown={_v28_trim_cd_bars}d]",
                                                "magenta",
                                            )
                                        else:
                                            _log(
                                                f"Rotation full exit allowed: sell {_wt} "
                                                f"(P&L={_wd.get('unrealized_pct', 0.0):.1f}%, held={_held_days_label}, rot={_wd.get('rotation_score', _wd['score']):.3f}) "
                                                f"\u2192 buy {_bb} (raw={_bb_score:.3f}, rot={_bb_rotation_score:.3f}, delta={_rotation_delta:.3f})",
                                                "magenta",
                                            )
                                        break

                # V28 Fix 4: post-rotation summary log so we can see exactly
                # which blocked_buys got funded and which got starved.
                if _blocked_buys and (_rotation_pairs or _hc_in_blocked):
                    _funded_buys = {p["buy"] for p in _rotation_pairs}
                    _unfunded_blocked = [s for s in _blocked_buys if s not in _funded_buys]
                    _pair_summary = ", ".join(
                        f"{p['buy']}<-{p['sell']}({p['mode']},{p.get('sell_fraction',1.0):.0%})"
                        for p in _rotation_pairs
                    )
                    _unfunded_summary = ", ".join(
                        f"{_s}(raw={_bb_raw(_s):.3f},age={_bb_age(_s)}d)" for _s in _unfunded_blocked[:15]
                    )
                    _log(
                        f"V28 ROTATION RESULT: fired={len(_rotation_pairs)}/{_effective_max_rotations} "
                        f"pairs=[{_pair_summary}] "
                        f"unfunded={len(_unfunded_blocked)} (top: {_unfunded_summary})",
                        "magenta" if _rotation_pairs else "yellow",
                    )
                _evict_cooldown_dirty = False
                for _rp in _rotation_pairs:
                    if float((_rp or {}).get("sell_fraction", 1.0) or 1.0) >= 0.999:
                        nexus_sell_enforcement.add(_rp["sell"])
                        # ADDED BY CODEX (Fix 2C): mark the evicted ticker for re-buy
                        # cooldown so we don't flip-flop into the same name.
                        if strategy_cache is not None:
                            _evict_cooldown[_rp["sell"]] = _evict_cooldown_bars
                            _evict_cooldown_dirty = True
                # Sweep-3: persist cooldown to DB so a stop+resume preserves the state
                if _evict_cooldown_dirty and conn_trends is not None:
                    _save_evict_cooldown_to_db(conn_trends, instance_id, _evict_cooldown)
                _rotation_sell_budget = _estimate_rotation_sell_proceeds(
                    _rotation_pairs,
                    _prelim_sell_sizes,
                    prices,
                    portfolio_emulator,
                    price_history=data,
                )
                if _rotation_sell_budget > 0:
                    _available_buy_budget += _rotation_sell_budget
                    _stock_budget_available += _rotation_sell_budget
                    _log(
                        f"Rotation funding: +${_rotation_sell_budget:.0f} of sell proceeds released for replacement buys",
                        "magenta",
                    )

                _held_add_candidates = [s for s in stock_buys_scored if s in _open_positions_set]
                # V15 fix: also include held positions that meet the lower winner_add_min_raw_score
                # threshold, even if they don't meet the higher buy_threshold. This ensures
                # winners like DGII (+18%) aren't excluded from add-on buys just because
                # their current raw score (e.g. 0.27) is below buy_threshold (0.3).
                _wa_raw_min = float(config.get("winner_add_min_raw_score", 0.25) or 0.25)
                # sorted(): this appends to an ordered candidate list, so set
                # iteration order leaked into which winner-adds were considered.
                for _sym in sorted(_open_positions_set):
                    if _sym not in _held_add_candidates:
                        _sym_raw = float((scores.get(_sym) or {}).get("raw_net_score", 0.0) or 0.0)
                        if _sym_raw >= _wa_raw_min:
                            _held_add_candidates.append(_sym)
                _new_stock_candidates = [s for s in stock_buys_scored if s not in _open_positions_set]

                _winner_add_docs = []
                for _sym in _held_add_candidates:
                    _candidate_meta = _build_nexus_candidate_meta(
                        _sym,
                        scores.get(_sym),
                        config,
                        strategy_cache=strategy_cache,
                        is_propagation_expansion=_sym in _prop_expansion_set_alloc,
                        is_watchlist_member=_sym in _watchlist_member_tickers,
                        is_watchlist_priority=_sym in _watchlist_priority_tickers,
                    )
                    _ctx = _build_position_health_snapshot(
                        _sym,
                        portfolio_emulator=portfolio_emulator,
                        prices=prices,
                        price_history=data,
                        strategy_cache=strategy_cache,
                        date_key=date_key,
                        raw_score=float((scores.get(_sym) or {}).get("raw_net_score", 0.0) or 0.0),
                    )
                    _ctx.update(
                        {
                            "ticker": _sym,
                            "raw_net_score": float((scores.get(_sym) or {}).get("raw_net_score", 0.0) or 0.0),
                            "signal_source": _candidate_meta["signal_source"],
                            "is_watchlist_member": bool(_candidate_meta["is_watchlist_member"]),
                            "is_watchlist_priority": bool(_candidate_meta["is_watchlist_priority"]),
                            "is_propagation_expansion": bool(_candidate_meta["is_propagation_expansion"]),
                            "grace_eligible": bool(_candidate_meta["grace_eligible"]),
                            "existing_add_count": max(0, int((_ctx.get("buy_count", 1) or 1) - 1)),
                            # Task 12: current market value of the held position, so
                            # _plan_winner_adds can enforce single_position_max_pct.
                            "position_value": float(
                                (getattr(portfolio_emulator, "_positions", {}) or {}).get(_sym, 0.0) or 0.0
                            ) * float(_ctx.get("current_price", 0.0) or 0.0),
                        }
                    )
                    _winner_add_docs.append(_ctx)

                # V11: Reserve 60% of stock budget for new entries
                _winner_add_budget_cap = _stock_budget_available * 0.40
                _winner_add_budget = min(_stock_budget_available, _winner_add_budget_cap)

                _winner_add_funded: list = []
                _stock_budget_after_adds = _stock_budget_available
                # ADDED BY CODEX (Fix 1A): risk-off guard — winner adds must respect drawdown halt
                # and downtrend protection so they don't bypass portfolio safety rails.
                if not _drawdown_halt_active and not _downtrend_active:
                    # V31 Section 3.3: anchor reinforcement (3 stages) replaces winner_adds
                    # AND momentum_amplifier when feature flag is enabled (default).
                    _v31_anchor_enabled = bool(config.get("anchor_reinforce_enabled", True))
                    if _v31_anchor_enabled:
                        _log(
                            f"V31 anchor reinforcement budget: cap=${_winner_add_budget_cap:.0f} "
                            f"(40% of stock_budget=${_stock_budget_available:.0f}), "
                            f"candidates={len(_winner_add_docs)}",
                            "cyan",
                        )
                        _winner_add_funded, _stock_budget_after_adds = _plan_anchor_reinforcement(
                            _winner_add_docs,
                            _winner_add_budget,
                            min_position_size=_min_position_size,
                            config=config,
                            strategy_cache=strategy_cache,
                            portfolio_total=portfolio_total,
                        )
                    else:
                        # Legacy winner_adds path (bisection fallback)
                        _log(
                            f"Winner add budget: cap=${_winner_add_budget_cap:.0f} (40% of stock_budget=${_stock_budget_available:.0f}), "
                            f"candidates={len(_winner_add_docs)}",
                            "cyan",
                        )
                        _winner_add_funded, _stock_budget_after_adds = _plan_winner_adds(
                            _winner_add_docs,
                            _winner_add_budget,
                            min_position_size=_min_position_size,
                            config=config,
                            portfolio_total=portfolio_total,
                        )
                    # Sweep-3 fix: filter out winner adds whose live-bar score is a sell
                    # signal BEFORE computing spent. The previous order summed buy_cash
                    # for all funded items, then skipped sell-signal items inside the
                    # promotion loop — leaving _stock_budget_after_adds over-deducted.
                    # Also drop tickers already in nexus_sell_enforcement so trend
                    # reversal / consecutive-sell prunes can't be silently overridden.
                    _winner_add_funded_filtered = []
                    for _add in _winner_add_funded:
                        _add_existing = scores.get(_add["ticker"]) if isinstance(scores.get(_add["ticker"]), dict) else None
                        if _add_existing is not None and int(_add_existing.get("score", 0) or 0) == -1:
                            _log(
                                f"Winner add skipped: {_add['ticker']} has live sell signal "
                                f"(score=-1) — refusing to override",
                                "yellow",
                            )
                            continue
                        if _add["ticker"] in nexus_sell_enforcement:
                            _log(
                                f"Winner add skipped: {_add['ticker']} in nexus_sell_enforcement "
                                f"— refusing to override",
                                "yellow",
                            )
                            continue
                        if _add_existing is not None and bool(_add_existing.get("_forced_exit")):
                            _log(
                                f"Winner add skipped: {_add['ticker']} has _forced_exit=True "
                                f"— refusing to override",
                                "yellow",
                            )
                            continue
                        _winner_add_funded_filtered.append(_add)
                    _winner_add_funded = _winner_add_funded_filtered
                    # V11: Return unused winner-add budget to the pool for new entries
                    _winner_add_spent = sum(
                        float(_a.get("buy_cash", 0.0) or 0.0) for _a in _winner_add_funded
                    )
                    _stock_budget_after_adds = _stock_budget_available - _winner_add_spent
                    for _add in _winner_add_funded:
                        nexus_position_sizes[_add["ticker"]] = {
                            "buy_cash": round(float(_add.get("buy_cash", 0.0) or 0.0), 2),
                            "high_conviction": float(_add.get("raw_net_score", 0.0) or 0.0) >= 0.50,
                            "asset_class": "stock",
                            "raw_net_score": round(float(_add.get("raw_net_score", 0.0) or 0.0), 4),
                            "signal_source": str(_add.get("signal_source") or "winner_add"),
                            "is_watchlist_member": bool(_add.get("is_watchlist_member")),
                            "is_watchlist_priority": bool(_add.get("is_watchlist_priority")),
                            "is_propagation_expansion": bool(_add.get("is_propagation_expansion")),
                            "grace_eligible": bool(_add.get("grace_eligible")),
                            "winner_add": True,
                        }
                        # ADDED BY CODEX (Fix 1A): promote scores so the broker actually sees this
                        # as a buy decision (the broker reads scores, not nexus_position_sizes).
                        if _add["ticker"] in scores and isinstance(scores.get(_add["ticker"]), dict):
                            scores[_add["ticker"]]["score"] = 1
                            scores[_add["ticker"]]["action_intent"] = "winner_add_buy"
                        else:
                            scores[_add["ticker"]] = {
                                "score": 1,
                                "action_intent": "winner_add_buy",
                                "raw_net_score": float(_add.get("raw_net_score", 0.0) or 0.0),
                            }
                        _log(
                            f"Winner add-on: {_add['ticker']} alloc=${float(_add.get('buy_cash', 0.0) or 0.0):.0f} "
                            f"(P&L={float(_add.get('unrealized_pct', 0.0) or 0.0):+.1f}%, held={int(_add.get('held_days', 0) or 0)}d, "
                            f"drop={float(_add.get('drop_from_peak_pct', 0.0) or 0.0):.1f}%)",
                            "green",
                        )
                else:
                    _log(
                        f"Winner adds skipped: drawdown_halt={_drawdown_halt_active}, downtrend={_downtrend_active}",
                        "yellow",
                    )

                # ── Momentum amplifier: buy MORE shares of exceptional momentum runners ──
                # V18a Codex fix: exclude winner-add funded tickers from amplifier to prevent
                # double-booking budget. Also cap amplifier by remaining stock budget.
                # V22: Reserve a portion of budget for new entries before amplifier consumes it.
                _winner_add_funded_tickers = {a["ticker"] for a in _winner_add_funded}
                _new_entry_reserve_pct = float(config.get("new_entry_reserved_budget_pct", 0.30) or 0.30)
                _new_entry_reserve = _stock_budget_after_adds * _new_entry_reserve_pct
                _amplifier_budget_remaining = max(0.0, _stock_budget_after_adds - _new_entry_reserve)
                # ADDED BY CODEX (Fix 1B): risk-off guard — amplifier ignores live-bar score and
                # would otherwise plow into downtrending positions during halts.
                # V31 Section 3.3: skip amplifier entirely when anchor reinforcement is on
                # (anchor reinforcement already covers the same job with structurally-aware staging).
                if (
                    not _drawdown_halt_active
                    and not _downtrend_active
                    and not bool(config.get("anchor_reinforce_enabled", True))
                    and config.get("momentum_amplifier_enabled", True)
                    and portfolio_total > 0
                    and _amplifier_budget_remaining > 0
                ):
                    _amplifier_buys = _momentum_amplifier_pass(
                        portfolio_emulator, scores, config,
                        strategy_cache=strategy_cache,
                        date_key=date_key,
                        portfolio_total=portfolio_total,
                    )
                    # Filter out tickers that already got winner adds this bar
                    _amplifier_buys = [a for a in _amplifier_buys if a["ticker"] not in _winner_add_funded_tickers]
                    for _amp in _amplifier_buys:
                        # Sweep-2 fix: skip amplifier if the live-bar score is a sell signal.
                        # Otherwise Fix 1B's promotion below would override a -1 sentiment-driven
                        # sell into a buy, even though the position isn't in nexus_sell_enforcement.
                        _amp_existing = scores.get(_amp["ticker"]) if isinstance(scores.get(_amp["ticker"]), dict) else None
                        if _amp_existing is not None and int(_amp_existing.get("score", 0) or 0) == -1:
                            _log(
                                f"Amplifier skipped: {_amp['ticker']} has live sell signal "
                                f"(score=-1) — refusing to override",
                                "yellow",
                            )
                            continue
                        # Sweep-3 fix: also block amplifier on tickers in nexus_sell_enforcement
                        # (trend reversal / consecutive sell pruning) and on _forced_exit positions
                        # (fast loser, trailing stop, hold-limit). The base score check above
                        # catches most cases, but a hold-limit fired on a +30%-+38% position
                        # technically passes the amplifier P&L gate while still being a forced sell.
                        if _amp["ticker"] in nexus_sell_enforcement:
                            _log(
                                f"Amplifier skipped: {_amp['ticker']} in nexus_sell_enforcement "
                                f"— refusing to override",
                                "yellow",
                            )
                            continue
                        if _amp_existing is not None and bool(_amp_existing.get("_forced_exit")):
                            _log(
                                f"Amplifier skipped: {_amp['ticker']} has _forced_exit=True "
                                f"— refusing to override",
                                "yellow",
                            )
                            continue
                        # Cap by amplifier budget (reserves new_entry_reserved_budget_pct for new entries)
                        _amp["buy_cash"] = min(_amp["buy_cash"], max(0.0, _amplifier_budget_remaining))
                        if _amp["buy_cash"] < float(config.get("min_position_size", 100.0) or 100.0):
                            continue
                        nexus_position_sizes[_amp["ticker"]] = {
                            "buy_cash": _amp["buy_cash"],
                            "score": 1,
                            "raw_net_score": float((scores.get(_amp["ticker"]) or {}).get("raw_net_score", 0.0) or 0.0),
                            "signal_source": "momentum_amplifier",
                            "is_watchlist_member": _amp["ticker"] in _watchlist_member_tickers,
                            "is_watchlist_priority": _amp["ticker"] in _watchlist_priority_tickers,
                            "is_propagation_expansion": False,
                            "grace_eligible": False,
                            "momentum_amplifier": True,
                        }
                        # ADDED BY CODEX (Fix 1B): promote scores so the broker actually executes.
                        if _amp["ticker"] in scores and isinstance(scores.get(_amp["ticker"]), dict):
                            scores[_amp["ticker"]]["score"] = 1
                            scores[_amp["ticker"]]["action_intent"] = "momentum_amplifier_buy"
                        else:
                            scores[_amp["ticker"]] = {
                                "score": 1,
                                "action_intent": "momentum_amplifier_buy",
                                "raw_net_score": float((scores.get(_amp["ticker"]) or {}).get("raw_net_score", 0.0) or 0.0),
                            }
                        _stock_budget_after_adds -= _amp["buy_cash"]
                        _amplifier_budget_remaining -= _amp["buy_cash"]
                elif (_drawdown_halt_active or _downtrend_active) and config.get("momentum_amplifier_enabled", True):
                    _log(
                        f"Momentum amplifier skipped: drawdown_halt={_drawdown_halt_active}, downtrend={_downtrend_active}",
                        "yellow",
                    )

                _stock_candidate_docs = []
                for _sym in _new_stock_candidates:
                    _candidate_meta = _build_nexus_candidate_meta(
                        _sym,
                        scores.get(_sym),
                        config,
                        strategy_cache=strategy_cache,
                        is_propagation_expansion=_sym in _prop_expansion_set_alloc,
                        is_watchlist_member=_sym in _watchlist_member_tickers,
                        is_watchlist_priority=_sym in _watchlist_priority_tickers,
                    )
                    _stock_candidate_docs.append(
                        {
                            "ticker": _sym,
                            "raw_net_score": float((scores.get(_sym) or {}).get("raw_net_score", 0.0) or 0.0),
                            # Wire n_paths through so _conviction_allocation_schedule
                            # can use it as a saturation tiebreak. scores[sym] is
                            # populated at line ~15037 from propagated[sym]["n_paths"].
                            "n_paths": int((scores.get(_sym) or {}).get("n_paths", 0) or 0),
                            "signal_source": _candidate_meta["signal_source"],
                            "is_watchlist_member": bool(_candidate_meta["is_watchlist_member"]),
                            "is_watchlist_priority": bool(_candidate_meta["is_watchlist_priority"]),
                            "is_propagation_expansion": bool(_candidate_meta["is_propagation_expansion"]),
                            "grace_eligible": bool(_candidate_meta["grace_eligible"]),
                        }
                    )
                _funded_stock_slate, _queued_for_cash_or_slots, _stock_slate_meta = _plan_executable_stock_buy_slate(
                    _stock_candidate_docs,
                    _stock_budget_after_adds,
                    min_position_size=_min_position_size,
                    config=config,
                    blocked_tickers=_v31_blocked_set,
                    # Tier-3 B2: thread broker's _initial_value so scaled new-buy
                    # cap can pick the right account-size bucket.
                    initial_value=float(getattr(portfolio_emulator, "_initial_value", 0.0) or 0.0),
                    # Task 12: current portfolio total for the single_position_max_pct cap.
                    portfolio_total=portfolio_total,
                )
                # V31 Section 4.3: vol-adjusted sizing — reweight slate so high-vol
                # names get smaller positions and low-vol names get larger ones,
                # while preserving total budget invariance.
                if bool(config.get("vol_adjust_sizing_enabled", True)) and _funded_stock_slate:
                    _funded_stock_slate = _apply_vol_adjustment(_funded_stock_slate, data, config)
                    if _funded_stock_slate:
                        _vol_adj_summary = ", ".join(
                            f"{f.get('ticker','?')}:{float(f.get('vol_adjust_mult', 1.0)):.2f}x"
                            for f in _funded_stock_slate[:5]
                            if "vol_adjust_mult" in f
                        )
                        if _vol_adj_summary:
                            _log(f"V31 vol-adjust applied: {_vol_adj_summary}", "cyan")
                # V31 Section 4.4: portfolio-level sector concentration cap.
                # Distinct from existing per-bar `max_sector_buy_pct`. Demotes
                # lowest-conviction buys until each sector is under the cap.
                if bool(config.get("max_sector_portfolio_enabled", True)) and _funded_stock_slate:
                    _funded_stock_slate = _enforce_sector_portfolio_cap(
                        _funded_stock_slate,
                        portfolio_emulator,
                        portfolio_total,
                        config,
                        prices=prices,
                        price_history=data,
                        # η.G — Phase η (2026-05-20): supply context so the cap
                        # enforcer can attempt a conditional swap before
                        # demoting eligible HIGH-conviction new buys.
                        scores=scores,
                        strategy_cache=strategy_cache,
                        propagated=propagated,
                        nexus_sell_enforcement=nexus_sell_enforcement,
                        sentiment_data=sentiment_data,
                        date_key=date_key,
                    )
                # HM fix: Deduct slate consumption so reserved slot doesn't double-allocate
                _slate_spend = sum(float(f.get("buy_cash", 0.0) or 0.0) for f in _funded_stock_slate)
                _stock_budget_after_adds = max(0.0, _stock_budget_after_adds - _slate_spend)
                _deferred_stock_slate_candidates = {
                    str(_sym).strip().upper()
                    for _sym in (_queued_for_cash_or_slots or [])
                    if str(_sym).strip()
                }
                if _stock_slate_meta.get("selected"):
                    _log(f"Executable stock slate: {', '.join(_stock_slate_meta['selected'])}", "cyan")
                if _queued_for_cash_or_slots:
                    _log(
                        f"Queued due to cash / slot cap: {', '.join(_queued_for_cash_or_slots[:8])}"
                        f"{'...' if len(_queued_for_cash_or_slots) > 8 else ''}",
                        "cyan",
                    )
                for _funded in _funded_stock_slate:
                    nexus_position_sizes[_funded["ticker"]] = {
                        "buy_cash": round(float(_funded.get("buy_cash", 0.0) or 0.0), 2),
                        "high_conviction": float(_funded.get("raw_net_score", 0.0) or 0.0) >= 0.50,
                        "asset_class": "stock",
                        "raw_net_score": round(float(_funded.get("raw_net_score", 0.0) or 0.0), 4),
                        "signal_source": str(_funded.get("signal_source") or ""),
                        "is_watchlist_member": bool(_funded.get("is_watchlist_member")),
                        "is_watchlist_priority": bool(_funded.get("is_watchlist_priority")),
                        "is_propagation_expansion": bool(_funded.get("is_propagation_expansion")),
                        "grace_eligible": bool(_funded.get("grace_eligible")),
                    }
            if etf_buys and _etf_budget_available > 0:
                # V12: Enforce min_position_size for ETFs — skip undersized allocations
                _etf_min = max(_min_position_size, float(config.get("etf_min_position_size", _min_position_size) or _min_position_size))
                # Determine how many ETFs can be funded at the minimum
                _max_fundable_etfs = max(1, int(_etf_budget_available / _etf_min)) if _etf_budget_available >= _etf_min else 0
                _etf_to_fund = etf_buys[:_max_fundable_etfs] if _max_fundable_etfs > 0 else []
                # Phase ε.C.4 (BT294837 follow-up, 2026-05-19, root cause of
                # permanent V28.8.1 BREACH state): the ETF allocation channel
                # pre-ε.C.4 wrote `nexus_position_sizes[sym] = {"asset_class":
                # "etf", ...}` without consulting `_current_positions`,
                # `_max_positions`, or `_v28_7_position_breach_active`. On
                # bar 1 of BT294837, 4-6 trend ETFs (BOTZ/ROBT/WTAI/ARKQ/
                # UBOT/AIQ) plus 8 stocks seated immediately → 12-14
                # positions vs cap=8. ETFs are protected by profitable_
                # min_hold/winner_lock and never roll off, leaving the
                # portfolio in permanent BREACH. The breach flag then
                # blocks BFQ dequeue + partial-trim rotations, starving
                # all HC propagation discoveries (16 unfunded per breach
                # bar in BT294837). The fix: enforce a per-account ETF
                # position cap (`max_positions_etf`, default 4) using a
                # cache-tracked held-ETF set. Existing held ETFs ride
                # along; new ETF buys are skipped if at the cap. NO
                # TICKER HARDCODING — works for any ETF universe.
                try:
                    _etf_max_held = max(0, int(config.get("max_positions_etf", 4) or 4))
                except (TypeError, ValueError):
                    _etf_max_held = 4
                _held_etf_tracker = (
                    strategy_cache.setdefault("_nexus_held_etfs", set())
                    if strategy_cache is not None
                    else set()
                )
                if not isinstance(_held_etf_tracker, set):
                    # Persistence may have round-tripped to a list/dict
                    try:
                        _held_etf_tracker = set(_held_etf_tracker or [])
                    except TypeError:
                        _held_etf_tracker = set()
                    if strategy_cache is not None:
                        strategy_cache["_nexus_held_etfs"] = _held_etf_tracker
                # Reconcile tracker against the LIVE portfolio.
                # Phase ε.C.4 fix (bug-sweep adversarial finding B2): the
                # tracker must do TWO operations each bar:
                # (a) DROP sold ETFs (intersection_update with live held),
                # (b) ADD currently-held ETFs from `etf_set` ∩ portfolio
                # so warm-start with empty cache doesn't lose the live
                # ETF count and permit over-allocation. `etf_set` is the
                # known ETF universe in scope here; intersecting with live
                # positions gives the actual held-ETF set.
                _live_held_set: set[str] = set()
                if portfolio_emulator is not None:
                    try:
                        _pe_positions = getattr(portfolio_emulator, "_positions", {}) or {}
                        _live_held_set = {
                            str(t or "").strip().upper()
                            for t, q in _pe_positions.items()
                            if float(q or 0) > 0
                        }
                    except Exception:
                        _live_held_set = set()
                # Restrict reconciliation domain to known ETFs (intersect with
                # etf_set if available). This avoids accidentally classifying
                # stock positions as ETFs.
                _etf_universe: set[str] = set()
                try:
                    _etf_universe = {str(t or "").strip().upper() for t in (etf_set or set()) if str(t or "").strip()}
                except (TypeError, ValueError):
                    _etf_universe = set()
                # (a) drop sold/non-existent entries from prior bars
                _held_etf_tracker.intersection_update(_live_held_set)
                # (b) add currently-held ETFs that aren't yet in the tracker
                #     (warm-start case OR positions opened outside this strategy)
                if _etf_universe:
                    _held_etf_tracker.update(_live_held_set & _etf_universe)
                _etf_slots_remaining = max(0, _etf_max_held - len(_held_etf_tracker))
                if _etf_slots_remaining < len(_etf_to_fund):
                    _etf_capped_out = _etf_to_fund[_etf_slots_remaining:]
                    _etf_to_fund = _etf_to_fund[:_etf_slots_remaining]
                    _log(
                        f"[ε.C.4] ETF cap reached: max_positions_etf={_etf_max_held}, "
                        f"currently_held={len(_held_etf_tracker)}, slots_remaining="
                        f"{_etf_slots_remaining}. Skipping {len(_etf_capped_out)} "
                        f"new ETF buy(s): {_etf_capped_out}",
                        "yellow",
                    )
                if _etf_to_fund:
                    cash_per_etf = _etf_budget_available / len(_etf_to_fund)
                    for sym in _etf_to_fund:
                        nexus_position_sizes[sym] = {"buy_cash": round(cash_per_etf, 2), "asset_class": "etf", "signal_source": "etf"}
                        _held_etf_tracker.add(str(sym or "").strip().upper())
                    if len(_etf_to_fund) < len(etf_buys):
                        _skipped_etfs = [s for s in etf_buys if s not in _etf_to_fund]
                        _log(f"ETF min-size filter: funded {len(_etf_to_fund)} ETF(s) @ ${cash_per_etf:.0f} each, skipped {len(_skipped_etfs)}: {_skipped_etfs} (min=${_etf_min:.0f})", "yellow")
                elif etf_buys:
                    _log(f"ETF budget too low: ${_etf_budget_available:.0f} < ${_etf_min:.0f} min — skipping all {len(etf_buys)} ETF buys", "yellow")

        # Momentum watchlist sell protection: held momentum positions
        # are protected from LLM sell signals. Only forced exits (trailing
        # stop, fast loser) can sell them — those use _forced_exit flag which
        # is checked separately below.
        _mw_protected: set[str] = set()
        if config.get("momentum_watchlist_enabled", False) and strategy_cache is not None:
            _mw_protected = set((strategy_cache.get("_momentum_held") or {}).keys())
            # Also protect tickers being bought this bar via momentum watchlist.
            # Use momentum_watchlist_score in scores dict as the definitive marker
            # (signal_source gets overridden to "watchlist_priority" by _build_nexus_candidate_meta).
            for _sym, _score_doc in scores.items():
                if isinstance(_score_doc, dict) and float(_score_doc.get("momentum_watchlist_score", 0) or 0) > 0:
                    _mw_protected.add(str(_sym).strip().upper())

        # Sell sizes: use LLM-provided sell_pct (partial sell support)
        for sym in sell_syms:
            # A partial-sell hint (e.g. a profit-take tier trim) must still be sized
            # even for momentum-protected names — otherwise the broker defaults to a
            # 100% liquidation instead of the intended partial trim.
            _sym_sf_hint = (scores.get(sym) or {}).get("sell_fraction")
            _is_partial_sell = _sym_sf_hint is not None and 0.0 < float(_sym_sf_hint or 1.0) < 1.0
            if sym in _mw_protected and not _is_partial_sell:
                continue
            sd = sentiment_data.get(sym) or {}
            sp = float((scores.get(sym) or {}).get("sell_fraction", sd.get("sell_pct", 1.0)) or 1.0)
            sp = max(0.01, min(1.0, sp))
            entry = nexus_position_sizes.get(sym, {})
            entry["sell_fraction"] = sp
            nexus_position_sizes[sym] = entry

        # Enforced sells always sell fully
        for sym in nexus_sell_enforcement:
            if sym in _mw_protected:
                continue
            entry = nexus_position_sizes.get(sym, {})
            entry["sell_fraction"] = 1.0
            nexus_position_sizes[sym] = entry
        for sym, override in _rotation_sell_size_overrides.items():
            if sym in nexus_sell_enforcement:
                continue
            if sym in _mw_protected:
                continue
            sell_fraction = float((override or {}).get("sell_fraction", 0.0) or 0.0)
            if sell_fraction <= 0.0:
                continue
            entry = nexus_position_sizes.get(sym, {})
            entry["sell_fraction"] = sell_fraction
            nexus_position_sizes[sym] = entry

        if nexus_position_sizes:
            _stock_buy_count = sum(
                1
                for _sym, _hint in nexus_position_sizes.items()
                if not str(_sym).startswith("_")
                and isinstance(_hint, dict)
                and float(_hint.get("buy_cash", 0.0) or 0.0) > 0.0
                and str(_hint.get("asset_class") or "stock").strip().lower() != "etf"
            )
            _etf_buy_count = sum(
                1
                for _sym, _hint in nexus_position_sizes.items()
                if not str(_sym).startswith("_")
                and isinstance(_hint, dict)
                and float(_hint.get("buy_cash", 0.0) or 0.0) > 0.0
                and str(_hint.get("asset_class") or "stock").strip().lower() == "etf"
            )
            _sell_count = sum(
                1
                for _sym, _hint in nexus_position_sizes.items()
                if not str(_sym).startswith("_")
                and isinstance(_hint, dict)
                and float(_hint.get("sell_fraction", 0.0) or 0.0) > 0.0
            )
            _log(
                f"Pre-queue position sizes: {_stock_buy_count} stock buys sized "
                f"(from {len(stock_buys)} buy signals), {_etf_buy_count} ETF buys sized "
                f"(from {len(etf_buys)} ETF signals), "
                f"{_sell_count} sells (portfolio_total={portfolio_total:.0f})",
                "cyan",
            )

        # ── Momentum Watchlist: track bought positions + rotation swap ──
        # Clear per-bar rotation sell tracker + per-bar momentum-sized set
        # + per-bar free-cash spend tracker (V31.2 shared across Fix 5 A/B + Fix B)
        if isinstance(strategy_cache, dict):
            strategy_cache["_mw_rotation_sells_this_bar"] = set()
            strategy_cache["_mw_sized_this_bar"] = set()
            strategy_cache["_mw_free_cash_spent_this_bar"] = 0.0
        if config.get("momentum_watchlist_enabled", False) and strategy_cache is not None:
            _mw_held = strategy_cache.setdefault("_momentum_held", {})
            _mw_bar = int(strategy_cache.get("_deployment_bar_index", 1) or 1)
            # Bug fix #1: build _open_positions_set unconditionally (may not
            # exist if stock_buys was empty and the allocation block didn't run)
            _mw_open_set: set[str] = set()
            if portfolio_emulator is not None:
                for _mw_s, _mw_q in (getattr(portfolio_emulator, "_positions", {}) or {}).items():
                    if float(_mw_q or 0) > 0:
                        _mw_open_set.add(str(_mw_s).strip().upper())
            # Track newly bought momentum positions
            for _sym, _hint in nexus_position_sizes.items():
                if isinstance(_hint, dict) and float(_hint.get("buy_cash", 0) or 0) > 0:
                    _src = str(_hint.get("signal_source") or "")
                    _mw_score_val = float((scores.get(_sym) or {}).get("momentum_watchlist_score", 0) or 0)
                    if _src == "momentum_watchlist" or _mw_score_val > 0:
                        _mw_held[_sym] = {
                            "bar_entered": _mw_bar,
                            "entry_score": _mw_score_val,
                            "current_score": _mw_score_val,
                        }
            # Remove sold momentum positions (and populate re-buy cooldown
            # to prevent same-name churn — Codex BLOCK fix for Change 3).
            # 2026-05-07 granularity-scaling: cooldown is bar-decremented;
            # scale to keep wall-clock churn-prevention window constant.
            _mw_cooldown_bars = _scale_bars(int(config.get("momentum_sell_cooldown_bars", 5) or 5), config)
            _mw_cooldown_store = strategy_cache.setdefault("_momentum_sell_cooldown", {}) if isinstance(strategy_cache, dict) else {}
            # V31.4 Fix 17: record sold position into post_sell_breakout_history
            # for later breakout-re-entry detection.
            _ps_history_write = strategy_cache.setdefault("_post_sell_breakout_history", {}) if isinstance(strategy_cache, dict) else {}
            def _record_ps_history(_ps_sym: str, _ps_reason: str):
                try:
                    _ps_exit_price = _resolve_symbol_price(
                        _ps_sym, prices, data, portfolio_emulator=portfolio_emulator,
                    )
                    _ps_history_write[str(_ps_sym).strip().upper()] = {
                        "sell_bar": int(_mw_bar),
                        "sell_date": str(date_key or ""),
                        "sell_price": float(_ps_exit_price or 0.0),
                        "sell_reason": _ps_reason,
                    }
                except Exception:
                    pass
            for _sym in list(_mw_held.keys()):
                if _sym in (nexus_sell_enforcement or set()):
                    del _mw_held[_sym]
                    if _mw_cooldown_bars > 0 and isinstance(_mw_cooldown_store, dict):
                        _mw_cooldown_store[_sym] = _mw_cooldown_bars
                    _record_ps_history(_sym, "sell_enforcement")
                elif _sym in (sell_syms or []):
                    _sell_frac = float(nexus_position_sizes.get(_sym, {}).get("sell_fraction", 0) or 0)
                    if _sell_frac >= 1.0:
                        del _mw_held[_sym]
                        if _mw_cooldown_bars > 0 and isinstance(_mw_cooldown_store, dict):
                            _mw_cooldown_store[_sym] = _mw_cooldown_bars
                        _record_ps_history(_sym, "full_exit")
            # Clean stale entries (positions sold outside momentum system).
            # Exempt tickers being bought THIS bar — the broker hasn't executed
            # the buy yet, so they're not in _mw_open_set, but they will be next bar.
            _mw_buying_this_bar = {
                str(_s).strip().upper()
                for _s, _h in nexus_position_sizes.items()
                if isinstance(_h, dict) and float(_h.get("buy_cash", 0) or 0) > 0
            }
            for _sym in list(_mw_held.keys()):
                if _sym not in _mw_open_set and _sym not in _mw_buying_this_bar:
                    del _mw_held[_sym]
            # Bug fix #3: reuse scored result from slot reservation if available
            _mw_ranked_for_rot = strategy_cache.get("_momentum_ranked_cache") or []
            if not _mw_ranked_for_rot:
                try:
                    _mw_ranked_for_rot = _score_momentum_rank(
                        strategy_cache.get("_momentum_watchlist", {}),
                        strategy_cache, date_key, config,
                    )
                except Exception:
                    _mw_ranked_for_rot = []
            # Rotation swap: sell weakest held, buy strongest non-held.
            # Pass momentum-sell cooldown so we don't rotate INTO a ticker we
            # just rotated OUT of.
            _mw_rot_cooldown_map = strategy_cache.get("_momentum_sell_cooldown", {}) if isinstance(strategy_cache, dict) else {}
            _mw_rot_cooldown_set = set(_mw_rot_cooldown_map.keys())
            try:
                _mw_sell, _mw_buy, _mw_buy_score = _rotate_momentum_slots(
                    _mw_ranked_for_rot, _mw_held, config, _mw_bar, _mw_open_set,
                    recent_sell_cooldown=_mw_rot_cooldown_set,
                )
                if _mw_sell and _mw_buy and portfolio_emulator is not None:
                    # 2026-07-19 regime-safety Phase 3: lane regime gate.
                    _mw_lane_ok, _mw_lane_why = _rotation_lane_allowed(
                        strategy_cache, portfolio_emulator, config)
                    if not _mw_lane_ok:
                        _log(f"ROTATION lane blocked ({_mw_lane_why}): "
                             f"mw_rotation {_mw_sell}->{_mw_buy} skipped", "yellow")
                        _mw_sell, _mw_buy = None, None
                if _mw_sell and _mw_buy and portfolio_emulator is not None:
                    # V32 Phase 3 B-1: blacklist check (same fix as mw_buy lane).
                    _fl_bl_mwr = _normalize_cache_mapping(strategy_cache, "_fast_loser_blacklist") if strategy_cache else {}
                    if _mw_buy in _fl_bl_mwr:
                        _bl_rem_r = (_fl_bl_mwr.get(_mw_buy) or {}).get("bars_remaining", 0)
                        _log(f"V32 P3 B-1 mw_rotation blacklist-block: {_mw_buy} ({_bl_rem_r} bars remaining)", "yellow")
                        _mw_sell, _mw_buy = None, None
                if _mw_sell and _mw_buy and portfolio_emulator is not None:
                    # V32 T1-c + T2-a: momentum_watchlist_rotation lane gate on the BUY ticker.
                    _mw_buy_price_for_gate = _resolve_symbol_price(
                        _mw_buy, prices, data, portfolio_emulator=portfolio_emulator,
                    )
                    _mw_gate_blocked, _ = _v32_momentum_ath_or_mcap_block(
                        _mw_buy, _mw_buy_price_for_gate, data, strategy_cache,
                        config, float(_mw_buy_score or 0.0), log_fn=_log, lane="mw_rotation",
                        date_key=date_key,
                    )
                    if _mw_gate_blocked:
                        # Skip this rotation pair; keep current holding.
                        _mw_sell, _mw_buy = None, None
                if _mw_sell and _mw_buy and portfolio_emulator is not None:
                    # Run-185254 leak #1: validate the incoming BUY against the
                    # broker execution gates BEFORE the sell leg commits, so a
                    # sub-floor replacement can't turn the rotation sell-only.
                    _mw_rot_ok, _mw_rot_block = _rotation_incoming_executable(
                        _mw_buy, _mw_buy_price_for_gate, config,
                        asset_class=str((scores.get(_mw_buy) or {}).get("asset_class") or "stock"),
                    )
                    if not _mw_rot_ok:
                        _log(
                            f"ROTATION PREVALIDATE: skip incoming {_mw_buy} "
                            f"({_mw_rot_block}) — rotation skipped, keeping {_mw_sell}",
                            "yellow",
                        )
                        _mw_sell, _mw_buy = None, None
                if _mw_sell and _mw_buy and portfolio_emulator is not None:
                    _mw_sell_price = _resolve_symbol_price(
                        _mw_sell, prices, data, portfolio_emulator=portfolio_emulator,
                    )
                    _mw_sell_qty = float(
                        (getattr(portfolio_emulator, "_positions", {}) or {}).get(_mw_sell, 0)
                    )
                    _mw_freed = max(0.0, _mw_sell_price * _mw_sell_qty) if _mw_sell_price > 0 else 0.0
                    _mw_min_pos = float(config.get("min_position_size", 100.0) or 100.0)
                    # V31.2 Fix 5: enforce size floor via free-cash top-up.
                    # Previous formula min(freed, max(floor, ...)) capped at freed
                    # cash — floor never fired.
                    # V31.2 bug-sweep: use cumulative _mw_free_cash_spent tracker
                    # so Fix 5 Site A + Site B + Fix B don't double-spend the same
                    # free cash pool (broker hasn't executed yet, emulator cash
                    # snapshot is stale after first write).
                    _mw_size_floor_pct = float(config.get("momentum_position_size_floor_pct", 0.10) or 0.10)
                    _mw_size_floor = portfolio_total * _mw_size_floor_pct if portfolio_total > 0 else 0.0
                    _mw_free_cash_now = 0.0
                    if hasattr(portfolio_emulator, "get_cash"):
                        try:
                            _mw_free_cash_now = float(portfolio_emulator.get_cash() or 0.0)
                        except Exception as _mw_fc_exc:
                            _mw_free_cash_now = 0.0
                            _log(f"V31.2 WARN: get_cash() failed in momentum rotation: {_mw_fc_exc}", "yellow")
                    _mw_fc_spent_sofar = float((strategy_cache or {}).get("_mw_free_cash_spent_this_bar", 0.0) or 0.0)
                    _mw_free_cash_avail = max(0.0, _mw_free_cash_now - _mw_fc_spent_sofar)
                    _mw_extra_needed = max(0.0, _mw_size_floor - _mw_freed)
                    _mw_extra = min(_mw_extra_needed, _mw_free_cash_avail * 0.95)
                    _mw_buy_alloc = max(_mw_min_pos, _mw_freed + _mw_extra)
                    # Track A (run-163943): pre-validate the incoming BUY against
                    # the V31 sector-portfolio cap BEFORE the sell leg commits, so
                    # a rotation into an already-capped sector can't turn sell-only
                    # (06-12 DAR->AMD, 06-22 VIK/AIT->SMCI/LRCX were demoted).
                    _mw_sc_ok, _mw_sc_block = _rotation_incoming_sector_cap_ok(
                        _mw_buy, _mw_buy_alloc, portfolio_emulator, portfolio_total,
                        config, prices, data, selling_sym=_mw_sell,
                    )
                    if not _mw_sc_ok:
                        _log(
                            f"ROTATION PREVALIDATE sector-cap: skip incoming {_mw_buy} "
                            f"({_mw_sc_block}) — rotation skipped, keeping {_mw_sell}",
                            "yellow",
                        )
                    if isinstance(strategy_cache, dict) and _mw_sc_ok:
                        strategy_cache["_mw_free_cash_spent_this_bar"] = _mw_fc_spent_sofar + _mw_extra
                    if _mw_buy_alloc >= _mw_min_pos and _mw_sc_ok:
                        # Bug fix #2: capture sell score before deletion
                        _mw_sell_score = _mw_held.get(_mw_sell, {}).get("current_score", 0)
                        nexus_sell_enforcement.add(_mw_sell)
                        # Track rotation sell so final _mw_protected subtraction preserves it
                        if isinstance(strategy_cache, dict):
                            strategy_cache.setdefault("_mw_rotation_sells_this_bar", set()).add(_mw_sell)
                        sentiment_data[_mw_sell] = {"sentiment": -1, "event": "general"}
                        nexus_position_sizes[_mw_buy] = {
                            "buy_cash": round(_mw_buy_alloc, 2),
                            "high_conviction": True,
                            "asset_class": "stock",
                            "raw_net_score": round(max(_mw_buy_score, 0.50), 4),
                            "signal_source": "momentum_watchlist_rotation",
                            "is_propagation_expansion": False,
                            "is_watchlist_member": True,
                            "is_watchlist_priority": True,
                            "grace_eligible": True,
                        }
                        if _mw_buy not in scores:
                            scores[_mw_buy] = {}
                        scores[_mw_buy]["score"] = 1
                        scores[_mw_buy]["raw_net_score"] = max(_mw_buy_score, 0.50)
                        scores[_mw_buy]["action_intent"] = "momentum_watchlist_rotation"
                        # Update tracking + populate re-buy cooldown on the sold
                        # ticker so we don't rotate back into it next bar.
                        if _mw_sell in _mw_held:
                            del _mw_held[_mw_sell]
                        _mw_cooldown_bars_rot = _scale_bars(int(config.get("momentum_sell_cooldown_bars", 5) or 5), config)
                        if _mw_cooldown_bars_rot > 0 and isinstance(strategy_cache, dict):
                            strategy_cache.setdefault("_momentum_sell_cooldown", {})[_mw_sell] = _mw_cooldown_bars_rot
                        _mw_held[_mw_buy] = {
                            "bar_entered": _mw_bar,
                            "entry_score": _mw_buy_score,
                            "current_score": _mw_buy_score,
                        }
                        _log(
                            f"Momentum rotation: sell {_mw_sell} (score={_mw_sell_score:.3f}) "
                            f"→ buy {_mw_buy} (score={_mw_buy_score:.3f}, ${_mw_buy_alloc:.0f})",
                            "magenta",
                        )
            except Exception as _mw_rot_exc:
                _log(f"Momentum rotation error: {_mw_rot_exc}", "yellow")

            # ── V31.1 Fix A: Portfolio-wide momentum swap ─────────────────
            # If no momentum-vs-momentum rotation fired, try rotating against
            # the weakest NON-momentum held position. Lets SNDK/LITE break in
            # when the portfolio is filled with weaker non-momentum holds.
            # Only fires if the within-momentum rotation above didn't already
            # consume a slot (check nexus_sell_enforcement additions this bar).
            _mw_rot_sells_this_bar = (
                strategy_cache.get("_mw_rotation_sells_this_bar", set())
                if isinstance(strategy_cache, dict) else set()
            )
            if (
                config.get("momentum_swap_vs_portfolio_enabled", True)
                and not _mw_rot_sells_this_bar
                and portfolio_emulator is not None
                and _mw_ranked_for_rot
            ):
                try:
                    _mw_pf_pnl: dict[str, dict] = {}
                    for _mw_pf_sym in _mw_open_set:
                        # V31.1 Codex-fix: pass live raw_score so winner_lock
                        # gate uses current signal strength, not snapshot default.
                        _mw_pf_live_raw = float(
                            (scores.get(_mw_pf_sym) or {}).get("raw_net_score", 0.0) or 0.0
                        )
                        _mw_pf_snap = _build_position_health_snapshot(
                            _mw_pf_sym,
                            portfolio_emulator=portfolio_emulator,
                            prices=prices,
                            price_history=data if isinstance(data, dict) else None,
                            strategy_cache=strategy_cache,
                            date_key=date_key,
                            raw_score=_mw_pf_live_raw,
                        )
                        _mw_pf_wlock, _ = _rotation_winner_lock_active(
                            held_pnl_pct=float(_mw_pf_snap.get("unrealized_pct", 0.0) or 0.0),
                            held_days=_mw_pf_snap.get("held_days"),
                            held_raw_score=_mw_pf_live_raw,
                            drop_from_peak_pct=_mw_pf_snap.get("drop_from_peak_pct"),
                            is_equity=bool(_mw_pf_snap.get("is_equity", True)),
                            config=config,
                        )
                        # V31.2 Fix 2 (bug-sweep correction): use momentum watchlist
                        # score only. Don't fall back to raw_net_score — different
                        # scale (graph propagation vs multi-timeframe momentum %).
                        # A non-momentum held gets held_score=0, making it eligible
                        # for swap ONLY if winner_lock gate fails (below) — which
                        # it shouldn't for real compounders.
                        _mw_pf_held_score = float(
                            (strategy_cache.get("_momentum_held") or {}).get(_mw_pf_sym, {}).get("current_score", 0.0) or 0.0
                        )
                        _mw_pf_pnl[_mw_pf_sym] = {
                            "unrealized_pct": _mw_pf_snap.get("unrealized_pct", 0.0),
                            "held_days": _mw_pf_snap.get("held_days") or 0,
                            "winner_locked": _mw_pf_wlock,
                            "held_score": _mw_pf_held_score,
                            "drop_from_peak_pct": float(_mw_pf_snap.get("drop_from_peak_pct", 0.0) or 0.0),
                        }
                    # V31.7 Fix G: diagnostic log of weakest-pick candidates.
                    # TTD Mar 18 exit came through here (weakest pnl=+0.3% sold to buy
                    # NUVL/ZTO). This log exposes which positions are vulnerable so future
                    # iterations can target unexpected swaps with evidence.
                    if bool(config.get("v317_portfolio_swap_diagnostic_enabled", False)) and _mw_pf_pnl:
                        try:
                            _v317_cands = sorted(
                                [
                                    (
                                        _v317_s,
                                        float(_v317_i.get("unrealized_pct", 0.0) or 0.0),
                                        int(_v317_i.get("held_days", 0) or 0),
                                        bool(_v317_i.get("winner_locked", False)),
                                        float(_v317_i.get("held_score", 0.0) or 0.0),
                                        float(_v317_i.get("drop_from_peak_pct", 0.0) or 0.0),
                                    )
                                    for _v317_s, _v317_i in _mw_pf_pnl.items()
                                ],
                                key=lambda t: t[1],
                            )
                            _v317_preview = ", ".join(
                                f"{_v317_x[0]}(pnl={_v317_x[1]:+.1f}%,d={_v317_x[2]},wl={_v317_x[3]},hs={_v317_x[4]:.2f},pd={_v317_x[5]:.1f}%)"
                                for _v317_x in _v317_cands[:5]
                            )
                            _log(f"V31.7 portfolio_swap weakest candidates: {_v317_preview}", "cyan")
                        except Exception as _v317_diag_exc:
                            _log(f"V31.7 portfolio_swap diag error: {_v317_diag_exc}", "yellow")
                    _mw_pf_sell, _mw_pf_buy, _mw_pf_score, _mw_pf_sell_pnl = _rotate_momentum_vs_portfolio_weakest(
                        _mw_ranked_for_rot, _mw_pf_pnl, config, _mw_open_set,
                        recent_sell_cooldown=_mw_rot_cooldown_set,
                    )
                    # V31.1 bug-sweep fix: skip if buy ticker already sized this
                    # bar via another path (breakout_boost, propagation, BFQ).
                    if _mw_pf_sell and _mw_pf_buy and _mw_pf_buy not in nexus_position_sizes:
                        # 2026-07-19 regime-safety Phase 3: lane regime gate.
                        _mw_pf_lane_ok, _mw_pf_lane_why = _rotation_lane_allowed(
                            strategy_cache, portfolio_emulator, config)
                        if not _mw_pf_lane_ok:
                            _log(f"ROTATION lane blocked ({_mw_pf_lane_why}): "
                                 f"mw_swap {_mw_pf_sell}->{_mw_pf_buy} skipped", "yellow")
                            _mw_pf_sell, _mw_pf_buy = None, None
                    if _mw_pf_sell and _mw_pf_buy and _mw_pf_buy not in nexus_position_sizes:
                        # V32 Phase 3 B-1: blacklist check (same fix as mw_buy/mw_rotation).
                        _fl_bl_mws = _normalize_cache_mapping(strategy_cache, "_fast_loser_blacklist") if strategy_cache else {}
                        if _mw_pf_buy in _fl_bl_mws:
                            _bl_rem_s = (_fl_bl_mws.get(_mw_pf_buy) or {}).get("bars_remaining", 0)
                            _log(f"V32 P3 B-1 mw_swap blacklist-block: {_mw_pf_buy} ({_bl_rem_s} bars remaining)", "yellow")
                            _mw_pf_sell, _mw_pf_buy = None, None
                    if _mw_pf_sell and _mw_pf_buy and _mw_pf_buy not in nexus_position_sizes:
                        # V32 T1-c + T2-a: momentum_watchlist_portfolio_swap lane gate on BUY.
                        _mw_pf_buy_price_for_gate = _resolve_symbol_price(
                            _mw_pf_buy, prices, data, portfolio_emulator=portfolio_emulator,
                        )
                        _mw_pf_gate_blocked, _ = _v32_momentum_ath_or_mcap_block(
                            _mw_pf_buy, _mw_pf_buy_price_for_gate, data, strategy_cache,
                            config, float(_mw_pf_score or 0.0), log_fn=_log, lane="mw_swap",
                            date_key=date_key,
                        )
                        if _mw_pf_gate_blocked:
                            _mw_pf_sell, _mw_pf_buy = None, None
                    if _mw_pf_sell and _mw_pf_buy and _mw_pf_buy not in nexus_position_sizes:
                        # Run-185254 leak #1: pre-validate the incoming BUY
                        # before the sell leg commits (see mw_rotation lane).
                        _mw_pf_rot_ok, _mw_pf_rot_block = _rotation_incoming_executable(
                            _mw_pf_buy, _mw_pf_buy_price_for_gate, config,
                            asset_class=str((scores.get(_mw_pf_buy) or {}).get("asset_class") or "stock"),
                        )
                        if not _mw_pf_rot_ok:
                            _log(
                                f"ROTATION PREVALIDATE: skip incoming {_mw_pf_buy} "
                                f"({_mw_pf_rot_block}) — swap skipped, keeping {_mw_pf_sell}",
                                "yellow",
                            )
                            _mw_pf_sell, _mw_pf_buy = None, None
                    if _mw_pf_sell and _mw_pf_buy and _mw_pf_buy not in nexus_position_sizes:
                        _mw_pf_sell_price = _resolve_symbol_price(
                            _mw_pf_sell, prices, data, portfolio_emulator=portfolio_emulator,
                        )
                        _mw_pf_sell_qty = float(
                            (getattr(portfolio_emulator, "_positions", {}) or {}).get(_mw_pf_sell, 0)
                        )
                        _mw_pf_freed = max(0.0, _mw_pf_sell_price * _mw_pf_sell_qty) if _mw_pf_sell_price > 0 else 0.0
                        _mw_pf_min_pos = float(config.get("min_position_size", 100.0) or 100.0)
                        _mw_pf_floor_pct = float(config.get("momentum_position_size_floor_pct", 0.10) or 0.10)
                        _mw_pf_floor = portfolio_total * _mw_pf_floor_pct if portfolio_total > 0 else 0.0
                        _mw_pf_free_cash = 0.0
                        if hasattr(portfolio_emulator, "get_cash"):
                            try:
                                _mw_pf_free_cash = float(portfolio_emulator.get_cash() or 0.0)
                            except Exception as _mw_pf_fc_exc:
                                _mw_pf_free_cash = 0.0
                                _log(f"V31.2 WARN: get_cash() failed in portfolio_swap: {_mw_pf_fc_exc}", "yellow")
                        # V31.2 bug-sweep: subtract free cash already reserved by
                        # Fix 5 / breakout_add this bar to prevent double-spend.
                        _mw_pf_fc_spent = float((strategy_cache or {}).get("_mw_free_cash_spent_this_bar", 0.0) or 0.0)
                        _mw_pf_free_cash_avail = max(0.0, _mw_pf_free_cash - _mw_pf_fc_spent)
                        # Enforce floor via free-cash top-up (Fix A sizing).
                        _mw_pf_extra_needed = max(0.0, _mw_pf_floor - _mw_pf_freed)
                        _mw_pf_extra = min(_mw_pf_extra_needed, _mw_pf_free_cash_avail * 0.95)
                        _mw_pf_alloc = max(_mw_pf_min_pos, _mw_pf_freed + _mw_pf_extra)
                        # Track A (run-163943): sector-cap pre-validation (see mw_rotation lane).
                        _mw_pf_sc_ok, _mw_pf_sc_block = _rotation_incoming_sector_cap_ok(
                            _mw_pf_buy, _mw_pf_alloc, portfolio_emulator, portfolio_total,
                            config, prices, data, selling_sym=_mw_pf_sell,
                        )
                        if not _mw_pf_sc_ok:
                            _log(
                                f"ROTATION PREVALIDATE sector-cap: skip incoming {_mw_pf_buy} "
                                f"({_mw_pf_sc_block}) — swap skipped, keeping {_mw_pf_sell}",
                                "yellow",
                            )
                        if _mw_pf_alloc >= _mw_pf_min_pos and _mw_pf_sc_ok:
                            nexus_sell_enforcement.add(_mw_pf_sell)
                            if isinstance(strategy_cache, dict):
                                strategy_cache.setdefault("_mw_rotation_sells_this_bar", set()).add(_mw_pf_sell)
                            sentiment_data[_mw_pf_sell] = {"sentiment": -1, "event": "general"}
                            # V31.1 bug-sweep fix: if sold ticker is in _mw_held,
                            # remove it to prevent double-bookkeeping.
                            if _mw_pf_sell in _mw_held:
                                del _mw_held[_mw_pf_sell]
                            # η.E — Phase η (2026-05-20): floor + natural-signal differentiator.
                            _eta_e_pf_floored = max(_mw_pf_score, 1.50)
                            if config.get("eta_floor_differentiator_enabled", True):
                                _eta_e_pf_diff = min(0.20, max(0.0, float(_mw_pf_score)) * 0.5)
                                _eta_e_pf_raw_net = _eta_e_pf_floored + _eta_e_pf_diff
                            else:
                                _eta_e_pf_raw_net = _eta_e_pf_floored
                            nexus_position_sizes[_mw_pf_buy] = {
                                "buy_cash": round(_mw_pf_alloc, 2),
                                "high_conviction": True,
                                "asset_class": "stock",
                                "raw_net_score": round(_eta_e_pf_raw_net, 4),
                                "raw_net_natural": float(_mw_pf_score),
                                "signal_source": "momentum_watchlist_portfolio_swap",
                                "is_propagation_expansion": False,
                                "is_watchlist_member": True,
                                "is_watchlist_priority": True,
                                "grace_eligible": True,
                            }
                            if _mw_pf_buy not in scores:
                                scores[_mw_pf_buy] = {}
                            scores[_mw_pf_buy]["score"] = 1
                            scores[_mw_pf_buy]["raw_net_score"] = _eta_e_pf_raw_net
                            scores[_mw_pf_buy]["raw_net_natural"] = float(_mw_pf_score)
                            scores[_mw_pf_buy]["action_intent"] = "momentum_watchlist_portfolio_swap"
                            _mw_pf_cooldown_bars = _scale_bars(int(config.get("momentum_sell_cooldown_bars", 5) or 5), config)
                            if _mw_pf_cooldown_bars > 0 and isinstance(strategy_cache, dict):
                                strategy_cache.setdefault("_momentum_sell_cooldown", {})[_mw_pf_sell] = _mw_pf_cooldown_bars
                            _mw_held[_mw_pf_buy] = {
                                "bar_entered": _mw_bar,
                                "entry_score": _mw_pf_score,
                                "current_score": _mw_pf_score,
                            }
                            # V31.1 Codex-fix: register sized ticker so downstream
                            # BFQ paths (direct_reserved, dequeue) don't overwrite.
                            # V31.2 bug-sweep: track free cash consumed by this swap.
                            if isinstance(strategy_cache, dict):
                                strategy_cache.setdefault("_mw_sized_this_bar", set()).add(_mw_pf_buy)
                                strategy_cache["_mw_free_cash_spent_this_bar"] = (
                                    float(strategy_cache.get("_mw_free_cash_spent_this_bar", 0.0) or 0.0)
                                    + _mw_pf_extra
                                )
                            _log(
                                f"Momentum portfolio swap: sell {_mw_pf_sell} (pnl={_mw_pf_sell_pnl:+.1f}%) "
                                f"→ buy {_mw_pf_buy} (score={_mw_pf_score:.3f}, ${_mw_pf_alloc:.0f})",
                                "magenta",
                            )
                except Exception as _mw_pf_exc:
                    _log(f"Momentum portfolio swap error: {_mw_pf_exc}", "yellow")

            # ── V31.1 Fix B: Momentum breakout add (from free cash) ───────
            # When a top momentum ticker isn't held AND we have an open slot
            # AND free cash, allocate from free cash at the floor (~10% of
            # portfolio). Catches SNDK/LITE-class breakouts post-rediscovery.
            if (
                config.get("momentum_breakout_add_enabled", True)
                and portfolio_emulator is not None
                and _mw_ranked_for_rot
            ):
                try:
                    _mw_ba_min_score = float(config.get("momentum_breakout_min_score", 1.0) or 1.0)
                    _mw_ba_pos_pct = float(config.get("momentum_breakout_position_pct", 0.12) or 0.12)
                    _mw_ba_min_free = float(config.get("momentum_breakout_min_free_cash", 200.0) or 200.0)
                    _mw_ba_min_pos = float(config.get("min_position_size", 100.0) or 100.0)
                    _mw_ba_max_per_bar = int(config.get("momentum_breakout_max_per_bar", 1) or 1)
                    # BT136708 bug-sweep 2026-05-18: fallback default 8 conflicted with the
                    # main path's max_positions default of 15 (line 21121). Normalise to 15
                    # so a missing config key doesn't silently throttle the momentum-watchlist
                    # breakout-add path below the global cap.
                    _mw_ba_max_positions = int(config.get("max_positions", 15) or 15)
                    # 2026-07-25 (default OFF): use the REGIME cap, not the raw
                    # global one. bt#500437 logged `Buy gate inputs for FTH:
                    # ... open_pos=11 ... -> PASS` against a cap of 8 -- this
                    # lane counted against max_positions while every other lane
                    # was capped by regime, so it opened positions the book was
                    # not allowed to hold. Same defect class as the backfill
                    # queue's headroom (see _bfq_regime_headroom).
                    if bool(config.get("momentum_breakout_add_respect_gates", False)):
                        # _capacity_regime so the bear-capacity latch binds this
                        # lane too (2026-07-26) -- see the BFQ headroom call.
                        _mw_ba_max_positions = min(_mw_ba_max_positions, _apply_recovery_cap(
                            _regime_position_cap(config, _capacity_regime(
                                (strategy_cache or {}).get("_market_regime"),
                                (strategy_cache or {}).get("_bear_capacity_latch"))),
                            (strategy_cache or {}).get("_market_regime_recovery"), config))
                    _mw_ba_buy_price_floor = float(config.get("buy_price_floor", 8.0) or 8.0)
                    _mw_ba_current_positions = len(_mw_open_set)
                    # V31.1 bug-sweep fix: count only NEW-entry buys (tickers not
                    # already in _mw_open_set), so winner_adds don't inflate count.
                    _mw_ba_buying_this_bar = sum(
                        1 for _s, _h in nexus_position_sizes.items()
                        if isinstance(_h, dict) and float(_h.get("buy_cash", 0) or 0) > 0
                        and str(_s).strip().upper() not in _mw_open_set
                    )
                    _mw_ba_free_cash = 0.0
                    if hasattr(portfolio_emulator, "get_cash"):
                        try:
                            _mw_ba_free_cash = float(portfolio_emulator.get_cash() or 0.0)
                        except Exception as _mw_ba_fc_exc:
                            _mw_ba_free_cash = 0.0
                            _log(f"V31.2 WARN: get_cash() failed in breakout_add: {_mw_ba_fc_exc}", "yellow")
                    # V31.2 bug-sweep: subtract cash already reserved by Fix 5
                    # Site A/B this bar to prevent double-spend of same free cash.
                    _mw_ba_fc_spent = float((strategy_cache or {}).get("_mw_free_cash_spent_this_bar", 0.0) or 0.0)
                    _mw_ba_free_cash = max(0.0, _mw_ba_free_cash - _mw_ba_fc_spent)
                    _mw_ba_fires = 0
                    for _mw_ba_sym, _mw_ba_score in _mw_ranked_for_rot:
                        if _mw_ba_fires >= _mw_ba_max_per_bar:
                            break
                        if _mw_ba_score < _mw_ba_min_score:
                            break
                        if _mw_ba_current_positions + _mw_ba_buying_this_bar >= _mw_ba_max_positions:
                            break
                        if _mw_ba_free_cash < _mw_ba_min_free:
                            break
                        _mw_ba_sym_u = str(_mw_ba_sym).strip().upper()
                        if _mw_ba_sym_u in _mw_open_set:
                            continue
                        if _mw_ba_sym_u in _mw_rot_cooldown_set:
                            continue
                        if _mw_ba_sym_u in nexus_position_sizes:
                            continue  # already sized via another path this bar
                        # V31.1 bug-sweep fix: skip tickers being force-sold
                        if _mw_ba_sym_u in (nexus_sell_enforcement or set()):
                            continue
                        # ── 2026-07-25 (default OFF): honour the gates that the
                        # SIBLING lanes apply. Forensics on bt#500437: this lane
                        # fired 5 times for $3,513 and produced 0 winners
                        # (-$376.97 = 45% of every loss in the run; 7/7 losers
                        # counting bt#211684). EVERY fill was on a bar where
                        # mw_buy/mw_swap had already REFUSED the same ticker --
                        # "mw_buy extension-block: ALM runup +82.4% > 25%" then
                        # "Momentum breakout add: buy ALM ($720 from free cash)";
                        # "mw_buy blacklist-block: FTH (5 bars remaining)" then
                        # "Momentum breakout add: buy FTH ($702)". It is a
                        # consistency hole, not a strategy: the same bar cannot
                        # both refuse and buy a ticker.
                        if bool(config.get("momentum_breakout_add_respect_gates", False)):
                            _mw_ba_bl = (_normalize_cache_mapping(strategy_cache, "_fast_loser_blacklist")
                                         if strategy_cache else {})
                            if _mw_ba_sym_u in _mw_ba_bl:
                                _mw_ba_rem = (_mw_ba_bl.get(_mw_ba_sym_u) or {}).get("bars_remaining", 0)
                                _log(f"Momentum breakout add blacklist-block: {_mw_ba_sym_u} "
                                     f"({_mw_ba_rem} bars remaining)", "yellow")
                                continue
                            _mw_ba_gate_px = _resolve_symbol_price(
                                _mw_ba_sym_u, prices, data, portfolio_emulator=portfolio_emulator)
                            _mw_ba_gate_blocked, _mw_ba_gate_why = _v32_momentum_ath_or_mcap_block(
                                _mw_ba_sym_u, _mw_ba_gate_px, data, strategy_cache, config,
                                float(_mw_ba_score or 0.0), log_fn=_log, lane="mw_breakout_add",
                                date_key=date_key,
                            )
                            if _mw_ba_gate_blocked:
                                continue
                        # V31.1 bug-sweep fix: skip tickers below price floor
                        _mw_ba_price = _resolve_symbol_price(
                            _mw_ba_sym_u, prices, data, portfolio_emulator=portfolio_emulator,
                        )
                        if _mw_ba_price > 0 and _mw_ba_price < _mw_ba_buy_price_floor:
                            continue
                        _mw_ba_target = portfolio_total * _mw_ba_pos_pct if portfolio_total > 0 else 0.0
                        _mw_ba_alloc = min(_mw_ba_free_cash * 0.95, max(_mw_ba_min_pos, _mw_ba_target))
                        # 2026-07-25 (default 0 = OFF): hard NAV ceiling. This
                        # lane self-sizes at momentum_breakout_position_pct (0.12)
                        # of NAV "from free cash" and ignores the normal slate
                        # sizing, so it produced the single largest position in
                        # the bear book (ALM $720 = 12.0% of NAV, vs the +6.88%
                        # reference's largest at 6.9%). Count-based limits cannot
                        # fix this -- they trim the tail of the size distribution,
                        # never the head; only a dollar limiter binds.
                        # A2 (2026-07-28): resolved from THIS cycle's regime, not
                        # the previous cycle's profile overlay.
                        _mw_ba_nav_cap = _resolve_momentum_breakout_nav_cap(
                            config, strategy_cache)
                        if _mw_ba_nav_cap > 0 and portfolio_total > 0:
                            _mw_ba_alloc = min(_mw_ba_alloc, portfolio_total * _mw_ba_nav_cap)
                        if _mw_ba_alloc < _mw_ba_min_pos:
                            continue
                        # η.E — Phase η (2026-05-20): floor + natural-signal differentiator.
                        _eta_e_ba_floored = max(_mw_ba_score, 1.50)
                        if config.get("eta_floor_differentiator_enabled", True):
                            _eta_e_ba_diff = min(0.20, max(0.0, float(_mw_ba_score)) * 0.5)
                            _eta_e_ba_raw_net = _eta_e_ba_floored + _eta_e_ba_diff
                        else:
                            _eta_e_ba_raw_net = _eta_e_ba_floored
                        nexus_position_sizes[_mw_ba_sym_u] = {
                            "buy_cash": round(_mw_ba_alloc, 2),
                            "high_conviction": True,
                            "asset_class": "stock",
                            "raw_net_score": round(_eta_e_ba_raw_net, 4),
                            "raw_net_natural": float(_mw_ba_score),
                            "signal_source": "momentum_breakout_add",
                            "is_propagation_expansion": False,
                            "is_watchlist_member": True,
                            "is_watchlist_priority": True,
                            "grace_eligible": True,
                        }
                        if _mw_ba_sym_u not in scores:
                            scores[_mw_ba_sym_u] = {}
                        scores[_mw_ba_sym_u]["score"] = 1
                        scores[_mw_ba_sym_u]["raw_net_score"] = _eta_e_ba_raw_net
                        scores[_mw_ba_sym_u]["raw_net_natural"] = float(_mw_ba_score)
                        scores[_mw_ba_sym_u]["action_intent"] = "momentum_breakout_add"
                        _mw_held[_mw_ba_sym_u] = {
                            "bar_entered": _mw_bar,
                            "entry_score": _mw_ba_score,
                            "current_score": _mw_ba_score,
                        }
                        if isinstance(strategy_cache, dict):
                            strategy_cache.setdefault("_mw_sized_this_bar", set()).add(_mw_ba_sym_u)
                            # V31.2 bug-sweep: track free cash consumed by Fix B
                            strategy_cache["_mw_free_cash_spent_this_bar"] = (
                                float(strategy_cache.get("_mw_free_cash_spent_this_bar", 0.0) or 0.0)
                                + _mw_ba_alloc
                            )
                        _mw_ba_free_cash = max(0.0, _mw_ba_free_cash - _mw_ba_alloc)
                        _mw_ba_buying_this_bar += 1
                        _mw_ba_fires += 1
                        _log(
                            f"Momentum breakout add: buy {_mw_ba_sym_u} "
                            f"(score={_mw_ba_score:.3f}, ${_mw_ba_alloc:.0f} from free cash)",
                            "magenta",
                        )
                except Exception as _mw_ba_exc:
                    _log(f"Momentum breakout add error: {_mw_ba_exc}", "yellow")

        # V6: Add forced-exit symbols (fast loser, trailing stop, hold-limit) to sell enforcement
        # so they cannot be overridden by broker aggregation, circuit breaker, or post-decision strategies.
        # Forced exits OVERRIDE momentum watchlist protection — a trailing stop or fast loser
        # must fire even for momentum-held positions.
        # Tier-3 A4 (2026-05-17): also write status="post_sell_watch" so the
        # daily re-entry eligibility check can monitor recovery.
        #   Live mode + DB available → write to GraphNexusDiscoveredStocks.
        #   Backtest mode             → mirror to strategy_cache in-memory
        #                               storage (BT136708 P1.7, 2026-05-18) so
        #                               re-entry pipeline can exercise without
        #                               polluting the shared live DB.
        #   Historical-lookback pre-pass → neither (suppressed entirely).
        _psw_master = bool(config.get("post_sell_watch_enabled", True))
        _psw_in_lookback = bool(config.get("historical_lookback_mode", False))
        _psw_live = bool(globals().get("_GN_LIVE_MODE_FLAG", False))
        _psw_db_write = _psw_master and _psw_live and not _psw_in_lookback
        _psw_inmem_write = _psw_master and not _psw_live and not _psw_in_lookback
        for _fe_sym, _fe_data in scores.items():
            if isinstance(_fe_data, dict) and _fe_data.get("_forced_exit") and _fe_data.get("score") == -1:
                if _fe_sym not in (nexus_sell_enforcement or set()):
                    nexus_sell_enforcement.add(_fe_sym)
                    _log(f"Sell enforcement ADD: {_fe_sym} forced_exit=True, reason={str(_fe_data.get('reason', '?'))[:60]}", "red")
                # Apply sell_fraction now — the main enforcement loop already ran,
                # so forced exits added here need explicit application.
                entry = nexus_position_sizes.get(_fe_sym, {})
                entry["sell_fraction"] = 1.0
                nexus_position_sizes[_fe_sym] = entry
                # Tier-3 A4: record post_sell_watch row for daily eligibility scan.
                if _psw_db_write or _psw_inmem_write:
                    try:
                        _psw_exit_price = _resolve_symbol_price(
                            _fe_sym, prices, data, portfolio_emulator=portfolio_emulator,
                        )
                        _psw_tier = _resolve_conviction_tier_at_exit(
                            _fe_sym, config, strategy_cache, propagated,
                        )
                        _psw_reason = str(_fe_data.get("reason", "forced_exit"))[:200]
                        _psw_exit_price_f = float(_psw_exit_price or 0.0)
                        if _psw_db_write and conn_trends is not None:
                            _mark_discovered_stock_sold(
                                conn_trends,
                                instance_id,
                                _fe_sym,
                                reason=_psw_reason,
                                date_key=date_key,
                                forced_exit=True,
                                exit_price=_psw_exit_price_f,
                                entry_conviction_tier=_psw_tier,
                            )
                        if _psw_inmem_write:
                            _post_sell_watch_inmem_write(
                                strategy_cache,
                                _fe_sym,
                                exit_price=_psw_exit_price_f,
                                entry_conviction_tier=_psw_tier,
                                sell_reason=_psw_reason,
                                date_key=date_key,
                            )
                    except Exception as _psw_exc:
                        _log(f"post_sell_watch write error: {_fe_sym}: {_psw_exc}", "yellow")

        # ── Two-phase rediscovery confirmation ──────────────────────
        # Rediscovered tickers were set to 'rediscovery_pending'. Now that
        # scoring is complete, confirm (active) or roll back (sold).
        if _rediscovery_pending_tickers and conn_trends:
            for _rpd_ticker in _rediscovery_pending_tickers:
                _rpd_score = scores.get(_rpd_ticker, {})
                _rpd_final = int(_rpd_score.get("score", 0) if isinstance(_rpd_score, dict) else 0)
                _rpd_doc_id = f"{instance_id}_{_rpd_ticker}"
                try:
                    if _rpd_final >= 1:
                        _r.db(DB_NAME).table(DISCOVERED_TABLE).get(_rpd_doc_id).update({"status": "active"}).run(conn_trends)
                        _log(f"Rediscovery confirmed: {_rpd_ticker} (score={_rpd_final})", "green")
                    else:
                        _r.db(DB_NAME).table(DISCOVERED_TABLE).get(_rpd_doc_id).update({"status": "sold"}).run(conn_trends)
                        _log(f"Rediscovery rolled back: {_rpd_ticker} (score={_rpd_final}, LLM rejected)", "yellow")
                except Exception:
                    pass

        # ============================================================
        # V7: BACKFILL QUEUE — deferred buy processing
        # ============================================================
        _bfq = list(_bfq_pending)
        _queue_admission_failures: dict[str, str] = {}
        if _bfq_enabled:
            _bfq_candidate_syms = list(_queue_stock_buys) if '_queue_stock_buys' in locals() else (list(stock_buys) if 'stock_buys' in locals() else [])
            _log(
                f"Backfill queue: enabled | stock_buys={len(_bfq_candidate_syms)} | "
                f"queue_size={len(_bfq_pending)} | halt={'YES' if _drawdown_halt_active else 'NO'}",
                "cyan",
            )

            # --- ENQUEUE: Add blocked buy candidates to queue ---
            _bfq_already_queued = {q["ticker"] for q in _bfq}
            _bfq_already_held = {t for t, q in (portfolio_emulator._positions or {}).items() if float(q or 0) > 0} if portfolio_emulator else set()
            # V7.5: Only count stocks as "bought" if there's enough cash to actually execute them all.
            # Position sizing allocates buy_cash based on portfolio_total (not available cash),
            # so ALL stock_buys get entries even when there's not enough liquid cash for all.
            # Compare available cash against total planned buy spend to identify which buys
            # will actually execute vs which will be SKIP BUY'd by the broker.
            _bfq_spendable_cash = max(0.0, float(_available_buy_budget or 0.0))
            _bfq_planned_spend = sum(v.get("buy_cash", 0) for v in nexus_position_sizes.values() if isinstance(v, dict) and "buy_cash" in v)
            if _bfq_planned_spend > _bfq_spendable_cash * 1.01:
                # More buys planned than cash available — many will be SKIP BUY'd
                # Don't mark any as "bought" so they can enter the backfill queue
                _bfq_bought_this_bar = set()
                _log(f"Backfill queue: cash shortfall detected (planned=${_bfq_planned_spend:.0f} vs avail=${_bfq_spendable_cash:.0f}) — enqueue enabled", "cyan")
            else:
                _bfq_bought_this_bar = {k for k, v in nexus_position_sizes.items() if isinstance(v, dict) and "buy_cash" in v}
            # V28 dedup fix: mark rotation-pair buy targets as "already bought
            # this bar" so the BFQ drain doesn't try to double-buy a ticker that
            # was just funded via rotation.
            # V28.9-B (Codex 3B BLOCK fix): ONLY mark as bought when the slate
            # planner actually funded the buy. Previously ALL _rotation_pairs
            # buys were unconditionally marked, blocking BFQ same-bar rescue
            # for buys dropped by the slate planner (deferred_unfunded_buy).
            # That bug was the real SNDK starvation path: gate conversion
            # could emit a full-exit pair, slate planner could drop the buy
            # due to slot_cap/budget, and BFQ couldn't rescue it because the
            # buy was falsely marked "already bought". Now unfunded rotation
            # buys remain eligible for BFQ drain rescue.
            try:
                for _rp_pair in (_rotation_pairs if "_rotation_pairs" in dir() else []):
                    _rp_buy = str((_rp_pair or {}).get("buy") or "").strip().upper()
                    if _rp_buy and _rp_buy in nexus_position_sizes:
                        _bfq_bought_this_bar.add(_rp_buy)
            except Exception:
                pass
            # V7.1: Use full stock_buys list (all buy signals) not just truncated pool stocks
            _bfq_all_candidates = list(_bfq_candidate_syms)
            _bfq_all_candidates.sort(
                key=lambda _sym: (
                    0 if bool((scores.get(_sym) or {}).get("is_watchlist_priority")) else
                    1 if bool((scores.get(_sym) or {}).get("is_propagation_expansion")) else
                    2 if str((scores.get(_sym) or {}).get("signal_source") or "").strip().lower() == "direct" else 3,
                    -float((scores.get(_sym) or {}).get("raw_net_score", 0.0) or 0.0),
                    -int((scores.get(_sym) or {}).get("n_paths", 0) or 0),
                    str(_sym or ""),
                )
            )
            _fl_blacklist_enq = (strategy_cache or {}).get("_fast_loser_blacklist", {})
            for _bfq_sym in _bfq_all_candidates:
                if (_bfq_sym not in _bfq_bought_this_bar
                    and _bfq_sym not in _bfq_already_held
                    and _bfq_sym not in _fl_blacklist_enq):
                    _bfq_score = float((scores.get(_bfq_sym) or {}).get("raw_net_score", 0.0) or 0.0)
                    if _bfq_score >= _bfq_min_score:
                        _bfq_meta = _build_nexus_candidate_meta(
                            _bfq_sym,
                            scores.get(_bfq_sym),
                            config,
                            strategy_cache=strategy_cache,
                            is_propagation_expansion=_bfq_sym in set(_prop_expansion_buys or []),
                            is_watchlist_member=_bfq_sym in _watchlist_member_tickers,
                            is_watchlist_priority=_bfq_sym in _watchlist_priority_tickers,
                        )
                        _bfq_source = _bfq_meta["signal_source"]
                        _bfq_price = _resolve_symbol_price(_bfq_sym, prices, data, portfolio_emulator=portfolio_emulator)
                        _bfq_priority = _queue_priority_rank(_bfq_meta)
                        _bfq_status, _bfq_replaced = _enqueue_backfill_candidate(_bfq, {
                            "ticker": _bfq_sym,
                            "first_signal_date": date_key,
                            "raw_net_score": round(_bfq_score, 4),
                            "n_paths": int((scores.get(_bfq_sym) or {}).get("n_paths", 0) or 0),
                            "signal_source": _bfq_source,
                            "is_watchlist_member": bool(_bfq_meta["is_watchlist_member"]),
                            "is_watchlist_priority": bool(_bfq_meta["is_watchlist_priority"]),
                            "is_propagation_expansion": bool(_bfq_meta["is_propagation_expansion"]),
                            "grace_eligible": bool(_bfq_meta["grace_eligible"]),
                            "price_at_signal": round(_bfq_price, 2) if _bfq_price > 0 else None,
                            "needs_price_backfill": _bfq_price <= 0,
                            "queued_price_source": "strategy" if _bfq_price > 0 else "broker",
                            "queued_from_bar": date_key,
                            "bars_in_queue": 0,
                        }, _bfq_max_size, reserved_priority_slots=_bfq_reserved_priority_slots, min_displacement_delta=_bfq_min_displace_delta, recurrence_bonus=_bfq_recurrence_bonus)
                        if _bfq_status == "added":
                            _price_msg = f", price=${_bfq_price:.2f}" if _bfq_price > 0 else ", price=pending"
                            _log(f"Backfill queue ADD: {_bfq_sym} (score={_bfq_score:.3f}{_price_msg}, source={_bfq_source})", "magenta")
                        elif _bfq_status == "updated":
                            _bfq_entry = next((q for q in _bfq if str(q.get("ticker","")).upper() == _bfq_sym), None)
                            _bfq_rc = int((_bfq_entry or {}).get("_recurrence_count", 0))
                            _rc_msg = f", recurrence={_bfq_rc}" if _bfq_rc > 0 else ""
                            _log(f"Backfill queue REFRESH: {_bfq_sym} (score={float((_bfq_entry or {}).get('raw_net_score', _bfq_score)):.3f}{_rc_msg}, source={_bfq_source})", "magenta")
                        elif _bfq_status == "replaced":
                            _log(f"Backfill queue REPLACE: {_bfq_sym} displaced {_bfq_replaced} (score={_bfq_score:.3f}, source={_bfq_source})", "magenta")
                        elif _bfq_status == "priority_evicted_general":
                            _log(f"Backfill queue PRIORITY_EVICT: {_bfq_sym} displaced {_bfq_replaced} (score={_bfq_score:.3f}, source={_bfq_source})", "magenta")
                        elif _bfq_status in {"full_priority_blocked", "full_general_blocked", "invalid"}:
                            _queue_admission_failures[_bfq_sym] = _bfq_status
                            _log(f"Backfill queue BLOCKED: {_bfq_sym} ({_bfq_status}, score={_bfq_score:.3f}, source={_bfq_source})", "yellow")

            # V7.1: Enqueue broker-skipped buys from PREVIOUS bar
            # Sort by score descending so highest-conviction skipped buys fill queue first (Issue 1 fix)
            _broker_skipped = sorted(
                _bsk_pending,
                key=lambda x: (
                    0 if bool(x.get("is_watchlist_priority")) else
                    1 if bool(x.get("is_propagation_expansion")) else
                    2 if str(x.get("signal_source") or "").strip().lower() == "direct" else 3,
                    -float((scores.get(x.get("ticker", "")) or {}).get("raw_net_score", 0.0) or 0.0),
                    -int((scores.get(x.get("ticker", "")) or {}).get("n_paths", 0) or 0),
                    str(x.get("ticker") or ""),
                ),
            )
            # Rebuild queued set to prevent duplicates from candidate loop (Issue 5/11 fix)
            _bfq_already_queued = {q["ticker"] for q in _bfq}
            _fl_blacklist_bsk = (strategy_cache or {}).get("_fast_loser_blacklist", {})
            for _bsk in _broker_skipped:
                _bsk_sym = _bsk.get("ticker", "")
                if (_bsk_sym
                    and _bsk_sym not in _bfq_already_held
                    and _bsk_sym not in _fl_blacklist_bsk):
                    _bsk_score = float((scores.get(_bsk_sym) or {}).get("raw_net_score", 0.0) or 0.0)
                    if _bsk_score >= _bfq_min_score:
                        _bsk_meta = _build_nexus_candidate_meta(
                            _bsk_sym,
                            scores.get(_bsk_sym),
                            config,
                            strategy_cache=strategy_cache,
                            signal_source=str(_bsk.get("signal_source") or "").strip().lower() or None,
                            is_propagation_expansion=bool(_bsk.get("is_propagation_expansion")),
                            is_watchlist_member=bool(_bsk.get("is_watchlist_member")) or bool(_bsk.get("is_watchlist_match")),
                            is_watchlist_priority=bool(_bsk.get("is_watchlist_priority")),
                            grace_eligible=True,
                        )
                        _bsk_source = _bsk_meta["signal_source"]
                        _bsk_price = _resolve_symbol_price(
                            _bsk_sym,
                            prices,
                            data,
                            portfolio_emulator=portfolio_emulator,
                            fallback_price=float(_bsk.get("price", 0.0) or 0.0),
                        )
                        _bsk_priority = _queue_priority_rank(_bsk_meta)
                        _bsk_status, _bsk_replaced = _enqueue_backfill_candidate(_bfq, {
                            "ticker": _bsk_sym,
                            "first_signal_date": date_key,
                            "raw_net_score": round(_bsk_score, 4),
                            "n_paths": int((scores.get(_bsk_sym) or {}).get("n_paths", 0) or 0),
                            "signal_source": _bsk_source,
                            "is_watchlist_member": bool(_bsk_meta["is_watchlist_member"]),
                            "is_watchlist_priority": bool(_bsk_meta["is_watchlist_priority"]),
                            "is_propagation_expansion": bool(_bsk_meta["is_propagation_expansion"]),
                            "grace_eligible": True,
                            "price_at_signal": round(_bsk_price, 2) if _bsk_price > 0 else None,
                            "needs_price_backfill": _bsk_price <= 0,
                            "queued_price_source": "broker",
                            "queued_from_bar": date_key,
                            "bars_in_queue": 0,
                            "broker_skip_reason": str(_bsk.get("reason") or ""),
                        }, _bfq_max_size, reserved_priority_slots=_bfq_reserved_priority_slots, min_displacement_delta=_bfq_min_displace_delta, recurrence_bonus=_bfq_recurrence_bonus)
                        if _bsk_status == "added":
                            _log(f"Backfill queue ADD (broker-skipped): {_bsk_sym} (score={_bsk_score:.3f}, priority={_bsk_priority}, allocated=${_bsk.get('allocated', 0):.0f})", "magenta")
                        elif _bsk_status == "updated":
                            _log(f"Backfill queue REFRESH (broker-skipped): {_bsk_sym} (score={_bsk_score:.3f}, priority={_bsk_priority})", "magenta")
                        elif _bsk_status == "replaced":
                            _log(f"Backfill queue REPLACE (broker-skipped): {_bsk_sym} displaced {_bsk_replaced} (score={_bsk_score:.3f}, priority={_bsk_priority})", "magenta")
                        elif _bsk_status == "priority_evicted_general":
                            _log(f"Backfill queue PRIORITY_EVICT (broker-skipped): {_bsk_sym} displaced {_bsk_replaced} (score={_bsk_score:.3f}, priority={_bsk_priority})", "magenta")
                        elif _bsk_status in {"full_priority_blocked", "full_general_blocked", "invalid"}:
                            _queue_admission_failures[_bsk_sym] = _bsk_status
                            _log(f"Backfill queue BLOCKED (broker-skipped): {_bsk_sym} ({_bsk_status}, priority={_bsk_priority})", "yellow")
            if strategy_cache is not None:
                strategy_cache["_broker_skipped_buys"] = []  # Clear after consuming

            # --- DEQUEUE: Process queued tickers if spendable cash/headroom are still available ---
            _planned_new_positions = sum(
                1
                for _sym, _hint in (nexus_position_sizes or {}).items()
                if isinstance(_hint, dict)
                and "buy_cash" in _hint
                and float((portfolio_emulator._positions or {}).get(_sym, 0.0) or 0.0) <= 0.0
            ) if portfolio_emulator else 0
            _bfq_leftover = max(0.0, _bfq_spendable_cash - _bfq_planned_spend)
            _bfq_reserve_from_budget = _reserved_backfill_budget if _bfq else 0.0
            _bfq_cash = max(0.0, _bfq_leftover + _bfq_reserve_from_budget)
            _bfq_positions = _count_open_positions(portfolio_emulator)
            # V28.7: unified max_positions default — main allocation was tightened from
            # 50 to 15, but BFQ path still used the old 50 default, so BFQ dequeue could
            # admit buys past the V28.7 cap. Match the default so a config without the
            # key produces consistent headroom across ALL buy paths.
            # 2026-07-25: derive headroom from the REGIME cap (default OFF keeps
            # the raw max_positions value byte-identically) — see
            # _bfq_regime_headroom. Without this the queue opened fresh longs in a
            # confirmed bear where every other lane was capped at 2.
            # 2026-07-26: route through _capacity_regime so the bear-capacity
            # latch binds this lane too. Without it the latch throttles only the
            # main slate and the queue happily refills the book on the same chop
            # bar -- the exact refill the latch exists to stop.
            _bfq_headroom = _bfq_regime_headroom(
                config,
                _capacity_regime((strategy_cache or {}).get("_market_regime"),
                                 (strategy_cache or {}).get("_bear_capacity_latch")),
                (strategy_cache or {}).get("_market_regime_recovery"),
                _bfq_positions,
                _planned_new_positions,
            )
            _bfq_min_pos = _min_position_size
            _bfq_processed = []
            _bfq_removed = []

            # V9 5D: Sort by score descending, high-conviction entries (score > 1.5) get priority
            _bfq.sort(key=_queue_sort_key)
            # V9: Check if drawdown halt allows partial backfill
            _bfq_halt_budget_pct = float((strategy_cache or {}).get("_bfq_halt_budget_pct", 0.0))
            if _drawdown_halt_active and _bfq_halt_budget_pct <= 0:
                _log("Backfill queue: dequeue paused while portfolio drawdown halt is active", "yellow")
            elif _drawdown_halt_active and _bfq_halt_budget_pct > 0:
                _bfq_cash = _bfq_cash * _bfq_halt_budget_pct
                _log(f"Backfill queue: drawdown halt active but backfill allowed at {_bfq_halt_budget_pct:.0%} budget (${_bfq_cash:.0f})", "yellow")

            # V20b: Reserved direct-item slot — guarantee at least 1 high-conviction
            # direct-source item gets funded per bar.
            # V28.8.1 (Codex-corrected): direct-reserved IS a new-ticker path (it adds
            # a new ticker to the portfolio). Per Codex 2B review, new-ticker paths
            # MUST be blocked during breach. Only net-zero swaps (BFQ rotation, full-
            # exit main rotation) should fire during breach.
            _bfq_breach_block = bool((strategy_cache or {}).get("_v28_7_position_breach_active"))
            _bfq_direct_reserved = bool(config.get("backfill_direct_reserved_slot", True))
            if _bfq_direct_reserved and _bfq_headroom > 0 and not _drawdown_halt_active and not _bfq_breach_block:
                # V31.1 Codex-fix: skip tickers already sized by momentum paths
                _bfq_mw_sized = (strategy_cache or {}).get("_mw_sized_this_bar", set()) or set()
                _bfq_direct_candidates = [
                    q for q in _bfq
                    if q["ticker"] not in set(_bfq_processed + _bfq_removed)
                    and str(q.get("signal_source") or "").strip().lower() == "direct"
                    and float(q.get("raw_net_score", 0.0) or 0.0) >= 1.0
                    and q["ticker"] not in (_bfq_already_held if '_bfq_already_held' in dir() else set())
                    # Sweep-2 fix: skip if a live sell signal is present so direct_reserved
                    # can't override sentiment-driven sells (the dequeue loop already checks
                    # this, but direct_reserved runs before the dequeue loop).
                    and q["ticker"] not in nexus_sell_enforcement
                    and (scores.get(q["ticker"]) or {}).get("score") != -1
                    and q["ticker"] not in _bfq_mw_sized
                    and q["ticker"] not in nexus_position_sizes
                ]
                _bfq_direct_candidates.sort(
                    key=lambda q: (-float(q.get("raw_net_score", 0.0) or 0.0),
                                   str(q.get("ticker") or "")))
                if _bfq_direct_candidates:
                    _bfq_direct_best = _bfq_direct_candidates[0]
                    _bfq_direct_sym = _bfq_direct_best["ticker"]
                    _bfq_direct_score = float(_bfq_direct_best.get("raw_net_score", 0.0) or 0.0)
                    # Fund from stock_budget_after_adds (the main budget, not residual queue budget)
                    # Run-185254 leak #3: sized at drain time from the CURRENT
                    # budget; the old min_pos*2 cap produced $200 crumbs.
                    _bfq_direct_alloc = _direct_reserve_alloc(config, _bfq_min_pos, _stock_budget_after_adds)
                    # With the $200 crumb cap gone, respect single_position_max_pct
                    # here like every other buy path (bug-sweep finding).
                    _bfq_direct_alloc = _clip_to_single_position_cap(
                        sym=_bfq_direct_sym,
                        intended_value=_bfq_direct_alloc,
                        current_position_value=0.0,
                        portfolio_total=portfolio_total,
                        config=config,
                    )
                    _bfq_direct_min_slot = _slot_min_notional(config, portfolio_total)
                    if _bfq_direct_min_slot > 0 and _bfq_direct_alloc < _bfq_direct_min_slot:
                        _log(
                            f"SLOT MIN-NOTIONAL: skip direct-reserved {_bfq_direct_sym} "
                            f"${_bfq_direct_alloc:.0f} < ${_bfq_direct_min_slot:.0f} floor",
                            "yellow",
                        )
                    elif _bfq_direct_alloc >= _bfq_min_pos and _stock_budget_after_adds >= _bfq_direct_alloc:
                        _bfq_direct_price = _resolve_symbol_price(
                            _bfq_direct_sym, prices, data, portfolio_emulator=portfolio_emulator,
                            fallback_price=float(_bfq_direct_best.get("price_at_signal", 0.0) or 0.0),
                        )
                        if _bfq_direct_price > 0:
                            nexus_position_sizes[_bfq_direct_sym] = {
                                "buy_cash": round(_bfq_direct_alloc, 2),
                                "high_conviction": True,
                                "asset_class": "stock",
                                "raw_net_score": round(_bfq_direct_score, 4),
                                "signal_source": "direct_reserved",
                                "is_propagation_expansion": False,
                                "is_watchlist_member": False,
                                "is_watchlist_priority": False,
                                "grace_eligible": True,
                                "backfill_direct_reserved": True,
                            }
                            if _bfq_direct_sym in scores and isinstance(scores.get(_bfq_direct_sym), dict):
                                scores[_bfq_direct_sym]["score"] = 1
                                scores[_bfq_direct_sym]["action_intent"] = "direct_reserved_buy"
                            else:
                                scores[_bfq_direct_sym] = {"score": 1, "action_intent": "direct_reserved_buy", "raw_net_score": _bfq_direct_score}
                            _bfq_processed.append(_bfq_direct_sym)
                            _stock_budget_after_adds -= _bfq_direct_alloc
                            _bfq_headroom -= 1
                            _log(
                                f"Backfill direct reserved: {_bfq_direct_sym} (score={_bfq_direct_score:.3f}, "
                                f"alloc=${_bfq_direct_alloc:.0f} from stock budget, queued {_bfq_direct_best.get('bars_in_queue', 0)} bars)",
                                "green",
                            )

            # V9 5D: Score-gated execution — high-conviction entries (raw_net_score > 1.5)
            # get the first 50% of backfill budget as priority allocation
            _bfq_priority_budget = _bfq_cash * 0.50
            _bfq_standard_budget = _bfq_cash - _bfq_priority_budget

            # V28 Fix 4: log BFQ drain entry conditions so we can see upfront
            # whether the drain even has a chance (cash + headroom).
            _bfq_top10_summary = ", ".join(
                f"{q.get('ticker','?')}(score={q.get('raw_net_score',0):.3f},age={q.get('bars_in_queue',0)}d)"
                for q in (_bfq[:10] or [])
            )
            _log(
                f"V28 BFQ DRAIN ENTRY: queue_size={len(_bfq)} headroom={_bfq_headroom} "
                f"cash=${_bfq_cash:.0f} priority_budget=${_bfq_priority_budget:.0f} "
                f"standard_budget=${_bfq_standard_budget:.0f} min_pos=${_bfq_min_pos:.0f} "
                f"top10=[{_bfq_top10_summary}]",
                "cyan",
            )

            for _bfq_item in list(_bfq):
                if _drawdown_halt_active and _bfq_halt_budget_pct <= 0:
                    break
                # V28.8.1 (Codex-corrected): BFQ dequeue IS a new-ticker path. Per
                # Codex 2B review, new-ticker paths must be blocked during breach.
                # Items age normally but don't fund. Only BFQ rotation (1-for-1 swap)
                # and full-exit main rotation are allowed during breach.
                _bfq_sym = _bfq_item["ticker"]
                _bfq_item["bars_in_queue"] = _bfq_item.get("bars_in_queue", 0) + 1
                if _bfq_breach_block:
                    if _bfq_item["bars_in_queue"] > (_bfq_priority_max_bars if (
                        bool(_bfq_item.get("is_watchlist_priority"))
                        or bool(_bfq_item.get("is_propagation_expansion"))
                        or float(_bfq_item.get("raw_net_score", 0.0) or 0.0) >= 1.0
                    ) else _bfq_max_bars):
                        _bfq_removed.append(_bfq_sym)
                        _log(f"Backfill queue EXPIRED (breach mode): {_bfq_sym}", "yellow")
                    continue

                # Expiry check
                _bfq_is_priority_entry = (
                    bool(_bfq_item.get("is_watchlist_priority"))
                    or bool(_bfq_item.get("is_propagation_expansion"))
                    or str(_bfq_item.get("signal_source") or "").strip().lower() in {"watchlist_priority", "propagation_expansion"}
                    # V20b fix: High-conviction items (score >= 1.0) get priority grace
                    # regardless of source. SNDK at score=1.843 was "direct" source and
                    # only got 10 bars grace (expired before rotation could process it).
                    or float(_bfq_item.get("raw_net_score", 0.0) or 0.0) >= 1.0
                )
                _bfq_entry_max_bars = _bfq_priority_max_bars if _bfq_is_priority_entry else _bfq_max_bars
                if _bfq_item["bars_in_queue"] > _bfq_entry_max_bars:
                    _bfq_removed.append(_bfq_sym)
                    _log(f"Backfill queue EXPIRED: {_bfq_sym} after {_bfq_item['bars_in_queue']} bars", "yellow")
                    continue

                # Skip if already held
                if _bfq_sym in _bfq_already_held:
                    _bfq_removed.append(_bfq_sym)
                    continue

                # Skip if already bought this bar
                if _bfq_sym in _bfq_bought_this_bar:
                    _bfq_removed.append(_bfq_sym)
                    continue

                # V31.1 Codex-fix: skip tickers already sized by momentum paths
                _bfq_mw_sized_dq = (strategy_cache or {}).get("_mw_sized_this_bar", set()) or set()
                if _bfq_sym in _bfq_mw_sized_dq or _bfq_sym in nexus_position_sizes:
                    _bfq_removed.append(_bfq_sym)
                    continue

                if _bfq_sym in nexus_sell_enforcement or (scores.get(_bfq_sym) or {}).get("score") == -1:
                    _bfq_removed.append(_bfq_sym)
                    _log(f"Backfill queue SOLD_OUT: {_bfq_sym} removed due to explicit sell signal", "yellow")
                    continue

                # V7.3: Skip if ticker is on fast-loser blacklist
                _fl_blacklist_deq = (strategy_cache or {}).get("_fast_loser_blacklist", {})
                if _bfq_sym in _fl_blacklist_deq:
                    _bfq_removed.append(_bfq_sym)
                    _log(f"Backfill queue BLACKLISTED: {_bfq_sym} blocked by fast-loser blacklist", "yellow")
                    continue

                # Get current price and score
                _bfq_cp = _resolve_symbol_price(
                    _bfq_sym,
                    prices,
                    data,
                    portfolio_emulator=portfolio_emulator,
                    fallback_price=float(_bfq_item.get("price_at_signal", 0.0) or 0.0),
                )
                _bfq_current_score = float((scores.get(_bfq_sym) or {}).get("raw_net_score", 0.0) or 0.0)

                if _bfq_cp <= 0:
                    continue  # No price available, try next bar
                if _bfq_item.get("needs_price_backfill"):
                    _bfq_item["price_at_signal"] = round(_bfq_cp, 2)
                    _bfq_item["needs_price_backfill"] = False

                # Price staleness check
                _bfq_orig_price = _safe_float(_bfq_item.get("price_at_signal"), 0.0)
                if _bfq_orig_price > 0:
                    _bfq_price_change = ((_bfq_cp - _bfq_orig_price) / _bfq_orig_price) * 100.0
                    if _bfq_price_change > _bfq_staleness_pct:
                        _bfq_removed.append(_bfq_sym)
                        _log(f"Backfill queue STALE: {_bfq_sym} price moved +{_bfq_price_change:.1f}% since signal", "yellow")
                        continue

                # Current score check — must still be positive
                _bfq_reject, _bfq_required_score, _bfq_score_gate = _should_reject_backfill_candidate(
                    _bfq_item,
                    _bfq_current_score,
                    float(config.get("buy_threshold", 0.15)),
                    config,
                )
                if _bfq_reject:
                    _bfq_removed.append(_bfq_sym)
                    _log(
                        f"Backfill queue REJECTED: {_bfq_sym} current score {_bfq_current_score:.3f} "
                        f"below {_bfq_required_score:.3f} ({_bfq_score_gate})",
                        "yellow",
                    )
                    continue

                _bfq_alloc, _bfq_budget_key = _plan_backfill_buy_allocation(
                    _bfq_item,
                    _bfq_current_score,
                    _bfq_priority_budget,
                    _bfq_standard_budget,
                    _bfq_min_pos,
                    _bfq_headroom,
                    config,
                )
                # V28 Fix 4: explicit log when allocation returns 0 — previously
                # this was silent and we couldn't tell whether headroom, cash, or
                # min_position_size was the blocker.
                if _bfq_alloc <= 0.0:
                    _log(
                        f"V28 BFQ ALLOC=0: {_bfq_sym} (queued {_bfq_item.get('bars_in_queue',0)}d, "
                        f"score={_bfq_current_score:.3f}, signal_score={_bfq_item.get('raw_net_score',0):.3f}) "
                        f"| priority_budget=${_bfq_priority_budget:.0f} standard_budget=${_bfq_standard_budget:.0f} "
                        f"min_pos=${_bfq_min_pos:.0f} headroom={_bfq_headroom} budget_key={_bfq_budget_key}",
                        "yellow",
                    )
                # Run-185254 leak #3: don't let a crumb consume a full
                # max_positions slot — leave the item queued for a bar when
                # the budget can fund more (slot_min_notional_pct lever,
                # default off; new positions only, ETF sleeve unaffected).
                _bfq_min_slot = _slot_min_notional(config, portfolio_total)
                if _bfq_alloc > 0.0 and _bfq_min_slot > 0 and _bfq_alloc < _bfq_min_slot:
                    _log(
                        f"SLOT MIN-NOTIONAL: skip queue buy {_bfq_sym} "
                        f"${_bfq_alloc:.0f} < ${_bfq_min_slot:.0f} floor — left queued",
                        "yellow",
                    )
                    continue
                if _bfq_alloc > 0.0:
                    # CAN BUY from queue!
                    _bfq_meta = _build_nexus_candidate_meta(
                        _bfq_sym,
                        scores.get(_bfq_sym),
                        config,
                        strategy_cache=strategy_cache,
                        signal_source=str(_bfq_item.get("signal_source") or "").strip().lower() or None,
                        is_propagation_expansion=bool(_bfq_item.get("is_propagation_expansion")),
                        is_watchlist_member=bool(_bfq_item.get("is_watchlist_member")),
                        is_watchlist_priority=bool(_bfq_item.get("is_watchlist_priority")),
                        grace_eligible=bool(_bfq_item.get("grace_eligible")),
                    )
                    nexus_position_sizes[_bfq_sym] = {
                        "buy_cash": round(_bfq_alloc, 2),
                        "high_conviction": _bfq_current_score >= 0.50,
                        "asset_class": "stock",
                        "raw_net_score": round(_bfq_current_score, 4),
                        "signal_source": _bfq_meta["signal_source"],
                        "is_watchlist_member": bool(_bfq_meta["is_watchlist_member"]),
                        "is_watchlist_priority": bool(_bfq_meta["is_watchlist_priority"]),
                        "is_propagation_expansion": bool(_bfq_meta["is_propagation_expansion"]),
                        "grace_eligible": bool(_bfq_meta["grace_eligible"]),
                    }
                    # ADDED BY CODEX (Fix 1C): promote scores so the broker executes queued
                    # buys whose live-bar score has decayed below buy_threshold but were
                    # explicitly admitted via grace/queued conviction.
                    if _bfq_sym in scores and isinstance(scores.get(_bfq_sym), dict):
                        scores[_bfq_sym]["score"] = 1
                        scores[_bfq_sym]["action_intent"] = "backfill_queue_buy"
                    else:
                        scores[_bfq_sym] = {"score": 1, "action_intent": "backfill_queue_buy"}
                    _bfq_processed.append(_bfq_sym)
                    # Deduct from appropriate budget pool
                    if _bfq_budget_key == "priority":
                        _bfq_priority_budget = max(0.0, _bfq_priority_budget - _bfq_alloc)
                    else:
                        _bfq_standard_budget = max(0.0, _bfq_standard_budget - _bfq_alloc)
                    _bfq_cash = max(0.0, _bfq_cash - _bfq_alloc)
                    _bfq_headroom -= 1
                    _log(
                        f"Backfill queue BUY: {_bfq_sym} (queued {_bfq_item['bars_in_queue']} bars, alloc=${_bfq_alloc:.0f}, "
                        f"score={_bfq_current_score:.3f}{' HIGH-CONV' if _bfq_budget_key == 'priority' else ''})",
                        "green",
                    )

            # ── V20: Backfill queue rotation — sell weakest held to fund high-conviction queue items ──
            # When the queue has unfilled high-conviction items and portfolio is full,
            # rotate out the weakest held position to free cash for the queued candidate.
            # Uses the existing _rotation_candidate_allowed function for safety.
            _bfq_rotation_count = 0
            _bfq_rotation_max = int(config.get("backfill_rotation_max_per_day", 1))
            _bfq_rotation_enabled = bool(config.get("backfill_rotation_enabled", True))
            _bfq_rotation_min_score = float(config.get("backfill_rotation_min_queue_score", 1.0))
            _bfq_rotation_min_hold = int(config.get("backfill_rotation_min_hold_days", 10))
            _bfq_rotation_max_pnl = float(config.get("backfill_rotation_max_held_pnl_pct", 3.0))
            # Codex fix: disable backfill rotation during risk-off modes
            # V28.7: ALSO trigger BFQ rotation when headroom is starved (not just cash).
            # The backtest showed 1,071 alloc=0 events where headroom=0 kept the queue
            # permanently starved. Converting this to weakest-held consolidation-rotation
            # is Codex's "one highest-leverage change".
            # V28.8: breach-suppression REMOVED. BFQ rotation is a net-zero swap
            # (sell weakest, buy high-conviction queued), so it must fire regardless
            # of max_positions breach. Previously V28.7 self-blocked this path,
            # causing SNDK/MU/LITE to rot in queue with headroom=0 for the entire
            # backtest. Restoring the rotation is the V28.8 recovery path.
            _bfq_headroom_trigger_enabled = bool(config.get("bfq_rotation_on_zero_headroom", True))
            _bfq_is_cash_starved = _bfq_cash < _bfq_min_pos
            _bfq_is_headroom_starved = _bfq_headroom_trigger_enabled and _bfq_headroom <= 0
            if (_bfq_rotation_enabled and (_bfq_is_cash_starved or _bfq_is_headroom_starved)
                    and portfolio_emulator is not None
                    and not _drawdown_halt_active and not _downtrend_active):
                # Find unfilled high-conviction queue items
                # V28.7: apply _evict_cooldown filter to BFQ candidates so a ticker we
                # just rotated-out cannot be immediately re-bought via the BFQ path.
                # Closes the churn loop Codex flagged as HIGH risk on the fix plan review.
                _bfq_unfilled = [
                    q for q in _bfq
                    if q["ticker"] not in set(_bfq_processed + _bfq_removed)
                    and q["ticker"] not in (_evict_cooldown or {})
                    and float(q.get("raw_net_score", 0.0) or 0.0) >= _bfq_rotation_min_score
                ]
                # Sort by score descending. Age boost removed — it doesn't help when items
                # enter the queue on the same bar (all get equal boost, relative order unchanged).
                # The real fix is equalizing priority rank for high-conviction direct items.
                _bfq_unfilled.sort(
                    key=lambda q: (-float(q.get("raw_net_score", 0.0) or 0.0),
                                   str(q.get("ticker") or "")))
                if _bfq_unfilled and _bfq_rotation_count < _bfq_rotation_max:
                    # Find weakest held positions eligible for rotation
                    _held_positions = []
                    # V28.6: parallel pool of winner-locked holds that may be
                    # bypass-eligible (feature-flagged). Drained only after the
                    # regular _held_positions pool is exhausted.
                    _held_positions_locked_bypass: list[dict] = []
                    _positions_map = getattr(portfolio_emulator, "_positions", {}) or {}
                    _already_sold_for_rotation: set[str] = set()
                    for _hp_sym, _hp_qty in _positions_map.items():
                        if float(_hp_qty or 0) <= 0:
                            continue
                        # Exclude momentum-protected positions from BFQ sell candidates
                        if _hp_sym in _mw_protected:
                            continue
                        _hp_snap = _build_position_health_snapshot(
                            _hp_sym, portfolio_emulator=portfolio_emulator,
                            prices=prices, price_history=data,
                            strategy_cache=strategy_cache, date_key=date_key,
                        )
                        _hp_pnl = float(_hp_snap.get("unrealized_pct", 0.0))
                        _hp_held = int(_hp_snap.get("held_days") or 0)
                        # Task 12: positive-graph rotation gate also protects the
                        # backfill-rotation outgoing picker — a held position the
                        # graph still rates positive is never a BFQ sell candidate.
                        _hp_raw = float((scores.get(_hp_sym) or {}).get("raw_net_score", 0.0) or 0.0)
                        if _graph_gate_holds(config, _hp_raw, _hp_pnl):
                            _log(
                                f"ROTATION_GRAPH_GATE: kept {_hp_sym} "
                                f"(raw={_hp_raw:+.2f} pnl={_hp_pnl:+.1f}%) [bfq]",
                                "cyan",
                            )
                            continue
                        _hp_locked, _ = _rotation_winner_lock_active(
                            held_pnl_pct=_hp_pnl, held_days=_hp_held,
                            held_raw_score=float((scores.get(_hp_sym) or {}).get("raw_net_score", 0.0) or 0.0),
                            drop_from_peak_pct=_hp_snap.get("drop_from_peak_pct"),
                            is_equity=True, config=config,
                        )
                        if _hp_locked:
                            # V28.6: stash winner-locked holds for possible bypass
                            # by aged high-conviction queue items. Feature-flag is
                            # re-checked per-candidate inside the pairing loop.
                            if config.get("backfill_rotation_winner_lock_bypass_enabled", True):
                                _held_positions_locked_bypass.append(
                                    {"sym": _hp_sym, "pnl": _hp_pnl, "held": _hp_held, "snap": _hp_snap}
                                )
                            continue
                        if _hp_held < _bfq_rotation_min_hold:
                            continue
                        if _hp_pnl > _bfq_rotation_max_pnl:
                            continue
                        _held_positions.append({"sym": _hp_sym, "pnl": _hp_pnl, "held": _hp_held, "snap": _hp_snap})
                    _held_positions.sort(key=lambda x: x["pnl"])  # weakest first
                    # V28.6: sort bypass pool by PnL ascending too — weakest
                    # armored winner goes first, protecting the top winners.
                    _held_positions_locked_bypass.sort(key=lambda x: x["pnl"])
                    # V20b fix: Loop over multiple queue items (was single-item only)
                    _hp_idx = 0
                    _hp_locked_idx = 0
                    # Perf: hoist momentum watchlist keys out of the per-candidate loop
                    # (watchlist is not mutated inside this loop — written only in phase 5).
                    _mw_keys_for_bfq: set[str] = set()
                    _bfq_mw_size_floor_pct = float(config.get("momentum_position_size_floor_pct", 0.10) or 0.10)
                    if config.get("momentum_watchlist_enabled", False) and isinstance(strategy_cache, dict):
                        _mw_keys_for_bfq = set((strategy_cache.get("_momentum_watchlist") or {}).keys())
                    # 2026-07-19 regime-safety Phase 3: lane regime gate —
                    # backfill rotation is a swap lane too and must not add
                    # names over the cap in chop or at all in bear/crash.
                    _bfq_lane_ok, _bfq_lane_why = _rotation_lane_allowed(
                        strategy_cache, portfolio_emulator, config)
                    if not _bfq_lane_ok and _bfq_unfilled:
                        _log(f"ROTATION lane blocked ({_bfq_lane_why}): "
                             f"backfill rotation disabled this bar "
                             f"({len(_bfq_unfilled)} candidate(s) dropped)", "yellow")
                        _bfq_unfilled = []
                    for _bfq_candidate in _bfq_unfilled:
                        if _bfq_rotation_count >= _bfq_rotation_max:
                            break
                        _best_queued = _bfq_candidate
                        # Find next available held position not already sold
                        _worst_held = None
                        _worst_held_is_bypass = False
                        while _hp_idx < len(_held_positions):
                            if _held_positions[_hp_idx]["sym"] not in _already_sold_for_rotation:
                                _worst_held = _held_positions[_hp_idx]
                                _hp_idx += 1
                                break
                            _hp_idx += 1
                        # V28.6: fall back to winner-lock bypass pool if regular pool exhausted
                        if _worst_held is None:
                            _bfq_q_score_probe = float(_best_queued.get("raw_net_score", 0.0) or 0.0)
                            _bfq_bars_probe = int(_best_queued.get("bars_in_queue", 0) or 0)
                            while _hp_locked_idx < len(_held_positions_locked_bypass):
                                _lh = _held_positions_locked_bypass[_hp_locked_idx]
                                _hp_locked_idx += 1
                                if _lh["sym"] in _already_sold_for_rotation:
                                    continue
                                _lh_held_score = float(
                                    (scores.get(_lh["sym"]) or {}).get("raw_net_score", 0.0) or 0.0
                                )
                                _lh_delta = _bfq_q_score_probe - _lh_held_score
                                if _bfq_winner_lock_bypass_allowed(
                                    queue_bars=_bfq_bars_probe,
                                    queue_score=_bfq_q_score_probe,
                                    delta=_lh_delta,
                                    held_pnl_pct=float(_lh["pnl"]),
                                    held_days=int(_lh["held"]),
                                    config=config,
                                ):
                                    _worst_held = _lh
                                    _worst_held_is_bypass = True
                                    break
                        if not _worst_held:
                            break
                        _bfq_q_score = float(_best_queued.get("raw_net_score", 0.0) or 0.0)
                        _bfq_h_score = float((scores.get(_worst_held["sym"]) or {}).get("raw_net_score", 0.0) or 0.0)
                        _bfq_delta = _bfq_q_score - _bfq_h_score
                        _bfq_min_delta = float(config.get("backfill_rotation_min_delta", 0.50))
                        if _bfq_delta >= _bfq_min_delta:
                            # Atomic sell/buy: add sell to enforcement AND buy to position_sizes on SAME bar
                            _bfq_sell_sym = _worst_held["sym"]
                            _bfq_buy_sym = _best_queued["ticker"]
                            # Defensive guard: never sell and re-buy the same ticker
                            if _bfq_buy_sym != _bfq_sell_sym:
                                # HM bug fix: Pre-check freed cash BEFORE committing sell.
                                # Previously sell was committed unconditionally, then buy
                                # could fail if freed cash < min_position_size.
                                _bfq_sell_price = _resolve_symbol_price(_bfq_sell_sym, prices, data, portfolio_emulator=portfolio_emulator)
                                _bfq_sell_qty = float(_positions_map.get(_bfq_sell_sym, 0))
                                _bfq_freed = max(0.0, _bfq_sell_price * _bfq_sell_qty) if _bfq_sell_price > 0 else 0.0
                                # V31.2 Fix 5: BFQ rotation floor enforcement via
                                # free-cash top-up (same pattern as momentum_watchlist_rotation).
                                # Uses the shared _mw_free_cash_spent_this_bar tracker
                                # so Fix 5 Site A + Site B + Fix B all draw from the
                                # same available pool without double-spend.
                                _bfq_size_floor = 0.0
                                if _bfq_buy_sym in _mw_keys_for_bfq and portfolio_total > 0:
                                    _bfq_size_floor = portfolio_total * _bfq_mw_size_floor_pct
                                _bfq_free_cash_now = 0.0
                                if hasattr(portfolio_emulator, "get_cash"):
                                    try:
                                        _bfq_free_cash_now = float(portfolio_emulator.get_cash() or 0.0)
                                    except Exception as _bfq_fc_exc:
                                        _bfq_free_cash_now = 0.0
                                        _log(f"V31.2 WARN: get_cash() failed in BFQ rotation: {_bfq_fc_exc}", "yellow")
                                _bfq_fc_spent_sofar = float((strategy_cache or {}).get("_mw_free_cash_spent_this_bar", 0.0) or 0.0)
                                _bfq_free_cash_avail = max(0.0, _bfq_free_cash_now - _bfq_fc_spent_sofar)
                                _bfq_extra_needed = max(0.0, _bfq_size_floor - _bfq_freed)
                                _bfq_extra = min(_bfq_extra_needed, _bfq_free_cash_avail * 0.95)
                                _bfq_buy_alloc = max(_bfq_min_pos, _bfq_freed + _bfq_extra)
                                # V32 Phase 3 B-6: diagnostic for cash-gate
                                # settlement race (PBF-class). When the planned
                                # BUY requires the in-bar SELL to settle to
                                # produce enough cash AND free cash alone is
                                # insufficient, log a warning so we can
                                # quantify how often the broker rejects with
                                # "SKIP BUY ... cash_to_use < min". This is
                                # non-blocking: the rotation still proceeds.
                                try:
                                    _b6_free_cash_post = max(0.0, _bfq_free_cash_now - _bfq_extra)
                                    _b6_needs_sell = (_bfq_buy_alloc - _b6_free_cash_post) > 0.0
                                    if _b6_needs_sell and _bfq_freed < _bfq_buy_alloc * 0.5:
                                        _log(
                                            f"V32 P3 B-6 cash-gate-risk: BFQ rotation buy {_bfq_buy_sym} "
                                            f"alloc=${_bfq_buy_alloc:.0f} freed=${_bfq_freed:.0f} "
                                            f"free_cash=${_bfq_free_cash_now:.0f} — broker may SKIP if "
                                            f"{_bfq_sell_sym} sell unsettled",
                                            "yellow",
                                        )
                                except Exception:
                                    pass
                                if isinstance(strategy_cache, dict):
                                    strategy_cache["_mw_free_cash_spent_this_bar"] = _bfq_fc_spent_sofar + _bfq_extra
                                if _bfq_buy_alloc >= _bfq_min_pos:
                                    # Only NOW commit the sell (buy is fundable)
                                    nexus_sell_enforcement.add(_bfq_sell_sym)
                                    _already_sold_for_rotation.add(_bfq_sell_sym)
                                    sentiment_data[_bfq_sell_sym] = {"sentiment": -1, "event": "general"}
                                    nexus_position_sizes[_bfq_buy_sym] = {
                                        "buy_cash": round(_bfq_buy_alloc, 2),
                                        "high_conviction": True,
                                        "asset_class": "stock",
                                        "raw_net_score": round(_bfq_q_score, 4),
                                        "signal_source": str(_best_queued.get("signal_source") or "backfill_rotation"),
                                        "is_propagation_expansion": bool(_best_queued.get("is_propagation_expansion")),
                                        "is_watchlist_member": False,
                                        "is_watchlist_priority": False,
                                        "grace_eligible": False,
                                        "backfill_rotation": True,
                                    }
                                    _bfq_processed.append(_bfq_buy_sym)
                                    _bfq_rotation_count += 1
                                    # V20b fix: Set score=1 so broker executes the buy (was score=0 → hold)
                                    if _bfq_buy_sym in scores and isinstance(scores.get(_bfq_buy_sym), dict):
                                        scores[_bfq_buy_sym]["score"] = 1
                                        scores[_bfq_buy_sym]["action_intent"] = "backfill_rotation_buy"
                                    else:
                                        scores[_bfq_buy_sym] = {"score": 1, "action_intent": "backfill_rotation_buy", "raw_net_score": _bfq_q_score}
                                    _bfq_rot_tag = " [V28.6 bypass]" if _worst_held_is_bypass else ""
                                    _log(
                                        f"Backfill rotation{_bfq_rot_tag}: selling {_bfq_sell_sym} (P&L={_worst_held['pnl']:+.1f}%, held={_worst_held['held']}d) "
                                        f"to fund {_bfq_buy_sym} (score={_bfq_q_score:.3f}, delta={_bfq_delta:.2f}, alloc=${_bfq_buy_alloc:.0f})",
                                        "green",
                                    )

            # Remove processed and expired items from queue
            _bfq = [q for q in _bfq if q["ticker"] not in set(_bfq_processed + _bfq_removed)]
            if strategy_cache is not None:
                strategy_cache["_backfill_queue"] = _bfq

            if _bfq:
                _log(f"Backfill queue: {len(_bfq)} pending ({', '.join(q['ticker'] for q in _bfq[:5])}{'...' if len(_bfq) > 5 else ''})", "cyan")

        _current_backfill_queue = list(_bfq if _bfq_enabled else _bfq_pending)
        _queued_symbols = {
            str((_entry or {}).get("ticker") or "").strip().upper()
            for _entry in _current_backfill_queue
            if str((_entry or {}).get("ticker") or "").strip()
        }
        _queued_priority_symbols = sorted(
            str((_entry or {}).get("ticker") or "").strip().upper()
            for _entry in _current_backfill_queue
            if bool((_entry or {}).get("grace_eligible")) or bool((_entry or {}).get("is_watchlist_priority")) or bool((_entry or {}).get("is_propagation_expansion"))
        )

        # ── V31.2 Fix 1 (final-pass): Cap each NEW-entry buy_cash at a
        # percentage of portfolio. Runs AFTER all allocation paths have
        # written to nexus_position_sizes, so catches every source:
        # _funded_stock_slate, momentum_watchlist_rotation (Fix 5),
        # momentum_watchlist_portfolio_swap (Fix A), momentum_breakout_add
        # (Fix B), backfill_queue_buy, backfill_rotation_buy (Fix 5),
        # direct_reserved. Does NOT cap additions to existing positions
        # (winner_add / anchor_reinforce add to current holders).
        # ────────────────────────────────────────────────────────────────
        # V31.2 2nd-sweep fix: initialize _held_for_cap UNCONDITIONALLY so
        # the total-spend cap always has a valid held-set filter, even when
        # the per-entry cap is disabled (config <= 0 or >= 1.0).
        _held_for_cap: set[str] = set()
        if portfolio_emulator is not None:
            for _pc_sym, _pc_q in (getattr(portfolio_emulator, "_positions", {}) or {}).items():
                if float(_pc_q or 0) > 0:
                    _held_for_cap.add(str(_pc_sym).strip().upper())
        _min_pos_final = float(config.get("min_position_size", 100.0) or 100.0)
        _rot_incr_cap_pct = float(config.get("rotation_incremental_cap_pct", 0.15) or 0.15)
        if _rot_incr_cap_pct > 0 and _rot_incr_cap_pct < 1.0 and portfolio_total > 0:
            _rot_incr_cap = portfolio_total * _rot_incr_cap_pct
            _rot_capped_count = 0
            for _cap_sym, _cap_hint in list(nexus_position_sizes.items()):
                if str(_cap_sym).startswith("_") or not isinstance(_cap_hint, dict):
                    continue
                if str(_cap_sym).strip().upper() in _held_for_cap:
                    continue
                _orig = float(_cap_hint.get("buy_cash", 0.0) or 0.0)
                if _orig > _rot_incr_cap:
                    _cap_hint["buy_cash"] = round(_rot_incr_cap, 2)
                    _rot_capped_count += 1
                    _log(
                        f"V31.2 rotation cap: {_cap_sym} alloc "
                        f"${_orig:.0f} → ${_rot_incr_cap:.0f} "
                        f"({_rot_incr_cap_pct:.0%} of portfolio ${portfolio_total:.0f}) "
                        f"[src={str(_cap_hint.get('signal_source', ''))[:30]}]",
                        "yellow",
                    )
            if _rot_capped_count > 0:
                _log(
                    f"V31.2 rotation cap: capped {_rot_capped_count} new-entry buy(s) at "
                    f"${_rot_incr_cap:.0f}",
                    "cyan",
                )

        # ── V31.2 Fix 1 (safety net): Cap total new-entry buy_cash at the
        # nexus_portfolio_pct budget. Protects against cumulative over-
        # allocation when multiple paths write in the same bar.
        # ────────────────────────────────────────────────────────────────
        _tot_cap_pct = float(config.get("nexus_portfolio_pct", 0.95) or 0.95)
        # With an index core armed, this cap is measured against FULL NAV and so
        # stops binding by construction -- 0.95 of NAV is more than the whole
        # satellite sleeve, so the satellite is free to crowd the core out. That
        # is not theoretical: the first Layer-3 validation run pinned the SPY
        # core at exactly 30.0% (its clamp FLOOR, core_min_pct) for the entire
        # window, because core = clamp(1 - cash_floor - satellite, ...) makes the
        # core a RESIDUAL of the satellite and nothing bounded the satellite.
        # Bound it to what the design leaves over, so a 60% core target actually
        # produces a 60% core.
        if bool(config.get("core_sleeve_enabled", False)):
            _core_tgt = float(config.get("core_target_pct", 0.60) or 0.60)
            _cash_fl = float(config.get("cash_reserve_floor_pct", 0.02) or 0.02)
            _sat_room = max(0.05, 1.0 - _core_tgt - _cash_fl)
            if _sat_room < _tot_cap_pct:
                _tot_cap_pct = _sat_room
        if _tot_cap_pct > 0 and portfolio_total > 0:
            _tot_cap = portfolio_total * _tot_cap_pct
            _total_new_spend = sum(
                float(_h.get("buy_cash", 0.0) or 0.0)
                for _s, _h in nexus_position_sizes.items()
                if isinstance(_h, dict)
                and not str(_s).startswith("_")
                and str(_s).strip().upper() not in _held_for_cap
            )
            if _total_new_spend > _tot_cap:
                _scale = _tot_cap / _total_new_spend
                _scaled_count = 0
                _undersized_tickers: list[str] = []
                for _ts_sym, _ts_hint in nexus_position_sizes.items():
                    if (
                        isinstance(_ts_hint, dict)
                        and not str(_ts_sym).startswith("_")
                        and str(_ts_sym).strip().upper() not in _held_for_cap
                    ):
                        _ts_orig = float(_ts_hint.get("buy_cash", 0.0) or 0.0)
                        if _ts_orig > 0:
                            _ts_scaled = _ts_orig * _scale
                            # V31.2 2nd-sweep fix: enforce min_position_size
                            # post-scale. If scaling would drop below min_pos,
                            # mark for removal rather than creating undersized
                            # orders the broker would reject.
                            if _ts_scaled < _min_pos_final:
                                _undersized_tickers.append(str(_ts_sym))
                            else:
                                _ts_hint["buy_cash"] = round(_ts_scaled, 2)
                                _scaled_count += 1
                for _us_sym in _undersized_tickers:
                    nexus_position_sizes.pop(_us_sym, None)
                _log(
                    f"V31.2 total-spend cap: scaled {_scaled_count} buy(s) by "
                    f"{_scale:.3f} (new_spend ${_total_new_spend:.0f} → ${_tot_cap:.0f}); "
                    f"dropped {len(_undersized_tickers)} undersized",
                    "cyan",
                )

        # P3 SNDK-fix (2026-04-29): final-pass undersized guard. Drop any
        # NEW-entry buy_cash below min_position_size before the broker
        # emission slate is built. Defense-in-depth net for any path that
        # writes to nexus_position_sizes without enforcing the floor — e.g.
        # the same-bar queue ordering in BT 896230 where SNDK was sized at
        # $87 (the residual cash after a paired backfill_rotation_buy
        # consumed the bar's freed cash). Held positions are excluded so
        # anchor_reinforce / winner_add top-ups (which have their own per-
        # path floors) are not affected.
        if _min_pos_final > 0:
            _final_dropped: list[tuple[str, float]] = []
            for _fd_sym, _fd_hint in list(nexus_position_sizes.items()):
                if not isinstance(_fd_hint, dict) or str(_fd_sym).startswith("_"):
                    continue
                if str(_fd_sym).strip().upper() in _held_for_cap:
                    continue
                _fd_buy_cash = float(_fd_hint.get("buy_cash", 0.0) or 0.0)
                if 0.0 < _fd_buy_cash < _min_pos_final:
                    _final_dropped.append((str(_fd_sym), _fd_buy_cash))
                    nexus_position_sizes.pop(_fd_sym, None)
            if _final_dropped:
                _preview = ", ".join(
                    f"{_t}=${_v:.2f}" for _t, _v in _final_dropped[:5]
                )
                if len(_final_dropped) > 5:
                    _preview += f", ... (+{len(_final_dropped) - 5})"
                _log(
                    f"P3 undersized guard: dropped {len(_final_dropped)} sub-floor "
                    f"new-entry buy(s) (<${_min_pos_final:.0f}): {_preview}",
                    "yellow",
                )

        _nexus_executable_buys = sorted(
            sym
            for sym, hint in (nexus_position_sizes or {}).items()
            if not str(sym).startswith("_")
            and isinstance(hint, dict)
            and float(hint.get("buy_cash", 0.0) or 0.0) > 0.0
        )
        _nexus_executable_set = set(_nexus_executable_buys)
        _force_enqueued_priority: list[str] = []
        _force_queue = list(_current_backfill_queue)
        _force_held = {
            str(t).strip().upper()
            for t, q in ((portfolio_emulator._positions or {}).items() if portfolio_emulator is not None else [])
            if str(t).strip() and float(q or 0.0) > 0.0
        }
        _force_candidates = sorted(
            (
                str(_sym).strip().upper()
                for _sym, _payload in scores.items()
                if isinstance(_payload, dict)
                and not str(_sym).startswith("_")
                and int(_payload.get("score", 0) or 0) == 1
            ),
            key=lambda _sym: (
                0 if bool((scores.get(_sym) or {}).get("is_watchlist_priority")) else
                1 if bool((scores.get(_sym) or {}).get("is_watchlist_member")) else
                2 if bool((scores.get(_sym) or {}).get("is_propagation_expansion")) else
                3,
                -float((scores.get(_sym) or {}).get("raw_net_score", 0.0) or 0.0),
                -int((scores.get(_sym) or {}).get("n_paths", 0) or 0),
                _sym,
            ),
        )
        for _force_sym in _force_candidates:
            if _force_sym in _nexus_executable_set or _force_sym in _queued_symbols or _force_sym in _force_held:
                continue
            _force_payload = scores.get(_force_sym) or {}
            _force_meta = _build_nexus_candidate_meta(
                _force_sym,
                _force_payload,
                config,
                strategy_cache=strategy_cache,
                is_propagation_expansion=bool(_force_payload.get("is_propagation_expansion")) or _force_sym in set(_prop_expansion_buys or []),
                is_watchlist_member=bool(_force_payload.get("is_watchlist_member")) or _force_sym in _watchlist_member_tickers,
                is_watchlist_priority=bool(_force_payload.get("is_watchlist_priority")) or _force_sym in _watchlist_priority_tickers,
                signal_source=str(_force_payload.get("signal_source") or "").strip().lower() or None,
                grace_eligible=True if (
                    bool(_force_payload.get("is_watchlist_member"))
                    or bool(_force_payload.get("is_watchlist_priority"))
                    or bool(_force_payload.get("is_propagation_expansion"))
                ) else bool(_force_payload.get("grace_eligible")),
            )
            _requires_protected_queue = (
                bool(_force_meta["is_watchlist_member"])
                or bool(_force_meta["is_watchlist_priority"])
                or bool(_force_meta["is_propagation_expansion"])
            )
            if not _requires_protected_queue:
                continue
            _force_price = _resolve_symbol_price(
                _force_sym,
                prices,
                data,
                portfolio_emulator=portfolio_emulator,
            )
            _force_score = float(_force_payload.get("raw_net_score", 0.0) or 0.0)
            _force_status, _force_replaced = _enqueue_backfill_candidate(
                _force_queue,
                {
                    "ticker": _force_sym,
                    "first_signal_date": date_key,
                    "raw_net_score": round(_force_score, 4),
                    "n_paths": int(_force_payload.get("n_paths", 0) or 0),
                    "signal_source": _force_meta["signal_source"],
                    "is_watchlist_member": bool(_force_meta["is_watchlist_member"]),
                    "is_watchlist_priority": bool(_force_meta["is_watchlist_priority"]),
                    "is_propagation_expansion": bool(_force_meta["is_propagation_expansion"]),
                    "grace_eligible": True,
                    "price_at_signal": round(_force_price, 2) if _force_price > 0 else None,
                    "needs_price_backfill": _force_price <= 0,
                    "queued_price_source": "force_enqueue" if _force_price > 0 else "broker",
                    "queued_from_bar": date_key,
                    "bars_in_queue": 0,
                },
                _bfq_max_size,
                reserved_priority_slots=_bfq_reserved_priority_slots,
                min_displacement_delta=_bfq_min_displace_delta,
                recurrence_bonus=_bfq_recurrence_bonus,
            )
            if _force_status in {"added", "updated", "replaced", "priority_evicted_general", "duplicate"}:
                _force_enqueued_priority.append(_force_sym)
                if _force_status == "added":
                    _log(f"Backfill queue FORCE-ADD: {_force_sym} (source={_force_meta['signal_source']}, score={_force_score:.3f})", "magenta")
                elif _force_status == "priority_evicted_general":
                    _log(f"Backfill queue FORCE-PRIORITY_EVICT: {_force_sym} displaced {_force_replaced} (score={_force_score:.3f})", "magenta")
                elif _force_status == "replaced":
                    _log(f"Backfill queue FORCE-REPLACE: {_force_sym} displaced {_force_replaced} (score={_force_score:.3f})", "magenta")
            else:
                _queue_admission_failures[_force_sym] = _force_status
                _log(f"Backfill queue FORCE-BLOCKED: {_force_sym} ({_force_status}, score={_force_score:.3f})", "yellow")

        if _force_enqueued_priority:
            if strategy_cache is not None:
                strategy_cache["_backfill_queue"] = _force_queue
            _current_backfill_queue = list(_force_queue)
            _queued_symbols = {
                str((_entry or {}).get("ticker") or "").strip().upper()
                for _entry in _current_backfill_queue
                if str((_entry or {}).get("ticker") or "").strip()
            }
            _queued_priority_symbols = sorted(
                str((_entry or {}).get("ticker") or "").strip().upper()
                for _entry in _current_backfill_queue
                if bool((_entry or {}).get("grace_eligible")) or bool((_entry or {}).get("is_watchlist_priority")) or bool((_entry or {}).get("is_propagation_expansion"))
            )

        _priority_invariant_demoted = []
        _deferred_unfunded_demoted = []
        _queue_only_demoted = []
        for _sym, _payload in list(scores.items()):
            if not isinstance(_payload, dict) or str(_sym).startswith("_"):
                continue
            if int(_payload.get("score", 0) or 0) != 1:
                continue
            if str(_sym).strip().upper() in _nexus_executable_set:
                continue
            if str(_sym).strip().upper() in _queued_symbols:
                _payload["score"] = 0
                _payload["action_intent"] = "queued_backfill"
                _orig_reason = str(_payload.get("reason") or "")
                _payload["reason"] = f"NEXUS_QUEUE_ONLY: {_sym} queued for protected backfill | {_orig_reason}"[:1500]
                _queue_only_demoted.append(_sym)
                continue
            _sym_key = str(_sym).strip().upper()
            _candidate_meta = _build_nexus_candidate_meta(
                _sym_key,
                _payload,
                config,
                strategy_cache=strategy_cache,
                is_propagation_expansion=bool(_payload.get("is_propagation_expansion")),
                is_watchlist_member=bool(_payload.get("is_watchlist_member")) or _sym_key in _watchlist_member_tickers,
                is_watchlist_priority=bool(_payload.get("is_watchlist_priority")) or _sym_key in _watchlist_priority_tickers,
                signal_source=str(_payload.get("signal_source") or "").strip().lower() or None,
                grace_eligible=bool(_payload.get("grace_eligible")),
            )
            _queue_failure_reason = _queue_admission_failures.get(_sym_key)
            _payload["score"] = 0
            _payload["action_intent"] = "hold"
            _orig_reason = str(_payload.get("reason") or "")
            if _candidate_meta["is_watchlist_priority"] or _candidate_meta["is_propagation_expansion"]:
                _payload["action_intent"] = "blocked_priority_buy"
                _block_reason = _queue_failure_reason or "missing_queue_record"
                _payload["reason"] = (
                    f"NEXUS_PRIORITY_BLOCKED: {_sym} had priority buy signal but no executable size; "
                    f"queue_status={_block_reason} | {_orig_reason}"
                )[:1500]
                _log(
                    f"Nexus priority invariant: {_sym} ended without executable size or queue record "
                    f"(queue_status={_block_reason})",
                    "red",
                )
                _priority_invariant_demoted.append(_sym)
                _log(f"Nexus sizing assertion: {_sym} had buy score without executable size or queue record - demoted to hold", "yellow")
            else:
                _block_reason = _queue_failure_reason or (
                    "deferred_by_executable_slate"
                    if _sym_key in _deferred_stock_slate_candidates
                    else "unfunded_tail_buy"
                )
                _payload["action_intent"] = "deferred_unfunded_buy"
                _payload["reason"] = (
                    f"NEXUS_DEFERRED_BUY: {_sym} deferred after executable slate/queue filtering; "
                    f"queue_status={_block_reason} | {_orig_reason}"
                )[:1500]
                _deferred_unfunded_demoted.append(_sym)

        action_intents = {
            sym: (payload.get("action_intent") or "hold")
            for sym, payload in scores.items()
            if isinstance(payload, dict) and not sym.startswith("_")
        }

        if _nexus_executable_buys:
            _log(f"Executable buys: {', '.join(_nexus_executable_buys[:12])}", "green")
        else:
            _log("Executable buys: none", "cyan")
        if _queued_priority_symbols:
            _log(f"Queued priority buys: {', '.join(_queued_priority_symbols[:12])}", "magenta")
        if _queue_only_demoted:
            _log(f"Promoted buys demoted to queue-only hold: {', '.join(sorted(_queue_only_demoted)[:12])}", "magenta")
        if _deferred_unfunded_demoted:
            _log(
                f"Deferred unfunded buys demoted to hold: {', '.join(sorted(_deferred_unfunded_demoted)[:12])}"
                f"{'...' if len(_deferred_unfunded_demoted) > 12 else ''}",
                "yellow",
            )
        if _priority_invariant_demoted:
            _log(
                f"Priority buys missing executable size or queue record: {', '.join(sorted(_priority_invariant_demoted)[:12])}"
                f"{'...' if len(_priority_invariant_demoted) > 12 else ''}",
                "red",
            )

        if not isinstance(overlay_traces, dict):
            overlay_traces = {}
        if not isinstance(candidate_features, dict):
            candidate_features = {}
        if not isinstance(llm_traces_global, list):
            llm_traces_global = list(llm_traces_global or [])
        trace_map = {
            sym: list(overlay_traces.get(sym) or []) + list(llm_traces_global)
            for sym in action_intents
        }
        with _timed_stage("Trade context persistence", start_details=f"symbols={len(action_intents)} | active_events={len(active_events)}"):
            _save_trade_contexts_and_outcomes(
                conn,
                instance_id=instance_id,
                date_key=date_key,
                prices=prices,
                scores=scores,
                candidate_features=candidate_features,
                llm_traces=trace_map,
                active_events=active_events,
                config=config,
                portfolio_emulator=portfolio_emulator,
                point_in_time_context=point_in_time_context,
            )

        # Attach nexus metadata for broker to extract
        scores["_nexus_discovered"] = list(all_discovered) if all_discovered else []
        # Remove momentum-protected tickers from sell enforcement before
        # returning to broker — the broker independently overrides decisions
        # to -1 for anything in this set (line broker.py:3802).
        if _mw_protected and nexus_sell_enforcement:
            # Preserve forced exits (trailing stop, fast loser) and momentum
            # rotation sells — these must stay in enforcement even for
            # momentum-protected tickers.
            _mw_must_keep = set()
            for _sym, _sd in scores.items():
                if isinstance(_sd, dict) and _sd.get("_forced_exit"):
                    _mw_must_keep.add(str(_sym).strip().upper())
            # Also preserve momentum rotation sells (the system itself chose to sell)
            _mw_rot_sells = strategy_cache.get("_mw_rotation_sells_this_bar", set()) if isinstance(strategy_cache, dict) else set()
            _mw_must_keep |= _mw_rot_sells
            nexus_sell_enforcement -= (_mw_protected - _mw_must_keep)
        scores["_nexus_sell_enforcement"] = list(nexus_sell_enforcement) if nexus_sell_enforcement else []
        nexus_position_sizes["_cash_reserve_floor_pct"] = float(config.get("cash_reserve_floor_pct", 0.10))
        nexus_position_sizes["_cash_reserve_floor_hard"] = bool(config.get("cash_reserve_floor_hard", True))
        nexus_position_sizes["_cash_reserve_hard_min_positions"] = int(config.get("cash_reserve_hard_min_positions", 5))
        nexus_position_sizes["_cash_reserve_release_after_min_positions"] = bool(config.get("cash_reserve_release_after_min_positions", True))
        nexus_position_sizes["_buy_price_floor"] = float(config.get("buy_price_floor", 5.0) or 0.0)
        # 2026-07-22 peak-defense: let the broker force-include held momentum-
        # watchlist names carrying a retained profit-take partial trim into the
        # sell-execution set (else the trim is dropped and the winner round-trips
        # — bt701112 CAR +142% -> -18%). Default OFF; plumbed via this control key.
        nexus_position_sizes["_momentum_partial_trim_execution_enabled"] = bool(config.get("momentum_partial_trim_execution_enabled", False))
        scores["_nexus_position_sizes"] = nexus_position_sizes
        scores["_nexus_executable_buys"] = _nexus_executable_buys
        scores["_nexus_action_intents"] = action_intents
        scores["_nexus_active_events"] = [dict(ev) for ev in active_events[:20]]
        # Pass only final live propagation-expansion buys to broker, not names demoted to queue/hold.
        scores["_nexus_expansion_buys"] = [
            sym for sym in (_prop_expansion_buys or [])
            if int(((scores.get(sym) or {}).get("score", 0)) or 0) == 1
        ]

        # ── V27 (Approach D): Discovery Snapshot Bridge — write snapshot ──
        # Refresh the snapshot row for this base instance with the current
        # discovery set + per-bucket fingerprints. Idempotent (insert with
        # conflict=replace). One row per base; cheap.
        #
        # V27.1 fix: previously gated on historical_lookback_mode=True, but
        # when broker.py REUSES a prior lookback (resume_opens=[]), every bar
        # in the run executes with historical_lookback_mode=False, so the
        # writer never fired and the snapshot never got created. Now fires
        # for both lookback and live bars, but throttled to ONCE per run via
        # a strategy_cache flag so we only write once per backtest. This is
        # safe for live bars because the post-lookback cleanup at line ~13702
        # already deletes any post-lookback discoveries before the first live
        # bar runs, so on the first live bar the discovery set IS the
        # lookback's final state.
        _snap_write_flag = "_nexus_discovery_snapshot_written"
        if (
            bool(config.get("nexus_discovery_snapshot_enabled", True))
            and base_instance_id
            and instance_id
            and strategy_cache is not None
            and not strategy_cache.get(_snap_write_flag)
        ):
            _snap_conn = _get_nexus_db_conn()
            if _snap_conn is not None:
                try:
                    _snap_fps = _compute_discovery_fingerprints(config)
                    _snap_count = _save_discovery_snapshot(
                        _snap_conn,
                        base_instance_id=base_instance_id,
                        current_instance_id=instance_id,
                        snapshot_scope_id=history_scope_id,
                        fingerprints=_snap_fps,
                        lookback_end_date=date_key,
                    )
                    strategy_cache[_snap_write_flag] = True
                    if _snap_count:
                        _log(
                            f"Discovery snapshot SAVED: {_snap_count} ticker(s) "
                            f"for base={base_instance_id} (date={date_key}, "
                            f"mode={'lookback' if historical_lookback_mode else 'live'})",
                            "cyan",
                        )
                except Exception as _snap_exc:
                    _log(f"Discovery snapshot WARN: {type(_snap_exc).__name__}: {str(_snap_exc)[:200]}", "yellow")
                    strategy_cache[_snap_write_flag] = True  # don't retry forever on errors
                finally:
                    try:
                        _snap_conn.close()
                    except Exception:
                        pass

        _finalize_pit_capture_safely(
            enabled=_pit_capture_requested,
            config=config,
            as_of=point_in_time_context.as_of
            if point_in_time_context is not None
            else current_time,
            recording_driver=_shared_neo4j_driver,
            strategy_cache=strategy_cache,
            alpaca_articles=articles,
            google_articles=google_articles,
            benzinga_data=bz_data,
        )

        # ── Close shared Neo4j driver ──────────────────────────────────────
        if _shared_neo4j_driver is not None:
            try:
                _shared_neo4j_driver.close()
            except Exception as _drv_close_exc:
                _log(f"Neo4j WARN: failed to close shared driver at end of run: {_drv_close_exc}", "yellow")

        # ── Per-day timing summary ─────────────────────────────────────────
        _run_once_elapsed = perf_counter() - _run_once_started
        _final_signal_docs = [
            payload for sym, payload in scores.items()
            if isinstance(payload, dict) and not str(sym).startswith("_")
        ]
        _final_buys = sum(1 for payload in _final_signal_docs if int(payload.get("score", 0) or 0) == 1)
        _final_sells = sum(1 for payload in _final_signal_docs if int(payload.get("score", 0) or 0) == -1)
        _final_holds = max(0, len(_final_signal_docs) - _final_buys - _final_sells)
        _cache_stats = get_prompt_cache_stats()
        _cache_info = (
            f" | cache hits={_cache_stats['hits']} misses={_cache_stats['misses']}"
            if _cache_should_enable
            else ""
        )
        _log(
            f"Run once complete | date={date_key} | total={_format_stage_elapsed(_run_once_elapsed)} "
            f"| buys={_final_buys} sells={_final_sells} holds={_final_holds}{_cache_info}",
            "green",
        )

        # Dual-cadence cycle-completed marker. Written ONLY on success path,
        # ONLY when dual-cadence is active and we passed the open gate (i.e.
        # this tick actually ran the full pipeline). The marker is read at
        # the start of the next tick to decide MONITOR vs FULL.
        # 2026-05-07 scheduler refactor: also write the marker when broker
        # passes mode="FULL" (legacy `_dual_cadence_active` is False on that
        # path because it requires `mode is None`). Without this branch, the
        # marker would never be set under broker-driven scheduling and the
        # _nexus_sell_enforcement_last cache would stay empty all day.
        _marker_should_write = (
            (_dual_cadence_active and _past_open_today)
            or mode == "FULL"
        )
        if _marker_should_write and isinstance(strategy_cache, dict):
            # When broker drives (mode="FULL"), the legacy gate didn't run,
            # so _today_ny was never computed. Compute it now in PT (the
            # marker convention is PT-date so midnight rollover matches
            # operator timezone, mirroring the gate's behavior at 16219).
            if not _today_ny:
                try:
                    from datetime import timezone as _tz_m
                    from zoneinfo import ZoneInfo as _ZI_m
                    _now_for_marker = current_time
                    if not hasattr(_now_for_marker, "astimezone"):
                        _now_for_marker = datetime.now(_tz_m.utc)
                    if _now_for_marker.tzinfo is None:
                        _now_for_marker = _now_for_marker.replace(tzinfo=_tz_m.utc)
                    _today_ny = _now_for_marker.astimezone(
                        _ZI_m("America/Los_Angeles")
                    ).strftime("%Y-%m-%d")
                except Exception:
                    _today_ny = (
                        current_time.strftime("%Y-%m-%d")
                        if hasattr(current_time, "strftime")
                        else date_key
                    )
            strategy_cache["_nexus_full_cycle_completed_date"] = _today_ny
            # Snapshot the active sell-enforcement set so the monitor cycle
            # can pass it through to the broker (otherwise the broker's
            # sell-enforcement gate goes empty between full cycles).
            try:
                _se = scores.get("_nexus_sell_enforcement")
                if isinstance(_se, (list, set, tuple)):
                    strategy_cache["_nexus_sell_enforcement_last"] = list(_se)
            except Exception:
                pass

        return scores
